window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["DEU"]={"book":"DEU","editions":{"hbo-source":[[1,1,"אֵ֣לֶּה הַ⁠דְּבָרִ֗ים אֲשֶׁ֨ר דִּבֶּ֤ר מֹשֶׁה֙ אֶל־כָּל־יִשְׂרָאֵ֔ל בְּ⁠עֵ֖בֶר הַ⁠יַּרְדֵּ֑ן בַּ⁠מִּדְבָּ֡ר בָּֽ⁠עֲרָבָה֩ מ֨וֹל ס֜וּף בֵּֽין־פָּארָ֧ן וּ⁠בֵֽין־תֹּ֛פֶל וְ⁠לָבָ֥ן וַ⁠חֲצֵרֹ֖ת וְ⁠דִ֥י זָהָֽב׃","ʼé֣lėh ha⁠dĕ̇bári֗ym ʼàşě֨r di̇bė֤r mòşěh֙ ʼel-ká̇l-yişĕ̂ráʼé֔l bĕ̇⁠ʻé֖ber ha⁠yȧrĕdé֑̇n bȧ⁠mi̇dĕbá̇֡r báֽ̇⁠ʻàrábáh֩ m֨wòl s֜ẇp béֽ̇yn-pá̇ʼrá֧n ẇ⁠béֽyn-ţò֛̇pel wĕ⁠lábá֥n wa⁠ẖàẕérò֖ţ wĕ⁠di֥y záháֽb׃"],[1,2,"אַחַ֨ד עָשָׂ֥ר יוֹם֙ מֵֽ⁠חֹרֵ֔ב דֶּ֖רֶךְ הַר־שֵׂעִ֑יר עַ֖ד קָדֵ֥שׁ בַּרְנֵֽעַ׃","ʼaẖa֨d ʻáşá֥̂r ywòm֙ méֽ⁠ẖòré֔b dė֖rekĕ har-şé̂ʻi֑yr ʻa֖d qádé֥ş̌ bȧrĕnéֽʻa׃"],[1,3,"וַ⁠יְהִי֙ בְּ⁠אַרְבָּעִ֣ים שָׁנָ֔ה בְּ⁠עַשְׁתֵּֽי־עָשָׂ֥ר חֹ֖דֶשׁ בְּ⁠אֶחָ֣ד לַ⁠חֹ֑דֶשׁ דִּבֶּ֤ר מֹשֶׁה֙ אֶל־בְּנֵ֣י יִשְׂרָאֵ֔ל כְּ֠⁠כֹל אֲשֶׁ֨ר צִוָּ֧ה יְהוָ֛ה אֹת֖⁠וֹ אֲלֵ⁠הֶֽם׃","wa⁠yĕhiy֙ bĕ̇⁠ʼarĕbá̇ʻi֣ym şá̌ná֔h bĕ̇⁠ʻaşĕ̌ţéֽ̇y-ʻáşá֥̂r ẖò֖deş̌ bĕ̇⁠ʼeẖá֣d la⁠ẖò֑deş̌ di̇bė֤r mòşěh֙ ʼel-bĕ̇né֣y yişĕ̂ráʼé֔l kĕ̇֠⁠kòl ʼàşě֨r ẕiwá֧̇h yĕhwá֛h ʼòţ֖⁠wò ʼàlé⁠heֽm׃"],[1,4,"אַחֲרֵ֣י הַכֹּת֗⁠וֹ אֵ֚ת סִיחֹן֙ מֶ֣לֶךְ הָֽ⁠אֱמֹרִ֔י אֲשֶׁ֥ר יוֹשֵׁ֖ב בְּ⁠חֶשְׁבּ֑וֹן וְ⁠אֵ֗ת ע֚וֹג מֶ֣לֶךְ הַ⁠בָּשָׁ֔ן אֲשֶׁר־יוֹשֵׁ֥ב בְּ⁠עַשְׁתָּרֹ֖ת בְּ⁠אֶדְרֶֽעִי׃","ʼaẖàré֣y hakò̇ţ֗⁠wò ʼé֚ţ siyẖòn֙ me֣lekĕ háֽ⁠ʼèmòri֔y ʼàşě֥r ywòşé֖̌b bĕ̇⁠ẖeşĕ̌ḃ֑wòn wĕ⁠ʼé֗ţ ʻ֚wòg me֣lekĕ ha⁠bá̇şá̌֔n ʼàşěr-ywòşé֥̌b bĕ̇⁠ʻaşĕ̌ţá̇rò֖ţ bĕ̇⁠ʼedĕreֽʻiy׃"],[1,5,"בְּ⁠עֵ֥בֶר הַ⁠יַּרְדֵּ֖ן בְּ⁠אֶ֣רֶץ מוֹאָ֑ב הוֹאִ֣יל מֹשֶׁ֔ה בֵּאֵ֛ר אֶת־הַ⁠תּוֹרָ֥ה הַ⁠זֹּ֖את לֵ⁠אמֹֽר׃","bĕ̇⁠ʻé֥ber ha⁠yȧrĕdé֖̇n bĕ̇⁠ʼe֣reẕ mwòʼá֑b hwòʼi֣yl mòşě֔h bé̇ʼé֛r ʼeţ-ha⁠ţ̇wòrá֥h ha⁠zò֖̇ʼţ lé⁠ʼmòֽr׃"],[1,6,"יְהוָ֧ה אֱלֹהֵ֛י⁠נוּ דִּבֶּ֥ר אֵלֵ֖י⁠נוּ בְּ⁠חֹרֵ֣ב לֵ⁠אמֹ֑ר רַב־לָ⁠כֶ֥ם שֶׁ֖בֶת בָּ⁠הָ֥ר הַ⁠זֶּֽה׃","yĕhwá֧h ʼèlòhé֛y⁠nẇ di̇bė֥r ʼélé֖y⁠nẇ bĕ̇⁠ẖòré֣b lé⁠ʼmò֑r rab-lá⁠ke֥m şě֖beţ bá̇⁠há֥r ha⁠zėֽh׃"],[1,7,"פְּנ֣וּ ׀ וּ⁠סְע֣וּ לָ⁠כֶ֗ם וּ⁠בֹ֨אוּ הַ֥ר הָֽ⁠אֱמֹרִי֮ וְ⁠אֶל־כָּל־שְׁכֵנָי⁠ו֒ בָּ⁠עֲרָבָ֥ה בָ⁠הָ֛ר וּ⁠בַ⁠שְּׁפֵלָ֥ה וּ⁠בַ⁠נֶּ֖גֶב וּ⁠בְ⁠ח֣וֹף הַ⁠יָּ֑ם אֶ֤רֶץ הַֽ⁠כְּנַעֲנִי֙ וְ⁠הַ⁠לְּבָנ֔וֹן עַד־הַ⁠נָּהָ֥ר הַ⁠גָּדֹ֖ל נְהַר־פְּרָֽת׃","pĕ̇n֣ẇ ׀ ẇ⁠sĕʻ֣ẇ lá⁠ke֗m ẇ⁠bò֨ʼẇ ha֥r háֽ⁠ʼèmòriy֮ wĕ⁠ʼel-ká̇l-şĕ̌kénáy⁠w֒ bá̇⁠ʻàrábá֥h bá⁠há֛r ẇ⁠ba⁠şĕ̇̌pélá֥h ẇ⁠ba⁠nė֖geb ẇ⁠bĕ⁠ẖ֣wòp ha⁠yá֑̇m ʼe֤reẕ haֽ⁠kĕ̇naʻàniy֙ wĕ⁠ha⁠lĕ̇bán֔wòn ʻad-ha⁠ná̇há֥r ha⁠gá̇dò֖l nĕhar-pĕ̇ráֽţ׃"],[1,8,"רְאֵ֛ה נָתַ֥תִּי לִ⁠פְנֵי⁠כֶ֖ם אֶת־הָ⁠אָ֑רֶץ בֹּ֚אוּ וּ⁠רְשׁ֣וּ אֶת־הָ⁠אָ֔רֶץ אֲשֶׁ֣ר נִשְׁבַּ֣ע יְ֠הוָה לַ⁠אֲבֹ֨תֵי⁠כֶ֜ם לְ⁠אַבְרָהָ֨ם לְ⁠יִצְחָ֤ק וּֽ⁠לְ⁠יַעֲקֹב֙ לָ⁠תֵ֣ת לָ⁠הֶ֔ם וּ⁠לְ⁠זַרְעָ֖⁠ם אַחֲרֵי⁠הֶֽם׃","rĕʼé֛h náţa֥ţi̇y li⁠pĕnéy⁠ke֖m ʼeţ-há⁠ʼá֑reẕ bò֚̇ʼẇ ẇ⁠rĕş֣̌ẇ ʼeţ-há⁠ʼá֔reẕ ʼàşě֣r nişĕ̌bȧ֣ʻ yĕ֠hwáh la⁠ʼàbò֨ţéy⁠ke֜m lĕ⁠ʼabĕráhá֨m lĕ⁠yiẕĕẖá֤q ẇֽ⁠lĕ⁠yaʻàqòb֙ lá⁠ţé֣ţ lá⁠he֔m ẇ⁠lĕ⁠zarĕʻá֖⁠m ʼaẖàréy⁠heֽm׃"],[1,9,"וָ⁠אֹמַ֣ר אֲלֵ⁠כֶ֔ם בָּ⁠עֵ֥ת הַ⁠הִ֖וא לֵ⁠אמֹ֑ר לֹא־אוּכַ֥ל לְ⁠בַדִּ֖⁠י שְׂאֵ֥ת אֶתְ⁠כֶֽם׃","wá⁠ʼòma֣r ʼàlé⁠ke֔m bá̇⁠ʻé֥ţ ha⁠hi֖wʼ lé⁠ʼmò֑r lòʼ-ʼẇka֥l lĕ⁠badi֖̇⁠y şĕ̂ʼé֥ţ ʼeţĕ⁠keֽm׃"],[1,10,"יְהוָ֥ה אֱלֹהֵי⁠כֶ֖ם הִרְבָּ֣ה אֶתְ⁠כֶ֑ם וְ⁠הִנְּ⁠כֶ֣ם הַ⁠יּ֔וֹם כְּ⁠כוֹכְבֵ֥י הַ⁠שָּׁמַ֖יִם לָ⁠רֹֽב׃","yĕhwá֥h ʼèlòhéy⁠ke֖m hirĕbá֣̇h ʼeţĕ⁠ke֑m wĕ⁠hinĕ̇⁠ke֣m ha⁠ẏ֔wòm kĕ̇⁠kwòkĕbé֥y ha⁠şá̇̌ma֖yim lá⁠ròֽb׃"],[1,11,"יְהוָ֞ה אֱלֹהֵ֣י אֲבֽוֹתֵ⁠כֶ֗ם יֹסֵ֧ף עֲלֵי⁠כֶ֛ם כָּ⁠כֶ֖ם אֶ֣לֶף פְּעָמִ֑ים וִ⁠יבָרֵ֣ךְ אֶתְ⁠כֶ֔ם כַּ⁠אֲשֶׁ֖ר דִּבֶּ֥ר לָ⁠כֶֽם׃","yĕhwá֞h ʼèlòhé֣y ʼàbֽwòţé⁠ke֗m yòsé֧p ʻàléy⁠ke֛m ká̇⁠ke֖m ʼe֣lep pĕ̇ʻámi֑ym wi⁠ybáré֣kĕ ʼeţĕ⁠ke֔m kȧ⁠ʼàşě֖r di̇bė֥r lá⁠keֽm׃"],[1,12,"אֵיכָ֥ה אֶשָּׂ֖א לְ⁠בַדִּ֑⁠י טָרְחֲ⁠כֶ֥ם וּ⁠מַֽשַּׂאֲ⁠כֶ֖ם וְ⁠רִֽיבְ⁠כֶֽם׃","ʼéyká֥h ʼeşá֖̇̂ʼ lĕ⁠badi֑̇⁠y tárĕẖà⁠ke֥m ẇ⁠maֽşȧ̂ʼà⁠ke֖m wĕ⁠riֽybĕ⁠keֽm׃"],[1,13,"הָב֣וּ לָ֠⁠כֶם אֲנָשִׁ֨ים חֲכָמִ֧ים וּ⁠נְבֹנִ֛ים וִ⁠ידֻעִ֖ים לְ⁠שִׁבְטֵי⁠כֶ֑ם וַ⁠אֲשִׂימֵ֖⁠ם בְּ⁠רָאשֵׁי⁠כֶֽם׃","háb֣ẇ lá֠⁠kem ʼànáşǐ֨ym ẖàkámi֧ym ẇ⁠nĕbòni֛ym wi⁠yduʻi֖ym lĕ⁠şǐbĕtéy⁠ke֑m wa⁠ʼàşîymé֖⁠m bĕ̇⁠ráʼşé̌y⁠keֽm׃"],[1,14,"וַֽ⁠תַּעֲנ֖וּ אֹתִ֑⁠י וַ⁠תֹּ֣אמְר֔וּ טֽוֹב־הַ⁠דָּבָ֥ר אֲשֶׁר־דִּבַּ֖רְתָּ לַ⁠עֲשֽׂוֹת׃","waֽ⁠ţȧʻàn֖ẇ ʼòţi֑⁠y wa⁠ţò֣̇ʼmĕr֔ẇ tֽwòb-ha⁠dá̇bá֥r ʼàşěr-di̇bȧ֖rĕţá̇ la⁠ʻàşֽ̂wòţ׃"],[1,15,"וָ⁠אֶקַּ֞ח אֶת־רָאשֵׁ֣י שִׁבְטֵי⁠כֶ֗ם אֲנָשִׁ֤ים חֲכָמִים֙ וִֽ⁠ידֻעִ֔ים וָ⁠אֶתֵּ֥ן אֹתָ֛⁠ם רָאשִׁ֖ים עֲלֵי⁠כֶ֑ם שָׂרֵ֨י אֲלָפִ֜ים וְ⁠שָׂרֵ֣י מֵא֗וֹת וְ⁠שָׂרֵ֤י חֲמִשִּׁים֙ וְ⁠שָׂרֵ֣י עֲשָׂרֹ֔ת וְ⁠שֹׁטְרִ֖ים לְ⁠שִׁבְטֵי⁠כֶֽם׃","wá⁠ʼeqȧ֞ẖ ʼeţ-ráʼşé֣̌y şǐbĕtéy⁠ke֗m ʼànáşǐ֤ym ẖàkámiym֙ wiֽ⁠yduʻi֔ym wá⁠ʼeţé֥̇n ʼòţá֛⁠m ráʼşǐ֖ym ʻàléy⁠ke֑m şá̂ré֨y ʼàlápi֜ym wĕ⁠şá̂ré֣y méʼ֗wòţ wĕ⁠şá̂ré֤y ẖàmişi̇̌ym֙ wĕ⁠şá̂ré֣y ʻàşá̂rò֔ţ wĕ⁠şò̌tĕri֖ym lĕ⁠şǐbĕtéy⁠keֽm׃"],[1,16,"וָ⁠אֲצַוֶּה֙ אֶת־שֹׁ֣פְטֵי⁠כֶ֔ם בָּ⁠עֵ֥ת הַ⁠הִ֖וא לֵ⁠אמֹ֑ר שָׁמֹ֤עַ בֵּין־אֲחֵי⁠כֶם֙ וּ⁠שְׁפַטְתֶּ֣ם צֶ֔דֶק בֵּֽין־אִ֥ישׁ וּ⁠בֵין־אָחִ֖י⁠ו וּ⁠בֵ֥ין גֵּרֽ⁠וֹ׃","wá⁠ʼàẕawėh֙ ʼeţ-şò֣̌pĕtéy⁠ke֔m bá̇⁠ʻé֥ţ ha⁠hi֖wʼ lé⁠ʼmò֑r şá̌mò֤ʻa bé̇yn-ʼàẖéy⁠kem֙ ẇ⁠şĕ̌patĕţė֣m ẕe֔deq béֽ̇yn-ʼi֥yş̌ ẇ⁠béyn-ʼáẖi֖y⁠w ẇ⁠bé֥yn gé̇rֽ⁠wò׃"],[1,17,"לֹֽא־תַכִּ֨ירוּ פָנִ֜ים בַּ⁠מִּשְׁפָּ֗ט כַּ⁠קָּטֹ֤ן כַּ⁠גָּדֹל֙ תִּשְׁמָע֔וּ⁠ן לֹ֤א תָג֨וּרוּ֙ מִ⁠פְּנֵי־אִ֔ישׁ כִּ֥י הַ⁠מִּשְׁפָּ֖ט לֵ⁠אלֹהִ֣ים ה֑וּא וְ⁠הַ⁠דָּבָר֙ אֲשֶׁ֣ר יִקְשֶׁ֣ה מִ⁠כֶּ֔ם תַּקְרִב֥וּ⁠ן אֵלַ֖⁠י וּ⁠שְׁמַעְתִּֽי⁠ו׃","lòֽʼ-ţaki̇֨yrẇ páni֜ym bȧ⁠mi̇şĕ̌pá̇֗t kȧ⁠qá̇tò֤n kȧ⁠gá̇dòl֙ ţi̇şĕ̌máʻ֔ẇ⁠n lò֤ʼ ţág֨ẇrẇ֙ mi⁠pĕ̇néy-ʼi֔yş̌ ki֥̇y ha⁠mi̇şĕ̌pá֖̇t lé⁠ʼlòhi֣ym h֑ẇʼ wĕ⁠ha⁠dá̇bár֙ ʼàşě֣r yiqĕşě֣h mi⁠kė֔m ţȧqĕrib֥ẇ⁠n ʼéla֖⁠y ẇ⁠şĕ̌maʻĕţiֽ̇y⁠w׃"],[1,18,"וָ⁠אֲצַוֶּ֥ה אֶתְ⁠כֶ֖ם בָּ⁠עֵ֣ת הַ⁠הִ֑וא אֵ֥ת כָּל־הַ⁠דְּבָרִ֖ים אֲשֶׁ֥ר תַּעֲשֽׂוּ⁠ן׃","wá⁠ʼàẕawė֥h ʼeţĕ⁠ke֖m bá̇⁠ʻé֣ţ ha⁠hi֑wʼ ʼé֥ţ ká̇l-ha⁠dĕ̇bári֖ym ʼàşě֥r ţȧʻàşֽ̂ẇ⁠n׃"],[1,19,"וַ⁠נִּסַּ֣ע מֵ⁠חֹרֵ֗ב וַ⁠נֵּ֡לֶךְ אֵ֣ת כָּל־הַ⁠מִּדְבָּ֣ר הַ⁠גָּדוֹל֩ וְ⁠הַ⁠נּוֹרָ֨א הַ⁠ה֜וּא אֲשֶׁ֣ר רְאִיתֶ֗ם דֶּ֚רֶךְ הַ֣ר הָֽ⁠אֱמֹרִ֔י כַּ⁠אֲשֶׁ֥ר צִוָּ֛ה יְהוָ֥ה אֱלֹהֵ֖י⁠נוּ אֹתָ֑⁠נוּ וַ⁠נָּבֹ֕א עַ֖ד קָדֵ֥שׁ בַּרְנֵֽעַ׃","wa⁠ni̇sȧ֣ʻ mé⁠ẖòré֗b wa⁠né̇֡lekĕ ʼé֣ţ ká̇l-ha⁠mi̇dĕbá֣̇r ha⁠gá̇dwòl֩ wĕ⁠ha⁠ṅwòrá֨ʼ ha⁠h֜ẇʼ ʼàşě֣r rĕʼiyţe֗m dė֚rekĕ ha֣r háֽ⁠ʼèmòri֔y kȧ⁠ʼàşě֥r ẕiwá֛̇h yĕhwá֥h ʼèlòhé֖y⁠nẇ ʼòţá֑⁠nẇ wa⁠ná̇bò֕ʼ ʻa֖d qádé֥ş̌ bȧrĕnéֽʻa׃"],[1,20,"וָ⁠אֹמַ֖ר אֲלֵ⁠כֶ֑ם בָּאתֶם֙ עַד־הַ֣ר הָ⁠אֱמֹרִ֔י אֲשֶׁר־יְהוָ֥ה אֱלֹהֵ֖י⁠נוּ נֹתֵ֥ן לָֽ⁠נוּ׃","wá⁠ʼòma֖r ʼàlé⁠ke֑m bá̇ʼţem֙ ʻad-ha֣r há⁠ʼèmòri֔y ʼàşěr-yĕhwá֥h ʼèlòhé֖y⁠nẇ nòţé֥n láֽ⁠nẇ׃"],[1,21,"רְ֠אֵה נָתַ֨ן יְהוָ֧ה אֱלֹהֶ֛י⁠ךָ לְ⁠פָנֶ֖י⁠ךָ אֶת־הָ⁠אָ֑רֶץ עֲלֵ֣ה רֵ֗שׁ כַּ⁠אֲשֶׁר֩ דִּבֶּ֨ר יְהוָ֜ה אֱלֹהֵ֤י אֲבֹתֶ֨י⁠ךָ֙ לָ֔⁠ךְ אַל־תִּירָ֖א וְ⁠אַל־תֵּחָֽת׃","rĕ֠ʼéh náţa֨n yĕhwá֧h ʼèlòhe֛y⁠ká lĕ⁠páne֖y⁠ká ʼeţ-há⁠ʼá֑reẕ ʻàlé֣h ré֗ş̌ kȧ⁠ʼàşěr֩ di̇bė֨r yĕhwá֜h ʼèlòhé֤y ʼàbòţe֨y⁠ká֙ lá֔⁠kĕ ʼal-ţi̇yrá֖ʼ wĕ⁠ʼal-ţé̇ẖáֽţ׃"],[1,22,"וַ⁠תִּקְרְב֣וּ⁠ן אֵלַ⁠י֮ כֻּלְּ⁠כֶם֒ וַ⁠תֹּאמְר֗וּ נִשְׁלְחָ֤ה אֲנָשִׁים֙ לְ⁠פָנֵ֔י⁠נוּ וְ⁠יַחְפְּרוּ־לָ֖⁠נוּ אֶת־הָ⁠אָ֑רֶץ וְ⁠יָשִׁ֤בוּ אֹתָ֨⁠נוּ֙ דָּבָ֔ר אֶת־הַ⁠דֶּ֨רֶךְ֙ אֲשֶׁ֣ר נַעֲלֶה־בָּ֔⁠הּ וְ⁠אֵת֙ הֶֽ⁠עָרִ֔ים אֲשֶׁ֥ר נָבֹ֖א אֲלֵי⁠הֶֽן׃","wa⁠ţi̇qĕrĕb֣ẇ⁠n ʼéla⁠y֮ ku̇lĕ̇⁠kem֒ wa⁠ţò̇ʼmĕr֗ẇ nişĕ̌lĕẖá֤h ʼànáşǐym֙ lĕ⁠páné֔y⁠nẇ wĕ⁠yaẖĕpĕ̇rẇ-lá֖⁠nẇ ʼeţ-há⁠ʼá֑reẕ wĕ⁠yáşǐ֤bẇ ʼòţá֨⁠nẇ֙ dá̇bá֔r ʼeţ-ha⁠dė֨rekĕ֙ ʼàşě֣r naʻàleh-bá̇֔⁠ḣ wĕ⁠ʼéţ֙ heֽ⁠ʻári֔ym ʼàşě֥r nábò֖ʼ ʼàléy⁠heֽn׃"],[1,23,"וַ⁠יִּיטַ֥ב בְּ⁠עֵינַ֖⁠י הַ⁠דָּבָ֑ר וָ⁠אֶקַּ֤ח מִ⁠כֶּם֙ שְׁנֵ֣ים עָשָׂ֣ר אֲנָשִׁ֔ים אִ֥ישׁ אֶחָ֖ד לַ⁠שָּֽׁבֶט׃","wa⁠yi̇yta֥b bĕ̇⁠ʻéyna֖⁠y ha⁠dá̇bá֑r wá⁠ʼeqȧ֤ẖ mi⁠kėm֙ şĕ̌né֣ym ʻáşá֣̂r ʼànáşǐ֔ym ʼi֥yş̌ ʼeẖá֖d la⁠şáֽ̇̌bet׃"],[1,24,"וַ⁠יִּפְנוּ֙ וַ⁠יַּעֲל֣וּ הָ⁠הָ֔רָ⁠ה וַ⁠יָּבֹ֖אוּ עַד־נַ֣חַל אֶשְׁכֹּ֑ל וַֽ⁠יְרַגְּל֖וּ אֹתָֽ⁠הּ׃","wa⁠yi̇pĕnẇ֙ wa⁠yȧʻàl֣ẇ há⁠há֔rá⁠h wa⁠yá̇bò֖ʼẇ ʻad-na֣ẖal ʼeşĕ̌kò֑̇l waֽ⁠yĕragĕ̇l֖ẇ ʼòţáֽ⁠ḣ׃"],[1,25,"וַ⁠יִּקְח֤וּ בְ⁠יָדָ⁠ם֙ מִ⁠פְּרִ֣י הָ⁠אָ֔רֶץ וַ⁠יּוֹרִ֖דוּ אֵלֵ֑י⁠נוּ וַ⁠יָּשִׁ֨בוּ אֹתָ֤⁠נוּ דָבָר֙ וַ⁠יֹּ֣אמְר֔וּ טוֹבָ֣ה הָ⁠אָ֔רֶץ אֲשֶׁר־יְהוָ֥ה אֱלֹהֵ֖י⁠נוּ נֹתֵ֥ן לָֽ⁠נוּ׃","wa⁠yi̇qĕẖ֤ẇ bĕ⁠yádá⁠m֙ mi⁠pĕ̇ri֣y há⁠ʼá֔reẕ wa⁠ẏwòri֖dẇ ʼélé֑y⁠nẇ wa⁠yá̇şǐ֨bẇ ʼòţá֤⁠nẇ dábár֙ wa⁠yò֣̇ʼmĕr֔ẇ twòbá֣h há⁠ʼá֔reẕ ʼàşěr-yĕhwá֥h ʼèlòhé֖y⁠nẇ nòţé֥n láֽ⁠nẇ׃"],[1,26,"וְ⁠לֹ֥א אֲבִיתֶ֖ם לַ⁠עֲלֹ֑ת וַ⁠תַּמְר֕וּ אֶת־פִּ֥י יְהוָ֖ה אֱלֹהֵי⁠כֶֽם׃","wĕ⁠lò֥ʼ ʼàbiyţe֖m la⁠ʻàlò֑ţ wa⁠ţȧmĕr֕ẇ ʼeţ-pi֥̇y yĕhwá֖h ʼèlòhéy⁠keֽm׃"],[1,27,"וַ⁠תֵּרָגְנ֤וּ בְ⁠אָהֳלֵי⁠כֶם֙ וַ⁠תֹּ֣אמְר֔וּ בְּ⁠שִׂנְאַ֤ת יְהוָה֙ אֹתָ֔⁠נוּ הוֹצִיאָ֖⁠נוּ מֵ⁠אֶ֣רֶץ מִצְרָ֑יִם לָ⁠תֵ֥ת אֹתָ֛⁠נוּ בְּ⁠יַ֥ד הָ⁠אֱמֹרִ֖י לְ⁠הַשְׁמִידֵֽ⁠נוּ׃","wa⁠ţé̇rágĕn֤ẇ bĕ⁠ʼáholéy⁠kem֙ wa⁠ţò֣̇ʼmĕr֔ẇ bĕ̇⁠şînĕʼa֤ţ yĕhwáh֙ ʼòţá֔⁠nẇ hwòẕiyʼá֖⁠nẇ mé⁠ʼe֣reẕ miẕĕrá֑yim lá⁠ţé֥ţ ʼòţá֛⁠nẇ bĕ̇⁠ya֥d há⁠ʼèmòri֖y lĕ⁠haşĕ̌miydéֽ⁠nẇ׃"],[1,28,"אָנָ֣ה ׀ אֲנַ֣חְנוּ עֹלִ֗ים אַחֵי⁠נוּ֩ הֵמַ֨סּוּ אֶת־לְבָבֵ֜⁠נוּ לֵ⁠אמֹ֗ר עַ֣ם גָּד֤וֹל וָ⁠רָם֙ מִמֶּ֔⁠נּוּ עָרִ֛ים גְּדֹלֹ֥ת וּ⁠בְצוּרֹ֖ת בַּ⁠שָּׁמָ֑יִם וְ⁠גַם־בְּנֵ֥י עֲנָקִ֖ים רָאִ֥ינוּ שָֽׁם׃","ʼáná֣h ׀ ʼàna֣ẖĕnẇ ʻòli֗ym ʼaẖéy⁠nẇ֩ héma֨ṡẇ ʼeţ-lĕbábé֜⁠nẇ lé⁠ʼmò֗r ʻa֣m gá̇d֤wòl wá⁠rám֙ mimė֔⁠ṅẇ ʻári֛ym gĕ̇dòlò֥ţ ẇ⁠bĕẕẇrò֖ţ bȧ⁠şá̇̌má֑yim wĕ⁠gam-bĕ̇né֥y ʻànáqi֖ym ráʼi֥ynẇ şáֽ̌m׃"],[1,29,"וָ⁠אֹמַ֖ר אֲלֵ⁠כֶ֑ם לֹא־תַֽעַרְצ֥וּ⁠ן וְֽ⁠לֹא־תִֽירְא֖וּ⁠ן מֵ⁠הֶֽם׃","wá⁠ʼòma֖r ʼàlé⁠ke֑m lòʼ-ţaֽʻarĕẕ֥ẇ⁠n wĕֽ⁠lòʼ-ţiֽyrĕʼ֖ẇ⁠n mé⁠heֽm׃"],[1,30,"יְהוָ֤ה אֱלֹֽהֵי⁠כֶם֙ הַ⁠הֹלֵ֣ךְ לִ⁠פְנֵי⁠כֶ֔ם ה֖וּא יִלָּחֵ֣ם לָ⁠כֶ֑ם כְּ֠⁠כֹל אֲשֶׁ֨ר עָשָׂ֧ה אִתְּ⁠כֶ֛ם בְּ⁠מִצְרַ֖יִם לְ⁠עֵינֵי⁠כֶֽם׃","yĕhwá֤h ʼèlòֽhéy⁠kem֙ ha⁠hòlé֣kĕ li⁠pĕnéy⁠ke֔m h֖ẇʼ yilá̇ẖé֣m lá⁠ke֑m kĕ̇֠⁠kòl ʼàşě֨r ʻáşá֧̂h ʼiţĕ̇⁠ke֛m bĕ̇⁠miẕĕra֖yim lĕ⁠ʻéynéy⁠keֽm׃"],[1,31,"וּ⁠בַ⁠מִּדְבָּר֙ אֲשֶׁ֣ר רָאִ֔יתָ אֲשֶׁ֤ר נְשָׂאֲ⁠ךָ֙ יְהוָ֣ה אֱלֹהֶ֔י⁠ךָ כַּ⁠אֲשֶׁ֥ר יִשָּׂא־אִ֖ישׁ אֶת־בְּנ֑⁠וֹ בְּ⁠כָל־הַ⁠דֶּ֨רֶךְ֙ אֲשֶׁ֣ר הֲלַכְתֶּ֔ם עַד־בֹּאֲ⁠כֶ֖ם עַד־הַ⁠מָּק֥וֹם הַ⁠זֶּֽה׃","ẇ⁠ba⁠mi̇dĕbá̇r֙ ʼàşě֣r ráʼi֔yţá ʼàşě֤r nĕşá̂ʼà⁠ká֙ yĕhwá֣h ʼèlòhe֔y⁠ká kȧ⁠ʼàşě֥r yişá̇̂ʼ-ʼi֖yş̌ ʼeţ-bĕ̇n֑⁠wò bĕ̇⁠kál-ha⁠dė֨rekĕ֙ ʼàşě֣r hàlakĕţė֔m ʻad-bò̇ʼà⁠ke֖m ʻad-ha⁠má̇q֥wòm ha⁠zėֽh׃"],[1,32,"וּ⁠בַ⁠דָּבָ֖ר הַ⁠זֶּ֑ה אֵֽינְ⁠כֶם֙ מַאֲמִינִ֔ם בַּ⁠יהוָ֖ה אֱלֹהֵי⁠כֶֽם׃","ẇ⁠ba⁠dá̇bá֖r ha⁠zė֑h ʼéֽynĕ⁠kem֙ maʼàmiyni֔m bȧ⁠yhwá֖h ʼèlòhéy⁠keֽm׃"],[1,33,"הַ⁠הֹלֵ֨ךְ לִ⁠פְנֵי⁠כֶ֜ם בַּ⁠דֶּ֗רֶךְ לָ⁠ת֥וּר לָ⁠כֶ֛ם מָק֖וֹם לַֽ⁠חֲנֹֽתְ⁠כֶ֑ם בָּ⁠אֵ֣שׁ ׀ לַ֗יְלָה לַ⁠רְאֹֽתְ⁠כֶם֙ בַּ⁠דֶּ֨רֶךְ֙ אֲשֶׁ֣ר תֵּֽלְכוּ־בָ֔⁠הּ וּ⁠בֶ⁠עָנָ֖ן יוֹמָֽם׃","ha⁠hòlé֨kĕ li⁠pĕnéy⁠ke֜m bȧ⁠dė֗rekĕ lá⁠ţ֥ẇr lá⁠ke֛m máq֖wòm laֽ⁠ẖànòֽţĕ⁠ke֑m bá̇⁠ʼé֣ş̌ ׀ la֗yĕláh la⁠rĕʼòֽţĕ⁠kem֙ bȧ⁠dė֨rekĕ֙ ʼàşě֣r ţéֽ̇lĕkẇ-bá֔⁠ḣ ẇ⁠be⁠ʻáná֖n ywòmáֽm׃"],[1,34,"וַ⁠יִּשְׁמַ֥ע יְהוָ֖ה אֶת־ק֣וֹל דִּבְרֵי⁠כֶ֑ם וַ⁠יִּקְצֹ֖ף וַ⁠יִּשָּׁבַ֥ע לֵ⁠אמֹֽר׃","wa⁠yi̇şĕ̌ma֥ʻ yĕhwá֖h ʼeţ-q֣wòl di̇bĕréy⁠ke֑m wa⁠yi̇qĕẕò֖p wa⁠yi̇şá̇̌ba֥ʻ lé⁠ʼmòֽr׃"],[1,35,"אִם־יִרְאֶ֥ה אִישׁ֙ בָּ⁠אֲנָשִׁ֣ים הָ⁠אֵ֔לֶּה הַ⁠דּ֥וֹר הָ⁠רָ֖ע הַ⁠זֶּ֑ה אֵ֚ת הָ⁠אָ֣רֶץ הַ⁠טּוֹבָ֔ה אֲשֶׁ֣ר נִשְׁבַּ֔עְתִּי לָ⁠תֵ֖ת לַ⁠אֲבֹתֵי⁠כֶֽם׃","ʼim-yirĕʼe֥h ʼiyş̌֙ bá̇⁠ʼànáşǐ֣ym há⁠ʼé֔lėh ha⁠ḋ֥wòr há⁠rá֖ʻ ha⁠zė֑h ʼé֚ţ há⁠ʼá֣reẕ ha⁠ṫwòbá֔h ʼàşě֣r nişĕ̌bȧ֔ʻĕţi̇y lá⁠ţé֖ţ la⁠ʼàbòţéy⁠keֽm׃"],[1,36,"זֽוּלָתִ֞י כָּלֵ֤ב בֶּן־יְפֻנֶּה֙ ה֣וּא יִרְאֶ֔⁠נָּה וְ⁠לֽ⁠וֹ־אֶתֵּ֧ן אֶת־הָ⁠אָ֛רֶץ אֲשֶׁ֥ר דָּֽרַךְ־בָּ֖⁠הּ וּ⁠לְ⁠בָנָ֑י⁠ו יַ֕עַן אֲשֶׁ֥ר מִלֵּ֖א אַחֲרֵ֥י יְהוָֽה׃","zֽẇláţi֞y ká̇lé֤b bėn-yĕpunėh֙ h֣ẇʼ yirĕʼe֔⁠ná̇h wĕ⁠lֽ⁠wò-ʼeţé֧̇n ʼeţ-há⁠ʼá֛reẕ ʼàşě֥r dáֽ̇rakĕ-bá֖̇⁠ḣ ẇ⁠lĕ⁠báná֑y⁠w ya֕ʻan ʼàşě֥r milé֖̇ʼ ʼaẖàré֥y yĕhwáֽh׃"],[1,37,"גַּם־בִּ⁠י֙ הִתְאַנַּ֣ף יְהוָ֔ה בִּ⁠גְלַלְ⁠כֶ֖ם לֵ⁠אמֹ֑ר גַּם־אַתָּ֖ה לֹא־תָבֹ֥א שָֽׁם׃","gȧm-bi̇⁠y֙ hiţĕʼanȧ֣p yĕhwá֔h bi̇⁠gĕlalĕ⁠ke֖m lé⁠ʼmò֑r gȧm-ʼaţá֖̇h lòʼ-ţábò֥ʼ şáֽ̌m׃"],[1,38,"יְהוֹשֻׁ֤עַ בִּן נוּן֙ הָ⁠עֹמֵ֣ד לְ⁠פָנֶ֔י⁠ךָ ה֖וּא יָ֣בֹא שָׁ֑מָּ⁠ה אֹת֣⁠וֹ חַזֵּ֔ק כִּי־ה֖וּא יַנְחִלֶ֥⁠נָּה אֶת־יִשְׂרָאֵֽל׃","yĕhwòşǔ֤ʻa bi̇n nẇn֙ há⁠ʻòmé֣d lĕ⁠páne֔y⁠ká h֖ẇʼ yá֣bòʼ şá֑̌má̇⁠h ʼòţ֣⁠wò ẖazé̇֔q ki̇y-h֖ẇʼ yanĕẖile֥⁠ná̇h ʼeţ-yişĕ̂ráʼéֽl׃"],[1,39,"וְ⁠טַפְּ⁠כֶם֩ אֲשֶׁ֨ר אֲמַרְתֶּ֜ם לָ⁠בַ֣ז יִהְיֶ֗ה וּ֠⁠בְנֵי⁠כֶם אֲשֶׁ֨ר לֹא־יָדְע֤וּ הַ⁠יּוֹם֙ ט֣וֹב וָ⁠רָ֔ע הֵ֖מָּה יָבֹ֣אוּ שָׁ֑מָּ⁠ה וְ⁠לָ⁠הֶ֣ם אֶתְּנֶ֔⁠נָּה וְ⁠הֵ֖ם יִירָשֽׁוּ⁠הָּ׃","wĕ⁠tapĕ̇⁠kem֩ ʼàşě֨r ʼàmarĕţė֜m lá⁠ba֣z yihĕye֗h ẇ֠⁠bĕnéy⁠kem ʼàşě֨r lòʼ-yádĕʻ֤ẇ ha⁠ẏwòm֙ t֣wòb wá⁠rá֔ʻ hé֖má̇h yábò֣ʼẇ şá֑̌má̇⁠h wĕ⁠lá⁠he֣m ʼeţĕ̇ne֔⁠ná̇h wĕ⁠hé֖m yiyráşֽ̌ẇ⁠há̇׃"],[1,40,"וְ⁠אַתֶּ֖ם פְּנ֣וּ לָ⁠כֶ֑ם וּ⁠סְע֥וּ הַ⁠מִּדְבָּ֖רָ⁠ה דֶּ֥רֶךְ יַם־סֽוּף׃","wĕ⁠ʼaţė֖m pĕ̇n֣ẇ lá⁠ke֑m ẇ⁠sĕʻ֥ẇ ha⁠mi̇dĕbá֖̇rá⁠h dė֥rekĕ yam-sֽẇp׃"],[1,41,"וַֽ⁠תַּעֲנ֣וּ ׀ וַ⁠תֹּאמְר֣וּ אֵלַ֗⁠י חָטָאנוּ֮ לַֽ⁠יהוָה֒ אֲנַ֤חְנוּ נַעֲלֶה֙ וְ⁠נִלְחַ֔מְנוּ כְּ⁠כֹ֥ל אֲשֶׁר־צִוָּ֖⁠נוּ יְהוָ֣ה אֱלֹהֵ֑י⁠נוּ וַֽ⁠תַּחְגְּר֗וּ אִ֚ישׁ אֶת־כְּלֵ֣י מִלְחַמְתּ֔⁠וֹ וַ⁠תָּהִ֖ינוּ לַ⁠עֲלֹ֥ת הָ⁠הָֽרָ⁠ה׃","waֽ⁠ţȧʻàn֣ẇ ׀ wa⁠ţò̇ʼmĕr֣ẇ ʼéla֗⁠y ẖátáʼnẇ֮ laֽ⁠yhwáh֒ ʼàna֤ẖĕnẇ naʻàleh֙ wĕ⁠nilĕẖa֔mĕnẇ kĕ̇⁠kò֥l ʼàşěr-ẕiwá֖̇⁠nẇ yĕhwá֣h ʼèlòhé֑y⁠nẇ waֽ⁠ţȧẖĕgĕ̇r֗ẇ ʼi֚yş̌ ʼeţ-kĕ̇lé֣y milĕẖamĕţ̇֔⁠wò wa⁠ţá̇hi֖ynẇ la⁠ʻàlò֥ţ há⁠háֽrá⁠h׃"],[1,42,"וַ⁠יֹּ֨אמֶר יְהוָ֜ה אֵלַ֗⁠י אֱמֹ֤ר לָ⁠הֶם֙ לֹ֤א תַֽעֲלוּ֙ וְ⁠לֹא־תִלָּ֣חֲמ֔וּ כִּ֥י אֵינֶ֖⁠נִּי בְּ⁠קִרְבְּ⁠כֶ֑ם וְ⁠לֹא֙ תִּנָּֽגְפ֔וּ לִ⁠פְנֵ֖י אֹיְבֵי⁠כֶֽם׃","wa⁠yò̇֨ʼmer yĕhwá֜h ʼéla֗⁠y ʼèmò֤r lá⁠hem֙ lò֤ʼ ţaֽʻàlẇ֙ wĕ⁠lòʼ-ţilá֣̇ẖàm֔ẇ ki֥̇y ʼéyne֖⁠ni̇y bĕ̇⁠qirĕbĕ̇⁠ke֑m wĕ⁠lòʼ֙ ţi̇náֽ̇gĕp֔ẇ li⁠pĕné֖y ʼòyĕbéy⁠keֽm׃"],[1,43,"וָ⁠אֲדַבֵּ֥ר אֲלֵי⁠כֶ֖ם וְ⁠לֹ֣א שְׁמַעְתֶּ֑ם וַ⁠תַּמְרוּ֙ אֶת־פִּ֣י יְהוָ֔ה וַ⁠תָּזִ֖דוּ וַ⁠תַּעֲל֥וּ הָ⁠הָֽרָ⁠ה׃","wá⁠ʼàdabé֥̇r ʼàléy⁠ke֖m wĕ⁠lò֣ʼ şĕ̌maʻĕţė֑m wa⁠ţȧmĕrẇ֙ ʼeţ-pi֣̇y yĕhwá֔h wa⁠ţá̇zi֖dẇ wa⁠ţȧʻàl֥ẇ há⁠háֽrá⁠h׃"],[1,44,"וַ⁠יֵּצֵ֨א הָ⁠אֱמֹרִ֜י הַ⁠יֹּשֵׁ֨ב בָּ⁠הָ֤ר הַ⁠הוּא֙ לִ⁠קְרַאתְ⁠כֶ֔ם וַ⁠יִּרְדְּפ֣וּ אֶתְ⁠כֶ֔ם כַּ⁠אֲשֶׁ֥ר תַּעֲשֶׂ֖ינָה הַ⁠דְּבֹרִ֑ים וַֽ⁠יַּכְּת֥וּ אֶתְ⁠כֶ֛ם בְּ⁠שֵׂעִ֖יר עַד־חָרְמָֽה׃","wa⁠yé̇ẕé֨ʼ há⁠ʼèmòri֜y ha⁠yò̇şé̌֨b bá̇⁠há֤r ha⁠hẇʼ֙ li⁠qĕraʼţĕ⁠ke֔m wa⁠yi̇rĕdĕ̇p֣ẇ ʼeţĕ⁠ke֔m kȧ⁠ʼàşě֥r ţȧʻàşê֖ynáh ha⁠dĕ̇bòri֑ym waֽ⁠yȧkĕ̇ţ֥ẇ ʼeţĕ⁠ke֛m bĕ̇⁠şé̂ʻi֖yr ʻad-ẖárĕmáֽh׃"],[1,45,"וַ⁠תָּשֻׁ֥בוּ וַ⁠תִּבְכּ֖וּ לִ⁠פְנֵ֣י יְהוָ֑ה וְ⁠לֹֽא־שָׁמַ֤ע יְהוָה֙ בְּ⁠קֹ֣לְ⁠כֶ֔ם וְ⁠לֹ֥א הֶאֱזִ֖ין אֲלֵי⁠כֶֽם׃","wa⁠ţá̇şǔ֥bẇ wa⁠ţi̇bĕk֖̇ẇ li⁠pĕné֣y yĕhwá֑h wĕ⁠lòֽʼ-şá̌ma֤ʻ yĕhwáh֙ bĕ̇⁠qò֣lĕ⁠ke֔m wĕ⁠lò֥ʼ heʼèzi֖yn ʼàléy⁠keֽm׃"],[1,46,"וַ⁠תֵּשְׁב֥וּ בְ⁠קָדֵ֖שׁ יָמִ֣ים רַבִּ֑ים כַּ⁠יָּמִ֖ים אֲשֶׁ֥ר יְשַׁבְתֶּֽם׃","wa⁠ţé̇şĕ̌b֥ẇ bĕ⁠qádé֖ş̌ yámi֣ym rabi֑̇ym kȧ⁠yá̇mi֖ym ʼàşě֥r yĕşǎbĕţėֽm׃"],[2,1,"וַ⁠נֵּ֜פֶן וַ⁠נִּסַּ֤ע הַ⁠מִּדְבָּ֨רָ⁠ה֙ דֶּ֣רֶךְ יַם־ס֔וּף כַּ⁠אֲשֶׁ֛ר דִּבֶּ֥ר יְהוָ֖ה אֵלָ֑⁠י וַ⁠נָּ֥סָב אֶת־הַר־שֵׂעִ֖יר יָמִ֥ים רַבִּֽים׃ס","wa⁠né̇֜pen wa⁠ni̇sȧ֤ʻ ha⁠mi̇dĕbá̇֨rá⁠h֙ dė֣rekĕ yam-s֔ẇp kȧ⁠ʼàşě֛r di̇bė֥r yĕhwá֖h ʼélá֑⁠y wa⁠ná֥̇sáb ʼeţ-har-şé̂ʻi֖yr yámi֥ym rabiֽ̇ym׃s"],[2,2,"וַ⁠יֹּ֥אמֶר יְהוָ֖ה אֵלַ֥⁠י לֵ⁠אמֹֽר׃","wa⁠yò֥̇ʼmer yĕhwá֖h ʼéla֥⁠y lé⁠ʼmòֽr׃"],[2,3,"רַב־לָ⁠כֶ֕ם סֹ֖ב אֶת־הָ⁠הָ֣ר הַ⁠זֶּ֑ה פְּנ֥וּ לָ⁠כֶ֖ם צָפֹֽנָ⁠ה׃","rab-lá⁠ke֕m sò֖b ʼeţ-há⁠há֣r ha⁠zė֑h pĕ̇n֥ẇ lá⁠ke֖m ẕápòֽná⁠h׃"],[2,4,"וְ⁠אֶת־הָ⁠עָם֮ צַ֣ו לֵ⁠אמֹר֒ אַתֶּ֣ם עֹֽבְרִ֗ים בִּ⁠גְבוּל֙ אֲחֵי⁠כֶ֣ם בְּנֵי־עֵשָׂ֔ו הַ⁠יֹּשְׁבִ֖ים בְּ⁠שֵׂעִ֑יר וְ⁠יִֽירְא֣וּ מִ⁠כֶּ֔ם וְ⁠נִשְׁמַרְתֶּ֖ם מְאֹֽד׃","wĕ⁠ʼeţ-há⁠ʻám֮ ẕa֣w lé⁠ʼmòr֒ ʼaţė֣m ʻòֽbĕri֗ym bi̇⁠gĕbẇl֙ ʼàẖéy⁠ke֣m bĕ̇néy-ʻéşá̂֔w ha⁠yò̇şĕ̌bi֖ym bĕ̇⁠şé̂ʻi֑yr wĕ⁠yiֽyrĕʼ֣ẇ mi⁠kė֔m wĕ⁠nişĕ̌marĕţė֖m mĕʼòֽd׃"],[2,5,"אַל־תִּתְגָּר֣וּ בָ֔⁠ם כִּ֠י לֹֽא־אֶתֵּ֤ן לָ⁠כֶם֙ מֵֽ⁠אַרְצָ֔⁠ם עַ֖ד מִדְרַ֣ךְ כַּף־רָ֑גֶל כִּֽי־יְרֻשָּׁ֣ה לְ⁠עֵשָׂ֔ו נָתַ֖תִּי אֶת־הַ֥ר שֵׂעִֽיר׃","ʼal-ţi̇ţĕgá̇r֣ẇ bá֔⁠m ki̇֠y lòֽʼ-ʼeţé֤̇n lá⁠kem֙ méֽ⁠ʼarĕẕá֔⁠m ʻa֖d midĕra֣kĕ kȧp-rá֑gel kiֽ̇y-yĕruşá֣̇̌h lĕ⁠ʻéşá̂֔w náţa֖ţi̇y ʼeţ-ha֥r şé̂ʻiֽyr׃"],[2,6,"אֹ֣כֶל תִּשְׁבְּר֧וּ מֵֽ⁠אִתָּ֛⁠ם בַּ⁠כֶּ֖סֶף וַ⁠אֲכַלְתֶּ֑ם וְ⁠גַם־מַ֜יִם תִּכְר֧וּ מֵ⁠אִתָּ֛⁠ם בַּ⁠כֶּ֖סֶף וּ⁠שְׁתִיתֶֽם׃","ʼò֣kel ţi̇şĕ̌bĕ̇r֧ẇ méֽ⁠ʼiţá֛̇⁠m bȧ⁠kė֖sep wa⁠ʼàkalĕţė֑m wĕ⁠gam-ma֜yim ţi̇kĕr֧ẇ mé⁠ʼiţá֛̇⁠m bȧ⁠kė֖sep ẇ⁠şĕ̌ţiyţeֽm׃"],[2,7,"כִּי֩ יְהוָ֨ה אֱלֹהֶ֜י⁠ךָ בֵּֽרַכְ⁠ךָ֗ בְּ⁠כֹל֙ מַעֲשֵׂ֣ה יָדֶ֔⁠ךָ יָדַ֣ע לֶכְתְּ⁠ךָ֔ אֶת־הַ⁠מִּדְבָּ֥ר הַ⁠גָּדֹ֖ל הַ⁠זֶּ֑ה זֶ֣ה ׀ אַרְבָּעִ֣ים שָׁנָ֗ה יְהוָ֤ה אֱלֹהֶ֨י⁠ךָ֙ עִמָּ֔⁠ךְ לֹ֥א חָסַ֖רְתָּ דָּבָֽר׃","ki̇y֩ yĕhwá֨h ʼèlòhe֜y⁠ká béֽ̇rakĕ⁠ká֗ bĕ̇⁠kòl֙ maʻàşé֣̂h yáde֔⁠ká yáda֣ʻ lekĕţĕ̇⁠ká֔ ʼeţ-ha⁠mi̇dĕbá֥̇r ha⁠gá̇dò֖l ha⁠zė֑h ze֣h ׀ ʼarĕbá̇ʻi֣ym şá̌ná֗h yĕhwá֤h ʼèlòhe֨y⁠ká֙ ʻimá̇֔⁠kĕ lò֥ʼ ẖása֖rĕţá̇ dá̇báֽr׃"],[2,8,"וַֽ⁠נַּעֲבֹ֞ר מֵ⁠אֵ֧ת אַחֵ֣י⁠נוּ בְנֵי־עֵשָׂ֗ו הַ⁠יֹּֽשְׁבִים֙ בְּ⁠שֵׂעִ֔יר מִ⁠דֶּ֨רֶךְ֙ הָֽ⁠עֲרָבָ֔ה מֵ⁠אֵילַ֖ת וּ⁠מֵ⁠עֶצְיֹ֣ן גָּ֑בֶר ס וַ⁠נֵּ֨פֶן֙ וַֽ⁠נַּעֲבֹ֔ר דֶּ֖רֶךְ מִדְבַּ֥ר מוֹאָֽב׃","waֽ⁠nȧʻàbò֞r mé⁠ʼé֧ţ ʼaẖé֣y⁠nẇ bĕnéy-ʻéşá̂֗w ha⁠yòֽ̇şĕ̌biym֙ bĕ̇⁠şé̂ʻi֔yr mi⁠dė֨rekĕ֙ háֽ⁠ʻàrábá֔h mé⁠ʼéyla֖ţ ẇ⁠mé⁠ʻeẕĕyò֣n gá֑̇ber s wa⁠né̇֨pen֙ waֽ⁠nȧʻàbò֔r dė֖rekĕ midĕbȧ֥r mwòʼáֽb׃"],[2,9,"וַ⁠יֹּ֨אמֶר יְהוָ֜ה אֵלַ֗⁠י אֶל־תָּ֨צַר֙ אֶת־מוֹאָ֔ב וְ⁠אַל־תִּתְגָּ֥ר בָּ֖⁠ם מִלְחָמָ֑ה כִּ֠י לֹֽא־אֶתֵּ֨ן לְ⁠ךָ֤ מֵֽ⁠אַרְצ⁠וֹ֙ יְרֻשָּׁ֔ה כִּ֣י לִ⁠בְנֵי־ל֔וֹט נָתַ֥תִּי אֶת־עָ֖ר יְרֻשָּֽׁה׃","wa⁠yò̇֨ʼmer yĕhwá֜h ʼéla֗⁠y ʼel-ţá̇֨ẕar֙ ʼeţ-mwòʼá֔b wĕ⁠ʼal-ţi̇ţĕgá֥̇r bá֖̇⁠m milĕẖámá֑h ki̇֠y lòֽʼ-ʼeţé̇֨n lĕ⁠ká֤ méֽ⁠ʼarĕẕ⁠wò֙ yĕruşá̇̌֔h ki֣̇y li⁠bĕnéy-l֔wòt náţa֥ţi̇y ʼeţ-ʻá֖r yĕruşáֽ̇̌h׃"],[2,10,"הָ⁠אֵמִ֥ים לְ⁠פָנִ֖ים יָ֣שְׁבוּ בָ֑⁠הּ עַ֣ם גָּד֥וֹל וְ⁠רַ֛ב וָ⁠רָ֖ם כָּ⁠עֲנָקִֽים׃","há⁠ʼémi֥ym lĕ⁠páni֖ym yá֣şĕ̌bẇ bá֑⁠ḣ ʻa֣m gá̇d֥wòl wĕ⁠ra֛b wá⁠rá֖m ká̇⁠ʻànáqiֽym׃"],[2,11,"רְפָאִ֛ים יֵחָשְׁב֥וּ אַף־הֵ֖ם כָּ⁠עֲנָקִ֑ים וְ⁠הַ⁠מֹּ֣אָבִ֔ים יִקְרְא֥וּ לָ⁠הֶ֖ם אֵמִֽים׃","rĕpáʼi֛ym yéẖáşĕ̌b֥ẇ ʼap-hé֖m ká̇⁠ʻànáqi֑ym wĕ⁠ha⁠mò֣̇ʼábi֔ym yiqĕrĕʼ֥ẇ lá⁠he֖m ʼémiֽym׃"],[2,12,"וּ⁠בְ⁠שֵׂעִ֞יר יָשְׁב֣וּ הַ⁠חֹרִים֮ לְ⁠פָנִים֒ וּ⁠בְנֵ֧י עֵשָׂ֣ו יִֽירָשׁ֗וּ⁠ם וַ⁠יַּשְׁמִידוּ⁠ם֙ מִ⁠פְּנֵי⁠הֶ֔ם וַ⁠יֵּשְׁב֖וּ תַּחְתָּ֑⁠ם כַּ⁠אֲשֶׁ֧ר עָשָׂ֣ה יִשְׂרָאֵ֗ל לְ⁠אֶ֨רֶץ֙ יְרֻשָּׁת֔⁠וֹ אֲשֶׁר־נָתַ֥ן יְהוָ֖ה לָ⁠הֶֽם׃","ẇ⁠bĕ⁠şé̂ʻi֞yr yáşĕ̌b֣ẇ ha⁠ẖòriym֮ lĕ⁠pániym֒ ẇ⁠bĕné֧y ʻéşá֣̂w yiֽyráş̌֗ẇ⁠m wa⁠yȧşĕ̌miydẇ⁠m֙ mi⁠pĕ̇néy⁠he֔m wa⁠yé̇şĕ̌b֖ẇ ţȧẖĕţá֑̇⁠m kȧ⁠ʼàşě֧r ʻáşá֣̂h yişĕ̂ráʼé֗l lĕ⁠ʼe֨reẕ֙ yĕruşá̇̌ţ֔⁠wò ʼàşěr-náţa֥n yĕhwá֖h lá⁠heֽm׃"],[2,13,"עַתָּ֗ה קֻ֛מוּ וְ⁠עִבְר֥וּ לָ⁠כֶ֖ם אֶת־נַ֣חַל זָ֑רֶד וַֽ⁠נַּעֲבֹ֖ר אֶת־נַ֥חַל זָֽרֶד׃","ʻaţá̇֗h qu֛mẇ wĕ⁠ʻibĕr֥ẇ lá⁠ke֖m ʼeţ-na֣ẖal zá֑red waֽ⁠nȧʻàbò֖r ʼeţ-na֥ẖal záֽred׃"],[2,14,"וְ⁠הַ⁠יָּמִ֞ים אֲשֶׁר־הָלַ֣כְנוּ ׀ מִ⁠קָּדֵ֣שׁ בַּרְנֵ֗עַ עַ֤ד אֲשֶׁר־עָבַ֨רְנוּ֙ אֶת־נַ֣חַל זֶ֔רֶד שְׁלֹשִׁ֥ים וּ⁠שְׁמֹנֶ֖ה שָׁנָ֑ה עַד־תֹּ֨ם כָּל־הַ⁠דּ֜וֹר אַנְשֵׁ֤י הַ⁠מִּלְחָמָה֙ מִ⁠קֶּ֣רֶב הַֽ⁠מַּחֲנֶ֔ה כַּ⁠אֲשֶׁ֛ר נִשְׁבַּ֥ע יְהוָ֖ה לָ⁠הֶֽם׃","wĕ⁠ha⁠yá̇mi֞ym ʼàşěr-hála֣kĕnẇ ׀ mi⁠qá̇dé֣ş̌ bȧrĕné֗ʻa ʻa֤d ʼàşěr-ʻába֨rĕnẇ֙ ʼeţ-na֣ẖal ze֔red şĕ̌lòşǐ֥ym ẇ⁠şĕ̌mòne֖h şá̌ná֑h ʻad-ţò̇֨m ká̇l-ha⁠ḋ֜wòr ʼanĕşé֤̌y ha⁠mi̇lĕẖámáh֙ mi⁠qė֣reb haֽ⁠mȧẖàne֔h kȧ⁠ʼàşě֛r nişĕ̌bȧ֥ʻ yĕhwá֖h lá⁠heֽm׃"],[2,15,"וְ⁠גַ֤ם יַד־יְהוָה֙ הָ֣יְתָה בָּ֔⁠ם לְ⁠הֻמָּ֖⁠ם מִ⁠קֶּ֣רֶב הַֽ⁠מַּחֲנֶ֑ה עַ֖ד תֻּמָּֽ⁠ם׃","wĕ⁠ga֤m yad-yĕhwáh֙ há֣yĕţáh bá̇֔⁠m lĕ⁠humá֖̇⁠m mi⁠qė֣reb haֽ⁠mȧẖàne֑h ʻa֖d ţu̇máֽ̇⁠m׃"],[2,16,"וַ⁠יְהִ֨י כַ⁠אֲשֶׁר־תַּ֜מּוּ כָּל־אַנְשֵׁ֧י הַ⁠מִּלְחָמָ֛ה לָ⁠מ֖וּת מִ⁠קֶּ֥רֶב הָ⁠עָֽם׃ס","wa⁠yĕhi֨y ka⁠ʼàşěr-ţȧ֜ṁẇ ká̇l-ʼanĕşé֧̌y ha⁠mi̇lĕẖámá֛h lá⁠m֖ẇţ mi⁠qė֥reb há⁠ʻáֽm׃s"],[2,17,"וַ⁠יְדַבֵּ֥ר יְהוָ֖ה אֵלַ֥⁠י לֵ⁠אמֹֽר׃","wa⁠yĕdabé֥̇r yĕhwá֖h ʼéla֥⁠y lé⁠ʼmòֽr׃"],[2,18,"אַתָּ֨ה עֹבֵ֥ר הַ⁠יּ֛וֹם אֶת־גְּב֥וּל מוֹאָ֖ב אֶת־עָֽר׃","ʼaţá̇֨h ʻòbé֥r ha⁠ẏ֛wòm ʼeţ-gĕ̇b֥ẇl mwòʼá֖b ʼeţ-ʻáֽr׃"],[2,19,"וְ⁠קָרַבְתָּ֗ מ֚וּל בְּנֵ֣י עַמּ֔וֹן אַל־תְּצֻרֵ֖⁠ם וְ⁠אַל־תִּתְגָּ֣ר בָּ֑⁠ם כִּ֣י לֹֽא־אֶ֠תֵּן מֵ⁠אֶ֨רֶץ בְּנֵי־עַמּ֤וֹן לְ⁠ךָ֙ יְרֻשָּׁ֔ה כִּ֥י לִ⁠בְנֵי־ל֖וֹט נְתַתִּ֥י⁠הָ יְרֻשָּֽׁה׃","wĕ⁠qárabĕţá̇֗ m֚ẇl bĕ̇né֣y ʻaṁ֔wòn ʼal-ţĕ̇ẕuré֖⁠m wĕ⁠ʼal-ţi̇ţĕgá֣̇r bá֑̇⁠m ki֣̇y lòֽʼ-ʼe֠ţé̇n mé⁠ʼe֨reẕ bĕ̇néy-ʻaṁ֤wòn lĕ⁠ká֙ yĕruşá̇̌֔h ki֥̇y li⁠bĕnéy-l֖wòt nĕţaţi֥̇y⁠há yĕruşáֽ̇̌h׃"],[2,20,"אֶֽרֶץ־רְפָאִ֥ים תֵּחָשֵׁ֖ב אַף־הִ֑וא רְפָאִ֤ים יָֽשְׁבוּ־בָ⁠הּ֙ לְ⁠פָנִ֔ים וְ⁠הָֽ⁠עַמֹּנִ֔ים יִקְרְא֥וּ לָ⁠הֶ֖ם זַמְזֻמִּֽים׃","ʼeֽreẕ-rĕpáʼi֥ym ţé̇ẖáşé֖̌b ʼap-hi֑wʼ rĕpáʼi֤ym yáֽşĕ̌bẇ-bá⁠ḣ֙ lĕ⁠páni֔ym wĕ⁠háֽ⁠ʻamò̇ni֔ym yiqĕrĕʼ֥ẇ lá⁠he֖m zamĕzumiֽ̇ym׃"],[2,21,"עַ֣ם גָּד֥וֹל וְ⁠רַ֛ב וָ⁠רָ֖ם כָּ⁠עֲנָקִ֑ים וַ⁠יַּשְׁמִידֵ֤⁠ם יְהוָה֙ מִ⁠פְּנֵי⁠הֶ֔ם וַ⁠יִּירָשֻׁ֖⁠ם וַ⁠יֵּשְׁב֥וּ תַחְתָּֽ⁠ם׃","ʻa֣m gá̇d֥wòl wĕ⁠ra֛b wá⁠rá֖m ká̇⁠ʻànáqi֑ym wa⁠yȧşĕ̌miydé֤⁠m yĕhwáh֙ mi⁠pĕ̇néy⁠he֔m wa⁠yi̇yráşǔ֖⁠m wa⁠yé̇şĕ̌b֥ẇ ţaẖĕţáֽ̇⁠m׃"],[2,22,"כַּ⁠אֲשֶׁ֤ר עָשָׂה֙ לִ⁠בְנֵ֣י עֵשָׂ֔ו הַ⁠יֹּשְׁבִ֖ים בְּ⁠שֵׂעִ֑יר אֲשֶׁ֨ר הִשְׁמִ֤יד אֶת־הַ⁠חֹרִי֙ מִ⁠פְּנֵי⁠הֶ֔ם וַ⁠יִּֽירָשֻׁ⁠ם֙ וַ⁠יֵּשְׁב֣וּ תַחְתָּ֔⁠ם עַ֖ד הַ⁠יּ֥וֹם הַ⁠זֶּֽה׃","kȧ⁠ʼàşě֤r ʻáşá̂h֙ li⁠bĕné֣y ʻéşá̂֔w ha⁠yò̇şĕ̌bi֖ym bĕ̇⁠şé̂ʻi֑yr ʼàşě֨r hişĕ̌mi֤yd ʼeţ-ha⁠ẖòriy֙ mi⁠pĕ̇néy⁠he֔m wa⁠yiֽ̇yráşǔ⁠m֙ wa⁠yé̇şĕ̌b֣ẇ ţaẖĕţá̇֔⁠m ʻa֖d ha⁠ẏ֥wòm ha⁠zėֽh׃"],[2,23,"וְ⁠הָֽ⁠עַוִּ֛ים הַ⁠יֹּשְׁבִ֥ים בַּ⁠חֲצֵרִ֖ים עַד־עַזָּ֑ה כַּפְתֹּרִים֙ הַ⁠יֹּצְאִ֣ים מִ⁠כַּפְתּ֔וֹר הִשְׁמִידֻ֖⁠ם וַ⁠יֵּשְׁב֥וּ תַחְתָּֽ⁠ם׃","wĕ⁠háֽ⁠ʻawi֛̇ym ha⁠yò̇şĕ̌bi֥ym bȧ⁠ẖàẕéri֖ym ʻad-ʻazá֑̇h kȧpĕţò̇riym֙ ha⁠yò̇ẕĕʼi֣ym mi⁠kȧpĕţ̇֔wòr hişĕ̌miydu֖⁠m wa⁠yé̇şĕ̌b֥ẇ ţaẖĕţáֽ̇⁠m׃"],[2,24,"ק֣וּמוּ סְּע֗וּ וְ⁠עִבְרוּ֮ אֶת־נַ֣חַל אַרְנֹן֒ רְאֵ֣ה נָתַ֣תִּי בְ֠⁠יָדְ⁠ךָ אֶת־סִיחֹ֨ן מֶֽלֶךְ־חֶשְׁבּ֧וֹן הָֽ⁠אֱמֹרִ֛י וְ⁠אֶת־אַרְצ֖⁠וֹ הָחֵ֣ל רָ֑שׁ וְ⁠הִתְגָּ֥ר בּ֖⁠וֹ מִלְחָמָֽה׃","q֣ẇmẇ sĕ̇ʻ֗ẇ wĕ⁠ʻibĕrẇ֮ ʼeţ-na֣ẖal ʼarĕnòn֒ rĕʼé֣h náţa֣ţi̇y bĕ֠⁠yádĕ⁠ká ʼeţ-siyẖò֨n meֽlekĕ-ẖeşĕ̌ḃ֧wòn háֽ⁠ʼèmòri֛y wĕ⁠ʼeţ-ʼarĕẕ֖⁠wò háẖé֣l rá֑ş̌ wĕ⁠hiţĕgá֥̇r ḃ֖⁠wò milĕẖámáֽh׃"],[2,25,"הַ⁠יּ֣וֹם הַ⁠זֶּ֗ה אָחֵל֙ תֵּ֤ת פַּחְדְּ⁠ךָ֙ וְ⁠יִרְאָ֣תְ⁠ךָ֔ עַל־פְּנֵי֙ הָֽ⁠עַמִּ֔ים תַּ֖חַת כָּל־הַ⁠שָּׁמָ֑יִם אֲשֶׁ֤ר יִשְׁמְעוּ⁠ן֙ שִׁמְעֲ⁠ךָ֔ וְ⁠רָגְז֥וּ וְ⁠חָל֖וּ מִ⁠פָּנֶֽי⁠ךָ׃","ha⁠ẏ֣wòm ha⁠zė֗h ʼáẖél֙ ţé֤̇ţ pȧẖĕdĕ̇⁠ká֙ wĕ⁠yirĕʼá֣ţĕ⁠ká֔ ʻal-pĕ̇néy֙ háֽ⁠ʻami̇֔ym ţȧ֖ẖaţ ká̇l-ha⁠şá̇̌má֑yim ʼàşě֤r yişĕ̌mĕʻẇ⁠n֙ şǐmĕʻà⁠ká֔ wĕ⁠rágĕz֥ẇ wĕ⁠ẖál֖ẇ mi⁠pá̇neֽy⁠ká׃"],[2,26,"וָ⁠אֶשְׁלַ֤ח מַלְאָכִים֙ מִ⁠מִּדְבַּ֣ר קְדֵמ֔וֹת אֶל־סִיח֖וֹן מֶ֣לֶךְ חֶשְׁבּ֑וֹן דִּבְרֵ֥י שָׁל֖וֹם לֵ⁠אמֹֽר׃","wá⁠ʼeşĕ̌la֤ẖ malĕʼákiym֙ mi⁠mi̇dĕbȧ֣r qĕdém֔wòţ ʼel-siyẖ֖wòn me֣lekĕ ẖeşĕ̌ḃ֑wòn di̇bĕré֥y şá̌l֖wòm lé⁠ʼmòֽr׃"],[2,27,"אֶעְבְּרָ֣ה בְ⁠אַרְצֶ֔⁠ךָ בַּ⁠דֶּ֥רֶךְ בַּ⁠דֶּ֖רֶךְ אֵלֵ֑ךְ לֹ֥א אָס֖וּר יָמִ֥ין וּ⁠שְׂמֹֽאול׃","ʼeʻĕbĕ̇rá֣h bĕ⁠ʼarĕẕe֔⁠ká bȧ⁠dė֥rekĕ bȧ⁠dė֖rekĕ ʼélé֑kĕ lò֥ʼ ʼás֖ẇr yámi֥yn ẇ⁠şĕ̂mòֽʼwl׃"],[2,28,"אֹ֣כֶל בַּ⁠כֶּ֤סֶף תַּשְׁבִּרֵ֨⁠נִי֙ וְ⁠אָכַ֔לְתִּי וּ⁠מַ֛יִם בַּ⁠כֶּ֥סֶף תִּתֶּן־לִ֖⁠י וְ⁠שָׁתִ֑יתִי רַ֖ק אֶעְבְּרָ֥ה בְ⁠רַגְלָֽ⁠י׃","ʼò֣kel bȧ⁠kė֤sep ţȧşĕ̌bi̇ré֨⁠niy֙ wĕ⁠ʼáka֔lĕţi̇y ẇ⁠ma֛yim bȧ⁠kė֥sep ţi̇ţėn-li֖⁠y wĕ⁠şá̌ţi֑yţiy ra֖q ʼeʻĕbĕ̇rá֥h bĕ⁠ragĕláֽ⁠y׃"],[2,29,"כַּ⁠אֲשֶׁ֨ר עָֽשׂוּ־לִ֜⁠י בְּנֵ֣י עֵשָׂ֗ו הַ⁠יֹּֽשְׁבִים֙ בְּ⁠שֵׂעִ֔יר וְ⁠הַ⁠מּ֣וֹאָבִ֔ים הַ⁠יֹּשְׁבִ֖ים בְּ⁠עָ֑ר עַ֤ד אֲשֶֽׁר־אֶֽעֱבֹר֙ אֶת־הַ⁠יַּרְדֵּ֔ן אֶל־הָ⁠אָ֕רֶץ אֲשֶׁר־יְהוָ֥ה אֱלֹהֵ֖י⁠נוּ נֹתֵ֥ן לָֽ⁠נוּ׃","kȧ⁠ʼàşě֨r ʻáֽş̂ẇ-li֜⁠y bĕ̇né֣y ʻéşá̂֗w ha⁠yòֽ̇şĕ̌biym֙ bĕ̇⁠şé̂ʻi֔yr wĕ⁠ha⁠ṁ֣wòʼábi֔ym ha⁠yò̇şĕ̌bi֖ym bĕ̇⁠ʻá֑r ʻa֤d ʼàşěֽr-ʼeֽʻèbòr֙ ʼeţ-ha⁠yȧrĕdé̇֔n ʼel-há⁠ʼá֕reẕ ʼàşěr-yĕhwá֥h ʼèlòhé֖y⁠nẇ nòţé֥n láֽ⁠nẇ׃"],[2,30,"וְ⁠לֹ֣א אָבָ֗ה סִיחֹן֙ מֶ֣לֶךְ חֶשְׁבּ֔וֹן הַעֲבִרֵ֖⁠נוּ בּ֑⁠וֹ כִּֽי־הִקְשָׁה֩ יְהוָ֨ה אֱלֹהֶ֜י⁠ךָ אֶת־רוּח֗⁠וֹ וְ⁠אִמֵּץ֙ אֶת־לְבָב֔⁠וֹ לְמַ֛עַן תִּתּ֥⁠וֹ בְ⁠יָדְ⁠ךָ֖ כַּ⁠יּ֥וֹם הַ⁠זֶּֽה׃ס","wĕ⁠lò֣ʼ ʼábá֗h siyẖòn֙ me֣lekĕ ẖeşĕ̌ḃ֔wòn haʻàbiré֖⁠nẇ ḃ֑⁠wò kiֽ̇y-hiqĕşá̌h֩ yĕhwá֨h ʼèlòhe֜y⁠ká ʼeţ-rẇẖ֗⁠wò wĕ⁠ʼimé̇ẕ֙ ʼeţ-lĕbáb֔⁠wò lĕma֛ʻan ţi̇ţ֥̇⁠wò bĕ⁠yádĕ⁠ká֖ kȧ⁠ẏ֥wòm ha⁠zėֽh׃s"],[2,31,"וַ⁠יֹּ֤אמֶר יְהוָה֙ אֵלַ֔⁠י רְאֵ֗ה הַֽחִלֹּ֨תִי֙ תֵּ֣ת לְ⁠פָנֶ֔י⁠ךָ אֶת־סִיחֹ֖ן וְ⁠אֶת־אַרְצ֑⁠וֹ הָחֵ֣ל רָ֔שׁ לָ⁠רֶ֖שֶׁת אֶת־אַרְצֽ⁠וֹ׃","wa⁠yò֤̇ʼmer yĕhwáh֙ ʼéla֔⁠y rĕʼé֗h haֽẖilò̇֨ţiy֙ ţé֣̇ţ lĕ⁠páne֔y⁠ká ʼeţ-siyẖò֖n wĕ⁠ʼeţ-ʼarĕẕ֑⁠wò háẖé֣l rá֔ş̌ lá⁠re֖şěţ ʼeţ-ʼarĕẕֽ⁠wò׃"],[2,32,"וַ⁠יֵּצֵא֩ סִיחֹ֨ן לִ⁠קְרָאתֵ֜⁠נוּ ה֧וּא וְ⁠כָל־עַמּ֛⁠וֹ לַ⁠מִּלְחָמָ֖ה יָֽהְצָ⁠ה׃","wa⁠yé̇ẕéʼ֩ siyẖò֨n li⁠qĕráʼţé֜⁠nẇ h֧ẇʼ wĕ⁠kál-ʻaṁ֛⁠wò la⁠mi̇lĕẖámá֖h yáֽhĕẕá⁠h׃"],[2,33,"וַֽ⁠יִּתְּנֵ֛⁠הוּ יְהוָ֥ה אֱלֹהֵ֖י⁠נוּ לְ⁠פָנֵ֑י⁠נוּ וַ⁠נַּ֥ךְ אֹת֛⁠וֹ וְ⁠אֶת־בנ⁠ו וְ⁠אֶת־כָּל־עַמּֽ⁠וֹ׃","waֽ⁠yi̇ţĕ̇né֛⁠hẇ yĕhwá֥h ʼèlòhé֖y⁠nẇ lĕ⁠páné֑y⁠nẇ wa⁠nȧ֥kĕ ʼòţ֛⁠wò wĕ⁠ʼeţ-bn⁠w wĕ⁠ʼeţ-ká̇l-ʻaṁֽ⁠wò׃"],[2,34,"וַ⁠נִּלְכֹּ֤ד אֶת־כָּל־עָרָי⁠ו֙ בָּ⁠עֵ֣ת הַ⁠הִ֔וא וַֽ⁠נַּחֲרֵם֙ אֶת־כָּל־עִ֣יר מְתִ֔ם וְ⁠הַ⁠נָּשִׁ֖ים וְ⁠הַ⁠טָּ֑ף לֹ֥א הִשְׁאַ֖רְנוּ שָׂרִֽיד׃","wa⁠ni̇lĕkò֤̇d ʼeţ-ká̇l-ʻáráy⁠w֙ bá̇⁠ʻé֣ţ ha⁠hi֔wʼ waֽ⁠nȧẖàrém֙ ʼeţ-ká̇l-ʻi֣yr mĕţi֔m wĕ⁠ha⁠ná̇şǐ֖ym wĕ⁠ha⁠tá֑̇p lò֥ʼ hişĕ̌ʼa֖rĕnẇ şá̂riֽyd׃"],[2,35,"רַ֥ק הַ⁠בְּהֵמָ֖ה בָּזַ֣זְנוּ לָ֑⁠נוּ וּ⁠שְׁלַ֥ל הֶ⁠עָרִ֖ים אֲשֶׁ֥ר לָכָֽדְנוּ׃","ra֥q ha⁠bĕ̇hémá֖h bá̇za֣zĕnẇ lá֑⁠nẇ ẇ⁠şĕ̌la֥l he⁠ʻári֖ym ʼàşě֥r lákáֽdĕnẇ׃"],[2,36,"מֵֽ⁠עֲרֹעֵ֡ר אֲשֶׁר֩ עַל־שְׂפַת־נַ֨חַל אַרְנֹ֜ן וְ⁠הָ⁠עִ֨יר אֲשֶׁ֤ר בַּ⁠נַּ֨חַל֙ וְ⁠עַד־הַ⁠גִּלְעָ֔ד לֹ֤א הָֽיְתָה֙ קִרְיָ֔ה אֲשֶׁ֥ר שָׂגְבָ֖ה מִמֶּ֑⁠נּוּ אֶת־הַ⁠כֹּ֕ל נָתַ֛ן יְהוָ֥ה אֱלֹהֵ֖י⁠נוּ לְ⁠פָנֵֽי⁠נוּ׃","méֽ⁠ʻàròʻé֡r ʼàşěr֩ ʻal-şĕ̂paţ-na֨ẖal ʼarĕnò֜n wĕ⁠há⁠ʻi֨yr ʼàşě֤r bȧ⁠nȧ֨ẖal֙ wĕ⁠ʻad-ha⁠gi̇lĕʻá֔d lò֤ʼ háֽyĕţáh֙ qirĕyá֔h ʼàşě֥r şá̂gĕbá֖h mimė֑⁠ṅẇ ʼeţ-ha⁠kò̇֕l náţa֛n yĕhwá֥h ʼèlòhé֖y⁠nẇ lĕ⁠pánéֽy⁠nẇ׃"],[2,37,"רַ֛ק אֶל־אֶ֥רֶץ בְּנֵי־עַמּ֖וֹן לֹ֣א קָרָ֑בְתָּ כָּל־יַ֞ד נַ֤חַל יַבֹּק֙ וְ⁠עָרֵ֣י הָ⁠הָ֔ר וְ⁠כֹ֥ל אֲשֶׁר־צִוָּ֖ה יְהוָ֥ה אֱלֹהֵֽי⁠נוּ׃","ra֛q ʼel-ʼe֥reẕ bĕ̇néy-ʻaṁ֖wòn lò֣ʼ qárá֑bĕţá̇ ká̇l-ya֞d na֤ẖal yabò̇q֙ wĕ⁠ʻáré֣y há⁠há֔r wĕ⁠kò֥l ʼàşěr-ẕiwá֖̇h yĕhwá֥h ʼèlòhéֽy⁠nẇ׃"],[3,1,"וַ⁠נֵּ֣פֶן וַ⁠נַּ֔עַל דֶּ֖רֶךְ הַ⁠בָּשָׁ֑ן וַ⁠יֵּצֵ֣א עוֹג֩ מֶֽלֶךְ־הַ⁠בָּשָׁ֨ן לִ⁠קְרָאתֵ֜⁠נוּ ה֧וּא וְ⁠כָל־עַמּ֛⁠וֹ לַ⁠מִּלְחָמָ֖ה אֶדְרֶֽעִי׃","wa⁠né֣̇pen wa⁠nȧ֔ʻal dė֖rekĕ ha⁠bá̇şá֑̌n wa⁠yé̇ẕé֣ʼ ʻwòg֩ meֽlekĕ-ha⁠bá̇şá̌֨n li⁠qĕráʼţé֜⁠nẇ h֧ẇʼ wĕ⁠kál-ʻaṁ֛⁠wò la⁠mi̇lĕẖámá֖h ʼedĕreֽʻiy׃"],[3,2,"וַ⁠יֹּ֨אמֶר יְהוָ֤ה אֵלַ⁠י֙ אַל־תִּירָ֣א אֹת֔⁠וֹ כִּ֣י בְ⁠יָדְ⁠ךָ֞ נָתַ֧תִּי אֹת֛⁠וֹ וְ⁠אֶת־כָּל־עַמּ֖⁠וֹ וְ⁠אֶת־אַרְצ֑⁠וֹ וְ⁠עָשִׂ֣יתָ לּ֔⁠וֹ כַּ⁠אֲשֶׁ֣ר עָשִׂ֗יתָ לְ⁠סִיחֹן֙ מֶ֣לֶךְ הָֽ⁠אֱמֹרִ֔י אֲשֶׁ֥ר יוֹשֵׁ֖ב בְּ⁠חֶשְׁבּֽוֹן׃","wa⁠yò̇֨ʼmer yĕhwá֤h ʼéla⁠y֙ ʼal-ţi̇yrá֣ʼ ʼòţ֔⁠wò ki֣̇y bĕ⁠yádĕ⁠ká֞ náţa֧ţi̇y ʼòţ֛⁠wò wĕ⁠ʼeţ-ká̇l-ʻaṁ֖⁠wò wĕ⁠ʼeţ-ʼarĕẕ֑⁠wò wĕ⁠ʻáşî֣yţá l̇֔⁠wò kȧ⁠ʼàşě֣r ʻáşî֗yţá lĕ⁠siyẖòn֙ me֣lekĕ háֽ⁠ʼèmòri֔y ʼàşě֥r ywòşé֖̌b bĕ̇⁠ẖeşĕ̌ḃֽwòn׃"],[3,3,"וַ⁠יִּתֵּן֩ יְהוָ֨ה אֱלֹהֵ֜י⁠נוּ בְּ⁠יָדֵ֗⁠נוּ גַּ֛ם אֶת־ע֥וֹג מֶֽלֶךְ־הַ⁠בָּשָׁ֖ן וְ⁠אֶת־כָּל־עַמּ֑⁠וֹ וַ⁠נַּכֵּ֕⁠הוּ עַד־בִּלְתִּ֥י הִשְׁאִֽיר־ל֖⁠וֹ שָׂרִֽיד׃","wa⁠yi̇ţé̇n֩ yĕhwá֨h ʼèlòhé֜y⁠nẇ bĕ̇⁠yádé֗⁠nẇ gȧ֛m ʼeţ-ʻ֥wòg meֽlekĕ-ha⁠bá̇şá֖̌n wĕ⁠ʼeţ-ká̇l-ʻaṁ֑⁠wò wa⁠nȧké̇֕⁠hẇ ʻad-bi̇lĕţi֥̇y hişĕ̌ʼiֽyr-l֖⁠wò şá̂riֽyd׃"],[3,4,"וַ⁠נִּלְכֹּ֤ד אֶת־כָּל־עָרָי⁠ו֙ בָּ⁠עֵ֣ת הַ⁠הִ֔וא לֹ֤א הָֽיְתָה֙ קִרְיָ֔ה אֲשֶׁ֥ר לֹא־לָקַ֖חְנוּ מֵֽ⁠אִתָּ֑⁠ם שִׁשִּׁ֥ים עִיר֙ כָּל־חֶ֣בֶל אַרְגֹּ֔ב מַמְלֶ֥כֶת ע֖וֹג בַּ⁠בָּשָֽׁן׃","wa⁠ni̇lĕkò֤̇d ʼeţ-ká̇l-ʻáráy⁠w֙ bá̇⁠ʻé֣ţ ha⁠hi֔wʼ lò֤ʼ háֽyĕţáh֙ qirĕyá֔h ʼàşě֥r lòʼ-láqa֖ẖĕnẇ méֽ⁠ʼiţá֑̇⁠m şǐşi֥̇̌ym ʻiyr֙ ká̇l-ẖe֣bel ʼarĕgò̇֔b mamĕle֥keţ ʻ֖wòg bȧ⁠bá̇şáֽ̌n׃"],[3,5,"כָּל־אֵ֜לֶּה עָרִ֧ים בְּצֻר֛וֹת חוֹמָ֥ה גְבֹהָ֖ה דְּלָתַ֣יִם וּ⁠בְרִ֑יחַ לְ⁠בַ֛ד מֵ⁠עָרֵ֥י הַ⁠פְּרָזִ֖י הַרְבֵּ֥ה מְאֹֽד׃","ká̇l-ʼé֜lėh ʻári֧ym bĕ̇ẕur֛wòţ ẖwòmá֥h gĕbòhá֖h dĕ̇láţa֣yim ẇ⁠bĕri֑yẖa lĕ⁠ba֛d mé⁠ʻáré֥y ha⁠pĕ̇rázi֖y harĕbé֥̇h mĕʼòֽd׃"],[3,6,"וַ⁠נַּחֲרֵ֣ם אוֹתָ֔⁠ם כַּ⁠אֲשֶׁ֣ר עָשִׂ֔ינוּ לְ⁠סִיחֹ֖ן מֶ֣לֶךְ חֶשְׁבּ֑וֹן הַחֲרֵם֙ כָּל־עִ֣יר מְתִ֔ם הַ⁠נָּשִׁ֖ים וְ⁠הַ⁠טָּֽף׃","wa⁠nȧẖàré֣m ʼwòţá֔⁠m kȧ⁠ʼàşě֣r ʻáşî֔ynẇ lĕ⁠siyẖò֖n me֣lekĕ ẖeşĕ̌ḃ֑wòn haẖàrém֙ ká̇l-ʻi֣yr mĕţi֔m ha⁠ná̇şǐ֖ym wĕ⁠ha⁠táֽ̇p׃"],[3,7,"וְ⁠כָל־הַ⁠בְּהֵמָ֛ה וּ⁠שְׁלַ֥ל הֶ⁠עָרִ֖ים בַּזּ֥וֹנוּ לָֽ⁠נוּ׃","wĕ⁠kál-ha⁠bĕ̇hémá֛h ẇ⁠şĕ̌la֥l he⁠ʻári֖ym bȧż֥wònẇ láֽ⁠nẇ׃"],[3,8,"וַ⁠נִּקַּ֞ח בָּ⁠עֵ֤ת הַ⁠הִוא֙ אֶת־הָ⁠אָ֔רֶץ מִ⁠יַּ֗ד שְׁנֵי֙ מַלְכֵ֣י הָ⁠אֱמֹרִ֔י אֲשֶׁ֖ר בְּ⁠עֵ֣בֶר הַ⁠יַּרְדֵּ֑ן מִ⁠נַּ֥חַל אַרְנֹ֖ן עַד־הַ֥ר חֶרְמֽוֹן׃","wa⁠ni̇qȧ֞ẖ bá̇⁠ʻé֤ţ ha⁠hiwʼ֙ ʼeţ-há⁠ʼá֔reẕ mi⁠yȧ֗d şĕ̌néy֙ malĕké֣y há⁠ʼèmòri֔y ʼàşě֖r bĕ̇⁠ʻé֣ber ha⁠yȧrĕdé֑̇n mi⁠nȧ֥ẖal ʼarĕnò֖n ʻad-ha֥r ẖerĕmֽwòn׃"],[3,9,"צִידֹנִ֛ים יִקְרְא֥וּ לְ⁠חֶרְמ֖וֹן שִׂרְיֹ֑ן וְ⁠הָ֣⁠אֱמֹרִ֔י יִקְרְאוּ־ל֖⁠וֹ שְׂנִֽיר׃","ẕiydòni֛ym yiqĕrĕʼ֥ẇ lĕ⁠ẖerĕm֖wòn şîrĕyò֑n wĕ⁠há֣⁠ʼèmòri֔y yiqĕrĕʼẇ-l֖⁠wò şĕ̂niֽyr׃"],[3,10,"כֹּ֣ל ׀ עָרֵ֣י הַ⁠מִּישֹׁ֗ר וְ⁠כָל־הַ⁠גִּלְעָד֙ וְ⁠כָל־הַ⁠בָּשָׁ֔ן עַד־סַלְכָ֖ה וְ⁠אֶדְרֶ֑עִי עָרֵ֛י מַמְלֶ֥כֶת ע֖וֹג בַּ⁠בָּשָֽׁן׃","kò֣̇l ׀ ʻáré֣y ha⁠mi̇yşò̌֗r wĕ⁠kál-ha⁠gi̇lĕʻád֙ wĕ⁠kál-ha⁠bá̇şá̌֔n ʻad-salĕká֖h wĕ⁠ʼedĕre֑ʻiy ʻáré֛y mamĕle֥keţ ʻ֖wòg bȧ⁠bá̇şáֽ̌n׃"],[3,11,"כִּ֣י רַק־ע֞וֹג מֶ֣לֶךְ הַ⁠בָּשָׁ֗ן נִשְׁאַר֮ מִ⁠יֶּ֣תֶר הָ⁠רְפָאִים֒ הִנֵּ֤ה עַרְשׂ⁠וֹ֙ עֶ֣רֶשׂ בַּרְזֶ֔ל הֲ⁠לֹ֣ה הִ֔וא בְּ⁠רַבַּ֖ת בְּנֵ֣י עַמּ֑וֹן תֵּ֧שַׁע אַמּ֣וֹת אָרְכָּ֗⁠הּ וְ⁠אַרְבַּ֥ע אַמּ֛וֹת רָחְבָּ֖⁠הּ בְּ⁠אַמַּת־אִֽישׁ׃","ki֣̇y raq-ʻ֞wòg me֣lekĕ ha⁠bá̇şá̌֗n nişĕ̌ʼar֮ mi⁠yė֣ţer há⁠rĕpáʼiym֒ hiné֤̇h ʻarĕş̂⁠wò֙ ʻe֣reş̂ bȧrĕze֔l hà⁠lò֣h hi֔wʼ bĕ̇⁠rabȧ֖ţ bĕ̇né֣y ʻaṁ֑wòn ţé֧̇şǎʻ ʼaṁ֣wòţ ʼárĕká̇֗⁠ḣ wĕ⁠ʼarĕbȧ֥ʻ ʼaṁ֛wòţ ráẖĕbá֖̇⁠ḣ bĕ̇⁠ʼamȧţ-ʼiֽyş̌׃"],[3,12,"וְ⁠אֶת־הָ⁠אָ֧רֶץ הַ⁠זֹּ֛את יָרַ֖שְׁנוּ בָּ⁠עֵ֣ת הַ⁠הִ֑וא מֵ⁠עֲרֹעֵ֞ר אֲשֶׁר־עַל־נַ֣חַל אַרְנֹ֗ן וַ⁠חֲצִ֤י הַֽר־הַ⁠גִּלְעָד֙ וְ⁠עָרָ֔י⁠ו נָתַ֕תִּי לָ⁠רֻֽאוּבֵנִ֖י וְ⁠לַ⁠גָּדִֽי׃","wĕ⁠ʼeţ-há⁠ʼá֧reẕ ha⁠zò֛̇ʼţ yára֖şĕ̌nẇ bá̇⁠ʻé֣ţ ha⁠hi֑wʼ mé⁠ʻàròʻé֞r ʼàşěr-ʻal-na֣ẖal ʼarĕnò֗n wa⁠ẖàẕi֤y haֽr-ha⁠gi̇lĕʻád֙ wĕ⁠ʻárá֔y⁠w náţa֕ţi̇y lá⁠ruֽʼẇbéni֖y wĕ⁠la⁠gá̇diֽy׃"],[3,13,"וְ⁠יֶ֨תֶר הַ⁠גִּלְעָ֤ד וְ⁠כָל־הַ⁠בָּשָׁן֙ מַמְלֶ֣כֶת ע֔וֹג נָתַ֕תִּי לַ⁠חֲצִ֖י שֵׁ֣בֶט הַֽ⁠מְנַשֶּׁ֑ה כֹּ֣ל חֶ֤בֶל הָֽ⁠אַרְגֹּב֙ לְ⁠כָל־הַ⁠בָּשָׁ֔ן הַ⁠ה֥וּא יִקָּרֵ֖א אֶ֥רֶץ רְפָאִֽים׃","wĕ⁠ye֨ţer ha⁠gi̇lĕʻá֤d wĕ⁠kál-ha⁠bá̇şá̌n֙ mamĕle֣keţ ʻ֔wòg náţa֕ţi̇y la⁠ẖàẕi֖y şé֣̌bet haֽ⁠mĕnaşė֑̌h kò֣̇l ẖe֤bel háֽ⁠ʼarĕgò̇b֙ lĕ⁠kál-ha⁠bá̇şá̌֔n ha⁠h֥ẇʼ yiqá̇ré֖ʼ ʼe֥reẕ rĕpáʼiֽym׃"],[3,14,"יָאִ֣יר בֶּן־מְנַשֶּׁ֗ה לָקַח֙ אֶת־כָּל־חֶ֣בֶל אַרְגֹּ֔ב עַד־גְּב֥וּל הַ⁠גְּשׁוּרִ֖י וְ⁠הַ⁠מַּֽעֲכָתִ֑י וַ⁠יִּקְרָא֩ אֹתָ֨⁠ם עַל־שְׁמ֤⁠וֹ אֶת־הַ⁠בָּשָׁן֙ חַוֺּ֣ת יָאִ֔יר עַ֖ד הַ⁠יּ֥וֹם הַ⁠זֶּֽה׃","yáʼi֣yr bėn-mĕnaşė̌֗h láqaẖ֙ ʼeţ-ká̇l-ẖe֣bel ʼarĕgò̇֔b ʻad-gĕ̇b֥ẇl ha⁠gĕ̇ş̌ẇri֖y wĕ⁠ha⁠mȧֽʻàkáţi֑y wa⁠yi̇qĕráʼ֩ ʼòţá֨⁠m ʻal-şĕ̌m֤⁠wò ʼeţ-ha⁠bá̇şá̌n֙ ẖaẇֺ֣ţ yáʼi֔yr ʻa֖d ha⁠ẏ֥wòm ha⁠zėֽh׃"],[3,15,"וּ⁠לְ⁠מָכִ֖יר נָתַ֥תִּי אֶת־הַ⁠גִּלְעָֽד׃","ẇ⁠lĕ⁠máki֖yr náţa֥ţi̇y ʼeţ-ha⁠gi̇lĕʻáֽd׃"],[3,16,"וְ⁠לָ⁠רֻאוּבֵנִ֨י וְ⁠לַ⁠גָּדִ֜י נָתַ֤תִּי מִן־הַ⁠גִּלְעָד֙ וְ⁠עַד־נַ֣חַל אַרְנֹ֔ן תּ֥וֹךְ הַ⁠נַּ֖חַל וּ⁠גְבֻ֑ל וְ⁠עַד֙ יַבֹּ֣ק הַ⁠נַּ֔חַל גְּב֖וּל בְּנֵ֥י עַמּֽוֹן׃","wĕ⁠lá⁠ruʼẇbéni֨y wĕ⁠la⁠gá̇di֜y náţa֤ţi̇y min-ha⁠gi̇lĕʻád֙ wĕ⁠ʻad-na֣ẖal ʼarĕnò֔n ţ֥̇wòkĕ ha⁠nȧ֖ẖal ẇ⁠gĕbu֑l wĕ⁠ʻad֙ yabò֣̇q ha⁠nȧ֔ẖal gĕ̇b֖ẇl bĕ̇né֥y ʻaṁֽwòn׃"],[3,17,"וְ⁠הָֽ⁠עֲרָבָ֖ה וְ⁠הַ⁠יַּרְדֵּ֣ן וּ⁠גְבֻ֑ל מִ⁠כִּנֶּ֗רֶת וְ⁠עַ֨ד יָ֤ם הָֽ⁠עֲרָבָה֙ יָ֣ם הַ⁠מֶּ֔לַח תַּ֛חַת אַשְׁדֹּ֥ת הַ⁠פִּסְגָּ֖ה מִזְרָֽחָ⁠ה׃","wĕ⁠háֽ⁠ʻàrábá֖h wĕ⁠ha⁠yȧrĕdé֣̇n ẇ⁠gĕbu֑l mi⁠ki̇nė֗reţ wĕ⁠ʻa֨d yá֤m háֽ⁠ʻàrábáh֙ yá֣m ha⁠mė֔laẖ ţȧ֛ẖaţ ʼaşĕ̌dò֥̇ţ ha⁠pi̇sĕgá֖̇h mizĕráֽẖá⁠h׃"],[3,18,"וָ⁠אֲצַ֣ו אֶתְ⁠כֶ֔ם בָּ⁠עֵ֥ת הַ⁠הִ֖וא לֵ⁠אמֹ֑ר יְהוָ֣ה אֱלֹהֵי⁠כֶ֗ם נָתַ֨ן לָ⁠כֶ֜ם אֶת־הָ⁠אָ֤רֶץ הַ⁠זֹּאת֙ לְ⁠רִשְׁתָּ֔⁠הּ חֲלוּצִ֣ים תַּֽעַבְר֗וּ לִ⁠פְנֵ֛י אֲחֵי⁠כֶ֥ם בְּנֵֽי־יִשְׂרָאֵ֖ל כָּל־בְּנֵי־חָֽיִל׃","wá⁠ʼàẕa֣w ʼeţĕ⁠ke֔m bá̇⁠ʻé֥ţ ha⁠hi֖wʼ lé⁠ʼmò֑r yĕhwá֣h ʼèlòhéy⁠ke֗m náţa֨n lá⁠ke֜m ʼeţ-há⁠ʼá֤reẕ ha⁠zò̇ʼţ֙ lĕ⁠rişĕ̌ţá̇֔⁠ḣ ẖàlẇẕi֣ym ţȧֽʻabĕr֗ẇ li⁠pĕné֛y ʼàẖéy⁠ke֥m bĕ̇néֽy-yişĕ̂ráʼé֖l ká̇l-bĕ̇néy-ẖáֽyil׃"],[3,19,"רַ֠ק נְשֵׁי⁠כֶ֣ם וְ⁠טַפְּ⁠כֶם֮ וּ⁠מִקְנֵ⁠כֶם֒ יָדַ֕עְתִּי כִּֽי־מִקְנֶ֥ה רַ֖ב לָ⁠כֶ֑ם יֵֽשְׁבוּ֙ בְּ⁠עָ֣רֵי⁠כֶ֔ם אֲשֶׁ֥ר נָתַ֖תִּי לָ⁠כֶֽם׃","ra֠q nĕşé̌y⁠ke֣m wĕ⁠tapĕ̇⁠kem֮ ẇ⁠miqĕné⁠kem֒ yáda֕ʻĕţi̇y kiֽ̇y-miqĕne֥h ra֖b lá⁠ke֑m yéֽşĕ̌bẇ֙ bĕ̇⁠ʻá֣réy⁠ke֔m ʼàşě֥r náţa֖ţi̇y lá⁠keֽm׃"],[3,20,"עַ֠ד אֲשֶׁר־יָנִ֨יחַ יְהוָ֥ה ׀ לַֽ⁠אֲחֵי⁠כֶם֮ כָּ⁠כֶם֒ וְ⁠יָרְשׁ֣וּ גַם־הֵ֔ם אֶת־הָ⁠אָ֕רֶץ אֲשֶׁ֨ר יְהוָ֧ה אֱלֹהֵי⁠כֶ֛ם נֹתֵ֥ן לָ⁠הֶ֖ם בְּ⁠עֵ֣בֶר הַ⁠יַּרְדֵּ֑ן וְ⁠שַׁבְתֶּ֗ם אִ֚ישׁ לִֽ⁠ירֻשָּׁת֔⁠וֹ אֲשֶׁ֥ר נָתַ֖תִּי לָ⁠כֶֽם׃","ʻa֠d ʼàşěr-yáni֨yẖa yĕhwá֥h ׀ laֽ⁠ʼàẖéy⁠kem֮ ká̇⁠kem֒ wĕ⁠yárĕş֣̌ẇ gam-hé֔m ʼeţ-há⁠ʼá֕reẕ ʼàşě֨r yĕhwá֧h ʼèlòhéy⁠ke֛m nòţé֥n lá⁠he֖m bĕ̇⁠ʻé֣ber ha⁠yȧrĕdé֑̇n wĕ⁠şǎbĕţė֗m ʼi֚yş̌ liֽ⁠yruşá̇̌ţ֔⁠wò ʼàşě֥r náţa֖ţi̇y lá⁠keֽm׃"],[3,21,"וְ⁠אֶת־יְהוֹשׁ֣וּעַ צִוֵּ֔יתִי בָּ⁠עֵ֥ת הַ⁠הִ֖וא לֵ⁠אמֹ֑ר עֵינֶ֣י⁠ךָ הָ⁠רֹאֹ֗ת אֵת֩ כָּל־אֲשֶׁ֨ר עָשָׂ֜ה יְהוָ֤ה אֱלֹהֵי⁠כֶם֙ לִ⁠שְׁנֵי֙ הַ⁠מְּלָכִ֣ים הָ⁠אֵ֔לֶּה כֵּֽן־יַעֲשֶׂ֤ה יְהוָה֙ לְ⁠כָל־הַ⁠מַּמְלָכ֔וֹת אֲשֶׁ֥ר אַתָּ֖ה עֹבֵ֥ר שָֽׁמָּ⁠ה׃","wĕ⁠ʼeţ-yĕhwòş֣̌ẇʻa ẕiwé̇֔yţiy bá̇⁠ʻé֥ţ ha⁠hi֖wʼ lé⁠ʼmò֑r ʻéyne֣y⁠ká há⁠ròʼò֗ţ ʼéţ֩ ká̇l-ʼàşě֨r ʻáşá̂֜h yĕhwá֤h ʼèlòhéy⁠kem֙ li⁠şĕ̌néy֙ ha⁠mĕ̇láki֣ym há⁠ʼé֔lėh kéֽ̇n-yaʻàşê֤h yĕhwáh֙ lĕ⁠kál-ha⁠mȧmĕlák֔wòţ ʼàşě֥r ʼaţá֖̇h ʻòbé֥r şáֽ̌má̇⁠h׃"],[3,22,"לֹ֖א תְִּירָא֑וּ⁠ם כִּ֚י יְהוָ֣ה אֱלֹֽהֵי⁠כֶ֔ם ה֖וּא הַ⁠נִּלְחָ֥ם לָ⁠כֶֽם׃ס","lò֖ʼ ţĕi̇yráʼ֑ẇ⁠m ki֚̇y yĕhwá֣h ʼèlòֽhéy⁠ke֔m h֖ẇʼ ha⁠ni̇lĕẖá֥m lá⁠keֽm׃s"],[3,23,"וָ⁠אֶתְחַנַּ֖ן אֶל־יְהוָ֑ה בָּ⁠עֵ֥ת הַ⁠הִ֖וא לֵ⁠אמֹֽר׃","wá⁠ʼeţĕẖanȧ֖n ʼel-yĕhwá֑h bá̇⁠ʻé֥ţ ha⁠hi֖wʼ lé⁠ʼmòֽr׃"],[3,24,"אֲדֹנָ֣⁠י יְהוִ֗ה אַתָּ֤ה הַֽחִלּ֨וֹתָ֙ לְ⁠הַרְא֣וֹת אֶֽת־עַבְדְּ⁠ךָ֔ אֶ֨ת־גָּדְלְ⁠ךָ֔ וְ⁠אֶת־יָדְ⁠ךָ֖ הַ⁠חֲזָקָ֑ה אֲשֶׁ֤ר מִי־אֵל֙ בַּ⁠שָּׁמַ֣יִם וּ⁠בָ⁠אָ֔רֶץ אֲשֶׁר־יַעֲשֶׂ֥ה כְ⁠מַעֲשֶׂ֖י⁠ךָ וְ⁠כִ⁠גְבוּרֹתֶֽ⁠ךָ׃","ʼàdòná֣⁠y yĕhwi֗h ʼaţá֤̇h haֽẖil̇֨wòţá֙ lĕ⁠harĕʼ֣wòţ ʼeֽţ-ʻabĕdĕ̇⁠ká֔ ʼe֨ţ-gá̇dĕlĕ⁠ká֔ wĕ⁠ʼeţ-yádĕ⁠ká֖ ha⁠ẖàzáqá֑h ʼàşě֤r miy-ʼél֙ bȧ⁠şá̇̌ma֣yim ẇ⁠bá⁠ʼá֔reẕ ʼàşěr-yaʻàşê֥h kĕ⁠maʻàşê֖y⁠ká wĕ⁠ki⁠gĕbẇròţeֽ⁠ká׃"],[3,25,"אֶעְבְּרָה־נָּ֗א וְ⁠אֶרְאֶה֙ אֶת־הָ⁠אָ֣רֶץ הַ⁠טּוֹבָ֔ה אֲשֶׁ֖ר בְּ⁠עֵ֣בֶר הַ⁠יַּרְדֵּ֑ן הָ⁠הָ֥ר הַ⁠טּ֛וֹב הַ⁠זֶּ֖ה וְ⁠הַ⁠לְּבָנֽוֹן׃","ʼeʻĕbĕ̇ráh-ná̇֗ʼ wĕ⁠ʼerĕʼeh֙ ʼeţ-há⁠ʼá֣reẕ ha⁠ṫwòbá֔h ʼàşě֖r bĕ̇⁠ʻé֣ber ha⁠yȧrĕdé֑̇n há⁠há֥r ha⁠ṫ֛wòb ha⁠zė֖h wĕ⁠ha⁠lĕ̇bánֽwòn׃"],[3,26,"וַ⁠יִּתְעַבֵּ֨ר יְהוָ֥ה בִּ⁠י֙ לְמַ֣עַנְ⁠כֶ֔ם וְ⁠לֹ֥א שָׁמַ֖ע אֵלָ֑⁠י וַ⁠יֹּ֨אמֶר יְהוָ֤ה אֵלַ⁠י֙ רַב־לָ֔⁠ךְ אַל־תּ֗וֹסֶף דַּבֵּ֥ר אֵלַ֛⁠י ע֖וֹד בַּ⁠דָּבָ֥ר הַ⁠זֶּֽה׃","wa⁠yi̇ţĕʻabé̇֨r yĕhwá֥h bi̇⁠y֙ lĕma֣ʻanĕ⁠ke֔m wĕ⁠lò֥ʼ şá̌ma֖ʻ ʼélá֑⁠y wa⁠yò̇֨ʼmer yĕhwá֤h ʼéla⁠y֙ rab-lá֔⁠kĕ ʼal-ţ̇֗wòsep dȧbé֥̇r ʼéla֛⁠y ʻ֖wòd bȧ⁠dá̇bá֥r ha⁠zėֽh׃"],[3,27,"עֲלֵ֣ה ׀ רֹ֣אשׁ הַ⁠פִּסְגָּ֗ה וְ⁠שָׂ֥א עֵינֶ֛י⁠ךָ יָ֧מָּ⁠ה וְ⁠צָפֹ֛נָ⁠ה וְ⁠תֵימָ֥נָ⁠ה וּ⁠מִזְרָ֖חָ⁠ה וּ⁠רְאֵ֣ה בְ⁠עֵינֶ֑י⁠ךָ כִּי־לֹ֥א תַעֲבֹ֖ר אֶת־הַ⁠יַּרְדֵּ֥ן הַ⁠זֶּֽה׃","ʻàlé֣h ׀ rò֣ʼş̌ ha⁠pi̇sĕgá̇֗h wĕ⁠şá֥̂ʼ ʻéyne֛y⁠ká yá֧má̇⁠h wĕ⁠ẕápò֛ná⁠h wĕ⁠ţéymá֥ná⁠h ẇ⁠mizĕrá֖ẖá⁠h ẇ⁠rĕʼé֣h bĕ⁠ʻéyne֑y⁠ká ki̇y-lò֥ʼ ţaʻàbò֖r ʼeţ-ha⁠yȧrĕdé֥̇n ha⁠zėֽh׃"],[3,28,"וְ⁠צַ֥ו אֶת־יְהוֹשֻׁ֖עַ וְ⁠חַזְּקֵ֣⁠הוּ וְ⁠אַמְּצֵ֑⁠הוּ כִּי־ה֣וּא יַעֲבֹ֗ר לִ⁠פְנֵי֙ הָ⁠עָ֣ם הַ⁠זֶּ֔ה וְ⁠הוּא֙ יַנְחִ֣יל אוֹתָ֔⁠ם אֶת־הָ⁠אָ֖רֶץ אֲשֶׁ֥ר תִּרְאֶֽה׃","wĕ⁠ẕa֥w ʼeţ-yĕhwòşǔ֖ʻa wĕ⁠ẖazĕ̇qé֣⁠hẇ wĕ⁠ʼamĕ̇ẕé֑⁠hẇ ki̇y-h֣ẇʼ yaʻàbò֗r li⁠pĕnéy֙ há⁠ʻá֣m ha⁠zė֔h wĕ⁠hẇʼ֙ yanĕẖi֣yl ʼwòţá֔⁠m ʼeţ-há⁠ʼá֖reẕ ʼàşě֥r ţi̇rĕʼeֽh׃"],[3,29,"וַ⁠נֵּ֣שֶׁב בַּ⁠גָּ֔יְא מ֖וּל בֵּ֥ית פְּעֽוֹר׃פ","wa⁠né֣̇şěb bȧ⁠gá̇֔yĕʼ m֖ẇl bé֥̇yţ pĕ̇ʻֽwòr׃p"],[4,1,"וְ⁠עַתָּ֣ה יִשְׂרָאֵ֗ל שְׁמַ֤ע אֶל־הַֽ⁠חֻקִּים֙ וְ⁠אֶל־הַ⁠מִּשְׁפָּטִ֔ים אֲשֶׁ֧ר אָֽנֹכִ֛י מְלַמֵּ֥ד אֶתְ⁠כֶ֖ם לַ⁠עֲשׂ֑וֹת לְמַ֣עַן תִּֽחְי֗וּ וּ⁠בָאתֶם֙ וִֽ⁠ירִשְׁתֶּ֣ם אֶת־הָ⁠אָ֔רֶץ אֲשֶׁ֧ר יְהוָ֛ה אֱלֹהֵ֥י אֲבֹתֵי⁠כֶ֖ם נֹתֵ֥ן לָ⁠כֶֽם׃","wĕ⁠ʻaţá֣̇h yişĕ̂ráʼé֗l şĕ̌ma֤ʻ ʼel-haֽ⁠ẖuqi̇ym֙ wĕ⁠ʼel-ha⁠mi̇şĕ̌pá̇ti֔ym ʼàşě֧r ʼáֽnòki֛y mĕlamé֥̇d ʼeţĕ⁠ke֖m la⁠ʻàş֑̂wòţ lĕma֣ʻan ţiֽ̇ẖĕy֗ẇ ẇ⁠báʼţem֙ wiֽ⁠yrişĕ̌ţė֣m ʼeţ-há⁠ʼá֔reẕ ʼàşě֧r yĕhwá֛h ʼèlòhé֥y ʼàbòţéy⁠ke֖m nòţé֥n lá⁠keֽm׃"],[4,2,"לֹ֣א תֹסִ֗פוּ עַל־הַ⁠דָּבָר֙ אֲשֶׁ֤ר אָנֹכִי֙ מְצַוֶּ֣ה אֶתְ⁠כֶ֔ם וְ⁠לֹ֥א תִגְרְע֖וּ מִמֶּ֑⁠נּוּ לִ⁠שְׁמֹ֗ר אֶת־מִצְוֺת֙ יְהוָ֣ה אֱלֹֽהֵי⁠כֶ֔ם אֲשֶׁ֥ר אָנֹכִ֖י מְצַוֶּ֥ה אֶתְ⁠כֶֽם׃","lò֣ʼ ţòsi֗pẇ ʻal-ha⁠dá̇bár֙ ʼàşě֤r ʼánòkiy֙ mĕẕawė֣h ʼeţĕ⁠ke֔m wĕ⁠lò֥ʼ ţigĕrĕʻ֖ẇ mimė֑⁠ṅẇ li⁠şĕ̌mò֗r ʼeţ-miẕĕwֺţ֙ yĕhwá֣h ʼèlòֽhéy⁠ke֔m ʼàşě֥r ʼánòki֖y mĕẕawė֥h ʼeţĕ⁠keֽm׃"],[4,3,"עֵֽינֵי⁠כֶם֙ הָֽ⁠רֹאֹ֔ת אֵ֛ת אֲשֶׁר־עָשָׂ֥ה יְהוָ֖ה בְּ⁠בַ֣עַל פְּע֑וֹר כִּ֣י כָל־הָ⁠אִ֗ישׁ אֲשֶׁ֤ר הָלַךְ֙ אַחֲרֵ֣י בַֽעַל־פְּע֔וֹר הִשְׁמִיד֛⁠וֹ יְהוָ֥ה אֱלֹהֶ֖י⁠ךָ מִ⁠קִּרְבֶּֽ⁠ךָ׃","ʻéֽynéy⁠kem֙ háֽ⁠ròʼò֔ţ ʼé֛ţ ʼàşěr-ʻáşá֥̂h yĕhwá֖h bĕ̇⁠ba֣ʻal pĕ̇ʻ֑wòr ki֣̇y kál-há⁠ʼi֗yş̌ ʼàşě֤r hálakĕ֙ ʼaẖàré֣y baֽʻal-pĕ̇ʻ֔wòr hişĕ̌miyd֛⁠wò yĕhwá֥h ʼèlòhe֖y⁠ká mi⁠qi̇rĕbėֽ⁠ká׃"],[4,4,"וְ⁠אַתֶּם֙ הַ⁠דְּבֵקִ֔ים בַּ⁠יהוָ֖ה אֱלֹהֵי⁠כֶ֑ם חַיִּ֥ים כֻּלְּ⁠כֶ֖ם הַ⁠יּֽוֹם׃","wĕ⁠ʼaţėm֙ ha⁠dĕ̇béqi֔ym bȧ⁠yhwá֖h ʼèlòhéy⁠ke֑m ẖayi֥̇ym ku̇lĕ̇⁠ke֖m ha⁠ẏֽwòm׃"],[4,5,"רְאֵ֣ה ׀ לִמַּ֣דְתִּי אֶתְ⁠כֶ֗ם חֻקִּים֙ וּ⁠מִשְׁפָּטִ֔ים כַּ⁠אֲשֶׁ֥ר צִוַּ֖⁠נִי יְהוָ֣ה אֱלֹהָ֑⁠י לַ⁠עֲשׂ֣וֹת כֵּ֔ן בְּ⁠קֶ֣רֶב הָ⁠אָ֔רֶץ אֲשֶׁ֥ר אַתֶּ֛ם בָּאִ֥ים שָׁ֖מָּ⁠ה לְ⁠רִשְׁתָּֽ⁠הּ׃","rĕʼé֣h ׀ limȧ֣dĕţi̇y ʼeţĕ⁠ke֗m ẖuqi̇ym֙ ẇ⁠mişĕ̌pá̇ti֔ym kȧ⁠ʼàşě֥r ẕiwȧ֖⁠niy yĕhwá֣h ʼèlòhá֑⁠y la⁠ʻàş֣̂wòţ ké̇֔n bĕ̇⁠qe֣reb há⁠ʼá֔reẕ ʼàşě֥r ʼaţė֛m bá̇ʼi֥ym şá֖̌má̇⁠h lĕ⁠rişĕ̌ţáֽ̇⁠ḣ׃"],[4,6,"וּ⁠שְׁמַרְתֶּם֮ וַ⁠עֲשִׂיתֶם֒ כִּ֣י הִ֤וא חָכְמַתְ⁠כֶם֙ וּ⁠בִ֣ינַתְ⁠כֶ֔ם לְ⁠עֵינֵ֖י הָ⁠עַמִּ֑ים אֲשֶׁ֣ר יִשְׁמְע֗וּ⁠ן אֵ֚ת כָּל־הַ⁠חֻקִּ֣ים הָ⁠אֵ֔לֶּה וְ⁠אָמְר֗וּ רַ֚ק עַם־חָכָ֣ם וְ⁠נָב֔וֹן הַ⁠גּ֥וֹי הַ⁠גָּד֖וֹל הַ⁠זֶּֽה׃","ẇ⁠şĕ̌marĕţėm֮ wa⁠ʻàşîyţem֒ ki֣̇y hi֤wʼ ẖákĕmaţĕ⁠kem֙ ẇ⁠bi֣ynaţĕ⁠ke֔m lĕ⁠ʻéyné֖y há⁠ʻami֑̇ym ʼàşě֣r yişĕ̌mĕʻ֗ẇ⁠n ʼé֚ţ ká̇l-ha⁠ẖuqi֣̇ym há⁠ʼé֔lėh wĕ⁠ʼámĕr֗ẇ ra֚q ʻam-ẖáká֣m wĕ⁠náb֔wòn ha⁠ġ֥wòy ha⁠gá̇d֖wòl ha⁠zėֽh׃"],[4,7,"כִּ֚י מִי־ג֣וֹי גָּד֔וֹל אֲשֶׁר־ל֥⁠וֹ אֱלֹהִ֖ים קְרֹבִ֣ים אֵלָ֑י⁠ו כַּ⁠יהוָ֣ה אֱלֹהֵ֔י⁠נוּ בְּ⁠כָּל־קָרְאֵ֖⁠נוּ אֵלָֽי⁠ו׃","ki֚̇y miy-g֣wòy gá̇d֔wòl ʼàşěr-l֥⁠wò ʼèlòhi֖ym qĕròbi֣ym ʼélá֑y⁠w kȧ⁠yhwá֣h ʼèlòhé֔y⁠nẇ bĕ̇⁠ká̇l-qárĕʼé֖⁠nẇ ʼéláֽy⁠w׃"],[4,8,"וּ⁠מִי֙ גּ֣וֹי גָּד֔וֹל אֲשֶׁר־ל֛⁠וֹ חֻקִּ֥ים וּ⁠מִשְׁפָּטִ֖ים צַדִּיקִ֑ם כְּ⁠כֹל֙ הַ⁠תּוֹרָ֣ה הַ⁠זֹּ֔את אֲשֶׁ֧ר אָנֹכִ֛י נֹתֵ֥ן לִ⁠פְנֵי⁠כֶ֖ם הַ⁠יּֽוֹם׃","ẇ⁠miy֙ ġ֣wòy gá̇d֔wòl ʼàşěr-l֛⁠wò ẖuqi֥̇ym ẇ⁠mişĕ̌pá̇ti֖ym ẕadi̇yqi֑m kĕ̇⁠kòl֙ ha⁠ţ̇wòrá֣h ha⁠zò̇֔ʼţ ʼàşě֧r ʼánòki֛y nòţé֥n li⁠pĕnéy⁠ke֖m ha⁠ẏֽwòm׃"],[4,9,"רַ֡ק הִשָּׁ֣מֶר לְ⁠ךָ֩ וּ⁠שְׁמֹ֨ר נַפְשְׁ⁠ךָ֜ מְאֹ֗ד פֶּן־תִּשְׁכַּ֨ח אֶת־הַ⁠דְּבָרִ֜ים אֲשֶׁר־רָא֣וּ עֵינֶ֗י⁠ךָ וּ⁠פֶן־יָס֨וּרוּ֙ מִ⁠לְּבָ֣בְ⁠ךָ֔ כֹּ֖ל יְמֵ֣י חַיֶּ֑י⁠ךָ וְ⁠הוֹדַעְתָּ֥⁠ם לְ⁠בָנֶ֖י⁠ךָ וְ⁠לִ⁠בְנֵ֥י בָנֶֽי⁠ךָ׃","ra֡q hişá֣̇̌mer lĕ⁠ká֩ ẇ⁠şĕ̌mò֨r napĕşĕ̌⁠ká֜ mĕʼò֗d pėn-ţi̇şĕ̌kȧ֨ẖ ʼeţ-ha⁠dĕ̇bári֜ym ʼàşěr-ráʼ֣ẇ ʻéyne֗y⁠ká ẇ⁠pen-yás֨ẇrẇ֙ mi⁠lĕ̇bá֣bĕ⁠ká֔ kò֖̇l yĕmé֣y ẖayė֑y⁠ká wĕ⁠hwòdaʻĕţá֥̇⁠m lĕ⁠báne֖y⁠ká wĕ⁠li⁠bĕné֥y báneֽy⁠ká׃"],[4,10,"י֗וֹם אֲשֶׁ֨ר עָמַ֜דְתָּ לִ⁠פְנֵ֨י יְהוָ֣ה אֱלֹהֶי⁠ךָ֮ בְּ⁠חֹרֵב֒ בֶּ⁠אֱמֹ֨ר יְהוָ֜ה אֵלַ֗⁠י הַקְהֶל־לִ⁠י֙ אֶת־הָ⁠עָ֔ם וְ⁠אַשְׁמִעֵ֖⁠ם אֶת־דְּבָרָ֑⁠י אֲשֶׁ֨ר יִלְמְד֜וּ⁠ן לְ⁠יִרְאָ֣ה אֹתִ֗⁠י כָּל־הַ⁠יָּמִים֙ אֲשֶׁ֨ר הֵ֤ם חַיִּים֙ עַל־הָ֣⁠אֲדָמָ֔ה וְ⁠אֶת־בְּנֵי⁠הֶ֖ם יְלַמֵּדֽוּ⁠ן׃","y֗wòm ʼàşě֨r ʻáma֜dĕţá̇ li⁠pĕné֨y yĕhwá֣h ʼèlòhey⁠ká֮ bĕ̇⁠ẖòréb֒ bė⁠ʼèmò֨r yĕhwá֜h ʼéla֗⁠y haqĕhel-li⁠y֙ ʼeţ-há⁠ʻá֔m wĕ⁠ʼaşĕ̌miʻé֖⁠m ʼeţ-dĕ̇bárá֑⁠y ʼàşě֨r yilĕmĕd֜ẇ⁠n lĕ⁠yirĕʼá֣h ʼòţi֗⁠y ká̇l-ha⁠yá̇miym֙ ʼàşě֨r hé֤m ẖayi̇ym֙ ʻal-há֣⁠ʼàdámá֔h wĕ⁠ʼeţ-bĕ̇néy⁠he֖m yĕlamé̇dֽẇ⁠n׃"],[4,11,"וַ⁠תִּקְרְב֥וּ⁠ן וַ⁠תַּֽעַמְד֖וּ⁠ן תַּ֣חַת הָ⁠הָ֑ר וְ⁠הָ⁠הָ֞ר בֹּעֵ֤ר בָּ⁠אֵשׁ֙ עַד־לֵ֣ב הַ⁠שָּׁמַ֔יִם חֹ֖שֶׁךְ עָנָ֥ן וַ⁠עֲרָפֶֽל׃","wa⁠ţi̇qĕrĕb֥ẇ⁠n wa⁠ţȧֽʻamĕd֖ẇ⁠n ţȧ֣ẖaţ há⁠há֑r wĕ⁠há⁠há֞r bò̇ʻé֤r bá̇⁠ʼéş̌֙ ʻad-lé֣b ha⁠şá̇̌ma֔yim ẖò֖şěkĕ ʻáná֥n wa⁠ʻàrápeֽl׃"],[4,12,"וַ⁠יְדַבֵּ֧ר יְהוָ֛ה אֲלֵי⁠כֶ֖ם מִ⁠תּ֣וֹךְ הָ⁠אֵ֑שׁ ק֤וֹל דְּבָרִים֙ אַתֶּ֣ם שֹׁמְעִ֔ים וּ⁠תְמוּנָ֛ה אֵינְ⁠כֶ֥ם רֹאִ֖ים זוּלָתִ֥י קֽוֹל׃","wa⁠yĕdabé֧̇r yĕhwá֛h ʼàléy⁠ke֖m mi⁠ţ֣̇wòkĕ há⁠ʼé֑ş̌ q֤wòl dĕ̇báriym֙ ʼaţė֣m şò̌mĕʻi֔ym ẇ⁠ţĕmẇná֛h ʼéynĕ⁠ke֥m ròʼi֖ym zẇláţi֥y qֽwòl׃"],[4,13,"וַ⁠יַּגֵּ֨ד לָ⁠כֶ֜ם אֶת־בְּרִית֗⁠וֹ אֲשֶׁ֨ר צִוָּ֤ה אֶתְ⁠כֶם֙ לַ⁠עֲשׂ֔וֹת עֲשֶׂ֖רֶת הַ⁠דְּבָרִ֑ים וַֽ⁠יִּכְתְּבֵ֔⁠ם עַל־שְׁנֵ֖י לֻח֥וֹת אֲבָנִֽים׃","wa⁠yȧgé̇֨d lá⁠ke֜m ʼeţ-bĕ̇riyţ֗⁠wò ʼàşě֨r ẕiwá֤̇h ʼeţĕ⁠kem֙ la⁠ʻàş̂֔wòţ ʻàşê֖reţ ha⁠dĕ̇bári֑ym waֽ⁠yi̇kĕţĕ̇bé֔⁠m ʻal-şĕ̌né֖y luẖ֥wòţ ʼàbániֽym׃"],[4,14,"וְ⁠אֹתִ֞⁠י צִוָּ֤ה יְהוָה֙ בָּ⁠עֵ֣ת הַ⁠הִ֔וא לְ⁠לַמֵּ֣ד אֶתְ⁠כֶ֔ם חֻקִּ֖ים וּ⁠מִשְׁפָּטִ֑ים לַ⁠עֲשֹׂתְ⁠כֶ֣ם אֹתָ֔⁠ם בָּ⁠אָ֕רֶץ אֲשֶׁ֥ר אַתֶּ֛ם עֹבְרִ֥ים שָׁ֖מָּ⁠ה לְ⁠רִשְׁתָּֽ⁠הּ׃","wĕ⁠ʼòţi֞⁠y ẕiwá֤̇h yĕhwáh֙ bá̇⁠ʻé֣ţ ha⁠hi֔wʼ lĕ⁠lamé֣̇d ʼeţĕ⁠ke֔m ẖuqi֖̇ym ẇ⁠mişĕ̌pá̇ti֑ym la⁠ʻàşò̂ţĕ⁠ke֣m ʼòţá֔⁠m bá̇⁠ʼá֕reẕ ʼàşě֥r ʼaţė֛m ʻòbĕri֥ym şá֖̌má̇⁠h lĕ⁠rişĕ̌ţáֽ̇⁠ḣ׃"],[4,15,"וְ⁠נִשְׁמַרְתֶּ֥ם מְאֹ֖ד לְ⁠נַפְשֹׁתֵי⁠כֶ֑ם כִּ֣י לֹ֤א רְאִיתֶם֙ כָּל־תְּמוּנָ֔ה בְּ⁠י֗וֹם דִּבֶּ֨ר יְהוָ֧ה אֲלֵי⁠כֶ֛ם בְּ⁠חֹרֵ֖ב מִ⁠תּ֥וֹךְ הָ⁠אֵֽשׁ׃","wĕ⁠nişĕ̌marĕţė֥m mĕʼò֖d lĕ⁠napĕşò̌ţéy⁠ke֑m ki֣̇y lò֤ʼ rĕʼiyţem֙ ká̇l-ţĕ̇mẇná֔h bĕ̇⁠y֗wòm di̇bė֨r yĕhwá֧h ʼàléy⁠ke֛m bĕ̇⁠ẖòré֖b mi⁠ţ֥̇wòkĕ há⁠ʼéֽş̌׃"],[4,16,"פֶּ֨ן־תַּשְׁחִת֔וּ⁠ן וַ⁠עֲשִׂיתֶ֥ם לָ⁠כֶ֛ם פֶּ֖סֶל תְּמוּנַ֣ת כָּל־סָ֑מֶל תַּבְנִ֥ית זָכָ֖ר א֥וֹ נְקֵבָֽה׃","pė֨n-ţȧşĕ̌ẖiţ֔ẇ⁠n wa⁠ʻàşîyţe֥m lá⁠ke֛m pė֖sel ţĕ̇mẇna֣ţ ká̇l-sá֑mel ţȧbĕni֥yţ záká֖r ʼ֥wò nĕqébáֽh׃"],[4,17,"תַּבְנִ֕ית כָּל־בְּהֵמָ֖ה אֲשֶׁ֣ר בָּ⁠אָ֑רֶץ תַּבְנִית֙ כָּל־צִפּ֣וֹר כָּנָ֔ף אֲשֶׁ֥ר תָּע֖וּף בַּ⁠שָּׁמָֽיִם׃","ţȧbĕni֕yţ ká̇l-bĕ̇hémá֖h ʼàşě֣r bá̇⁠ʼá֑reẕ ţȧbĕniyţ֙ ká̇l-ẕiṗ֣wòr ká̇ná֔p ʼàşě֥r ţá̇ʻ֖ẇp bȧ⁠şá̇̌máֽyim׃"],[4,18,"תַּבְנִ֕ית כָּל־רֹמֵ֖שׂ בָּ⁠אֲדָמָ֑ה תַּבְנִ֛ית כָּל־דָּגָ֥ה אֲשֶׁר־בַּ⁠מַּ֖יִם מִ⁠תַּ֥חַת לָ⁠אָֽרֶץ׃","ţȧbĕni֕yţ ká̇l-ròmé֖ş̂ bá̇⁠ʼàdámá֑h ţȧbĕni֛yţ ká̇l-dá̇gá֥h ʼàşěr-bȧ⁠mȧ֖yim mi⁠ţȧ֥ẖaţ lá⁠ʼáֽreẕ׃"],[4,19,"וּ⁠פֶן־תִּשָּׂ֨א עֵינֶ֜י⁠ךָ הַ⁠שָּׁמַ֗יְמָ⁠ה וְֽ֠⁠רָאִיתָ אֶת־הַ⁠שֶּׁ֨מֶשׁ וְ⁠אֶת־הַ⁠יָּרֵ֜חַ וְ⁠אֶת־הַ⁠כּֽוֹכָבִ֗ים כֹּ֚ל צְבָ֣א הַ⁠שָּׁמַ֔יִם וְ⁠נִדַּחְתָּ֛ וְ⁠הִשְׁתַּחֲוִ֥יתָ לָ⁠הֶ֖ם וַ⁠עֲבַדְתָּ֑⁠ם אֲשֶׁ֨ר חָלַ֜ק יְהוָ֤ה אֱלֹהֶ֨י⁠ךָ֙ אֹתָ֔⁠ם לְ⁠כֹל֙ הָֽ⁠עַמִּ֔ים תַּ֖חַת כָּל־הַ⁠שָּׁמָֽיִם׃","ẇ⁠pen-ţi̇şá̇̂֨ʼ ʻéyne֜y⁠ká ha⁠şá̇̌ma֗yĕmá⁠h wĕֽ֠⁠ráʼiyţá ʼeţ-ha⁠şė̌֨meş̌ wĕ⁠ʼeţ-ha⁠yá̇ré֜ẖa wĕ⁠ʼeţ-ha⁠kֽ̇wòkábi֗ym kò֚̇l ẕĕbá֣ʼ ha⁠şá̇̌ma֔yim wĕ⁠nidȧẖĕţá֛̇ wĕ⁠hişĕ̌ţȧẖàwi֥yţá lá⁠he֖m wa⁠ʻàbadĕţá֑̇⁠m ʼàşě֨r ẖála֜q yĕhwá֤h ʼèlòhe֨y⁠ká֙ ʼòţá֔⁠m lĕ⁠kòl֙ háֽ⁠ʻami̇֔ym ţȧ֖ẖaţ ká̇l-ha⁠şá̇̌máֽyim׃"],[4,20,"וְ⁠אֶתְ⁠כֶם֙ לָקַ֣ח יְהוָ֔ה וַ⁠יּוֹצִ֥א אֶתְ⁠כֶ֛ם מִ⁠כּ֥וּר הַ⁠בַּרְזֶ֖ל מִ⁠מִּצְרָ֑יִם לִ⁠הְי֥וֹת ל֛⁠וֹ לְ⁠עַ֥ם נַחֲלָ֖ה כַּ⁠יּ֥וֹם הַ⁠זֶּֽה׃","wĕ⁠ʼeţĕ⁠kem֙ láqa֣ẖ yĕhwá֔h wa⁠ẏwòẕi֥ʼ ʼeţĕ⁠ke֛m mi⁠k֥̇ẇr ha⁠bȧrĕze֖l mi⁠mi̇ẕĕrá֑yim li⁠hĕy֥wòţ l֛⁠wò lĕ⁠ʻa֥m naẖàlá֖h kȧ⁠ẏ֥wòm ha⁠zėֽh׃"],[4,21,"וַֽ⁠יהוָ֥ה הִתְאַנֶּף־בִּ֖⁠י עַל־דִּבְרֵי⁠כֶ֑ם וַ⁠יִּשָּׁבַ֗ע לְ⁠בִלְתִּ֤י עָבְרִ⁠י֙ אֶת־הַ⁠יַּרְדֵּ֔ן וּ⁠לְ⁠בִלְתִּי־בֹא֙ אֶל־הָ⁠אָ֣רֶץ הַ⁠טּוֹבָ֔ה אֲשֶׁר֙ יְהוָ֣ה אֱלֹהֶ֔י⁠ךָ נֹתֵ֥ן לְ⁠ךָ֖ נַחֲלָֽה׃","waֽ⁠yhwá֥h hiţĕʼanėp-bi֖̇⁠y ʻal-di̇bĕréy⁠ke֑m wa⁠yi̇şá̇̌ba֗ʻ lĕ⁠bilĕţi֤̇y ʻábĕri⁠y֙ ʼeţ-ha⁠yȧrĕdé̇֔n ẇ⁠lĕ⁠bilĕţi̇y-bòʼ֙ ʼel-há⁠ʼá֣reẕ ha⁠ṫwòbá֔h ʼàşěr֙ yĕhwá֣h ʼèlòhe֔y⁠ká nòţé֥n lĕ⁠ká֖ naẖàláֽh׃"],[4,22,"כִּ֣י אָנֹכִ֥י מֵת֙ בָּ⁠אָ֣רֶץ הַ⁠זֹּ֔את אֵינֶ֥⁠נִּי עֹבֵ֖ר אֶת־הַ⁠יַּרְדֵּ֑ן וְ⁠אַתֶּם֙ עֹֽבְרִ֔ים וִֽ⁠ירִשְׁתֶּ֕ם אֶת־הָ⁠אָ֥רֶץ הַ⁠טּוֹבָ֖ה הַ⁠זֹּֽאת׃","ki֣̇y ʼánòki֥y méţ֙ bá̇⁠ʼá֣reẕ ha⁠zò̇֔ʼţ ʼéyne֥⁠ni̇y ʻòbé֖r ʼeţ-ha⁠yȧrĕdé֑̇n wĕ⁠ʼaţėm֙ ʻòֽbĕri֔ym wiֽ⁠yrişĕ̌ţė֕m ʼeţ-há⁠ʼá֥reẕ ha⁠ṫwòbá֖h ha⁠zòֽ̇ʼţ׃"],[4,23,"הִשָּׁמְר֣וּ לָ⁠כֶ֗ם פֶּֽן־תִּשְׁכְּחוּ֙ אֶת־בְּרִ֤ית יְהוָה֙ אֱלֹ֣הֵי⁠כֶ֔ם אֲשֶׁ֥ר כָּרַ֖ת עִמָּ⁠כֶ֑ם וַ⁠עֲשִׂיתֶ֨ם לָ⁠כֶ֥ם פֶּ֨סֶל֙ תְּמ֣וּנַת כֹּ֔ל אֲשֶׁ֥ר צִוְּ⁠ךָ֖ יְהוָ֥ה אֱלֹהֶֽי⁠ךָ׃","hişá̇̌mĕr֣ẇ lá⁠ke֗m pėֽn-ţi̇şĕ̌kĕ̇ẖẇ֙ ʼeţ-bĕ̇ri֤yţ yĕhwáh֙ ʼèlò֣héy⁠ke֔m ʼàşě֥r ká̇ra֖ţ ʻimá̇⁠ke֑m wa⁠ʻàşîyţe֨m lá⁠ke֥m pė֨sel֙ ţĕ̇m֣ẇnaţ kò̇֔l ʼàşě֥r ẕiwĕ̇⁠ká֖ yĕhwá֥h ʼèlòheֽy⁠ká׃"],[4,24,"כִּ֚י יְהוָ֣ה אֱלֹהֶ֔י⁠ךָ אֵ֥שׁ אֹכְלָ֖ה ה֑וּא אֵ֖ל קַנָּֽא׃פ","ki֚̇y yĕhwá֣h ʼèlòhe֔y⁠ká ʼé֥ş̌ ʼòkĕlá֖h h֑ẇʼ ʼé֖l qanáֽ̇ʼ׃p"],[4,25,"כִּֽי־תוֹלִ֤יד בָּנִים֙ וּ⁠בְנֵ֣י בָנִ֔ים וְ⁠נוֹשַׁנְתֶּ֖ם בָּ⁠אָ֑רֶץ וְ⁠הִשְׁחַתֶּ֗ם וַ⁠עֲשִׂ֤יתֶם פֶּ֨סֶל֙ תְּמ֣וּנַת כֹּ֔ל וַ⁠עֲשִׂיתֶ֥ם הָ⁠רַ֛ע בְּ⁠עֵינֵ֥י יְהוָֽה־אֱלֹהֶ֖י⁠ךָ לְ⁠הַכְעִיסֽ⁠וֹ׃","kiֽ̇y-ţwòli֤yd bá̇niym֙ ẇ⁠bĕné֣y báni֔ym wĕ⁠nwòşǎnĕţė֖m bá̇⁠ʼá֑reẕ wĕ⁠hişĕ̌ẖaţė֗m wa⁠ʻàşî֤yţem pė֨sel֙ ţĕ̇m֣ẇnaţ kò̇֔l wa⁠ʻàşîyţe֥m há⁠ra֛ʻ bĕ̇⁠ʻéyné֥y yĕhwáֽh-ʼèlòhe֖y⁠ká lĕ⁠hakĕʻiysֽ⁠wò׃"],[4,26,"הַעִידֹתִי֩ בָ⁠כֶ֨ם הַ⁠יּ֜וֹם אֶת־הַ⁠שָּׁמַ֣יִם וְ⁠אֶת־הָ⁠אָ֗רֶץ כִּֽי־אָבֹ֣ד תֹּאבֵדוּ⁠ן֮ מַהֵר֒ מֵ⁠עַ֣ל הָ⁠אָ֔רֶץ אֲשֶׁ֨ר אַתֶּ֜ם עֹבְרִ֧ים אֶת־הַ⁠יַּרְדֵּ֛ן שָׁ֖מָּ⁠ה לְ⁠רִשְׁתָּ֑⁠הּ לֹֽא־תַאֲרִיכֻ֤⁠ן יָמִים֙ עָלֶ֔י⁠הָ כִּ֥י הִשָּׁמֵ֖ד תִּשָּׁמֵדֽוּ⁠ן׃","haʻiydòţiy֩ bá⁠ke֨m ha⁠ẏ֜wòm ʼeţ-ha⁠şá̇̌ma֣yim wĕ⁠ʼeţ-há⁠ʼá֗reẕ kiֽ̇y-ʼábò֣d ţò̇ʼbédẇ⁠n֮ mahér֒ mé⁠ʻa֣l há⁠ʼá֔reẕ ʼàşě֨r ʼaţė֜m ʻòbĕri֧ym ʼeţ-ha⁠yȧrĕdé֛̇n şá֖̌má̇⁠h lĕ⁠rişĕ̌ţá֑̇⁠ḣ lòֽʼ-ţaʼàriyku֤⁠n yámiym֙ ʻále֔y⁠há ki֥̇y hişá̇̌mé֖d ţi̇şá̇̌médֽẇ⁠n׃"],[4,27,"וְ⁠הֵפִ֧יץ יְהוָ֛ה אֶתְ⁠כֶ֖ם בָּ⁠עַמִּ֑ים וְ⁠נִשְׁאַרְתֶּם֙ מְתֵ֣י מִסְפָּ֔ר בַּ⁠גּוֹיִ֕ם אֲשֶׁ֨ר יְנַהֵ֧ג יְהוָ֛ה אֶתְ⁠כֶ֖ם שָֽׁמָּ⁠ה׃","wĕ⁠hépi֧yẕ yĕhwá֛h ʼeţĕ⁠ke֖m bá̇⁠ʻami֑̇ym wĕ⁠nişĕ̌ʼarĕţėm֙ mĕţé֣y misĕpá̇֔r bȧ⁠ġwòyi֕m ʼàşě֨r yĕnahé֧g yĕhwá֛h ʼeţĕ⁠ke֖m şáֽ̌má̇⁠h׃"],[4,28,"וַ⁠עֲבַדְתֶּם־שָׁ֣ם אֱלֹהִ֔ים מַעֲשֵׂ֖ה יְדֵ֣י אָדָ֑ם עֵ֣ץ וָ⁠אֶ֔בֶן אֲשֶׁ֤ר לֹֽא־יִרְאוּ⁠ן֙ וְ⁠לֹ֣א יִשְׁמְע֔וּ⁠ן וְ⁠לֹ֥א יֹֽאכְל֖וּ⁠ן וְ⁠לֹ֥א יְרִיחֻֽ⁠ן׃","wa⁠ʻàbadĕţėm-şá֣̌m ʼèlòhi֔ym maʻàşé֖̂h yĕdé֣y ʼádá֑m ʻé֣ẕ wá⁠ʼe֔ben ʼàşě֤r lòֽʼ-yirĕʼẇ⁠n֙ wĕ⁠lò֣ʼ yişĕ̌mĕʻ֔ẇ⁠n wĕ⁠lò֥ʼ yòֽʼkĕl֖ẇ⁠n wĕ⁠lò֥ʼ yĕriyẖuֽ⁠n׃"],[4,29,"וּ⁠בִקַּשְׁתֶּ֥ם מִ⁠שָּׁ֛ם אֶת־יְהוָ֥ה אֱלֹהֶ֖י⁠ךָ וּ⁠מָצָ֑אתָ כִּ֣י תִדְרְשֶׁ֔⁠נּוּ בְּ⁠כָל־לְבָבְ⁠ךָ֖ וּ⁠בְ⁠כָל־נַפְשֶֽׁ⁠ךָ׃","ẇ⁠biqȧşĕ̌ţė֥m mi⁠şá֛̇̌m ʼeţ-yĕhwá֥h ʼèlòhe֖y⁠ká ẇ⁠máẕá֑ʼţá ki֣̇y ţidĕrĕşě֔⁠ṅẇ bĕ̇⁠kál-lĕbábĕ⁠ká֖ ẇ⁠bĕ⁠kál-napĕşěֽ⁠ká׃"],[4,30,"בַּ⁠צַּ֣ר לְ⁠ךָ֔ וּ⁠מְצָא֕וּ⁠ךָ כֹּ֖ל הַ⁠דְּבָרִ֣ים הָ⁠אֵ֑לֶּה בְּ⁠אַחֲרִית֙ הַ⁠יָּמִ֔ים וְ⁠שַׁבְתָּ֙ עַד־יְהוָ֣ה אֱלֹהֶ֔י⁠ךָ וְ⁠שָׁמַעְתָּ֖ בְּ⁠קֹלֽ⁠וֹ׃","bȧ⁠ẕȧ֣r lĕ⁠ká֔ ẇ⁠mĕẕáʼ֕ẇ⁠ká kò֖̇l ha⁠dĕ̇bári֣ym há⁠ʼé֑lėh bĕ̇⁠ʼaẖàriyţ֙ ha⁠yá̇mi֔ym wĕ⁠şǎbĕţá̇֙ ʻad-yĕhwá֣h ʼèlòhe֔y⁠ká wĕ⁠şá̌maʻĕţá֖̇ bĕ̇⁠qòlֽ⁠wò׃"],[4,31,"כִּ֣י אֵ֤ל רַחוּם֙ יְהוָ֣ה אֱלֹהֶ֔י⁠ךָ לֹ֥א יַרְפְּ⁠ךָ֖ וְ⁠לֹ֣א יַשְׁחִיתֶ֑⁠ךָ וְ⁠לֹ֤א יִשְׁכַּח֙ אֶת־בְּרִ֣ית אֲבֹתֶ֔י⁠ךָ אֲשֶׁ֥ר נִשְׁבַּ֖ע לָ⁠הֶֽם׃","ki֣̇y ʼé֤l raẖẇm֙ yĕhwá֣h ʼèlòhe֔y⁠ká lò֥ʼ yarĕpĕ̇⁠ká֖ wĕ⁠lò֣ʼ yaşĕ̌ẖiyţe֑⁠ká wĕ⁠lò֤ʼ yişĕ̌kȧẖ֙ ʼeţ-bĕ̇ri֣yţ ʼàbòţe֔y⁠ká ʼàşě֥r nişĕ̌bȧ֖ʻ lá⁠heֽm׃"],[4,32,"כִּ֣י שְׁאַל־נָא֩ לְ⁠יָמִ֨ים רִֽאשֹׁנִ֜ים אֲשֶׁר־הָי֣וּ לְ⁠פָנֶ֗י⁠ךָ לְ⁠מִן־הַ⁠יּוֹם֙ אֲשֶׁר֩ בָּרָ֨א אֱלֹהִ֤ים ׀ אָדָם֙ עַל־הָ⁠אָ֔רֶץ וּ⁠לְ⁠מִ⁠קְצֵ֥ה הַ⁠שָּׁמַ֖יִם וְ⁠עַד־קְצֵ֣ה הַ⁠שָּׁמָ֑יִם הֲ⁠נִֽהְיָ֗ה כַּ⁠דָּבָ֤ר הַ⁠גָּדוֹל֙ הַ⁠זֶּ֔ה א֖וֹ הֲ⁠נִשְׁמַ֥ע כָּמֹֽ⁠הוּ׃","ki֣̇y şĕ̌ʼal-náʼ֩ lĕ⁠yámi֨ym riֽʼşò̌ni֜ym ʼàşěr-háy֣ẇ lĕ⁠páne֗y⁠ká lĕ⁠min-ha⁠ẏwòm֙ ʼàşěr֩ bá̇rá֨ʼ ʼèlòhi֤ym ׀ ʼádám֙ ʻal-há⁠ʼá֔reẕ ẇ⁠lĕ⁠mi⁠qĕẕé֥h ha⁠şá̇̌ma֖yim wĕ⁠ʻad-qĕẕé֣h ha⁠şá̇̌má֑yim hà⁠niֽhĕyá֗h kȧ⁠dá̇bá֤r ha⁠gá̇dwòl֙ ha⁠zė֔h ʼ֖wò hà⁠nişĕ̌ma֥ʻ ká̇mòֽ⁠hẇ׃"],[4,33,"הֲ⁠שָׁ֣מַֽע עָם֩ ק֨וֹל אֱלֹהִ֜ים מְדַבֵּ֧ר מִ⁠תּוֹךְ־הָ⁠אֵ֛שׁ כַּ⁠אֲשֶׁר־שָׁמַ֥עְתָּ אַתָּ֖ה וַ⁠יֶּֽחִי׃","hà⁠şá֣̌maֽʻ ʻám֩ q֨wòl ʼèlòhi֜ym mĕdabé֧̇r mi⁠ţ̇wòkĕ-há⁠ʼé֛ş̌ kȧ⁠ʼàşěr-şá̌ma֥ʻĕţá̇ ʼaţá֖̇h wa⁠yėֽẖiy׃"],[4,34,"א֣וֹ ׀ הֲ⁠נִסָּ֣ה אֱלֹהִ֗ים לָ֠⁠בוֹא לָ⁠קַ֨חַת ל֣⁠וֹ גוֹי֮ מִ⁠קֶּ֣רֶב גּוֹי֒ בְּ⁠מַסֹּת֩ בְּ⁠אֹתֹ֨ת וּ⁠בְ⁠מוֹפְתִ֜ים וּ⁠בְ⁠מִלְחָמָ֗ה וּ⁠בְ⁠יָ֤ד חֲזָקָה֙ וּ⁠בִ⁠זְר֣וֹעַ נְטוּיָ֔ה וּ⁠בְ⁠מוֹרָאִ֖ים גְּדֹלִ֑ים כְּ֠⁠כֹל אֲשֶׁר־עָשָׂ֨ה לָ⁠כֶ֜ם יְהוָ֧ה אֱלֹהֵי⁠כֶ֛ם בְּ⁠מִצְרַ֖יִם לְ⁠עֵינֶֽי⁠ךָ׃","ʼ֣wò ׀ hà⁠nisá֣̇h ʼèlòhi֗ym lá֠⁠bwòʼ lá⁠qa֨ẖaţ l֣⁠wò gwòy֮ mi⁠qė֣reb ġwòy֒ bĕ̇⁠masò̇ţ֩ bĕ̇⁠ʼòţò֨ţ ẇ⁠bĕ⁠mwòpĕţi֜ym ẇ⁠bĕ⁠milĕẖámá֗h ẇ⁠bĕ⁠yá֤d ẖàzáqáh֙ ẇ⁠bi⁠zĕr֣wòʻa nĕtẇyá֔h ẇ⁠bĕ⁠mwòráʼi֖ym gĕ̇dòli֑ym kĕ̇֠⁠kòl ʼàşěr-ʻáşá̂֨h lá⁠ke֜m yĕhwá֧h ʼèlòhéy⁠ke֛m bĕ̇⁠miẕĕra֖yim lĕ⁠ʻéyneֽy⁠ká׃"],[4,35,"אַתָּה֙ הָרְאֵ֣תָ לָ⁠דַ֔עַת כִּ֥י יְהוָ֖ה ה֣וּא הָ⁠אֱלֹהִ֑ים אֵ֥ין ע֖וֹד מִ⁠לְ⁠בַדּֽ⁠וֹ׃","ʼaţá̇h֙ hárĕʼé֣ţá lá⁠da֔ʻaţ ki֥̇y yĕhwá֖h h֣ẇʼ há⁠ʼèlòhi֑ym ʼé֥yn ʻ֖wòd mi⁠lĕ⁠baḋֽ⁠wò׃"],[4,36,"מִן־הַ⁠שָּׁמַ֛יִם הִשְׁמִֽיעֲ⁠ךָ֥ אֶת־קֹל֖⁠וֹ לְ⁠יַסְּרֶ֑⁠ךָּ וְ⁠עַל־הָ⁠אָ֗רֶץ הֶרְאֲ⁠ךָ֙ אֶת־אִשּׁ֣⁠וֹ הַ⁠גְּדוֹלָ֔ה וּ⁠דְבָרָ֥י⁠ו שָׁמַ֖עְתָּ מִ⁠תּ֥וֹךְ הָ⁠אֵֽשׁ׃","min-ha⁠şá̇̌ma֛yim hişĕ̌miֽyʻà⁠ká֥ ʼeţ-qòl֖⁠wò lĕ⁠yasĕ̇re֑⁠ká̇ wĕ⁠ʻal-há⁠ʼá֗reẕ herĕʼà⁠ká֙ ʼeţ-ʼiş֣̇̌⁠wò ha⁠gĕ̇dwòlá֔h ẇ⁠dĕbárá֥y⁠w şá̌ma֖ʻĕţá̇ mi⁠ţ֥̇wòkĕ há⁠ʼéֽş̌׃"],[4,37,"וְ⁠תַ֗חַת כִּ֤י אָהַב֙ אֶת־אֲבֹתֶ֔י⁠ךָ וַ⁠יִּבְחַ֥ר בְּ⁠זַרְע֖⁠וֹ אַחֲרָ֑י⁠ו וַ⁠יּוֹצִֽאֲ⁠ךָ֧ בְּ⁠פָנָ֛י⁠ו בְּ⁠כֹח֥⁠וֹ הַ⁠גָּדֹ֖ל מִ⁠מִּצְרָֽיִם׃","wĕ⁠ţa֗ẖaţ ki֤̇y ʼáhab֙ ʼeţ-ʼàbòţe֔y⁠ká wa⁠yi̇bĕẖa֥r bĕ̇⁠zarĕʻ֖⁠wò ʼaẖàrá֑y⁠w wa⁠ẏwòẕiֽʼà⁠ká֧ bĕ̇⁠páná֛y⁠w bĕ̇⁠kòẖ֥⁠wò ha⁠gá̇dò֖l mi⁠mi̇ẕĕráֽyim׃"],[4,38,"לְ⁠הוֹרִ֗ישׁ גּוֹיִ֛ם גְּדֹלִ֧ים וַ⁠עֲצֻמִ֛ים מִמְּ⁠ךָ֖ מִ⁠פָּנֶ֑י⁠ךָ לַ⁠הֲבִֽיאֲ⁠ךָ֗ לָֽ⁠תֶת־לְ⁠ךָ֧ אֶת־אַרְצָ֛⁠ם נַחֲלָ֖ה כַּ⁠יּ֥וֹם הַ⁠זֶּֽה׃","lĕ⁠hwòri֗yş̌ ġwòyi֛m gĕ̇dòli֧ym wa⁠ʻàẕumi֛ym mimĕ̇⁠ká֖ mi⁠pá̇ne֑y⁠ká la⁠hàbiֽyʼà⁠ká֗ láֽ⁠ţeţ-lĕ⁠ká֧ ʼeţ-ʼarĕẕá֛⁠m naẖàlá֖h kȧ⁠ẏ֥wòm ha⁠zėֽh׃"],[4,39,"וְ⁠יָדַעְתָּ֣ הַ⁠יּ֗וֹם וַ⁠הֲשֵׁבֹתָ֮ אֶל־לְבָבֶ⁠ךָ֒ כִּ֤י יְהוָה֙ ה֣וּא הָֽ⁠אֱלֹהִ֔ים בַּ⁠שָּׁמַ֣יִם מִ⁠מַּ֔עַל וְ⁠עַל־הָ⁠אָ֖רֶץ מִ⁠תָּ֑חַת אֵ֖ין עֽוֹד׃","wĕ⁠yádaʻĕţá֣̇ ha⁠ẏ֗wòm wa⁠hàşé̌bòţá֮ ʼel-lĕbábe⁠ká֒ ki֤̇y yĕhwáh֙ h֣ẇʼ háֽ⁠ʼèlòhi֔ym bȧ⁠şá̇̌ma֣yim mi⁠mȧ֔ʻal wĕ⁠ʻal-há⁠ʼá֖reẕ mi⁠ţá֑̇ẖaţ ʼé֖yn ʻֽwòd׃"],[4,40,"וְ⁠שָׁמַרְתָּ֞ אֶת־חֻקָּ֣י⁠ו וְ⁠אֶת־מִצְוֺתָ֗י⁠ו אֲשֶׁ֨ר אָנֹכִ֤י מְצַוְּ⁠ךָ֙ הַ⁠יּ֔וֹם אֲשֶׁר֙ יִיטַ֣ב לְ⁠ךָ֔ וּ⁠לְ⁠בָנֶ֖י⁠ךָ אַחֲרֶ֑י⁠ךָ וּ⁠לְמַ֨עַן תַּאֲרִ֤יךְ יָמִים֙ עַל־הַ֣⁠אֲדָמָ֔ה אֲשֶׁ֨ר יְהוָ֧ה אֱלֹהֶ֛י⁠ךָ נֹתֵ֥ן לְ⁠ךָ֖ כָּל־הַ⁠יָּמִֽים׃פ","wĕ⁠şá̌marĕţá̇֞ ʼeţ-ẖuqá֣̇y⁠w wĕ⁠ʼeţ-miẕĕwֺţá֗y⁠w ʼàşě֨r ʼánòki֤y mĕẕawĕ̇⁠ká֙ ha⁠ẏ֔wòm ʼàşěr֙ yiyta֣b lĕ⁠ká֔ ẇ⁠lĕ⁠báne֖y⁠ká ʼaẖàre֑y⁠ká ẇ⁠lĕma֨ʻan ţȧʼàri֤ykĕ yámiym֙ ʻal-ha֣⁠ʼàdámá֔h ʼàşě֨r yĕhwá֧h ʼèlòhe֛y⁠ká nòţé֥n lĕ⁠ká֖ ká̇l-ha⁠yá̇miֽym׃p"],[4,41,"אָ֣ז יַבְדִּ֤יל מֹשֶׁה֙ שָׁלֹ֣שׁ עָרִ֔ים בְּ⁠עֵ֖בֶר הַ⁠יַּרְדֵּ֑ן מִזְרְחָ֖⁠ה שָֽׁמֶשׁ׃","ʼá֣z yabĕdi֤̇yl mòşěh֙ şá̌lò֣ş̌ ʻári֔ym bĕ̇⁠ʻé֖ber ha⁠yȧrĕdé֑̇n mizĕrĕẖá֖⁠h şáֽ̌meş̌׃"],[4,42,"לָ⁠נֻ֨ס שָׁ֜מָּ⁠ה רוֹצֵ֗חַ אֲשֶׁ֨ר יִרְצַ֤ח אֶת־רֵעֵ֨⁠הוּ֙ בִּ⁠בְלִי־דַ֔עַת וְ⁠ה֛וּא לֹא־שֹׂנֵ֥א ל֖⁠וֹ מִ⁠תְּמ֣וֹל שִׁלְשׁ֑וֹם וְ⁠נָ֗ס אֶל־אַחַ֛ת מִן־הֶ⁠עָרִ֥ים הָ⁠אֵ֖ל וָ⁠חָֽי׃","lá⁠nu֨s şá̌֜má̇⁠h rwòẕé֗ẖa ʼàşě֨r yirĕẕa֤ẖ ʼeţ-réʻé֨⁠hẇ֙ bi̇⁠bĕliy-da֔ʻaţ wĕ⁠h֛ẇʼ lòʼ-şò̂né֥ʼ l֖⁠wò mi⁠ţĕ̇m֣wòl şǐlĕş֑̌wòm wĕ⁠ná֗s ʼel-ʼaẖa֛ţ min-he⁠ʻári֥ym há⁠ʼé֖l wá⁠ẖáֽy׃"],[4,43,"אֶת־בֶּ֧צֶר בַּ⁠מִּדְבָּ֛ר בְּ⁠אֶ֥רֶץ הַ⁠מִּישֹׁ֖ר לָ⁠רֻֽאוּבֵנִ֑י וְ⁠אֶת־רָאמֹ֤ת בַּ⁠גִּלְעָד֙ לַ⁠גָּדִ֔י וְ⁠אֶת־גּוֹלָ֥ן בַּ⁠בָּשָׁ֖ן לַֽ⁠מְנַשִּֽׁי׃","ʼeţ-bė֧ẕer bȧ⁠mi̇dĕbá֛̇r bĕ̇⁠ʼe֥reẕ ha⁠mi̇yşò֖̌r lá⁠ruֽʼẇbéni֑y wĕ⁠ʼeţ-ráʼmò֤ţ bȧ⁠gi̇lĕʻád֙ la⁠gá̇di֔y wĕ⁠ʼeţ-ġwòlá֥n bȧ⁠bá̇şá֖̌n laֽ⁠mĕnaşiֽ̇̌y׃"],[4,44,"וְ⁠זֹ֖את הַ⁠תּוֹרָ֑ה אֲשֶׁר־שָׂ֣ם מֹשֶׁ֔ה לִ⁠פְנֵ֖י בְּנֵ֥י יִשְׂרָאֵֽל׃","wĕ⁠zò֖ʼţ ha⁠ţ̇wòrá֑h ʼàşěr-şá֣̂m mòşě֔h li⁠pĕné֖y bĕ̇né֥y yişĕ̂ráʼéֽl׃"],[4,45,"אֵ֚לֶּה הָֽ⁠עֵדֹ֔ת וְ⁠הַֽ⁠חֻקִּ֖ים וְ⁠הַ⁠מִּשְׁפָּטִ֑ים אֲשֶׁ֨ר דִּבֶּ֤ר מֹשֶׁה֙ אֶל־בְּנֵ֣י יִשְׂרָאֵ֔ל בְּ⁠צֵאתָ֖⁠ם מִ⁠מִּצְרָֽיִם׃","ʼé֚lėh háֽ⁠ʻédò֔ţ wĕ⁠haֽ⁠ẖuqi֖̇ym wĕ⁠ha⁠mi̇şĕ̌pá̇ti֑ym ʼàşě֨r di̇bė֤r mòşěh֙ ʼel-bĕ̇né֣y yişĕ̂ráʼé֔l bĕ̇⁠ẕéʼţá֖⁠m mi⁠mi̇ẕĕráֽyim׃"],[4,46,"בְּ⁠עֵ֨בֶר הַ⁠יַּרְדֵּ֜ן בַּ⁠גַּ֗יְא מ֚וּל בֵּ֣ית פְּע֔וֹר בְּ⁠אֶ֗רֶץ סִיחֹן֙ מֶ֣לֶךְ הָֽ⁠אֱמֹרִ֔י אֲשֶׁ֥ר יוֹשֵׁ֖ב בְּ⁠חֶשְׁבּ֑וֹן אֲשֶׁ֨ר הִכָּ֤ה מֹשֶׁה֙ וּ⁠בְנֵֽי יִשְׂרָאֵ֔ל בְּ⁠צֵאתָ֖⁠ם מִ⁠מִּצְרָֽיִם׃","bĕ̇⁠ʻé֨ber ha⁠yȧrĕdé̇֜n bȧ⁠gȧ֗yĕʼ m֚ẇl bé֣̇yţ pĕ̇ʻ֔wòr bĕ̇⁠ʼe֗reẕ siyẖòn֙ me֣lekĕ háֽ⁠ʼèmòri֔y ʼàşě֥r ywòşé֖̌b bĕ̇⁠ẖeşĕ̌ḃ֑wòn ʼàşě֨r hiká֤̇h mòşěh֙ ẇ⁠bĕnéֽy yişĕ̂ráʼé֔l bĕ̇⁠ẕéʼţá֖⁠m mi⁠mi̇ẕĕráֽyim׃"],[4,47,"וַ⁠יִּֽירְשׁ֨וּ אֶת־אַרְצ֜⁠וֹ וְ⁠אֶת־אֶ֣רֶץ ׀ ע֣וֹג מֶֽלֶךְ־הַ⁠בָּשָׁ֗ן שְׁנֵי֙ מַלְכֵ֣י הָֽ⁠אֱמֹרִ֔י אֲשֶׁ֖ר בְּ⁠עֵ֣בֶר הַ⁠יַּרְדֵּ֑ן מִזְרַ֖ח שָֽׁמֶשׁ׃","wa⁠yiֽ̇yrĕş̌֨ẇ ʼeţ-ʼarĕẕ֜⁠wò wĕ⁠ʼeţ-ʼe֣reẕ ׀ ʻ֣wòg meֽlekĕ-ha⁠bá̇şá̌֗n şĕ̌néy֙ malĕké֣y háֽ⁠ʼèmòri֔y ʼàşě֖r bĕ̇⁠ʻé֣ber ha⁠yȧrĕdé֑̇n mizĕra֖ẖ şáֽ̌meş̌׃"],[4,48,"מֵ⁠עֲרֹעֵ֞ר אֲשֶׁ֨ר עַל־שְׂפַת־נַ֧חַל אַרְנֹ֛ן וְ⁠עַד־הַ֥ר שִׂיאֹ֖ן ה֥וּא חֶרְמֽוֹן׃","mé⁠ʻàròʻé֞r ʼàşě֨r ʻal-şĕ̂paţ-na֧ẖal ʼarĕnò֛n wĕ⁠ʻad-ha֥r şîyʼò֖n h֥ẇʼ ẖerĕmֽwòn׃"],[4,49,"וְ⁠כָל־הָ֨⁠עֲרָבָ֜ה עֵ֤בֶר הַ⁠יַּרְדֵּן֙ מִזְרָ֔חָ⁠ה וְ⁠עַ֖ד יָ֣ם הָ⁠עֲרָבָ֑ה תַּ֖חַת אַשְׁדֹּ֥ת הַ⁠פִּסְגָּֽה׃פ","wĕ⁠kál-há֨⁠ʻàrábá֜h ʻé֤ber ha⁠yȧrĕdé̇n֙ mizĕrá֔ẖá⁠h wĕ⁠ʻa֖d yá֣m há⁠ʻàrábá֑h ţȧ֖ẖaţ ʼaşĕ̌dò֥̇ţ ha⁠pi̇sĕgáֽ̇h׃p"],[5,1,"וַ⁠יִּקְרָ֣א מֹשֶׁה֮ אֶל־כָּל־יִשְׂרָאֵל֒ וַ⁠יֹּ֣אמֶר אֲלֵ⁠הֶ֗ם שְׁמַ֤ע יִשְׂרָאֵל֙ אֶת־הַ⁠חֻקִּ֣ים וְ⁠אֶת־הַ⁠מִּשְׁפָּטִ֔ים אֲשֶׁ֧ר אָנֹכִ֛י דֹּבֵ֥ר בְּ⁠אָזְנֵי⁠כֶ֖ם הַ⁠יּ֑וֹם וּ⁠לְמַדְתֶּ֣ם אֹתָ֔⁠ם וּ⁠שְׁמַרְתֶּ֖ם לַ⁠עֲשֹׂתָֽ⁠ם׃","wa⁠yi̇qĕrá֣ʼ mòşěh֮ ʼel-ká̇l-yişĕ̂ráʼél֒ wa⁠yò֣̇ʼmer ʼàlé⁠he֗m şĕ̌ma֤ʻ yişĕ̂ráʼél֙ ʼeţ-ha⁠ẖuqi֣̇ym wĕ⁠ʼeţ-ha⁠mi̇şĕ̌pá̇ti֔ym ʼàşě֧r ʼánòki֛y dò̇bé֥r bĕ̇⁠ʼázĕnéy⁠ke֖m ha⁠ẏ֑wòm ẇ⁠lĕmadĕţė֣m ʼòţá֔⁠m ẇ⁠şĕ̌marĕţė֖m la⁠ʻàşò̂ţáֽ⁠m׃"],[5,2,"יְהוָ֣ה אֱלֹהֵ֗י⁠נוּ כָּרַ֥ת עִמָּ֛⁠נוּ בְּרִ֖ית בְּ⁠חֹרֵֽב׃","yĕhwá֣h ʼèlòhé֗y⁠nẇ ká̇ra֥ţ ʻimá֛̇⁠nẇ bĕ̇ri֖yţ bĕ̇⁠ẖòréֽb׃"],[5,3,"לֹ֣א אֶת־אֲבֹתֵ֔י⁠נוּ כָּרַ֥ת יְהוָ֖ה אֶת־הַ⁠בְּרִ֣ית הַ⁠זֹּ֑את כִּ֣י אִתָּ֗⁠נוּ אֲנַ֨חְנוּ אֵ֥לֶּה פֹ֛ה הַ⁠יּ֖וֹם כֻּלָּ֥⁠נוּ חַיִּֽים׃","lò֣ʼ ʼeţ-ʼàbòţé֔y⁠nẇ ká̇ra֥ţ yĕhwá֖h ʼeţ-ha⁠bĕ̇ri֣yţ ha⁠zò֑̇ʼţ ki֣̇y ʼiţá̇֗⁠nẇ ʼàna֨ẖĕnẇ ʼé֥lėh pò֛h ha⁠ẏ֖wòm ku̇lá֥̇⁠nẇ ẖayiֽ̇ym׃"],[5,4,"פָּנִ֣ים ׀ בְּ⁠פָנִ֗ים דִּבֶּ֨ר יְהוָ֧ה עִמָּ⁠כֶ֛ם בָּ⁠הָ֖ר מִ⁠תּ֥וֹךְ הָ⁠אֵֽשׁ׃","pá̇ni֣ym ׀ bĕ̇⁠páni֗ym di̇bė֨r yĕhwá֧h ʻimá̇⁠ke֛m bá̇⁠há֖r mi⁠ţ֥̇wòkĕ há⁠ʼéֽş̌׃"],[5,5,"אָ֠נֹכִי עֹמֵ֨ד בֵּין־יְהוָ֤ה וּ⁠בֵֽינֵי⁠כֶם֙ בָּ⁠עֵ֣ת הַ⁠הִ֔וא לְ⁠הַגִּ֥יד לָ⁠כֶ֖ם אֶת־דְּבַ֣ר יְהוָ֑ה כִּ֤י יְרֵאתֶם֙ מִ⁠פְּנֵ֣י הָ⁠אֵ֔שׁ וְ⁠לֹֽא־עֲלִיתֶ֥ם בָּ⁠הָ֖ר לֵ⁠אמֹֽר׃ס","ʼá֠nòkiy ʻòmé֨d bé̇yn-yĕhwá֤h ẇ⁠béֽynéy⁠kem֙ bá̇⁠ʻé֣ţ ha⁠hi֔wʼ lĕ⁠hagi֥̇yd lá⁠ke֖m ʼeţ-dĕ̇ba֣r yĕhwá֑h ki֤̇y yĕréʼţem֙ mi⁠pĕ̇né֣y há⁠ʼé֔ş̌ wĕ⁠lòֽʼ-ʻàliyţe֥m bá̇⁠há֖r lé⁠ʼmòֽr׃s"],[5,6,"אָֽנֹכִי֙ יְהוָ֣ה אֱלֹהֶ֔י⁠ךָ אֲשֶׁ֧ר הוֹצֵאתִ֛י⁠ךָ מֵ⁠אֶ֥רֶץ מִצְרַ֖יִם מִ⁠בֵּ֥ית עֲבָדִֽים׃","ʼáֽnòkiy֙ yĕhwá֣h ʼèlòhe֔y⁠ká ʼàşě֧r hwòẕéʼţi֛y⁠ká mé⁠ʼe֥reẕ miẕĕra֖yim mi⁠bé֥̇yţ ʻàbádiֽym׃"],[5,7,"לֹא־יִהְיֶ֥ה לְ⁠ךָ֛ אֱלֹהִ֥ים אֲחֵרִ֖ים עַל־פָּנָֽ⁠יַ׃","lòʼ-yihĕye֥h lĕ⁠ká֛ ʼèlòhi֥ym ʼàẖéri֖ym ʻal-pá̇náֽ⁠ya׃"],[5,8,"לֹֽ֣א־תַעֲשֶׂ֥ה לְ⁠ךָ֥ פֶ֨סֶל֙ כָּל־תְּמוּנָ֔ה אֲשֶׁ֤ר בַּ⁠שָּׁמַ֨יִם֙ מִ⁠מַּ֔עַל וַ⁠אֲשֶׁ֥ר בָּ⁠אָ֖רֶץ מִ⁠תָּ֑חַת וַ⁠אֲשֶׁ֥ר בַּ⁠מַּ֖יִם מִ⁠תַּ֥חַת לָ⁠אָֽרֶץ׃","lòֽ֣ʼ-ţaʻàşê֥h lĕ⁠ká֥ pe֨sel֙ ká̇l-ţĕ̇mẇná֔h ʼàşě֤r bȧ⁠şá̇̌ma֨yim֙ mi⁠mȧ֔ʻal wa⁠ʼàşě֥r bá̇⁠ʼá֖reẕ mi⁠ţá֑̇ẖaţ wa⁠ʼàşě֥r bȧ⁠mȧ֖yim mi⁠ţȧ֥ẖaţ lá⁠ʼáֽreẕ׃"],[5,9,"לֹא־תִשְׁתַּחֲוֶ֥ה לָ⁠הֶ֖ם וְ⁠לֹ֣א תָעָבְדֵ֑⁠ם כִּ֣י אָנֹכִ֞י יְהוָ֤ה אֱלֹהֶ֨י⁠ךָ֙ אֵ֣ל קַנָּ֔א פֹּ֠קֵד עֲוֺ֨ן אָב֧וֹת עַל־בָּנִ֛ים וְ⁠עַל־שִׁלֵּשִׁ֥ים וְ⁠עַל־רִבֵּעִ֖ים לְ⁠שֹׂנְאָֽ⁠י׃","lòʼ-ţişĕ̌ţȧẖàwe֥h lá⁠he֖m wĕ⁠lò֣ʼ ţáʻábĕdé֑⁠m ki֣̇y ʼánòki֞y yĕhwá֤h ʼèlòhe֨y⁠ká֙ ʼé֣l qaná̇֔ʼ pò̇֠qéd ʻàwֺ֨n ʼáb֧wòţ ʻal-bá̇ni֛ym wĕ⁠ʻal-şǐlé̇şǐ֥ym wĕ⁠ʻal-ribé̇ʻi֖ym lĕ⁠şò̂nĕʼáֽ⁠y׃"],[5,10,"וְ⁠עֹ֥שֶׂה חֶ֖סֶד לַֽ⁠אֲלָפִ֑ים לְ⁠אֹהֲבַ֖⁠י וּ⁠לְ⁠שֹׁמְרֵ֥י מצות⁠ו׃ס","wĕ⁠ʻò֥şêh ẖe֖sed laֽ⁠ʼàlápi֑ym lĕ⁠ʼòhàba֖⁠y ẇ⁠lĕ⁠şò̌mĕré֥y mẕwţ⁠w׃s"],[5,11,"לֹ֥א תִשָּׂ֛א אֶת־שֵֽׁם־יְהוָ֥ה אֱלֹהֶ֖י⁠ךָ לַ⁠שָּׁ֑וְא כִּ֣י לֹ֤א יְנַקֶּה֙ יְהוָ֔ה אֵ֛ת אֲשֶׁר־יִשָּׂ֥א אֶת־שְׁמ֖⁠וֹ לַ⁠שָּֽׁוְא׃ס","lò֥ʼ ţişá֛̇̂ʼ ʼeţ-şéֽ̌m-yĕhwá֥h ʼèlòhe֖y⁠ká la⁠şá֑̇̌wĕʼ ki֣̇y lò֤ʼ yĕnaqėh֙ yĕhwá֔h ʼé֛ţ ʼàşěr-yişá֥̇̂ʼ ʼeţ-şĕ̌m֖⁠wò la⁠şáֽ̇̌wĕʼ׃s"],[5,12,"שָׁמ֛וֹר אֶת־י֥וֹם הַ⁠שַׁבָּ֖ת לְ⁠קַדְּשׁ֑⁠וֹ כַּ⁠אֲשֶׁ֥ר צִוְּ⁠ךָ֖ יְהוָ֥ה אֱלֹהֶֽי⁠ךָ׃","şá̌m֛wòr ʼeţ-y֥wòm ha⁠şǎbá֖̇ţ lĕ⁠qadĕ̇ş֑̌⁠wò kȧ⁠ʼàşě֥r ẕiwĕ̇⁠ká֖ yĕhwá֥h ʼèlòheֽy⁠ká׃"],[5,13,"שֵׁ֤שֶׁת יָמִים֙ תַּֽעֲבֹ֔ד וְ⁠עָשִׂ֖יתָ כָּל־מְלַאכְתֶּֽ⁠ךָ׃","şé֤̌şěţ yámiym֙ ţȧֽʻàbò֔d wĕ⁠ʻáşî֖yţá ká̇l-mĕlaʼkĕţėֽ⁠ká׃"],[5,14,"וְ⁠י֨וֹם֙ הַ⁠שְּׁבִיעִ֔י שַׁבָּ֖ת לַ⁠יהוָ֣ה אֱלֹהֶ֑י⁠ךָ לֹ֣א תַעֲשֶׂ֣ה כָל־מְלָאכָ֡ה אַתָּ֣ה וּ⁠בִנְ⁠ךָֽ־וּ⁠בִתֶּ֣⁠ךָ וְ⁠עַבְדְּ⁠ךָֽ־וַ֠⁠אֲמָתֶ⁠ךָ וְ⁠שׁוֹרְ⁠ךָ֨ וַ⁠חֲמֹֽרְ⁠ךָ֜ וְ⁠כָל־בְּהֶמְתֶּ֗⁠ךָ וְ⁠גֵֽרְ⁠ךָ֙ אֲשֶׁ֣ר בִּ⁠שְׁעָרֶ֔י⁠ךָ לְמַ֗עַן יָנ֛וּחַ עַבְדְּ⁠ךָ֥ וַ⁠אֲמָתְ⁠ךָ֖ כָּמֽוֹ⁠ךָ׃","wĕ⁠y֨wòm֙ ha⁠şĕ̇̌biyʻi֔y şǎbá֖̇ţ la⁠yhwá֣h ʼèlòhe֑y⁠ká lò֣ʼ ţaʻàşê֣h kál-mĕláʼká֡h ʼaţá֣̇h ẇ⁠binĕ⁠káֽ-ẇ⁠biţė֣⁠ká wĕ⁠ʻabĕdĕ̇⁠káֽ-wa֠⁠ʼàmáţe⁠ká wĕ⁠ş̌wòrĕ⁠ká֨ wa⁠ẖàmòֽrĕ⁠ká֜ wĕ⁠kál-bĕ̇hemĕţė֗⁠ká wĕ⁠géֽrĕ⁠ká֙ ʼàşě֣r bi̇⁠şĕ̌ʻáre֔y⁠ká lĕma֗ʻan yán֛ẇẖa ʻabĕdĕ̇⁠ká֥ wa⁠ʼàmáţĕ⁠ká֖ ká̇mֽwò⁠ká׃"],[5,15,"וְ⁠זָכַרְתָּ֗ כִּ֣י־עֶ֤בֶד הָיִ֨יתָ֙ ׀ בְּ⁠אֶ֣רֶץ מִצְרַ֔יִם וַ⁠יֹּצִ֨אֲ⁠ךָ֜ יְהוָ֤ה אֱלֹהֶ֨י⁠ךָ֙ מִ⁠שָּׁ֔ם בְּ⁠יָ֥ד חֲזָקָ֖ה וּ⁠בִ⁠זְרֹ֣עַ נְטוּיָ֑ה עַל־כֵּ֗ן צִוְּ⁠ךָ֙ יְהוָ֣ה אֱלֹהֶ֔י⁠ךָ לַ⁠עֲשׂ֖וֹת אֶת־י֥וֹם הַ⁠שַׁבָּֽת׃ס","wĕ⁠zákarĕţá̇֗ ki֣̇y-ʻe֤bed háyi֨yţá֙ ׀ bĕ̇⁠ʼe֣reẕ miẕĕra֔yim wa⁠yò̇ẕi֨ʼà⁠ká֜ yĕhwá֤h ʼèlòhe֨y⁠ká֙ mi⁠şá̇̌֔m bĕ̇⁠yá֥d ẖàzáqá֖h ẇ⁠bi⁠zĕrò֣ʻa nĕtẇyá֑h ʻal-ké̇֗n ẕiwĕ̇⁠ká֙ yĕhwá֣h ʼèlòhe֔y⁠ká la⁠ʻàş֖̂wòţ ʼeţ-y֥wòm ha⁠şǎbáֽ̇ţ׃s"],[5,16,"כַּבֵּ֤ד אֶת־אָבִ֨י⁠ךָ֙ וְ⁠אֶת־אִמֶּ֔⁠ךָ כַּ⁠אֲשֶׁ֥ר צִוְּ⁠ךָ֖ יְהוָ֣ה אֱלֹהֶ֑י⁠ךָ לְמַ֣עַן ׀ יַאֲרִיכֻ֣⁠ן יָמֶ֗י⁠ךָ וּ⁠לְמַ֨עַן֙ יִ֣יטַב לָ֔⁠ךְ עַ֚ל הָֽ⁠אֲדָמָ֔ה אֲשֶׁר־יְהוָ֥ה אֱלֹהֶ֖י⁠ךָ נֹתֵ֥ן לָֽ⁠ךְ׃ס","kȧbé֤̇d ʼeţ-ʼábi֨y⁠ká֙ wĕ⁠ʼeţ-ʼimė֔⁠ká kȧ⁠ʼàşě֥r ẕiwĕ̇⁠ká֖ yĕhwá֣h ʼèlòhe֑y⁠ká lĕma֣ʻan ׀ yaʼàriyku֣⁠n yáme֗y⁠ká ẇ⁠lĕma֨ʻan֙ yi֣ytab lá֔⁠kĕ ʻa֚l háֽ⁠ʼàdámá֔h ʼàşěr-yĕhwá֥h ʼèlòhe֖y⁠ká nòţé֥n láֽ⁠kĕ׃s"],[5,17,"לֹ֖א תִּרְצָֽח׃ס","lò֖ʼ ţi̇rĕẕáֽẖ׃s"],[5,18,"וְ⁠לֹ֖א תִּנְאָֽף׃ס","wĕ⁠lò֖ʼ ţi̇nĕʼáֽp׃s"],[5,19,"וְ⁠לֹ֖א תִּגְנֹֽב׃ס","wĕ⁠lò֖ʼ ţi̇gĕnòֽb׃s"],[5,20,"וְ⁠לֹֽא־תַעֲנֶ֥ה בְ⁠רֵֽעֲ⁠ךָ֖ עֵ֥ד שָֽׁוְא׃ס","wĕ⁠lòֽʼ-ţaʻàne֥h bĕ⁠réֽʻà⁠ká֖ ʻé֥d şáֽ̌wĕʼ׃s"],[5,21,"וְ⁠לֹ֥א תַחְמֹ֖ד אֵ֣שֶׁת רֵעֶ֑⁠ךָ ס וְ⁠לֹ֨א תִתְאַוֶּ֜ה בֵּ֣ית רֵעֶ֗⁠ךָ שָׂדֵ֜⁠הוּ וְ⁠עַבְדּ֤⁠וֹ וַ⁠אֲמָת⁠וֹ֙ שׁוֹר֣⁠וֹ וַ⁠חֲמֹר֔⁠וֹ וְ⁠כֹ֖ל אֲשֶׁ֥ר לְ⁠רֵעֶֽ⁠ךָ׃ס","wĕ⁠lò֥ʼ ţaẖĕmò֖d ʼé֣şěţ réʻe֑⁠ká s wĕ⁠lò֨ʼ ţiţĕʼawė֜h bé֣̇yţ réʻe֗⁠ká şá̂dé֜⁠hẇ wĕ⁠ʻabĕḋ֤⁠wò wa⁠ʼàmáţ⁠wò֙ ş̌wòr֣⁠wò wa⁠ẖàmòr֔⁠wò wĕ⁠kò֖l ʼàşě֥r lĕ⁠réʻeֽ⁠ká׃s"],[5,22,"אֶֽת־הַ⁠דְּבָרִ֣ים הָ⁠אֵ֡לֶּה דִּבֶּר֩ יְהוָ֨ה אֶל־כָּל־קְהַלְ⁠כֶ֜ם בָּ⁠הָ֗ר מִ⁠תּ֤וֹךְ הָ⁠אֵשׁ֙ הֶֽ⁠עָנָ֣ן וְ⁠הָֽ⁠עֲרָפֶ֔ל ק֥וֹל גָּד֖וֹל וְ⁠לֹ֣א יָסָ֑ף וַֽ⁠יִּכְתְּבֵ֗⁠ם עַל־שְׁנֵי֙ לֻחֹ֣ת אֲבָנִ֔ים וַֽ⁠יִּתְּנֵ֖⁠ם אֵלָֽ⁠י׃","ʼeֽţ-ha⁠dĕ̇bári֣ym há⁠ʼé֡lėh di̇bėr֩ yĕhwá֨h ʼel-ká̇l-qĕhalĕ⁠ke֜m bá̇⁠há֗r mi⁠ţ֤̇wòkĕ há⁠ʼéş̌֙ heֽ⁠ʻáná֣n wĕ⁠háֽ⁠ʻàrápe֔l q֥wòl gá̇d֖wòl wĕ⁠lò֣ʼ yásá֑p waֽ⁠yi̇kĕţĕ̇bé֗⁠m ʻal-şĕ̌néy֙ luẖò֣ţ ʼàbáni֔ym waֽ⁠yi̇ţĕ̇né֖⁠m ʼéláֽ⁠y׃"],[5,23,"וַ⁠יְהִ֗י כְּ⁠שָׁמְעֲ⁠כֶ֤ם אֶת־הַ⁠קּוֹל֙ מִ⁠תּ֣וֹךְ הַ⁠חֹ֔שֶׁךְ וְ⁠הָ⁠הָ֖ר בֹּעֵ֣ר בָּ⁠אֵ֑שׁ וַ⁠תִּקְרְב֣וּ⁠ן אֵלַ֔⁠י כָּל־רָאשֵׁ֥י שִׁבְטֵי⁠כֶ֖ם וְ⁠זִקְנֵי⁠כֶֽם׃","wa⁠yĕhi֗y kĕ̇⁠şá̌mĕʻà⁠ke֤m ʼeţ-ha⁠q̇wòl֙ mi⁠ţ֣̇wòkĕ ha⁠ẖò֔şěkĕ wĕ⁠há⁠há֖r bò̇ʻé֣r bá̇⁠ʼé֑ş̌ wa⁠ţi̇qĕrĕb֣ẇ⁠n ʼéla֔⁠y ká̇l-ráʼşé֥̌y şǐbĕtéy⁠ke֖m wĕ⁠ziqĕnéy⁠keֽm׃"],[5,24,"וַ⁠תֹּאמְר֗וּ הֵ֣ן הֶרְאָ֜⁠נוּ יְהוָ֤ה אֱלֹהֵ֨י⁠נוּ֙ אֶת־כְּבֹד֣⁠וֹ וְ⁠אֶת־גָּדְל֔⁠וֹ וְ⁠אֶת־קֹל֥⁠וֹ שָׁמַ֖עְנוּ מִ⁠תּ֣וֹךְ הָ⁠אֵ֑שׁ הַ⁠יּ֤וֹם הַ⁠זֶּה֙ רָאִ֔ינוּ כִּֽי־יְדַבֵּ֧ר אֱלֹהִ֛ים אֶת־הָֽ⁠אָדָ֖ם וָ⁠חָֽי׃","wa⁠ţò̇ʼmĕr֗ẇ hé֣n herĕʼá֜⁠nẇ yĕhwá֤h ʼèlòhé֨y⁠nẇ֙ ʼeţ-kĕ̇bòd֣⁠wò wĕ⁠ʼeţ-gá̇dĕl֔⁠wò wĕ⁠ʼeţ-qòl֥⁠wò şá̌ma֖ʻĕnẇ mi⁠ţ֣̇wòkĕ há⁠ʼé֑ş̌ ha⁠ẏ֤wòm ha⁠zėh֙ ráʼi֔ynẇ kiֽ̇y-yĕdabé֧̇r ʼèlòhi֛ym ʼeţ-háֽ⁠ʼádá֖m wá⁠ẖáֽy׃"],[5,25,"וְ⁠עַתָּה֙ לָ֣⁠מָּה נָמ֔וּת כִּ֣י תֹֽאכְלֵ֔⁠נוּ הָ⁠אֵ֥שׁ הַ⁠גְּדֹלָ֖ה הַ⁠זֹּ֑את אִם־יֹסְפִ֣ים ׀ אֲנַ֗חְנוּ לִ֠⁠שְׁמֹעַ אֶת־ק֨וֹל יְהוָ֧ה אֱלֹהֵ֛י⁠נוּ ע֖וֹד וָ⁠מָֽתְנוּ׃","wĕ⁠ʻaţá̇h֙ lá֣⁠má̇h nám֔ẇţ ki֣̇y ţòֽʼkĕlé֔⁠nẇ há⁠ʼé֥ş̌ ha⁠gĕ̇dòlá֖h ha⁠zò֑̇ʼţ ʼim-yòsĕpi֣ym ׀ ʼàna֗ẖĕnẇ li֠⁠şĕ̌mòʻa ʼeţ-q֨wòl yĕhwá֧h ʼèlòhé֛y⁠nẇ ʻ֖wòd wá⁠máֽţĕnẇ׃"],[5,26,"כִּ֣י מִ֣י כָל־בָּשָׂ֡ר אֲשֶׁ֣ר שָׁמַ֣ע קוֹל֩ אֱלֹהִ֨ים חַיִּ֜ים מְדַבֵּ֧ר מִ⁠תּוֹךְ־הָ⁠אֵ֛שׁ כָּמֹ֖⁠נוּ וַ⁠יֶּֽחִי׃","ki֣̇y mi֣y kál-bá̇şá̂֡r ʼàşě֣r şá̌ma֣ʻ qwòl֩ ʼèlòhi֨ym ẖayi̇֜ym mĕdabé֧̇r mi⁠ţ̇wòkĕ-há⁠ʼé֛ş̌ ká̇mò֖⁠nẇ wa⁠yėֽẖiy׃"],[5,27,"קְרַ֤ב אַתָּה֙ וּֽ⁠שֲׁמָ֔ע אֵ֛ת כָּל־אֲשֶׁ֥ר יֹאמַ֖ר יְהוָ֣ה אֱלֹהֵ֑י⁠נוּ וְ⁠אַ֣תְּ ׀ תְּדַבֵּ֣ר אֵלֵ֗י⁠נוּ אֵת֩ כָּל־אֲשֶׁ֨ר יְדַבֵּ֜ר יְהוָ֧ה אֱלֹהֵ֛י⁠נוּ אֵלֶ֖י⁠ךָ וְ⁠שָׁמַ֥עְנוּ וְ⁠עָשִֽׂינוּ׃","qĕra֤b ʼaţá̇h֙ ẇֽ⁠şà̌má֔ʻ ʼé֛ţ ká̇l-ʼàşě֥r yòʼma֖r yĕhwá֣h ʼèlòhé֑y⁠nẇ wĕ⁠ʼa֣ţĕ̇ ׀ ţĕ̇dabé֣̇r ʼélé֗y⁠nẇ ʼéţ֩ ká̇l-ʼàşě֨r yĕdabé̇֜r yĕhwá֧h ʼèlòhé֛y⁠nẇ ʼéle֖y⁠ká wĕ⁠şá̌ma֥ʻĕnẇ wĕ⁠ʻáşîֽynẇ׃"],[5,28,"וַ⁠יִּשְׁמַ֤ע יְהוָה֙ אֶת־ק֣וֹל דִּבְרֵי⁠כֶ֔ם בְּ⁠דַבֶּרְ⁠כֶ֖ם אֵלָ֑⁠י וַ⁠יֹּ֨אמֶר יְהוָ֜ה אֵלַ֗⁠י שָׁ֠מַעְתִּי אֶת־ק֨וֹל דִּבְרֵ֜י הָ⁠עָ֤ם הַ⁠זֶּה֙ אֲשֶׁ֣ר דִּבְּר֣וּ אֵלֶ֔י⁠ךָ הֵיטִ֖יבוּ כָּל־אֲשֶׁ֥ר דִּבֵּֽרוּ׃","wa⁠yi̇şĕ̌ma֤ʻ yĕhwáh֙ ʼeţ-q֣wòl di̇bĕréy⁠ke֔m bĕ̇⁠dabėrĕ⁠ke֖m ʼélá֑⁠y wa⁠yò̇֨ʼmer yĕhwá֜h ʼéla֗⁠y şá̌֠maʻĕţi̇y ʼeţ-q֨wòl di̇bĕré֜y há⁠ʻá֤m ha⁠zėh֙ ʼàşě֣r di̇bĕ̇r֣ẇ ʼéle֔y⁠ká héyti֖ybẇ ká̇l-ʼàşě֥r di̇béֽ̇rẇ׃"],[5,29,"מִֽי־יִתֵּ֡ן וְ⁠הָיָה֩ לְבָבָ֨⁠ם זֶ֜ה לָ⁠הֶ֗ם לְ⁠יִרְאָ֥ה אֹתִ֛⁠י וְ⁠לִ⁠שְׁמֹ֥ר אֶת־כָּל־מִצְוֺתַ֖⁠י כָּל־הַ⁠יָּמִ֑ים לְמַ֨עַן יִיטַ֥ב לָ⁠הֶ֛ם וְ⁠לִ⁠בְנֵי⁠הֶ֖ם לְ⁠עֹלָֽם׃","miֽy-yiţé̇֡n wĕ⁠háyáh֩ lĕbábá֨⁠m ze֜h lá⁠he֗m lĕ⁠yirĕʼá֥h ʼòţi֛⁠y wĕ⁠li⁠şĕ̌mò֥r ʼeţ-ká̇l-miẕĕwֺţa֖⁠y ká̇l-ha⁠yá̇mi֑ym lĕma֨ʻan yiyta֥b lá⁠he֛m wĕ⁠li⁠bĕnéy⁠he֖m lĕ⁠ʻòláֽm׃"],[5,30,"לֵ֖ךְ אֱמֹ֣ר לָ⁠הֶ֑ם שׁ֥וּבוּ לָ⁠כֶ֖ם לְ⁠אָהֳלֵי⁠כֶֽם׃","lé֖kĕ ʼèmò֣r lá⁠he֑m ş֥̌ẇbẇ lá⁠ke֖m lĕ⁠ʼáholéy⁠keֽm׃"],[5,31,"וְ⁠אַתָּ֗ה פֹּה֮ עֲמֹ֣ד עִמָּדִ⁠י֒ וַ⁠אֲדַבְּרָ֣ה אֵלֶ֗י⁠ךָ אֵ֧ת כָּל־הַ⁠מִּצְוָ֛ה וְ⁠הַ⁠חֻקִּ֥ים וְ⁠הַ⁠מִּשְׁפָּטִ֖ים אֲשֶׁ֣ר תְּלַמְּדֵ֑⁠ם וְ⁠עָשׂ֣וּ בָ⁠אָ֔רֶץ אֲשֶׁ֧ר אָנֹכִ֛י נֹתֵ֥ן לָ⁠הֶ֖ם לְ⁠רִשְׁתָּֽ⁠הּ׃","wĕ⁠ʼaţá̇֗h pò̇h֮ ʻàmò֣d ʻimá̇di⁠y֒ wa⁠ʼàdabĕ̇rá֣h ʼéle֗y⁠ká ʼé֧ţ ká̇l-ha⁠mi̇ẕĕwá֛h wĕ⁠ha⁠ẖuqi֥̇ym wĕ⁠ha⁠mi̇şĕ̌pá̇ti֖ym ʼàşě֣r ţĕ̇lamĕ̇dé֑⁠m wĕ⁠ʻáş֣̂ẇ bá⁠ʼá֔reẕ ʼàşě֧r ʼánòki֛y nòţé֥n lá⁠he֖m lĕ⁠rişĕ̌ţáֽ̇⁠ḣ׃"],[5,32,"וּ⁠שְׁמַרְתֶּ֣ם לַ⁠עֲשׂ֔וֹת כַּ⁠אֲשֶׁ֥ר צִוָּ֛ה יְהוָ֥ה אֱלֹהֵי⁠כֶ֖ם אֶתְ⁠כֶ֑ם לֹ֥א תָסֻ֖רוּ יָמִ֥ין וּ⁠שְׂמֹֽאל׃","ẇ⁠şĕ̌marĕţė֣m la⁠ʻàş̂֔wòţ kȧ⁠ʼàşě֥r ẕiwá֛̇h yĕhwá֥h ʼèlòhéy⁠ke֖m ʼeţĕ⁠ke֑m lò֥ʼ ţásu֖rẇ yámi֥yn ẇ⁠şĕ̂mòֽʼl׃"],[5,33,"בְּ⁠כָל־הַ⁠דֶּ֗רֶךְ אֲשֶׁ֨ר צִוָּ֜ה יְהוָ֧ה אֱלֹהֵי⁠כֶ֛ם אֶתְ⁠כֶ֖ם תֵּלֵ֑כוּ לְמַ֤עַן תִּֽחְיוּ⁠ן֙ וְ⁠ט֣וֹב לָ⁠כֶ֔ם וְ⁠הַאֲרַכְתֶּ֣ם יָמִ֔ים בָּ⁠אָ֖רֶץ אֲשֶׁ֥ר תִּֽירָשֽׁוּ⁠ן׃","bĕ̇⁠kál-ha⁠dė֗rekĕ ʼàşě֨r ẕiwá̇֜h yĕhwá֧h ʼèlòhéy⁠ke֛m ʼeţĕ⁠ke֖m ţé̇lé֑kẇ lĕma֤ʻan ţiֽ̇ẖĕyẇ⁠n֙ wĕ⁠t֣wòb lá⁠ke֔m wĕ⁠haʼàrakĕţė֣m yámi֔ym bá̇⁠ʼá֖reẕ ʼàşě֥r ţiֽ̇yráşֽ̌ẇ⁠n׃"],[6,1,"וְ⁠זֹ֣את הַ⁠מִּצְוָ֗ה הַֽ⁠חֻקִּים֙ וְ⁠הַ⁠מִּשְׁפָּטִ֔ים אֲשֶׁ֥ר צִוָּ֛ה יְהוָ֥ה אֱלֹהֵי⁠כֶ֖ם לְ⁠לַמֵּ֣ד אֶתְ⁠כֶ֑ם לַ⁠עֲשׂ֣וֹת בָּ⁠אָ֔רֶץ אֲשֶׁ֥ר אַתֶּ֛ם עֹבְרִ֥ים שָׁ֖מָּ⁠ה לְ⁠רִשְׁתָּֽ⁠הּ׃","wĕ⁠zò֣ʼţ ha⁠mi̇ẕĕwá֗h haֽ⁠ẖuqi̇ym֙ wĕ⁠ha⁠mi̇şĕ̌pá̇ti֔ym ʼàşě֥r ẕiwá֛̇h yĕhwá֥h ʼèlòhéy⁠ke֖m lĕ⁠lamé֣̇d ʼeţĕ⁠ke֑m la⁠ʻàş֣̂wòţ bá̇⁠ʼá֔reẕ ʼàşě֥r ʼaţė֛m ʻòbĕri֥ym şá֖̌má̇⁠h lĕ⁠rişĕ̌ţáֽ̇⁠ḣ׃"],[6,2,"לְמַ֨עַן תִּירָ֜א אֶת־יְהוָ֣ה אֱלֹהֶ֗י⁠ךָ לִ֠⁠שְׁמֹר אֶת־כָּל־חֻקֹּתָ֣י⁠ו וּ⁠מִצְוֺתָי⁠ו֮ אֲשֶׁ֣ר אָנֹכִ֣י מְצַוֶּ⁠ךָ֒ אַתָּה֙ וּ⁠בִנְ⁠ךָ֣ וּ⁠בֶן־בִּנְ⁠ךָ֔ כֹּ֖ל יְמֵ֣י חַיֶּ֑י⁠ךָ וּ⁠לְמַ֖עַן יַאֲרִכֻ֥⁠ן יָמֶֽי⁠ךָ׃","lĕma֨ʻan ţi̇yrá֜ʼ ʼeţ-yĕhwá֣h ʼèlòhe֗y⁠ká li֠⁠şĕ̌mòr ʼeţ-ká̇l-ẖuqò̇ţá֣y⁠w ẇ⁠miẕĕwֺţáy⁠w֮ ʼàşě֣r ʼánòki֣y mĕẕawė⁠ká֒ ʼaţá̇h֙ ẇ⁠binĕ⁠ká֣ ẇ⁠ben-bi̇nĕ⁠ká֔ kò֖̇l yĕmé֣y ẖayė֑y⁠ká ẇ⁠lĕma֖ʻan yaʼàriku֥⁠n yámeֽy⁠ká׃"],[6,3,"וְ⁠שָׁמַעְתָּ֤ יִשְׂרָאֵל֙ וְ⁠שָׁמַרְתָּ֣ לַ⁠עֲשׂ֔וֹת אֲשֶׁר֙ יִיטַ֣ב לְ⁠ךָ֔ וַ⁠אֲשֶׁ֥ר תִּרְבּ֖וּ⁠ן מְאֹ֑ד כַּ⁠אֲשֶׁר֩ דִּבֶּ֨ר יְהוָ֜ה אֱלֹהֵ֤י אֲבֹתֶ֨י⁠ךָ֙ לָ֔⁠ךְ אֶ֛רֶץ זָבַ֥ת חָלָ֖ב וּ⁠דְבָֽשׁ׃פ","wĕ⁠şá̌maʻĕţá֤̇ yişĕ̂ráʼél֙ wĕ⁠şá̌marĕţá֣̇ la⁠ʻàş̂֔wòţ ʼàşěr֙ yiyta֣b lĕ⁠ká֔ wa⁠ʼàşě֥r ţi̇rĕḃ֖ẇ⁠n mĕʼò֑d kȧ⁠ʼàşěr֩ di̇bė֨r yĕhwá֜h ʼèlòhé֤y ʼàbòţe֨y⁠ká֙ lá֔⁠kĕ ʼe֛reẕ zába֥ţ ẖálá֖b ẇ⁠dĕbáֽş̌׃p"],[6,4,"שְׁמַ֖ע יִשְׂרָאֵ֑ל יְהוָ֥ה אֱלֹהֵ֖י⁠נוּ יְהוָ֥ה ׀ אֶחָֽד׃","şĕ̌ma֖ʻ yişĕ̂ráʼé֑l yĕhwá֥h ʼèlòhé֖y⁠nẇ yĕhwá֥h ׀ ʼeẖáֽd׃"],[6,5,"וְ⁠אָ֣הַבְתָּ֔ אֵ֖ת יְהוָ֣ה אֱלֹהֶ֑י⁠ךָ בְּ⁠כָל־לְבָבְ⁠ךָ֥ וּ⁠בְ⁠כָל־נַפְשְׁ⁠ךָ֖ וּ⁠בְ⁠כָל־מְאֹדֶֽ⁠ךָ׃","wĕ⁠ʼá֣habĕţá̇֔ ʼé֖ţ yĕhwá֣h ʼèlòhe֑y⁠ká bĕ̇⁠kál-lĕbábĕ⁠ká֥ ẇ⁠bĕ⁠kál-napĕşĕ̌⁠ká֖ ẇ⁠bĕ⁠kál-mĕʼòdeֽ⁠ká׃"],[6,6,"וְ⁠הָי֞וּ הַ⁠דְּבָרִ֣ים הָ⁠אֵ֗לֶּה אֲשֶׁ֨ר אָנֹכִ֧י מְצַוְּ⁠ךָ֛ הַ⁠יּ֖וֹם עַל־לְבָבֶֽ⁠ךָ׃","wĕ⁠háy֞ẇ ha⁠dĕ̇bári֣ym há⁠ʼé֗lėh ʼàşě֨r ʼánòki֧y mĕẕawĕ̇⁠ká֛ ha⁠ẏ֖wòm ʻal-lĕbábeֽ⁠ká׃"],[6,7,"וְ⁠שִׁנַּנְתָּ֣⁠ם לְ⁠בָנֶ֔י⁠ךָ וְ⁠דִבַּרְתָּ֖ בָּ֑⁠ם בְּ⁠שִׁבְתְּ⁠ךָ֤ בְּ⁠בֵיתֶ֨⁠ךָ֙ וּ⁠בְ⁠לֶכְתְּ⁠ךָ֣ בַ⁠דֶּ֔רֶךְ וּֽ⁠בְ⁠שָׁכְבְּ⁠ךָ֖ וּ⁠בְ⁠קוּמֶֽ⁠ךָ׃","wĕ⁠şǐnȧnĕţá֣̇⁠m lĕ⁠báne֔y⁠ká wĕ⁠dibȧrĕţá֖̇ bá֑̇⁠m bĕ̇⁠şǐbĕţĕ̇⁠ká֤ bĕ̇⁠béyţe֨⁠ká֙ ẇ⁠bĕ⁠lekĕţĕ̇⁠ká֣ ba⁠dė֔rekĕ ẇֽ⁠bĕ⁠şá̌kĕbĕ̇⁠ká֖ ẇ⁠bĕ⁠qẇmeֽ⁠ká׃"],[6,8,"וּ⁠קְשַׁרְתָּ֥⁠ם לְ⁠א֖וֹת עַל־יָדֶ֑⁠ךָ וְ⁠הָי֥וּ לְ⁠טֹטָפֹ֖ת בֵּ֥ין עֵינֶֽי⁠ךָ׃","ẇ⁠qĕşǎrĕţá֥̇⁠m lĕ⁠ʼ֖wòţ ʻal-yáde֑⁠ká wĕ⁠háy֥ẇ lĕ⁠tòtápò֖ţ bé֥̇yn ʻéyneֽy⁠ká׃"],[6,9,"וּ⁠כְתַבְתָּ֛⁠ם עַל־מְזוּזֹ֥ת בֵּיתֶ֖⁠ךָ וּ⁠בִ⁠שְׁעָרֶֽי⁠ךָ׃ס","ẇ⁠kĕţabĕţá֛̇⁠m ʻal-mĕzẇzò֥ţ bé̇yţe֖⁠ká ẇ⁠bi⁠şĕ̌ʻáreֽy⁠ká׃s"],[6,10,"וְ⁠הָיָ֞ה כִּ֥י יְבִיאֲ⁠ךָ֣ ׀ יְהוָ֣ה אֱלֹהֶ֗י⁠ךָ אֶל־הָ⁠אָ֜רֶץ אֲשֶׁ֨ר נִשְׁבַּ֧ע לַ⁠אֲבֹתֶ֛י⁠ךָ לְ⁠אַבְרָהָ֛ם לְ⁠יִצְחָ֥ק וּֽ⁠לְ⁠יַעֲקֹ֖ב לָ֣⁠תֶת לָ֑⁠ךְ עָרִ֛ים גְּדֹלֹ֥ת וְ⁠טֹבֹ֖ת אֲשֶׁ֥ר לֹא־בָנִֽיתָ׃","wĕ⁠háyá֞h ki֥̇y yĕbiyʼà⁠ká֣ ׀ yĕhwá֣h ʼèlòhe֗y⁠ká ʼel-há⁠ʼá֜reẕ ʼàşě֨r nişĕ̌bȧ֧ʻ la⁠ʼàbòţe֛y⁠ká lĕ⁠ʼabĕráhá֛m lĕ⁠yiẕĕẖá֥q ẇֽ⁠lĕ⁠yaʻàqò֖b lá֣⁠ţeţ lá֑⁠kĕ ʻári֛ym gĕ̇dòlò֥ţ wĕ⁠tòbò֖ţ ʼàşě֥r lòʼ-bániֽyţá׃"],[6,11,"וּ⁠בָ֨תִּ֜ים מְלֵאִ֣ים כָּל־טוּב֮ אֲשֶׁ֣ר לֹא־מִלֵּאתָ֒ וּ⁠בֹרֹ֤ת חֲצוּבִים֙ אֲשֶׁ֣ר לֹא־חָצַ֔בְתָּ כְּרָמִ֥ים וְ⁠זֵיתִ֖ים אֲשֶׁ֣ר לֹא־נָטָ֑עְתָּ וְ⁠אָכַלְתָּ֖ וְ⁠שָׂבָֽעְתָּ׃","ẇ⁠bá֨ţi̇֜ym mĕléʼi֣ym ká̇l-tẇb֮ ʼàşě֣r lòʼ-milé̇ʼţá֒ ẇ⁠bòrò֤ţ ẖàẕẇbiym֙ ʼàşě֣r lòʼ-ẖáẕa֔bĕţá̇ kĕ̇rámi֥ym wĕ⁠zéyţi֖ym ʼàşě֣r lòʼ-nátá֑ʻĕţá̇ wĕ⁠ʼákalĕţá֖̇ wĕ⁠şá̂báֽʻĕţá̇׃"],[6,12,"הִשָּׁ֣מֶר לְ⁠ךָ֔ פֶּן־תִּשְׁכַּ֖ח אֶת־יְהוָ֑ה אֲשֶׁ֧ר הוֹצִֽיאֲ⁠ךָ֛ מֵ⁠אֶ֥רֶץ מִצְרַ֖יִם מִ⁠בֵּ֥ית עֲבָדִֽים׃","hişá֣̇̌mer lĕ⁠ká֔ pėn-ţi̇şĕ̌kȧ֖ẖ ʼeţ-yĕhwá֑h ʼàşě֧r hwòẕiֽyʼà⁠ká֛ mé⁠ʼe֥reẕ miẕĕra֖yim mi⁠bé֥̇yţ ʻàbádiֽym׃"],[6,13,"אֶת־יְהוָ֧ה אֱלֹהֶ֛י⁠ךָ תִּירָ֖א וְ⁠אֹת֣⁠וֹ תַעֲבֹ֑ד וּ⁠בִ⁠שְׁמ֖⁠וֹ תִּשָּׁבֵֽעַ׃","ʼeţ-yĕhwá֧h ʼèlòhe֛y⁠ká ţi̇yrá֖ʼ wĕ⁠ʼòţ֣⁠wò ţaʻàbò֑d ẇ⁠bi⁠şĕ̌m֖⁠wò ţi̇şá̇̌béֽʻa׃"],[6,14,"לֹ֣א תֵֽלְכ֔וּ⁠ן אַחֲרֵ֖י אֱלֹהִ֣ים אֲחֵרִ֑ים מֵ⁠אֱלֹהֵי֙ הָֽ⁠עַמִּ֔ים אֲשֶׁ֖ר סְבִיבוֹתֵי⁠כֶֽם׃","lò֣ʼ ţéֽlĕk֔ẇ⁠n ʼaẖàré֖y ʼèlòhi֣ym ʼàẖéri֑ym mé⁠ʼèlòhéy֙ háֽ⁠ʻami̇֔ym ʼàşě֖r sĕbiybwòţéy⁠keֽm׃"],[6,15,"כִּ֣י אֵ֥ל קַנָּ֛א יְהוָ֥ה אֱלֹהֶ֖י⁠ךָ בְּ⁠קִרְבֶּ֑⁠ךָ פֶּן־יֶ֠חֱרֶה אַף־יְהוָ֤ה אֱלֹהֶ֨י⁠ךָ֙ בָּ֔⁠ךְ וְ⁠הִשְׁמִ֣ידְ⁠ךָ֔ מֵ⁠עַ֖ל פְּנֵ֥י הָ⁠אֲדָמָֽה׃ס","ki֣̇y ʼé֥l qaná֛̇ʼ yĕhwá֥h ʼèlòhe֖y⁠ká bĕ̇⁠qirĕbė֑⁠ká pėn-ye֠ẖèreh ʼap-yĕhwá֤h ʼèlòhe֨y⁠ká֙ bá̇֔⁠kĕ wĕ⁠hişĕ̌mi֣ydĕ⁠ká֔ mé⁠ʻa֖l pĕ̇né֥y há⁠ʼàdámáֽh׃s"],[6,16,"לֹ֣א תְנַסּ֔וּ אֶת־יְהוָ֖ה אֱלֹהֵי⁠כֶ֑ם כַּ⁠אֲשֶׁ֥ר נִסִּיתֶ֖ם בַּ⁠מַּסָּֽה׃","lò֣ʼ ţĕnaṡ֔ẇ ʼeţ-yĕhwá֖h ʼèlòhéy⁠ke֑m kȧ⁠ʼàşě֥r nisi̇yţe֖m bȧ⁠mȧsáֽ̇h׃"],[6,17,"שָׁמ֣וֹר תִּשְׁמְר֔וּ⁠ן אֶת־מִצְוֺ֖ת יְהוָ֣ה אֱלֹהֵי⁠כֶ֑ם וְ⁠עֵדֹתָ֥י⁠ו וְ⁠חֻקָּ֖י⁠ו אֲשֶׁ֥ר צִוָּֽ⁠ךְ׃","şá̌m֣wòr ţi̇şĕ̌mĕr֔ẇ⁠n ʼeţ-miẕĕwֺ֖ţ yĕhwá֣h ʼèlòhéy⁠ke֑m wĕ⁠ʻédòţá֥y⁠w wĕ⁠ẖuqá֖̇y⁠w ʼàşě֥r ẕiwáֽ̇⁠kĕ׃"],[6,18,"וְ⁠עָשִׂ֛יתָ הַ⁠יָּשָׁ֥ר וְ⁠הַ⁠טּ֖וֹב בְּ⁠עֵינֵ֣י יְהוָ֑ה לְמַ֨עַן֙ יִ֣יטַב לָ֔⁠ךְ וּ⁠בָ֗אתָ וְ⁠יָֽרַשְׁתָּ֙ אֶת־הָ⁠אָ֣רֶץ הַ⁠טֹּבָ֔ה אֲשֶׁר־נִשְׁבַּ֥ע יְהוָ֖ה לַ⁠אֲבֹתֶֽי⁠ךָ׃","wĕ⁠ʻáşî֛yţá ha⁠yá̇şá֥̌r wĕ⁠ha⁠ṫ֖wòb bĕ̇⁠ʻéyné֣y yĕhwá֑h lĕma֨ʻan֙ yi֣ytab lá֔⁠kĕ ẇ⁠bá֗ʼţá wĕ⁠yáֽraşĕ̌ţá̇֙ ʼeţ-há⁠ʼá֣reẕ ha⁠tò̇bá֔h ʼàşěr-nişĕ̌bȧ֥ʻ yĕhwá֖h la⁠ʼàbòţeֽy⁠ká׃"],[6,19,"לַ⁠הֲדֹ֥ף אֶת־כָּל־אֹיְבֶ֖י⁠ךָ מִ⁠פָּנֶ֑י⁠ךָ כַּ⁠אֲשֶׁ֖ר דִּבֶּ֥ר יְהוָֽה׃ס","la⁠hàdò֥p ʼeţ-ká̇l-ʼòyĕbe֖y⁠ká mi⁠pá̇ne֑y⁠ká kȧ⁠ʼàşě֖r di̇bė֥r yĕhwáֽh׃s"],[6,20,"כִּֽי־יִשְׁאָלְ⁠ךָ֥ בִנְ⁠ךָ֛ מָחָ֖ר לֵ⁠אמֹ֑ר מָ֣ה הָ⁠עֵדֹ֗ת וְ⁠הַֽ⁠חֻקִּים֙ וְ⁠הַ⁠מִּשְׁפָּטִ֔ים אֲשֶׁ֥ר צִוָּ֛ה יְהוָ֥ה אֱלֹהֵ֖י⁠נוּ אֶתְ⁠כֶֽם׃","kiֽ̇y-yişĕ̌ʼálĕ⁠ká֥ binĕ⁠ká֛ máẖá֖r lé⁠ʼmò֑r má֣h há⁠ʻédò֗ţ wĕ⁠haֽ⁠ẖuqi̇ym֙ wĕ⁠ha⁠mi̇şĕ̌pá̇ti֔ym ʼàşě֥r ẕiwá֛̇h yĕhwá֥h ʼèlòhé֖y⁠nẇ ʼeţĕ⁠keֽm׃"],[6,21,"וְ⁠אָמַרְתָּ֣ לְ⁠בִנְ⁠ךָ֔ עֲבָדִ֛ים הָיִ֥ינוּ לְ⁠פַרְעֹ֖ה בְּ⁠מִצְרָ֑יִם וַ⁠יּוֹצִיאֵ֧⁠נוּ יְהוָ֛ה מִ⁠מִּצְרַ֖יִם בְּ⁠יָ֥ד חֲזָקָֽה׃","wĕ⁠ʼámarĕţá֣̇ lĕ⁠binĕ⁠ká֔ ʻàbádi֛ym háyi֥ynẇ lĕ⁠parĕʻò֖h bĕ̇⁠miẕĕrá֑yim wa⁠ẏwòẕiyʼé֧⁠nẇ yĕhwá֛h mi⁠mi̇ẕĕra֖yim bĕ̇⁠yá֥d ẖàzáqáֽh׃"],[6,22,"וַ⁠יִּתֵּ֣ן יְהוָ֡ה אוֹתֹ֣ת וּ֠⁠מֹפְתִים גְּדֹלִ֨ים וְ⁠רָעִ֧ים ׀ בְּ⁠מִצְרַ֛יִם בְּ⁠פַרְעֹ֥ה וּ⁠בְ⁠כָל־בֵּית֖⁠וֹ לְ⁠עֵינֵֽי⁠נוּ׃","wa⁠yi̇ţé֣̇n yĕhwá֡h ʼwòţò֣ţ ẇ֠⁠mòpĕţiym gĕ̇dòli֨ym wĕ⁠ráʻi֧ym ׀ bĕ̇⁠miẕĕra֛yim bĕ̇⁠parĕʻò֥h ẇ⁠bĕ⁠kál-bé̇yţ֖⁠wò lĕ⁠ʻéynéֽy⁠nẇ׃"],[6,23,"וְ⁠אוֹתָ֖⁠נוּ הוֹצִ֣יא מִ⁠שָּׁ֑ם לְמַ֨עַן֙ הָבִ֣יא אֹתָ֔⁠נוּ לָ֤⁠תֶת לָ֨⁠נוּ֙ אֶת־הָ⁠אָ֔רֶץ אֲשֶׁ֥ר נִשְׁבַּ֖ע לַ⁠אֲבֹתֵֽי⁠נוּ׃","wĕ⁠ʼwòţá֖⁠nẇ hwòẕi֣yʼ mi⁠şá֑̇̌m lĕma֨ʻan֙ hábi֣yʼ ʼòţá֔⁠nẇ lá֤⁠ţeţ lá֨⁠nẇ֙ ʼeţ-há⁠ʼá֔reẕ ʼàşě֥r nişĕ̌bȧ֖ʻ la⁠ʼàbòţéֽy⁠nẇ׃"],[6,24,"וַ⁠יְצַוֵּ֣⁠נוּ יְהוָ֗ה לַ⁠עֲשׂוֹת֙ אֶת־כָּל־הַ⁠חֻקִּ֣ים הָ⁠אֵ֔לֶּה לְ⁠יִרְאָ֖ה אֶת־יְהוָ֣ה אֱלֹהֵ֑י⁠נוּ לְ⁠ט֥וֹב לָ֨⁠נוּ֙ כָּל־הַ⁠יָּמִ֔ים לְ⁠חַיֹּתֵ֖⁠נוּ כְּ⁠הַ⁠יּ֥וֹם הַ⁠זֶּֽה׃","wa⁠yĕẕawé֣̇⁠nẇ yĕhwá֗h la⁠ʻàş̂wòţ֙ ʼeţ-ká̇l-ha⁠ẖuqi֣̇ym há⁠ʼé֔lėh lĕ⁠yirĕʼá֖h ʼeţ-yĕhwá֣h ʼèlòhé֑y⁠nẇ lĕ⁠t֥wòb lá֨⁠nẇ֙ ká̇l-ha⁠yá̇mi֔ym lĕ⁠ẖayò̇ţé֖⁠nẇ kĕ̇⁠ha⁠ẏ֥wòm ha⁠zėֽh׃"],[6,25,"וּ⁠צְדָקָ֖ה תִּֽהְיֶה־לָּ֑⁠נוּ כִּֽי־נִשְׁמֹ֨ר לַ⁠עֲשׂ֜וֹת אֶת־כָּל־הַ⁠מִּצְוָ֣ה הַ⁠זֹּ֗את לִ⁠פְנֵ֛י יְהוָ֥ה אֱלֹהֵ֖י⁠נוּ כַּ⁠אֲשֶׁ֥ר צִוָּֽ⁠נוּ׃ס","ẇ⁠ẕĕdáqá֖h ţiֽ̇hĕyeh-lá֑̇⁠nẇ kiֽ̇y-nişĕ̌mò֨r la⁠ʻàş̂֜wòţ ʼeţ-ká̇l-ha⁠mi̇ẕĕwá֣h ha⁠zò̇֗ʼţ li⁠pĕné֛y yĕhwá֥h ʼèlòhé֖y⁠nẇ kȧ⁠ʼàşě֥r ẕiwáֽ̇⁠nẇ׃s"],[7,1,"כִּ֤י יְבִֽיאֲ⁠ךָ֙ יְהוָ֣ה אֱלֹהֶ֔י⁠ךָ אֶל־הָ⁠אָ֕רֶץ אֲשֶׁר־אַתָּ֥ה בָא־שָׁ֖מָּ⁠ה לְ⁠רִשְׁתָּ֑⁠הּ וְ⁠נָשַׁ֣ל גּֽוֹיִם־רַבִּ֣ים ׀ מִ⁠פָּנֶ֡י⁠ךָ הַֽ⁠חִתִּי֩ וְ⁠הַ⁠גִּרְגָּשִׁ֨י וְ⁠הָ⁠אֱמֹרִ֜י וְ⁠הַ⁠כְּנַעֲנִ֣י וְ⁠הַ⁠פְּרִזִּ֗י וְ⁠הַֽ⁠חִוִּי֙ וְ⁠הַ⁠יְבוּסִ֔י שִׁבְעָ֣ה גוֹיִ֔ם רַבִּ֥ים וַ⁠עֲצוּמִ֖ים מִמֶּֽ⁠ךָּ׃","ki֤̇y yĕbiֽyʼà⁠ká֙ yĕhwá֣h ʼèlòhe֔y⁠ká ʼel-há⁠ʼá֕reẕ ʼàşěr-ʼaţá֥̇h báʼ-şá֖̌má̇⁠h lĕ⁠rişĕ̌ţá֑̇⁠ḣ wĕ⁠náşǎ֣l ġֽwòyim-rabi֣̇ym ׀ mi⁠pá̇ne֡y⁠ká haֽ⁠ẖiţi̇y֩ wĕ⁠ha⁠gi̇rĕgá̇şǐ֨y wĕ⁠há⁠ʼèmòri֜y wĕ⁠ha⁠kĕ̇naʻàni֣y wĕ⁠ha⁠pĕ̇rizi̇֗y wĕ⁠haֽ⁠ẖiwi̇y֙ wĕ⁠ha⁠yĕbẇsi֔y şǐbĕʻá֣h gwòyi֔m rabi֥̇ym wa⁠ʻàẕẇmi֖ym mimėֽ⁠ká̇׃"],[7,2,"וּ⁠נְתָנָ֞⁠ם יְהוָ֧ה אֱלֹהֶ֛י⁠ךָ לְ⁠פָנֶ֖י⁠ךָ וְ⁠הִכִּיתָ֑⁠ם הַחֲרֵ֤ם תַּחֲרִים֙ אֹתָ֔⁠ם לֹא־תִכְרֹ֥ת לָ⁠הֶ֛ם בְּרִ֖ית וְ⁠לֹ֥א תְחָנֵּֽ⁠ם׃","ẇ⁠nĕţáná֞⁠m yĕhwá֧h ʼèlòhe֛y⁠ká lĕ⁠páne֖y⁠ká wĕ⁠hiki̇yţá֑⁠m haẖàré֤m ţȧẖàriym֙ ʼòţá֔⁠m lòʼ-ţikĕrò֥ţ lá⁠he֛m bĕ̇ri֖yţ wĕ⁠lò֥ʼ ţĕẖánéֽ̇⁠m׃"],[7,3,"וְ⁠לֹ֥א תִתְחַתֵּ֖ן בָּ֑⁠ם בִּתְּ⁠ךָ֙ לֹא־תִתֵּ֣ן לִ⁠בְנ֔⁠וֹ וּ⁠בִתּ֖⁠וֹ לֹא־תִקַּ֥ח לִ⁠בְנֶֽ⁠ךָ׃","wĕ⁠lò֥ʼ ţiţĕẖaţé֖̇n bá֑̇⁠m bi̇ţĕ̇⁠ká֙ lòʼ-ţiţé֣̇n li⁠bĕn֔⁠wò ẇ⁠biţ֖̇⁠wò lòʼ-ţiqȧ֥ẖ li⁠bĕneֽ⁠ká׃"],[7,4,"כִּֽי־יָסִ֤יר אֶת־בִּנְ⁠ךָ֙ מֵֽ⁠אַחֲרַ֔⁠י וְ⁠עָבְד֖וּ אֱלֹהִ֣ים אֲחֵרִ֑ים וְ⁠חָרָ֤ה אַף־יְהוָה֙ בָּ⁠כֶ֔ם וְ⁠הִשְׁמִידְ⁠ךָ֖ מַהֵֽר׃","kiֽ̇y-yási֤yr ʼeţ-bi̇nĕ⁠ká֙ méֽ⁠ʼaẖàra֔⁠y wĕ⁠ʻábĕd֖ẇ ʼèlòhi֣ym ʼàẖéri֑ym wĕ⁠ẖárá֤h ʼap-yĕhwáh֙ bá̇⁠ke֔m wĕ⁠hişĕ̌miydĕ⁠ká֖ mahéֽr׃"],[7,5,"כִּֽי־אִם־כֹּ֤ה תַעֲשׂוּ֙ לָ⁠הֶ֔ם מִזְבְּחֹתֵי⁠הֶ֣ם תִּתֹּ֔צוּ וּ⁠מַצֵּבֹתָ֖⁠ם תְּשַׁבֵּ֑רוּ וַ⁠אֲשֵֽׁירֵ⁠הֶם֙ תְּגַדֵּע֔וּ⁠ן וּ⁠פְסִילֵי⁠הֶ֖ם תִּשְׂרְפ֥וּ⁠ן בָּ⁠אֵֽשׁ׃","kiֽ̇y-ʼim-kò֤̇h ţaʻàş̂ẇ֙ lá⁠he֔m mizĕbĕ̇ẖòţéy⁠he֣m ţi̇ţò̇֔ẕẇ ẇ⁠maẕé̇bòţá֖⁠m ţĕ̇şǎbé֑̇rẇ wa⁠ʼàşéֽ̌yré⁠hem֙ ţĕ̇gadé̇ʻ֔ẇ⁠n ẇ⁠pĕsiyléy⁠he֖m ţi̇şĕ̂rĕp֥ẇ⁠n bá̇⁠ʼéֽş̌׃"],[7,6,"כִּ֣י עַ֤ם קָדוֹשׁ֙ אַתָּ֔ה לַ⁠יהוָ֖ה אֱלֹהֶ֑י⁠ךָ בְּ⁠ךָ֞ בָּחַ֣ר ׀ יְהוָ֣ה אֱלֹהֶ֗י⁠ךָ לִ⁠הְי֥וֹת ל⁠וֹ֙ לְ⁠עַ֣ם סְגֻלָּ֔ה מִ⁠כֹּל֙ הָֽ⁠עַמִּ֔ים אֲשֶׁ֖ר עַל־פְּנֵ֥י הָ⁠אֲדָמָֽה׃ס","ki֣̇y ʻa֤m qádwòş̌֙ ʼaţá̇֔h la⁠yhwá֖h ʼèlòhe֑y⁠ká bĕ̇⁠ká֞ bá̇ẖa֣r ׀ yĕhwá֣h ʼèlòhe֗y⁠ká li⁠hĕy֥wòţ l⁠wò֙ lĕ⁠ʻa֣m sĕgulá̇֔h mi⁠kò̇l֙ háֽ⁠ʻami̇֔ym ʼàşě֖r ʻal-pĕ̇né֥y há⁠ʼàdámáֽh׃s"],[7,7,"לֹ֣א מֵֽ⁠רֻבְּ⁠כֶ֞ם מִ⁠כָּל־הָֽ⁠עַמִּ֗ים חָשַׁ֧ק יְהוָ֛ה בָּ⁠כֶ֖ם וַ⁠יִּבְחַ֣ר בָּ⁠כֶ֑ם כִּֽי־אַתֶּ֥ם הַ⁠מְעַ֖ט מִ⁠כָּל־הָ⁠עַמִּֽים׃","lò֣ʼ méֽ⁠rubĕ̇⁠ke֞m mi⁠ká̇l-háֽ⁠ʻami̇֗ym ẖáşǎ֧q yĕhwá֛h bá̇⁠ke֖m wa⁠yi̇bĕẖa֣r bá̇⁠ke֑m kiֽ̇y-ʼaţė֥m ha⁠mĕʻa֖t mi⁠ká̇l-há⁠ʻamiֽ̇ym׃"],[7,8,"כִּי֩ מֵֽ⁠אַהֲבַ֨ת יְהוָ֜ה אֶתְ⁠כֶ֗ם וּ⁠מִ⁠שָּׁמְר֤⁠וּ אֶת־הַ⁠שְּׁבֻעָה֙ אֲשֶׁ֤ר נִשְׁבַּע֙ לַ⁠אֲבֹ֣תֵי⁠כֶ֔ם הוֹצִ֧יא יְהוָ֛ה אֶתְ⁠כֶ֖ם בְּ⁠יָ֣ד חֲזָקָ֑ה וַֽ⁠יִּפְדְּ⁠ךָ֙ מִ⁠בֵּ֣ית עֲבָדִ֔ים מִ⁠יַּ֖ד פַּרְעֹ֥ה מֶֽלֶךְ־מִצְרָֽיִם׃","ki̇y֩ méֽ⁠ʼahàba֨ţ yĕhwá֜h ʼeţĕ⁠ke֗m ẇ⁠mi⁠şá̇̌mĕr֤⁠ẇ ʼeţ-ha⁠şĕ̇̌buʻáh֙ ʼàşě֤r nişĕ̌bȧʻ֙ la⁠ʼàbò֣ţéy⁠ke֔m hwòẕi֧yʼ yĕhwá֛h ʼeţĕ⁠ke֖m bĕ̇⁠yá֣d ẖàzáqá֑h waֽ⁠yi̇pĕdĕ̇⁠ká֙ mi⁠bé֣̇yţ ʻàbádi֔ym mi⁠yȧ֖d pȧrĕʻò֥h meֽlekĕ-miẕĕráֽyim׃"],[7,9,"וְ⁠יָ֣דַעְתָּ֔ כִּֽי־יְהוָ֥ה אֱלֹהֶ֖י⁠ךָ ה֣וּא הָֽ⁠אֱלֹהִ֑ים הָ⁠אֵל֙ הַֽ⁠נֶּאֱמָ֔ן שֹׁמֵ֧ר הַ⁠בְּרִ֣ית וְ⁠הַ⁠חֶ֗סֶד לְ⁠אֹהֲבָ֛י⁠ו וּ⁠לְ⁠שֹׁמְרֵ֥י מצותו לְ⁠אֶ֥לֶף דּֽוֹר׃","wĕ⁠yá֣daʻĕţá̇֔ kiֽ̇y-yĕhwá֥h ʼèlòhe֖y⁠ká h֣ẇʼ háֽ⁠ʼèlòhi֑ym há⁠ʼél֙ haֽ⁠nėʼèmá֔n şò̌mé֧r ha⁠bĕ̇ri֣yţ wĕ⁠ha⁠ẖe֗sed lĕ⁠ʼòhàbá֛y⁠w ẇ⁠lĕ⁠şò̌mĕré֥y mẕwţw lĕ⁠ʼe֥lep ḋֽwòr׃"],[7,10,"וּ⁠מְשַׁלֵּ֧ם לְ⁠שֹׂנְאָ֛י⁠ו אֶל־פָּנָ֖י⁠ו לְ⁠הַאֲבִיד֑⁠וֹ לֹ֤א יְאַחֵר֙ לְ⁠שֹׂ֣נְא֔⁠וֹ אֶל־פָּנָ֖י⁠ו יְשַׁלֶּם־לֽ⁠וֹ׃","ẇ⁠mĕşǎlé֧̇m lĕ⁠şò̂nĕʼá֛y⁠w ʼel-pá̇ná֖y⁠w lĕ⁠haʼàbiyd֑⁠wò lò֤ʼ yĕʼaẖér֙ lĕ⁠şò֣̂nĕʼ֔⁠wò ʼel-pá̇ná֖y⁠w yĕşǎlėm-lֽ⁠wò׃"],[7,11,"וְ⁠שָׁמַרְתָּ֨ אֶת־הַ⁠מִּצְוָ֜ה וְ⁠אֶת־הַֽ⁠חֻקִּ֣ים וְ⁠אֶת־הַ⁠מִּשְׁפָּטִ֗ים אֲשֶׁ֨ר אָנֹכִ֧י מְצַוְּ⁠ךָ֛ הַ⁠יּ֖וֹם לַ⁠עֲשׂוֹתָֽ⁠ם׃פ","wĕ⁠şá̌marĕţá̇֨ ʼeţ-ha⁠mi̇ẕĕwá֜h wĕ⁠ʼeţ-haֽ⁠ẖuqi֣̇ym wĕ⁠ʼeţ-ha⁠mi̇şĕ̌pá̇ti֗ym ʼàşě֨r ʼánòki֧y mĕẕawĕ̇⁠ká֛ ha⁠ẏ֖wòm la⁠ʻàş̂wòţáֽ⁠m׃p"],[7,12,"וְ⁠הָיָ֣ה ׀ עֵ֣קֶב תִּשְׁמְע֗וּ⁠ן אֵ֤ת הַ⁠מִּשְׁפָּטִים֙ הָ⁠אֵ֔לֶּה וּ⁠שְׁמַרְתֶּ֥ם וַ⁠עֲשִׂיתֶ֖ם אֹתָ֑⁠ם וְ⁠שָׁמַר֩ יְהוָ֨ה אֱלֹהֶ֜י⁠ךָ לְ⁠ךָ֗ אֶֽת־הַ⁠בְּרִית֙ וְ⁠אֶת־הַ⁠חֶ֔סֶד אֲשֶׁ֥ר נִשְׁבַּ֖ע לַ⁠אֲבֹתֶֽי⁠ךָ׃","wĕ⁠háyá֣h ׀ ʻé֣qeb ţi̇şĕ̌mĕʻ֗ẇ⁠n ʼé֤ţ ha⁠mi̇şĕ̌pá̇tiym֙ há⁠ʼé֔lėh ẇ⁠şĕ̌marĕţė֥m wa⁠ʻàşîyţe֖m ʼòţá֑⁠m wĕ⁠şá̌mar֩ yĕhwá֨h ʼèlòhe֜y⁠ká lĕ⁠ká֗ ʼeֽţ-ha⁠bĕ̇riyţ֙ wĕ⁠ʼeţ-ha⁠ẖe֔sed ʼàşě֥r nişĕ̌bȧ֖ʻ la⁠ʼàbòţeֽy⁠ká׃"],[7,13,"וַ⁠אֲהֵ֣בְ⁠ךָ֔ וּ⁠בֵרַכְ⁠ךָ֖ וְ⁠הִרְבֶּ֑⁠ךָ וּ⁠בֵרַ֣ךְ פְּרִֽי־בִטְנְ⁠ךָ֣ וּ⁠פְרִֽי־אַ֠דְמָתֶ⁠ךָ דְּגָ֨נְ⁠ךָ֜ וְ⁠תִֽירֹשְׁ⁠ךָ֣ וְ⁠יִצְהָרֶ֗⁠ךָ שְׁגַר־אֲלָפֶ֨י⁠ךָ֙ וְ⁠עַשְׁתְּרֹ֣ת צֹאנֶ֔⁠ךָ עַ֚ל הָֽ⁠אֲדָמָ֔ה אֲשֶׁר־נִשְׁבַּ֥ע לַ⁠אֲבֹתֶ֖י⁠ךָ לָ֥⁠תֶת לָֽ⁠ךְ׃","wa⁠ʼàhé֣bĕ⁠ká֔ ẇ⁠bérakĕ⁠ká֖ wĕ⁠hirĕbė֑⁠ká ẇ⁠béra֣kĕ pĕ̇riֽy-bitĕnĕ⁠ká֣ ẇ⁠pĕriֽy-ʼa֠dĕmáţe⁠ká dĕ̇gá֨nĕ⁠ká֜ wĕ⁠ţiֽyròşĕ̌⁠ká֣ wĕ⁠yiẕĕháre֗⁠ká şĕ̌gar-ʼàlápe֨y⁠ká֙ wĕ⁠ʻaşĕ̌ţĕ̇rò֣ţ ẕòʼne֔⁠ká ʻa֚l háֽ⁠ʼàdámá֔h ʼàşěr-nişĕ̌bȧ֥ʻ la⁠ʼàbòţe֖y⁠ká lá֥⁠ţeţ láֽ⁠kĕ׃"],[7,14,"בָּר֥וּךְ תִּֽהְיֶ֖ה מִ⁠כָּל־הָ⁠עַמִּ֑ים לֹא־יִהְיֶ֥ה בְ⁠ךָ֛ עָקָ֥ר וַֽ⁠עֲקָרָ֖ה וּ⁠בִ⁠בְהֶמְתֶּֽ⁠ךָ׃","bá̇r֥ẇkĕ ţiֽ̇hĕye֖h mi⁠ká̇l-há⁠ʻami֑̇ym lòʼ-yihĕye֥h bĕ⁠ká֛ ʻáqá֥r waֽ⁠ʻàqárá֖h ẇ⁠bi⁠bĕhemĕţėֽ⁠ká׃"],[7,15,"וְ⁠הֵסִ֧יר יְהוָ֛ה מִמְּ⁠ךָ֖ כָּל־חֹ֑לִי וְ⁠כָל־מַדְוֵי֩ מִצְרַ֨יִם הָ⁠רָעִ֜ים אֲשֶׁ֣ר יָדַ֗עְתָּ לֹ֤א יְשִׂימָ⁠ם֙ בָּ֔⁠ךְ וּ⁠נְתָנָ֖⁠ם בְּ⁠כָל־שֹׂנְאֶֽי⁠ךָ׃","wĕ⁠hési֧yr yĕhwá֛h mimĕ̇⁠ká֖ ká̇l-ẖò֑liy wĕ⁠kál-madĕwéy֩ miẕĕra֨yim há⁠ráʻi֜ym ʼàşě֣r yáda֗ʻĕţá̇ lò֤ʼ yĕşîymá⁠m֙ bá̇֔⁠kĕ ẇ⁠nĕţáná֖⁠m bĕ̇⁠kál-şò̂nĕʼeֽy⁠ká׃"],[7,16,"וְ⁠אָכַלְתָּ֣ אֶת־כָּל־הָֽ⁠עַמִּ֗ים אֲשֶׁ֨ר יְהוָ֤ה אֱלֹהֶ֨י⁠ךָ֙ נֹתֵ֣ן לָ֔⁠ךְ לֹא־תָחֹ֥ס עֵֽינְ⁠ךָ֖ עֲלֵי⁠הֶ֑ם וְ⁠לֹ֤א תַעֲבֹד֙ אֶת־אֱלֹ֣הֵי⁠הֶ֔ם כִּֽי־מוֹקֵ֥שׁ ה֖וּא לָֽ⁠ךְ׃ס","wĕ⁠ʼákalĕţá֣̇ ʼeţ-ká̇l-háֽ⁠ʻami̇֗ym ʼàşě֨r yĕhwá֤h ʼèlòhe֨y⁠ká֙ nòţé֣n lá֔⁠kĕ lòʼ-ţáẖò֥s ʻéֽynĕ⁠ká֖ ʻàléy⁠he֑m wĕ⁠lò֤ʼ ţaʻàbòd֙ ʼeţ-ʼèlò֣héy⁠he֔m kiֽ̇y-mwòqé֥ş̌ h֖ẇʼ láֽ⁠kĕ׃s"],[7,17,"כִּ֤י תֹאמַר֙ בִּ⁠לְבָ֣בְ⁠ךָ֔ רַבִּ֛ים הַ⁠גּוֹיִ֥ם הָ⁠אֵ֖לֶּה מִמֶּ֑⁠נִּי אֵיכָ֥ה אוּכַ֖ל לְ⁠הוֹרִישָֽׁ⁠ם׃","ki֤̇y ţòʼmar֙ bi̇⁠lĕbá֣bĕ⁠ká֔ rabi֛̇ym ha⁠ġwòyi֥m há⁠ʼé֖lėh mimė֑⁠ni̇y ʼéyká֥h ʼẇka֖l lĕ⁠hwòriyşáֽ̌⁠m׃"],[7,18,"לֹ֥א תִירָ֖א מֵ⁠הֶ֑ם זָכֹ֣ר תִּזְכֹּ֗ר אֵ֤ת אֲשֶׁר־עָשָׂה֙ יְהוָ֣ה אֱלֹהֶ֔י⁠ךָ לְ⁠פַרְעֹ֖ה וּ⁠לְ⁠כָל־מִצְרָֽיִם׃","lò֥ʼ ţiyrá֖ʼ mé⁠he֑m zákò֣r ţi̇zĕkò̇֗r ʼé֤ţ ʼàşěr-ʻáşá̂h֙ yĕhwá֣h ʼèlòhe֔y⁠ká lĕ⁠parĕʻò֖h ẇ⁠lĕ⁠kál-miẕĕráֽyim׃"],[7,19,"הַ⁠מַּסֹּ֨ת הַ⁠גְּדֹלֹ֜ת אֲשֶׁר־רָא֣וּ עֵינֶ֗י⁠ךָ וְ⁠הָ⁠אֹתֹ֤ת וְ⁠הַ⁠מֹּֽפְתִים֙ וְ⁠הַ⁠יָּ֤ד הַ⁠חֲזָקָה֙ וְ⁠הַ⁠זְּרֹ֣עַ הַ⁠נְּטוּיָ֔ה אֲשֶׁ֥ר הוֹצִֽאֲ⁠ךָ֖ יְהוָ֣ה אֱלֹהֶ֑י⁠ךָ כֵּֽן־יַעֲשֶׂ֞ה יְהוָ֤ה אֱלֹהֶ֨י⁠ךָ֙ לְ⁠כָל־הָ֣⁠עַמִּ֔ים אֲשֶׁר־אַתָּ֥ה יָרֵ֖א מִ⁠פְּנֵי⁠הֶֽם׃","ha⁠mȧsò̇֨ţ ha⁠gĕ̇dòlò֜ţ ʼàşěr-ráʼ֣ẇ ʻéyne֗y⁠ká wĕ⁠há⁠ʼòţò֤ţ wĕ⁠ha⁠mòֽ̇pĕţiym֙ wĕ⁠ha⁠yá֤̇d ha⁠ẖàzáqáh֙ wĕ⁠ha⁠zĕ̇rò֣ʻa ha⁠nĕ̇tẇyá֔h ʼàşě֥r hwòẕiֽʼà⁠ká֖ yĕhwá֣h ʼèlòhe֑y⁠ká kéֽ̇n-yaʻàşê֞h yĕhwá֤h ʼèlòhe֨y⁠ká֙ lĕ⁠kál-há֣⁠ʻami̇֔ym ʼàşěr-ʼaţá֥̇h yáré֖ʼ mi⁠pĕ̇néy⁠heֽm׃"],[7,20,"וְ⁠גַם֙ אֶת־הַ⁠צִּרְעָ֔ה יְשַׁלַּ֛ח יְהוָ֥ה אֱלֹהֶ֖י⁠ךָ בָּ֑⁠ם עַד־אֲבֹ֗ד הַ⁠נִּשְׁאָרִ֛ים וְ⁠הַ⁠נִּסְתָּרִ֖ים מִ⁠פָּנֶֽי⁠ךָ׃","wĕ⁠gam֙ ʼeţ-ha⁠ẕi̇rĕʻá֔h yĕşǎlȧ֛ẖ yĕhwá֥h ʼèlòhe֖y⁠ká bá֑̇⁠m ʻad-ʼàbò֗d ha⁠ni̇şĕ̌ʼári֛ym wĕ⁠ha⁠ni̇sĕţá̇ri֖ym mi⁠pá̇neֽy⁠ká׃"],[7,21,"לֹ֥א תַעֲרֹ֖ץ מִ⁠פְּנֵי⁠הֶ֑ם כִּֽי־יְהוָ֤ה אֱלֹהֶ֨י⁠ךָ֙ בְּ⁠קִרְבֶּ֔⁠ךָ אֵ֥ל גָּד֖וֹל וְ⁠נוֹרָֽא׃","lò֥ʼ ţaʻàrò֖ẕ mi⁠pĕ̇néy⁠he֑m kiֽ̇y-yĕhwá֤h ʼèlòhe֨y⁠ká֙ bĕ̇⁠qirĕbė֔⁠ká ʼé֥l gá̇d֖wòl wĕ⁠nwòráֽʼ׃"],[7,22,"וְ⁠נָשַׁל֩ יְהוָ֨ה אֱלֹהֶ֜י⁠ךָ אֶת־הַ⁠גּוֹיִ֥ם הָ⁠אֵ֛ל מִ⁠פָּנֶ֖י⁠ךָ מְעַ֣ט מְעָ֑ט לֹ֤א תוּכַל֙ כַּלֹּתָ֣⁠ם מַהֵ֔ר פֶּן־תִּרְבֶּ֥ה עָלֶ֖י⁠ךָ חַיַּ֥ת הַ⁠שָּׂדֶֽה׃","wĕ⁠náşǎl֩ yĕhwá֨h ʼèlòhe֜y⁠ká ʼeţ-ha⁠ġwòyi֥m há⁠ʼé֛l mi⁠pá̇ne֖y⁠ká mĕʻa֣t mĕʻá֑t lò֤ʼ ţẇkal֙ kȧlò̇ţá֣⁠m mahé֔r pėn-ţi̇rĕbė֥h ʻále֖y⁠ká ẖayȧ֥ţ ha⁠şá̇̂deֽh׃"],[7,23,"וּ⁠נְתָנָ֛⁠ם יְהוָ֥ה אֱלֹהֶ֖י⁠ךָ לְ⁠פָנֶ֑י⁠ךָ וְ⁠הָמָ⁠ם֙ מְהוּמָ֣ה גְדֹלָ֔ה עַ֖ד הִשָּׁמְדָֽ⁠ם׃","ẇ⁠nĕţáná֛⁠m yĕhwá֥h ʼèlòhe֖y⁠ká lĕ⁠páne֑y⁠ká wĕ⁠hámá⁠m֙ mĕhẇmá֣h gĕdòlá֔h ʻa֖d hişá̇̌mĕdáֽ⁠m׃"],[7,24,"וְ⁠נָתַ֤ן מַלְכֵי⁠הֶם֙ בְּ⁠יָדֶ֔⁠ךָ וְ⁠הַאֲבַדְתָּ֣ אֶת־שְׁמָ֔⁠ם מִ⁠תַּ֖חַת הַ⁠שָּׁמָ֑יִם לֹֽא־יִתְיַצֵּ֥ב אִישׁ֙ בְּ⁠פָנֶ֔י⁠ךָ עַ֥ד הִשְׁמִֽדְ⁠ךָ֖ אֹתָֽ⁠ם׃","wĕ⁠náţa֤n malĕkéy⁠hem֙ bĕ̇⁠yáde֔⁠ká wĕ⁠haʼàbadĕţá֣̇ ʼeţ-şĕ̌má֔⁠m mi⁠ţȧ֖ẖaţ ha⁠şá̇̌má֑yim lòֽʼ-yiţĕyaẕé֥̇b ʼiyş̌֙ bĕ̇⁠páne֔y⁠ká ʻa֥d hişĕ̌miֽdĕ⁠ká֖ ʼòţáֽ⁠m׃"],[7,25,"פְּסִילֵ֥י אֱלֹהֵי⁠הֶ֖ם תִּשְׂרְפ֣וּ⁠ן בָּ⁠אֵ֑שׁ לֹֽא־תַחְמֹד֩ כֶּ֨סֶף וְ⁠זָהָ֤ב עֲלֵי⁠הֶם֙ וְ⁠לָקַחְתָּ֣ לָ֔⁠ךְ פֶּ֚ן תִּוָּקֵ֣שׁ בּ֔⁠וֹ כִּ֧י תוֹעֲבַ֛ת יְהוָ֥ה אֱלֹהֶ֖י⁠ךָ הֽוּא׃","pĕ̇siylé֥y ʼèlòhéy⁠he֖m ţi̇şĕ̂rĕp֣ẇ⁠n bá̇⁠ʼé֑ş̌ lòֽʼ-ţaẖĕmòd֩ kė֨sep wĕ⁠záhá֤b ʻàléy⁠hem֙ wĕ⁠láqaẖĕţá֣̇ lá֔⁠kĕ pė֚n ţi̇wá̇qé֣ş̌ ḃ֔⁠wò ki֧̇y ţwòʻàba֛ţ yĕhwá֥h ʼèlòhe֖y⁠ká hֽẇʼ׃"],[7,26,"וְ⁠לֹא־תָבִ֤יא תֽוֹעֵבָה֙ אֶל־בֵּיתֶ֔⁠ךָ וְ⁠הָיִ֥יתָ חֵ֖רֶם כָּמֹ֑⁠הוּ שַׁקֵּ֧ץ ׀ תְּשַׁקְּצֶ֛⁠נּוּ וְ⁠תַעֵ֥ב ׀ תְּֽתַעֲבֶ֖⁠נּוּ כִּי־חֵ֥רֶם הֽוּא׃פ","wĕ⁠lòʼ-ţábi֤yʼ ţֽwòʻébáh֙ ʼel-bé̇yţe֔⁠ká wĕ⁠háyi֥yţá ẖé֖rem ká̇mò֑⁠hẇ şǎqé֧̇ẕ ׀ ţĕ̇şǎqĕ̇ẕe֛⁠ṅẇ wĕ⁠ţaʻé֥b ׀ ţĕֽ̇ţaʻàbe֖⁠ṅẇ ki̇y-ẖé֥rem hֽẇʼ׃p"],[8,1,"כָּל־הַ⁠מִּצְוָ֗ה אֲשֶׁ֨ר אָנֹכִ֧י מְצַוְּ⁠ךָ֛ הַ⁠יּ֖וֹם תִּשְׁמְר֣וּ⁠ן לַ⁠עֲשׂ֑וֹת לְמַ֨עַן תִּֽחְי֜וּ⁠ן וּ⁠רְבִיתֶ֗ם וּ⁠בָאתֶם֙ וִֽ⁠ירִשְׁתֶּ֣ם אֶת־הָ⁠אָ֔רֶץ אֲשֶׁר־נִשְׁבַּ֥ע יְהוָ֖ה לַ⁠אֲבֹתֵי⁠כֶֽם׃","ká̇l-ha⁠mi̇ẕĕwá֗h ʼàşě֨r ʼánòki֧y mĕẕawĕ̇⁠ká֛ ha⁠ẏ֖wòm ţi̇şĕ̌mĕr֣ẇ⁠n la⁠ʻàş֑̂wòţ lĕma֨ʻan ţiֽ̇ẖĕy֜ẇ⁠n ẇ⁠rĕbiyţe֗m ẇ⁠báʼţem֙ wiֽ⁠yrişĕ̌ţė֣m ʼeţ-há⁠ʼá֔reẕ ʼàşěr-nişĕ̌bȧ֥ʻ yĕhwá֖h la⁠ʼàbòţéy⁠keֽm׃"],[8,2,"וְ⁠זָכַרְתָּ֣ אֶת־כָּל־הַ⁠דֶּ֗רֶךְ אֲשֶׁ֨ר הֹלִֽיכֲ⁠ךָ֜ יְהוָ֧ה אֱלֹהֶ֛י⁠ךָ זֶ֛ה אַרְבָּעִ֥ים שָׁנָ֖ה בַּ⁠מִּדְבָּ֑ר לְמַ֨עַן עַנֹּֽתְ⁠ךָ֜ לְ⁠נַסֹּֽתְ⁠ךָ֗ לָ⁠דַ֜עַת אֶת־אֲשֶׁ֧ר בִּֽ⁠לְבָבְ⁠ךָ֛ הֲ⁠תִשְׁמֹ֥ר מצות⁠ו אִם־לֹֽא׃","wĕ⁠zákarĕţá֣̇ ʼeţ-ká̇l-ha⁠dė֗rekĕ ʼàşě֨r hòliֽykà⁠ká֜ yĕhwá֧h ʼèlòhe֛y⁠ká ze֛h ʼarĕbá̇ʻi֥ym şá̌ná֖h bȧ⁠mi̇dĕbá֑̇r lĕma֨ʻan ʻanòֽ̇ţĕ⁠ká֜ lĕ⁠nasòֽ̇ţĕ⁠ká֗ lá⁠da֜ʻaţ ʼeţ-ʼàşě֧r biֽ̇⁠lĕbábĕ⁠ká֛ hà⁠ţişĕ̌mò֥r mẕwţ⁠w ʼim-lòֽʼ׃"],[8,3,"וַֽ⁠יְעַנְּ⁠ךָ֮ וַ⁠יַּרְעִבֶ⁠ךָ֒ וַ⁠יַּֽאֲכִֽלְ⁠ךָ֤ אֶת הַ⁠מָּן֙ אֲשֶׁ֣ר לֹא־יָדַ֔עְתָּ וְ⁠לֹ֥א יָדְע֖וּ⁠ן אֲבֹתֶ֑י⁠ךָ לְמַ֣עַן הוֹדִֽעֲ⁠ךָ֗ כִּ֠י לֹ֣א עַל־הַ⁠לֶּ֤חֶם לְ⁠בַדּ⁠וֹ֙ יִחְיֶ֣ה הָֽ⁠אָדָ֔ם כִּ֛י עַל־כָּל־מוֹצָ֥א פִֽי־יְהוָ֖ה יִחְיֶ֥ה הָ⁠אָדָֽם׃","waֽ⁠yĕʻanĕ̇⁠ká֮ wa⁠yȧrĕʻibe⁠ká֒ wa⁠yȧֽʼàkiֽlĕ⁠ká֤ ʼeţ ha⁠má̇n֙ ʼàşě֣r lòʼ-yáda֔ʻĕţá̇ wĕ⁠lò֥ʼ yádĕʻ֖ẇ⁠n ʼàbòţe֑y⁠ká lĕma֣ʻan hwòdiֽʻà⁠ká֗ ki̇֠y lò֣ʼ ʻal-ha⁠lė֤ẖem lĕ⁠baḋ⁠wò֙ yiẖĕye֣h háֽ⁠ʼádá֔m ki֛̇y ʻal-ká̇l-mwòẕá֥ʼ piֽy-yĕhwá֖h yiẖĕye֥h há⁠ʼádáֽm׃"],[8,4,"שִׂמְלָ֨תְ⁠ךָ֜ לֹ֤א בָֽלְתָה֙ מֵֽ⁠עָלֶ֔י⁠ךָ וְ⁠רַגְלְ⁠ךָ֖ לֹ֣א בָצֵ֑קָה זֶ֖ה אַרְבָּעִ֥ים שָׁנָֽה׃","şîmĕlá֨ţĕ⁠ká֜ lò֤ʼ báֽlĕţáh֙ méֽ⁠ʻále֔y⁠ká wĕ⁠ragĕlĕ⁠ká֖ lò֣ʼ báẕé֑qáh ze֖h ʼarĕbá̇ʻi֥ym şá̌náֽh׃"],[8,5,"וְ⁠יָדַעְתָּ֖ עִם־לְבָבֶ֑⁠ךָ כִּ֗י כַּ⁠אֲשֶׁ֨ר יְיַסֵּ֥ר אִישׁ֙ אֶת־בְּנ֔⁠וֹ יְהוָ֥ה אֱלֹהֶ֖י⁠ךָ מְיַסְּרֶֽ⁠ךָּ׃","wĕ⁠yádaʻĕţá֖̇ ʻim-lĕbábe֑⁠ká ki̇֗y kȧ⁠ʼàşě֨r yĕyasé֥̇r ʼiyş̌֙ ʼeţ-bĕ̇n֔⁠wò yĕhwá֥h ʼèlòhe֖y⁠ká mĕyasĕ̇reֽ⁠ká̇׃"],[8,6,"וְ⁠שָׁ֣מַרְתָּ֔ אֶת־מִצְוֺ֖ת יְהוָ֣ה אֱלֹהֶ֑י⁠ךָ לָ⁠לֶ֥כֶת בִּ⁠דְרָכָ֖י⁠ו וּ⁠לְ⁠יִרְאָ֥ה אֹתֽ⁠וֹ׃","wĕ⁠şá֣̌marĕţá̇֔ ʼeţ-miẕĕwֺ֖ţ yĕhwá֣h ʼèlòhe֑y⁠ká lá⁠le֥keţ bi̇⁠dĕráká֖y⁠w ẇ⁠lĕ⁠yirĕʼá֥h ʼòţֽ⁠wò׃"],[8,7,"כִּ֚י יְהוָ֣ה אֱלֹהֶ֔י⁠ךָ מְבִֽיאֲ⁠ךָ֖ אֶל־אֶ֣רֶץ טוֹבָ֑ה אֶ֚רֶץ נַ֣חֲלֵי מָ֔יִם עֲיָנֹת֙ וּ⁠תְהֹמֹ֔ת יֹצְאִ֥ים בַּ⁠בִּקְעָ֖ה וּ⁠בָ⁠הָֽר׃","ki֚̇y yĕhwá֣h ʼèlòhe֔y⁠ká mĕbiֽyʼà⁠ká֖ ʼel-ʼe֣reẕ twòbá֑h ʼe֚reẕ na֣ẖàléy má֔yim ʻàyánòţ֙ ẇ⁠ţĕhòmò֔ţ yòẕĕʼi֥ym bȧ⁠bi̇qĕʻá֖h ẇ⁠bá⁠háֽr׃"],[8,8,"אֶ֤רֶץ חִטָּה֙ וּ⁠שְׂעֹרָ֔ה וְ⁠גֶ֥פֶן וּ⁠תְאֵנָ֖ה וְ⁠רִמּ֑וֹן אֶֽרֶץ־זֵ֥ית שֶׁ֖מֶן וּ⁠דְבָֽשׁ׃","ʼe֤reẕ ẖitá̇h֙ ẇ⁠şĕ̂ʻòrá֔h wĕ⁠ge֥pen ẇ⁠ţĕʼéná֖h wĕ⁠riṁ֑wòn ʼeֽreẕ-zé֥yţ şě֖men ẇ⁠dĕbáֽş̌׃"],[8,9,"אֶ֗רֶץ אֲשֶׁ֨ר לֹ֤א בְ⁠מִסְכֵּנֻת֙ תֹּֽאכַל־בָּ֣⁠הּ לֶ֔חֶם לֹֽא־תֶחְסַ֥ר כֹּ֖ל בָּ֑⁠הּ אֶ֚רֶץ אֲשֶׁ֣ר אֲבָנֶ֣י⁠הָ בַרְזֶ֔ל וּ⁠מֵ⁠הֲרָרֶ֖י⁠הָ תַּחְצֹ֥ב נְחֹֽשֶׁת׃","ʼe֗reẕ ʼàşě֨r lò֤ʼ bĕ⁠misĕké̇nuţ֙ ţòֽ̇ʼkal-bá֣̇⁠ḣ le֔ẖem lòֽʼ-ţeẖĕsa֥r kò֖̇l bá֑̇⁠ḣ ʼe֚reẕ ʼàşě֣r ʼàbáne֣y⁠há barĕze֔l ẇ⁠mé⁠hàráre֖y⁠há ţȧẖĕẕò֥b nĕẖòֽşěţ׃"],[8,10,"וְ⁠אָכַלְתָּ֖ וְ⁠שָׂבָ֑עְתָּ וּ⁠בֵֽרַכְתָּ֙ אֶת־יְהוָ֣ה אֱלֹהֶ֔י⁠ךָ עַל־הָ⁠אָ֥רֶץ הַ⁠טֹּבָ֖ה אֲשֶׁ֥ר נָֽתַן־לָֽ⁠ךְ׃","wĕ⁠ʼákalĕţá֖̇ wĕ⁠şá̂bá֑ʻĕţá̇ ẇ⁠béֽrakĕţá̇֙ ʼeţ-yĕhwá֣h ʼèlòhe֔y⁠ká ʻal-há⁠ʼá֥reẕ ha⁠tò̇bá֖h ʼàşě֥r náֽţan-láֽ⁠kĕ׃"],[8,11,"הִשָּׁ֣מֶר לְ⁠ךָ֔ פֶּן־תִּשְׁכַּ֖ח אֶת־יְהוָ֣ה אֱלֹהֶ֑י⁠ךָ לְ⁠בִלְתִּ֨י שְׁמֹ֤ר מִצְוֺתָי⁠ו֙ וּ⁠מִשְׁפָּטָ֣י⁠ו וְ⁠חֻקֹּתָ֔י⁠ו אֲשֶׁ֛ר אָנֹכִ֥י מְצַוְּ⁠ךָ֖ הַ⁠יּֽוֹם׃","hişá֣̇̌mer lĕ⁠ká֔ pėn-ţi̇şĕ̌kȧ֖ẖ ʼeţ-yĕhwá֣h ʼèlòhe֑y⁠ká lĕ⁠bilĕţi̇֨y şĕ̌mò֤r miẕĕwֺţáy⁠w֙ ẇ⁠mişĕ̌pá̇tá֣y⁠w wĕ⁠ẖuqò̇ţá֔y⁠w ʼàşě֛r ʼánòki֥y mĕẕawĕ̇⁠ká֖ ha⁠ẏֽwòm׃"],[8,12,"פֶּן־תֹּאכַ֖ל וְ⁠שָׂבָ֑עְתָּ וּ⁠בָתִּ֥ים טוֹבִ֛ים תִּבְנֶ֖ה וְ⁠יָשָֽׁבְתָּ׃","pėn-ţò̇ʼka֖l wĕ⁠şá̂bá֑ʻĕţá̇ ẇ⁠báţi֥̇ym twòbi֛ym ţi̇bĕne֖h wĕ⁠yáşáֽ̌bĕţá̇׃"],[8,13,"וּ⁠בְקָֽרְ⁠ךָ֤ וְ⁠צֹֽאנְ⁠ךָ֙ יִרְבְּיֻ֔⁠ן וְ⁠כֶ֥סֶף וְ⁠זָהָ֖ב יִרְבֶּה־לָּ֑⁠ךְ וְ⁠כֹ֥ל אֲשֶׁר־לְ⁠ךָ֖ יִרְבֶּֽה׃","ẇ⁠bĕqáֽrĕ⁠ká֤ wĕ⁠ẕòֽʼnĕ⁠ká֙ yirĕbĕ̇yu֔⁠n wĕ⁠ke֥sep wĕ⁠záhá֖b yirĕbėh-lá֑̇⁠kĕ wĕ⁠kò֥l ʼàşěr-lĕ⁠ká֖ yirĕbėֽh׃"],[8,14,"וְ⁠רָ֖ם לְבָבֶ֑⁠ךָ וְ⁠שָֽׁכַחְתָּ֙ אֶת־יְהוָ֣ה אֱלֹהֶ֔י⁠ךָ הַ⁠מּוֹצִיאֲ⁠ךָ֛ מֵ⁠אֶ֥רֶץ מִצְרַ֖יִם מִ⁠בֵּ֥ית עֲבָדִֽים׃","wĕ⁠rá֖m lĕbábe֑⁠ká wĕ⁠şáֽ̌kaẖĕţá̇֙ ʼeţ-yĕhwá֣h ʼèlòhe֔y⁠ká ha⁠ṁwòẕiyʼà⁠ká֛ mé⁠ʼe֥reẕ miẕĕra֖yim mi⁠bé֥̇yţ ʻàbádiֽym׃"],[8,15,"הַ⁠מּוֹלִ֨יכֲ⁠ךָ֜ בַּ⁠מִּדְבָּ֣ר ׀ הַ⁠גָּדֹ֣ל וְ⁠הַ⁠נּוֹרָ֗א נָחָ֤שׁ ׀ שָׂרָף֙ וְ⁠עַקְרָ֔ב וְ⁠צִמָּא֖וֹן אֲשֶׁ֣ר אֵֽין־מָ֑יִם הַ⁠מּוֹצִ֤יא לְ⁠ךָ֙ מַ֔יִם מִ⁠צּ֖וּר הַֽ⁠חַלָּמִֽישׁ׃","ha⁠ṁwòli֨ykà⁠ká֜ bȧ⁠mi̇dĕbá֣̇r ׀ ha⁠gá̇dò֣l wĕ⁠ha⁠ṅwòrá֗ʼ náẖá֤ş̌ ׀ şá̂ráp֙ wĕ⁠ʻaqĕrá֔b wĕ⁠ẕimá̇ʼ֖wòn ʼàşě֣r ʼéֽyn-má֑yim ha⁠ṁwòẕi֤yʼ lĕ⁠ká֙ ma֔yim mi⁠ẕ֖̇ẇr haֽ⁠ẖalá̇miֽyş̌׃"],[8,16,"הַ⁠מַּֽאֲכִ֨לְ⁠ךָ֥ מָן֙ בַּ⁠מִּדְבָּ֔ר אֲשֶׁ֥ר לֹא־יָדְע֖וּ⁠ן אֲבֹתֶ֑י⁠ךָ לְמַ֣עַן עַנֹּֽתְ⁠ךָ֗ וּ⁠לְמַ֨עַן֙ נַסֹּתֶ֔⁠ךָ לְ⁠הֵיטִֽבְ⁠ךָ֖ בְּ⁠אַחֲרִיתֶֽ⁠ךָ׃","ha⁠mȧֽʼàki֨lĕ⁠ká֥ mán֙ bȧ⁠mi̇dĕbá̇֔r ʼàşě֥r lòʼ-yádĕʻ֖ẇ⁠n ʼàbòţe֑y⁠ká lĕma֣ʻan ʻanòֽ̇ţĕ⁠ká֗ ẇ⁠lĕma֨ʻan֙ nasò̇ţe֔⁠ká lĕ⁠héytiֽbĕ⁠ká֖ bĕ̇⁠ʼaẖàriyţeֽ⁠ká׃"],[8,17,"וְ⁠אָמַרְתָּ֖ בִּ⁠לְבָבֶ֑⁠ךָ כֹּחִ⁠י֙ וְ⁠עֹ֣צֶם יָדִ֔⁠י עָ֥שָׂה לִ֖⁠י אֶת־הַ⁠חַ֥יִל הַ⁠זֶּֽה׃","wĕ⁠ʼámarĕţá֖̇ bi̇⁠lĕbábe֑⁠ká kò̇ẖi⁠y֙ wĕ⁠ʻò֣ẕem yádi֔⁠y ʻá֥şá̂h li֖⁠y ʼeţ-ha⁠ẖa֥yil ha⁠zėֽh׃"],[8,18,"וְ⁠זָֽכַרְתָּ֙ אֶת־יְהוָ֣ה אֱלֹהֶ֔י⁠ךָ כִּ֣י ה֗וּא הַ⁠נֹּתֵ֥ן לְ⁠ךָ֛ כֹּ֖חַ לַ⁠עֲשׂ֣וֹת חָ֑יִל לְמַ֨עַן הָקִ֧ים אֶת־בְּרִית֛⁠וֹ אֲשֶׁר־נִשְׁבַּ֥ע לַ⁠אֲבֹתֶ֖י⁠ךָ כַּ⁠יּ֥וֹם הַ⁠זֶּֽה׃פ","wĕ⁠záֽkarĕţá̇֙ ʼeţ-yĕhwá֣h ʼèlòhe֔y⁠ká ki֣̇y h֗ẇʼ ha⁠nò̇ţé֥n lĕ⁠ká֛ kò֖̇ẖa la⁠ʻàş֣̂wòţ ẖá֑yil lĕma֨ʻan háqi֧ym ʼeţ-bĕ̇riyţ֛⁠wò ʼàşěr-nişĕ̌bȧ֥ʻ la⁠ʼàbòţe֖y⁠ká kȧ⁠ẏ֥wòm ha⁠zėֽh׃p"],[8,19,"וְ⁠הָיָ֗ה אִם־שָׁכֹ֤חַ תִּשְׁכַּח֙ אֶת־יְהוָ֣ה אֱלֹהֶ֔י⁠ךָ וְ⁠הָֽלַכְתָּ֗ אַחֲרֵי֙ אֱלֹהִ֣ים אֲחֵרִ֔ים וַ⁠עֲבַדְתָּ֖⁠ם וְ⁠הִשְׁתַּחֲוִ֣יתָ לָ⁠הֶ֑ם הַעִדֹ֤תִי בָ⁠כֶם֙ הַ⁠יּ֔וֹם כִּ֥י אָבֹ֖ד תֹּאבֵדֽוּ⁠ן׃","wĕ⁠háyá֗h ʼim-şá̌kò֤ẖa ţi̇şĕ̌kȧẖ֙ ʼeţ-yĕhwá֣h ʼèlòhe֔y⁠ká wĕ⁠háֽlakĕţá̇֗ ʼaẖàréy֙ ʼèlòhi֣ym ʼàẖéri֔ym wa⁠ʻàbadĕţá֖̇⁠m wĕ⁠hişĕ̌ţȧẖàwi֣yţá lá⁠he֑m haʻidò֤ţiy bá⁠kem֙ ha⁠ẏ֔wòm ki֥̇y ʼábò֖d ţò̇ʼbédֽẇ⁠n׃"],[8,20,"כַּ⁠גּוֹיִ֗ם אֲשֶׁ֤ר יְהוָה֙ מַאֲבִ֣יד מִ⁠פְּנֵי⁠כֶ֔ם כֵּ֖ן תֹאבֵד֑וּ⁠ן עֵ֚קֶב לֹ֣א תִשְׁמְע֔וּ⁠ן בְּ⁠ק֖וֹל יְהוָ֥ה אֱלֹהֵי⁠כֶֽם׃פ","kȧ⁠ġwòyi֗m ʼàşě֤r yĕhwáh֙ maʼàbi֣yd mi⁠pĕ̇néy⁠ke֔m ké֖̇n ţòʼbéd֑ẇ⁠n ʻé֚qeb lò֣ʼ ţişĕ̌mĕʻ֔ẇ⁠n bĕ̇⁠q֖wòl yĕhwá֥h ʼèlòhéy⁠keֽm׃p"],[9,1,"שְׁמַ֣ע יִשְׂרָאֵ֗ל אַתָּ֨ה עֹבֵ֤ר הַ⁠יּוֹם֙ אֶת־הַ⁠יַּרְדֵּ֔ן לָ⁠בֹא֙ לָ⁠רֶ֣שֶׁת גּוֹיִ֔ם גְּדֹלִ֥ים וַ⁠עֲצֻמִ֖ים מִמֶּ֑⁠ךָּ עָרִ֛ים גְּדֹלֹ֥ת וּ⁠בְצֻרֹ֖ת בַּ⁠שָּׁמָֽיִם׃","şĕ̌ma֣ʻ yişĕ̂ráʼé֗l ʼaţá̇֨h ʻòbé֤r ha⁠ẏwòm֙ ʼeţ-ha⁠yȧrĕdé̇֔n lá⁠bòʼ֙ lá⁠re֣şěţ ġwòyi֔m gĕ̇dòli֥ym wa⁠ʻàẕumi֖ym mimė֑⁠ká̇ ʻári֛ym gĕ̇dòlò֥ţ ẇ⁠bĕẕurò֖ţ bȧ⁠şá̇̌máֽyim׃"],[9,2,"עַֽם־גָּד֥וֹל וָ⁠רָ֖ם בְּנֵ֣י עֲנָקִ֑ים אֲשֶׁ֨ר אַתָּ֤ה יָדַ֨עְתָּ֙ וְ⁠אַתָּ֣ה שָׁמַ֔עְתָּ מִ֣י יִתְיַצֵּ֔ב לִ⁠פְנֵ֖י בְּנֵ֥י עֲנָֽק׃","ʻaֽm-gá̇d֥wòl wá⁠rá֖m bĕ̇né֣y ʻànáqi֑ym ʼàşě֨r ʼaţá֤̇h yáda֨ʻĕţá̇֙ wĕ⁠ʼaţá֣̇h şá̌ma֔ʻĕţá̇ mi֣y yiţĕyaẕé̇֔b li⁠pĕné֖y bĕ̇né֥y ʻànáֽq׃"],[9,3,"וְ⁠יָדַעְתָּ֣ הַ⁠יּ֗וֹם כִּי֩ יְהוָ֨ה אֱלֹהֶ֜י⁠ךָ הֽוּא־הָ⁠עֹבֵ֤ר לְ⁠פָנֶ֨י⁠ךָ֙ אֵ֣שׁ אֹֽכְלָ֔ה ה֧וּא יַשְׁמִידֵ֛⁠ם וְ⁠ה֥וּא יַכְנִיעֵ֖⁠ם לְ⁠פָנֶ֑י⁠ךָ וְ⁠הֽוֹרַשְׁתָּ֤⁠ם וְ⁠הַֽאַבַדְתָּ⁠ם֙ מַהֵ֔ר כַּ⁠אֲשֶׁ֛ר דִּבֶּ֥ר יְהוָ֖ה לָֽ⁠ךְ׃","wĕ⁠yádaʻĕţá֣̇ ha⁠ẏ֗wòm ki̇y֩ yĕhwá֨h ʼèlòhe֜y⁠ká hֽẇʼ-há⁠ʻòbé֤r lĕ⁠páne֨y⁠ká֙ ʼé֣ş̌ ʼòֽkĕlá֔h h֧ẇʼ yaşĕ̌miydé֛⁠m wĕ⁠h֥ẇʼ yakĕniyʻé֖⁠m lĕ⁠páne֑y⁠ká wĕ⁠hֽwòraşĕ̌ţá֤̇⁠m wĕ⁠haֽʼabadĕţá̇⁠m֙ mahé֔r kȧ⁠ʼàşě֛r di̇bė֥r yĕhwá֖h láֽ⁠kĕ׃"],[9,4,"אַל־תֹּאמַ֣ר בִּ⁠לְבָבְ⁠ךָ֗ בַּ⁠הֲדֹ֣ף יְהוָה֩ אֱלֹהֶ֨י⁠ךָ אֹתָ֥⁠ם ׀ מִ⁠לְּ⁠פָנֶי⁠ךָ֮ לֵ⁠אמֹר֒ בְּ⁠צִדְקָתִ⁠י֙ הֱבִיאַ֣⁠נִי יְהוָ֔ה לָ⁠רֶ֖שֶׁת אֶת־הָ⁠אָ֣רֶץ הַ⁠זֹּ֑את וּ⁠בְ⁠רִשְׁעַת֙ הַ⁠גּוֹיִ֣ם הָ⁠אֵ֔לֶּה יְהוָ֖ה מוֹרִישָׁ֥⁠ם מִ⁠פָּנֶֽי⁠ךָ׃","ʼal-ţò̇ʼma֣r bi̇⁠lĕbábĕ⁠ká֗ bȧ⁠hàdò֣p yĕhwáh֩ ʼèlòhe֨y⁠ká ʼòţá֥⁠m ׀ mi⁠lĕ̇⁠páney⁠ká֮ lé⁠ʼmòr֒ bĕ̇⁠ẕidĕqáţi⁠y֙ hèbiyʼa֣⁠niy yĕhwá֔h lá⁠re֖şěţ ʼeţ-há⁠ʼá֣reẕ ha⁠zò֑̇ʼţ ẇ⁠bĕ⁠rişĕ̌ʻaţ֙ ha⁠ġwòyi֣m há⁠ʼé֔lėh yĕhwá֖h mwòriyşá֥̌⁠m mi⁠pá̇neֽy⁠ká׃"],[9,5,"לֹ֣א בְ⁠צִדְקָתְ⁠ךָ֗ וּ⁠בְ⁠יֹ֨שֶׁר֙ לְבָ֣בְ⁠ךָ֔ אַתָּ֥ה בָ֖א לָ⁠רֶ֣שֶׁת אֶת־אַרְצָ֑⁠ם כִּ֞י בְּ⁠רִשְׁעַ֣ת ׀ הַ⁠גּוֹיִ֣ם הָ⁠אֵ֗לֶּה יְהוָ֤ה אֱלֹהֶ֨י⁠ךָ֙ מוֹרִישָׁ֣⁠ם מִ⁠פָּנֶ֔י⁠ךָ וּ⁠לְמַ֜עַן הָקִ֣ים אֶת־הַ⁠דָּבָ֗ר אֲשֶׁ֨ר נִשְׁבַּ֤ע יְהוָה֙ לַ⁠אֲבֹתֶ֔י⁠ךָ לְ⁠אַבְרָהָ֥ם לְ⁠יִצְחָ֖ק וּֽ⁠לְ⁠יַעֲקֹֽב׃","lò֣ʼ bĕ⁠ẕidĕqáţĕ⁠ká֗ ẇ⁠bĕ⁠yò֨şěr֙ lĕbá֣bĕ⁠ká֔ ʼaţá֥̇h bá֖ʼ lá⁠re֣şěţ ʼeţ-ʼarĕẕá֑⁠m ki̇֞y bĕ̇⁠rişĕ̌ʻa֣ţ ׀ ha⁠ġwòyi֣m há⁠ʼé֗lėh yĕhwá֤h ʼèlòhe֨y⁠ká֙ mwòriyşá֣̌⁠m mi⁠pá̇ne֔y⁠ká ẇ⁠lĕma֜ʻan háqi֣ym ʼeţ-ha⁠dá̇bá֗r ʼàşě֨r nişĕ̌bȧ֤ʻ yĕhwáh֙ la⁠ʼàbòţe֔y⁠ká lĕ⁠ʼabĕráhá֥m lĕ⁠yiẕĕẖá֖q ẇֽ⁠lĕ⁠yaʻàqòֽb׃"],[9,6,"וְ⁠יָדַעְתָּ֗ כִּ֠י לֹ֤א בְ⁠צִדְקָֽתְ⁠ךָ֙ יְהוָ֣ה אֱ֠לֹהֶי⁠ךָ נֹתֵ֨ן לְ⁠ךָ֜ אֶת־הָ⁠אָ֧רֶץ הַ⁠טּוֹבָ֛ה הַ⁠זֹּ֖את לְ⁠רִשְׁתָּ֑⁠הּ כִּ֥י עַם־קְשֵׁה־עֹ֖רֶף אָֽתָּה׃","wĕ⁠yádaʻĕţá̇֗ ki̇֠y lò֤ʼ bĕ⁠ẕidĕqáֽţĕ⁠ká֙ yĕhwá֣h ʼè֠lòhey⁠ká nòţé֨n lĕ⁠ká֜ ʼeţ-há⁠ʼá֧reẕ ha⁠ṫwòbá֛h ha⁠zò֖̇ʼţ lĕ⁠rişĕ̌ţá֑̇⁠ḣ ki֥̇y ʻam-qĕşé̌h-ʻò֖rep ʼáֽţá̇h׃"],[9,7,"זְכֹר֙ אַל־תִּשְׁכַּ֔ח אֵ֧ת אֲשֶׁר־הִקְצַ֛פְתָּ אֶת־יְהוָ֥ה אֱלֹהֶ֖י⁠ךָ בַּ⁠מִּדְבָּ֑ר לְ⁠מִן־הַ⁠יּ֞וֹם אֲשֶׁר־יָצָ֣אתָ ׀ מֵ⁠אֶ֣רֶץ מִצְרַ֗יִם עַד־בֹּֽאֲ⁠כֶם֙ עַד־הַ⁠מָּק֣וֹם הַ⁠זֶּ֔ה מַמְרִ֥ים הֱיִיתֶ֖ם עִם־יְהוָֽה׃","zĕkòr֙ ʼal-ţi̇şĕ̌kȧ֔ẖ ʼé֧ţ ʼàşěr-hiqĕẕa֛pĕţá̇ ʼeţ-yĕhwá֥h ʼèlòhe֖y⁠ká bȧ⁠mi̇dĕbá֑̇r lĕ⁠min-ha⁠ẏ֞wòm ʼàşěr-yáẕá֣ʼţá ׀ mé⁠ʼe֣reẕ miẕĕra֗yim ʻad-bòֽ̇ʼà⁠kem֙ ʻad-ha⁠má̇q֣wòm ha⁠zė֔h mamĕri֥ym hèyiyţe֖m ʻim-yĕhwáֽh׃"],[9,8,"וּ⁠בְ⁠חֹרֵ֥ב הִקְצַפְתֶּ֖ם אֶת־יְהוָ֑ה וַ⁠יִּתְאַנַּ֧ף יְהוָ֛ה בָּ⁠כֶ֖ם לְ⁠הַשְׁמִ֥יד אֶתְ⁠כֶֽם׃","ẇ⁠bĕ⁠ẖòré֥b hiqĕẕapĕţė֖m ʼeţ-yĕhwá֑h wa⁠yi̇ţĕʼanȧ֧p yĕhwá֛h bá̇⁠ke֖m lĕ⁠haşĕ̌mi֥yd ʼeţĕ⁠keֽm׃"],[9,9,"בַּ⁠עֲלֹתִ֣⁠י הָ⁠הָ֗רָ⁠ה לָ⁠קַ֜חַת לוּחֹ֤ת הָֽ⁠אֲבָנִים֙ לוּחֹ֣ת הַ⁠בְּרִ֔ית אֲשֶׁר־כָּרַ֥ת יְהוָ֖ה עִמָּ⁠כֶ֑ם וָ⁠אֵשֵׁ֣ב בָּ⁠הָ֗ר אַרְבָּעִ֥ים יוֹם֙ וְ⁠אַרְבָּעִ֣ים לַ֔יְלָה לֶ֚חֶם לֹ֣א אָכַ֔לְתִּי וּ⁠מַ֖יִם לֹ֥א שָׁתִֽיתִי׃","bȧ⁠ʻàlòţi֣⁠y há⁠há֗rá⁠h lá⁠qa֜ẖaţ lẇẖò֤ţ háֽ⁠ʼàbániym֙ lẇẖò֣ţ ha⁠bĕ̇ri֔yţ ʼàşěr-ká̇ra֥ţ yĕhwá֖h ʻimá̇⁠ke֑m wá⁠ʼéşé֣̌b bá̇⁠há֗r ʼarĕbá̇ʻi֥ym ywòm֙ wĕ⁠ʼarĕbá̇ʻi֣ym la֔yĕláh le֚ẖem lò֣ʼ ʼáka֔lĕţi̇y ẇ⁠ma֖yim lò֥ʼ şá̌ţiֽyţiy׃"],[9,10,"וַ⁠יִּתֵּ֨ן יְהוָ֜ה אֵלַ֗⁠י אֶת־שְׁנֵי֙ לוּחֹ֣ת הָֽ⁠אֲבָנִ֔ים כְּתֻבִ֖ים בְּ⁠אֶצְבַּ֣ע אֱלֹהִ֑ים וַ⁠עֲלֵי⁠הֶ֗ם כְּֽ⁠כָל־הַ⁠דְּבָרִ֡ים אֲשֶׁ֣ר דִּבֶּר֩ יְהוָ֨ה עִמָּ⁠כֶ֥ם בָּ⁠הָ֛ר מִ⁠תּ֥וֹךְ הָ⁠אֵ֖שׁ בְּ⁠י֥וֹם הַ⁠קָּהָֽל׃","wa⁠yi̇ţé̇֨n yĕhwá֜h ʼéla֗⁠y ʼeţ-şĕ̌néy֙ lẇẖò֣ţ háֽ⁠ʼàbáni֔ym kĕ̇ţubi֖ym bĕ̇⁠ʼeẕĕbȧ֣ʻ ʼèlòhi֑ym wa⁠ʻàléy⁠he֗m kĕֽ̇⁠kál-ha⁠dĕ̇bári֡ym ʼàşě֣r di̇bėr֩ yĕhwá֨h ʻimá̇⁠ke֥m bá̇⁠há֛r mi⁠ţ֥̇wòkĕ há⁠ʼé֖ş̌ bĕ̇⁠y֥wòm ha⁠qá̇háֽl׃"],[9,11,"וַ⁠יְהִ֗י מִ⁠קֵּץ֙ אַרְבָּעִ֣ים י֔וֹם וְ⁠אַרְבָּעִ֖ים לָ֑יְלָה נָתַ֨ן יְהוָ֜ה אֵלַ֗⁠י אֶת־שְׁנֵ֛י לֻחֹ֥ת הָ⁠אֲבָנִ֖ים לֻח֥וֹת הַ⁠בְּרִֽית׃","wa⁠yĕhi֗y mi⁠qé̇ẕ֙ ʼarĕbá̇ʻi֣ym y֔wòm wĕ⁠ʼarĕbá̇ʻi֖ym lá֑yĕláh náţa֨n yĕhwá֜h ʼéla֗⁠y ʼeţ-şĕ̌né֛y luẖò֥ţ há⁠ʼàbáni֖ym luẖ֥wòţ ha⁠bĕ̇riֽyţ׃"],[9,12,"וַ⁠יֹּ֨אמֶר יְהוָ֜ה אֵלַ֗⁠י ק֣וּם רֵ֤ד מַהֵר֙ מִ⁠זֶּ֔ה כִּ֚י שִׁחֵ֣ת עַמְּ⁠ךָ֔ אֲשֶׁ֥ר הוֹצֵ֖אתָ מִ⁠מִּצְרָ֑יִם סָ֣רוּ מַהֵ֗ר מִן־הַ⁠דֶּ֨רֶךְ֙ אֲשֶׁ֣ר צִוִּיתִ֔⁠ם עָשׂ֥וּ לָ⁠הֶ֖ם מַסֵּכָֽה׃","wa⁠yò̇֨ʼmer yĕhwá֜h ʼéla֗⁠y q֣ẇm ré֤d mahér֙ mi⁠zė֔h ki֚̇y şǐẖé֣ţ ʻamĕ̇⁠ká֔ ʼàşě֥r hwòẕé֖ʼţá mi⁠mi̇ẕĕrá֑yim sá֣rẇ mahé֗r min-ha⁠dė֨rekĕ֙ ʼàşě֣r ẕiwi̇yţi֔⁠m ʻáş֥̂ẇ lá⁠he֖m masé̇káֽh׃"],[9,13,"וַ⁠יֹּ֥אמֶר יְהוָ֖ה אֵלַ֣⁠י לֵ⁠אמֹ֑ר רָאִ֨יתִי֙ אֶת־הָ⁠עָ֣ם הַ⁠זֶּ֔ה וְ⁠הִנֵּ֥ה עַם־קְשֵׁה־עֹ֖רֶף הֽוּא׃","wa⁠yò֥̇ʼmer yĕhwá֖h ʼéla֣⁠y lé⁠ʼmò֑r ráʼi֨yţiy֙ ʼeţ-há⁠ʻá֣m ha⁠zė֔h wĕ⁠hiné֥̇h ʻam-qĕşé̌h-ʻò֖rep hֽẇʼ׃"],[9,14,"הֶ֤רֶף מִמֶּ֨⁠נִּי֙ וְ⁠אַשְׁמִידֵ֔⁠ם וְ⁠אֶמְחֶ֣ה אֶת־שְׁמָ֔⁠ם מִ⁠תַּ֖חַת הַ⁠שָּׁמָ֑יִם וְ⁠אֶֽעֱשֶׂה֙ אֽוֹתְ⁠ךָ֔ לְ⁠גוֹי־עָצ֥וּם וָ⁠רָ֖ב מִמֶּֽ⁠נּוּ׃","he֤rep mimė֨⁠ni̇y֙ wĕ⁠ʼaşĕ̌miydé֔⁠m wĕ⁠ʼemĕẖe֣h ʼeţ-şĕ̌má֔⁠m mi⁠ţȧ֖ẖaţ ha⁠şá̇̌má֑yim wĕ⁠ʼeֽʻèşêh֙ ʼֽwòţĕ⁠ká֔ lĕ⁠gwòy-ʻáẕ֥ẇm wá⁠rá֖b mimėֽ⁠ṅẇ׃"],[9,15,"וָ⁠אֵ֗פֶן וָֽ⁠אֵרֵד֙ מִן־הָ⁠הָ֔ר וְ⁠הָ⁠הָ֖ר בֹּעֵ֣ר בָּ⁠אֵ֑שׁ וּ⁠שְׁנֵי֙ לֻחֹ֣ת הַ⁠בְּרִ֔ית עַ֖ל שְׁתֵּ֥י יָדָֽ⁠י׃","wá⁠ʼé֗pen wáֽ⁠ʼéréd֙ min-há⁠há֔r wĕ⁠há⁠há֖r bò̇ʻé֣r bá̇⁠ʼé֑ş̌ ẇ⁠şĕ̌néy֙ luẖò֣ţ ha⁠bĕ̇ri֔yţ ʻa֖l şĕ̌ţé֥̇y yádáֽ⁠y׃"],[9,16,"וָ⁠אֵ֗רֶא וְ⁠הִנֵּ֤ה חֲטָאתֶם֙ לַ⁠יהוָ֣ה אֱלֹֽהֵי⁠כֶ֔ם עֲשִׂיתֶ֣ם לָ⁠כֶ֔ם עֵ֖גֶל מַסֵּכָ֑ה סַרְתֶּ֣ם מַהֵ֔ר מִן־הַ⁠דֶּ֕רֶךְ אֲשֶׁר־צִוָּ֥ה יְהוָ֖ה אֶתְ⁠כֶֽם׃","wá⁠ʼé֗reʼ wĕ⁠hiné֤̇h ẖàtáʼţem֙ la⁠yhwá֣h ʼèlòֽhéy⁠ke֔m ʻàşîyţe֣m lá⁠ke֔m ʻé֖gel masé̇ká֑h sarĕţė֣m mahé֔r min-ha⁠dė֕rekĕ ʼàşěr-ẕiwá֥̇h yĕhwá֖h ʼeţĕ⁠keֽm׃"],[9,17,"וָ⁠אֶתְפֹּשׂ֙ בִּ⁠שְׁנֵ֣י הַ⁠לֻּחֹ֔ת וָֽ⁠אַשְׁלִכֵ֔⁠ם מֵ⁠עַ֖ל שְׁתֵּ֣י יָדָ֑⁠י וָ⁠אֲשַׁבְּרֵ֖⁠ם לְ⁠עֵינֵי⁠כֶֽם׃","wá⁠ʼeţĕpò̇ş̂֙ bi̇⁠şĕ̌né֣y ha⁠lu̇ẖò֔ţ wáֽ⁠ʼaşĕ̌liké֔⁠m mé⁠ʻa֖l şĕ̌ţé֣̇y yádá֑⁠y wá⁠ʼàşǎbĕ̇ré֖⁠m lĕ⁠ʻéynéy⁠keֽm׃"],[9,18,"וָֽ⁠אֶתְנַפַּל֩ לִ⁠פְנֵ֨י יְהוָ֜ה כָּ⁠רִאשֹׁנָ֗ה אַרְבָּעִ֥ים יוֹם֙ וְ⁠אַרְבָּעִ֣ים לַ֔יְלָה לֶ֚חֶם לֹ֣א אָכַ֔לְתִּי וּ⁠מַ֖יִם לֹ֣א שָׁתִ֑יתִי עַ֤ל כָּל־חַטַּאתְ⁠כֶם֙ אֲשֶׁ֣ר חֲטָאתֶ֔ם לַ⁠עֲשׂ֥וֹת הָ⁠רַ֛ע בְּ⁠עֵינֵ֥י יְהוָ֖ה לְ⁠הַכְעִיסֽ⁠וֹ׃","wáֽ⁠ʼeţĕnapȧl֩ li⁠pĕné֨y yĕhwá֜h ká̇⁠riʼşò̌ná֗h ʼarĕbá̇ʻi֥ym ywòm֙ wĕ⁠ʼarĕbá̇ʻi֣ym la֔yĕláh le֚ẖem lò֣ʼ ʼáka֔lĕţi̇y ẇ⁠ma֖yim lò֣ʼ şá̌ţi֑yţiy ʻa֤l ká̇l-ẖatȧʼţĕ⁠kem֙ ʼàşě֣r ẖàtáʼţe֔m la⁠ʻàş֥̂wòţ há⁠ra֛ʻ bĕ̇⁠ʻéyné֥y yĕhwá֖h lĕ⁠hakĕʻiysֽ⁠wò׃"],[9,19,"כִּ֣י יָגֹ֗רְתִּי מִ⁠פְּנֵ֤י הָ⁠אַף֙ וְ⁠הַ֣⁠חֵמָ֔ה אֲשֶׁ֨ר קָצַ֧ף יְהוָ֛ה עֲלֵי⁠כֶ֖ם לְ⁠הַשְׁמִ֣יד אֶתְ⁠כֶ֑ם וַ⁠יִּשְׁמַ֤ע יְהוָה֙ אֵלַ֔⁠י גַּ֖ם בַּ⁠פַּ֥עַם הַ⁠הִֽוא׃","ki֣̇y yágò֗rĕţi̇y mi⁠pĕ̇né֤y há⁠ʼap֙ wĕ⁠ha֣⁠ẖémá֔h ʼàşě֨r qáẕa֧p yĕhwá֛h ʻàléy⁠ke֖m lĕ⁠haşĕ̌mi֣yd ʼeţĕ⁠ke֑m wa⁠yi̇şĕ̌ma֤ʻ yĕhwáh֙ ʼéla֔⁠y gȧ֖m bȧ⁠pȧ֥ʻam ha⁠hiֽwʼ׃"],[9,20,"וּֽ⁠בְ⁠אַהֲרֹ֗ן הִתְאַנַּ֧ף יְהוָ֛ה מְאֹ֖ד לְ⁠הַשְׁמִיד֑⁠וֹ וָֽ⁠אֶתְפַּלֵּ֛ל גַּם־בְּעַ֥ד אַהֲרֹ֖ן בָּ⁠עֵ֥ת הַ⁠הִֽוא","ẇֽ⁠bĕ⁠ʼahàrò֗n hiţĕʼanȧ֧p yĕhwá֛h mĕʼò֖d lĕ⁠haşĕ̌miyd֑⁠wò wáֽ⁠ʼeţĕpȧlé֛̇l gȧm-bĕ̇ʻa֥d ʼahàrò֖n bá̇⁠ʻé֥ţ ha⁠hiֽwʼ"],[9,21,"וְֽ⁠אֶת־חַטַּאתְ⁠כֶ֞ם אֲשֶׁר־עֲשִׂיתֶ֣ם אֶת־הָ⁠עֵ֗גֶל לָקַחְתִּי֮ וָ⁠אֶשְׂרֹ֣ף אֹת֣⁠וֹ ׀ בָּ⁠אֵשׁ֒ וָ⁠אֶכֹּ֨ת אֹת֤⁠וֹ טָחוֹן֙ הֵיטֵ֔ב עַ֥ד אֲשֶׁר־דַּ֖ק לְ⁠עָפָ֑ר וָֽ⁠אַשְׁלִךְ֙ אֶת־עֲפָר֔⁠וֹ אֶל־הַ⁠נַּ֖חַל הַ⁠יֹּרֵ֥ד מִן־הָ⁠הָֽר׃","wĕֽ⁠ʼeţ-ẖatȧʼţĕ⁠ke֞m ʼàşěr-ʻàşîyţe֣m ʼeţ-há⁠ʻé֗gel láqaẖĕţi̇y֮ wá⁠ʼeşĕ̂rò֣p ʼòţ֣⁠wò ׀ bá̇⁠ʼéş̌֒ wá⁠ʼekò̇֨ţ ʼòţ֤⁠wò táẖwòn֙ héyté֔b ʻa֥d ʼàşěr-dȧ֖q lĕ⁠ʻápá֑r wáֽ⁠ʼaşĕ̌likĕ֙ ʼeţ-ʻàpár֔⁠wò ʼel-ha⁠nȧ֖ẖal ha⁠yò̇ré֥d min-há⁠háֽr׃"],[9,22,"וּ⁠בְ⁠תַבְעֵרָה֙ וּ⁠בְ⁠מַסָּ֔ה וּ⁠בְ⁠קִבְרֹ֖ת הַֽתַּאֲוָ֑ה מַקְצִפִ֥ים הֱיִיתֶ֖ם אֶת־יְהוָֽה׃","ẇ⁠bĕ⁠ţabĕʻéráh֙ ẇ⁠bĕ⁠masá̇֔h ẇ⁠bĕ⁠qibĕrò֖ţ haֽţȧʼàwá֑h maqĕẕipi֥ym hèyiyţe֖m ʼeţ-yĕhwáֽh׃"],[9,23,"וּ⁠בִ⁠שְׁלֹ֨חַ יְהוָ֜ה אֶתְ⁠כֶ֗ם מִ⁠קָּדֵ֤שׁ בַּרְנֵ֨עַ֙ לֵ⁠אמֹ֔ר עֲלוּ֙ וּ⁠רְשׁ֣וּ אֶת־הָ⁠אָ֔רֶץ אֲשֶׁ֥ר נָתַ֖תִּי לָ⁠כֶ֑ם וַ⁠תַּמְר֗וּ אֶת־פִּ֤י יְהוָה֙ אֱלֹ֣הֵי⁠כֶ֔ם וְ⁠לֹ֤א הֶֽאֱמַנְתֶּם֙ ל֔⁠וֹ וְ⁠לֹ֥א שְׁמַעְתֶּ֖ם בְּ⁠קֹלֽ⁠וֹ׃","ẇ⁠bi⁠şĕ̌lò֨ẖa yĕhwá֜h ʼeţĕ⁠ke֗m mi⁠qá̇dé֤ş̌ bȧrĕné֨ʻa֙ lé⁠ʼmò֔r ʻàlẇ֙ ẇ⁠rĕş֣̌ẇ ʼeţ-há⁠ʼá֔reẕ ʼàşě֥r náţa֖ţi̇y lá⁠ke֑m wa⁠ţȧmĕr֗ẇ ʼeţ-pi֤̇y yĕhwáh֙ ʼèlò֣héy⁠ke֔m wĕ⁠lò֤ʼ heֽʼèmanĕţėm֙ l֔⁠wò wĕ⁠lò֥ʼ şĕ̌maʻĕţė֖m bĕ̇⁠qòlֽ⁠wò׃"],[9,24,"מַמְרִ֥ים הֱיִיתֶ֖ם עִם־יְהוָ֑ה מִ⁠יּ֖וֹם דַּעְתִּ֥⁠י אֶתְ⁠כֶֽם׃","mamĕri֥ym hèyiyţe֖m ʻim-yĕhwá֑h mi⁠ẏ֖wòm dȧʻĕţi֥̇⁠y ʼeţĕ⁠keֽm׃"],[9,25,"וָֽ⁠אֶתְנַפַּ֞ל לִ⁠פְנֵ֣י יְהוָ֗ה אֵ֣ת אַרְבָּעִ֥ים הַ⁠יּ֛וֹם וְ⁠אֶת־אַרְבָּעִ֥ים הַ⁠לַּ֖יְלָה אֲשֶׁ֣ר הִתְנַפָּ֑לְתִּי כִּֽי־אָמַ֥ר יְהוָ֖ה לְ⁠הַשְׁמִ֥יד אֶתְ⁠כֶֽם׃","wáֽ⁠ʼeţĕnapȧ֞l li⁠pĕné֣y yĕhwá֗h ʼé֣ţ ʼarĕbá̇ʻi֥ym ha⁠ẏ֛wòm wĕ⁠ʼeţ-ʼarĕbá̇ʻi֥ym ha⁠lȧ֖yĕláh ʼàşě֣r hiţĕnapá֑̇lĕţi̇y kiֽ̇y-ʼáma֥r yĕhwá֖h lĕ⁠haşĕ̌mi֥yd ʼeţĕ⁠keֽm׃"],[9,26,"וָ⁠אֶתְפַּלֵּ֣ל אֶל־יְהוָה֮ וָ⁠אֹמַר֒ אֲדֹנָ֣⁠י יְהוִ֗ה אַל־תַּשְׁחֵ֤ת עַמְּ⁠ךָ֙ וְ⁠נַחֲלָ֣תְ⁠ךָ֔ אֲשֶׁ֥ר פָּדִ֖יתָ בְּ⁠גָדְלֶ֑⁠ךָ אֲשֶׁר־הוֹצֵ֥אתָ מִ⁠מִּצְרַ֖יִם בְּ⁠יָ֥ד חֲזָקָֽה׃","wá⁠ʼeţĕpȧlé֣̇l ʼel-yĕhwáh֮ wá⁠ʼòmar֒ ʼàdòná֣⁠y yĕhwi֗h ʼal-ţȧşĕ̌ẖé֤ţ ʻamĕ̇⁠ká֙ wĕ⁠naẖàlá֣ţĕ⁠ká֔ ʼàşě֥r pá̇di֖yţá bĕ̇⁠gádĕle֑⁠ká ʼàşěr-hwòẕé֥ʼţá mi⁠mi̇ẕĕra֖yim bĕ̇⁠yá֥d ẖàzáqáֽh׃"],[9,27,"זְכֹר֙ לַ⁠עֲבָדֶ֔י⁠ךָ לְ⁠אַבְרָהָ֥ם לְ⁠יִצְחָ֖ק וּֽ⁠לְ⁠יַעֲקֹ֑ב אַל־תֵּ֗פֶן אֶל־קְשִׁי֙ הָ⁠עָ֣ם הַ⁠זֶּ֔ה וְ⁠אֶל־רִשְׁע֖⁠וֹ וְ⁠אֶל־חַטָּאתֽ⁠וֹ׃","zĕkòr֙ la⁠ʻàbáde֔y⁠ká lĕ⁠ʼabĕráhá֥m lĕ⁠yiẕĕẖá֖q ẇֽ⁠lĕ⁠yaʻàqò֑b ʼal-ţé̇֗pen ʼel-qĕşǐy֙ há⁠ʻá֣m ha⁠zė֔h wĕ⁠ʼel-rişĕ̌ʻ֖⁠wò wĕ⁠ʼel-ẖatá̇ʼţֽ⁠wò׃"],[9,28,"פֶּן־יֹאמְר֗וּ הָ⁠אָרֶץ֮ אֲשֶׁ֣ר הוֹצֵאתָ֣⁠נוּ מִ⁠שָּׁם֒ מִ⁠בְּלִי֙ יְכֹ֣לֶת יְהוָ֔ה לַ⁠הֲבִיאָ֕⁠ם אֶל־הָ⁠אָ֖רֶץ אֲשֶׁר־דִּבֶּ֣ר לָ⁠הֶ֑ם וּ⁠מִ⁠שִּׂנְאָת֣⁠וֹ אוֹתָ֔⁠ם הוֹצִיאָ֖⁠ם לַ⁠הֲמִתָ֥⁠ם בַּ⁠מִּדְבָּֽר׃","pėn-yòʼmĕr֗ẇ há⁠ʼáreẕ֮ ʼàşě֣r hwòẕéʼţá֣⁠nẇ mi⁠şá̇̌m֒ mi⁠bĕ̇liy֙ yĕkò֣leţ yĕhwá֔h la⁠hàbiyʼá֕⁠m ʼel-há⁠ʼá֖reẕ ʼàşěr-di̇bė֣r lá⁠he֑m ẇ⁠mi⁠şi̇̂nĕʼáţ֣⁠wò ʼwòţá֔⁠m hwòẕiyʼá֖⁠m la⁠hàmiţá֥⁠m bȧ⁠mi̇dĕbáֽ̇r׃"],[9,29,"וְ⁠הֵ֥ם עַמְּ⁠ךָ֖ וְ⁠נַחֲלָתֶ֑⁠ךָ אֲשֶׁ֤ר הוֹצֵ֨אתָ֙ בְּ⁠כֹחֲ⁠ךָ֣ הַ⁠גָּדֹ֔ל וּ⁠בִֽ⁠זְרֹעֲ⁠ךָ֖ הַ⁠נְּטוּיָֽה׃פ","wĕ⁠hé֥m ʻamĕ̇⁠ká֖ wĕ⁠naẖàláţe֑⁠ká ʼàşě֤r hwòẕé֨ʼţá֙ bĕ̇⁠kòẖà⁠ká֣ ha⁠gá̇dò֔l ẇ⁠biֽ⁠zĕròʻà⁠ká֖ ha⁠nĕ̇tẇyáֽh׃p"],[10,1,"בָּ⁠עֵ֨ת הַ⁠הִ֜וא אָמַ֧ר יְהוָ֣ה אֵלַ֗⁠י פְּסָל־לְ⁠ךָ֞ שְׁנֵֽי־לֻוחֹ֤ת אֲבָנִים֙ כָּ⁠רִ֣אשֹׁנִ֔ים וַ⁠עֲלֵ֥ה אֵלַ֖⁠י הָ⁠הָ֑רָ⁠ה וְ⁠עָשִׂ֥יתָ לְּ⁠ךָ֖ אֲר֥וֹן עֵֽץ׃","bá̇⁠ʻé֨ţ ha⁠hi֜wʼ ʼáma֧r yĕhwá֣h ʼéla֗⁠y pĕ̇sál-lĕ⁠ká֞ şĕ̌néֽy-luwẖò֤ţ ʼàbániym֙ ká̇⁠ri֣ʼşò̌ni֔ym wa⁠ʻàlé֥h ʼéla֖⁠y há⁠há֑rá⁠h wĕ⁠ʻáşî֥yţá lĕ̇⁠ká֖ ʼàr֥wòn ʻéֽẕ׃"],[10,2,"וְ⁠אֶכְתֹּב֙ עַל־הַ⁠לֻּחֹ֔ת אֶת־הַ⁠דְּבָרִ֔ים אֲשֶׁ֥ר הָי֛וּ עַל־הַ⁠לֻּחֹ֥ת הָ⁠רִאשֹׁנִ֖ים אֲשֶׁ֣ר שִׁבַּ֑רְתָּ וְ⁠שַׂמְתָּ֖⁠ם בָּ⁠אָרֽוֹן׃","wĕ⁠ʼekĕţò̇b֙ ʻal-ha⁠lu̇ẖò֔ţ ʼeţ-ha⁠dĕ̇bári֔ym ʼàşě֥r háy֛ẇ ʻal-ha⁠lu̇ẖò֥ţ há⁠riʼşò̌ni֖ym ʼàşě֣r şǐbȧ֑rĕţá̇ wĕ⁠şâmĕţá֖̇⁠m bá̇⁠ʼárֽwòn׃"],[10,3,"וָ⁠אַ֤עַשׂ אֲרוֹן֙ עֲצֵ֣י שִׁטִּ֔ים וָ⁠אֶפְסֹ֛ל שְׁנֵי־לֻחֹ֥ת אֲבָנִ֖ים כָּ⁠רִאשֹׁנִ֑ים וָ⁠אַ֣עַל הָ⁠הָ֔רָ⁠ה וּ⁠שְׁנֵ֥י הַ⁠לֻּחֹ֖ת בְּ⁠יָדִֽ⁠י׃","wá⁠ʼa֤ʻaş̂ ʼàrwòn֙ ʻàẕé֣y şǐti̇֔ym wá⁠ʼepĕsò֛l şĕ̌néy-luẖò֥ţ ʼàbáni֖ym ká̇⁠riʼşò̌ni֑ym wá⁠ʼa֣ʻal há⁠há֔rá⁠h ẇ⁠şĕ̌né֥y ha⁠lu̇ẖò֖ţ bĕ̇⁠yádiֽ⁠y׃"],[10,4,"וַ⁠יִּכְתֹּ֨ב עַֽל־הַ⁠לֻּחֹ֜ת כַּ⁠מִּכְתָּ֣ב הָ⁠רִאשׁ֗וֹן אֵ֚ת עֲשֶׂ֣רֶת הַ⁠דְּבָרִ֔ים אֲשֶׁ֣ר דִּבֶּר֩ יְהוָ֨ה אֲלֵי⁠כֶ֥ם בָּ⁠הָ֛ר מִ⁠תּ֥וֹךְ הָ⁠אֵ֖שׁ בְּ⁠י֣וֹם הַ⁠קָּהָ֑ל וַ⁠יִּתְּנֵ֥⁠ם יְהוָ֖ה אֵלָֽ⁠י׃","wa⁠yi̇kĕţò̇֨b ʻaֽl-ha⁠lu̇ẖò֜ţ kȧ⁠mi̇kĕţá֣̇b há⁠riʼş̌֗wòn ʼé֚ţ ʻàşê֣reţ ha⁠dĕ̇bári֔ym ʼàşě֣r di̇bėr֩ yĕhwá֨h ʼàléy⁠ke֥m bá̇⁠há֛r mi⁠ţ֥̇wòkĕ há⁠ʼé֖ş̌ bĕ̇⁠y֣wòm ha⁠qá̇há֑l wa⁠yi̇ţĕ̇né֥⁠m yĕhwá֖h ʼéláֽ⁠y׃"],[10,5,"וָ⁠אֵ֗פֶן וָֽ⁠אֵרֵד֙ מִן־הָ⁠הָ֔ר וָֽ⁠אָשִׂם֙ אֶת־הַ⁠לֻּחֹ֔ת בָּ⁠אָר֖וֹן אֲשֶׁ֣ר עָשִׂ֑יתִי וַ⁠יִּ֣הְיוּ שָׁ֔ם כַּ⁠אֲשֶׁ֥ר צִוַּ֖⁠נִי יְהוָֽה׃","wá⁠ʼé֗pen wáֽ⁠ʼéréd֙ min-há⁠há֔r wáֽ⁠ʼáşîm֙ ʼeţ-ha⁠lu̇ẖò֔ţ bá̇⁠ʼár֖wòn ʼàşě֣r ʻáşî֑yţiy wa⁠yi֣̇hĕyẇ şá̌֔m kȧ⁠ʼàşě֥r ẕiwȧ֖⁠niy yĕhwáֽh׃"],[10,6,"וּ⁠בְנֵ֣י יִשְׂרָאֵ֗ל נָֽסְע֛וּ מִ⁠בְּאֵרֹ֥ת בְּנֵי־יַעֲקָ֖ן מוֹסֵרָ֑ה שָׁ֣ם מֵ֤ת אַהֲרֹן֙ וַ⁠יִּקָּבֵ֣ר שָׁ֔ם וַ⁠יְכַהֵ֛ן אֶלְעָזָ֥ר בְּנ֖⁠וֹ תַּחְתָּֽי⁠ו׃","ẇ⁠bĕné֣y yişĕ̂ráʼé֗l náֽsĕʻ֛ẇ mi⁠bĕ̇ʼérò֥ţ bĕ̇néy-yaʻàqá֖n mwòsérá֑h şá֣̌m mé֤ţ ʼahàròn֙ wa⁠yi̇qá̇bé֣r şá̌֔m wa⁠yĕkahé֛n ʼelĕʻázá֥r bĕ̇n֖⁠wò ţȧẖĕţáֽ̇y⁠w׃"],[10,7,"מִ⁠שָּׁ֥ם נָסְע֖וּ הַ⁠גֻּדְגֹּ֑דָ⁠ה וּ⁠מִן־הַ⁠גֻּדְגֹּ֣דָ⁠ה יָטְבָ֔תָה אֶ֖רֶץ נַ֥חֲלֵי מָֽיִם׃","mi⁠şá֥̇̌m násĕʻ֖ẇ ha⁠gu̇dĕgò֑̇dá⁠h ẇ⁠min-ha⁠gu̇dĕgò֣̇dá⁠h yátĕbá֔ţáh ʼe֖reẕ na֥ẖàléy máֽyim׃"],[10,8,"בָּ⁠עֵ֣ת הַ⁠הִ֗וא הִבְדִּ֤יל יְהוָה֙ אֶת־שֵׁ֣בֶט הַ⁠לֵּוִ֔י לָ⁠שֵׂ֖את אֶת־אֲר֣וֹן בְּרִית־יְהוָ֑ה לַ⁠עֲמֹד֩ לִ⁠פְנֵ֨י יְהוָ֤ה לְ⁠שָֽׁרְת⁠וֹ֙ וּ⁠לְ⁠בָרֵ֣ךְ בִּ⁠שְׁמ֔⁠וֹ עַ֖ד הַ⁠יּ֥וֹם הַ⁠זֶּֽה׃","bá̇⁠ʻé֣ţ ha⁠hi֗wʼ hibĕdi֤̇yl yĕhwáh֙ ʼeţ-şé֣̌bet ha⁠lé̇wi֔y lá⁠şé֖̂ʼţ ʼeţ-ʼàr֣wòn bĕ̇riyţ-yĕhwá֑h la⁠ʻàmòd֩ li⁠pĕné֨y yĕhwá֤h lĕ⁠şáֽ̌rĕţ⁠wò֙ ẇ⁠lĕ⁠báré֣kĕ bi̇⁠şĕ̌m֔⁠wò ʻa֖d ha⁠ẏ֥wòm ha⁠zėֽh׃"],[10,9,"עַל־כֵּ֞ן לֹֽא־הָיָ֧ה לְ⁠לֵוִ֛י חֵ֥לֶק וְ⁠נַחֲלָ֖ה עִם־אֶחָ֑י⁠ו יְהוָה֙ ה֣וּא נַחֲלָת֔⁠וֹ כַּ⁠אֲשֶׁ֥ר דִּבֶּ֛ר יְהוָ֥ה אֱלֹהֶ֖י⁠ךָ לֽ⁠וֹ׃","ʻal-ké̇֞n lòֽʼ-háyá֧h lĕ⁠léwi֛y ẖé֥leq wĕ⁠naẖàlá֖h ʻim-ʼeẖá֑y⁠w yĕhwáh֙ h֣ẇʼ naẖàláţ֔⁠wò kȧ⁠ʼàşě֥r di̇bė֛r yĕhwá֥h ʼèlòhe֖y⁠ká lֽ⁠wò׃"],[10,10,"וְ⁠אָנֹכִ֞י עָמַ֣דְתִּי בָ⁠הָ֗ר כַּ⁠יָּמִים֙ הָ⁠רִ֣אשֹׁנִ֔ים אַרְבָּעִ֣ים י֔וֹם וְ⁠אַרְבָּעִ֖ים לָ֑יְלָה וַ⁠יִּשְׁמַ֨ע יְהוָ֜ה אֵלַ֗⁠י גַּ֚ם בַּ⁠פַּ֣עַם הַ⁠הִ֔וא לֹא־אָבָ֥ה יְהוָ֖ה הַשְׁחִיתֶֽ⁠ךָ׃","wĕ⁠ʼánòki֞y ʻáma֣dĕţi̇y bá⁠há֗r kȧ⁠yá̇miym֙ há⁠ri֣ʼşò̌ni֔ym ʼarĕbá̇ʻi֣ym y֔wòm wĕ⁠ʼarĕbá̇ʻi֖ym lá֑yĕláh wa⁠yi̇şĕ̌ma֨ʻ yĕhwá֜h ʼéla֗⁠y gȧ֚m bȧ⁠pȧ֣ʻam ha⁠hi֔wʼ lòʼ-ʼábá֥h yĕhwá֖h haşĕ̌ẖiyţeֽ⁠ká׃"],[10,11,"וַ⁠יֹּ֤אמֶר יְהוָה֙ אֵלַ֔⁠י ק֛וּם לֵ֥ךְ לְ⁠מַסַּ֖ע לִ⁠פְנֵ֣י הָ⁠עָ֑ם וְ⁠יָבֹ֨אוּ֙ וְ⁠יִֽרְשׁ֣וּ אֶת־הָ⁠אָ֔רֶץ אֲשֶׁר־נִשְׁבַּ֥עְתִּי לַ⁠אֲבֹתָ֖⁠ם לָ⁠תֵ֥ת לָ⁠הֶֽם׃פ","wa⁠yò֤̇ʼmer yĕhwáh֙ ʼéla֔⁠y q֛ẇm lé֥kĕ lĕ⁠masȧ֖ʻ li⁠pĕné֣y há⁠ʻá֑m wĕ⁠yábò֨ʼẇ֙ wĕ⁠yiֽrĕş֣̌ẇ ʼeţ-há⁠ʼá֔reẕ ʼàşěr-nişĕ̌bȧ֥ʻĕţi̇y la⁠ʼàbòţá֖⁠m lá⁠ţé֥ţ lá⁠heֽm׃p"],[10,12,"וְ⁠עַתָּה֙ יִשְׂרָאֵ֔ל מָ֚ה יְהוָ֣ה אֱלֹהֶ֔י⁠ךָ שֹׁאֵ֖ל מֵ⁠עִמָּ֑⁠ךְ כִּ֣י אִם־לְ֠⁠יִרְאָה אֶת־יְהוָ֨ה אֱלֹהֶ֜י⁠ךָ לָ⁠לֶ֤כֶת בְּ⁠כָל־דְּרָכָי⁠ו֙ וּ⁠לְ⁠אַהֲבָ֣ה אֹת֔⁠וֹ וְ⁠לַֽ⁠עֲבֹד֙ אֶת־יְהוָ֣ה אֱלֹהֶ֔י⁠ךָ בְּ⁠כָל־לְבָבְ⁠ךָ֖ וּ⁠בְ⁠כָל־נַפְשֶֽׁ⁠ךָ׃","wĕ⁠ʻaţá̇h֙ yişĕ̂ráʼé֔l má֚h yĕhwá֣h ʼèlòhe֔y⁠ká şò̌ʼé֖l mé⁠ʻimá֑̇⁠kĕ ki֣̇y ʼim-lĕ֠⁠yirĕʼáh ʼeţ-yĕhwá֨h ʼèlòhe֜y⁠ká lá⁠le֤keţ bĕ̇⁠kál-dĕ̇rákáy⁠w֙ ẇ⁠lĕ⁠ʼahàbá֣h ʼòţ֔⁠wò wĕ⁠laֽ⁠ʻàbòd֙ ʼeţ-yĕhwá֣h ʼèlòhe֔y⁠ká bĕ̇⁠kál-lĕbábĕ⁠ká֖ ẇ⁠bĕ⁠kál-napĕşěֽ⁠ká׃"],[10,13,"לִ⁠שְׁמֹ֞ר אֶת־מִצְוֺ֤ת יְהוָה֙ וְ⁠אֶת־חֻקֹּתָ֔י⁠ו אֲשֶׁ֛ר אָנֹכִ֥י מְצַוְּ⁠ךָ֖ הַ⁠יּ֑וֹם לְ⁠ט֖וֹב לָֽ⁠ךְ׃","li⁠şĕ̌mò֞r ʼeţ-miẕĕwֺ֤ţ yĕhwáh֙ wĕ⁠ʼeţ-ẖuqò̇ţá֔y⁠w ʼàşě֛r ʼánòki֥y mĕẕawĕ̇⁠ká֖ ha⁠ẏ֑wòm lĕ⁠t֖wòb láֽ⁠kĕ׃"],[10,14,"הֵ֚ן לַ⁠יהוָ֣ה אֱלֹהֶ֔י⁠ךָ הַ⁠שָּׁמַ֖יִם וּ⁠שְׁמֵ֣י הַ⁠שָּׁמָ֑יִם הָ⁠אָ֖רֶץ וְ⁠כָל־אֲשֶׁר־בָּֽ⁠הּ׃","hé֚n la⁠yhwá֣h ʼèlòhe֔y⁠ká ha⁠şá̇̌ma֖yim ẇ⁠şĕ̌mé֣y ha⁠şá̇̌má֑yim há⁠ʼá֖reẕ wĕ⁠kál-ʼàşěr-báֽ̇⁠ḣ׃"],[10,15,"רַ֧ק בַּ⁠אֲבֹתֶ֛י⁠ךָ חָשַׁ֥ק יְהוָ֖ה לְ⁠אַהֲבָ֣ה אוֹתָ֑⁠ם וַ⁠יִּבְחַ֞ר בְּ⁠זַרְעָ֣⁠ם אַחֲרֵי⁠הֶ֗ם בָּ⁠כֶ֛ם מִ⁠כָּל־הָ⁠עַמִּ֖ים כַּ⁠יּ֥וֹם הַ⁠זֶּה׃","ra֧q bȧ⁠ʼàbòţe֛y⁠ká ẖáşǎ֥q yĕhwá֖h lĕ⁠ʼahàbá֣h ʼwòţá֑⁠m wa⁠yi̇bĕẖa֞r bĕ̇⁠zarĕʻá֣⁠m ʼaẖàréy⁠he֗m bá̇⁠ke֛m mi⁠ká̇l-há⁠ʻami֖̇ym kȧ⁠ẏ֥wòm ha⁠zėh׃"],[10,16,"וּ⁠מַלְתֶּ֕ם אֵ֖ת עָרְלַ֣ת לְבַבְ⁠כֶ֑ם וְ⁠עָ֨רְפְּ⁠כֶ֔ם לֹ֥א תַקְשׁ֖וּ עֽוֹד׃","ẇ⁠malĕţė֕m ʼé֖ţ ʻárĕla֣ţ lĕbabĕ⁠ke֑m wĕ⁠ʻá֨rĕpĕ̇⁠ke֔m lò֥ʼ ţaqĕş֖̌ẇ ʻֽwòd׃"],[10,17,"כִּ֚י יְהוָ֣ה אֱלֹֽהֵי⁠כֶ֔ם ה֚וּא אֱלֹהֵ֣י הָֽ⁠אֱלֹהִ֔ים וַ⁠אֲדֹנֵ֖י הָ⁠אֲדֹנִ֑ים הָ⁠אֵ֨ל הַ⁠גָּדֹ֤ל הַ⁠גִּבֹּר֙ וְ⁠הַ⁠נּוֹרָ֔א אֲשֶׁר֙ לֹא־יִשָּׂ֣א פָנִ֔ים וְ⁠לֹ֥א יִקַּ֖ח שֹֽׁחַד׃","ki֚̇y yĕhwá֣h ʼèlòֽhéy⁠ke֔m h֚ẇʼ ʼèlòhé֣y háֽ⁠ʼèlòhi֔ym wa⁠ʼàdòné֖y há⁠ʼàdòni֑ym há⁠ʼé֨l ha⁠gá̇dò֤l ha⁠gi̇bò̇r֙ wĕ⁠ha⁠ṅwòrá֔ʼ ʼàşěr֙ lòʼ-yişá֣̇̂ʼ páni֔ym wĕ⁠lò֥ʼ yiqȧ֖ẖ şòֽ̌ẖad׃"],[10,18,"עֹשֶׂ֛ה מִשְׁפַּ֥ט יָת֖וֹם וְ⁠אַלְמָנָ֑ה וְ⁠אֹהֵ֣ב גֵּ֔ר לָ֥⁠תֶת ל֖⁠וֹ לֶ֥חֶם וְ⁠שִׂמְלָֽה׃","ʻòşê֛h mişĕ̌pȧ֥t yáţ֖wòm wĕ⁠ʼalĕmáná֑h wĕ⁠ʼòhé֣b gé̇֔r lá֥⁠ţeţ l֖⁠wò le֥ẖem wĕ⁠şîmĕláֽh׃"],[10,19,"וַ⁠אֲהַבְתֶּ֖ם אֶת־הַ⁠גֵּ֑ר כִּֽי־גֵרִ֥ים הֱיִיתֶ֖ם בְּ⁠אֶ֥רֶץ מִצְרָֽיִם׃","wa⁠ʼàhabĕţė֖m ʼeţ-ha⁠gé֑̇r kiֽ̇y-géri֥ym hèyiyţe֖m bĕ̇⁠ʼe֥reẕ miẕĕráֽyim׃"],[10,20,"אֶת־יְהוָ֧ה אֱלֹהֶ֛י⁠ךָ תִּירָ֖א אֹת֣⁠וֹ תַעֲבֹ֑ד וּ⁠ב֣⁠וֹ תִדְבָּ֔ק וּ⁠בִ⁠שְׁמ֖⁠וֹ תִּשָּׁבֵֽעַ׃","ʼeţ-yĕhwá֧h ʼèlòhe֛y⁠ká ţi̇yrá֖ʼ ʼòţ֣⁠wò ţaʻàbò֑d ẇ⁠b֣⁠wò ţidĕbá̇֔q ẇ⁠bi⁠şĕ̌m֖⁠wò ţi̇şá̇̌béֽʻa׃"],[10,21,"ה֥וּא תְהִלָּתְ⁠ךָ֖ וְ⁠ה֣וּא אֱלֹהֶ֑י⁠ךָ אֲשֶׁר־עָשָׂ֣ה אִתְּ⁠ךָ֗ אֶת־הַ⁠גְּדֹלֹ֤ת וְ⁠אֶת־הַ⁠נּֽוֹרָאֹת֙ הָ⁠אֵ֔לֶּה אֲשֶׁ֥ר רָא֖וּ עֵינֶֽי⁠ךָ׃","h֥ẇʼ ţĕhilá̇ţĕ⁠ká֖ wĕ⁠h֣ẇʼ ʼèlòhe֑y⁠ká ʼàşěr-ʻáşá֣̂h ʼiţĕ̇⁠ká֗ ʼeţ-ha⁠gĕ̇dòlò֤ţ wĕ⁠ʼeţ-ha⁠ṅֽwòráʼòţ֙ há⁠ʼé֔lėh ʼàşě֥r ráʼ֖ẇ ʻéyneֽy⁠ká׃"],[10,22,"בְּ⁠שִׁבְעִ֣ים נֶ֔פֶשׁ יָרְד֥וּ אֲבֹתֶ֖י⁠ךָ מִצְרָ֑יְמָ⁠הּ וְ⁠עַתָּ֗ה שָֽׂמְ⁠ךָ֙ יְהוָ֣ה אֱלֹהֶ֔י⁠ךָ כְּ⁠כוֹכְבֵ֥י הַ⁠שָּׁמַ֖יִם לָ⁠רֹֽב׃","bĕ̇⁠şǐbĕʻi֣ym ne֔peş̌ yárĕd֥ẇ ʼàbòţe֖y⁠ká miẕĕrá֑yĕmá⁠ḣ wĕ⁠ʻaţá̇֗h şáֽ̂mĕ⁠ká֙ yĕhwá֣h ʼèlòhe֔y⁠ká kĕ̇⁠kwòkĕbé֥y ha⁠şá̇̌ma֖yim lá⁠ròֽb׃"],[11,1,"וְ⁠אָ֣הַבְתָּ֔ אֵ֖ת יְהוָ֣ה אֱלֹהֶ֑י⁠ךָ וְ⁠שָׁמַרְתָּ֣ מִשְׁמַרְתּ֗⁠וֹ וְ⁠חֻקֹּתָ֧י⁠ו וּ⁠מִשְׁפָּטָ֛י⁠ו וּ⁠מִצְוֺתָ֖י⁠ו כָּל־הַ⁠יָּמִֽים׃","wĕ⁠ʼá֣habĕţá̇֔ ʼé֖ţ yĕhwá֣h ʼèlòhe֑y⁠ká wĕ⁠şá̌marĕţá֣̇ mişĕ̌marĕţ̇֗⁠wò wĕ⁠ẖuqò̇ţá֧y⁠w ẇ⁠mişĕ̌pá̇tá֛y⁠w ẇ⁠miẕĕwֺţá֖y⁠w ká̇l-ha⁠yá̇miֽym׃"],[11,2,"וִֽ⁠ידַעְתֶּם֮ הַ⁠יּוֹם֒ כִּ֣י ׀ לֹ֣א אֶת־בְּנֵי⁠כֶ֗ם אֲשֶׁ֤ר לֹֽא־יָדְעוּ֙ וַ⁠אֲשֶׁ֣ר לֹא־רָא֔וּ אֶת־מוּסַ֖ר יְהוָ֣ה אֱלֹהֵי⁠כֶ֑ם אֶת־גָּדְל֕⁠וֹ אֶת־יָד⁠וֹ֙ הַ⁠חֲזָקָ֔ה וּ⁠זְרֹע֖⁠וֹ הַ⁠נְּטוּיָֽה׃","wiֽ⁠ydaʻĕţėm֮ ha⁠ẏwòm֒ ki֣̇y ׀ lò֣ʼ ʼeţ-bĕ̇néy⁠ke֗m ʼàşě֤r lòֽʼ-yádĕʻẇ֙ wa⁠ʼàşě֣r lòʼ-ráʼ֔ẇ ʼeţ-mẇsa֖r yĕhwá֣h ʼèlòhéy⁠ke֑m ʼeţ-gá̇dĕl֕⁠wò ʼeţ-yád⁠wò֙ ha⁠ẖàzáqá֔h ẇ⁠zĕròʻ֖⁠wò ha⁠nĕ̇tẇyáֽh׃"],[11,3,"וְ⁠אֶת־אֹֽתֹתָי⁠ו֙ וְ⁠אֶֽת־מַעֲשָׂ֔י⁠ו אֲשֶׁ֥ר עָשָׂ֖ה בְּ⁠ת֣וֹךְ מִצְרָ֑יִם לְ⁠פַרְעֹ֥ה מֶֽלֶךְ־מִצְרַ֖יִם וּ⁠לְ⁠כָל־אַרְצֽ⁠וֹ׃","wĕ⁠ʼeţ-ʼòֽţòţáy⁠w֙ wĕ⁠ʼeֽţ-maʻàşá̂֔y⁠w ʼàşě֥r ʻáşá֖̂h bĕ̇⁠ţ֣wòkĕ miẕĕrá֑yim lĕ⁠parĕʻò֥h meֽlekĕ-miẕĕra֖yim ẇ⁠lĕ⁠kál-ʼarĕẕֽ⁠wò׃"],[11,4,"וַ⁠אֲשֶׁ֣ר עָשָׂה֩ לְ⁠חֵ֨יל מִצְרַ֜יִם לְ⁠סוּסָ֣י⁠ו וּ⁠לְ⁠רִכְבּ֗⁠וֹ אֲשֶׁ֨ר הֵצִ֜יף אֶת־מֵ֤י יַם־סוּף֙ עַל־פְּנֵי⁠הֶ֔ם בְּ⁠רָדְפָ֖⁠ם אַחֲרֵי⁠כֶ֑ם וַ⁠יְאַבְּדֵ֣⁠ם יְהוָ֔ה עַ֖ד הַ⁠יּ֥וֹם הַ⁠זֶּֽה׃","wa⁠ʼàşě֣r ʻáşá̂h֩ lĕ⁠ẖé֨yl miẕĕra֜yim lĕ⁠sẇsá֣y⁠w ẇ⁠lĕ⁠rikĕḃ֗⁠wò ʼàşě֨r héẕi֜yp ʼeţ-mé֤y yam-sẇp֙ ʻal-pĕ̇néy⁠he֔m bĕ̇⁠rádĕpá֖⁠m ʼaẖàréy⁠ke֑m wa⁠yĕʼabĕ̇dé֣⁠m yĕhwá֔h ʻa֖d ha⁠ẏ֥wòm ha⁠zėֽh׃"],[11,5,"וַ⁠אֲשֶׁ֥ר עָשָׂ֛ה לָ⁠כֶ֖ם בַּ⁠מִּדְבָּ֑ר עַד־בֹּאֲ⁠כֶ֖ם עַד־הַ⁠מָּק֥וֹם הַ⁠זֶּֽה׃","wa⁠ʼàşě֥r ʻáşá֛̂h lá⁠ke֖m bȧ⁠mi̇dĕbá֑̇r ʻad-bò̇ʼà⁠ke֖m ʻad-ha⁠má̇q֥wòm ha⁠zėֽh׃"],[11,6,"וַ⁠אֲשֶׁ֨ר עָשָׂ֜ה לְ⁠דָתָ֣ן וְ⁠לַ⁠אֲבִירָ֗ם בְּנֵ֣י אֱלִיאָב֮ בֶּן־רְאוּבֵן֒ אֲשֶׁ֨ר פָּצְתָ֤ה הָ⁠אָ֨רֶץ֙ אֶת־פִּ֔י⁠הָ וַ⁠תִּבְלָעֵ֥⁠ם וְ⁠אֶת־בָּתֵּי⁠הֶ֖ם וְ⁠אֶת־אָהֳלֵי⁠הֶ֑ם וְ⁠אֵ֤ת כָּל־הַ⁠יְקוּם֙ אֲשֶׁ֣ר בְּ⁠רַגְלֵי⁠הֶ֔ם בְּ⁠קֶ֖רֶב כָּל־יִשְׂרָאֵֽל׃","wa⁠ʼàşě֨r ʻáşá̂֜h lĕ⁠dáţá֣n wĕ⁠la⁠ʼàbiyrá֗m bĕ̇né֣y ʼèliyʼáb֮ bėn-rĕʼẇbén֒ ʼàşě֨r pá̇ẕĕţá֤h há⁠ʼá֨reẕ֙ ʼeţ-pi̇֔y⁠há wa⁠ţi̇bĕláʻé֥⁠m wĕ⁠ʼeţ-bá̇ţé̇y⁠he֖m wĕ⁠ʼeţ-ʼáholéy⁠he֑m wĕ⁠ʼé֤ţ ká̇l-ha⁠yĕqẇm֙ ʼàşě֣r bĕ̇⁠ragĕléy⁠he֔m bĕ̇⁠qe֖reb ká̇l-yişĕ̂ráʼéֽl׃"],[11,7,"כִּ֤י עֵֽינֵי⁠כֶם֙ הָֽ⁠רֹאֹ֔ת אֶת־כָּל־מַעֲשֵׂ֥ה יְהוָ֖ה הַ⁠גָּדֹ֑ל אֲשֶׁ֖ר עָשָֽׂה׃","ki֤̇y ʻéֽynéy⁠kem֙ háֽ⁠ròʼò֔ţ ʼeţ-ká̇l-maʻàşé֥̂h yĕhwá֖h ha⁠gá̇dò֑l ʼàşě֖r ʻáşáֽ̂h׃"],[11,8,"וּ⁠שְׁמַרְתֶּם֙ אֶת־כָּל־הַ⁠מִּצְוָ֔ה אֲשֶׁ֛ר אָנֹכִ֥י מְצַוְּ⁠ךָ֖ הַ⁠יּ֑וֹם לְמַ֣עַן תֶּחֶזְק֗וּ וּ⁠בָאתֶם֙ וִֽ⁠ירִשְׁתֶּ֣ם אֶת־הָ⁠אָ֔רֶץ אֲשֶׁ֥ר אַתֶּ֛ם עֹבְרִ֥ים שָׁ֖מָּ⁠ה לְ⁠רִשְׁתָּֽ⁠הּ׃","ẇ⁠şĕ̌marĕţėm֙ ʼeţ-ká̇l-ha⁠mi̇ẕĕwá֔h ʼàşě֛r ʼánòki֥y mĕẕawĕ̇⁠ká֖ ha⁠ẏ֑wòm lĕma֣ʻan ţėẖezĕq֗ẇ ẇ⁠báʼţem֙ wiֽ⁠yrişĕ̌ţė֣m ʼeţ-há⁠ʼá֔reẕ ʼàşě֥r ʼaţė֛m ʻòbĕri֥ym şá֖̌má̇⁠h lĕ⁠rişĕ̌ţáֽ̇⁠ḣ׃"],[11,9,"וּ⁠לְמַ֨עַן תַּאֲרִ֤יכוּ יָמִים֙ עַל־הָ֣⁠אֲדָמָ֔ה אֲשֶׁר֩ נִשְׁבַּ֨ע יְהוָ֧ה לַ⁠אֲבֹתֵי⁠כֶ֛ם לָ⁠תֵ֥ת לָ⁠הֶ֖ם וּ⁠לְ⁠זַרְעָ֑⁠ם אֶ֛רֶץ זָבַ֥ת חָלָ֖ב וּ⁠דְבָֽשׁ׃ס","ẇ⁠lĕma֨ʻan ţȧʼàri֤ykẇ yámiym֙ ʻal-há֣⁠ʼàdámá֔h ʼàşěr֩ nişĕ̌bȧ֨ʻ yĕhwá֧h la⁠ʼàbòţéy⁠ke֛m lá⁠ţé֥ţ lá⁠he֖m ẇ⁠lĕ⁠zarĕʻá֑⁠m ʼe֛reẕ zába֥ţ ẖálá֖b ẇ⁠dĕbáֽş̌׃s"],[11,10,"כִּ֣י הָ⁠אָ֗רֶץ אֲשֶׁ֨ר אַתָּ֤ה בָא־שָׁ֨מָּ⁠ה֙ לְ⁠רִשְׁתָּ֔⁠הּ לֹ֣א כְ⁠אֶ֤רֶץ מִצְרַ֨יִם֙ הִ֔וא אֲשֶׁ֥ר יְצָאתֶ֖ם מִ⁠שָּׁ֑ם אֲשֶׁ֤ר תִּזְרַע֙ אֶֽת־זַרְעֲ⁠ךָ֔ וְ⁠הִשְׁקִ֥יתָ בְ⁠רַגְלְ⁠ךָ֖ כְּ⁠גַ֥ן הַ⁠יָּרָֽק׃","ki֣̇y há⁠ʼá֗reẕ ʼàşě֨r ʼaţá֤̇h báʼ-şá̌֨má̇⁠h֙ lĕ⁠rişĕ̌ţá̇֔⁠ḣ lò֣ʼ kĕ⁠ʼe֤reẕ miẕĕra֨yim֙ hi֔wʼ ʼàşě֥r yĕẕáʼţe֖m mi⁠şá֑̇̌m ʼàşě֤r ţi̇zĕraʻ֙ ʼeֽţ-zarĕʻà⁠ká֔ wĕ⁠hişĕ̌qi֥yţá bĕ⁠ragĕlĕ⁠ká֖ kĕ̇⁠ga֥n ha⁠yá̇ráֽq׃"],[11,11,"וְ⁠הָ⁠אָ֗רֶץ אֲשֶׁ֨ר אַתֶּ֜ם עֹבְרִ֥ים שָׁ֨מָּ⁠ה֙ לְ⁠רִשְׁתָּ֔⁠הּ אֶ֥רֶץ הָרִ֖ים וּ⁠בְקָעֹ֑ת לִ⁠מְטַ֥ר הַ⁠שָּׁמַ֖יִם תִּשְׁתֶּה־מָּֽיִם׃","wĕ⁠há⁠ʼá֗reẕ ʼàşě֨r ʼaţė֜m ʻòbĕri֥ym şá̌֨má̇⁠h֙ lĕ⁠rişĕ̌ţá̇֔⁠ḣ ʼe֥reẕ hári֖ym ẇ⁠bĕqáʻò֑ţ li⁠mĕta֥r ha⁠şá̇̌ma֖yim ţi̇şĕ̌ţėh-máֽ̇yim׃"],[11,12,"אֶ֕רֶץ אֲשֶׁר־יְהוָ֥ה אֱלֹהֶ֖י⁠ךָ דֹּרֵ֣שׁ אֹתָ֑⁠הּ תָּמִ֗יד עֵינֵ֨י יְהוָ֤ה אֱלֹהֶ֨י⁠ךָ֙ בָּ֔⁠הּ מֵֽ⁠רֵשִׁית֙ הַ⁠שָּׁנָ֔ה וְ⁠עַ֖ד אַחֲרִ֥ית שָׁנָֽה׃ס","ʼe֕reẕ ʼàşěr-yĕhwá֥h ʼèlòhe֖y⁠ká dò̇ré֣ş̌ ʼòţá֑⁠ḣ ţá̇mi֗yd ʻéyné֨y yĕhwá֤h ʼèlòhe֨y⁠ká֙ bá̇֔⁠ḣ méֽ⁠réşǐyţ֙ ha⁠şá̇̌ná֔h wĕ⁠ʻa֖d ʼaẖàri֥yţ şá̌náֽh׃s"],[11,13,"וְ⁠הָיָ֗ה אִם־שָׁמֹ֤עַ תִּשְׁמְעוּ֙ אֶל־מִצְוֺתַ֔⁠י אֲשֶׁ֧ר אָנֹכִ֛י מְצַוֶּ֥ה אֶתְ⁠כֶ֖ם הַ⁠יּ֑וֹם לְ⁠אַהֲבָ֞ה אֶת־יְהוָ֤ה אֱלֹֽהֵי⁠כֶם֙ וּ⁠לְ⁠עָבְד֔⁠וֹ בְּ⁠כָל־לְבַבְ⁠כֶ֖ם וּ⁠בְ⁠כָל־נַפְשְׁ⁠כֶֽם׃","wĕ⁠háyá֗h ʼim-şá̌mò֤ʻa ţi̇şĕ̌mĕʻẇ֙ ʼel-miẕĕwֺţa֔⁠y ʼàşě֧r ʼánòki֛y mĕẕawė֥h ʼeţĕ⁠ke֖m ha⁠ẏ֑wòm lĕ⁠ʼahàbá֞h ʼeţ-yĕhwá֤h ʼèlòֽhéy⁠kem֙ ẇ⁠lĕ⁠ʻábĕd֔⁠wò bĕ̇⁠kál-lĕbabĕ⁠ke֖m ẇ⁠bĕ⁠kál-napĕşĕ̌⁠keֽm׃"],[11,14,"וְ⁠נָתַתִּ֧י מְטַֽר־אַרְצְ⁠כֶ֛ם בְּ⁠עִתּ֖⁠וֹ יוֹרֶ֣ה וּ⁠מַלְק֑וֹשׁ וְ⁠אָסַפְתָּ֣ דְגָנֶ֔⁠ךָ וְ⁠תִֽירֹשְׁ⁠ךָ֖ וְ⁠יִצְהָרֶֽ⁠ךָ׃","wĕ⁠náţaţi֧̇y mĕtaֽr-ʼarĕẕĕ⁠ke֛m bĕ̇⁠ʻiţ֖̇⁠wò ywòre֣h ẇ⁠malĕq֑wòş̌ wĕ⁠ʼásapĕţá֣̇ dĕgáne֔⁠ká wĕ⁠ţiֽyròşĕ̌⁠ká֖ wĕ⁠yiẕĕháreֽ⁠ká׃"],[11,15,"וְ⁠נָתַתִּ֛י עֵ֥שֶׂב בְּ⁠שָׂדְ⁠ךָ֖ לִ⁠בְהֶמְתֶּ֑⁠ךָ וְ⁠אָכַלְתָּ֖ וְ⁠שָׂבָֽעְתָּ׃","wĕ⁠náţaţi֛̇y ʻé֥şêb bĕ̇⁠şá̂dĕ⁠ká֖ li⁠bĕhemĕţė֑⁠ká wĕ⁠ʼákalĕţá֖̇ wĕ⁠şá̂báֽʻĕţá̇׃"],[11,16,"הִשָּֽׁמְר֣וּ לָ⁠כֶ֔ם פֶּ֥ן יִפְתֶּ֖ה לְבַבְ⁠כֶ֑ם וְ⁠סַרְתֶּ֗ם וַ⁠עֲבַדְתֶּם֙ אֱלֹהִ֣ים אֲחֵרִ֔ים וְ⁠הִשְׁתַּחֲוִיתֶ֖ם לָ⁠הֶֽם׃","hişáֽ̇̌mĕr֣ẇ lá⁠ke֔m pė֥n yipĕţė֖h lĕbabĕ⁠ke֑m wĕ⁠sarĕţė֗m wa⁠ʻàbadĕţėm֙ ʼèlòhi֣ym ʼàẖéri֔ym wĕ⁠hişĕ̌ţȧẖàwiyţe֖m lá⁠heֽm׃"],[11,17,"וְ⁠חָרָ֨ה אַף־יְהוָ֜ה בָּ⁠כֶ֗ם וְ⁠עָצַ֤ר אֶת־הַ⁠שָּׁמַ֨יִם֙ וְ⁠לֹֽא־יִהְיֶ֣ה מָטָ֔ר וְ⁠הָ֣⁠אֲדָמָ֔ה לֹ֥א תִתֵּ֖ן אֶת־יְבוּלָ֑⁠הּ וַ⁠אֲבַדְתֶּ֣ם מְהֵרָ֗ה מֵ⁠עַל֙ הָ⁠אָ֣רֶץ הַ⁠טֹּבָ֔ה אֲשֶׁ֥ר יְהוָ֖ה נֹתֵ֥ן לָ⁠כֶֽם׃","wĕ⁠ẖárá֨h ʼap-yĕhwá֜h bá̇⁠ke֗m wĕ⁠ʻáẕa֤r ʼeţ-ha⁠şá̇̌ma֨yim֙ wĕ⁠lòֽʼ-yihĕye֣h mátá֔r wĕ⁠há֣⁠ʼàdámá֔h lò֥ʼ ţiţé֖̇n ʼeţ-yĕbẇlá֑⁠ḣ wa⁠ʼàbadĕţė֣m mĕhérá֗h mé⁠ʻal֙ há⁠ʼá֣reẕ ha⁠tò̇bá֔h ʼàşě֥r yĕhwá֖h nòţé֥n lá⁠keֽm׃"],[11,18,"וְ⁠שַׂמְתֶּם֙ אֶת־דְּבָרַ֣⁠י אֵ֔לֶּה עַל־לְבַבְ⁠כֶ֖ם וְ⁠עַֽל־נַפְשְׁ⁠כֶ֑ם וּ⁠קְשַׁרְתֶּ֨ם אֹתָ֤⁠ם לְ⁠אוֹת֙ עַל־יֶדְ⁠כֶ֔ם וְ⁠הָי֥וּ לְ⁠טוֹטָפֹ֖ת בֵּ֥ין עֵינֵי⁠כֶֽם׃","wĕ⁠şâmĕţėm֙ ʼeţ-dĕ̇bára֣⁠y ʼé֔lėh ʻal-lĕbabĕ⁠ke֖m wĕ⁠ʻaֽl-napĕşĕ̌⁠ke֑m ẇ⁠qĕşǎrĕţė֨m ʼòţá֤⁠m lĕ⁠ʼwòţ֙ ʻal-yedĕ⁠ke֔m wĕ⁠háy֥ẇ lĕ⁠twòtápò֖ţ bé֥̇yn ʻéynéy⁠keֽm׃"],[11,19,"וְ⁠לִמַּדְתֶּ֥ם אֹתָ֛⁠ם אֶת־בְּנֵי⁠כֶ֖ם לְ⁠דַבֵּ֣ר בָּ֑⁠ם בְּ⁠שִׁבְתְּ⁠ךָ֤ בְּ⁠בֵיתֶ֨⁠ךָ֙ וּ⁠בְ⁠לֶכְתְּ⁠ךָ֣ בַ⁠דֶּ֔רֶךְ וּֽ⁠בְ⁠שָׁכְבְּ⁠ךָ֖ וּ⁠בְ⁠קוּמֶֽ⁠ךָ׃","wĕ⁠limȧdĕţė֥m ʼòţá֛⁠m ʼeţ-bĕ̇néy⁠ke֖m lĕ⁠dabé֣̇r bá֑̇⁠m bĕ̇⁠şǐbĕţĕ̇⁠ká֤ bĕ̇⁠béyţe֨⁠ká֙ ẇ⁠bĕ⁠lekĕţĕ̇⁠ká֣ ba⁠dė֔rekĕ ẇֽ⁠bĕ⁠şá̌kĕbĕ̇⁠ká֖ ẇ⁠bĕ⁠qẇmeֽ⁠ká׃"],[11,20,"וּ⁠כְתַבְתָּ֛⁠ם עַל־מְזוּז֥וֹת בֵּיתֶ֖⁠ךָ וּ⁠בִ⁠שְׁעָרֶֽי⁠ךָ׃","ẇ⁠kĕţabĕţá֛̇⁠m ʻal-mĕzẇz֥wòţ bé̇yţe֖⁠ká ẇ⁠bi⁠şĕ̌ʻáreֽy⁠ká׃"],[11,21,"לְמַ֨עַן יִרְבּ֤וּ יְמֵי⁠כֶם֙ וִ⁠ימֵ֣י בְנֵי⁠כֶ֔ם עַ֚ל הָֽ⁠אֲדָמָ֔ה אֲשֶׁ֨ר נִשְׁבַּ֧ע יְהוָ֛ה לַ⁠אֲבֹתֵי⁠כֶ֖ם לָ⁠תֵ֣ת לָ⁠הֶ֑ם כִּ⁠ימֵ֥י הַ⁠שָּׁמַ֖יִם עַל־הָ⁠אָֽרֶץ׃ס","lĕma֨ʻan yirĕḃ֤ẇ yĕméy⁠kem֙ wi⁠ymé֣y bĕnéy⁠ke֔m ʻa֚l háֽ⁠ʼàdámá֔h ʼàşě֨r nişĕ̌bȧ֧ʻ yĕhwá֛h la⁠ʼàbòţéy⁠ke֖m lá⁠ţé֣ţ lá⁠he֑m ki̇⁠ymé֥y ha⁠şá̇̌ma֖yim ʻal-há⁠ʼáֽreẕ׃s"],[11,22,"כִּי֩ אִם־שָׁמֹ֨ר תִּשְׁמְר֜וּ⁠ן אֶת־כָּל־הַ⁠מִּצְוָ֣ה הַ⁠זֹּ֗את אֲשֶׁ֧ר אָנֹכִ֛י מְצַוֶּ֥ה אֶתְ⁠כֶ֖ם לַ⁠עֲשֹׂתָ֑⁠הּ לְ⁠אַהֲבָ֞ה אֶת־יְהוָ֧ה אֱלֹהֵי⁠כֶ֛ם לָ⁠לֶ֥כֶת בְּ⁠כָל־דְּרָכָ֖י⁠ו וּ⁠לְ⁠דָבְקָה־בֽ⁠וֹ׃","ki̇y֩ ʼim-şá̌mò֨r ţi̇şĕ̌mĕr֜ẇ⁠n ʼeţ-ká̇l-ha⁠mi̇ẕĕwá֣h ha⁠zò̇֗ʼţ ʼàşě֧r ʼánòki֛y mĕẕawė֥h ʼeţĕ⁠ke֖m la⁠ʻàşò̂ţá֑⁠ḣ lĕ⁠ʼahàbá֞h ʼeţ-yĕhwá֧h ʼèlòhéy⁠ke֛m lá⁠le֥keţ bĕ̇⁠kál-dĕ̇ráká֖y⁠w ẇ⁠lĕ⁠dábĕqáh-bֽ⁠wò׃"],[11,23,"וְ⁠הוֹרִ֧ישׁ יְהוָ֛ה אֶת־כָּל־הַ⁠גּוֹיִ֥ם הָ⁠אֵ֖לֶּה מִ⁠לִּ⁠פְנֵי⁠כֶ֑ם וִֽ⁠ירִשְׁתֶּ֣ם גּוֹיִ֔ם גְּדֹלִ֥ים וַ⁠עֲצֻמִ֖ים מִ⁠כֶּֽם׃","wĕ⁠hwòri֧yş̌ yĕhwá֛h ʼeţ-ká̇l-ha⁠ġwòyi֥m há⁠ʼé֖lėh mi⁠li̇⁠pĕnéy⁠ke֑m wiֽ⁠yrişĕ̌ţė֣m ġwòyi֔m gĕ̇dòli֥ym wa⁠ʻàẕumi֖ym mi⁠kėֽm׃"],[11,24,"כָּל־הַ⁠מָּק֗וֹם אֲשֶׁ֨ר תִּדְרֹ֧ךְ כַּֽף־רַגְלְ⁠כֶ֛ם בּ֖⁠וֹ לָ⁠כֶ֣ם יִהְיֶ֑ה מִן־הַ⁠מִּדְבָּ֨ר וְ⁠הַ⁠לְּבָנ֜וֹן מִן־הַ⁠נָּהָ֣ר נְהַר־פְּרָ֗ת וְ⁠עַד֙ הַ⁠יָּ֣ם הָֽ⁠אַחֲר֔וֹן יִהְיֶ֖ה גְּבֻלְ⁠כֶֽם׃","ká̇l-ha⁠má̇q֗wòm ʼàşě֨r ţi̇dĕrò֧kĕ kȧֽp-ragĕlĕ⁠ke֛m ḃ֖⁠wò lá⁠ke֣m yihĕye֑h min-ha⁠mi̇dĕbá̇֨r wĕ⁠ha⁠lĕ̇bán֜wòn min-ha⁠ná̇há֣r nĕhar-pĕ̇rá֗ţ wĕ⁠ʻad֙ ha⁠yá֣̇m háֽ⁠ʼaẖàr֔wòn yihĕye֖h gĕ̇bulĕ⁠keֽm׃"],[11,25,"לֹא־יִתְיַצֵּ֥ב אִ֖ישׁ בִּ⁠פְנֵי⁠כֶ֑ם פַּחְדְּ⁠כֶ֨ם וּ⁠מֽוֹרַאֲ⁠כֶ֜ם יִתֵּ֣ן ׀ יְהוָ֣ה אֱלֹֽהֵי⁠כֶ֗ם עַל־פְּנֵ֤י כָל־הָ⁠אָ֨רֶץ֙ אֲשֶׁ֣ר תִּדְרְכוּ־בָ֔⁠הּ כַּ⁠אֲשֶׁ֖ר דִּבֶּ֥ר לָ⁠כֶֽם׃ס","lòʼ-yiţĕyaẕé֥̇b ʼi֖yş̌ bi̇⁠pĕnéy⁠ke֑m pȧẖĕdĕ̇⁠ke֨m ẇ⁠mֽwòraʼà⁠ke֜m yiţé֣̇n ׀ yĕhwá֣h ʼèlòֽhéy⁠ke֗m ʻal-pĕ̇né֤y kál-há⁠ʼá֨reẕ֙ ʼàşě֣r ţi̇dĕrĕkẇ-bá֔⁠ḣ kȧ⁠ʼàşě֖r di̇bė֥r lá⁠keֽm׃s"],[11,26,"רְאֵ֗ה אָנֹכִ֛י נֹתֵ֥ן לִ⁠פְנֵי⁠כֶ֖ם הַ⁠יּ֑וֹם בְּרָכָ֖ה וּ⁠קְלָלָֽה׃","rĕʼé֗h ʼánòki֛y nòţé֥n li⁠pĕnéy⁠ke֖m ha⁠ẏ֑wòm bĕ̇ráká֖h ẇ⁠qĕláláֽh׃"],[11,27,"אֶֽת־הַ⁠בְּרָכָ֑ה אֲשֶׁ֣ר תִּשְׁמְע֗וּ אֶל־מִצְוֺת֙ יְהוָ֣ה אֱלֹֽהֵי⁠כֶ֔ם אֲשֶׁ֧ר אָנֹכִ֛י מְצַוֶּ֥ה אֶתְ⁠כֶ֖ם הַ⁠יּֽוֹם׃","ʼeֽţ-ha⁠bĕ̇ráká֑h ʼàşě֣r ţi̇şĕ̌mĕʻ֗ẇ ʼel-miẕĕwֺţ֙ yĕhwá֣h ʼèlòֽhéy⁠ke֔m ʼàşě֧r ʼánòki֛y mĕẕawė֥h ʼeţĕ⁠ke֖m ha⁠ẏֽwòm׃"],[11,28,"וְ⁠הַ⁠קְּלָלָ֗ה אִם־לֹ֤א תִשְׁמְעוּ֙ אֶל־מִצְוֺת֙ יְהוָ֣ה אֱלֹֽהֵי⁠כֶ֔ם וְ⁠סַרְתֶּ֣ם מִן־הַ⁠דֶּ֔רֶךְ אֲשֶׁ֧ר אָנֹכִ֛י מְצַוֶּ֥ה אֶתְ⁠כֶ֖ם הַ⁠יּ֑וֹם לָ⁠לֶ֗כֶת אַחֲרֵ֛י אֱלֹהִ֥ים אֲחֵרִ֖ים אֲשֶׁ֥ר לֹֽא־יְדַעְתֶּֽם׃ס","wĕ⁠ha⁠qĕ̇lálá֗h ʼim-lò֤ʼ ţişĕ̌mĕʻẇ֙ ʼel-miẕĕwֺţ֙ yĕhwá֣h ʼèlòֽhéy⁠ke֔m wĕ⁠sarĕţė֣m min-ha⁠dė֔rekĕ ʼàşě֧r ʼánòki֛y mĕẕawė֥h ʼeţĕ⁠ke֖m ha⁠ẏ֑wòm lá⁠le֗keţ ʼaẖàré֛y ʼèlòhi֥ym ʼàẖéri֖ym ʼàşě֥r lòֽʼ-yĕdaʻĕţėֽm׃s"],[11,29,"וְ⁠הָיָ֗ה כִּ֤י יְבִֽיאֲ⁠ךָ֙ יְהוָ֣ה אֱלֹהֶ֔י⁠ךָ אֶל־הָ⁠אָ֕רֶץ אֲשֶׁר־אַתָּ֥ה בָא־שָׁ֖מָּ⁠ה לְ⁠רִשְׁתָּ֑⁠הּ וְ⁠נָתַתָּ֤ה אֶת־הַ⁠בְּרָכָה֙ עַל־הַ֣ר גְּרִזִ֔ים וְ⁠אֶת־הַ⁠קְּלָלָ֖ה עַל־הַ֥ר עֵיבָֽל׃","wĕ⁠háyá֗h ki֤̇y yĕbiֽyʼà⁠ká֙ yĕhwá֣h ʼèlòhe֔y⁠ká ʼel-há⁠ʼá֕reẕ ʼàşěr-ʼaţá֥̇h báʼ-şá֖̌má̇⁠h lĕ⁠rişĕ̌ţá֑̇⁠ḣ wĕ⁠náţaţá֤̇h ʼeţ-ha⁠bĕ̇rákáh֙ ʻal-ha֣r gĕ̇rizi֔ym wĕ⁠ʼeţ-ha⁠qĕ̇lálá֖h ʻal-ha֥r ʻéybáֽl׃"],[11,30,"הֲ⁠לֹא־הֵ֜מָּה בְּ⁠עֵ֣בֶר הַ⁠יַּרְדֵּ֗ן אַֽחֲרֵי֙ דֶּ֚רֶךְ מְב֣וֹא הַ⁠שֶּׁ֔מֶשׁ בְּ⁠אֶ֨רֶץ֙ הַֽ⁠כְּנַעֲנִ֔י הַ⁠יֹּשֵׁ֖ב בָּ⁠עֲרָבָ֑ה מ֚וּל הַ⁠גִּלְגָּ֔ל אֵ֖צֶל אֵלוֹנֵ֥י מֹרֶֽה׃","hà⁠lòʼ-hé֜má̇h bĕ̇⁠ʻé֣ber ha⁠yȧrĕdé̇֗n ʼaֽẖàréy֙ dė֚rekĕ mĕb֣wòʼ ha⁠şė̌֔meş̌ bĕ̇⁠ʼe֨reẕ֙ haֽ⁠kĕ̇naʻàni֔y ha⁠yò̇şé֖̌b bá̇⁠ʻàrábá֑h m֚ẇl ha⁠gi̇lĕgá̇֔l ʼé֖ẕel ʼélwòné֥y mòreֽh׃"],[11,31,"כִּ֤י אַתֶּם֙ עֹבְרִ֣ים אֶת־הַ⁠יַּרְדֵּ֔ן לָ⁠בֹא֙ לָ⁠רֶ֣שֶׁת אֶת־הָ⁠אָ֔רֶץ אֲשֶׁר־יְהוָ֥ה אֱלֹהֵי⁠כֶ֖ם נֹתֵ֣ן לָ⁠כֶ֑ם וִֽ⁠ירִשְׁתֶּ֥ם אֹתָ֖⁠הּ וִֽ⁠ישַׁבְתֶּם־בָּֽ⁠הּ׃","ki֤̇y ʼaţėm֙ ʻòbĕri֣ym ʼeţ-ha⁠yȧrĕdé̇֔n lá⁠bòʼ֙ lá⁠re֣şěţ ʼeţ-há⁠ʼá֔reẕ ʼàşěr-yĕhwá֥h ʼèlòhéy⁠ke֖m nòţé֣n lá⁠ke֑m wiֽ⁠yrişĕ̌ţė֥m ʼòţá֖⁠ḣ wiֽ⁠yşǎbĕţėm-báֽ̇⁠ḣ׃"],[11,32,"וּ⁠שְׁמַרְתֶּ֣ם לַ⁠עֲשׂ֔וֹת אֵ֥ת כָּל־הַֽ⁠חֻקִּ֖ים וְ⁠אֶת־הַ⁠מִּשְׁפָּטִ֑ים אֲשֶׁ֧ר אָנֹכִ֛י נֹתֵ֥ן לִ⁠פְנֵי⁠כֶ֖ם הַ⁠יּֽוֹם׃","ẇ⁠şĕ̌marĕţė֣m la⁠ʻàş̂֔wòţ ʼé֥ţ ká̇l-haֽ⁠ẖuqi֖̇ym wĕ⁠ʼeţ-ha⁠mi̇şĕ̌pá̇ti֑ym ʼàşě֧r ʼánòki֛y nòţé֥n li⁠pĕnéy⁠ke֖m ha⁠ẏֽwòm׃"],[12,1,"אֵ֠לֶּה הַֽ⁠חֻקִּ֣ים וְ⁠הַ⁠מִּשְׁפָּטִים֮ אֲשֶׁ֣ר תִּשְׁמְר֣וּ⁠ן לַ⁠עֲשׂוֹת֒ בָּ⁠אָ֕רֶץ אֲשֶׁר֩ נָתַ֨ן יְהוָ֜ה אֱלֹהֵ֧י אֲבֹתֶ֛י⁠ךָ לְ⁠ךָ֖ לְ⁠רִשְׁתָּ֑⁠הּ כָּל־הַ⁠יָּמִ֔ים אֲשֶׁר־אַתֶּ֥ם חַיִּ֖ים עַל־הָ⁠אֲדָמָֽה׃","ʼé֠lėh haֽ⁠ẖuqi֣̇ym wĕ⁠ha⁠mi̇şĕ̌pá̇tiym֮ ʼàşě֣r ţi̇şĕ̌mĕr֣ẇ⁠n la⁠ʻàş̂wòţ֒ bá̇⁠ʼá֕reẕ ʼàşěr֩ náţa֨n yĕhwá֜h ʼèlòhé֧y ʼàbòţe֛y⁠ká lĕ⁠ká֖ lĕ⁠rişĕ̌ţá֑̇⁠ḣ ká̇l-ha⁠yá̇mi֔ym ʼàşěr-ʼaţė֥m ẖayi֖̇ym ʻal-há⁠ʼàdámáֽh׃"],[12,2,"אַבֵּ֣ד תְּ֠אַבְּדוּ⁠ן אֶֽת־כָּל־הַ⁠מְּקֹמ֞וֹת אֲשֶׁ֧ר עָֽבְדוּ־שָׁ֣ם הַ⁠גּוֹיִ֗ם אֲשֶׁ֥ר אַתֶּ֛ם יֹרְשִׁ֥ים אֹתָ֖⁠ם אֶת־אֱלֹהֵי⁠הֶ֑ם עַל־הֶ⁠הָרִ֤ים הָֽ⁠רָמִים֙ וְ⁠עַל־הַ⁠גְּבָע֔וֹת וְ⁠תַ֖חַת כָּל־עֵ֥ץ רַעֲנָן׃","ʼabé֣̇d ţĕ̇֠ʼabĕ̇dẇ⁠n ʼeֽţ-ká̇l-ha⁠mĕ̇qòm֞wòţ ʼàşě֧r ʻáֽbĕdẇ-şá֣̌m ha⁠ġwòyi֗m ʼàşě֥r ʼaţė֛m yòrĕşǐ֥ym ʼòţá֖⁠m ʼeţ-ʼèlòhéy⁠he֑m ʻal-he⁠hári֤ym háֽ⁠rámiym֙ wĕ⁠ʻal-ha⁠gĕ̇báʻ֔wòţ wĕ⁠ţa֖ẖaţ ká̇l-ʻé֥ẕ raʻànán׃"],[12,3,"וְ⁠נִתַּצְתֶּ֣ם אֶת־מִזְבּחֹתָ֗⁠ם וְ⁠שִׁבַּרְתֶּם֙ אֶת־מַצֵּ֣בֹתָ֔⁠ם וַ⁠אֲשֵֽׁרֵי⁠הֶם֙ תִּשְׂרְפ֣וּ⁠ן בָּ⁠אֵ֔שׁ וּ⁠פְסִילֵ֥י אֱלֹֽהֵי⁠הֶ֖ם תְּגַדֵּע֑וּ⁠ן וְ⁠אִבַּדְתֶּ֣ם אֶת־שְׁמָ֔⁠ם מִן־הַ⁠מָּק֖וֹם הַ⁠הֽוּא׃","wĕ⁠niţȧẕĕţė֣m ʼeţ-mizĕḃẖòţá֗⁠m wĕ⁠şǐbȧrĕţėm֙ ʼeţ-maẕé֣̇bòţá֔⁠m wa⁠ʼàşéֽ̌réy⁠hem֙ ţi̇şĕ̂rĕp֣ẇ⁠n bá̇⁠ʼé֔ş̌ ẇ⁠pĕsiylé֥y ʼèlòֽhéy⁠he֖m ţĕ̇gadé̇ʻ֑ẇ⁠n wĕ⁠ʼibȧdĕţė֣m ʼeţ-şĕ̌má֔⁠m min-ha⁠má̇q֖wòm ha⁠hֽẇʼ׃"],[12,4,"לֹֽא־תַעֲשׂ֣וּ⁠ן כֵּ֔ן לַ⁠יהוָ֖ה אֱלֹהֵי⁠כֶֽם׃","lòֽʼ-ţaʻàş֣̂ẇ⁠n ké̇֔n la⁠yhwá֖h ʼèlòhéy⁠keֽm׃"],[12,5,"כִּ֠י אִֽם־אֶל־הַ⁠מָּק֞וֹם אֲשֶׁר־יִבְחַ֨ר יְהוָ֤ה אֱלֹֽהֵי⁠כֶם֙ מִ⁠כָּל־שִׁבְטֵי⁠כֶ֔ם לָ⁠שׂ֥וּם אֶת־שְׁמ֖⁠וֹ שָׁ֑ם לְ⁠שִׁכְנ֥⁠וֹ תִדְרְשׁ֖וּ וּ⁠בָ֥אתָ שָֽׁמָּ⁠ה׃","ki̇֠y ʼiֽm-ʼel-ha⁠má̇q֞wòm ʼàşěr-yibĕẖa֨r yĕhwá֤h ʼèlòֽhéy⁠kem֙ mi⁠ká̇l-şǐbĕtéy⁠ke֔m lá⁠ş֥̂ẇm ʼeţ-şĕ̌m֖⁠wò şá֑̌m lĕ⁠şǐkĕn֥⁠wò ţidĕrĕş֖̌ẇ ẇ⁠bá֥ʼţá şáֽ̌má̇⁠h׃"],[12,6,"וַ⁠הֲבֵאתֶ֣ם שָׁ֗מָּ⁠ה עֹלֹֽתֵי⁠כֶם֙ וְ⁠זִבְחֵי⁠כֶ֔ם וְ⁠אֵת֙ מַעְשְׂרֹ֣תֵי⁠כֶ֔ם וְ⁠אֵ֖ת תְּרוּמַ֣ת יֶדְ⁠כֶ֑ם וְ⁠נִדְרֵי⁠כֶם֙ וְ⁠נִדְבֹ֣תֵי⁠כֶ֔ם וּ⁠בְכֹרֹ֥ת בְּקַרְ⁠כֶ֖ם וְ⁠צֹאנְ⁠כֶֽם׃","wa⁠hàbéʼţe֣m şá̌֗má̇⁠h ʻòlòֽţéy⁠kem֙ wĕ⁠zibĕẖéy⁠ke֔m wĕ⁠ʼéţ֙ maʻĕşĕ̂rò֣ţéy⁠ke֔m wĕ⁠ʼé֖ţ ţĕ̇rẇma֣ţ yedĕ⁠ke֑m wĕ⁠nidĕréy⁠kem֙ wĕ⁠nidĕbò֣ţéy⁠ke֔m ẇ⁠bĕkòrò֥ţ bĕ̇qarĕ⁠ke֖m wĕ⁠ẕòʼnĕ⁠keֽm׃"],[12,7,"וַ⁠אֲכַלְתֶּם־שָׁ֗ם לִ⁠פְנֵי֙ יְהוָ֣ה אֱלֹֽהֵי⁠כֶ֔ם וּ⁠שְׂמַחְתֶּ֗ם בְּ⁠כֹל֙ מִשְׁלַ֣ח יֶדְ⁠כֶ֔ם אַתֶּ֖ם וּ⁠בָתֵּי⁠כֶ֑ם אֲשֶׁ֥ר בֵּֽרַכְ⁠ךָ֖ יְהוָ֥ה אֱלֹהֶֽי⁠ךָ׃","wa⁠ʼàkalĕţėm-şá̌֗m li⁠pĕnéy֙ yĕhwá֣h ʼèlòֽhéy⁠ke֔m ẇ⁠şĕ̂maẖĕţė֗m bĕ̇⁠kòl֙ mişĕ̌la֣ẖ yedĕ⁠ke֔m ʼaţė֖m ẇ⁠báţé̇y⁠ke֑m ʼàşě֥r béֽ̇rakĕ⁠ká֖ yĕhwá֥h ʼèlòheֽy⁠ká׃"],[12,8,"לֹ֣א תַעֲשׂ֔וּ⁠ן כְּ֠⁠כֹל אֲשֶׁ֨ר אֲנַ֧חְנוּ עֹשִׂ֛ים פֹּ֖ה הַ⁠יּ֑וֹם אִ֖ישׁ כָּל־הַ⁠יָּשָׁ֥ר בְּ⁠עֵינָֽי⁠ו׃","lò֣ʼ ţaʻàş̂֔ẇ⁠n kĕ̇֠⁠kòl ʼàşě֨r ʼàna֧ẖĕnẇ ʻòşî֛ym pò֖̇h ha⁠ẏ֑wòm ʼi֖yş̌ ká̇l-ha⁠yá̇şá֥̌r bĕ̇⁠ʻéynáֽy⁠w׃"],[12,9,"כִּ֥י לֹא־בָּאתֶ֖ם עַד־עָ֑תָּה אֶל־הַ⁠מְּנוּחָה֙ וְ⁠אֶל־הַֽ⁠נַּחֲלָ֔ה אֲשֶׁר־יְהוָ֥ה אֱלֹהֶ֖י⁠ךָ נֹתֵ֥ן לָֽ⁠ךְ׃","ki֥̇y lòʼ-bá̇ʼţe֖m ʻad-ʻá֑ţá̇h ʼel-ha⁠mĕ̇nẇẖáh֙ wĕ⁠ʼel-haֽ⁠nȧẖàlá֔h ʼàşěr-yĕhwá֥h ʼèlòhe֖y⁠ká nòţé֥n láֽ⁠kĕ׃"],[12,10,"וַ⁠עֲבַרְתֶּם֮ אֶת־הַ⁠יַּרְדֵּן֒ וִֽ⁠ישַׁבְתֶּ֣ם בָּ⁠אָ֔רֶץ אֲשֶׁר־יְהוָ֥ה אֱלֹהֵי⁠כֶ֖ם מַנְחִ֣יל אֶתְ⁠כֶ֑ם וְ⁠הֵנִ֨יחַ לָ⁠כֶ֧ם מִ⁠כָּל־אֹיְבֵי⁠כֶ֛ם מִ⁠סָּבִ֖יב וִֽ⁠ישַׁבְתֶּם־בֶּֽטַח׃","wa⁠ʻàbarĕţėm֮ ʼeţ-ha⁠yȧrĕdé̇n֒ wiֽ⁠yşǎbĕţė֣m bá̇⁠ʼá֔reẕ ʼàşěr-yĕhwá֥h ʼèlòhéy⁠ke֖m manĕẖi֣yl ʼeţĕ⁠ke֑m wĕ⁠héni֨yẖa lá⁠ke֧m mi⁠ká̇l-ʼòyĕbéy⁠ke֛m mi⁠sá̇bi֖yb wiֽ⁠yşǎbĕţėm-bėֽtaẖ׃"],[12,11,"וְ⁠הָיָ֣ה הַ⁠מָּק֗וֹם אֲשֶׁר־יִבְחַר֩ יְהוָ֨ה אֱלֹהֵי⁠כֶ֥ם בּ⁠וֹ֙ לְ⁠שַׁכֵּ֤ן שְׁמ⁠וֹ֙ שָׁ֔ם שָׁ֣מָּ⁠ה תָבִ֔יאוּ אֵ֛ת כָּל־אֲשֶׁ֥ר אָנֹכִ֖י מְצַוֶּ֣ה אֶתְ⁠כֶ֑ם עוֹלֹתֵי⁠כֶ֣ם וְ⁠זִבְחֵי⁠כֶ֗ם מַעְשְׂרֹֽתֵי⁠כֶם֙ וּ⁠תְרֻמַ֣ת יֶדְ⁠כֶ֔ם וְ⁠כֹל֙ מִבְחַ֣ר נִדְרֵי⁠כֶ֔ם אֲשֶׁ֥ר תִּדְּר֖וּ לַֽ⁠יהוָֽה׃","wĕ⁠háyá֣h ha⁠má̇q֗wòm ʼàşěr-yibĕẖar֩ yĕhwá֨h ʼèlòhéy⁠ke֥m ḃ⁠wò֙ lĕ⁠şǎké֤̇n şĕ̌m⁠wò֙ şá̌֔m şá֣̌má̇⁠h ţábi֔yʼẇ ʼé֛ţ ká̇l-ʼàşě֥r ʼánòki֖y mĕẕawė֣h ʼeţĕ⁠ke֑m ʻwòlòţéy⁠ke֣m wĕ⁠zibĕẖéy⁠ke֗m maʻĕşĕ̂ròֽţéy⁠kem֙ ẇ⁠ţĕruma֣ţ yedĕ⁠ke֔m wĕ⁠kòl֙ mibĕẖa֣r nidĕréy⁠ke֔m ʼàşě֥r ţi̇dĕ̇r֖ẇ laֽ⁠yhwáֽh׃"],[12,12,"וּ⁠שְׂמַחְתֶּ֗ם לִ⁠פְנֵי֮ יְהוָ֣ה אֱלֹֽהֵי⁠כֶם֒ אַתֶּ֗ם וּ⁠בְנֵי⁠כֶם֙ וּ⁠בְנֹ֣תֵי⁠כֶ֔ם וְ⁠עַבְדֵי⁠כֶ֖ם וְ⁠אַמְהֹתֵי⁠כֶ֑ם וְ⁠הַ⁠לֵּוִי֙ אֲשֶׁ֣ר בְּ⁠שַֽׁעֲרֵי⁠כֶ֔ם כִּ֣י אֵ֥ין ל֛⁠וֹ חֵ֥לֶק וְ⁠נַחֲלָ֖ה אִתְּ⁠כֶֽם׃","ẇ⁠şĕ̂maẖĕţė֗m li⁠pĕnéy֮ yĕhwá֣h ʼèlòֽhéy⁠kem֒ ʼaţė֗m ẇ⁠bĕnéy⁠kem֙ ẇ⁠bĕnò֣ţéy⁠ke֔m wĕ⁠ʻabĕdéy⁠ke֖m wĕ⁠ʼamĕhòţéy⁠ke֑m wĕ⁠ha⁠lé̇wiy֙ ʼàşě֣r bĕ̇⁠şǎֽʻàréy⁠ke֔m ki֣̇y ʼé֥yn l֛⁠wò ẖé֥leq wĕ⁠naẖàlá֖h ʼiţĕ̇⁠keֽm׃"],[12,13,"הִשָּׁ֣מֶר לְ⁠ךָ֔ פֶּֽן־תַּעֲלֶ֖ה עֹלֹתֶ֑י⁠ךָ בְּ⁠כָל־מָק֖וֹם אֲשֶׁ֥ר תִּרְאֶֽה׃","hişá֣̇̌mer lĕ⁠ká֔ pėֽn-ţȧʻàle֖h ʻòlòţe֑y⁠ká bĕ̇⁠kál-máq֖wòm ʼàşě֥r ţi̇rĕʼeֽh׃"],[12,14,"כִּ֣י אִם־בַּ⁠מָּק֞וֹם אֲשֶׁר־יִבְחַ֤ר יְהוָה֙ בְּ⁠אַחַ֣ד שְׁבָטֶ֔י⁠ךָ שָׁ֖ם תַּעֲלֶ֣ה עֹלֹתֶ֑י⁠ךָ וְ⁠שָׁ֣ם תַּעֲשֶׂ֔ה כֹּ֛ל אֲשֶׁ֥ר אָנֹכִ֖י מְצַוֶּֽ⁠ךָּ׃","ki֣̇y ʼim-bȧ⁠má̇q֞wòm ʼàşěr-yibĕẖa֤r yĕhwáh֙ bĕ̇⁠ʼaẖa֣d şĕ̌báte֔y⁠ká şá֖̌m ţȧʻàle֣h ʻòlòţe֑y⁠ká wĕ⁠şá֣̌m ţȧʻàşê֔h kò֛̇l ʼàşě֥r ʼánòki֖y mĕẕawėֽ⁠ká̇׃"],[12,15,"רַק֩ בְּ⁠כָל־אַוַּ֨ת נַפְשְׁ⁠ךָ֜ תִּזְבַּ֣ח ׀ וְ⁠אָכַלְתָּ֣ בָשָׂ֗ר כְּ⁠בִרְכַּ֨ת יְהוָ֧ה אֱלֹהֶ֛י⁠ךָ אֲשֶׁ֥ר נָֽתַן־לְ⁠ךָ֖ בְּ⁠כָל־שְׁעָרֶ֑י⁠ךָ הַ⁠טָּמֵ֤א וְ⁠הַ⁠טָּהוֹר֙ יֹאכְלֶ֔⁠נּוּ כַּ⁠צְּבִ֖י וְ⁠כָ⁠אַיָּֽל׃","raq֩ bĕ̇⁠kál-ʼawȧ֨ţ napĕşĕ̌⁠ká֜ ţi̇zĕbȧ֣ẖ ׀ wĕ⁠ʼákalĕţá֣̇ báşá̂֗r kĕ̇⁠birĕkȧ֨ţ yĕhwá֧h ʼèlòhe֛y⁠ká ʼàşě֥r náֽţan-lĕ⁠ká֖ bĕ̇⁠kál-şĕ̌ʻáre֑y⁠ká ha⁠tá̇mé֤ʼ wĕ⁠ha⁠tá̇hwòr֙ yòʼkĕle֔⁠ṅẇ kȧ⁠ẕĕ̇bi֖y wĕ⁠ká⁠ʼayáֽ̇l׃"],[12,16,"רַ֥ק הַ⁠דָּ֖ם לֹ֣א תֹאכֵ֑לוּ עַל־הָ⁠אָ֥רֶץ תִּשְׁפְּכֶ֖⁠נּוּ כַּ⁠מָּֽיִם׃","ra֥q ha⁠dá֖̇m lò֣ʼ ţòʼké֑lẇ ʻal-há⁠ʼá֥reẕ ţi̇şĕ̌pĕ̇ke֖⁠ṅẇ kȧ⁠máֽ̇yim׃"],[12,17,"לֹֽא־תוּכַ֞ל לֶ⁠אֱכֹ֣ל בִּ⁠שְׁעָרֶ֗י⁠ךָ מַעְשַׂ֤ר דְּגָֽנְ⁠ךָ֙ וְ⁠תִֽירֹשְׁ⁠ךָ֣ וְ⁠יִצְהָרֶ֔⁠ךָ וּ⁠בְכֹרֹ֥ת בְּקָרְ⁠ךָ֖ וְ⁠צֹאנֶ֑⁠ךָ וְ⁠כָל־נְדָרֶ֨י⁠ךָ֙ אֲשֶׁ֣ר תִּדֹּ֔ר וְ⁠נִדְבֹתֶ֖י⁠ךָ וּ⁠תְרוּמַ֥ת יָדֶֽ⁠ךָ׃","lòֽʼ-ţẇka֞l le⁠ʼèkò֣l bi̇⁠şĕ̌ʻáre֗y⁠ká maʻĕşâ֤r dĕ̇gáֽnĕ⁠ká֙ wĕ⁠ţiֽyròşĕ̌⁠ká֣ wĕ⁠yiẕĕháre֔⁠ká ẇ⁠bĕkòrò֥ţ bĕ̇qárĕ⁠ká֖ wĕ⁠ẕòʼne֑⁠ká wĕ⁠kál-nĕdáre֨y⁠ká֙ ʼàşě֣r ţi̇dò̇֔r wĕ⁠nidĕbòţe֖y⁠ká ẇ⁠ţĕrẇma֥ţ yádeֽ⁠ká׃"],[12,18,"כִּ֡י אִם־לִ⁠פְנֵי֩ יְהוָ֨ה אֱלֹהֶ֜י⁠ךָ תֹּאכְלֶ֗⁠נּוּ בַּ⁠מָּקוֹם֙ אֲשֶׁ֨ר יִבְחַ֜ר יְהוָ֣ה אֱלֹהֶי⁠ךָ֮ בּ⁠וֹ֒ אַתָּ֨ה וּ⁠בִנְ⁠ךָ֤ וּ⁠בִתֶּ֨⁠ךָ֙ וְ⁠עַבְדְּ⁠ךָ֣ וַ⁠אֲמָתֶ֔⁠ךָ וְ⁠הַ⁠לֵּוִ֖י אֲשֶׁ֣ר בִּ⁠שְׁעָרֶ֑י⁠ךָ וְ⁠שָׂמַחְתָּ֗ לִ⁠פְנֵי֙ יְהוָ֣ה אֱלֹהֶ֔י⁠ךָ בְּ⁠כֹ֖ל מִשְׁלַ֥ח יָדֶֽ⁠ךָ׃","ki̇֡y ʼim-li⁠pĕnéy֩ yĕhwá֨h ʼèlòhe֜y⁠ká ţò̇ʼkĕle֗⁠ṅẇ bȧ⁠má̇qwòm֙ ʼàşě֨r yibĕẖa֜r yĕhwá֣h ʼèlòhey⁠ká֮ ḃ⁠wò֒ ʼaţá̇֨h ẇ⁠binĕ⁠ká֤ ẇ⁠biţė֨⁠ká֙ wĕ⁠ʻabĕdĕ̇⁠ká֣ wa⁠ʼàmáţe֔⁠ká wĕ⁠ha⁠lé̇wi֖y ʼàşě֣r bi̇⁠şĕ̌ʻáre֑y⁠ká wĕ⁠şá̂maẖĕţá̇֗ li⁠pĕnéy֙ yĕhwá֣h ʼèlòhe֔y⁠ká bĕ̇⁠kò֖l mişĕ̌la֥ẖ yádeֽ⁠ká׃"],[12,19,"הִשָּׁ֣מֶר לְ⁠ךָ֔ פֶּֽן־תַּעֲזֹ֖ב אֶת־הַ⁠לֵּוִ֑י כָּל־יָמֶ֖י⁠ךָ עַל־אַדְמָתֶֽ⁠ךָ׃ס","hişá֣̇̌mer lĕ⁠ká֔ pėֽn-ţȧʻàzò֖b ʼeţ-ha⁠lé̇wi֑y ká̇l-yáme֖y⁠ká ʻal-ʼadĕmáţeֽ⁠ká׃s"],[12,20,"כִּֽי־יַרְחִיב֩ יְהוָ֨ה אֱלֹהֶ֥י⁠ךָ אֶֽת־גְּבֽוּלְ⁠ךָ֮ כַּ⁠אֲשֶׁ֣ר דִּבֶּר־לָ⁠ךְ֒ וְ⁠אָמַרְתָּ֙ אֹכְלָ֣ה בָשָׂ֔ר כִּֽי־תְאַוֶּ֥ה נַפְשְׁ⁠ךָ֖ לֶ⁠אֱכֹ֣ל בָּשָׂ֑ר בְּ⁠כָל־אַוַּ֥ת נַפְשְׁ⁠ךָ֖ תֹּאכַ֥ל בָּשָֽׂר׃","kiֽ̇y-yarĕẖiyb֩ yĕhwá֨h ʼèlòhe֥y⁠ká ʼeֽţ-gĕ̇bֽẇlĕ⁠ká֮ kȧ⁠ʼàşě֣r di̇bėr-lá⁠kĕ֒ wĕ⁠ʼámarĕţá̇֙ ʼòkĕlá֣h báşá̂֔r kiֽ̇y-ţĕʼawė֥h napĕşĕ̌⁠ká֖ le⁠ʼèkò֣l bá̇şá֑̂r bĕ̇⁠kál-ʼawȧ֥ţ napĕşĕ̌⁠ká֖ ţò̇ʼka֥l bá̇şáֽ̂r׃"],[12,21,"כִּֽי־יִרְחַ֨ק מִמְּ⁠ךָ֜ הַ⁠מָּק֗וֹם אֲשֶׁ֨ר יִבְחַ֜ר יְהוָ֣ה אֱלֹהֶי⁠ךָ֮ לָ⁠שׂ֣וּם שְׁמ֣⁠וֹ שָׁם֒ וְ⁠זָבַחְתָּ֞ מִ⁠בְּקָרְ⁠ךָ֣ וּ⁠מִ⁠צֹּֽאנְ⁠ךָ֗ אֲשֶׁ֨ר נָתַ֤ן יְהוָה֙ לְ⁠ךָ֔ כַּ⁠אֲשֶׁ֖ר צִוִּיתִ֑⁠ךָ וְ⁠אָֽכַלְתָּ֙ בִּ⁠שְׁעָרֶ֔י⁠ךָ בְּ⁠כֹ֖ל אַוַּ֥ת נַפְשֶֽׁ⁠ךָ׃","kiֽ̇y-yirĕẖa֨q mimĕ̇⁠ká֜ ha⁠má̇q֗wòm ʼàşě֨r yibĕẖa֜r yĕhwá֣h ʼèlòhey⁠ká֮ lá⁠ş֣̂ẇm şĕ̌m֣⁠wò şá̌m֒ wĕ⁠zábaẖĕţá̇֞ mi⁠bĕ̇qárĕ⁠ká֣ ẇ⁠mi⁠ẕòֽ̇ʼnĕ⁠ká֗ ʼàşě֨r náţa֤n yĕhwáh֙ lĕ⁠ká֔ kȧ⁠ʼàşě֖r ẕiwi̇yţi֑⁠ká wĕ⁠ʼáֽkalĕţá̇֙ bi̇⁠şĕ̌ʻáre֔y⁠ká bĕ̇⁠kò֖l ʼawȧ֥ţ napĕşěֽ⁠ká׃"],[12,22,"אַ֗ךְ כַּ⁠אֲשֶׁ֨ר יֵאָכֵ֤ל אֶֽת־הַ⁠צְּבִי֙ וְ⁠אֶת־הָ֣⁠אַיָּ֔ל כֵּ֖ן תֹּאכְלֶ֑⁠נּוּ הַ⁠טָּמֵא֙ וְ⁠הַ⁠טָּה֔וֹר יַחְדָּ֖ו יֹאכְלֶֽ⁠נּוּ׃","ʼa֗kĕ kȧ⁠ʼàşě֨r yéʼáké֤l ʼeֽţ-ha⁠ẕĕ̇biy֙ wĕ⁠ʼeţ-há֣⁠ʼayá̇֔l ké֖̇n ţò̇ʼkĕle֑⁠ṅẇ ha⁠tá̇méʼ֙ wĕ⁠ha⁠tá̇h֔wòr yaẖĕdá֖̇w yòʼkĕleֽ⁠ṅẇ׃"],[12,23,"רַ֣ק חֲזַ֗ק לְ⁠בִלְתִּי֙ אֲכֹ֣ל הַ⁠דָּ֔ם כִּ֥י הַ⁠דָּ֖ם ה֣וּא הַ⁠נָּ֑פֶשׁ וְ⁠לֹא־תֹאכַ֥ל הַ⁠נֶּ֖פֶשׁ עִם־הַ⁠בָּשָֽׂר׃","ra֣q ẖàza֗q lĕ⁠bilĕţi̇y֙ ʼàkò֣l ha⁠dá̇֔m ki֥̇y ha⁠dá֖̇m h֣ẇʼ ha⁠ná֑̇peş̌ wĕ⁠lòʼ-ţòʼka֥l ha⁠nė֖peş̌ ʻim-ha⁠bá̇şáֽ̂r׃"],[12,24,"לֹ֖א תֹּאכְלֶ֑⁠נּוּ עַל־הָ⁠אָ֥רֶץ תִּשְׁפְּכֶ֖⁠נּוּ כַּ⁠מָּֽיִם׃","lò֖ʼ ţò̇ʼkĕle֑⁠ṅẇ ʻal-há⁠ʼá֥reẕ ţi̇şĕ̌pĕ̇ke֖⁠ṅẇ kȧ⁠máֽ̇yim׃"],[12,25,"לֹ֖א תֹּאכְלֶ֑⁠נּוּ לְמַ֨עַן יִיטַ֤ב לְ⁠ךָ֙ וּ⁠לְ⁠בָנֶ֣י⁠ךָ אַחֲרֶ֔י⁠ךָ כִּֽי־תַעֲשֶׂ֥ה הַ⁠יָּשָׁ֖ר בְּ⁠עֵינֵ֥י יְהוָֽה׃","lò֖ʼ ţò̇ʼkĕle֑⁠ṅẇ lĕma֨ʻan yiyta֤b lĕ⁠ká֙ ẇ⁠lĕ⁠báne֣y⁠ká ʼaẖàre֔y⁠ká kiֽ̇y-ţaʻàşê֥h ha⁠yá̇şá֖̌r bĕ̇⁠ʻéyné֥y yĕhwáֽh׃"],[12,26,"רַ֧ק קָֽדָשֶׁ֛י⁠ךָ אֲשֶׁר־יִהְי֥וּ לְ⁠ךָ֖ וּ⁠נְדָרֶ֑י⁠ךָ תִּשָּׂ֣א וּ⁠בָ֔אתָ אֶל־הַ⁠מָּק֖וֹם אֲשֶׁר־יִבְחַ֥ר יְהוָֽה׃","ra֧q qáֽdáşě֛y⁠ká ʼàşěr-yihĕy֥ẇ lĕ⁠ká֖ ẇ⁠nĕdáre֑y⁠ká ţi̇şá֣̇̂ʼ ẇ⁠bá֔ʼţá ʼel-ha⁠má̇q֖wòm ʼàşěr-yibĕẖa֥r yĕhwáֽh׃"],[12,27,"וְ⁠עָשִׂ֤יתָ עֹלֹתֶ֨י⁠ךָ֙ הַ⁠בָּשָׂ֣ר וְ⁠הַ⁠דָּ֔ם עַל־מִזְבַּ֖ח יְהוָ֣ה אֱלֹהֶ֑י⁠ךָ וְ⁠דַם־זְבָחֶ֗י⁠ךָ יִשָּׁפֵךְ֙ עַל־מִזְבַּח֙ יְהוָ֣ה אֱלֹהֶ֔י⁠ךָ וְ⁠הַ⁠בָּשָׂ֖ר תֹּאכֵֽל׃","wĕ⁠ʻáşî֤yţá ʻòlòţe֨y⁠ká֙ ha⁠bá̇şá֣̂r wĕ⁠ha⁠dá̇֔m ʻal-mizĕbȧ֖ẖ yĕhwá֣h ʼèlòhe֑y⁠ká wĕ⁠dam-zĕbáẖe֗y⁠ká yişá̇̌pékĕ֙ ʻal-mizĕbȧẖ֙ yĕhwá֣h ʼèlòhe֔y⁠ká wĕ⁠ha⁠bá̇şá֖̂r ţò̇ʼkéֽl׃"],[12,28,"שְׁמֹ֣ר וְ⁠שָׁמַעְתָּ֗ אֵ֚ת כָּל־הַ⁠דְּבָרִ֣ים הָ⁠אֵ֔לֶּה אֲשֶׁ֥ר אָנֹכִ֖י מְצַוֶּ֑⁠ךָּ לְמַעַן֩ יִיטַ֨ב לְ⁠ךָ֜ וּ⁠לְ⁠בָנֶ֤י⁠ךָ אַחֲרֶ֨י⁠ךָ֙ עַד־עוֹלָ֔ם כִּ֤י תַעֲשֶׂה֙ הַ⁠טּ֣וֹב וְ⁠הַ⁠יָּשָׁ֔ר בְּ⁠עֵינֵ֖י יְהוָ֥ה אֱלֹהֶֽי⁠ךָ׃ס","şĕ̌mò֣r wĕ⁠şá̌maʻĕţá̇֗ ʼé֚ţ ká̇l-ha⁠dĕ̇bári֣ym há⁠ʼé֔lėh ʼàşě֥r ʼánòki֖y mĕẕawė֑⁠ká̇ lĕmaʻan֩ yiyta֨b lĕ⁠ká֜ ẇ⁠lĕ⁠báne֤y⁠ká ʼaẖàre֨y⁠ká֙ ʻad-ʻwòlá֔m ki֤̇y ţaʻàşêh֙ ha⁠ṫ֣wòb wĕ⁠ha⁠yá̇şá̌֔r bĕ̇⁠ʻéyné֖y yĕhwá֥h ʼèlòheֽy⁠ká׃s"],[12,29,"כִּֽי־יַכְרִית֩ יְהוָ֨ה אֱלֹהֶ֜י⁠ךָ אֶת־הַ⁠גּוֹיִ֗ם אֲשֶׁ֨ר אַתָּ֥ה בָא־שָׁ֛מָּ⁠ה לָ⁠רֶ֥שֶׁת אוֹתָ֖⁠ם מִ⁠פָּנֶ֑י⁠ךָ וְ⁠יָרַשְׁתָּ֣ אֹתָ֔⁠ם וְ⁠יָשַׁבְתָּ֖ בְּ⁠אַרְצָֽ⁠ם׃","kiֽ̇y-yakĕriyţ֩ yĕhwá֨h ʼèlòhe֜y⁠ká ʼeţ-ha⁠ġwòyi֗m ʼàşě֨r ʼaţá֥̇h báʼ-şá֛̌má̇⁠h lá⁠re֥şěţ ʼwòţá֖⁠m mi⁠pá̇ne֑y⁠ká wĕ⁠yáraşĕ̌ţá֣̇ ʼòţá֔⁠m wĕ⁠yáşǎbĕţá֖̇ bĕ̇⁠ʼarĕẕáֽ⁠m׃"],[12,30,"הִשָּׁ֣מֶר לְ⁠ךָ֗ פֶּן־תִּנָּקֵשׁ֙ אַחֲרֵי⁠הֶ֔ם אַחֲרֵ֖י הִשָּׁמְדָ֣⁠ם מִ⁠פָּנֶ֑י⁠ךָ וּ⁠פֶן־תִּדְרֹ֨שׁ לֵֽ⁠אלֹהֵי⁠הֶ֜ם לֵ⁠אמֹ֨ר אֵיכָ֨ה יַעַבְד֜וּ הַ⁠גּוֹיִ֤ם הָ⁠אֵ֨לֶּה֙ אֶת־אֱלֹ֣הֵי⁠הֶ֔ם וְ⁠אֶעֱשֶׂה־כֵּ֖ן גַּם־אָֽנִי׃","hişá֣̇̌mer lĕ⁠ká֗ pėn-ţi̇ná̇qéş̌֙ ʼaẖàréy⁠he֔m ʼaẖàré֖y hişá̇̌mĕdá֣⁠m mi⁠pá̇ne֑y⁠ká ẇ⁠pen-ţi̇dĕrò֨ş̌ léֽ⁠ʼlòhéy⁠he֜m lé⁠ʼmò֨r ʼéyká֨h yaʻabĕd֜ẇ ha⁠ġwòyi֤m há⁠ʼé֨lėh֙ ʼeţ-ʼèlò֣héy⁠he֔m wĕ⁠ʼeʻèşêh-ké֖̇n gȧm-ʼáֽniy׃"],[12,31,"לֹא־תַעֲשֶׂ֣ה כֵ֔ן לַ⁠יהוָ֖ה אֱלֹהֶ֑י⁠ךָ כִּי֩ כָּל־תּוֹעֲבַ֨ת יְהוָ֜ה אֲשֶׁ֣ר שָׂנֵ֗א עָשׂוּ֙ לֵ⁠אלֹ֣הֵי⁠הֶ֔ם כִּ֣י גַ֤ם אֶת־בְּנֵי⁠הֶם֙ וְ⁠אֶת־בְּנֹ֣תֵי⁠הֶ֔ם יִשְׂרְפ֥וּ בָ⁠אֵ֖שׁ לֵֽ⁠אלֹהֵי⁠הֶֽם׃","lòʼ-ţaʻàşê֣h ké֔n la⁠yhwá֖h ʼèlòhe֑y⁠ká ki̇y֩ ká̇l-ţ̇wòʻàba֨ţ yĕhwá֜h ʼàşě֣r şá̂né֗ʼ ʻáş̂ẇ֙ lé⁠ʼlò֣héy⁠he֔m ki֣̇y ga֤m ʼeţ-bĕ̇néy⁠hem֙ wĕ⁠ʼeţ-bĕ̇nò֣ţéy⁠he֔m yişĕ̂rĕp֥ẇ bá⁠ʼé֖ş̌ léֽ⁠ʼlòhéy⁠heֽm׃"],[12,32,"אֵ֣ת כָּל־הַ⁠דָּבָ֗ר אֲשֶׁ֤ר אָנֹכִי֙ מְצַוֶּ֣ה אֶתְ⁠כֶ֔ם אֹת֥⁠וֹ תִשְׁמְר֖וּ לַ⁠עֲשׂ֑וֹת לֹא־תֹסֵ֣ף עָלָ֔י⁠ו וְ⁠לֹ֥א תִגְרַ֖ע מִמֶּֽ⁠נּוּ׃פ","ʼé֣ţ ká̇l-ha⁠dá̇bá֗r ʼàşě֤r ʼánòkiy֙ mĕẕawė֣h ʼeţĕ⁠ke֔m ʼòţ֥⁠wò ţişĕ̌mĕr֖ẇ la⁠ʻàş֑̂wòţ lòʼ-ţòsé֣p ʻálá֔y⁠w wĕ⁠lò֥ʼ ţigĕra֖ʻ mimėֽ⁠ṅẇ׃p"],[13,1,"כִּֽי־יָק֤וּם בְּ⁠קִרְבְּ⁠ךָ֙ נָבִ֔יא א֖וֹ חֹלֵ֣ם חֲל֑וֹם וְ⁠נָתַ֥ן אֵלֶ֛י⁠ךָ א֖וֹת א֥וֹ מוֹפֵֽת׃","kiֽ̇y-yáq֤ẇm bĕ̇⁠qirĕbĕ̇⁠ká֙ nábi֔yʼ ʼ֖wò ẖòlé֣m ẖàl֑wòm wĕ⁠náţa֥n ʼéle֛y⁠ká ʼ֖wòţ ʼ֥wò mwòpéֽţ׃"],[13,2,"וּ⁠בָ֤א הָ⁠אוֹת֙ וְ⁠הַ⁠מּוֹפֵ֔ת אֲשֶׁר־דִּבֶּ֥ר אֵלֶ֖י⁠ךָ לֵ⁠אמֹ֑ר נֵֽלְכָ֞ה אַחֲרֵ֨י אֱלֹהִ֧ים אֲחֵרִ֛ים אֲשֶׁ֥ר לֹֽא־יְדַעְתָּ֖⁠ם וְ⁠נָֽעָבְדֵֽ⁠ם׃","ẇ⁠bá֤ʼ há⁠ʼwòţ֙ wĕ⁠ha⁠ṁwòpé֔ţ ʼàşěr-di̇bė֥r ʼéle֖y⁠ká lé⁠ʼmò֑r néֽlĕká֞h ʼaẖàré֨y ʼèlòhi֧ym ʼàẖéri֛ym ʼàşě֥r lòֽʼ-yĕdaʻĕţá֖̇⁠m wĕ⁠náֽʻábĕdéֽ⁠m׃"],[13,3,"לֹ֣א תִשְׁמַ֗ע אֶל־דִּבְרֵי֙ הַ⁠נָּבִ֣יא הַ⁠ה֔וּא א֛וֹ אֶל־חוֹלֵ֥ם הַ⁠חֲל֖וֹם הַ⁠ה֑וּא כִּ֣י מְנַסֶּ֞ה יְהוָ֤ה אֱלֹֽהֵי⁠כֶם֙ אֶתְ⁠כֶ֔ם לָ⁠דַ֗עַת הֲ⁠יִשְׁ⁠כֶ֤ם אֹֽהֲבִים֙ אֶת־יְהוָ֣ה אֱלֹהֵי⁠כֶ֔ם בְּ⁠כָל־לְבַבְ⁠כֶ֖ם וּ⁠בְ⁠כָל־נַפְשְׁ⁠כֶֽם׃","lò֣ʼ ţişĕ̌ma֗ʻ ʼel-di̇bĕréy֙ ha⁠ná̇bi֣yʼ ha⁠h֔ẇʼ ʼ֛wò ʼel-ẖwòlé֥m ha⁠ẖàl֖wòm ha⁠h֑ẇʼ ki֣̇y mĕnasė֞h yĕhwá֤h ʼèlòֽhéy⁠kem֙ ʼeţĕ⁠ke֔m lá⁠da֗ʻaţ hà⁠yişĕ̌⁠ke֤m ʼòֽhàbiym֙ ʼeţ-yĕhwá֣h ʼèlòhéy⁠ke֔m bĕ̇⁠kál-lĕbabĕ⁠ke֖m ẇ⁠bĕ⁠kál-napĕşĕ̌⁠keֽm׃"],[13,4,"אַחֲרֵ֨י יְהוָ֧ה אֱלֹהֵי⁠כֶ֛ם תֵּלֵ֖כוּ וְ⁠אֹת֣⁠וֹ תִירָ֑אוּ וְ⁠אֶת־מִצְוֺתָ֤י⁠ו תִּשְׁמֹ֨רוּ֙ וּ⁠בְ⁠קֹל֣⁠וֹ תִשְׁמָ֔עוּ וְ⁠אֹת֥⁠וֹ תַעֲבֹ֖דוּ וּ⁠ב֥⁠וֹ תִדְבָּקֽוּ⁠ן׃","ʼaẖàré֨y yĕhwá֧h ʼèlòhéy⁠ke֛m ţé̇lé֖kẇ wĕ⁠ʼòţ֣⁠wò ţiyrá֑ʼẇ wĕ⁠ʼeţ-miẕĕwֺţá֤y⁠w ţi̇şĕ̌mò֨rẇ֙ ẇ⁠bĕ⁠qòl֣⁠wò ţişĕ̌má֔ʻẇ wĕ⁠ʼòţ֥⁠wò ţaʻàbò֖dẇ ẇ⁠b֥⁠wò ţidĕbá̇qֽẇ⁠n׃"],[13,5,"וְ⁠הַ⁠נָּבִ֣יא הַ⁠ה֡וּא א֣וֹ חֹלֵם֩ הַ⁠חֲל֨וֹם הַ⁠ה֜וּא יוּמָ֗ת כִּ֣י דִבֶּר־סָ֠רָה עַל־יְהוָ֨ה אֱלֹֽהֵי⁠כֶ֜ם הַ⁠מּוֹצִ֥יא אֶתְ⁠כֶ֣ם ׀ מֵ⁠אֶ֣רֶץ מִצְרַ֗יִם וְ⁠הַ⁠פֹּֽדְ⁠ךָ֙ מִ⁠בֵּ֣ית עֲבָדִ֔ים לְ⁠הַדִּֽיחֲ⁠ךָ֙ מִן־הַ⁠דֶּ֔רֶךְ אֲשֶׁ֧ר צִוְּ⁠ךָ֛ יְהוָ֥ה אֱלֹהֶ֖י⁠ךָ לָ⁠לֶ֣כֶת בָּ֑⁠הּ וּ⁠בִֽעַרְתָּ֥ הָ⁠רָ֖ע מִ⁠קִּרְבֶּֽ⁠ךָ׃","wĕ⁠ha⁠ná̇bi֣yʼ ha⁠h֡ẇʼ ʼ֣wò ẖòlém֩ ha⁠ẖàl֨wòm ha⁠h֜ẇʼ yẇmá֗ţ ki֣̇y dibėr-sá֠ráh ʻal-yĕhwá֨h ʼèlòֽhéy⁠ke֜m ha⁠ṁwòẕi֥yʼ ʼeţĕ⁠ke֣m ׀ mé⁠ʼe֣reẕ miẕĕra֗yim wĕ⁠ha⁠pòֽ̇dĕ⁠ká֙ mi⁠bé֣̇yţ ʻàbádi֔ym lĕ⁠hadiֽ̇yẖà⁠ká֙ min-ha⁠dė֔rekĕ ʼàşě֧r ẕiwĕ̇⁠ká֛ yĕhwá֥h ʼèlòhe֖y⁠ká lá⁠le֣keţ bá֑̇⁠ḣ ẇ⁠biֽʻarĕţá֥̇ há⁠rá֖ʻ mi⁠qi̇rĕbėֽ⁠ká׃"],[13,6,"כִּ֣י יְסִֽיתְ⁠ךָ֡ אָחִ֣י⁠ךָ בֶן־אִ֠מֶּ⁠ךָ אֽוֹ־בִנְ⁠ךָ֨ אֽוֹ־בִתְּ⁠ךָ֜ א֣וֹ ׀ אֵ֣שֶׁת חֵיקֶ֗⁠ךָ א֧וֹ רֵֽעֲ⁠ךָ֛ אֲשֶׁ֥ר כְּ⁠נַפְשְׁ⁠ךָ֖ בַּ⁠סֵּ֣תֶר לֵ⁠אמֹ֑ר נֵֽלְכָ֗ה וְ⁠נַֽעַבְדָה֙ אֱלֹהִ֣ים אֲחֵרִ֔ים אֲשֶׁר֙ לֹ֣א יָדַ֔עְתָּ אַתָּ֖ה וַ⁠אֲבֹתֶֽי⁠ךָ׃","ki֣̇y yĕsiֽyţĕ⁠ká֡ ʼáẖi֣y⁠ká ben-ʼi֠mė⁠ká ʼֽwò-binĕ⁠ká֨ ʼֽwò-biţĕ̇⁠ká֜ ʼ֣wò ׀ ʼé֣şěţ ẖéyqe֗⁠ká ʼ֧wò réֽʻà⁠ká֛ ʼàşě֥r kĕ̇⁠napĕşĕ̌⁠ká֖ bȧ⁠sé֣̇ţer lé⁠ʼmò֑r néֽlĕká֗h wĕ⁠naֽʻabĕdáh֙ ʼèlòhi֣ym ʼàẖéri֔ym ʼàşěr֙ lò֣ʼ yáda֔ʻĕţá̇ ʼaţá֖̇h wa⁠ʼàbòţeֽy⁠ká׃"],[13,7,"מֵ⁠אֱלֹהֵ֣י הָֽ⁠עַמִּ֗ים אֲשֶׁר֙ סְבִיבֹ֣תֵי⁠כֶ֔ם הַ⁠קְּרֹבִ֣ים אֵלֶ֔י⁠ךָ א֖וֹ הָ⁠רְחֹקִ֣ים מִמֶּ֑⁠ךָּ מִ⁠קְצֵ֥ה הָ⁠אָ֖רֶץ וְ⁠עַד־קְצֵ֥ה הָ⁠אָֽרֶץ׃","mé⁠ʼèlòhé֣y háֽ⁠ʻami̇֗ym ʼàşěr֙ sĕbiybò֣ţéy⁠ke֔m ha⁠qĕ̇ròbi֣ym ʼéle֔y⁠ká ʼ֖wò há⁠rĕẖòqi֣ym mimė֑⁠ká̇ mi⁠qĕẕé֥h há⁠ʼá֖reẕ wĕ⁠ʻad-qĕẕé֥h há⁠ʼáֽreẕ׃"],[13,8,"לֹא־תֹאבֶ֣ה ל֔⁠וֹ וְ⁠לֹ֥א תִשְׁמַ֖ע אֵלָ֑י⁠ו וְ⁠לֹא־תָח֤וֹס עֵֽינְ⁠ךָ֙ עָלָ֔י⁠ו וְ⁠לֹֽא־תַחְמֹ֥ל וְ⁠לֹֽא־תְכַסֶּ֖ה עָלָֽי⁠ו׃","lòʼ-ţòʼbe֣h l֔⁠wò wĕ⁠lò֥ʼ ţişĕ̌ma֖ʻ ʼélá֑y⁠w wĕ⁠lòʼ-ţáẖ֤wòs ʻéֽynĕ⁠ká֙ ʻálá֔y⁠w wĕ⁠lòֽʼ-ţaẖĕmò֥l wĕ⁠lòֽʼ-ţĕkasė֖h ʻáláֽy⁠w׃"],[13,9,"כִּ֤י הָרֹג֙ תַּֽהַרְגֶ֔⁠נּוּ יָֽדְ⁠ךָ֛ תִּֽהְיֶה־בּ֥⁠וֹ בָ⁠רִֽאשׁוֹנָ֖ה לַ⁠הֲמִית֑⁠וֹ וְ⁠יַ֥ד כָּל־הָ⁠עָ֖ם בָּ⁠אַחֲרֹנָֽה׃","ki֤̇y háròg֙ ţȧֽharĕge֔⁠ṅẇ yáֽdĕ⁠ká֛ ţiֽ̇hĕyeh-ḃ֥⁠wò bá⁠riֽʼş̌wòná֖h la⁠hàmiyţ֑⁠wò wĕ⁠ya֥d ká̇l-há⁠ʻá֖m bá̇⁠ʼaẖàrònáֽh׃"],[13,10,"וּ⁠סְקַלְתּ֥⁠וֹ בָ⁠אֲבָנִ֖ים וָ⁠מֵ֑ת כִּ֣י בִקֵּ֗שׁ לְ⁠הַדִּֽיחֲ⁠ךָ֙ מֵ⁠עַל֙ יְהוָ֣ה אֱלֹהֶ֔י⁠ךָ הַ⁠מּוֹצִיאֲ⁠ךָ֛ מֵ⁠אֶ֥רֶץ מִצְרַ֖יִם מִ⁠בֵּ֥ית עֲבָדִֽים׃","ẇ⁠sĕqalĕţ֥̇⁠wò bá⁠ʼàbáni֖ym wá⁠mé֑ţ ki֣̇y biqé̇֗ş̌ lĕ⁠hadiֽ̇yẖà⁠ká֙ mé⁠ʻal֙ yĕhwá֣h ʼèlòhe֔y⁠ká ha⁠ṁwòẕiyʼà⁠ká֛ mé⁠ʼe֥reẕ miẕĕra֖yim mi⁠bé֥̇yţ ʻàbádiֽym׃"],[13,11,"וְ⁠כָל־יִשְׂרָאֵ֔ל יִשְׁמְע֖וּ וְ⁠יִֽרָא֑וּ⁠ן וְ⁠לֹֽא־יוֹסִ֣פוּ לַ⁠עֲשׂ֗וֹת כַּ⁠דָּבָ֥ר הָ⁠רָ֛ע הַ⁠זֶּ֖ה בְּ⁠קִרְבֶּֽ⁠ךָ׃ס","wĕ⁠kál-yişĕ̂ráʼé֔l yişĕ̌mĕʻ֖ẇ wĕ⁠yiֽráʼ֑ẇ⁠n wĕ⁠lòֽʼ-ywòsi֣pẇ la⁠ʻàş̂֗wòţ kȧ⁠dá̇bá֥r há⁠rá֛ʻ ha⁠zė֖h bĕ̇⁠qirĕbėֽ⁠ká׃s"],[13,12,"כִּֽי־תִשְׁמַ֞ע בְּ⁠אַחַ֣ת עָרֶ֗י⁠ךָ אֲשֶׁר֩ יְהוָ֨ה אֱלֹהֶ֜י⁠ךָ נֹתֵ֥ן לְ⁠ךָ֛ לָ⁠שֶׁ֥בֶת שָׁ֖ם לֵ⁠אמֹֽר׃","kiֽ̇y-ţişĕ̌ma֞ʻ bĕ̇⁠ʼaẖa֣ţ ʻáre֗y⁠ká ʼàşěr֩ yĕhwá֨h ʼèlòhe֜y⁠ká nòţé֥n lĕ⁠ká֛ lá⁠şě֥beţ şá֖̌m lé⁠ʼmòֽr׃"],[13,13,"יָצְא֞וּ אֲנָשִׁ֤ים בְּנֵֽי־בְלִיַּ֨עַל֙ מִ⁠קִּרְבֶּ֔⁠ךָ וַ⁠יַּדִּ֛יחוּ אֶת־יֹשְׁבֵ֥י עִירָ֖⁠ם לֵ⁠אמֹ֑ר נֵלְכָ֗ה וְ⁠נַעַבְדָ֛ה אֱלֹהִ֥ים אֲחֵרִ֖ים אֲשֶׁ֥ר לֹא־יְדַעְתֶּֽם׃","yáẕĕʼ֞ẇ ʼànáşǐ֤ym bĕ̇néֽy-bĕliyȧ֨ʻal֙ mi⁠qi̇rĕbė֔⁠ká wa⁠yȧdi֛̇yẖẇ ʼeţ-yòşĕ̌bé֥y ʻiyrá֖⁠m lé⁠ʼmò֑r nélĕká֗h wĕ⁠naʻabĕdá֛h ʼèlòhi֥ym ʼàẖéri֖ym ʼàşě֥r lòʼ-yĕdaʻĕţėֽm׃"],[13,14,"וְ⁠דָרַשְׁתָּ֧ וְ⁠חָקַרְתָּ֧ וְ⁠שָׁאַלְתָּ֖ הֵיטֵ֑ב וְ⁠הִנֵּ֤ה אֱמֶת֙ נָכ֣וֹן הַ⁠דָּבָ֔ר נֶעֶשְׂתָ֛ה הַ⁠תּוֹעֵבָ֥ה הַ⁠זֹּ֖את בְּ⁠קִרְבֶּֽ⁠ךָ׃","wĕ⁠dáraşĕ̌ţá֧̇ wĕ⁠ẖáqarĕţá֧̇ wĕ⁠şá̌ʼalĕţá֖̇ héyté֑b wĕ⁠hiné֤̇h ʼèmeţ֙ nák֣wòn ha⁠dá̇bá֔r neʻeşĕ̂ţá֛h ha⁠ţ̇wòʻébá֥h ha⁠zò֖̇ʼţ bĕ̇⁠qirĕbėֽ⁠ká׃"],[13,15,"הַכֵּ֣ה תַכֶּ֗ה אֶת־יֹֽשְׁבֵ֛י הָ⁠עִ֥יר ה⁠הוא לְ⁠פִי־חָ֑רֶב הַחֲרֵ֨ם אֹתָ֧⁠הּ וְ⁠אֶת־כָּל־אֲשֶׁר־בָּ֛⁠הּ וְ⁠אֶת־בְּהֶמְתָּ֖⁠הּ לְ⁠פִי־חָֽרֶב׃","haké֣̇h ţakė֗h ʼeţ-yòֽşĕ̌bé֛y há⁠ʻi֥yr h⁠hwʼ lĕ⁠piy-ẖá֑reb haẖàré֨m ʼòţá֧⁠ḣ wĕ⁠ʼeţ-ká̇l-ʼàşěr-bá֛̇⁠ḣ wĕ⁠ʼeţ-bĕ̇hemĕţá֖̇⁠ḣ lĕ⁠piy-ẖáֽreb׃"],[13,16,"וְ⁠אֶת־כָּל־שְׁלָלָ֗⁠הּ תִּקְבֹּץ֮ אֶל־תּ֣וֹךְ רְחֹבָ⁠הּ֒ וְ⁠שָׂרַפְתָּ֨ בָ⁠אֵ֜שׁ אֶת־הָ⁠עִ֤יר וְ⁠אֶת־כָּל־שְׁלָלָ⁠הּ֙ כָּלִ֔יל לַ⁠יהוָ֖ה אֱלֹהֶ֑י⁠ךָ וְ⁠הָיְתָה֙ תֵּ֣ל עוֹלָ֔ם לֹ֥א תִבָּנֶ֖ה עֽוֹד׃","wĕ⁠ʼeţ-ká̇l-şĕ̌lálá֗⁠ḣ ţi̇qĕbò̇ẕ֮ ʼel-ţ֣̇wòkĕ rĕẖòbá⁠ḣ֒ wĕ⁠şá̂rapĕţá̇֨ bá⁠ʼé֜ş̌ ʼeţ-há⁠ʻi֤yr wĕ⁠ʼeţ-ká̇l-şĕ̌lálá⁠ḣ֙ ká̇li֔yl la⁠yhwá֖h ʼèlòhe֑y⁠ká wĕ⁠háyĕţáh֙ ţé֣̇l ʻwòlá֔m lò֥ʼ ţibá̇ne֖h ʻֽwòd׃"],[13,17,"וְ⁠לֹֽא־יִדְבַּ֧ק בְּ⁠יָדְ⁠ךָ֛ מְא֖וּמָה מִן־הַ⁠חֵ֑רֶם לְמַעַן֩ יָשׁ֨וּב יְהוָ֜ה מֵ⁠חֲר֣וֹן אַפּ֗⁠וֹ וְ⁠נָֽתַן־לְ⁠ךָ֤ רַחֲמִים֙ וְ⁠רִֽחַמְ⁠ךָ֣ וְ⁠הִרְבֶּ֔⁠ךָ כַּ⁠אֲשֶׁ֥ר נִשְׁבַּ֖ע לַ⁠אֲבֹתֶֽי⁠ךָ׃","wĕ⁠lòֽʼ-yidĕbȧ֧q bĕ̇⁠yádĕ⁠ká֛ mĕʼ֖ẇmáh min-ha⁠ẖé֑rem lĕmaʻan֩ yáş̌֨ẇb yĕhwá֜h mé⁠ẖàr֣wòn ʼaṗ֗⁠wò wĕ⁠náֽţan-lĕ⁠ká֤ raẖàmiym֙ wĕ⁠riֽẖamĕ⁠ká֣ wĕ⁠hirĕbė֔⁠ká kȧ⁠ʼàşě֥r nişĕ̌bȧ֖ʻ la⁠ʼàbòţeֽy⁠ká׃"],[13,18,"כִּ֣י תִשְׁמַ֗ע בְּ⁠קוֹל֙ יְהוָ֣ה אֱלֹהֶ֔י⁠ךָ לִ⁠שְׁמֹר֙ אֶת־כָּל־מִצְוֺתָ֔י⁠ו אֲשֶׁ֛ר אָנֹכִ֥י מְצַוְּ⁠ךָ֖ הַ⁠יּ֑וֹם לַ⁠עֲשׂוֹת֙ הַ⁠יָּשָׁ֔ר בְּ⁠עֵינֵ֖י יְהוָ֥ה אֱלֹהֶֽי⁠ךָ׃ס","ki֣̇y ţişĕ̌ma֗ʻ bĕ̇⁠qwòl֙ yĕhwá֣h ʼèlòhe֔y⁠ká li⁠şĕ̌mòr֙ ʼeţ-ká̇l-miẕĕwֺţá֔y⁠w ʼàşě֛r ʼánòki֥y mĕẕawĕ̇⁠ká֖ ha⁠ẏ֑wòm la⁠ʻàş̂wòţ֙ ha⁠yá̇şá̌֔r bĕ̇⁠ʻéyné֖y yĕhwá֥h ʼèlòheֽy⁠ká׃s"],[14,1,"בָּנִ֣ים אַתֶּ֔ם לַֽ⁠יהוָ֖ה אֱלֹהֵי⁠כֶ֑ם לֹ֣א תִתְגֹּֽדְד֗וּ וְ⁠לֹֽא־תָשִׂ֧ימוּ קָרְחָ֛ה בֵּ֥ין עֵינֵי⁠כֶ֖ם לָ⁠מֵֽת׃","bá̇ni֣ym ʼaţė֔m laֽ⁠yhwá֖h ʼèlòhéy⁠ke֑m lò֣ʼ ţiţĕgòֽ̇dĕd֗ẇ wĕ⁠lòֽʼ-ţáşî֧ymẇ qárĕẖá֛h bé֥̇yn ʻéynéy⁠ke֖m lá⁠méֽţ׃"],[14,2,"כִּ֣י עַ֤ם קָדוֹשׁ֙ אַתָּ֔ה לַ⁠יהוָ֖ה אֱלֹהֶ֑י⁠ךָ וּ⁠בְ⁠ךָ֞ בָּחַ֣ר יְהוָ֗ה לִֽ⁠הְי֥וֹת ל⁠וֹ֙ לְ⁠עַ֣ם סְגֻלָּ֔ה מִ⁠כֹּל֙ הָֽ⁠עַמִּ֔ים אֲשֶׁ֖ר עַל־פְּנֵ֥י הָ⁠אֲדָמָֽה׃ס","ki֣̇y ʻa֤m qádwòş̌֙ ʼaţá̇֔h la⁠yhwá֖h ʼèlòhe֑y⁠ká ẇ⁠bĕ⁠ká֞ bá̇ẖa֣r yĕhwá֗h liֽ⁠hĕy֥wòţ l⁠wò֙ lĕ⁠ʻa֣m sĕgulá̇֔h mi⁠kò̇l֙ háֽ⁠ʻami̇֔ym ʼàşě֖r ʻal-pĕ̇né֥y há⁠ʼàdámáֽh׃s"],[14,3,"לֹ֥א תֹאכַ֖ל כָּל־תּוֹעֵבָֽה׃","lò֥ʼ ţòʼka֖l ká̇l-ţ̇wòʻébáֽh׃"],[14,4,"זֹ֥את הַ⁠בְּהֵמָ֖ה אֲשֶׁ֣ר תֹּאכֵ֑לוּ שׁ֕וֹר שֵׂ֥ה כְשָׂבִ֖ים וְ⁠שֵׂ֥ה עִזִּֽים׃","zò֥ʼţ ha⁠bĕ̇hémá֖h ʼàşě֣r ţò̇ʼké֑lẇ ş̌֕wòr şé֥̂h kĕşá̂bi֖ym wĕ⁠şé֥̂h ʻiziֽ̇ym׃"],[14,5,"אַיָּ֥ל וּ⁠צְבִ֖י וְ⁠יַחְמ֑וּר וְ⁠אַקּ֥וֹ וְ⁠דִישֹׁ֖ן וּ⁠תְא֥וֹ וָ⁠זָֽמֶר׃","ʼayá֥̇l ẇ⁠ẕĕbi֖y wĕ⁠yaẖĕm֑ẇr wĕ⁠ʼaq֥̇wò wĕ⁠diyşò֖̌n ẇ⁠ţĕʼ֥wò wá⁠záֽmer׃"],[14,6,"וְ⁠כָל־בְּהֵמָ֞ה מַפְרֶ֣סֶת פַּרְסָ֗ה וְ⁠שֹׁסַ֤עַת שֶׁ֨סַע֙ שְׁתֵּ֣י פְרָס֔וֹת מַעֲלַ֥ת גֵּרָ֖ה בַּ⁠בְּהֵמָ֑ה אֹתָ֖⁠הּ תֹּאכֵֽלוּ׃","wĕ⁠kál-bĕ̇hémá֞h mapĕre֣seţ pȧrĕsá֗h wĕ⁠şò̌sa֤ʻaţ şě֨saʻ֙ şĕ̌ţé֣̇y pĕrás֔wòţ maʻàla֥ţ gé̇rá֖h bȧ⁠bĕ̇hémá֑h ʼòţá֖⁠ḣ ţò̇ʼkéֽlẇ׃"],[14,7,"אַ֣ךְ אֶת־זֶ֞ה לֹ֤א תֹֽאכְלוּ֙ מִ⁠מַּֽעֲלֵ֣י הַ⁠גֵּרָ֔ה וּ⁠מִ⁠מַּפְרִיסֵ֥י הַ⁠פַּרְסָ֖ה הַ⁠שְּׁסוּעָ֑ה אֶֽת־הַ֠⁠גָּמָל וְ⁠אֶת־הָ⁠אַרְנֶ֨בֶת וְ⁠אֶת־הַ⁠שָּׁפָ֜ן כִּֽי־מַעֲלֵ֧ה גֵרָ֣ה הֵ֗מָּה וּ⁠פַרְסָה֙ לֹ֣א הִפְרִ֔יסוּ טְמֵאִ֥ים הֵ֖ם לָ⁠כֶֽם׃","ʼa֣kĕ ʼeţ-ze֞h lò֤ʼ ţòֽʼkĕlẇ֙ mi⁠mȧֽʻàlé֣y ha⁠gé̇rá֔h ẇ⁠mi⁠mȧpĕriysé֥y ha⁠pȧrĕsá֖h ha⁠şĕ̇̌sẇʻá֑h ʼeֽţ-ha֠⁠gá̇mál wĕ⁠ʼeţ-há⁠ʼarĕne֨beţ wĕ⁠ʼeţ-ha⁠şá̇̌pá֜n kiֽ̇y-maʻàlé֧h gérá֣h hé֗má̇h ẇ⁠parĕsáh֙ lò֣ʼ hipĕri֔ysẇ tĕméʼi֥ym hé֖m lá⁠keֽm׃"],[14,8,"וְ⁠אֶת־הַ֠⁠חֲזִיר כִּֽי־מַפְרִ֨יס פַּרְסָ֥ה הוּא֙ וְ⁠לֹ֣א גֵרָ֔ה טָמֵ֥א ה֖וּא לָ⁠כֶ֑ם מִ⁠בְּשָׂרָ⁠ם֙ לֹ֣א תֹאכֵ֔לוּ וּ⁠בְ⁠נִבְלָתָ֖⁠ם לֹ֥א תִגָּֽעוּ׃ס","wĕ⁠ʼeţ-ha֠⁠ẖàziyr kiֽ̇y-mapĕri֨ys pȧrĕsá֥h hẇʼ֙ wĕ⁠lò֣ʼ gérá֔h támé֥ʼ h֖ẇʼ lá⁠ke֑m mi⁠bĕ̇şá̂rá⁠m֙ lò֣ʼ ţòʼké֔lẇ ẇ⁠bĕ⁠nibĕláţá֖⁠m lò֥ʼ ţigáֽ̇ʻẇ׃s"],[14,9,"אֶת־זֶה֙ תֹּֽאכְל֔וּ מִ⁠כֹּ֖ל אֲשֶׁ֣ר בַּ⁠מָּ֑יִם כֹּ֧ל אֲשֶׁר־ל֛⁠וֹ סְנַפִּ֥יר וְ⁠קַשְׂקֶ֖שֶׂת תֹּאכֵֽלוּ׃","ʼeţ-zeh֙ ţòֽ̇ʼkĕl֔ẇ mi⁠kò֖̇l ʼàşě֣r bȧ⁠má֑̇yim kò֧̇l ʼàşěr-l֛⁠wò sĕnapi֥̇yr wĕ⁠qaşĕ̂qe֖şêţ ţò̇ʼkéֽlẇ׃"],[14,10,"וְ⁠כֹ֨ל אֲשֶׁ֧ר אֵֽין־ל֛⁠וֹ סְנַפִּ֥יר וְ⁠קַשְׂקֶ֖שֶׂת לֹ֣א תֹאכֵ֑לוּ טָמֵ֥א ה֖וּא לָ⁠כֶֽם׃ס","wĕ⁠kò֨l ʼàşě֧r ʼéֽyn-l֛⁠wò sĕnapi֥̇yr wĕ⁠qaşĕ̂qe֖şêţ lò֣ʼ ţòʼké֑lẇ támé֥ʼ h֖ẇʼ lá⁠keֽm׃s"],[14,11,"כָּל־צִפּ֥וֹר טְהֹרָ֖ה תֹּאכֵֽלוּ׃","ká̇l-ẕiṗ֥wòr tĕhòrá֖h ţò̇ʼkéֽlẇ׃"],[14,12,"וְ⁠זֶ֕ה אֲשֶׁ֥ר לֹֽא־תֹאכְל֖וּ מֵ⁠הֶ֑ם הַ⁠נֶּ֥שֶׁר וְ⁠הַ⁠פֶּ֖רֶס וְ⁠הָֽ⁠עָזְנִיָּֽה׃","wĕ⁠ze֕h ʼàşě֥r lòֽʼ-ţòʼkĕl֖ẇ mé⁠he֑m ha⁠nė֥şěr wĕ⁠ha⁠pė֖res wĕ⁠háֽ⁠ʻázĕniyáֽ̇h׃"],[14,13,"וְ⁠הָ⁠רָאָה֙ וְ⁠אֶת־הָ֣⁠אַיָּ֔ה וְ⁠הַ⁠דַּיָּ֖ה לְ⁠מִינָֽ⁠הּ׃","wĕ⁠há⁠ráʼáh֙ wĕ⁠ʼeţ-há֣⁠ʼayá̇֔h wĕ⁠ha⁠dȧyá֖̇h lĕ⁠miynáֽ⁠ḣ׃"],[14,14,"וְ⁠אֵ֥ת כָּל־עֹרֵ֖ב לְ⁠מִינֽ⁠וֹ׃","wĕ⁠ʼé֥ţ ká̇l-ʻòré֖b lĕ⁠miynֽ⁠wò׃"],[14,15,"וְ⁠אֵת֙ בַּ֣ת הַֽ⁠יַּעֲנָ֔ה וְ⁠אֶת־הַ⁠תַּחְמָ֖ס וְ⁠אֶת־הַ⁠שָּׁ֑חַף וְ⁠אֶת־הַ⁠נֵּ֖ץ לְ⁠מִינֵֽ⁠הוּ׃","wĕ⁠ʼéţ֙ bȧ֣ţ haֽ⁠yȧʻàná֔h wĕ⁠ʼeţ-ha⁠ţȧẖĕmá֖s wĕ⁠ʼeţ-ha⁠şá֑̇̌ẖap wĕ⁠ʼeţ-ha⁠né֖̇ẕ lĕ⁠miynéֽ⁠hẇ׃"],[14,16,"אֶת־הַ⁠כּ֥וֹס וְ⁠אֶת־הַ⁠יַּנְשׁ֖וּף וְ⁠הַ⁠תִּנְשָֽׁמֶת׃","ʼeţ-ha⁠k֥̇wòs wĕ⁠ʼeţ-ha⁠yȧnĕş֖̌ẇp wĕ⁠ha⁠ţi̇nĕşáֽ̌meţ׃"],[14,17,"וְ⁠הַ⁠קָּאָ֥ת וְ⁠אֶֽת־הָ⁠רָחָ֖מָ⁠ה וְ⁠אֶת־הַ⁠שָּׁלָֽךְ׃","wĕ⁠ha⁠qá̇ʼá֥ţ wĕ⁠ʼeֽţ-há⁠ráẖá֖má⁠h wĕ⁠ʼeţ-ha⁠şá̇̌láֽkĕ׃"],[14,18,"וְ⁠הַ֣⁠חֲסִידָ֔ה וְ⁠הָ⁠אֲנָפָ֖ה לְ⁠מִינָ֑⁠הּ וְ⁠הַ⁠דּוּכִיפַ֖ת וְ⁠הָ⁠עֲטַלֵּֽף׃","wĕ⁠ha֣⁠ẖàsiydá֔h wĕ⁠há⁠ʼànápá֖h lĕ⁠miyná֑⁠ḣ wĕ⁠ha⁠ḋẇkiypa֖ţ wĕ⁠há⁠ʻàtaléֽ̇p׃"],[14,19,"וְ⁠כֹל֙ שֶׁ֣רֶץ הָ⁠ע֔וֹף טָמֵ֥א ה֖וּא לָ⁠כֶ֑ם לֹ֖א יֵאָכֵֽלוּ׃","wĕ⁠kòl֙ şě֣reẕ há⁠ʻ֔wòp támé֥ʼ h֖ẇʼ lá⁠ke֑m lò֖ʼ yéʼákéֽlẇ׃"],[14,20,"כָּל־ע֥וֹף טָה֖וֹר תֹּאכֵֽלוּ׃","ká̇l-ʻ֥wòp táh֖wòr ţò̇ʼkéֽlẇ׃"],[14,21,"לֹ֣א תֹאכְל֣וּ כָל־נְ֠בֵלָה לַ⁠גֵּ֨ר אֲשֶׁר־בִּ⁠שְׁעָרֶ֜י⁠ךָ תִּתְּנֶ֣נָּ⁠ה וַ⁠אֲכָלָ֗⁠הּ א֤וֹ מָכֹר֙ לְ⁠נָכְרִ֔י כִּ֣י עַ֤ם קָדוֹשׁ֙ אַתָּ֔ה לַ⁠יהוָ֖ה אֱלֹהֶ֑י⁠ךָ לֹֽא־תְבַשֵּׁ֥ל גְּדִ֖י בַּ⁠חֲלֵ֥ב אִמּֽ⁠וֹ׃פ","lò֣ʼ ţòʼkĕl֣ẇ kál-nĕ֠béláh la⁠gé̇֨r ʼàşěr-bi̇⁠şĕ̌ʻáre֜y⁠ká ţi̇ţĕ̇ne֣ná̇⁠h wa⁠ʼàkálá֗⁠ḣ ʼ֤wò mákòr֙ lĕ⁠nákĕri֔y ki֣̇y ʻa֤m qádwòş̌֙ ʼaţá̇֔h la⁠yhwá֖h ʼèlòhe֑y⁠ká lòֽʼ-ţĕbaşé֥̇̌l gĕ̇di֖y bȧ⁠ẖàlé֥b ʼiṁֽ⁠wò׃p"],[14,22,"עַשֵּׂ֣ר תְּעַשֵּׂ֔ר אֵ֖ת כָּל־תְּבוּאַ֣ת זַרְעֶ֑⁠ךָ הַ⁠יֹּצֵ֥א הַ⁠שָּׂדֶ֖ה שָׁנָ֥ה שָׁנָֽה׃","ʻaşé֣̇̂r ţĕ̇ʻaşé̇̂֔r ʼé֖ţ ká̇l-ţĕ̇bẇʼa֣ţ zarĕʻe֑⁠ká ha⁠yò̇ẕé֥ʼ ha⁠şá̇̂de֖h şá̌ná֥h şá̌náֽh׃"],[14,23,"וְ⁠אָכַלְתָּ֞ לִ⁠פְנֵ֣י ׀ יְהוָ֣ה אֱלֹהֶ֗י⁠ךָ בַּ⁠מָּק֣וֹם אֲשֶׁר־יִבְחַר֮ לְ⁠שַׁכֵּ֣ן שְׁמ֣⁠וֹ שָׁם֒ מַעְשַׂ֤ר דְּגָֽנְ⁠ךָ֙ תִּֽירֹשְׁ⁠ךָ֣ וְ⁠יִצְהָרֶ֔⁠ךָ וּ⁠בְכֹרֹ֥ת בְּקָרְ⁠ךָ֖ וְ⁠צֹאנֶ֑⁠ךָ לְמַ֣עַן תִּלְמַ֗ד לְ⁠יִרְאָ֛ה אֶת־יְהוָ֥ה אֱלֹהֶ֖י⁠ךָ כָּל־הַ⁠יָּמִֽים׃","wĕ⁠ʼákalĕţá̇֞ li⁠pĕné֣y ׀ yĕhwá֣h ʼèlòhe֗y⁠ká bȧ⁠má̇q֣wòm ʼàşěr-yibĕẖar֮ lĕ⁠şǎké֣̇n şĕ̌m֣⁠wò şá̌m֒ maʻĕşâ֤r dĕ̇gáֽnĕ⁠ká֙ ţiֽ̇yròşĕ̌⁠ká֣ wĕ⁠yiẕĕháre֔⁠ká ẇ⁠bĕkòrò֥ţ bĕ̇qárĕ⁠ká֖ wĕ⁠ẕòʼne֑⁠ká lĕma֣ʻan ţi̇lĕma֗d lĕ⁠yirĕʼá֛h ʼeţ-yĕhwá֥h ʼèlòhe֖y⁠ká ká̇l-ha⁠yá̇miֽym׃"],[14,24,"וְ⁠כִֽי־יִרְבֶּ֨ה מִמְּ⁠ךָ֜ הַ⁠דֶּ֗רֶךְ כִּ֣י לֹ֣א תוּכַ֘ל שְׂאֵת⁠וֹ֒ כִּֽי־יִרְחַ֤ק מִמְּ⁠ךָ֙ הַ⁠מָּק֔וֹם אֲשֶׁ֤ר יִבְחַר֙ יְהוָ֣ה אֱלֹהֶ֔י⁠ךָ לָ⁠שׂ֥וּם שְׁמ֖⁠וֹ שָׁ֑ם כִּ֥י יְבָרֶכְ⁠ךָ֖ יְהוָ֥ה אֱלֹהֶֽי⁠ךָ׃","wĕ⁠kiֽy-yirĕbė֨h mimĕ̇⁠ká֜ ha⁠dė֗rekĕ ki֣̇y lò֣ʼ ţẇka֘l şĕ̂ʼéţ⁠wò֒ kiֽ̇y-yirĕẖa֤q mimĕ̇⁠ká֙ ha⁠má̇q֔wòm ʼàşě֤r yibĕẖar֙ yĕhwá֣h ʼèlòhe֔y⁠ká lá⁠ş֥̂ẇm şĕ̌m֖⁠wò şá֑̌m ki֥̇y yĕbárekĕ⁠ká֖ yĕhwá֥h ʼèlòheֽy⁠ká׃"],[14,25,"וְ⁠נָתַתָּ֖ה בַּ⁠כָּ֑סֶף וְ⁠צַרְתָּ֤ הַ⁠כֶּ֨סֶף֙ בְּ⁠יָ֣דְ⁠ךָ֔ וְ⁠הָֽלַכְתָּ֙ אֶל־הַ⁠מָּק֔וֹם אֲשֶׁ֥ר יִבְחַ֛ר יְהוָ֥ה אֱלֹהֶ֖י⁠ךָ בּֽ⁠וֹ׃","wĕ⁠náţaţá֖̇h bȧ⁠ká֑̇sep wĕ⁠ẕarĕţá֤̇ ha⁠kė֨sep֙ bĕ̇⁠yá֣dĕ⁠ká֔ wĕ⁠háֽlakĕţá̇֙ ʼel-ha⁠má̇q֔wòm ʼàşě֥r yibĕẖa֛r yĕhwá֥h ʼèlòhe֖y⁠ká ḃֽ⁠wò׃"],[14,26,"וְ⁠נָתַתָּ֣ה הַ⁠כֶּ֡סֶף בְּ⁠כֹל֩ אֲשֶׁר־תְּאַוֶּ֨ה נַפְשְׁ⁠ךָ֜ בַּ⁠בָּקָ֣ר וּ⁠בַ⁠צֹּ֗אן וּ⁠בַ⁠יַּ֨יִן֙ וּ⁠בַ⁠שֵּׁכָ֔ר וּ⁠בְ⁠כֹ֛ל אֲשֶׁ֥ר תִּֽשְׁאָלְ⁠ךָ֖ נַפְשֶׁ֑⁠ךָ וְ⁠אָכַ֣לְתָּ שָּׁ֗ם לִ⁠פְנֵי֙ יְהוָ֣ה אֱלֹהֶ֔י⁠ךָ וְ⁠שָׂמַחְתָּ֖ אַתָּ֥ה וּ⁠בֵיתֶֽ⁠ךָ׃","wĕ⁠náţaţá֣̇h ha⁠kė֡sep bĕ̇⁠kòl֩ ʼàşěr-ţĕ̇ʼawė֨h napĕşĕ̌⁠ká֜ bȧ⁠bá̇qá֣r ẇ⁠ba⁠ẕò̇֗ʼn ẇ⁠ba⁠yȧ֨yin֙ ẇ⁠ba⁠şé̇̌ká֔r ẇ⁠bĕ⁠kò֛l ʼàşě֥r ţiֽ̇şĕ̌ʼálĕ⁠ká֖ napĕşě֑⁠ká wĕ⁠ʼáka֣lĕţá̇ şá̇̌֗m li⁠pĕnéy֙ yĕhwá֣h ʼèlòhe֔y⁠ká wĕ⁠şá̂maẖĕţá֖̇ ʼaţá֥̇h ẇ⁠béyţeֽ⁠ká׃"],[14,27,"וְ⁠הַ⁠לֵּוִ֥י אֲשֶׁר־בִּ⁠שְׁעָרֶ֖י⁠ךָ לֹ֣א תַֽעַזְבֶ֑⁠נּוּ כִּ֣י אֵ֥ין ל֛⁠וֹ חֵ֥לֶק וְ⁠נַחֲלָ֖ה עִמָּֽ⁠ךְ׃ס","wĕ⁠ha⁠lé̇wi֥y ʼàşěr-bi̇⁠şĕ̌ʻáre֖y⁠ká lò֣ʼ ţaֽʻazĕbe֑⁠ṅẇ ki֣̇y ʼé֥yn l֛⁠wò ẖé֥leq wĕ⁠naẖàlá֖h ʻimáֽ̇⁠kĕ׃s"],[14,28,"מִ⁠קְצֵ֣ה ׀ שָׁלֹ֣שׁ שָׁנִ֗ים תּוֹצִיא֙ אֶת־כָּל־מַעְשַׂר֙ תְּבוּאָ֣תְ⁠ךָ֔ בַּ⁠שָּׁנָ֖ה הַ⁠הִ֑וא וְ⁠הִנַּחְתָּ֖ בִּ⁠שְׁעָרֶֽי⁠ךָ׃","mi⁠qĕẕé֣h ׀ şá̌lò֣ş̌ şá̌ni֗ym ţ̇wòẕiyʼ֙ ʼeţ-ká̇l-maʻĕşâr֙ ţĕ̇bẇʼá֣ţĕ⁠ká֔ bȧ⁠şá̇̌ná֖h ha⁠hi֑wʼ wĕ⁠hinȧẖĕţá֖̇ bi̇⁠şĕ̌ʻáreֽy⁠ká׃"],[14,29,"וּ⁠בָ֣א הַ⁠לֵּוִ֡י כִּ֣י אֵֽין־ל⁠וֹ֩ חֵ֨לֶק וְ⁠נַחֲלָ֜ה עִמָּ֗⁠ךְ וְ֠⁠הַ⁠גֵּר וְ⁠הַ⁠יָּת֤וֹם וְ⁠הָֽ⁠אַלְמָנָה֙ אֲשֶׁ֣ר בִּ⁠שְׁעָרֶ֔י⁠ךָ וְ⁠אָכְל֖וּ וְ⁠שָׂבֵ֑עוּ לְמַ֤עַן יְבָרֶכְ⁠ךָ֙ יְהוָ֣ה אֱלֹהֶ֔י⁠ךָ בְּ⁠כָל־מַעֲשֵׂ֥ה יָדְ⁠ךָ֖ אֲשֶׁ֥ר תַּעֲשֶֽׂה׃ס","ẇ⁠bá֣ʼ ha⁠lé̇wi֡y ki֣̇y ʼéֽyn-l⁠wò֩ ẖé֨leq wĕ⁠naẖàlá֜h ʻimá̇֗⁠kĕ wĕ֠⁠ha⁠gé̇r wĕ⁠ha⁠yá̇ţ֤wòm wĕ⁠háֽ⁠ʼalĕmánáh֙ ʼàşě֣r bi̇⁠şĕ̌ʻáre֔y⁠ká wĕ⁠ʼákĕl֖ẇ wĕ⁠şá̂bé֑ʻẇ lĕma֤ʻan yĕbárekĕ⁠ká֙ yĕhwá֣h ʼèlòhe֔y⁠ká bĕ̇⁠kál-maʻàşé֥̂h yádĕ⁠ká֖ ʼàşě֥r ţȧʻàşêֽh׃s"],[15,1,"מִ⁠קֵּ֥ץ שֶֽׁבַע־שָׁנִ֖ים תַּעֲשֶׂ֥ה שְׁמִטָּֽה׃","mi⁠qé֥̇ẕ şěֽbaʻ-şá̌ni֖ym ţȧʻàşê֥h şĕ̌mitáֽ̇h׃"],[15,2,"וְ⁠זֶה֮ דְּבַ֣ר הַ⁠שְּׁמִטָּה֒ שָׁמ֗וֹט כָּל־בַּ֨עַל֙ מַשֵּׁ֣ה יָד֔⁠וֹ אֲשֶׁ֥ר יַשֶּׁ֖ה בְּ⁠רֵעֵ֑⁠הוּ לֹֽא־יִגֹּ֤שׂ אֶת־רֵעֵ֨⁠הוּ֙ וְ⁠אֶת־אָחִ֔י⁠ו כִּֽי־קָרָ֥א שְׁמִטָּ֖ה לַֽ⁠יהוָֽה׃","wĕ⁠zeh֮ dĕ̇ba֣r ha⁠şĕ̇̌mitá̇h֒ şá̌m֗wòt ká̇l-bȧ֨ʻal֙ maşé֣̇̌h yád֔⁠wò ʼàşě֥r yaşė֖̌h bĕ̇⁠réʻé֑⁠hẇ lòֽʼ-yigò֤̇ş̂ ʼeţ-réʻé֨⁠hẇ֙ wĕ⁠ʼeţ-ʼáẖi֔y⁠w kiֽ̇y-qárá֥ʼ şĕ̌mitá֖̇h laֽ⁠yhwáֽh׃"],[15,3,"אֶת־הַ⁠נָּכְרִ֖י תִּגֹּ֑שׂ וַ⁠אֲשֶׁ֨ר יִהְיֶ֥ה לְ⁠ךָ֛ אֶת־אָחִ֖י⁠ךָ תַּשְׁמֵ֥ט יָדֶֽ⁠ךָ׃","ʼeţ-ha⁠ná̇kĕri֖y ţi̇gò֑̇ş̂ wa⁠ʼàşě֨r yihĕye֥h lĕ⁠ká֛ ʼeţ-ʼáẖi֖y⁠ká ţȧşĕ̌mé֥t yádeֽ⁠ká׃"],[15,4,"אֶ֕פֶס כִּ֛י לֹ֥א יִֽהְיֶה־בְּ⁠ךָ֖ אֶבְי֑וֹן כִּֽי־בָרֵ֤ךְ יְבָֽרֶכְ⁠ךָ֙ יְהוָ֔ה בָּ⁠אָ֕רֶץ אֲשֶׁר֙ יְהוָ֣ה אֱלֹהֶ֔י⁠ךָ נֹֽתֵן־לְ⁠ךָ֥ נַחֲלָ֖ה לְ⁠רִשְׁתָּֽ⁠הּ׃","ʼe֕pes ki֛̇y lò֥ʼ yiֽhĕyeh-bĕ̇⁠ká֖ ʼebĕy֑wòn kiֽ̇y-báré֤kĕ yĕbáֽrekĕ⁠ká֙ yĕhwá֔h bá̇⁠ʼá֕reẕ ʼàşěr֙ yĕhwá֣h ʼèlòhe֔y⁠ká nòֽţén-lĕ⁠ká֥ naẖàlá֖h lĕ⁠rişĕ̌ţáֽ̇⁠ḣ׃"],[15,5,"רַ֚ק אִם־שָׁמ֣וֹעַ תִּשְׁמַ֔ע בְּ⁠ק֖וֹל יְהוָ֣ה אֱלֹהֶ֑י⁠ךָ לִ⁠שְׁמֹ֤ר לַ⁠עֲשׂוֹת֙ אֶת־כָּל־הַ⁠מִּצְוָ֣ה הַ⁠זֹּ֔את אֲשֶׁ֛ר אָנֹכִ֥י מְצַוְּ⁠ךָ֖ הַ⁠יּֽוֹם׃","ra֚q ʼim-şá̌m֣wòʻa ţi̇şĕ̌ma֔ʻ bĕ̇⁠q֖wòl yĕhwá֣h ʼèlòhe֑y⁠ká li⁠şĕ̌mò֤r la⁠ʻàş̂wòţ֙ ʼeţ-ká̇l-ha⁠mi̇ẕĕwá֣h ha⁠zò̇֔ʼţ ʼàşě֛r ʼánòki֥y mĕẕawĕ̇⁠ká֖ ha⁠ẏֽwòm׃"],[15,6,"כִּֽי־יְהוָ֤ה אֱלֹהֶ֨י⁠ךָ֙ בֵּֽרַכְ⁠ךָ֔ כַּ⁠אֲשֶׁ֖ר דִּבֶּר־לָ֑⁠ךְ וְ⁠הַֽעֲבַטְתָּ֞ גּוֹיִ֣ם רַבִּ֗ים וְ⁠אַתָּה֙ לֹ֣א תַעֲבֹ֔ט וּ⁠מָֽשַׁלְתָּ֙ בְּ⁠גוֹיִ֣ם רַבִּ֔ים וּ⁠בְ⁠ךָ֖ לֹ֥א יִמְשֹֽׁלוּ׃ס","kiֽ̇y-yĕhwá֤h ʼèlòhe֨y⁠ká֙ béֽ̇rakĕ⁠ká֔ kȧ⁠ʼàşě֖r di̇bėr-lá֑⁠kĕ wĕ⁠haֽʻàbatĕţá̇֞ ġwòyi֣m rabi̇֗ym wĕ⁠ʼaţá̇h֙ lò֣ʼ ţaʻàbò֔t ẇ⁠máֽşǎlĕţá̇֙ bĕ̇⁠gwòyi֣m rabi̇֔ym ẇ⁠bĕ⁠ká֖ lò֥ʼ yimĕşòֽ̌lẇ׃s"],[15,7,"כִּֽי־יִהְיֶה֩ בְ⁠ךָ֨ אֶבְי֜וֹן מֵ⁠אַחַ֤ד אַחֶ֨י⁠ךָ֙ בְּ⁠אַחַ֣ד שְׁעָרֶ֔י⁠ךָ בְּ⁠אַ֨רְצְ⁠ךָ֔ אֲשֶׁר־יְהוָ֥ה אֱלֹהֶ֖י⁠ךָ נֹתֵ֣ן לָ֑⁠ךְ לֹ֧א תְאַמֵּ֣ץ אֶת־לְבָבְ⁠ךָ֗ וְ⁠לֹ֤א תִקְפֹּץ֙ אֶת־יָ֣דְ⁠ךָ֔ מֵ⁠אָחִ֖י⁠ךָ הָ⁠אֶבְיֽוֹן׃","kiֽ̇y-yihĕyeh֩ bĕ⁠ká֨ ʼebĕy֜wòn mé⁠ʼaẖa֤d ʼaẖe֨y⁠ká֙ bĕ̇⁠ʼaẖa֣d şĕ̌ʻáre֔y⁠ká bĕ̇⁠ʼa֨rĕẕĕ⁠ká֔ ʼàşěr-yĕhwá֥h ʼèlòhe֖y⁠ká nòţé֣n lá֑⁠kĕ lò֧ʼ ţĕʼamé֣̇ẕ ʼeţ-lĕbábĕ⁠ká֗ wĕ⁠lò֤ʼ ţiqĕpò̇ẕ֙ ʼeţ-yá֣dĕ⁠ká֔ mé⁠ʼáẖi֖y⁠ká há⁠ʼebĕyֽwòn׃"],[15,8,"כִּֽי־פָתֹ֧חַ תִּפְתַּ֛ח אֶת־יָדְ⁠ךָ֖ ל֑⁠וֹ וְ⁠הַעֲבֵט֙ תַּעֲבִיטֶ֔⁠נּוּ דֵּ֚י מַחְסֹר֔⁠וֹ אֲשֶׁ֥ר יֶחְסַ֖ר לֽ⁠וֹ׃","kiֽ̇y-páţò֧ẖa ţi̇pĕţȧ֛ẖ ʼeţ-yádĕ⁠ká֖ l֑⁠wò wĕ⁠haʻàbét֙ ţȧʻàbiyte֔⁠ṅẇ dé֚̇y maẖĕsòr֔⁠wò ʼàşě֥r yeẖĕsa֖r lֽ⁠wò׃"],[15,9,"הִשָּׁ֣מֶר לְ⁠ךָ֡ פֶּן־יִהְיֶ֣ה דָבָר֩ עִם־לְבָבְ⁠ךָ֨ בְלִיַּ֜עַל לֵ⁠אמֹ֗ר קָֽרְבָ֣ה שְׁנַֽת־הַ⁠שֶּׁבַע֮ שְׁנַ֣ת הַ⁠שְּׁמִטָּה֒ וְ⁠רָעָ֣ה עֵֽינְ⁠ךָ֗ בְּ⁠אָחִ֨י⁠ךָ֙ הָֽ⁠אֶבְי֔וֹן וְ⁠לֹ֥א תִתֵּ֖ן ל֑⁠וֹ וְ⁠קָרָ֤א עָלֶ֨י⁠ךָ֙ אֶל־יְהוָ֔ה וְ⁠הָיָ֥ה בְ⁠ךָ֖ חֵֽטְא׃","hişá֣̇̌mer lĕ⁠ká֡ pėn-yihĕye֣h dábár֩ ʻim-lĕbábĕ⁠ká֨ bĕliyȧ֜ʻal lé⁠ʼmò֗r qáֽrĕbá֣h şĕ̌naֽţ-ha⁠şė̌baʻ֮ şĕ̌na֣ţ ha⁠şĕ̇̌mitá̇h֒ wĕ⁠ráʻá֣h ʻéֽynĕ⁠ká֗ bĕ̇⁠ʼáẖi֨y⁠ká֙ háֽ⁠ʼebĕy֔wòn wĕ⁠lò֥ʼ ţiţé֖̇n l֑⁠wò wĕ⁠qárá֤ʼ ʻále֨y⁠ká֙ ʼel-yĕhwá֔h wĕ⁠háyá֥h bĕ⁠ká֖ ẖéֽtĕʼ׃"],[15,10,"נָת֤וֹן תִּתֵּן֙ ל֔⁠וֹ וְ⁠לֹא־יֵרַ֥ע לְבָבְ⁠ךָ֖ בְּ⁠תִתְּ⁠ךָ֣ ל֑⁠וֹ כִּ֞י בִּ⁠גְלַ֣ל ׀ הַ⁠דָּבָ֣ר הַ⁠זֶּ֗ה יְבָרֶכְ⁠ךָ֙ יְהוָ֣ה אֱלֹהֶ֔י⁠ךָ בְּ⁠כָֽל־מַעֲשֶׂ֔⁠ךָ וּ⁠בְ⁠כֹ֖ל מִשְׁלַ֥ח יָדֶֽ⁠ךָ׃","náţ֤wòn ţi̇ţé̇n֙ l֔⁠wò wĕ⁠lòʼ-yéra֥ʻ lĕbábĕ⁠ká֖ bĕ̇⁠ţiţĕ̇⁠ká֣ l֑⁠wò ki̇֞y bi̇⁠gĕla֣l ׀ ha⁠dá̇bá֣r ha⁠zė֗h yĕbárekĕ⁠ká֙ yĕhwá֣h ʼèlòhe֔y⁠ká bĕ̇⁠káֽl-maʻàşê֔⁠ká ẇ⁠bĕ⁠kò֖l mişĕ̌la֥ẖ yádeֽ⁠ká׃"],[15,11,"כִּ֛י לֹא־יֶחְדַּ֥ל אֶבְי֖וֹן מִ⁠קֶּ֣רֶב הָ⁠אָ֑רֶץ עַל־כֵּ֞ן אָנֹכִ֤י מְצַוְּ⁠ךָ֙ לֵ⁠אמֹ֔ר פָּ֠תֹחַ תִּפְתַּ֨ח אֶת־יָדְ⁠ךָ֜ לְ⁠אָחִ֧י⁠ךָ לַ⁠עֲנִיֶּ֛⁠ךָ וּ⁠לְ⁠אֶבְיֹנְ⁠ךָ֖ בְּ⁠אַרְצֶֽ⁠ךָ׃ס","ki֛̇y lòʼ-yeẖĕdȧ֥l ʼebĕy֖wòn mi⁠qė֣reb há⁠ʼá֑reẕ ʻal-ké̇֞n ʼánòki֤y mĕẕawĕ̇⁠ká֙ lé⁠ʼmò֔r pá̇֠ţòẖa ţi̇pĕţȧ֨ẖ ʼeţ-yádĕ⁠ká֜ lĕ⁠ʼáẖi֧y⁠ká la⁠ʻàniyė֛⁠ká ẇ⁠lĕ⁠ʼebĕyònĕ⁠ká֖ bĕ̇⁠ʼarĕẕeֽ⁠ká׃s"],[15,12,"כִּֽי־יִמָּכֵ֨ר לְ⁠ךָ֜ אָחִ֣י⁠ךָ הָֽ⁠עִבְרִ֗י א֚וֹ הָֽ⁠עִבְרִיָּ֔ה וַ⁠עֲבָֽדְ⁠ךָ֖ שֵׁ֣שׁ שָׁנִ֑ים וּ⁠בַ⁠שָּׁנָה֙ הַ⁠שְּׁבִיעִ֔ת תְּשַׁלְּחֶ֥⁠נּוּ חָפְשִׁ֖י מֵ⁠עִמָּֽ⁠ךְ׃","kiֽ̇y-yimá̇ké֨r lĕ⁠ká֜ ʼáẖi֣y⁠ká háֽ⁠ʻibĕri֗y ʼ֚wò háֽ⁠ʻibĕriyá̇֔h wa⁠ʻàbáֽdĕ⁠ká֖ şé֣̌ş̌ şá̌ni֑ym ẇ⁠ba⁠şá̇̌náh֙ ha⁠şĕ̇̌biyʻi֔ţ ţĕ̇şǎlĕ̇ẖe֥⁠ṅẇ ẖápĕşǐ֖y mé⁠ʻimáֽ̇⁠kĕ׃"],[15,13,"וְ⁠כִֽי־תְשַׁלְּחֶ֥⁠נּוּ חָפְשִׁ֖י מֵֽ⁠עִמָּ֑⁠ךְ לֹ֥א תְשַׁלְּחֶ֖⁠נּוּ רֵיקָֽם׃","wĕ⁠kiֽy-ţĕşǎlĕ̇ẖe֥⁠ṅẇ ẖápĕşǐ֖y méֽ⁠ʻimá֑̇⁠kĕ lò֥ʼ ţĕşǎlĕ̇ẖe֖⁠ṅẇ réyqáֽm׃"],[15,14,"הַעֲנֵ֤יק תַּעֲנִיק֙ ל֔⁠וֹ מִ⁠צֹּ֣אנְ⁠ךָ֔ וּ⁠מִֽ⁠גָּרְנְ⁠ךָ֖ וּ⁠מִ⁠יִּקְבֶ֑⁠ךָ אֲשֶׁ֧ר בֵּרַכְ⁠ךָ֛ יְהוָ֥ה אֱלֹהֶ֖י⁠ךָ תִּתֶּן־לֽ⁠וֹ׃","haʻàné֤yq ţȧʻàniyq֙ l֔⁠wò mi⁠ẕò֣̇ʼnĕ⁠ká֔ ẇ⁠miֽ⁠gá̇rĕnĕ⁠ká֖ ẇ⁠mi⁠yi̇qĕbe֑⁠ká ʼàşě֧r bé̇rakĕ⁠ká֛ yĕhwá֥h ʼèlòhe֖y⁠ká ţi̇ţėn-lֽ⁠wò׃"],[15,15,"וְ⁠זָכַרְתָּ֗ כִּ֣י עֶ֤בֶד הָיִ֨יתָ֙ בְּ⁠אֶ֣רֶץ מִצְרַ֔יִם וַֽ⁠יִּפְדְּ⁠ךָ֖ יְהוָ֣ה אֱלֹהֶ֑י⁠ךָ עַל־כֵּ֞ן אָנֹכִ֧י מְצַוְּ⁠ךָ֛ אֶת־הַ⁠דָּבָ֥ר הַ⁠זֶּ֖ה הַ⁠יּֽוֹם׃","wĕ⁠zákarĕţá̇֗ ki֣̇y ʻe֤bed háyi֨yţá֙ bĕ̇⁠ʼe֣reẕ miẕĕra֔yim waֽ⁠yi̇pĕdĕ̇⁠ká֖ yĕhwá֣h ʼèlòhe֑y⁠ká ʻal-ké̇֞n ʼánòki֧y mĕẕawĕ̇⁠ká֛ ʼeţ-ha⁠dá̇bá֥r ha⁠zė֖h ha⁠ẏֽwòm׃"],[15,16,"וְ⁠הָיָה֙ כִּֽי־יֹאמַ֣ר אֵלֶ֔י⁠ךָ לֹ֥א אֵצֵ֖א מֵ⁠עִמָּ֑⁠ךְ כִּ֤י אֲהֵֽבְ⁠ךָ֙ וְ⁠אֶת־בֵּיתֶ֔⁠ךָ כִּי־ט֥וֹב ל֖⁠וֹ עִמָּֽ⁠ךְ׃","wĕ⁠háyáh֙ kiֽ̇y-yòʼma֣r ʼéle֔y⁠ká lò֥ʼ ʼéẕé֖ʼ mé⁠ʻimá֑̇⁠kĕ ki֤̇y ʼàhéֽbĕ⁠ká֙ wĕ⁠ʼeţ-bé̇yţe֔⁠ká ki̇y-t֥wòb l֖⁠wò ʻimáֽ̇⁠kĕ׃"],[15,17,"וְ⁠לָקַחְתָּ֣ אֶת־הַ⁠מַּרְצֵ֗עַ וְ⁠נָתַתָּ֤ה בְ⁠אָזְנ⁠וֹ֙ וּ⁠בַ⁠דֶּ֔לֶת וְ⁠הָיָ֥ה לְ⁠ךָ֖ עֶ֣בֶד עוֹלָ֑ם וְ⁠אַ֥ף לַ⁠אֲמָתְ⁠ךָ֖ תַּעֲשֶׂה־כֵּֽן׃","wĕ⁠láqaẖĕţá֣̇ ʼeţ-ha⁠mȧrĕẕé֗ʻa wĕ⁠náţaţá֤̇h bĕ⁠ʼázĕn⁠wò֙ ẇ⁠ba⁠dė֔leţ wĕ⁠háyá֥h lĕ⁠ká֖ ʻe֣bed ʻwòlá֑m wĕ⁠ʼa֥p la⁠ʼàmáţĕ⁠ká֖ ţȧʻàşêh-kéֽ̇n׃"],[15,18,"לֹא־יִקְשֶׁ֣ה בְ⁠עֵינֶ֗⁠ךָ בְּ⁠שַׁלֵּֽחֲ⁠ךָ֙ אֹת֤⁠וֹ חָפְשִׁי֙ מֵֽ⁠עִמָּ֔⁠ךְ כִּ֗י מִשְׁנֶה֙ שְׂכַ֣ר שָׂכִ֔יר עֲבָֽדְ⁠ךָ֖ שֵׁ֣שׁ שָׁנִ֑ים וּ⁠בֵֽרַכְ⁠ךָ֙ יְהוָ֣ה אֱלֹהֶ֔י⁠ךָ בְּ⁠כֹ֖ל אֲשֶׁ֥ר תַּעֲשֶֽׂה׃פ","lòʼ-yiqĕşě֣h bĕ⁠ʻéyne֗⁠ká bĕ̇⁠şǎléֽ̇ẖà⁠ká֙ ʼòţ֤⁠wò ẖápĕşǐy֙ méֽ⁠ʻimá̇֔⁠kĕ ki̇֗y mişĕ̌neh֙ şĕ̂ka֣r şá̂ki֔yr ʻàbáֽdĕ⁠ká֖ şé֣̌ş̌ şá̌ni֑ym ẇ⁠béֽrakĕ⁠ká֙ yĕhwá֣h ʼèlòhe֔y⁠ká bĕ̇⁠kò֖l ʼàşě֥r ţȧʻàşêֽh׃p"],[15,19,"כָּֽל־הַ⁠בְּכ֡וֹר אֲשֶׁר֩ יִוָּלֵ֨ד בִּ⁠בְקָרְ⁠ךָ֤ וּ⁠בְ⁠צֹֽאנְ⁠ךָ֙ הַ⁠זָּכָ֔ר תַּקְדִּ֖ישׁ לַ⁠יהוָ֣ה אֱלֹהֶ֑י⁠ךָ לֹ֤א תַעֲבֹד֙ בִּ⁠בְכֹ֣ר שׁוֹרֶ֔⁠ךָ וְ⁠לֹ֥א תָגֹ֖ז בְּכ֥וֹר צֹאנֶֽ⁠ךָ׃","káֽ̇l-ha⁠bĕ̇k֡wòr ʼàşěr֩ yiwá̇lé֨d bi̇⁠bĕqárĕ⁠ká֤ ẇ⁠bĕ⁠ẕòֽʼnĕ⁠ká֙ ha⁠zá̇ká֔r ţȧqĕdi֖̇yş̌ la⁠yhwá֣h ʼèlòhe֑y⁠ká lò֤ʼ ţaʻàbòd֙ bi̇⁠bĕkò֣r ş̌wòre֔⁠ká wĕ⁠lò֥ʼ ţágò֖z bĕ̇k֥wòr ẕòʼneֽ⁠ká׃"],[15,20,"לִ⁠פְנֵי֩ יְהוָ֨ה אֱלֹהֶ֤י⁠ךָ תֹאכֲלֶ֨⁠נּוּ֙ שָׁנָ֣ה בְ⁠שָׁנָ֔ה בַּ⁠מָּק֖וֹם אֲשֶׁר־יִבְחַ֣ר יְהוָ֑ה אַתָּ֖ה וּ⁠בֵיתֶֽ⁠ךָ׃","li⁠pĕnéy֩ yĕhwá֨h ʼèlòhe֤y⁠ká ţòʼkàle֨⁠ṅẇ֙ şá̌ná֣h bĕ⁠şá̌ná֔h bȧ⁠má̇q֖wòm ʼàşěr-yibĕẖa֣r yĕhwá֑h ʼaţá֖̇h ẇ⁠béyţeֽ⁠ká׃"],[15,21,"וְ⁠כִֽי־יִהְיֶ֨ה ב֜⁠וֹ מ֗וּם פִּסֵּ֨חַ֙ א֣וֹ עִוֵּ֔ר כֹּ֖ל מ֣וּם רָ֑ע לֹ֣א תִזְבָּחֶ֔⁠נּוּ לַ⁠יהוָ֖ה אֱלֹהֶֽי⁠ךָ׃","wĕ⁠kiֽy-yihĕye֨h b֜⁠wò m֗ẇm pi̇sé̇֨ẖa֙ ʼ֣wò ʻiwé̇֔r kò֖̇l m֣ẇm rá֑ʻ lò֣ʼ ţizĕbá̇ẖe֔⁠ṅẇ la⁠yhwá֖h ʼèlòheֽy⁠ká׃"],[15,22,"בִּ⁠שְׁעָרֶ֖י⁠ךָ תֹּאכֲלֶ֑⁠נּוּ הַ⁠טָּמֵ֤א וְ⁠הַ⁠טָּהוֹר֙ יַחְדָּ֔ו כַּ⁠צְּבִ֖י וְ⁠כָ⁠אַיָּֽל׃","bi̇⁠şĕ̌ʻáre֖y⁠ká ţò̇ʼkàle֑⁠ṅẇ ha⁠tá̇mé֤ʼ wĕ⁠ha⁠tá̇hwòr֙ yaẖĕdá̇֔w kȧ⁠ẕĕ̇bi֖y wĕ⁠ká⁠ʼayáֽ̇l׃"],[15,23,"רַ֥ק אֶת־דָּמ֖⁠וֹ לֹ֣א תֹאכֵ֑ל עַל־הָ⁠אָ֥רֶץ תִּשְׁפְּכֶ֖⁠נּוּ כַּ⁠מָּֽיִם׃פ","ra֥q ʼeţ-dá̇m֖⁠wò lò֣ʼ ţòʼké֑l ʻal-há⁠ʼá֥reẕ ţi̇şĕ̌pĕ̇ke֖⁠ṅẇ kȧ⁠máֽ̇yim׃p"],[16,1,"שָׁמוֹר֙ אֶת־חֹ֣דֶשׁ הָ⁠אָבִ֔יב וְ⁠עָשִׂ֣יתָ פֶּ֔סַח לַ⁠יהוָ֖ה אֱלֹהֶ֑י⁠ךָ כִּ֞י בְּ⁠חֹ֣דֶשׁ הָֽ⁠אָבִ֗יב הוֹצִ֨יאֲ⁠ךָ֜ יְהוָ֧ה אֱלֹהֶ֛י⁠ךָ מִ⁠מִּצְרַ֖יִם לָֽיְלָה׃","şá̌mwòr֙ ʼeţ-ẖò֣deş̌ há⁠ʼábi֔yb wĕ⁠ʻáşî֣yţá pė֔saẖ la⁠yhwá֖h ʼèlòhe֑y⁠ká ki̇֞y bĕ̇⁠ẖò֣deş̌ háֽ⁠ʼábi֗yb hwòẕi֨yʼà⁠ká֜ yĕhwá֧h ʼèlòhe֛y⁠ká mi⁠mi̇ẕĕra֖yim láֽyĕláh׃"],[16,2,"וְ⁠זָבַ֥חְתָּ פֶּ֛סַח לַ⁠יהוָ֥ה אֱלֹהֶ֖י⁠ךָ צֹ֣אן וּ⁠בָקָ֑ר בַּ⁠מָּקוֹם֙ אֲשֶׁר־יִבְחַ֣ר יְהוָ֔ה לְ⁠שַׁכֵּ֥ן שְׁמ֖⁠וֹ שָֽׁם׃","wĕ⁠zába֥ẖĕţá̇ pė֛saẖ la⁠yhwá֥h ʼèlòhe֖y⁠ká ẕò֣ʼn ẇ⁠báqá֑r bȧ⁠má̇qwòm֙ ʼàşěr-yibĕẖa֣r yĕhwá֔h lĕ⁠şǎké֥̇n şĕ̌m֖⁠wò şáֽ̌m׃"],[16,3,"לֹא־תֹאכַ֤ל עָלָי⁠ו֙ חָמֵ֔ץ שִׁבְעַ֥ת יָמִ֛ים תֹּֽאכַל־עָלָ֥י⁠ו מַצּ֖וֹת לֶ֣חֶם עֹ֑נִי כִּ֣י בְ⁠חִפָּז֗וֹן יָצָ֨אתָ֙ מֵ⁠אֶ֣רֶץ מִצְרַ֔יִם לְמַ֣עַן תִּזְכֹּר֔ אֶת־י֤וֹם צֵֽאתְ⁠ךָ֙ מֵ⁠אֶ֣רֶץ מִצְרַ֔יִם כֹּ֖ל יְמֵ֥י חַיֶּֽי⁠ךָ׃","lòʼ-ţòʼka֤l ʻáláy⁠w֙ ẖámé֔ẕ şǐbĕʻa֥ţ yámi֛ym ţòֽ̇ʼkal-ʻálá֥y⁠w maẕ֖̇wòţ le֣ẖem ʻò֑niy ki֣̇y bĕ⁠ẖipá̇z֗wòn yáẕá֨ʼţá֙ mé⁠ʼe֣reẕ miẕĕra֔yim lĕma֣ʻan ţi̇zĕkò̇r֔ ʼeţ-y֤wòm ẕéֽʼţĕ⁠ká֙ mé⁠ʼe֣reẕ miẕĕra֔yim kò֖̇l yĕmé֥y ẖayėֽy⁠ká׃"],[16,4,"וְ⁠לֹֽא־יֵרָאֶ֨ה לְ⁠ךָ֥ שְׂאֹ֛ר בְּ⁠כָל־גְּבֻלְ⁠ךָ֖ שִׁבְעַ֣ת יָמִ֑ים וְ⁠לֹא־יָלִ֣ין מִן־הַ⁠בָּשָׂ֗ר אֲשֶׁ֨ר תִּזְבַּ֥ח בָּ⁠עֶ֛רֶב בַּ⁠יּ֥וֹם הָ⁠רִאשׁ֖וֹן לַ⁠בֹּֽקֶר׃","wĕ⁠lòֽʼ-yéráʼe֨h lĕ⁠ká֥ şĕ̂ʼò֛r bĕ̇⁠kál-gĕ̇bulĕ⁠ká֖ şǐbĕʻa֣ţ yámi֑ym wĕ⁠lòʼ-yáli֣yn min-ha⁠bá̇şá̂֗r ʼàşě֨r ţi̇zĕbȧ֥ẖ bá̇⁠ʻe֛reb bȧ⁠ẏ֥wòm há⁠riʼş֖̌wòn la⁠bòֽ̇qer׃"],[16,5,"לֹ֥א תוּכַ֖ל לִ⁠זְבֹּ֣חַ אֶת־הַ⁠פָּ֑סַח בְּ⁠אַחַ֣ד שְׁעָרֶ֔י⁠ךָ אֲשֶׁר־יְהוָ֥ה אֱלֹהֶ֖י⁠ךָ נֹתֵ֥ן לָֽ⁠ךְ׃","lò֥ʼ ţẇka֖l li⁠zĕbò֣̇ẖa ʼeţ-ha⁠pá֑̇saẖ bĕ̇⁠ʼaẖa֣d şĕ̌ʻáre֔y⁠ká ʼàşěr-yĕhwá֥h ʼèlòhe֖y⁠ká nòţé֥n láֽ⁠kĕ׃"],[16,6,"כִּ֠י אִֽם־אֶל־הַ⁠מָּק֞וֹם אֲשֶׁר־יִבְחַ֨ר יְהוָ֤ה אֱלֹהֶ֨י⁠ךָ֙ לְ⁠שַׁכֵּ֣ן שְׁמ֔⁠וֹ שָׁ֛ם תִּזְבַּ֥ח אֶת־הַ⁠פֶּ֖סַח בָּ⁠עָ֑רֶב כְּ⁠ב֣וֹא הַ⁠שֶּׁ֔מֶשׁ מוֹעֵ֖ד צֵֽאתְ⁠ךָ֥ מִ⁠מִּצְרָֽיִם׃","ki̇֠y ʼiֽm-ʼel-ha⁠má̇q֞wòm ʼàşěr-yibĕẖa֨r yĕhwá֤h ʼèlòhe֨y⁠ká֙ lĕ⁠şǎké֣̇n şĕ̌m֔⁠wò şá֛̌m ţi̇zĕbȧ֥ẖ ʼeţ-ha⁠pė֖saẖ bá̇⁠ʻá֑reb kĕ̇⁠b֣wòʼ ha⁠şė̌֔meş̌ mwòʻé֖d ẕéֽʼţĕ⁠ká֥ mi⁠mi̇ẕĕráֽyim׃"],[16,7,"וּ⁠בִשַּׁלְתָּ֙ וְ⁠אָ֣כַלְתָּ֔ בַּ⁠מָּק֕וֹם אֲשֶׁ֥ר יִבְחַ֛ר יְהוָ֥ה אֱלֹהֶ֖י⁠ךָ בּ֑⁠וֹ וּ⁠פָנִ֣יתָ בַ⁠בֹּ֔קֶר וְ⁠הָלַכְתָּ֖ לְ⁠אֹהָלֶֽי⁠ךָ׃","ẇ⁠bişȧ̌lĕţá̇֙ wĕ⁠ʼá֣kalĕţá̇֔ bȧ⁠má̇q֕wòm ʼàşě֥r yibĕẖa֛r yĕhwá֥h ʼèlòhe֖y⁠ká ḃ֑⁠wò ẇ⁠páni֣yţá ba⁠bò̇֔qer wĕ⁠hálakĕţá֖̇ lĕ⁠ʼòháleֽy⁠ká׃"],[16,8,"שֵׁ֥שֶׁת יָמִ֖ים תֹּאכַ֣ל מַצּ֑וֹת וּ⁠בַ⁠יּ֣וֹם הַ⁠שְּׁבִיעִ֗י עֲצֶ֨רֶת֙ לַ⁠יהוָ֣ה אֱלֹהֶ֔י⁠ךָ לֹ֥א תַעֲשֶׂ֖ה מְלָאכָֽה׃ס","şé֥̌şěţ yámi֖ym ţò̇ʼka֣l maẕ֑̇wòţ ẇ⁠ba⁠ẏ֣wòm ha⁠şĕ̇̌biyʻi֗y ʻàẕe֨reţ֙ la⁠yhwá֣h ʼèlòhe֔y⁠ká lò֥ʼ ţaʻàşê֖h mĕláʼkáֽh׃s"],[16,9,"שִׁבְעָ֥ה שָׁבֻעֹ֖ת תִּסְפָּר־לָ֑⁠ךְ מֵ⁠הָחֵ֤ל חֶרְמֵשׁ֙ בַּ⁠קָּמָ֔ה תָּחֵ֣ל לִ⁠סְפֹּ֔ר שִׁבְעָ֖ה שָׁבֻעֽוֹת׃","şǐbĕʻá֥h şá̌buʻò֖ţ ţi̇sĕpá̇r-lá֑⁠kĕ mé⁠háẖé֤l ẖerĕméş̌֙ bȧ⁠qá̇má֔h ţá̇ẖé֣l li⁠sĕpò̇֔r şǐbĕʻá֖h şá̌buʻֽwòţ׃"],[16,10,"וְ⁠עָשִׂ֜יתָ חַ֤ג שָׁבֻעוֹת֙ לַ⁠יהוָ֣ה אֱלֹהֶ֔י⁠ךָ מִסַּ֛ת נִדְבַ֥ת יָדְ⁠ךָ֖ אֲשֶׁ֣ר תִּתֵּ֑ן כַּ⁠אֲשֶׁ֥ר יְבָרֶכְ⁠ךָ֖ יְהוָ֥ה אֱלֹהֶֽי⁠ךָ׃","wĕ⁠ʻáşî֜yţá ẖa֤g şá̌buʻwòţ֙ la⁠yhwá֣h ʼèlòhe֔y⁠ká misȧ֛ţ nidĕba֥ţ yádĕ⁠ká֖ ʼàşě֣r ţi̇ţé֑̇n kȧ⁠ʼàşě֥r yĕbárekĕ⁠ká֖ yĕhwá֥h ʼèlòheֽy⁠ká׃"],[16,11,"וְ⁠שָׂמַחְתָּ֞ לִ⁠פְנֵ֣י ׀ יְהוָ֣ה אֱלֹהֶ֗י⁠ךָ אַתָּ֨ה וּ⁠בִנְ⁠ךָ֣ וּ⁠בִתֶּ⁠ךָ֮ וְ⁠עַבְדְּ⁠ךָ֣ וַ⁠אֲמָתֶ⁠ךָ֒ וְ⁠הַ⁠לֵּוִי֙ אֲשֶׁ֣ר בִּ⁠שְׁעָרֶ֔י⁠ךָ וְ⁠הַ⁠גֵּ֛ר וְ⁠הַ⁠יָּת֥וֹם וְ⁠הָ⁠אַלְמָנָ֖ה אֲשֶׁ֣ר בְּ⁠קִרְבֶּ֑⁠ךָ בַּ⁠מָּק֗וֹם אֲשֶׁ֤ר יִבְחַר֙ יְהוָ֣ה אֱלֹהֶ֔י⁠ךָ לְ⁠שַׁכֵּ֥ן שְׁמ֖⁠וֹ שָֽׁם׃","wĕ⁠şá̂maẖĕţá̇֞ li⁠pĕné֣y ׀ yĕhwá֣h ʼèlòhe֗y⁠ká ʼaţá̇֨h ẇ⁠binĕ⁠ká֣ ẇ⁠biţė⁠ká֮ wĕ⁠ʻabĕdĕ̇⁠ká֣ wa⁠ʼàmáţe⁠ká֒ wĕ⁠ha⁠lé̇wiy֙ ʼàşě֣r bi̇⁠şĕ̌ʻáre֔y⁠ká wĕ⁠ha⁠gé֛̇r wĕ⁠ha⁠yá̇ţ֥wòm wĕ⁠há⁠ʼalĕmáná֖h ʼàşě֣r bĕ̇⁠qirĕbė֑⁠ká bȧ⁠má̇q֗wòm ʼàşě֤r yibĕẖar֙ yĕhwá֣h ʼèlòhe֔y⁠ká lĕ⁠şǎké֥̇n şĕ̌m֖⁠wò şáֽ̌m׃"],[16,12,"וְ⁠זָ֣כַרְתָּ֔ כִּי־עֶ֥בֶד הָיִ֖יתָ בְּ⁠מִצְרָ֑יִם וְ⁠שָׁמַרְתָּ֣ וְ⁠עָשִׂ֔יתָ אֶת־הַֽ⁠חֻקִּ֖ים הָ⁠אֵֽלֶּה׃פ","wĕ⁠zá֣karĕţá̇֔ ki̇y-ʻe֥bed háyi֖yţá bĕ̇⁠miẕĕrá֑yim wĕ⁠şá̌marĕţá֣̇ wĕ⁠ʻáşî֔yţá ʼeţ-haֽ⁠ẖuqi֖̇ym há⁠ʼéֽlėh׃p"],[16,13,"חַ֧ג הַ⁠סֻּכֹּ֛ת תַּעֲשֶׂ֥ה לְ⁠ךָ֖ שִׁבְעַ֣ת יָמִ֑ים בְּ⁠אָ֨סְפְּ⁠ךָ֔ מִֽ⁠גָּרְנְ⁠ךָ֖ וּ⁠מִ⁠יִּקְבֶֽ⁠ךָ׃","ẖa֧g ha⁠su̇kò֛̇ţ ţȧʻàşê֥h lĕ⁠ká֖ şǐbĕʻa֣ţ yámi֑ym bĕ̇⁠ʼá֨sĕpĕ̇⁠ká֔ miֽ⁠gá̇rĕnĕ⁠ká֖ ẇ⁠mi⁠yi̇qĕbeֽ⁠ká׃"],[16,14,"וְ⁠שָׂמַחְתָּ֖ בְּ⁠חַגֶּ֑⁠ךָ אַתָּ֨ה וּ⁠בִנְ⁠ךָ֤ וּ⁠בִתֶּ֨⁠ךָ֙ וְ⁠עַבְדְּ⁠ךָ֣ וַ⁠אֲמָתֶ֔⁠ךָ וְ⁠הַ⁠לֵּוִ֗י וְ⁠הַ⁠גֵּ֛ר וְ⁠הַ⁠יָּת֥וֹם וְ⁠הָ⁠אַלְמָנָ֖ה אֲשֶׁ֥ר בִּ⁠שְׁעָרֶֽי⁠ךָ׃","wĕ⁠şá̂maẖĕţá֖̇ bĕ̇⁠ẖagė֑⁠ká ʼaţá̇֨h ẇ⁠binĕ⁠ká֤ ẇ⁠biţė֨⁠ká֙ wĕ⁠ʻabĕdĕ̇⁠ká֣ wa⁠ʼàmáţe֔⁠ká wĕ⁠ha⁠lé̇wi֗y wĕ⁠ha⁠gé֛̇r wĕ⁠ha⁠yá̇ţ֥wòm wĕ⁠há⁠ʼalĕmáná֖h ʼàşě֥r bi̇⁠şĕ̌ʻáreֽy⁠ká׃"],[16,15,"שִׁבְעַ֣ת יָמִ֗ים תָּחֹג֙ לַ⁠יהוָ֣ה אֱלֹהֶ֔י⁠ךָ בַּ⁠מָּק֖וֹם אֲשֶׁר־יִבְחַ֣ר יְהוָ֑ה כִּ֣י יְבָרֶכְ⁠ךָ֞ יְהוָ֣ה אֱלֹהֶ֗י⁠ךָ בְּ⁠כֹ֤ל תְּבוּאָֽתְ⁠ךָ֙ וּ⁠בְ⁠כֹל֙ מַעֲשֵׂ֣ה יָדֶ֔י⁠ךָ וְ⁠הָיִ֖יתָ אַ֥ךְ שָׂמֵֽחַ׃","şǐbĕʻa֣ţ yámi֗ym ţá̇ẖòg֙ la⁠yhwá֣h ʼèlòhe֔y⁠ká bȧ⁠má̇q֖wòm ʼàşěr-yibĕẖa֣r yĕhwá֑h ki֣̇y yĕbárekĕ⁠ká֞ yĕhwá֣h ʼèlòhe֗y⁠ká bĕ̇⁠kò֤l ţĕ̇bẇʼáֽţĕ⁠ká֙ ẇ⁠bĕ⁠kòl֙ maʻàşé֣̂h yáde֔y⁠ká wĕ⁠háyi֖yţá ʼa֥kĕ şá̂méֽẖa׃"],[16,16,"שָׁל֣וֹשׁ פְּעָמִ֣ים ׀ בַּ⁠שָּׁנָ֡ה יֵרָאֶ֨ה כָל־זְכוּרְ⁠ךָ֜ אֶת־פְּנֵ֣י ׀ יְהוָ֣ה אֱלֹהֶ֗י⁠ךָ בַּ⁠מָּקוֹם֙ אֲשֶׁ֣ר יִבְחָ֔ר בְּ⁠חַ֧ג הַ⁠מַּצּ֛וֹת וּ⁠בְ⁠חַ֥ג הַ⁠שָּׁבֻע֖וֹת וּ⁠בְ⁠חַ֣ג הַ⁠סֻּכּ֑וֹת וְ⁠לֹ֧א יֵרָאֶ֛ה אֶת־פְּנֵ֥י יְהוָ֖ה רֵיקָֽם׃","şá̌l֣wòş̌ pĕ̇ʻámi֣ym ׀ bȧ⁠şá̇̌ná֡h yéráʼe֨h kál-zĕkẇrĕ⁠ká֜ ʼeţ-pĕ̇né֣y ׀ yĕhwá֣h ʼèlòhe֗y⁠ká bȧ⁠má̇qwòm֙ ʼàşě֣r yibĕẖá֔r bĕ̇⁠ẖa֧g ha⁠mȧẕ֛̇wòţ ẇ⁠bĕ⁠ẖa֥g ha⁠şá̇̌buʻ֖wòţ ẇ⁠bĕ⁠ẖa֣g ha⁠su̇k֑̇wòţ wĕ⁠lò֧ʼ yéráʼe֛h ʼeţ-pĕ̇né֥y yĕhwá֖h réyqáֽm׃"],[16,17,"אִ֖ישׁ כְּ⁠מַתְּנַ֣ת יָד֑⁠וֹ כְּ⁠בִרְכַּ֛ת יְהוָ֥ה אֱלֹהֶ֖י⁠ךָ אֲשֶׁ֥ר נָֽתַן־לָֽ⁠ךְ׃ס","ʼi֖yş̌ kĕ̇⁠maţĕ̇na֣ţ yád֑⁠wò kĕ̇⁠birĕkȧ֛ţ yĕhwá֥h ʼèlòhe֖y⁠ká ʼàşě֥r náֽţan-láֽ⁠kĕ׃s"],[16,18,"שֹׁפְטִ֣ים וְ⁠שֹֽׁטְרִ֗ים תִּֽתֶּן־לְ⁠ךָ֙ בְּ⁠כָל־שְׁעָרֶ֔י⁠ךָ אֲשֶׁ֨ר יְהוָ֧ה אֱלֹהֶ֛י⁠ךָ נֹתֵ֥ן לְ⁠ךָ֖ לִ⁠שְׁבָטֶ֑י⁠ךָ וְ⁠שָׁפְט֥וּ אֶת־הָ⁠עָ֖ם מִשְׁפַּט־צֶֽדֶק׃","şò̌pĕti֣ym wĕ⁠şòֽ̌tĕri֗ym ţiֽ̇ţėn-lĕ⁠ká֙ bĕ̇⁠kál-şĕ̌ʻáre֔y⁠ká ʼàşě֨r yĕhwá֧h ʼèlòhe֛y⁠ká nòţé֥n lĕ⁠ká֖ li⁠şĕ̌báte֑y⁠ká wĕ⁠şá̌pĕt֥ẇ ʼeţ-há⁠ʻá֖m mişĕ̌pȧt-ẕeֽdeq׃"],[16,19,"לֹא־תַטֶּ֣ה מִשְׁפָּ֔ט לֹ֥א תַכִּ֖יר פָּנִ֑ים וְ⁠לֹא־תִקַּ֣ח שֹׁ֔חַד כִּ֣י הַ⁠שֹּׁ֗חַד יְעַוֵּר֙ עֵינֵ֣י חֲכָמִ֔ים וִֽ⁠יסַלֵּ֖ף דִּבְרֵ֥י צַדִּיקִֽם׃","lòʼ-ţatė֣h mişĕ̌pá̇֔t lò֥ʼ ţaki֖̇yr pá̇ni֑ym wĕ⁠lòʼ-ţiqȧ֣ẖ şò̌֔ẖad ki֣̇y ha⁠şò̇̌֗ẖad yĕʻawé̇r֙ ʻéyné֣y ẖàkámi֔ym wiֽ⁠ysalé֖̇p di̇bĕré֥y ẕadi̇yqiֽm׃"],[16,20,"צֶ֥דֶק צֶ֖דֶק תִּרְדֹּ֑ף לְמַ֤עַן תִּֽחְיֶה֙ וְ⁠יָרַשְׁתָּ֣ אֶת־הָ⁠אָ֔רֶץ אֲשֶׁר־יְהוָ֥ה אֱלֹהֶ֖י⁠ךָ נֹתֵ֥ן לָֽ⁠ךְ׃ס","ẕe֥deq ẕe֖deq ţi̇rĕdò֑̇p lĕma֤ʻan ţiֽ̇ẖĕyeh֙ wĕ⁠yáraşĕ̌ţá֣̇ ʼeţ-há⁠ʼá֔reẕ ʼàşěr-yĕhwá֥h ʼèlòhe֖y⁠ká nòţé֥n láֽ⁠kĕ׃s"],[16,21,"לֹֽא־תִטַּ֥ע לְ⁠ךָ֛ אֲשֵׁרָ֖ה כָּל־עֵ֑ץ אֵ֗צֶל מִזְבַּ֛ח יְהוָ֥ה אֱלֹהֶ֖י⁠ךָ אֲשֶׁ֥ר תַּעֲשֶׂה־לָּֽ⁠ךְ׃ס","lòֽʼ-ţitȧ֥ʻ lĕ⁠ká֛ ʼàşé̌rá֖h ká̇l-ʻé֑ẕ ʼé֗ẕel mizĕbȧ֛ẖ yĕhwá֥h ʼèlòhe֖y⁠ká ʼàşě֥r ţȧʻàşêh-láֽ̇⁠kĕ׃s"],[16,22,"וְ⁠לֹֽא־תָקִ֥ים לְ⁠ךָ֖ מַצֵּבָ֑ה אֲשֶׁ֥ר שָׂנֵ֖א יְהוָ֥ה אֱלֹהֶֽי⁠ךָ׃ס","wĕ⁠lòֽʼ-ţáqi֥ym lĕ⁠ká֖ maẕé̇bá֑h ʼàşě֥r şá̂né֖ʼ yĕhwá֥h ʼèlòheֽy⁠ká׃s"],[17,1,"לֹא־תִזְבַּח֩ לַ⁠יהוָ֨ה אֱלֹהֶ֜י⁠ךָ שׁ֣וֹר וָ⁠שֶׂ֗ה אֲשֶׁ֨ר יִהְיֶ֥ה ב⁠וֹ֙ מ֔וּם כֹּ֖ל דָּבָ֣ר רָ֑ע כִּ֧י תוֹעֲבַ֛ת יְהוָ֥ה אֱלֹהֶ֖י⁠ךָ הֽוּא׃ס","lòʼ-ţizĕbȧẖ֩ la⁠yhwá֨h ʼèlòhe֜y⁠ká ş֣̌wòr wá⁠şê֗h ʼàşě֨r yihĕye֥h b⁠wò֙ m֔ẇm kò֖̇l dá̇bá֣r rá֑ʻ ki֧̇y ţwòʻàba֛ţ yĕhwá֥h ʼèlòhe֖y⁠ká hֽẇʼ׃s"],[17,2,"כִּֽי־יִמָּצֵ֤א בְ⁠קִרְבְּ⁠ךָ֙ בְּ⁠אַחַ֣ד שְׁעָרֶ֔י⁠ךָ אֲשֶׁר־יְהוָ֥ה אֱלֹהֶ֖י⁠ךָ נֹתֵ֣ן לָ֑⁠ךְ אִ֣ישׁ אוֹ־אִשָּׁ֗ה אֲשֶׁ֨ר יַעֲשֶׂ֧ה אֶת־הָ⁠רַ֛ע בְּ⁠עֵינֵ֥י יְהוָֽה־אֱלֹהֶ֖י⁠ךָ לַ⁠עֲבֹ֥ר בְּרִיתֽ⁠וֹ׃","kiֽ̇y-yimá̇ẕé֤ʼ bĕ⁠qirĕbĕ̇⁠ká֙ bĕ̇⁠ʼaẖa֣d şĕ̌ʻáre֔y⁠ká ʼàşěr-yĕhwá֥h ʼèlòhe֖y⁠ká nòţé֣n lá֑⁠kĕ ʼi֣yş̌ ʼwò-ʼişá̇̌֗h ʼàşě֨r yaʻàşê֧h ʼeţ-há⁠ra֛ʻ bĕ̇⁠ʻéyné֥y yĕhwáֽh-ʼèlòhe֖y⁠ká la⁠ʻàbò֥r bĕ̇riyţֽ⁠wò׃"],[17,3,"וַ⁠יֵּ֗לֶךְ וַֽ⁠יַּעֲבֹד֙ אֱלֹהִ֣ים אֲחֵרִ֔ים וַ⁠יִּשְׁתַּ֖חוּ לָ⁠הֶ֑ם וְ⁠לַ⁠שֶּׁ֣מֶשׁ ׀ א֣וֹ לַ⁠יָּרֵ֗חַ א֛וֹ לְ⁠כָל־צְבָ֥א הַ⁠שָּׁמַ֖יִם אֲשֶׁ֥ר לֹא־צִוִּֽיתִי׃","wa⁠yé̇֗lekĕ waֽ⁠yȧʻàbòd֙ ʼèlòhi֣ym ʼàẖéri֔ym wa⁠yi̇şĕ̌ţȧ֖ẖẇ lá⁠he֑m wĕ⁠la⁠şė֣̌meş̌ ׀ ʼ֣wò la⁠yá̇ré֗ẖa ʼ֛wò lĕ⁠kál-ẕĕbá֥ʼ ha⁠şá̇̌ma֖yim ʼàşě֥r lòʼ-ẕiwiֽ̇yţiy׃"],[17,4,"וְ⁠הֻֽגַּד־לְ⁠ךָ֖ וְ⁠שָׁמָ֑עְתָּ וְ⁠דָרַשְׁתָּ֣ הֵיטֵ֔ב וְ⁠הִנֵּ֤ה אֱמֶת֙ נָכ֣וֹן הַ⁠דָּבָ֔ר נֶעֶשְׂתָ֛ה הַ⁠תּוֹעֵבָ֥ה הַ⁠זֹּ֖את בְּ⁠יִשְׂרָאֵֽל׃","wĕ⁠huֽgȧd-lĕ⁠ká֖ wĕ⁠şá̌má֑ʻĕţá̇ wĕ⁠dáraşĕ̌ţá֣̇ héyté֔b wĕ⁠hiné֤̇h ʼèmeţ֙ nák֣wòn ha⁠dá̇bá֔r neʻeşĕ̂ţá֛h ha⁠ţ̇wòʻébá֥h ha⁠zò֖̇ʼţ bĕ̇⁠yişĕ̂ráʼéֽl׃"],[17,5,"וְ⁠הֽוֹצֵאתָ֣ אֶת־הָ⁠אִ֣ישׁ הַ⁠ה֡וּא אוֹ֩ אֶת־הָ⁠אִשָּׁ֨ה הַ⁠הִ֜וא אֲשֶׁ֣ר עָ֠שׂוּ אֶת־הַ⁠דָּבָ֨ר הָ⁠רָ֤ע הַ⁠זֶּה֙ אֶל־שְׁעָרֶ֔י⁠ךָ אֶת־הָ⁠אִ֕ישׁ א֖וֹ אֶת־הָ⁠אִשָּׁ֑ה וּ⁠סְקַלְתָּ֥⁠ם בָּ⁠אֲבָנִ֖ים וָ⁠מֵֽתוּ׃","wĕ⁠hֽwòẕéʼţá֣ ʼeţ-há⁠ʼi֣yş̌ ha⁠h֡ẇʼ ʼwò֩ ʼeţ-há⁠ʼişá̇̌֨h ha⁠hi֜wʼ ʼàşě֣r ʻá֠ş̂ẇ ʼeţ-ha⁠dá̇bá֨r há⁠rá֤ʻ ha⁠zėh֙ ʼel-şĕ̌ʻáre֔y⁠ká ʼeţ-há⁠ʼi֕yş̌ ʼ֖wò ʼeţ-há⁠ʼişá֑̇̌h ẇ⁠sĕqalĕţá֥̇⁠m bá̇⁠ʼàbáni֖ym wá⁠méֽţẇ׃"],[17,6,"עַל־פִּ֣י ׀ שְׁנַ֣יִם עֵדִ֗ים א֛וֹ שְׁלֹשָׁ֥ה עֵדִ֖ים יוּמַ֣ת הַ⁠מֵּ֑ת לֹ֣א יוּמַ֔ת עַל־פִּ֖י עֵ֥ד אֶחָֽד׃","ʻal-pi֣̇y ׀ şĕ̌na֣yim ʻédi֗ym ʼ֛wò şĕ̌lòşá֥̌h ʻédi֖ym yẇma֣ţ ha⁠mé֑̇ţ lò֣ʼ yẇma֔ţ ʻal-pi֖̇y ʻé֥d ʼeẖáֽd׃"],[17,7,"יַ֣ד הָ⁠עֵדִ֞ים תִּֽהְיֶה־בּ֤⁠וֹ בָ⁠רִאשֹׁנָה֙ לַ⁠הֲמִית֔⁠וֹ וְ⁠יַ֥ד כָּל־הָ⁠עָ֖ם בָּ⁠אַחֲרֹנָ֑ה וּ⁠בִֽעַרְתָּ֥ הָ⁠רָ֖ע מִ⁠קִּרְבֶּֽ⁠ךָ׃פ","ya֣d há⁠ʻédi֞ym ţiֽ̇hĕyeh-ḃ֤⁠wò bá⁠riʼşò̌náh֙ la⁠hàmiyţ֔⁠wò wĕ⁠ya֥d ká̇l-há⁠ʻá֖m bá̇⁠ʼaẖàròná֑h ẇ⁠biֽʻarĕţá֥̇ há⁠rá֖ʻ mi⁠qi̇rĕbėֽ⁠ká׃p"],[17,8,"כִּ֣י יִפָּלֵא֩ מִמְּ⁠ךָ֨ דָבָ֜ר לַ⁠מִּשְׁפָּ֗ט בֵּֽין־דָּ֨ם ׀ לְ⁠דָ֜ם בֵּֽין־דִּ֣ין לְ⁠דִ֗ין וּ⁠בֵ֥ין נֶ֨גַע֙ לָ⁠נֶ֔גַע דִּבְרֵ֥י רִיבֹ֖ת בִּ⁠שְׁעָרֶ֑י⁠ךָ וְ⁠קַמְתָּ֣ וְ⁠עָלִ֔יתָ אֶל־הַ⁠מָּק֔וֹם אֲשֶׁ֥ר יִבְחַ֛ר יְהוָ֥ה אֱלֹהֶ֖י⁠ךָ בּֽ⁠וֹ׃","ki֣̇y yipá̇léʼ֩ mimĕ̇⁠ká֨ dábá֜r la⁠mi̇şĕ̌pá̇֗t béֽ̇yn-dá̇֨m ׀ lĕ⁠dá֜m béֽ̇yn-di֣̇yn lĕ⁠di֗yn ẇ⁠bé֥yn ne֨gaʻ֙ lá⁠ne֔gaʻ di̇bĕré֥y riybò֖ţ bi̇⁠şĕ̌ʻáre֑y⁠ká wĕ⁠qamĕţá֣̇ wĕ⁠ʻáli֔yţá ʼel-ha⁠má̇q֔wòm ʼàşě֥r yibĕẖa֛r yĕhwá֥h ʼèlòhe֖y⁠ká ḃֽ⁠wò׃"],[17,9,"וּ⁠בָאתָ֗ אֶל־הַ⁠כֹּהֲנִים֙ הַ⁠לְוִיִּ֔ם וְ⁠אֶל־הַ⁠שֹּׁפֵ֔ט אֲשֶׁ֥ר יִהְיֶ֖ה בַּ⁠יָּמִ֣ים הָ⁠הֵ֑ם וְ⁠דָרַשְׁתָּ֙ וְ⁠הִגִּ֣ידוּ לְ⁠ךָ֔ אֵ֖ת דְּבַ֥ר הַ⁠מִּשְׁפָּֽט׃","ẇ⁠báʼţá֗ ʼel-ha⁠kò̇hàniym֙ ha⁠lĕwiyi̇֔m wĕ⁠ʼel-ha⁠şò̇̌pé֔t ʼàşě֥r yihĕye֖h bȧ⁠yá̇mi֣ym há⁠hé֑m wĕ⁠dáraşĕ̌ţá̇֙ wĕ⁠higi֣̇ydẇ lĕ⁠ká֔ ʼé֖ţ dĕ̇ba֥r ha⁠mi̇şĕ̌páֽ̇t׃"],[17,10,"וְ⁠עָשִׂ֗יתָ עַל־פִּ֤י הַ⁠דָּבָר֙ אֲשֶׁ֣ר יַגִּ֣ידֽוּ לְ⁠ךָ֔ מִן־הַ⁠מָּק֣וֹם הַ⁠ה֔וּא אֲשֶׁ֖ר יִבְחַ֣ר יְהוָ֑ה וְ⁠שָׁמַרְתָּ֣ לַ⁠עֲשׂ֔וֹת כְּ⁠כֹ֖ל אֲשֶׁ֥ר יוֹרֽוּ⁠ךָ׃","wĕ⁠ʻáşî֗yţá ʻal-pi֤̇y ha⁠dá̇bár֙ ʼàşě֣r yagi֣̇ydֽẇ lĕ⁠ká֔ min-ha⁠má̇q֣wòm ha⁠h֔ẇʼ ʼàşě֖r yibĕẖa֣r yĕhwá֑h wĕ⁠şá̌marĕţá֣̇ la⁠ʻàş̂֔wòţ kĕ̇⁠kò֖l ʼàşě֥r ywòrֽẇ⁠ká׃"],[17,11,"עַל־פִּ֨י הַ⁠תּוֹרָ֜ה אֲשֶׁ֣ר יוֹר֗וּ⁠ךָ וְ⁠עַל־הַ⁠מִּשְׁפָּ֛ט אֲשֶׁר־יֹאמְר֥וּ לְ⁠ךָ֖ תַּעֲשֶׂ֑ה לֹ֣א תָס֗וּר מִן־הַ⁠דָּבָ֛ר אֲשֶׁר־יַגִּ֥ידֽוּ לְ⁠ךָ֖ יָמִ֥ין וּ⁠שְׂמֹֽאל׃","ʻal-pi̇֨y ha⁠ţ̇wòrá֜h ʼàşě֣r ywòr֗ẇ⁠ká wĕ⁠ʻal-ha⁠mi̇şĕ̌pá֛̇t ʼàşěr-yòʼmĕr֥ẇ lĕ⁠ká֖ ţȧʻàşê֑h lò֣ʼ ţás֗ẇr min-ha⁠dá̇bá֛r ʼàşěr-yagi֥̇ydֽẇ lĕ⁠ká֖ yámi֥yn ẇ⁠şĕ̂mòֽʼl׃"],[17,12,"וְ⁠הָ⁠אִ֞ישׁ אֲשֶׁר־יַעֲשֶׂ֣ה בְ⁠זָד֗וֹן לְ⁠בִלְתִּ֨י שְׁמֹ֤עַ אֶל־הַ⁠כֹּהֵן֙ הָ⁠עֹמֵ֞ד לְ⁠שָׁ֤רֶת שָׁם֙ אֶת־יְהוָ֣ה אֱלֹהֶ֔י⁠ךָ א֖וֹ אֶל־הַ⁠שֹּׁפֵ֑ט וּ⁠מֵת֙ הָ⁠אִ֣ישׁ הַ⁠ה֔וּא וּ⁠בִֽעַרְתָּ֥ הָ⁠רָ֖ע מִ⁠יִּשְׂרָאֵֽל׃","wĕ⁠há⁠ʼi֞yş̌ ʼàşěr-yaʻàşê֣h bĕ⁠zád֗wòn lĕ⁠bilĕţi̇֨y şĕ̌mò֤ʻa ʼel-ha⁠kò̇hén֙ há⁠ʻòmé֞d lĕ⁠şá֤̌reţ şá̌m֙ ʼeţ-yĕhwá֣h ʼèlòhe֔y⁠ká ʼ֖wò ʼel-ha⁠şò̇̌pé֑t ẇ⁠méţ֙ há⁠ʼi֣yş̌ ha⁠h֔ẇʼ ẇ⁠biֽʻarĕţá֥̇ há⁠rá֖ʻ mi⁠yi̇şĕ̂ráʼéֽl׃"],[17,13,"וְ⁠כָל־הָ⁠עָ֖ם יִשְׁמְע֣וּ וְ⁠יִרָ֑אוּ וְ⁠לֹ֥א יְזִיד֖וּ⁠ן עֽוֹד׃ס","wĕ⁠kál-há⁠ʻá֖m yişĕ̌mĕʻ֣ẇ wĕ⁠yirá֑ʼẇ wĕ⁠lò֥ʼ yĕziyd֖ẇ⁠n ʻֽwòd׃s"],[17,14,"כִּֽי־תָבֹ֣א אֶל־הָ⁠אָ֗רֶץ אֲשֶׁ֨ר יְהוָ֤ה אֱלֹהֶ֨י⁠ךָ֙ נֹתֵ֣ן לָ֔⁠ךְ וִֽ⁠ירִשְׁתָּ֖⁠הּ וְ⁠יָשַׁ֣בְתָּה בָּ֑⁠הּ וְ⁠אָמַרְתָּ֗ אָשִׂ֤ימָה עָלַ⁠י֙ מֶ֔לֶךְ כְּ⁠כָל־הַ⁠גּוֹיִ֖ם אֲשֶׁ֥ר סְבִיבֹתָֽ⁠י׃","kiֽ̇y-ţábò֣ʼ ʼel-há⁠ʼá֗reẕ ʼàşě֨r yĕhwá֤h ʼèlòhe֨y⁠ká֙ nòţé֣n lá֔⁠kĕ wiֽ⁠yrişĕ̌ţá֖̇⁠ḣ wĕ⁠yáşǎ֣bĕţá̇h bá֑̇⁠ḣ wĕ⁠ʼámarĕţá̇֗ ʼáşî֤ymáh ʻála⁠y֙ me֔lekĕ kĕ̇⁠kál-ha⁠ġwòyi֖m ʼàşě֥r sĕbiybòţáֽ⁠y׃"],[17,15,"שׂ֣וֹם תָּשִׂ֤ים עָלֶ֨י⁠ךָ֙ מֶ֔לֶךְ אֲשֶׁ֥ר יִבְחַ֛ר יְהוָ֥ה אֱלֹהֶ֖י⁠ךָ בּ֑⁠וֹ מִ⁠קֶּ֣רֶב אַחֶ֗י⁠ךָ תָּשִׂ֤ים עָלֶ֨י⁠ךָ֙ מֶ֔לֶךְ לֹ֣א תוּכַ֗ל לָ⁠תֵ֤ת עָלֶ֨י⁠ךָ֙ אִ֣ישׁ נָכְרִ֔י אֲשֶׁ֥ר לֹֽא־אָחִ֖י⁠ךָ הֽוּא׃","ş֣̂wòm ţá̇şî֤ym ʻále֨y⁠ká֙ me֔lekĕ ʼàşě֥r yibĕẖa֛r yĕhwá֥h ʼèlòhe֖y⁠ká ḃ֑⁠wò mi⁠qė֣reb ʼaẖe֗y⁠ká ţá̇şî֤ym ʻále֨y⁠ká֙ me֔lekĕ lò֣ʼ ţẇka֗l lá⁠ţé֤ţ ʻále֨y⁠ká֙ ʼi֣yş̌ nákĕri֔y ʼàşě֥r lòֽʼ-ʼáẖi֖y⁠ká hֽẇʼ׃"],[17,16,"רַק֮ לֹא־יַרְבֶּה־לּ֣⁠וֹ סוּסִים֒ וְ⁠לֹֽא־יָשִׁ֤יב אֶת־הָ⁠עָם֙ מִצְרַ֔יְמָ⁠ה לְמַ֖עַן הַרְבּ֣וֹת ס֑וּס וַֽ⁠יהוָה֙ אָמַ֣ר לָ⁠כֶ֔ם לֹ֣א תֹסִפ֗וּ⁠ן לָ⁠שׁ֛וּב בַּ⁠דֶּ֥רֶךְ הַ⁠זֶּ֖ה עֽוֹד׃","raq֮ lòʼ-yarĕbėh-l֣̇⁠wò sẇsiym֒ wĕ⁠lòֽʼ-yáşǐ֤yb ʼeţ-há⁠ʻám֙ miẕĕra֔yĕmá⁠h lĕma֖ʻan harĕḃ֣wòţ s֑ẇs waֽ⁠yhwáh֙ ʼáma֣r lá⁠ke֔m lò֣ʼ ţòsip֗ẇ⁠n lá⁠ş֛̌ẇb bȧ⁠dė֥rekĕ ha⁠zė֖h ʻֽwòd׃"],[17,17,"וְ⁠לֹ֤א יַרְבֶּה־לּ⁠וֹ֙ נָשִׁ֔ים וְ⁠לֹ֥א יָס֖וּר לְבָב֑⁠וֹ וְ⁠כֶ֣סֶף וְ⁠זָהָ֔ב לֹ֥א יַרְבֶּה־לּ֖⁠וֹ מְאֹֽד׃","wĕ⁠lò֤ʼ yarĕbėh-l̇⁠wò֙ náşǐ֔ym wĕ⁠lò֥ʼ yás֖ẇr lĕbáb֑⁠wò wĕ⁠ke֣sep wĕ⁠záhá֔b lò֥ʼ yarĕbėh-l֖̇⁠wò mĕʼòֽd׃"],[17,18,"וְ⁠הָיָ֣ה כְ⁠שִׁבְתּ֔⁠וֹ עַ֖ל כִּסֵּ֣א מַמְלַכְתּ֑⁠וֹ וְ⁠כָ֨תַב ל֜⁠וֹ אֶת־מִשְׁנֵ֨ה הַ⁠תּוֹרָ֤ה הַ⁠זֹּאת֙ עַל־סֵ֔פֶר מִ⁠לִּ⁠פְנֵ֥י הַ⁠כֹּהֲנִ֖ים הַ⁠לְוִיִּֽם׃","wĕ⁠háyá֣h kĕ⁠şǐbĕţ̇֔⁠wò ʻa֖l ki̇sé֣̇ʼ mamĕlakĕţ֑̇⁠wò wĕ⁠ká֨ţab l֜⁠wò ʼeţ-mişĕ̌né֨h ha⁠ţ̇wòrá֤h ha⁠zò̇ʼţ֙ ʻal-sé֔per mi⁠li̇⁠pĕné֥y ha⁠kò̇hàni֖ym ha⁠lĕwiyiֽ̇m׃"],[17,19,"וְ⁠הָיְתָ֣ה עִמּ֔⁠וֹ וְ⁠קָ֥רָא ב֖⁠וֹ כָּל־יְמֵ֣י חַיָּ֑י⁠ו לְמַ֣עַן יִלְמַ֗ד לְ⁠יִרְאָה֙ אֶת־יְהוָ֣ה אֱלֹהָ֔י⁠ו לִ֠⁠שְׁמֹר אֶֽת־כָּל־דִּבְרֵ֞י הַ⁠תּוֹרָ֥ה הַ⁠זֹּ֛את וְ⁠אֶת־הַ⁠חֻקִּ֥ים הָ⁠אֵ֖לֶּה לַ⁠עֲשֹׂתָֽ⁠ם׃","wĕ⁠háyĕţá֣h ʻiṁ֔⁠wò wĕ⁠qá֥ráʼ b֖⁠wò ká̇l-yĕmé֣y ẖayá֑̇y⁠w lĕma֣ʻan yilĕma֗d lĕ⁠yirĕʼáh֙ ʼeţ-yĕhwá֣h ʼèlòhá֔y⁠w li֠⁠şĕ̌mòr ʼeֽţ-ká̇l-di̇bĕré֞y ha⁠ţ̇wòrá֥h ha⁠zò֛̇ʼţ wĕ⁠ʼeţ-ha⁠ẖuqi֥̇ym há⁠ʼé֖lėh la⁠ʻàşò̂ţáֽ⁠m׃"],[17,20,"לְ⁠בִלְתִּ֤י רוּם־לְבָב⁠וֹ֙ מֵֽ⁠אֶחָ֔י⁠ו וּ⁠לְ⁠בִלְתִּ֛י ס֥וּר מִן־הַ⁠מִּצְוָ֖ה יָמִ֣ין וּ⁠שְׂמֹ֑אול לְמַעַן֩ יַאֲרִ֨יךְ יָמִ֧ים עַל־מַמְלַכְתּ֛⁠וֹ ה֥וּא וּ⁠בָנָ֖י⁠ו בְּ⁠קֶ֥רֶב יִשְׂרָאֵֽל׃ס","lĕ⁠bilĕţi֤̇y rẇm-lĕbáb⁠wò֙ méֽ⁠ʼeẖá֔y⁠w ẇ⁠lĕ⁠bilĕţi֛̇y s֥ẇr min-ha⁠mi̇ẕĕwá֖h yámi֣yn ẇ⁠şĕ̂mò֑ʼwl lĕmaʻan֩ yaʼàri֨ykĕ yámi֧ym ʻal-mamĕlakĕţ֛̇⁠wò h֥ẇʼ ẇ⁠báná֖y⁠w bĕ̇⁠qe֥reb yişĕ̂ráʼéֽl׃s"],[18,1,"לֹֽא־יִ֠הְיֶה לַ⁠כֹּהֲנִ֨ים הַ⁠לְוִיִּ֜ם כָּל־שֵׁ֧בֶט לֵוִ֛י חֵ֥לֶק וְ⁠נַחֲלָ֖ה עִם־יִשְׂרָאֵ֑ל אִשֵּׁ֧י יְהוָ֛ה וְ⁠נַחֲלָת֖⁠וֹ יֹאכֵלֽוּ⁠ן׃","lòֽʼ-yi֠hĕyeh la⁠kò̇hàni֨ym ha⁠lĕwiyi̇֜m ká̇l-şé֧̌bet léwi֛y ẖé֥leq wĕ⁠naẖàlá֖h ʻim-yişĕ̂ráʼé֑l ʼişé֧̇̌y yĕhwá֛h wĕ⁠naẖàláţ֖⁠wò yòʼkélֽẇ⁠n׃"],[18,2,"וְ⁠נַחֲלָ֥ה לֹא־יִֽהְיֶה־לּ֖⁠וֹ בְּ⁠קֶ֣רֶב אֶחָ֑י⁠ו יְהוָה֙ ה֣וּא נַחֲלָת֔⁠וֹ כַּ⁠אֲשֶׁ֖ר דִּבֶּר־לֽ⁠וֹ׃ס","wĕ⁠naẖàlá֥h lòʼ-yiֽhĕyeh-l֖̇⁠wò bĕ̇⁠qe֣reb ʼeẖá֑y⁠w yĕhwáh֙ h֣ẇʼ naẖàláţ֔⁠wò kȧ⁠ʼàşě֖r di̇bėr-lֽ⁠wò׃s"],[18,3,"וְ⁠זֶ֡ה יִהְיֶה֩ מִשְׁפַּ֨ט הַ⁠כֹּהֲנִ֜ים מֵ⁠אֵ֣ת הָ⁠עָ֗ם מֵ⁠אֵ֛ת זֹבְחֵ֥י הַ⁠זֶּ֖בַח אִם־שׁ֣וֹר אִם־שֶׂ֑ה וְ⁠נָתַן֙ לַ⁠כֹּהֵ֔ן הַ⁠זְּרֹ֥עַ וְ⁠הַ⁠לְּחָיַ֖יִם וְ⁠הַ⁠קֵּבָֽה׃","wĕ⁠ze֡h yihĕyeh֩ mişĕ̌pȧ֨t ha⁠kò̇hàni֜ym mé⁠ʼé֣ţ há⁠ʻá֗m mé⁠ʼé֛ţ zòbĕẖé֥y ha⁠zė֖baẖ ʼim-ş֣̌wòr ʼim-şê֑h wĕ⁠náţan֙ la⁠kò̇hé֔n ha⁠zĕ̇rò֥ʻa wĕ⁠ha⁠lĕ̇ẖáya֖yim wĕ⁠ha⁠qé̇báֽh׃"],[18,4,"רֵאשִׁ֨ית דְּגָֽנְ⁠ךָ֜ תִּֽירֹשְׁ⁠ךָ֣ וְ⁠יִצְהָרֶ֗⁠ךָ וְ⁠רֵאשִׁ֛ית גֵּ֥ז צֹאנְ⁠ךָ֖ תִּתֶּן־לּֽ⁠וֹ׃","réʼşǐ֨yţ dĕ̇gáֽnĕ⁠ká֜ ţiֽ̇yròşĕ̌⁠ká֣ wĕ⁠yiẕĕháre֗⁠ká wĕ⁠réʼşǐ֛yţ gé֥̇z ẕòʼnĕ⁠ká֖ ţi̇ţėn-lֽ̇⁠wò׃"],[18,5,"כִּ֣י ב֗⁠וֹ בָּחַ֛ר יְהוָ֥ה אֱלֹהֶ֖י⁠ךָ מִ⁠כָּל־שְׁבָטֶ֑י⁠ךָ לַ⁠עֲמֹ֨ד לְ⁠שָׁרֵ֧ת בְּ⁠שֵׁם־יְהוָ֛ה ה֥וּא וּ⁠בָנָ֖י⁠ו כָּל־הַ⁠יָּמִֽים׃ס","ki֣̇y b֗⁠wò bá̇ẖa֛r yĕhwá֥h ʼèlòhe֖y⁠ká mi⁠ká̇l-şĕ̌báte֑y⁠ká la⁠ʻàmò֨d lĕ⁠şá̌ré֧ţ bĕ̇⁠şé̌m-yĕhwá֛h h֥ẇʼ ẇ⁠báná֖y⁠w ká̇l-ha⁠yá̇miֽym׃s"],[18,6,"וְ⁠כִֽי־יָבֹ֨א הַ⁠לֵּוִ֜י מֵ⁠אַחַ֤ד שְׁעָרֶ֨י⁠ךָ֙ מִ⁠כָּל־יִשְׂרָאֵ֔ל אֲשֶׁר־ה֖וּא גָּ֣ר שָׁ֑ם וּ⁠בָא֙ בְּ⁠כָל־אַוַּ֣ת נַפְשׁ֔⁠וֹ אֶל־הַ⁠מָּק֖וֹם אֲשֶׁר־יִבְחַ֥ר יְהוָֽה׃","wĕ⁠kiֽy-yábò֨ʼ ha⁠lé̇wi֜y mé⁠ʼaẖa֤d şĕ̌ʻáre֨y⁠ká֙ mi⁠ká̇l-yişĕ̂ráʼé֔l ʼàşěr-h֖ẇʼ gá֣̇r şá֑̌m ẇ⁠báʼ֙ bĕ̇⁠kál-ʼawȧ֣ţ napĕş̌֔⁠wò ʼel-ha⁠má̇q֖wòm ʼàşěr-yibĕẖa֥r yĕhwáֽh׃"],[18,7,"וְ⁠שֵׁרֵ֕ת בְּ⁠שֵׁ֖ם יְהוָ֣ה אֱלֹהָ֑י⁠ו כְּ⁠כָל־אֶחָי⁠ו֙ הַ⁠לְוִיִּ֔ם הָ⁠עֹמְדִ֥ים שָׁ֖ם לִ⁠פְנֵ֥י יְהוָֽה׃","wĕ⁠şé̌ré֕ţ bĕ̇⁠şé֖̌m yĕhwá֣h ʼèlòhá֑y⁠w kĕ̇⁠kál-ʼeẖáy⁠w֙ ha⁠lĕwiyi̇֔m há⁠ʻòmĕdi֥ym şá֖̌m li⁠pĕné֥y yĕhwáֽh׃"],[18,8,"חֵ֥לֶק כְּ⁠חֵ֖לֶק יֹאכֵ֑לוּ לְ⁠בַ֥ד מִמְכָּרָ֖י⁠ו עַל־הָ⁠אָבֽוֹת׃ס","ẖé֥leq kĕ̇⁠ẖé֖leq yòʼké֑lẇ lĕ⁠ba֥d mimĕká̇rá֖y⁠w ʻal-há⁠ʼábֽwòţ׃s"],[18,9,"כִּ֤י אַתָּה֙ בָּ֣א אֶל־הָ⁠אָ֔רֶץ אֲשֶׁר־יְהוָ֥ה אֱלֹהֶ֖י⁠ךָ נֹתֵ֣ן לָ֑⁠ךְ לֹֽא־תִלְמַ֣ד לַ⁠עֲשׂ֔וֹת כְּ⁠תוֹעֲבֹ֖ת הַ⁠גּוֹיִ֥ם הָ⁠הֵֽם׃","ki֤̇y ʼaţá̇h֙ bá֣̇ʼ ʼel-há⁠ʼá֔reẕ ʼàşěr-yĕhwá֥h ʼèlòhe֖y⁠ká nòţé֣n lá֑⁠kĕ lòֽʼ-ţilĕma֣d la⁠ʻàş̂֔wòţ kĕ̇⁠ţwòʻàbò֖ţ ha⁠ġwòyi֥m há⁠héֽm׃"],[18,10,"לֹֽא־יִמָּצֵ֣א בְ⁠ךָ֔ מַעֲבִ֥יר בְּנֽ⁠וֹ־וּ⁠בִתּ֖⁠וֹ בָּ⁠אֵ֑שׁ קֹסֵ֣ם קְסָמִ֔ים מְעוֹנֵ֥ן וּ⁠מְנַחֵ֖שׁ וּ⁠מְכַשֵּֽׁף׃","lòֽʼ-yimá̇ẕé֣ʼ bĕ⁠ká֔ maʻàbi֥yr bĕ̇nֽ⁠wò-ẇ⁠biţ֖̇⁠wò bá̇⁠ʼé֑ş̌ qòsé֣m qĕsámi֔ym mĕʻwòné֥n ẇ⁠mĕnaẖé֖ş̌ ẇ⁠mĕkaşéֽ̇̌p׃"],[18,11,"וְ⁠חֹבֵ֖ר חָ֑בֶר וְ⁠שֹׁאֵ֥ל אוֹב֙ וְ⁠יִדְּעֹנִ֔י וְ⁠דֹרֵ֖שׁ אֶל־הַ⁠מֵּתִֽים׃","wĕ⁠ẖòbé֖r ẖá֑ber wĕ⁠şò̌ʼé֥l ʼwòb֙ wĕ⁠yidĕ̇ʻòni֔y wĕ⁠dòré֖ş̌ ʼel-ha⁠mé̇ţiֽym׃"],[18,12,"כִּֽי־תוֹעֲבַ֥ת יְהוָ֖ה כָּל־עֹ֣שֵׂה אֵ֑לֶּה וּ⁠בִ⁠גְלַל֙ הַ⁠תּוֹעֵבֹ֣ת הָ⁠אֵ֔לֶּה יְהוָ֣ה אֱלֹהֶ֔י⁠ךָ מוֹרִ֥ישׁ אוֹתָ֖⁠ם מִ⁠פָּנֶֽי⁠ךָ׃","kiֽ̇y-ţwòʻàba֥ţ yĕhwá֖h ká̇l-ʻò֣şé̂h ʼé֑lėh ẇ⁠bi⁠gĕlal֙ ha⁠ţ̇wòʻébò֣ţ há⁠ʼé֔lėh yĕhwá֣h ʼèlòhe֔y⁠ká mwòri֥yş̌ ʼwòţá֖⁠m mi⁠pá̇neֽy⁠ká׃"],[18,13,"תָּמִ֣ים תִּֽהְיֶ֔ה עִ֖ם יְהוָ֥ה אֱלֹהֶֽי⁠ךָ׃ס","ţá̇mi֣ym ţiֽ̇hĕye֔h ʻi֖m yĕhwá֥h ʼèlòheֽy⁠ká׃s"],[18,14,"כִּ֣י ׀ הַ⁠גּוֹיִ֣ם הָ⁠אֵ֗לֶּה אֲשֶׁ֤ר אַתָּה֙ יוֹרֵ֣שׁ אוֹתָ֔⁠ם אֶל־מְעֹנְנִ֥ים וְ⁠אֶל־קֹסְמִ֖ים יִשְׁמָ֑עוּ וְ⁠אַתָּ֕ה לֹ֣א כֵ֔ן נָ֛תַן לְ⁠ךָ֖ יְהוָ֥ה אֱלֹהֶֽי⁠ךָ׃","ki֣̇y ׀ ha⁠ġwòyi֣m há⁠ʼé֗lėh ʼàşě֤r ʼaţá̇h֙ ywòré֣ş̌ ʼwòţá֔⁠m ʼel-mĕʻònĕni֥ym wĕ⁠ʼel-qòsĕmi֖ym yişĕ̌má֑ʻẇ wĕ⁠ʼaţá̇֕h lò֣ʼ ké֔n ná֛ţan lĕ⁠ká֖ yĕhwá֥h ʼèlòheֽy⁠ká׃"],[18,15,"נָבִ֨יא מִ⁠קִּרְבְּ⁠ךָ֤ מֵ⁠אַחֶ֨י⁠ךָ֙ כָּמֹ֔⁠נִי יָקִ֥ים לְ⁠ךָ֖ יְהוָ֣ה אֱלֹהֶ֑י⁠ךָ אֵלָ֖י⁠ו תִּשְׁמָעֽוּ⁠ן׃","nábi֨yʼ mi⁠qi̇rĕbĕ̇⁠ká֤ mé⁠ʼaẖe֨y⁠ká֙ ká̇mò֔⁠niy yáqi֥ym lĕ⁠ká֖ yĕhwá֣h ʼèlòhe֑y⁠ká ʼélá֖y⁠w ţi̇şĕ̌máʻֽẇ⁠n׃"],[18,16,"כְּ⁠כֹ֨ל אֲשֶׁר־שָׁאַ֜לְתָּ מֵ⁠עִ֨ם יְהוָ֤ה אֱלֹהֶ֨י⁠ךָ֙ בְּ⁠חֹרֵ֔ב בְּ⁠י֥וֹם הַ⁠קָּהָ֖ל לֵ⁠אמֹ֑ר לֹ֣א אֹסֵ֗ף לִ⁠שְׁמֹ֨עַ֙ אֶת־קוֹל֙ יְהוָ֣ה אֱלֹהָ֔⁠י וְ⁠אֶת־הָ⁠אֵ֨שׁ הַ⁠גְּדֹלָ֥ה הַ⁠זֹּ֛את לֹֽא־אֶרְאֶ֥ה ע֖וֹד וְ⁠לֹ֥א אָמֽוּת׃","kĕ̇⁠kò֨l ʼàşěr-şá̌ʼa֜lĕţá̇ mé⁠ʻi֨m yĕhwá֤h ʼèlòhe֨y⁠ká֙ bĕ̇⁠ẖòré֔b bĕ̇⁠y֥wòm ha⁠qá̇há֖l lé⁠ʼmò֑r lò֣ʼ ʼòsé֗p li⁠şĕ̌mò֨ʻa֙ ʼeţ-qwòl֙ yĕhwá֣h ʼèlòhá֔⁠y wĕ⁠ʼeţ-há⁠ʼé֨ş̌ ha⁠gĕ̇dòlá֥h ha⁠zò֛̇ʼţ lòֽʼ-ʼerĕʼe֥h ʻ֖wòd wĕ⁠lò֥ʼ ʼámֽẇţ׃"],[18,17,"וַ⁠יֹּ֥אמֶר יְהוָ֖ה אֵלָ֑⁠י הֵיטִ֖יבוּ אֲשֶׁ֥ר דִּבֵּֽרוּ׃","wa⁠yò֥̇ʼmer yĕhwá֖h ʼélá֑⁠y héyti֖ybẇ ʼàşě֥r di̇béֽ̇rẇ׃"],[18,18,"נָבִ֨יא אָקִ֥ים לָ⁠הֶ֛ם מִ⁠קֶּ֥רֶב אֲחֵי⁠הֶ֖ם כָּמ֑וֹ⁠ךָ וְ⁠נָתַתִּ֤י דְבָרַ⁠י֙ בְּ⁠פִ֔י⁠ו וְ⁠דִבֶּ֣ר אֲלֵי⁠הֶ֔ם אֵ֖ת כָּל־אֲשֶׁ֥ר אֲצַוֶּֽ⁠נּוּ׃","nábi֨yʼ ʼáqi֥ym lá⁠he֛m mi⁠qė֥reb ʼàẖéy⁠he֖m ká̇m֑wò⁠ká wĕ⁠náţaţi֤̇y dĕbára⁠y֙ bĕ̇⁠pi֔y⁠w wĕ⁠dibė֣r ʼàléy⁠he֔m ʼé֖ţ ká̇l-ʼàşě֥r ʼàẕawėֽ⁠ṅẇ׃"],[18,19,"וְ⁠הָיָ֗ה הָ⁠אִישׁ֙ אֲשֶׁ֤ר לֹֽא־יִשְׁמַע֙ אֶל־דְּבָרַ֔⁠י אֲשֶׁ֥ר יְדַבֵּ֖ר בִּ⁠שְׁמִ֑⁠י אָנֹכִ֖י אֶדְרֹ֥שׁ מֵ⁠עִמּֽ⁠וֹ׃","wĕ⁠háyá֗h há⁠ʼiyş̌֙ ʼàşě֤r lòֽʼ-yişĕ̌maʻ֙ ʼel-dĕ̇bára֔⁠y ʼàşě֥r yĕdabé֖̇r bi̇⁠şĕ̌mi֑⁠y ʼánòki֖y ʼedĕrò֥ş̌ mé⁠ʻiṁֽ⁠wò׃"],[18,20,"אַ֣ךְ הַ⁠נָּבִ֡יא אֲשֶׁ֣ר יָזִיד֩ לְ⁠דַבֵּ֨ר דָּבָ֜ר בִּ⁠שְׁמִ֗⁠י אֵ֣ת אֲשֶׁ֤ר לֹֽא־צִוִּיתִי⁠ו֙ לְ⁠דַבֵּ֔ר וַ⁠אֲשֶׁ֣ר יְדַבֵּ֔ר בְּ⁠שֵׁ֖ם אֱלֹהִ֣ים אֲחֵרִ֑ים וּ⁠מֵ֖ת הַ⁠נָּבִ֥יא הַ⁠הֽוּא׃","ʼa֣kĕ ha⁠ná̇bi֡yʼ ʼàşě֣r yáziyd֩ lĕ⁠dabé̇֨r dá̇bá֜r bi̇⁠şĕ̌mi֗⁠y ʼé֣ţ ʼàşě֤r lòֽʼ-ẕiwi̇yţiy⁠w֙ lĕ⁠dabé̇֔r wa⁠ʼàşě֣r yĕdabé̇֔r bĕ̇⁠şé֖̌m ʼèlòhi֣ym ʼàẖéri֑ym ẇ⁠mé֖ţ ha⁠ná̇bi֥yʼ ha⁠hֽẇʼ׃"],[18,21,"וְ⁠כִ֥י תֹאמַ֖ר בִּ⁠לְבָבֶ֑⁠ךָ אֵיכָה֙ נֵדַ֣ע אֶת־הַ⁠דָּבָ֔ר אֲשֶׁ֥ר לֹא־דִבְּר֖⁠וֹ יְהוָֽה׃","wĕ⁠ki֥y ţòʼma֖r bi̇⁠lĕbábe֑⁠ká ʼéykáh֙ néda֣ʻ ʼeţ-ha⁠dá̇bá֔r ʼàşě֥r lòʼ-dibĕ̇r֖⁠wò yĕhwáֽh׃"],[18,22,"אֲשֶׁר֩ יְדַבֵּ֨ר הַ⁠נָּבִ֜יא בְּ⁠שֵׁ֣ם יְהוָ֗ה וְ⁠לֹֽא־יִהְיֶ֤ה הַ⁠דָּבָר֙ וְ⁠לֹ֣א יָב֔וֹא ה֣וּא הַ⁠דָּבָ֔ר אֲשֶׁ֥ר לֹא־דִבְּר֖⁠וֹ יְהוָ֑ה בְּ⁠זָדוֹן֙ דִּבְּר֣⁠וֹ הַ⁠נָּבִ֔יא לֹ֥א תָג֖וּר מִמֶּֽ⁠נּוּ׃ס","ʼàşěr֩ yĕdabé̇֨r ha⁠ná̇bi֜yʼ bĕ̇⁠şé֣̌m yĕhwá֗h wĕ⁠lòֽʼ-yihĕye֤h ha⁠dá̇bár֙ wĕ⁠lò֣ʼ yáb֔wòʼ h֣ẇʼ ha⁠dá̇bá֔r ʼàşě֥r lòʼ-dibĕ̇r֖⁠wò yĕhwá֑h bĕ̇⁠zádwòn֙ di̇bĕ̇r֣⁠wò ha⁠ná̇bi֔yʼ lò֥ʼ ţág֖ẇr mimėֽ⁠ṅẇ׃s"],[19,1,"כִּֽי־יַכְרִ֞ית יְהוָ֤ה אֱלֹהֶ֨י⁠ךָ֙ אֶת־הַ⁠גּוֹיִ֔ם אֲשֶׁר֙ יְהוָ֣ה אֱלֹהֶ֔י⁠ךָ נֹתֵ֥ן לְ⁠ךָ֖ אֶת־אַרְצָ֑⁠ם וִֽ⁠ירִשְׁתָּ֕⁠ם וְ⁠יָשַׁבְתָּ֥ בְ⁠עָרֵי⁠הֶ֖ם וּ⁠בְ⁠בָתֵּי⁠הֶֽם׃","kiֽ̇y-yakĕri֞yţ yĕhwá֤h ʼèlòhe֨y⁠ká֙ ʼeţ-ha⁠ġwòyi֔m ʼàşěr֙ yĕhwá֣h ʼèlòhe֔y⁠ká nòţé֥n lĕ⁠ká֖ ʼeţ-ʼarĕẕá֑⁠m wiֽ⁠yrişĕ̌ţá̇֕⁠m wĕ⁠yáşǎbĕţá֥̇ bĕ⁠ʻáréy⁠he֖m ẇ⁠bĕ⁠báţé̇y⁠heֽm׃"],[19,2,"שָׁל֥וֹשׁ עָרִ֖ים תַּבְדִּ֣יל לָ֑⁠ךְ בְּ⁠ת֣וֹךְ אַרְצְ⁠ךָ֔ אֲשֶׁר֙ יְהוָ֣ה אֱלֹהֶ֔י⁠ךָ נֹתֵ֥ן לְ⁠ךָ֖ לְ⁠רִשְׁתָּֽ⁠הּ׃","şá̌l֥wòş̌ ʻári֖ym ţȧbĕdi֣̇yl lá֑⁠kĕ bĕ̇⁠ţ֣wòkĕ ʼarĕẕĕ⁠ká֔ ʼàşěr֙ yĕhwá֣h ʼèlòhe֔y⁠ká nòţé֥n lĕ⁠ká֖ lĕ⁠rişĕ̌ţáֽ̇⁠ḣ׃"],[19,3,"תָּכִ֣ין לְ⁠ךָ֮ הַ⁠דֶּרֶךְ֒ וְ⁠שִׁלַּשְׁתָּ֙ אֶת־גְּב֣וּל אַרְצְ⁠ךָ֔ אֲשֶׁ֥ר יַנְחִֽילְ⁠ךָ֖ יְהוָ֣ה אֱלֹהֶ֑י⁠ךָ וְ⁠הָיָ֕ה לָ⁠נ֥וּס שָׁ֖מָּ⁠ה כָּל־רֹצֵֽחַ׃","ţá̇ki֣yn lĕ⁠ká֮ ha⁠dėrekĕ֒ wĕ⁠şǐlȧşĕ̌ţá̇֙ ʼeţ-gĕ̇b֣ẇl ʼarĕẕĕ⁠ká֔ ʼàşě֥r yanĕẖiֽylĕ⁠ká֖ yĕhwá֣h ʼèlòhe֑y⁠ká wĕ⁠háyá֕h lá⁠n֥ẇs şá֖̌má̇⁠h ká̇l-ròẕéֽẖa׃"],[19,4,"וְ⁠זֶה֙ דְּבַ֣ר הָ⁠רֹצֵ֔חַ אֲשֶׁר־יָנ֥וּס שָׁ֖מָּ⁠ה וָ⁠חָ֑י אֲשֶׁ֨ר יַכֶּ֤ה אֶת־רֵעֵ֨⁠הוּ֙ בִּ⁠בְלִי־דַ֔עַת וְ⁠ה֛וּא לֹא־שֹׂנֵ֥א ל֖⁠וֹ מִ⁠תְּמֹ֥ל שִׁלְשֹֽׁם׃","wĕ⁠zeh֙ dĕ̇ba֣r há⁠ròẕé֔ẖa ʼàşěr-yán֥ẇs şá֖̌má̇⁠h wá⁠ẖá֑y ʼàşě֨r yakė֤h ʼeţ-réʻé֨⁠hẇ֙ bi̇⁠bĕliy-da֔ʻaţ wĕ⁠h֛ẇʼ lòʼ-şò̂né֥ʼ l֖⁠wò mi⁠ţĕ̇mò֥l şǐlĕşòֽ̌m׃"],[19,5,"וַ⁠אֲשֶׁר֩ יָבֹ֨א אֶת־רֵעֵ֥⁠הוּ בַ⁠יַּעַר֮ לַ⁠חְטֹ֣ב עֵצִים֒ וְ⁠נִדְּחָ֨ה יָד֤⁠וֹ בַ⁠גַּרְזֶן֙ לִ⁠כְרֹ֣ת הָ⁠עֵ֔ץ וְ⁠נָשַׁ֤ל הַ⁠בַּרְזֶל֙ מִן־הָ⁠עֵ֔ץ וּ⁠מָצָ֥א אֶת־רֵעֵ֖⁠הוּ וָ⁠מֵ֑ת ה֗וּא יָנ֛וּס אֶל־אַחַ֥ת הֶ⁠עָרִים־הָ⁠אֵ֖לֶּה וָ⁠חָֽי׃","wa⁠ʼàşěr֩ yábò֨ʼ ʼeţ-réʻé֥⁠hẇ ba⁠yȧʻar֮ la⁠ẖĕtò֣b ʻéẕiym֒ wĕ⁠nidĕ̇ẖá֨h yád֤⁠wò ba⁠gȧrĕzen֙ li⁠kĕrò֣ţ há⁠ʻé֔ẕ wĕ⁠náşǎ֤l ha⁠bȧrĕzel֙ min-há⁠ʻé֔ẕ ẇ⁠máẕá֥ʼ ʼeţ-réʻé֖⁠hẇ wá⁠mé֑ţ h֗ẇʼ yán֛ẇs ʼel-ʼaẖa֥ţ he⁠ʻáriym-há⁠ʼé֖lėh wá⁠ẖáֽy׃"],[19,6,"פֶּן־יִרְדֹּף֩ גֹּאֵ֨ל הַ⁠דָּ֜ם אַחֲרֵ֣י הָ⁠רֹצֵ֗חַ כִּי־יֵחַם֮ לְבָב⁠וֹ֒ וְ⁠הִשִּׂיג֛⁠וֹ כִּֽי־יִרְבֶּ֥ה הַ⁠דֶּ֖רֶךְ וְ⁠הִכָּ֣ה⁠וּ נָ֑פֶשׁ וְ⁠ל⁠וֹ֙ אֵ֣ין מִשְׁפַּט־מָ֔וֶת כִּ֠י לֹ֣א שֹׂנֵ֥א ה֛וּא ל֖⁠וֹ מִ⁠תְּמ֥וֹל שִׁלְשֽׁוֹם׃","pėn-yirĕdò̇p֩ gò̇ʼé֨l ha⁠dá̇֜m ʼaẖàré֣y há⁠ròẕé֗ẖa ki̇y-yéẖam֮ lĕbáb⁠wò֒ wĕ⁠hişi̇̂yg֛⁠wò kiֽ̇y-yirĕbė֥h ha⁠dė֖rekĕ wĕ⁠hiká֣̇h⁠ẇ ná֑peş̌ wĕ⁠l⁠wò֙ ʼé֣yn mişĕ̌pȧt-má֔weţ ki̇֠y lò֣ʼ şò̂né֥ʼ h֛ẇʼ l֖⁠wò mi⁠ţĕ̇m֥wòl şǐlĕşֽ̌wòm׃"],[19,7,"עַל־כֵּ֛ן אָנֹכִ֥י מְצַוְּ⁠ךָ֖ לֵ⁠אמֹ֑ר שָׁלֹ֥שׁ עָרִ֖ים תַּבְדִּ֥יל לָֽ⁠ךְ׃ס","ʻal-ké֛̇n ʼánòki֥y mĕẕawĕ̇⁠ká֖ lé⁠ʼmò֑r şá̌lò֥ş̌ ʻári֖ym ţȧbĕdi֥̇yl láֽ⁠kĕ׃s"],[19,8,"וְ⁠אִם־יַרְחִ֞יב יְהוָ֤ה אֱלֹהֶ֨י⁠ךָ֙ אֶת־גְּבֻ֣לְ⁠ךָ֔ כַּ⁠אֲשֶׁ֥ר נִשְׁבַּ֖ע לַ⁠אֲבֹתֶ֑י⁠ךָ וְ⁠נָ֤תַן לְ⁠ךָ֙ אֶת־כָּל־הָ⁠אָ֔רֶץ אֲשֶׁ֥ר דִּבֶּ֖ר לָ⁠תֵ֥ת לַ⁠אֲבֹתֶֽי⁠ךָ׃","wĕ⁠ʼim-yarĕẖi֞yb yĕhwá֤h ʼèlòhe֨y⁠ká֙ ʼeţ-gĕ̇bu֣lĕ⁠ká֔ kȧ⁠ʼàşě֥r nişĕ̌bȧ֖ʻ la⁠ʼàbòţe֑y⁠ká wĕ⁠ná֤ţan lĕ⁠ká֙ ʼeţ-ká̇l-há⁠ʼá֔reẕ ʼàşě֥r di̇bė֖r lá⁠ţé֥ţ la⁠ʼàbòţeֽy⁠ká׃"],[19,9,"כִּֽי־תִשְׁמֹר֩ אֶת־כָּל־הַ⁠מִּצְוָ֨ה הַ⁠זֹּ֜את לַ⁠עֲשֹׂתָ֗⁠הּ אֲשֶׁ֨ר אָנֹכִ֣י מְצַוְּ⁠ךָ֮ הַ⁠יּוֹם֒ לְ⁠אַהֲבָ֞ה אֶת־יְהוָ֧ה אֱלֹהֶ֛י⁠ךָ וְ⁠לָ⁠לֶ֥כֶת בִּ⁠דְרָכָ֖י⁠ו כָּל־הַ⁠יָּמִ֑ים וְ⁠יָסַפְתָּ֨ לְ⁠ךָ֥ עוֹד֙ שָׁלֹ֣שׁ עָרִ֔ים עַ֖ל הַ⁠שָּׁלֹ֥שׁ הָ⁠אֵֽלֶּה׃","kiֽ̇y-ţişĕ̌mòr֩ ʼeţ-ká̇l-ha⁠mi̇ẕĕwá֨h ha⁠zò̇֜ʼţ la⁠ʻàşò̂ţá֗⁠ḣ ʼàşě֨r ʼánòki֣y mĕẕawĕ̇⁠ká֮ ha⁠ẏwòm֒ lĕ⁠ʼahàbá֞h ʼeţ-yĕhwá֧h ʼèlòhe֛y⁠ká wĕ⁠lá⁠le֥keţ bi̇⁠dĕráká֖y⁠w ká̇l-ha⁠yá̇mi֑ym wĕ⁠yásapĕţá̇֨ lĕ⁠ká֥ ʻwòd֙ şá̌lò֣ş̌ ʻári֔ym ʻa֖l ha⁠şá̇̌lò֥ş̌ há⁠ʼéֽlėh׃"],[19,10,"וְ⁠לֹ֤א יִשָּׁפֵךְ֙ דָּ֣ם נָקִ֔י בְּ⁠קֶ֣רֶב אַרְצְ⁠ךָ֔ אֲשֶׁר֙ יְהוָ֣ה אֱלֹהֶ֔י⁠ךָ נֹתֵ֥ן לְ⁠ךָ֖ נַחֲלָ֑ה וְ⁠הָיָ֥ה עָלֶ֖י⁠ךָ דָּמִֽים׃ס","wĕ⁠lò֤ʼ yişá̇̌pékĕ֙ dá֣̇m náqi֔y bĕ̇⁠qe֣reb ʼarĕẕĕ⁠ká֔ ʼàşěr֙ yĕhwá֣h ʼèlòhe֔y⁠ká nòţé֥n lĕ⁠ká֖ naẖàlá֑h wĕ⁠háyá֥h ʻále֖y⁠ká dá̇miֽym׃s"],[19,11,"וְ⁠כִֽי־יִהְיֶ֥ה אִישׁ֙ שֹׂנֵ֣א לְ⁠רֵעֵ֔⁠הוּ וְ⁠אָ֤רַב ל⁠וֹ֙ וְ⁠קָ֣ם עָלָ֔י⁠ו וְ⁠הִכָּ֥ה⁠וּ נֶ֖פֶשׁ וָ⁠מֵ֑ת וְ⁠נָ֕ס אֶל־אַחַ֖ת הֶ⁠עָרִ֥ים הָ⁠אֵֽל׃","wĕ⁠kiֽy-yihĕye֥h ʼiyş̌֙ şò̂né֣ʼ lĕ⁠réʻé֔⁠hẇ wĕ⁠ʼá֤rab l⁠wò֙ wĕ⁠qá֣m ʻálá֔y⁠w wĕ⁠hiká֥̇h⁠ẇ ne֖peş̌ wá⁠mé֑ţ wĕ⁠ná֕s ʼel-ʼaẖa֖ţ he⁠ʻári֥ym há⁠ʼéֽl׃"],[19,12,"וְ⁠שָֽׁלְחוּ֙ זִקְנֵ֣י עִיר֔⁠וֹ וְ⁠לָקְח֥וּ אֹת֖⁠וֹ מִ⁠שָּׁ֑ם וְ⁠נָתְנ֣וּ אֹת֗⁠וֹ בְּ⁠יַ֛ד גֹּאֵ֥ל הַ⁠דָּ֖ם וָ⁠מֵֽת׃","wĕ⁠şáֽ̌lĕẖẇ֙ ziqĕné֣y ʻiyr֔⁠wò wĕ⁠láqĕẖ֥ẇ ʼòţ֖⁠wò mi⁠şá֑̇̌m wĕ⁠náţĕn֣ẇ ʼòţ֗⁠wò bĕ̇⁠ya֛d gò̇ʼé֥l ha⁠dá֖̇m wá⁠méֽţ׃"],[19,13,"לֹא־תָח֥וֹס עֵֽינְ⁠ךָ֖ עָלָ֑י⁠ו וּ⁠בִֽעַרְתָּ֧ דַֽם־הַ⁠נָּקִ֛י מִ⁠יִּשְׂרָאֵ֖ל וְ⁠ט֥וֹב לָֽ⁠ךְ׃ס","lòʼ-ţáẖ֥wòs ʻéֽynĕ⁠ká֖ ʻálá֑y⁠w ẇ⁠biֽʻarĕţá֧̇ daֽm-ha⁠ná̇qi֛y mi⁠yi̇şĕ̂ráʼé֖l wĕ⁠t֥wòb láֽ⁠kĕ׃s"],[19,14,"לֹ֤א תַסִּיג֙ גְּב֣וּל רֵֽעֲ⁠ךָ֔ אֲשֶׁ֥ר גָּבְל֖וּ רִאשֹׁנִ֑ים בְּ⁠נַחֲלָֽתְ⁠ךָ֙ אֲשֶׁ֣ר תִּנְחַ֔ל בָּ⁠אָ֕רֶץ אֲשֶׁר֙ יְהוָ֣ה אֱלֹהֶ֔י⁠ךָ נֹתֵ֥ן לְ⁠ךָ֖ לְ⁠רִשְׁתָּֽ⁠הּ׃ס","lò֤ʼ ţasi̇yg֙ gĕ̇b֣ẇl réֽʻà⁠ká֔ ʼàşě֥r gá̇bĕl֖ẇ riʼşò̌ni֑ym bĕ̇⁠naẖàláֽţĕ⁠ká֙ ʼàşě֣r ţi̇nĕẖa֔l bá̇⁠ʼá֕reẕ ʼàşěr֙ yĕhwá֣h ʼèlòhe֔y⁠ká nòţé֥n lĕ⁠ká֖ lĕ⁠rişĕ̌ţáֽ̇⁠ḣ׃s"],[19,15,"לֹֽא־יָקוּם֩ עֵ֨ד אֶחָ֜ד בְּ⁠אִ֗ישׁ לְ⁠כָל־עָוֺן֙ וּ⁠לְ⁠כָל־חַטָּ֔את בְּ⁠כָל־חֵ֖טְא אֲשֶׁ֣ר יֶֽחֱטָ֑א עַל־פִּ֣י ׀ שְׁנֵ֣י עֵדִ֗ים א֛וֹ עַל־פִּ֥י שְׁלֹשָֽׁה־עֵדִ֖ים יָק֥וּם דָּבָֽר׃","lòֽʼ-yáqẇm֩ ʻé֨d ʼeẖá֜d bĕ̇⁠ʼi֗yş̌ lĕ⁠kál-ʻáwֺn֙ ẇ⁠lĕ⁠kál-ẖatá̇֔ʼţ bĕ̇⁠kál-ẖé֖tĕʼ ʼàşě֣r yeֽẖètá֑ʼ ʻal-pi֣̇y ׀ şĕ̌né֣y ʻédi֗ym ʼ֛wò ʻal-pi֥̇y şĕ̌lòşáֽ̌h-ʻédi֖ym yáq֥ẇm dá̇báֽr׃"],[19,16,"כִּֽי־יָק֥וּם עֵד־חָמָ֖ס בְּ⁠אִ֑ישׁ לַ⁠עֲנ֥וֹת בּ֖⁠וֹ סָרָֽה׃","kiֽ̇y-yáq֥ẇm ʻéd-ẖámá֖s bĕ̇⁠ʼi֑yş̌ la⁠ʻàn֥wòţ ḃ֖⁠wò sáráֽh׃"],[19,17,"וְ⁠עָמְד֧וּ שְׁנֵֽי־הָ⁠אֲנָשִׁ֛ים אֲשֶׁר־לָ⁠הֶ֥ם הָ⁠רִ֖יב לִ⁠פְנֵ֣י יְהוָ֑ה לִ⁠פְנֵ֤י הַ⁠כֹּֽהֲנִים֙ וְ⁠הַ⁠שֹּׁ֣פְטִ֔ים אֲשֶׁ֥ר יִהְי֖וּ בַּ⁠יָּמִ֥ים הָ⁠הֵֽם׃","wĕ⁠ʻámĕd֧ẇ şĕ̌néֽy-há⁠ʼànáşǐ֛ym ʼàşěr-lá⁠he֥m há⁠ri֖yb li⁠pĕné֣y yĕhwá֑h li⁠pĕné֤y ha⁠kòֽ̇hàniym֙ wĕ⁠ha⁠şò֣̇̌pĕti֔ym ʼàşě֥r yihĕy֖ẇ bȧ⁠yá̇mi֥ym há⁠héֽm׃"],[19,18,"וְ⁠דָרְשׁ֥וּ הַ⁠שֹּׁפְטִ֖ים הֵיטֵ֑ב וְ⁠הִנֵּ֤ה עֵֽד־שֶׁ֨קֶר֙ הָ⁠עֵ֔ד שֶׁ֖קֶר עָנָ֥ה בְ⁠אָחִֽי⁠ו׃","wĕ⁠dárĕş֥̌ẇ ha⁠şò̇̌pĕti֖ym héyté֑b wĕ⁠hiné֤̇h ʻéֽd-şě֨qer֙ há⁠ʻé֔d şě֖qer ʻáná֥h bĕ⁠ʼáẖiֽy⁠w׃"],[19,19,"וַ⁠עֲשִׂ֣יתֶם ל֔⁠וֹ כַּ⁠אֲשֶׁ֥ר זָמַ֖ם לַ⁠עֲשׂ֣וֹת לְ⁠אָחִ֑י⁠ו וּ⁠בִֽעַרְתָּ֥ הָ⁠רָ֖ע מִ⁠קִּרְבֶּֽ⁠ךָ׃","wa⁠ʻàşî֣yţem l֔⁠wò kȧ⁠ʼàşě֥r záma֖m la⁠ʻàş֣̂wòţ lĕ⁠ʼáẖi֑y⁠w ẇ⁠biֽʻarĕţá֥̇ há⁠rá֖ʻ mi⁠qi̇rĕbėֽ⁠ká׃"],[19,20,"וְ⁠הַ⁠נִּשְׁאָרִ֖ים יִשְׁמְע֣וּ וְ⁠יִרָ֑אוּ וְ⁠לֹֽא־יֹסִ֨פוּ לַ⁠עֲשׂ֜וֹת ע֗וֹד כַּ⁠דָּבָ֥ר הָ⁠רָ֛ע הַ⁠זֶּ֖ה בְּ⁠קִרְבֶּֽ⁠ךָ׃","wĕ⁠ha⁠ni̇şĕ̌ʼári֖ym yişĕ̌mĕʻ֣ẇ wĕ⁠yirá֑ʼẇ wĕ⁠lòֽʼ-yòsi֨pẇ la⁠ʻàş̂֜wòţ ʻ֗wòd kȧ⁠dá̇bá֥r há⁠rá֛ʻ ha⁠zė֖h bĕ̇⁠qirĕbėֽ⁠ká׃"],[19,21,"וְ⁠לֹ֥א תָח֖וֹס עֵינֶ֑⁠ךָ נֶ֣פֶשׁ בְּ⁠נֶ֗פֶשׁ עַ֤יִן בְּ⁠עַ֨יִן֙ שֵׁ֣ן בְּ⁠שֵׁ֔ן יָ֥ד בְּ⁠יָ֖ד רֶ֥גֶל בְּ⁠רָֽגֶל׃ס","wĕ⁠lò֥ʼ ţáẖ֖wòs ʻéyne֑⁠ká ne֣peş̌ bĕ̇⁠ne֗peş̌ ʻa֤yin bĕ̇⁠ʻa֨yin֙ şé֣̌n bĕ̇⁠şé̌֔n yá֥d bĕ̇⁠yá֖d re֥gel bĕ̇⁠ráֽgel׃s"],[20,1,"כִּֽי־תֵצֵ֨א לַ⁠מִּלְחָמָ֜ה עַל־אֹיְבֶ֗י⁠ךָ וְֽ⁠רָאִ֜יתָ ס֤וּס וָ⁠רֶ֨כֶב֙ עַ֚ם רַ֣ב מִמְּ⁠ךָ֔ לֹ֥א תִירָ֖א מֵ⁠הֶ֑ם כִּֽי־יְהוָ֤ה אֱלֹהֶ֨י⁠ךָ֙ עִמָּ֔⁠ךְ הַ⁠מַּֽעַלְ⁠ךָ֖ מֵ⁠אֶ֥רֶץ מִצְרָֽיִם׃","kiֽ̇y-ţéẕé֨ʼ la⁠mi̇lĕẖámá֜h ʻal-ʼòyĕbe֗y⁠ká wĕֽ⁠ráʼi֜yţá s֤ẇs wá⁠re֨keb֙ ʻa֚m ra֣b mimĕ̇⁠ká֔ lò֥ʼ ţiyrá֖ʼ mé⁠he֑m kiֽ̇y-yĕhwá֤h ʼèlòhe֨y⁠ká֙ ʻimá̇֔⁠kĕ ha⁠mȧֽʻalĕ⁠ká֖ mé⁠ʼe֥reẕ miẕĕráֽyim׃"],[20,2,"וְ⁠הָיָ֕ה כְּ⁠קָֽרָבְ⁠כֶ֖ם אֶל־הַ⁠מִּלְחָמָ֑ה וְ⁠נִגַּ֥שׁ הַ⁠כֹּהֵ֖ן וְ⁠דִבֶּ֥ר אֶל־הָ⁠עָֽם׃","wĕ⁠háyá֕h kĕ̇⁠qáֽrábĕ⁠ke֖m ʼel-ha⁠mi̇lĕẖámá֑h wĕ⁠nigȧ֥ş̌ ha⁠kò̇hé֖n wĕ⁠dibė֥r ʼel-há⁠ʻáֽm׃"],[20,3,"וְ⁠אָמַ֤ר אֲלֵ⁠הֶם֙ שְׁמַ֣ע יִשְׂרָאֵ֔ל אַתֶּ֨ם קְרֵבִ֥ים הַ⁠יּ֛וֹם לַ⁠מִּלְחָמָ֖ה עַל־אֹיְבֵי⁠כֶ֑ם אַל־יֵרַ֣ךְ לְבַבְ⁠כֶ֗ם אַל־תִּֽירְא֧וּ וְ⁠אַֽל־תַּחְפְּז֛וּ וְ⁠אַל־תַּֽעַרְצ֖וּ מִ⁠פְּנֵי⁠הֶֽם׃","wĕ⁠ʼáma֤r ʼàlé⁠hem֙ şĕ̌ma֣ʻ yişĕ̂ráʼé֔l ʼaţė֨m qĕrébi֥ym ha⁠ẏ֛wòm la⁠mi̇lĕẖámá֖h ʻal-ʼòyĕbéy⁠ke֑m ʼal-yéra֣kĕ lĕbabĕ⁠ke֗m ʼal-ţiֽ̇yrĕʼ֧ẇ wĕ⁠ʼaֽl-ţȧẖĕpĕ̇z֛ẇ wĕ⁠ʼal-ţȧֽʻarĕẕ֖ẇ mi⁠pĕ̇néy⁠heֽm׃"],[20,4,"כִּ֚י יְהוָ֣ה אֱלֹֽהֵי⁠כֶ֔ם הַ⁠הֹלֵ֖ךְ עִמָּ⁠כֶ֑ם לְ⁠הִלָּחֵ֥ם לָ⁠כֶ֛ם עִם־אֹיְבֵי⁠כֶ֖ם לְ⁠הוֹשִׁ֥יעַ אֶתְ⁠כֶֽם׃","ki֚̇y yĕhwá֣h ʼèlòֽhéy⁠ke֔m ha⁠hòlé֖kĕ ʻimá̇⁠ke֑m lĕ⁠hilá̇ẖé֥m lá⁠ke֛m ʻim-ʼòyĕbéy⁠ke֖m lĕ⁠hwòşǐ֥yʻa ʼeţĕ⁠keֽm׃"],[20,5,"וְ⁠דִבְּר֣וּ הַ⁠שֹּֽׁטְרִים֮ אֶל־הָ⁠עָ֣ם לֵ⁠אמֹר֒ מִֽי־הָ⁠אִ֞ישׁ אֲשֶׁ֨ר בָּנָ֤ה בַֽיִת־חָדָשׁ֙ וְ⁠לֹ֣א חֲנָכ֔⁠וֹ יֵלֵ֖ךְ וְ⁠יָשֹׁ֣ב לְ⁠בֵית֑⁠וֹ פֶּן־יָמוּת֙ בַּ⁠מִּלְחָמָ֔ה וְ⁠אִ֥ישׁ אַחֵ֖ר יַחְנְכֶֽ⁠נּוּ׃","wĕ⁠dibĕ̇r֣ẇ ha⁠şòֽ̇̌tĕriym֮ ʼel-há⁠ʻá֣m lé⁠ʼmòr֒ miֽy-há⁠ʼi֞yş̌ ʼàşě֨r bá̇ná֤h baֽyiţ-ẖádáş̌֙ wĕ⁠lò֣ʼ ẖànák֔⁠wò yélé֖kĕ wĕ⁠yáşò֣̌b lĕ⁠béyţ֑⁠wò pėn-yámẇţ֙ bȧ⁠mi̇lĕẖámá֔h wĕ⁠ʼi֥yş̌ ʼaẖé֖r yaẖĕnĕkeֽ⁠ṅẇ׃"],[20,6,"וּ⁠מִֽי־הָ⁠אִ֞ישׁ אֲשֶׁר־נָטַ֥ע כֶּ֨רֶם֙ וְ⁠לֹ֣א חִלְּל֔⁠וֹ יֵלֵ֖ךְ וְ⁠יָשֹׁ֣ב לְ⁠בֵית֑⁠וֹ פֶּן־יָמוּת֙ בַּ⁠מִּלְחָמָ֔ה וְ⁠אִ֥ישׁ אַחֵ֖ר יְחַלְּלֶֽ⁠נּוּ׃","ẇ⁠miֽy-há⁠ʼi֞yş̌ ʼàşěr-náta֥ʻ kė֨rem֙ wĕ⁠lò֣ʼ ẖilĕ̇l֔⁠wò yélé֖kĕ wĕ⁠yáşò֣̌b lĕ⁠béyţ֑⁠wò pėn-yámẇţ֙ bȧ⁠mi̇lĕẖámá֔h wĕ⁠ʼi֥yş̌ ʼaẖé֖r yĕẖalĕ̇leֽ⁠ṅẇ׃"],[20,7,"וּ⁠מִֽי־הָ⁠אִ֞ישׁ אֲשֶׁר־אֵרַ֤שׂ אִשָּׁה֙ וְ⁠לֹ֣א לְקָחָ֔⁠הּ יֵלֵ֖ךְ וְ⁠יָשֹׁ֣ב לְ⁠בֵית֑⁠וֹ פֶּן־יָמוּת֙ בַּ⁠מִּלְחָמָ֔ה וְ⁠אִ֥ישׁ אַחֵ֖ר יִקָּחֶֽ⁠נָּה׃","ẇ⁠miֽy-há⁠ʼi֞yş̌ ʼàşěr-ʼéra֤ş̂ ʼişá̇̌h֙ wĕ⁠lò֣ʼ lĕqáẖá֔⁠ḣ yélé֖kĕ wĕ⁠yáşò֣̌b lĕ⁠béyţ֑⁠wò pėn-yámẇţ֙ bȧ⁠mi̇lĕẖámá֔h wĕ⁠ʼi֥yş̌ ʼaẖé֖r yiqá̇ẖeֽ⁠ná̇h׃"],[20,8,"וְ⁠יָסְפ֣וּ הַ⁠שֹּׁטְרִים֮ לְ⁠דַבֵּ֣ר אֶל־הָ⁠עָם֒ וְ⁠אָמְר֗וּ מִי־הָ⁠אִ֤ישׁ הַ⁠יָּרֵא֙ וְ⁠רַ֣ךְ הַ⁠לֵּבָ֔ב יֵלֵ֖ךְ וְ⁠יָשֹׁ֣ב לְ⁠בֵית֑⁠וֹ וְ⁠לֹ֥א יִמַּ֛ס אֶת־לְבַ֥ב אֶחָ֖י⁠ו כִּ⁠לְבָבֽ⁠וֹ׃","wĕ⁠yásĕp֣ẇ ha⁠şò̇̌tĕriym֮ lĕ⁠dabé֣̇r ʼel-há⁠ʻám֒ wĕ⁠ʼámĕr֗ẇ miy-há⁠ʼi֤yş̌ ha⁠yá̇réʼ֙ wĕ⁠ra֣kĕ ha⁠lé̇bá֔b yélé֖kĕ wĕ⁠yáşò֣̌b lĕ⁠béyţ֑⁠wò wĕ⁠lò֥ʼ yimȧ֛s ʼeţ-lĕba֥b ʼeẖá֖y⁠w ki̇⁠lĕbábֽ⁠wò׃"],[20,9,"וְ⁠הָיָ֛ה כְּ⁠כַלֹּ֥ת הַ⁠שֹּׁטְרִ֖ים לְ⁠דַבֵּ֣ר אֶל־הָ⁠עָ֑ם וּ⁠פָֽקְד֛וּ שָׂרֵ֥י צְבָא֖וֹת בְּ⁠רֹ֥אשׁ הָ⁠עָֽם׃ס","wĕ⁠háyá֛h kĕ̇⁠kalò֥̇ţ ha⁠şò̇̌tĕri֖ym lĕ⁠dabé֣̇r ʼel-há⁠ʻá֑m ẇ⁠páֽqĕd֛ẇ şá̂ré֥y ẕĕbáʼ֖wòţ bĕ̇⁠rò֥ʼş̌ há⁠ʻáֽm׃s"],[20,10,"כִּֽי־תִקְרַ֣ב אֶל־עִ֔יר לְ⁠הִלָּחֵ֖ם עָלֶ֑י⁠הָ וְ⁠קָרָ֥אתָ אֵלֶ֖י⁠הָ לְ⁠שָׁלֽוֹם׃","kiֽ̇y-ţiqĕra֣b ʼel-ʻi֔yr lĕ⁠hilá̇ẖé֖m ʻále֑y⁠há wĕ⁠qárá֥ʼţá ʼéle֖y⁠há lĕ⁠şá̌lֽwòm׃"],[20,11,"וְ⁠הָיָה֙ אִם־שָׁל֣וֹם תַּֽעַנְ⁠ךָ֔ וּ⁠פָתְחָ֖ה לָ֑⁠ךְ וְ⁠הָיָ֞ה כָּל־הָ⁠עָ֣ם הַ⁠נִּמְצָא־בָ֗⁠הּ יִהְי֥וּ לְ⁠ךָ֛ לָ⁠מַ֖ס וַ⁠עֲבָדֽוּ⁠ךָ׃","wĕ⁠háyáh֙ ʼim-şá̌l֣wòm ţȧֽʻanĕ⁠ká֔ ẇ⁠páţĕẖá֖h lá֑⁠kĕ wĕ⁠háyá֞h ká̇l-há⁠ʻá֣m ha⁠ni̇mĕẕáʼ-bá֗⁠ḣ yihĕy֥ẇ lĕ⁠ká֛ lá⁠ma֖s wa⁠ʻàbádֽẇ⁠ká׃"],[20,12,"וְ⁠אִם־לֹ֤א תַשְׁלִים֙ עִמָּ֔⁠ךְ וְ⁠עָשְׂתָ֥ה עִמְּ⁠ךָ֖ מִלְחָמָ֑ה וְ⁠צַרְתָּ֖ עָלֶֽי⁠הָּ׃","wĕ⁠ʼim-lò֤ʼ ţaşĕ̌liym֙ ʻimá̇֔⁠kĕ wĕ⁠ʻáşĕ̂ţá֥h ʻimĕ̇⁠ká֖ milĕẖámá֑h wĕ⁠ẕarĕţá֖̇ ʻáleֽy⁠há̇׃"],[20,13,"וּ⁠נְתָנָ֛⁠הּ יְהוָ֥ה אֱלֹהֶ֖י⁠ךָ בְּ⁠יָדֶ֑⁠ךָ וְ⁠הִכִּיתָ֥ אֶת־כָּל־זְכוּרָ֖⁠הּ לְ⁠פִי־חָֽרֶב׃","ẇ⁠nĕţáná֛⁠ḣ yĕhwá֥h ʼèlòhe֖y⁠ká bĕ̇⁠yáde֑⁠ká wĕ⁠hiki̇yţá֥ ʼeţ-ká̇l-zĕkẇrá֖⁠ḣ lĕ⁠piy-ẖáֽreb׃"],[20,14,"רַ֣ק הַ֠⁠נָּשִׁים וְ⁠הַ⁠טַּ֨ף וְ⁠הַ⁠בְּהֵמָ֜ה וְ⁠כֹל֩ אֲשֶׁ֨ר יִהְיֶ֥ה בָ⁠עִ֛יר כָּל־שְׁלָלָ֖⁠הּ תָּבֹ֣ז לָ֑⁠ךְ וְ⁠אָֽכַלְתָּ֙ אֶת־שְׁלַ֣ל אֹיְבֶ֔י⁠ךָ אֲשֶׁ֥ר נָתַ֛ן יְהוָ֥ה אֱלֹהֶ֖י⁠ךָ לָֽ⁠ךְ׃","ra֣q ha֠⁠ná̇şǐym wĕ⁠ha⁠tȧ֨p wĕ⁠ha⁠bĕ̇hémá֜h wĕ⁠kòl֩ ʼàşě֨r yihĕye֥h bá⁠ʻi֛yr ká̇l-şĕ̌lálá֖⁠ḣ ţá̇bò֣z lá֑⁠kĕ wĕ⁠ʼáֽkalĕţá̇֙ ʼeţ-şĕ̌la֣l ʼòyĕbe֔y⁠ká ʼàşě֥r náţa֛n yĕhwá֥h ʼèlòhe֖y⁠ká láֽ⁠kĕ׃"],[20,15,"כֵּ֤ן תַּעֲשֶׂה֙ לְ⁠כָל־הֶ֣⁠עָרִ֔ים הָ⁠רְחֹקֹ֥ת מִמְּ⁠ךָ֖ מְאֹ֑ד אֲשֶׁ֛ר לֹא־מֵ⁠עָרֵ֥י הַ⁠גּֽוֹיִם־הָ⁠אֵ֖לֶּה הֵֽנָּה׃","ké֤̇n ţȧʻàşêh֙ lĕ⁠kál-he֣⁠ʻári֔ym há⁠rĕẖòqò֥ţ mimĕ̇⁠ká֖ mĕʼò֑d ʼàşě֛r lòʼ-mé⁠ʻáré֥y ha⁠ġֽwòyim-há⁠ʼé֖lėh héֽná̇h׃"],[20,16,"רַ֗ק מֵ⁠עָרֵ֤י הָֽ⁠עַמִּים֙ הָ⁠אֵ֔לֶּה אֲשֶׁר֙ יְהוָ֣ה אֱלֹהֶ֔י⁠ךָ נֹתֵ֥ן לְ⁠ךָ֖ נַחֲלָ֑ה לֹ֥א תְחַיֶּ֖ה כָּל־נְשָׁמָֽה׃","ra֗q mé⁠ʻáré֤y háֽ⁠ʻami̇ym֙ há⁠ʼé֔lėh ʼàşěr֙ yĕhwá֣h ʼèlòhe֔y⁠ká nòţé֥n lĕ⁠ká֖ naẖàlá֑h lò֥ʼ ţĕẖayė֖h ká̇l-nĕşá̌máֽh׃"],[20,17,"כִּֽי־הַחֲרֵ֣ם תַּחֲרִימֵ֗⁠ם הַ⁠חִתִּ֤י וְ⁠הָ⁠אֱמֹרִי֙ הַ⁠כְּנַעֲנִ֣י וְ⁠הַ⁠פְּרִזִּ֔י הַ⁠חִוִּ֖י וְ⁠הַ⁠יְבוּסִ֑י כַּ⁠אֲשֶׁ֥ר צִוְּ⁠ךָ֖ יְהוָ֥ה אֱלֹהֶֽי⁠ךָ׃","kiֽ̇y-haẖàré֣m ţȧẖàriymé֗⁠m ha⁠ẖiţi֤̇y wĕ⁠há⁠ʼèmòriy֙ ha⁠kĕ̇naʻàni֣y wĕ⁠ha⁠pĕ̇rizi̇֔y ha⁠ẖiwi֖̇y wĕ⁠ha⁠yĕbẇsi֑y kȧ⁠ʼàşě֥r ẕiwĕ̇⁠ká֖ yĕhwá֥h ʼèlòheֽy⁠ká׃"],[20,18,"לְמַ֗עַן אֲשֶׁ֨ר לֹֽא־יְלַמְּד֤וּ אֶתְ⁠כֶם֙ לַ⁠עֲשׂ֔וֹת כְּ⁠כֹל֙ תּֽוֹעֲבֹתָ֔⁠ם אֲשֶׁ֥ר עָשׂ֖וּ לֵֽ⁠אלֹהֵי⁠הֶ֑ם וַ⁠חֲטָאתֶ֖ם לַ⁠יהוָ֥ה אֱלֹהֵי⁠כֶֽם׃ס","lĕma֗ʻan ʼàşě֨r lòֽʼ-yĕlamĕ̇d֤ẇ ʼeţĕ⁠kem֙ la⁠ʻàş̂֔wòţ kĕ̇⁠kòl֙ ţֽ̇wòʻàbòţá֔⁠m ʼàşě֥r ʻáş֖̂ẇ léֽ⁠ʼlòhéy⁠he֑m wa⁠ẖàtáʼţe֖m la⁠yhwá֥h ʼèlòhéy⁠keֽm׃s"],[20,19,"כִּֽי־תָצ֣וּר אֶל־עִיר֩ יָמִ֨ים רַבִּ֜ים לְֽ⁠הִלָּחֵ֧ם עָלֶ֣י⁠הָ לְ⁠תָפְשָׂ֗⁠הּ לֹֽא־תַשְׁחִ֤ית אֶת־עֵצָ⁠הּ֙ לִ⁠נְדֹּ֤חַ עָלָי⁠ו֙ גַּרְזֶ֔ן כִּ֚י מִמֶּ֣⁠נּוּ תֹאכֵ֔ל וְ⁠אֹת֖⁠וֹ לֹ֣א תִכְרֹ֑ת כִּ֤י הָֽ⁠אָדָם֙ עֵ֣ץ הַ⁠שָּׂדֶ֔ה לָ⁠בֹ֥א מִ⁠פָּנֶ֖י⁠ךָ בַּ⁠מָּצֽוֹר׃","kiֽ̇y-ţáẕ֣ẇr ʼel-ʻiyr֩ yámi֨ym rabi̇֜ym lĕֽ⁠hilá̇ẖé֧m ʻále֣y⁠há lĕ⁠ţápĕşá̂֗⁠ḣ lòֽʼ-ţaşĕ̌ẖi֤yţ ʼeţ-ʻéẕá⁠ḣ֙ li⁠nĕdò֤̇ẖa ʻáláy⁠w֙ gȧrĕze֔n ki֚̇y mimė֣⁠ṅẇ ţòʼké֔l wĕ⁠ʼòţ֖⁠wò lò֣ʼ ţikĕrò֑ţ ki֤̇y háֽ⁠ʼádám֙ ʻé֣ẕ ha⁠şá̇̂de֔h lá⁠bò֥ʼ mi⁠pá̇ne֖y⁠ká bȧ⁠má̇ẕֽwòr׃"],[20,20,"רַ֞ק עֵ֣ץ אֲשֶׁר־תֵּדַ֗ע כִּֽי־לֹא־עֵ֤ץ מַאֲכָל֙ ה֔וּא אֹת֥⁠וֹ תַשְׁחִ֖ית וְ⁠כָרָ֑תָּ וּ⁠בָנִ֣יתָ מָצ֗וֹר עַל־הָ⁠עִיר֙ אֲשֶׁר־הִ֨וא עֹשָׂ֧ה עִמְּ⁠ךָ֛ מִלְחָמָ֖ה עַ֥ד רִדְתָּֽ⁠הּ׃פ","ra֞q ʻé֣ẕ ʼàşěr-ţé̇da֗ʻ kiֽ̇y-lòʼ-ʻé֤ẕ maʼàkál֙ h֔ẇʼ ʼòţ֥⁠wò ţaşĕ̌ẖi֖yţ wĕ⁠kárá֑ţá̇ ẇ⁠báni֣yţá máẕ֗wòr ʻal-há⁠ʻiyr֙ ʼàşěr-hi֨wʼ ʻòşá֧̂h ʻimĕ̇⁠ká֛ milĕẖámá֖h ʻa֥d ridĕţáֽ̇⁠ḣ׃p"],[21,1,"כִּי־יִמָּצֵ֣א חָלָ֗ל בָּ⁠אֲדָמָה֙ אֲשֶׁר֩ יְהוָ֨ה אֱלֹהֶ֜י⁠ךָ נֹתֵ֤ן לְ⁠ךָ֙ לְ⁠רִשְׁתָּ֔⁠הּ נֹפֵ֖ל בַּ⁠שָּׂדֶ֑ה לֹ֥א נוֹדַ֖ע מִ֥י הִכָּֽה⁠וּ׃","ki̇y-yimá̇ẕé֣ʼ ẖálá֗l bá̇⁠ʼàdámáh֙ ʼàşěr֩ yĕhwá֨h ʼèlòhe֜y⁠ká nòţé֤n lĕ⁠ká֙ lĕ⁠rişĕ̌ţá̇֔⁠ḣ nòpé֖l bȧ⁠şá̇̂de֑h lò֥ʼ nwòda֖ʻ mi֥y hikáֽ̇h⁠ẇ׃"],[21,2,"וְ⁠יָצְא֥וּ זְקֵנֶ֖י⁠ךָ וְ⁠שֹׁפְטֶ֑י⁠ךָ וּ⁠מָדְדוּ֙ אֶל־הֶ֣⁠עָרִ֔ים אֲשֶׁ֖ר סְבִיבֹ֥ת הֶ⁠חָלָֽל׃","wĕ⁠yáẕĕʼ֥ẇ zĕqéne֖y⁠ká wĕ⁠şò̌pĕte֑y⁠ká ẇ⁠mádĕdẇ֙ ʼel-he֣⁠ʻári֔ym ʼàşě֖r sĕbiybò֥ţ he⁠ẖáláֽl׃"],[21,3,"וְ⁠הָיָ֣ה הָ⁠עִ֔יר הַ⁠קְּרֹבָ֖ה אֶל־הֶ⁠חָלָ֑ל וְ⁠לָֽקְח֡וּ זִקְנֵי֩ הָ⁠עִ֨יר הַ⁠הִ֜וא עֶגְלַ֣ת בָּקָ֗ר אֲשֶׁ֤ר לֹֽא־עֻבַּד֙ בָּ֔⁠הּ אֲשֶׁ֥ר לֹא־מָשְׁכָ֖ה בְּ⁠עֹֽל׃","wĕ⁠háyá֣h há⁠ʻi֔yr ha⁠qĕ̇ròbá֖h ʼel-he⁠ẖálá֑l wĕ⁠láֽqĕẖ֡ẇ ziqĕnéy֩ há⁠ʻi֨yr ha⁠hi֜wʼ ʻegĕla֣ţ bá̇qá֗r ʼàşě֤r lòֽʼ-ʻubȧd֙ bá̇֔⁠ḣ ʼàşě֥r lòʼ-máşĕ̌ká֖h bĕ̇⁠ʻòֽl׃"],[21,4,"וְ⁠הוֹרִ֡דוּ זִקְנֵי֩ הָ⁠עִ֨יר הַ⁠הִ֤וא אֶת־הָֽ⁠עֶגְלָה֙ אֶל־נַ֣חַל אֵיתָ֔ן אֲשֶׁ֛ר לֹא־יֵעָבֵ֥ד בּ֖⁠וֹ וְ⁠לֹ֣א יִזָּרֵ֑עַ וְ⁠עָֽרְפוּ־שָׁ֥ם אֶת־הָ⁠עֶגְלָ֖ה בַּ⁠נָּֽחַל׃","wĕ⁠hwòri֡dẇ ziqĕnéy֩ há⁠ʻi֨yr ha⁠hi֤wʼ ʼeţ-háֽ⁠ʻegĕláh֙ ʼel-na֣ẖal ʼéyţá֔n ʼàşě֛r lòʼ-yéʻábé֥d ḃ֖⁠wò wĕ⁠lò֣ʼ yizá̇ré֑ʻa wĕ⁠ʻáֽrĕpẇ-şá֥̌m ʼeţ-há⁠ʻegĕlá֖h bȧ⁠náֽ̇ẖal׃"],[21,5,"וְ⁠נִגְּשׁ֣וּ הַ⁠כֹּהֲנִים֮ בְּנֵ֣י לֵוִי֒ כִּ֣י בָ֗⁠ם בָּחַ֞ר יְהוָ֤ה אֱלֹהֶ֨י⁠ךָ֙ לְ⁠שָׁ֣רְת֔⁠וֹ וּ⁠לְ⁠בָרֵ֖ךְ בְּ⁠שֵׁ֣ם יְהוָ֑ה וְ⁠עַל־פִּי⁠הֶ֥ם יִהְיֶ֖ה כָּל־רִ֥יב וְ⁠כָל־נָֽגַע׃","wĕ⁠nigĕ̇ş֣̌ẇ ha⁠kò̇hàniym֮ bĕ̇né֣y léwiy֒ ki֣̇y bá֗⁠m bá̇ẖa֞r yĕhwá֤h ʼèlòhe֨y⁠ká֙ lĕ⁠şá֣̌rĕţ֔⁠wò ẇ⁠lĕ⁠báré֖kĕ bĕ̇⁠şé֣̌m yĕhwá֑h wĕ⁠ʻal-pi̇y⁠he֥m yihĕye֖h ká̇l-ri֥yb wĕ⁠kál-náֽgaʻ׃"],[21,6,"וְ⁠כֹ֗ל זִקְנֵי֙ הָ⁠עִ֣יר הַ⁠הִ֔וא הַ⁠קְּרֹבִ֖ים אֶל־הֶ⁠חָלָ֑ל יִרְחֲצוּ֙ אֶת־יְדֵי⁠הֶ֔ם עַל־הָ⁠עֶגְלָ֖ה הָ⁠עֲרוּפָ֥ה בַ⁠נָּֽחַל׃","wĕ⁠kò֗l ziqĕnéy֙ há⁠ʻi֣yr ha⁠hi֔wʼ ha⁠qĕ̇ròbi֖ym ʼel-he⁠ẖálá֑l yirĕẖàẕẇ֙ ʼeţ-yĕdéy⁠he֔m ʻal-há⁠ʻegĕlá֖h há⁠ʻàrẇpá֥h ba⁠náֽ̇ẖal׃"],[21,7,"וְ⁠עָנ֖וּ וְ⁠אָמְר֑וּ יָדֵ֗י⁠נוּ לֹ֤א שפכה אֶת־הַ⁠דָּ֣ם הַ⁠זֶּ֔ה וְ⁠עֵינֵ֖י⁠נוּ לֹ֥א רָאֽוּ׃","wĕ⁠ʻán֖ẇ wĕ⁠ʼámĕr֑ẇ yádé֗y⁠nẇ lò֤ʼ şpkh ʼeţ-ha⁠dá֣̇m ha⁠zė֔h wĕ⁠ʻéyné֖y⁠nẇ lò֥ʼ ráʼֽẇ׃"],[21,8,"כַּפֵּר֩ לְ⁠עַמְּ⁠ךָ֨ יִשְׂרָאֵ֤ל אֲשֶׁר־פָּדִ֨יתָ֙ יְהוָ֔ה וְ⁠אַל־תִּתֵּן֙ דָּ֣ם נָקִ֔י בְּ⁠קֶ֖רֶב עַמְּ⁠ךָ֣ יִשְׂרָאֵ֑ל וְ⁠נִכַּפֵּ֥ר לָ⁠הֶ֖ם הַ⁠דָּֽם׃","kȧpé̇r֩ lĕ⁠ʻamĕ̇⁠ká֨ yişĕ̂ráʼé֤l ʼàşěr-pá̇di֨yţá֙ yĕhwá֔h wĕ⁠ʼal-ţi̇ţé̇n֙ dá֣̇m náqi֔y bĕ̇⁠qe֖reb ʻamĕ̇⁠ká֣ yişĕ̂ráʼé֑l wĕ⁠nikȧpé֥̇r lá⁠he֖m ha⁠dáֽ̇m׃"],[21,9,"וְ⁠אַתָּ֗ה תְּבַעֵ֛ר הַ⁠דָּ֥ם הַ⁠נָּקִ֖י מִ⁠קִּרְבֶּ֑⁠ךָ כִּֽי־תַעֲשֶׂ֥ה הַ⁠יָּשָׁ֖ר בְּ⁠עֵינֵ֥י יְהוָֽה׃ס","wĕ⁠ʼaţá̇֗h ţĕ̇baʻé֛r ha⁠dá֥̇m ha⁠ná̇qi֖y mi⁠qi̇rĕbė֑⁠ká kiֽ̇y-ţaʻàşê֥h ha⁠yá̇şá֖̌r bĕ̇⁠ʻéyné֥y yĕhwáֽh׃s"],[21,10,"כִּֽי־תֵצֵ֥א לַ⁠מִּלְחָמָ֖ה עַל־אֹיְבֶ֑י⁠ךָ וּ⁠נְתָנ֞⁠וֹ יְהוָ֧ה אֱלֹהֶ֛י⁠ךָ בְּ⁠יָדֶ֖⁠ךָ וְ⁠שָׁבִ֥יתָ שִׁבְיֽ⁠וֹ׃","kiֽ̇y-ţéẕé֥ʼ la⁠mi̇lĕẖámá֖h ʻal-ʼòyĕbe֑y⁠ká ẇ⁠nĕţán֞⁠wò yĕhwá֧h ʼèlòhe֛y⁠ká bĕ̇⁠yáde֖⁠ká wĕ⁠şá̌bi֥yţá şǐbĕyֽ⁠wò׃"],[21,11,"וְ⁠רָאִיתָ֙ בַּ⁠שִּׁבְיָ֔ה אֵ֖שֶׁת יְפַת־תֹּ֑אַר וְ⁠חָשַׁקְתָּ֣ בָ֔⁠הּ וְ⁠לָקַחְתָּ֥ לְ⁠ךָ֖ לְ⁠אִשָּֽׁה׃","wĕ⁠ráʼiyţá֙ bȧ⁠şi̇̌bĕyá֔h ʼé֖şěţ yĕpaţ-ţò֑̇ʼar wĕ⁠ẖáşǎqĕţá֣̇ bá֔⁠ḣ wĕ⁠láqaẖĕţá֥̇ lĕ⁠ká֖ lĕ⁠ʼişáֽ̇̌h׃"],[21,12,"וַ⁠הֲבֵאתָ֖⁠הּ אֶל־תּ֣וֹךְ בֵּיתֶ֑⁠ךָ וְ⁠גִלְּחָה֙ אֶת־רֹאשָׁ֔⁠הּ וְ⁠עָשְׂתָ֖ה אֶת־צִפָּרְנֶֽי⁠הָ׃","wa⁠hàbéʼţá֖⁠ḣ ʼel-ţ֣̇wòkĕ bé̇yţe֑⁠ká wĕ⁠gilĕ̇ẖáh֙ ʼeţ-ròʼşá̌֔⁠ḣ wĕ⁠ʻáşĕ̂ţá֖h ʼeţ-ẕipá̇rĕneֽy⁠há׃"],[21,13,"וְ⁠הֵסִ֩ירָה֩ אֶת־שִׂמְלַ֨ת שִׁבְיָ֜⁠הּ מֵ⁠עָלֶ֗י⁠הָ וְ⁠יָֽשְׁבָה֙ בְּ⁠בֵיתֶ֔⁠ךָ וּ⁠בָֽכְתָ֛ה אֶת־אָבִ֥י⁠הָ וְ⁠אֶת־אִמָּ֖⁠הּ יֶ֣רַח יָמִ֑ים וְ⁠אַ֨חַר כֵּ֜ן תָּב֤וֹא אֵלֶ֨י⁠הָ֙ וּ⁠בְעַלְתָּ֔⁠הּ וְ⁠הָיְתָ֥ה לְ⁠ךָ֖ לְ⁠אִשָּֽׁה׃","wĕ⁠hési֩yráh֩ ʼeţ-şîmĕla֨ţ şǐbĕyá֜⁠ḣ mé⁠ʻále֗y⁠há wĕ⁠yáֽşĕ̌báh֙ bĕ̇⁠béyţe֔⁠ká ẇ⁠báֽkĕţá֛h ʼeţ-ʼábi֥y⁠há wĕ⁠ʼeţ-ʼimá֖̇⁠ḣ ye֣raẖ yámi֑ym wĕ⁠ʼa֨ẖar ké̇֜n ţá̇b֤wòʼ ʼéle֨y⁠há֙ ẇ⁠bĕʻalĕţá̇֔⁠ḣ wĕ⁠háyĕţá֥h lĕ⁠ká֖ lĕ⁠ʼişáֽ̇̌h׃"],[21,14,"וְ⁠הָיָ֞ה אִם־לֹ֧א חָפַ֣צְתָּ בָּ֗⁠הּ וְ⁠שִׁלַּחְתָּ⁠הּ֙ לְ⁠נַפְשָׁ֔⁠הּ וּ⁠מָכֹ֥ר לֹא־תִמְכְּרֶ֖⁠נָּה בַּ⁠כָּ֑סֶף לֹא־תִתְעַמֵּ֣ר בָּ֔⁠הּ תַּ֖חַת אֲשֶׁ֥ר עִנִּיתָֽ⁠הּ׃ס","wĕ⁠háyá֞h ʼim-lò֧ʼ ẖápa֣ẕĕţá̇ bá̇֗⁠ḣ wĕ⁠şǐlȧẖĕţá̇⁠ḣ֙ lĕ⁠napĕşá̌֔⁠ḣ ẇ⁠mákò֥r lòʼ-ţimĕkĕ̇re֖⁠ná̇h bȧ⁠ká֑̇sep lòʼ-ţiţĕʻamé֣̇r bá̇֔⁠ḣ ţȧ֖ẖaţ ʼàşě֥r ʻini̇yţáֽ⁠ḣ׃s"],[21,15,"כִּֽי־תִהְיֶ֨יןָ לְ⁠אִ֜ישׁ שְׁתֵּ֣י נָשִׁ֗ים הָ⁠אַחַ֤ת אֲהוּבָה֙ וְ⁠הָ⁠אַחַ֣ת שְׂנוּאָ֔ה וְ⁠יָֽלְדוּ־ל֣⁠וֹ בָנִ֔ים הָ⁠אֲהוּבָ֖ה וְ⁠הַ⁠שְּׂנוּאָ֑ה וְ⁠הָיָ֛ה הַ⁠בֵּ֥ן הַ⁠בְּכ֖וֹר לַ⁠שְּׂנִיאָֽה׃","kiֽ̇y-ţihĕye֨yná lĕ⁠ʼi֜yş̌ şĕ̌ţé֣̇y náşǐ֗ym há⁠ʼaẖa֤ţ ʼàhẇbáh֙ wĕ⁠há⁠ʼaẖa֣ţ şĕ̂nẇʼá֔h wĕ⁠yáֽlĕdẇ-l֣⁠wò báni֔ym há⁠ʼàhẇbá֖h wĕ⁠ha⁠şĕ̇̂nẇʼá֑h wĕ⁠háyá֛h ha⁠bé֥̇n ha⁠bĕ̇k֖wòr la⁠şĕ̇̂niyʼáֽh׃"],[21,16,"וְ⁠הָיָ֗ה בְּ⁠יוֹם֙ הַנְחִיל֣⁠וֹ אֶת־בָּנָ֔י⁠ו אֵ֥ת אֲשֶׁר־יִהְיֶ֖ה ל֑⁠וֹ לֹ֣א יוּכַ֗ל לְ⁠בַכֵּר֙ אֶת־בֶּן־הָ֣⁠אֲהוּבָ֔ה עַל־פְּנֵ֥י בֶן־הַ⁠שְּׂנוּאָ֖ה הַ⁠בְּכֹֽר׃","wĕ⁠háyá֗h bĕ̇⁠ywòm֙ hanĕẖiyl֣⁠wò ʼeţ-bá̇ná֔y⁠w ʼé֥ţ ʼàşěr-yihĕye֖h l֑⁠wò lò֣ʼ yẇka֗l lĕ⁠baké̇r֙ ʼeţ-bėn-há֣⁠ʼàhẇbá֔h ʻal-pĕ̇né֥y ben-ha⁠şĕ̇̂nẇʼá֖h ha⁠bĕ̇kòֽr׃"],[21,17,"כִּי֩ אֶת־הַ⁠בְּכֹ֨ר בֶּן־הַ⁠שְּׂנוּאָ֜ה יַכִּ֗יר לָ֤⁠תֶת ל⁠וֹ֙ פִּ֣י שְׁנַ֔יִם בְּ⁠כֹ֥ל אֲשֶׁר־יִמָּצֵ֖א ל֑⁠וֹ כִּי־הוּא֙ רֵאשִׁ֣ית אֹנ֔⁠וֹ ל֖⁠וֹ מִשְׁפַּ֥ט הַ⁠בְּכֹרָֽה׃ס","ki̇y֩ ʼeţ-ha⁠bĕ̇kò֨r bėn-ha⁠şĕ̇̂nẇʼá֜h yaki̇֗yr lá֤⁠ţeţ l⁠wò֙ pi֣̇y şĕ̌na֔yim bĕ̇⁠kò֥l ʼàşěr-yimá̇ẕé֖ʼ l֑⁠wò ki̇y-hẇʼ֙ réʼşǐ֣yţ ʼòn֔⁠wò l֖⁠wò mişĕ̌pȧ֥t ha⁠bĕ̇kòráֽh׃s"],[21,18,"כִּֽי־יִהְיֶ֣ה לְ⁠אִ֗ישׁ בֵּ֚ן סוֹרֵ֣ר וּ⁠מוֹרֶ֔ה אֵינֶ֣⁠נּוּ שֹׁמֵ֔עַ בְּ⁠ק֥וֹל אָבִ֖י⁠ו וּ⁠בְ⁠ק֣וֹל אִמּ֑⁠וֹ וְ⁠יסְּר֣וּ אֹת֔⁠וֹ וְ⁠לֹ֥א יִשְׁמַ֖ע אֲלֵי⁠הֶֽם׃","kiֽ̇y-yihĕye֣h lĕ⁠ʼi֗yş̌ bé֚̇n swòré֣r ẇ⁠mwòre֔h ʼéyne֣⁠ṅẇ şò̌mé֔ʻa bĕ̇⁠q֥wòl ʼábi֖y⁠w ẇ⁠bĕ⁠q֣wòl ʼiṁ֑⁠wò wĕ⁠ysĕ̇r֣ẇ ʼòţ֔⁠wò wĕ⁠lò֥ʼ yişĕ̌ma֖ʻ ʼàléy⁠heֽm׃"],[21,19,"וְ⁠תָ֥פְשׂוּ ב֖⁠וֹ אָבִ֣י⁠ו וְ⁠אִמּ֑⁠וֹ וְ⁠הוֹצִ֧יאוּ אֹת֛⁠וֹ אֶל־זִקְנֵ֥י עִיר֖⁠וֹ וְ⁠אֶל־שַׁ֥עַר מְקֹמֽ⁠וֹ׃","wĕ⁠ţá֥pĕş̂ẇ b֖⁠wò ʼábi֣y⁠w wĕ⁠ʼiṁ֑⁠wò wĕ⁠hwòẕi֧yʼẇ ʼòţ֛⁠wò ʼel-ziqĕné֥y ʻiyr֖⁠wò wĕ⁠ʼel-şǎ֥ʻar mĕqòmֽ⁠wò׃"],[21,20,"וְ⁠אָמְר֞וּ אֶל־זִקְנֵ֣י עִיר֗⁠וֹ בְּנֵ֤⁠נוּ זֶה֙ סוֹרֵ֣ר וּ⁠מֹרֶ֔ה אֵינֶ֥⁠נּוּ שֹׁמֵ֖עַ בְּ⁠קֹלֵ֑⁠נוּ זוֹלֵ֖ל וְ⁠סֹבֵֽא׃","wĕ⁠ʼámĕr֞ẇ ʼel-ziqĕné֣y ʻiyr֗⁠wò bĕ̇né֤⁠nẇ zeh֙ swòré֣r ẇ⁠mòre֔h ʼéyne֥⁠ṅẇ şò̌mé֖ʻa bĕ̇⁠qòlé֑⁠nẇ zwòlé֖l wĕ⁠sòbéֽʼ׃"],[21,21,"וּ֠⁠רְגָמֻ⁠הוּ כָּל־אַנְשֵׁ֨י עִיר֤⁠וֹ בָֽ⁠אֲבָנִים֙ וָ⁠מֵ֔ת וּ⁠בִֽעַרְתָּ֥ הָ⁠רָ֖ע מִ⁠קִּרְבֶּ֑⁠ךָ וְ⁠כָל־יִשְׂרָאֵ֖ל יִשְׁמְע֥וּ וְ⁠יִרָֽאוּ׃ס","ẇ֠⁠rĕgámu⁠hẇ ká̇l-ʼanĕşé̌֨y ʻiyr֤⁠wò báֽ⁠ʼàbániym֙ wá⁠mé֔ţ ẇ⁠biֽʻarĕţá֥̇ há⁠rá֖ʻ mi⁠qi̇rĕbė֑⁠ká wĕ⁠kál-yişĕ̂ráʼé֖l yişĕ̌mĕʻ֥ẇ wĕ⁠yiráֽʼẇ׃s"],[21,22,"וְ⁠כִֽי־יִהְיֶ֣ה בְ⁠אִ֗ישׁ חֵ֛טְא מִשְׁפַּט־מָ֖וֶת וְ⁠הוּמָ֑ת וְ⁠תָלִ֥יתָ אֹת֖⁠וֹ עַל־עֵֽץ׃","wĕ⁠kiֽy-yihĕye֣h bĕ⁠ʼi֗yş̌ ẖé֛tĕʼ mişĕ̌pȧt-má֖weţ wĕ⁠hẇmá֑ţ wĕ⁠ţáli֥yţá ʼòţ֖⁠wò ʻal-ʻéֽẕ׃"],[21,23,"לֹא־תָלִ֨ין נִבְלָת֜⁠וֹ עַל־הָ⁠עֵ֗ץ כִּֽי־קָב֤וֹר תִּקְבְּרֶ֨⁠נּוּ֙ בַּ⁠יּ֣וֹם הַ⁠ה֔וּא כִּֽי־קִלְלַ֥ת אֱלֹהִ֖ים תָּל֑וּי וְ⁠לֹ֤א תְטַמֵּא֙ אֶת־אַדְמָ֣תְ⁠ךָ֔ אֲשֶׁר֙ יְהוָ֣ה אֱלֹהֶ֔י⁠ךָ נֹתֵ֥ן לְ⁠ךָ֖ נַחֲלָֽה׃ס","lòʼ-ţáli֨yn nibĕláţ֜⁠wò ʻal-há⁠ʻé֗ẕ kiֽ̇y-qáb֤wòr ţi̇qĕbĕ̇re֨⁠ṅẇ֙ bȧ⁠ẏ֣wòm ha⁠h֔ẇʼ kiֽ̇y-qilĕla֥ţ ʼèlòhi֖ym ţá̇l֑ẇy wĕ⁠lò֤ʼ ţĕtamé̇ʼ֙ ʼeţ-ʼadĕmá֣ţĕ⁠ká֔ ʼàşěr֙ yĕhwá֣h ʼèlòhe֔y⁠ká nòţé֥n lĕ⁠ká֖ naẖàláֽh׃s"],[22,1,"לֹֽא־תִרְאֶה֩ אֶת־שׁ֨וֹר אָחִ֜י⁠ךָ א֤וֹ אֶת־שֵׂי⁠וֹ֙ נִדָּחִ֔ים וְ⁠הִתְעַלַּמְתָּ֖ מֵ⁠הֶ֑ם הָשֵׁ֥ב תְּשִׁיבֵ֖⁠ם לְ⁠אָחִֽי⁠ךָ׃","lòֽʼ-ţirĕʼeh֩ ʼeţ-ş̌֨wòr ʼáẖi֜y⁠ká ʼ֤wò ʼeţ-şé̂y⁠wò֙ nidá̇ẖi֔ym wĕ⁠hiţĕʻalȧmĕţá֖̇ mé⁠he֑m háşé֥̌b ţĕ̇şǐybé֖⁠m lĕ⁠ʼáẖiֽy⁠ká׃"],[22,2,"וְ⁠אִם־לֹ֨א קָר֥וֹב אָחִ֛י⁠ךָ אֵלֶ֖י⁠ךָ וְ⁠לֹ֣א יְדַעְתּ֑⁠וֹ וַ⁠אֲסַפְתּ⁠וֹ֙ אֶל־תּ֣וֹךְ בֵּיתֶ֔⁠ךָ וְ⁠הָיָ֣ה עִמְּ⁠ךָ֗ עַ֣ד דְּרֹ֤שׁ אָחִ֨י⁠ךָ֙ אֹת֔⁠וֹ וַ⁠הֲשֵׁבֹת֖⁠וֹ לֽ⁠וֹ׃","wĕ⁠ʼim-lò֨ʼ qár֥wòb ʼáẖi֛y⁠ká ʼéle֖y⁠ká wĕ⁠lò֣ʼ yĕdaʻĕţ֑̇⁠wò wa⁠ʼàsapĕţ̇⁠wò֙ ʼel-ţ֣̇wòkĕ bé̇yţe֔⁠ká wĕ⁠háyá֣h ʻimĕ̇⁠ká֗ ʻa֣d dĕ̇rò֤ş̌ ʼáẖi֨y⁠ká֙ ʼòţ֔⁠wò wa⁠hàşé̌bòţ֖⁠wò lֽ⁠wò׃"],[22,3,"וְ⁠כֵ֧ן תַּעֲשֶׂ֣ה לַ⁠חֲמֹר֗⁠וֹ וְ⁠כֵ֣ן תַּעֲשֶׂה֮ לְ⁠שִׂמְלָת⁠וֹ֒ וְ⁠כֵ֣ן תַּעֲשֶׂ֜ה לְ⁠כָל־אֲבֵדַ֥ת אָחִ֛י⁠ךָ אֲשֶׁר־תֹּאבַ֥ד מִמֶּ֖⁠נּוּ וּ⁠מְצָאתָ֑⁠הּ לֹ֥א תוּכַ֖ל לְ⁠הִתְעַלֵּֽם׃ס","wĕ⁠ké֧n ţȧʻàşê֣h la⁠ẖàmòr֗⁠wò wĕ⁠ké֣n ţȧʻàşêh֮ lĕ⁠şîmĕláţ⁠wò֒ wĕ⁠ké֣n ţȧʻàşê֜h lĕ⁠kál-ʼàbéda֥ţ ʼáẖi֛y⁠ká ʼàşěr-ţò̇ʼba֥d mimė֖⁠ṅẇ ẇ⁠mĕẕáʼţá֑⁠ḣ lò֥ʼ ţẇka֖l lĕ⁠hiţĕʻaléֽ̇m׃s"],[22,4,"לֹא־תִרְאֶה֩ אֶת־חֲמ֨וֹר אָחִ֜י⁠ךָ א֤וֹ שׁוֹר⁠וֹ֙ נֹפְלִ֣ים בַּ⁠דֶּ֔רֶךְ וְ⁠הִתְעַלַּמְתָּ֖ מֵ⁠הֶ֑ם הָקֵ֥ם תָּקִ֖ים עִמּֽ⁠וֹ׃ס","lòʼ-ţirĕʼeh֩ ʼeţ-ẖàm֨wòr ʼáẖi֜y⁠ká ʼ֤wò ş̌wòr⁠wò֙ nòpĕli֣ym bȧ⁠dė֔rekĕ wĕ⁠hiţĕʻalȧmĕţá֖̇ mé⁠he֑m háqé֥m ţá̇qi֖ym ʻiṁֽ⁠wò׃s"],[22,5,"לֹא־יִהְיֶ֤ה כְלִי־גֶ֨בֶר֙ עַל־אִשָּׁ֔ה וְ⁠לֹא־יִלְבַּ֥שׁ גֶּ֖בֶר שִׂמְלַ֣ת אִשָּׁ֑ה כִּ֧י תוֹעֲבַ֛ת יְהוָ֥ה אֱלֹהֶ֖י⁠ךָ כָּל־עֹ֥שֵׂה אֵֽלֶּה׃פ","lòʼ-yihĕye֤h kĕliy-ge֨ber֙ ʻal-ʼişá̇̌֔h wĕ⁠lòʼ-yilĕbȧ֥ş̌ gė֖ber şîmĕla֣ţ ʼişá֑̇̌h ki֧̇y ţwòʻàba֛ţ yĕhwá֥h ʼèlòhe֖y⁠ká ká̇l-ʻò֥şé̂h ʼéֽlėh׃p"],[22,6,"כִּ֣י יִקָּרֵ֣א קַן־צִפּ֣וֹר ׀ לְ⁠פָנֶ֡י⁠ךָ בַּ⁠דֶּ֜רֶךְ בְּ⁠כָל־עֵ֣ץ ׀ א֣וֹ עַל־הָ⁠אָ֗רֶץ אֶפְרֹחִים֙ א֣וֹ בֵיצִ֔ים וְ⁠הָ⁠אֵ֤ם רֹבֶ֨צֶת֙ עַל־הָֽ⁠אֶפְרֹחִ֔ים א֖וֹ עַל־הַ⁠בֵּיצִ֑ים לֹא־תִקַּ֥ח הָ⁠אֵ֖ם עַל־הַ⁠בָּנִֽים׃","ki֣̇y yiqá̇ré֣ʼ qan-ẕiṗ֣wòr ׀ lĕ⁠páne֡y⁠ká bȧ⁠dė֜rekĕ bĕ̇⁠kál-ʻé֣ẕ ׀ ʼ֣wò ʻal-há⁠ʼá֗reẕ ʼepĕròẖiym֙ ʼ֣wò béyẕi֔ym wĕ⁠há⁠ʼé֤m ròbe֨ẕeţ֙ ʻal-háֽ⁠ʼepĕròẖi֔ym ʼ֖wò ʻal-ha⁠bé̇yẕi֑ym lòʼ-ţiqȧ֥ẖ há⁠ʼé֖m ʻal-ha⁠bá̇niֽym׃"],[22,7,"שַׁלֵּ֤חַ תְּשַׁלַּח֙ אֶת־הָ⁠אֵ֔ם וְ⁠אֶת־הַ⁠בָּנִ֖ים תִּֽקַּֽח־לָ֑⁠ךְ לְמַ֨עַן֙ יִ֣יטַב לָ֔⁠ךְ וְ⁠הַאֲרַכְתָּ֖ יָמִֽים׃ס","şǎlé֤̇ẖa ţĕ̇şǎlȧẖ֙ ʼeţ-há⁠ʼé֔m wĕ⁠ʼeţ-ha⁠bá̇ni֖ym ţiֽ̇qȧֽẖ-lá֑⁠kĕ lĕma֨ʻan֙ yi֣ytab lá֔⁠kĕ wĕ⁠haʼàrakĕţá֖̇ yámiֽym׃s"],[22,8,"כִּ֤י תִבְנֶה֙ בַּ֣יִת חָדָ֔שׁ וְ⁠עָשִׂ֥יתָ מַעֲקֶ֖ה לְ⁠גַגֶּ֑⁠ךָ וְ⁠לֹֽא־תָשִׂ֤ים דָּמִים֙ בְּ⁠בֵיתֶ֔⁠ךָ כִּֽי־יִפֹּ֥ל הַ⁠נֹּפֵ֖ל מִמֶּֽ⁠נּוּ׃ס","ki֤̇y ţibĕneh֙ bȧ֣yiţ ẖádá֔ş̌ wĕ⁠ʻáşî֥yţá maʻàqe֖h lĕ⁠gagė֑⁠ká wĕ⁠lòֽʼ-ţáşî֤ym dá̇miym֙ bĕ̇⁠béyţe֔⁠ká kiֽ̇y-yipò֥̇l ha⁠nò̇pé֖l mimėֽ⁠ṅẇ׃s"],[22,9,"לֹא־תִזְרַ֥ע כַּרְמְ⁠ךָ֖ כִּלְאָ֑יִם פֶּן־תִּקְדַּ֗שׁ הַֽ⁠מְלֵאָ֤ה הַ⁠זֶּ֨רַע֙ אֲשֶׁ֣ר תִּזְרָ֔ע וּ⁠תְבוּאַ֖ת הַ⁠כָּֽרֶם׃ס","lòʼ-ţizĕra֥ʻ kȧrĕmĕ⁠ká֖ ki̇lĕʼá֑yim pėn-ţi̇qĕdȧ֗ş̌ haֽ⁠mĕléʼá֤h ha⁠zė֨raʻ֙ ʼàşě֣r ţi̇zĕrá֔ʻ ẇ⁠ţĕbẇʼa֖ţ ha⁠káֽ̇rem׃s"],[22,10,"לֹֽא־תַחֲרֹ֥שׁ בְּ⁠שׁוֹר־וּ⁠בַ⁠חֲמֹ֖ר יַחְדָּֽו׃ס","lòֽʼ-ţaẖàrò֥ş̌ bĕ̇⁠ş̌wòr-ẇ⁠ba⁠ẖàmò֖r yaẖĕdáֽ̇w׃s"],[22,11,"לֹ֤א תִלְבַּשׁ֙ שַֽׁעַטְנֵ֔ז צֶ֥מֶר וּ⁠פִשְׁתִּ֖ים יַחְדָּֽו׃ס","lò֤ʼ ţilĕbȧş̌֙ şǎֽʻatĕné֔z ẕe֥mer ẇ⁠pişĕ̌ţi֖̇ym yaẖĕdáֽ̇w׃s"],[22,12,"גְּדִלִ֖ים תַּעֲשֶׂה־לָּ֑⁠ךְ עַל־אַרְבַּ֛ע כַּנְפ֥וֹת כְּסוּתְ⁠ךָ֖ אֲשֶׁ֥ר תְּכַסֶּה־בָּֽ⁠הּ׃ס","gĕ̇dili֖ym ţȧʻàşêh-lá֑̇⁠kĕ ʻal-ʼarĕbȧ֛ʻ kȧnĕp֥wòţ kĕ̇sẇţĕ⁠ká֖ ʼàşě֥r ţĕ̇kasėh-báֽ̇⁠ḣ׃s"],[22,13,"כִּֽי־יִקַּ֥ח אִ֖ישׁ אִשָּׁ֑ה וּ⁠בָ֥א אֵלֶ֖י⁠הָ וּ⁠שְׂנֵאָֽ⁠הּ׃","kiֽ̇y-yiqȧ֥ẖ ʼi֖yş̌ ʼişá֑̇̌h ẇ⁠bá֥ʼ ʼéle֖y⁠há ẇ⁠şĕ̂néʼáֽ⁠ḣ׃"],[22,14,"וְ⁠שָׂ֥ם לָ⁠הּ֙ עֲלִילֹ֣ת דְּבָרִ֔ים וְ⁠הוֹצִ֥יא עָלֶ֖י⁠הָ שֵׁ֣ם רָ֑ע וְ⁠אָמַ֗ר אֶת־הָ⁠אִשָּׁ֤ה הַ⁠זֹּאת֙ לָקַ֔חְתִּי וָ⁠אֶקְרַ֣ב אֵלֶ֔י⁠הָ וְ⁠לֹא־מָצָ֥אתִי לָ֖⁠הּ בְּתוּלִֽים׃","wĕ⁠şá֥̂m lá⁠ḣ֙ ʻàliylò֣ţ dĕ̇bári֔ym wĕ⁠hwòẕi֥yʼ ʻále֖y⁠há şé֣̌m rá֑ʻ wĕ⁠ʼáma֗r ʼeţ-há⁠ʼişá֤̇̌h ha⁠zò̇ʼţ֙ láqa֔ẖĕţi̇y wá⁠ʼeqĕra֣b ʼéle֔y⁠há wĕ⁠lòʼ-máẕá֥ʼţiy lá֖⁠ḣ bĕ̇ţẇliֽym׃"],[22,15,"וְ⁠לָקַ֛ח אֲבִ֥י ה⁠נער וְ⁠אִמָּ֑⁠הּ וְ⁠הוֹצִ֜יאוּ אֶת־בְּתוּלֵ֧י ה⁠נער אֶל־זִקְנֵ֥י הָ⁠עִ֖יר הַ⁠שָּֽׁעְרָ⁠ה׃","wĕ⁠láqa֛ẖ ʼàbi֥y h⁠nʻr wĕ⁠ʼimá֑̇⁠ḣ wĕ⁠hwòẕi֜yʼẇ ʼeţ-bĕ̇ţẇlé֧y h⁠nʻr ʼel-ziqĕné֥y há⁠ʻi֖yr ha⁠şáֽ̇̌ʻĕrá⁠h׃"],[22,16,"וְ⁠אָמַ֛ר אֲבִ֥י ה⁠נער אֶל־הַ⁠זְּקֵנִ֑ים אֶת־בִּתִּ֗⁠י נָתַ֜תִּי לָ⁠אִ֥ישׁ הַ⁠זֶּ֛ה לְ⁠אִשָּׁ֖ה וַ⁠יִּשְׂנָאֶֽ⁠הָ׃","wĕ⁠ʼáma֛r ʼàbi֥y h⁠nʻr ʼel-ha⁠zĕ̇qéni֑ym ʼeţ-bi̇ţi̇֗⁠y náţa֜ţi̇y lá⁠ʼi֥yş̌ ha⁠zė֛h lĕ⁠ʼişá֖̇̌h wa⁠yi̇şĕ̂náʼeֽ⁠há׃"],[22,17,"וְ⁠הִנֵּה־ה֡וּא שָׂם֩ עֲלִילֹ֨ת דְּבָרִ֜ים לֵ⁠אמֹ֗ר לֹֽא־מָצָ֤אתִי לְ⁠בִתְּ⁠ךָ֙ בְּתוּלִ֔ים וְ⁠אֵ֖לֶּה בְּתוּלֵ֣י בִתִּ֑⁠י וּ⁠פָֽרְשׂוּ֙ הַ⁠שִּׂמְלָ֔ה לִ⁠פְנֵ֖י זִקְנֵ֥י הָ⁠עִֽיר׃","wĕ⁠hiné̇h-h֡ẇʼ şá̂m֩ ʻàliylò֨ţ dĕ̇bári֜ym lé⁠ʼmò֗r lòֽʼ-máẕá֤ʼţiy lĕ⁠biţĕ̇⁠ká֙ bĕ̇ţẇli֔ym wĕ⁠ʼé֖lėh bĕ̇ţẇlé֣y biţi֑̇⁠y ẇ⁠páֽrĕş̂ẇ֙ ha⁠şi̇̂mĕlá֔h li⁠pĕné֖y ziqĕné֥y há⁠ʻiֽyr׃"],[22,18,"וְ⁠לָֽקְח֛וּ זִקְנֵ֥י הָֽ⁠עִיר־הַ⁠הִ֖וא אֶת־הָ⁠אִ֑ישׁ וְ⁠יִסְּר֖וּ אֹתֽ⁠וֹ׃","wĕ⁠láֽqĕẖ֛ẇ ziqĕné֥y háֽ⁠ʻiyr-ha⁠hi֖wʼ ʼeţ-há⁠ʼi֑yş̌ wĕ⁠yisĕ̇r֖ẇ ʼòţֽ⁠wò׃"],[22,19,"וְ⁠עָנְשׁ֨וּ אֹת֜⁠וֹ מֵ֣אָה כֶ֗סֶף וְ⁠נָתְנוּ֙ לַ⁠אֲבִ֣י הַֽ⁠נַּעֲרָ֔ה כִּ֤י הוֹצִיא֙ שֵׁ֣ם רָ֔ע עַ֖ל בְּתוּלַ֣ת יִשְׂרָאֵ֑ל וְ⁠לֽ⁠וֹ־תִהְיֶ֣ה לְ⁠אִשָּׁ֔ה לֹא־יוּכַ֥ל לְ⁠שַּׁלְּחָ֖⁠הּ כָּל־יָמָֽי⁠ו׃ס","wĕ⁠ʻánĕş̌֨ẇ ʼòţ֜⁠wò mé֣ʼáh ke֗sep wĕ⁠náţĕnẇ֙ la⁠ʼàbi֣y haֽ⁠nȧʻàrá֔h ki֤̇y hwòẕiyʼ֙ şé֣̌m rá֔ʻ ʻa֖l bĕ̇ţẇla֣ţ yişĕ̂ráʼé֑l wĕ⁠lֽ⁠wò-ţihĕye֣h lĕ⁠ʼişá̇̌֔h lòʼ-yẇka֥l lĕ⁠şȧ̌lĕ̇ẖá֖⁠ḣ ká̇l-yámáֽy⁠w׃s"],[22,20,"וְ⁠אִם־אֱמֶ֣ת הָיָ֔ה הַ⁠דָּבָ֖ר הַ⁠זֶּ֑ה לֹא־נִמְצְא֥וּ בְתוּלִ֖ים ל⁠נער׃","wĕ⁠ʼim-ʼème֣ţ háyá֔h ha⁠dá̇bá֖r ha⁠zė֑h lòʼ-nimĕẕĕʼ֥ẇ bĕţẇli֖ym l⁠nʻr׃"],[22,21,"וְ⁠הוֹצִ֨יאוּ אֶת־ה⁠נער אֶל־פֶּ֣תַח בֵּית־אָבִ֗י⁠הָ וּ⁠סְקָלוּ⁠הָ֩ אַנְשֵׁ֨י עִירָ֤⁠הּ בָּ⁠אֲבָנִים֙ וָ⁠מֵ֔תָה כִּֽי־עָשְׂתָ֤ה נְבָלָה֙ בְּ⁠יִשְׂרָאֵ֔ל לִ⁠זְנ֖וֹת בֵּ֣ית אָבִ֑י⁠הָ וּ⁠בִֽעַרְתָּ֥ הָ⁠רָ֖ע מִ⁠קִּרְבֶּֽ⁠ךָ׃ס","wĕ⁠hwòẕi֨yʼẇ ʼeţ-h⁠nʻr ʼel-pė֣ţaẖ bé̇yţ-ʼábi֗y⁠há ẇ⁠sĕqálẇ⁠há֩ ʼanĕşé̌֨y ʻiyrá֤⁠ḣ bá̇⁠ʼàbániym֙ wá⁠mé֔ţáh kiֽ̇y-ʻáşĕ̂ţá֤h nĕbáláh֙ bĕ̇⁠yişĕ̂ráʼé֔l li⁠zĕn֖wòţ bé֣̇yţ ʼábi֑y⁠há ẇ⁠biֽʻarĕţá֥̇ há⁠rá֖ʻ mi⁠qi̇rĕbėֽ⁠ká׃s"],[22,22,"כִּֽי־יִמָּצֵ֨א אִ֜ישׁ שֹׁכֵ֣ב ׀ עִם־אִשָּׁ֣ה בְעֻֽלַת־בַּ֗עַל וּ⁠מֵ֨תוּ֙ גַּם־שְׁנֵי⁠הֶ֔ם הָ⁠אִ֛ישׁ הַ⁠שֹּׁכֵ֥ב עִם־הָ⁠אִשָּׁ֖ה וְ⁠הָ⁠אִשָּׁ֑ה וּ⁠בִֽעַרְתָּ֥ הָ⁠רָ֖ע מִ⁠יִּשְׂרָאֵֽל׃ס","kiֽ̇y-yimá̇ẕé֨ʼ ʼi֜yş̌ şò̌ké֣b ׀ ʻim-ʼişá֣̇̌h bĕʻuֽlaţ-bȧ֗ʻal ẇ⁠mé֨ţẇ֙ gȧm-şĕ̌néy⁠he֔m há⁠ʼi֛yş̌ ha⁠şò̇̌ké֥b ʻim-há⁠ʼişá֖̇̌h wĕ⁠há⁠ʼişá֑̇̌h ẇ⁠biֽʻarĕţá֥̇ há⁠rá֖ʻ mi⁠yi̇şĕ̂ráʼéֽl׃s"],[22,23,"כִּ֤י יִהְיֶה֙ נער בְתוּלָ֔ה מְאֹרָשָׂ֖ה לְ⁠אִ֑ישׁ וּ⁠מְצָאָ֥⁠הּ אִ֛ישׁ בָּ⁠עִ֖יר וְ⁠שָׁכַ֥ב עִמָּֽ⁠הּ׃","ki֤̇y yihĕyeh֙ nʻr bĕţẇlá֔h mĕʼòráşá֖̂h lĕ⁠ʼi֑yş̌ ẇ⁠mĕẕáʼá֥⁠ḣ ʼi֛yş̌ bá̇⁠ʻi֖yr wĕ⁠şá̌ka֥b ʻimáֽ̇⁠ḣ׃"],[22,24,"וְ⁠הוֹצֵאתֶ֨ם אֶת־שְׁנֵי⁠הֶ֜ם אֶל־שַׁ֣עַר ׀ הָ⁠עִ֣יר הַ⁠הִ֗וא וּ⁠סְקַלְתֶּ֨ם אֹתָ֥⁠ם בָּ⁠אֲבָנִים֮ וָ⁠מֵתוּ֒ אֶת־ה⁠נער עַל־דְּבַר֙ אֲשֶׁ֣ר לֹא־צָעֲקָ֣ה בָ⁠עִ֔יר וְ⁠אֶ֨ת־הָ⁠אִ֔ישׁ עַל־דְּבַ֥ר אֲשֶׁר־עִנָּ֖ה אֶת־אֵ֣שֶׁת רֵעֵ֑⁠הוּ וּ⁠בִֽעַרְתָּ֥ הָ⁠רָ֖ע מִ⁠קִּרְבֶּֽ⁠ךָ׃ס","wĕ⁠hwòẕéʼţe֨m ʼeţ-şĕ̌néy⁠he֜m ʼel-şǎ֣ʻar ׀ há⁠ʻi֣yr ha⁠hi֗wʼ ẇ⁠sĕqalĕţė֨m ʼòţá֥⁠m bá̇⁠ʼàbániym֮ wá⁠méţẇ֒ ʼeţ-h⁠nʻr ʻal-dĕ̇bar֙ ʼàşě֣r lòʼ-ẕáʻàqá֣h bá⁠ʻi֔yr wĕ⁠ʼe֨ţ-há⁠ʼi֔yş̌ ʻal-dĕ̇ba֥r ʼàşěr-ʻiná֖̇h ʼeţ-ʼé֣şěţ réʻé֑⁠hẇ ẇ⁠biֽʻarĕţá֥̇ há⁠rá֖ʻ mi⁠qi̇rĕbėֽ⁠ká׃s"],[22,25,"וְֽ⁠אִם־בַּ⁠שָּׂדֶ֞ה יִמְצָ֣א הָ⁠אִ֗ישׁ אֶת־הנער הַ⁠מְאֹ֣רָשָׂ֔ה וְ⁠הֶחֱזִֽיק־בָּ֥⁠הּ הָ⁠אִ֖ישׁ וְ⁠שָׁכַ֣ב עִמָּ֑⁠הּ וּ⁠מֵ֗ת הָ⁠אִ֛ישׁ אֲשֶׁר־שָׁכַ֥ב עִמָּ֖⁠הּ לְ⁠בַדּֽ⁠וֹ׃","wĕֽ⁠ʼim-bȧ⁠şá̇̂de֞h yimĕẕá֣ʼ há⁠ʼi֗yş̌ ʼeţ-hnʻr ha⁠mĕʼò֣ráşá̂֔h wĕ⁠heẖèziֽyq-bá֥̇⁠ḣ há⁠ʼi֖yş̌ wĕ⁠şá̌ka֣b ʻimá֑̇⁠ḣ ẇ⁠mé֗ţ há⁠ʼi֛yş̌ ʼàşěr-şá̌ka֥b ʻimá֖̇⁠ḣ lĕ⁠baḋֽ⁠wò׃"],[22,26,"ו⁠ל⁠נער לֹא־תַעֲשֶׂ֣ה דָבָ֔ר אֵ֥ין לנער חֵ֣טְא מָ֑וֶת כִּ֡י כַּ⁠אֲשֶׁר֩ יָק֨וּם אִ֤ישׁ עַל־רֵעֵ֨⁠הוּ֙ וּ⁠רְצָח֣⁠וֹ נֶ֔פֶשׁ כֵּ֖ן הַ⁠דָּבָ֥ר הַ⁠זֶּֽה׃","w⁠l⁠nʻr lòʼ-ţaʻàşê֣h dábá֔r ʼé֥yn lnʻr ẖé֣tĕʼ má֑weţ ki̇֡y kȧ⁠ʼàşěr֩ yáq֨ẇm ʼi֤yş̌ ʻal-réʻé֨⁠hẇ֙ ẇ⁠rĕẕáẖ֣⁠wò ne֔peş̌ ké֖̇n ha⁠dá̇bá֥r ha⁠zėֽh׃"],[22,27,"כִּ֥י בַ⁠שָּׂדֶ֖ה מְצָאָ֑⁠הּ צָעֲקָ֗ה הנער הַ⁠מְאֹ֣רָשָׂ֔ה וְ⁠אֵ֥ין מוֹשִׁ֖יעַ לָֽ⁠הּ׃ס","ki֥̇y ba⁠şá̇̂de֖h mĕẕáʼá֑⁠ḣ ẕáʻàqá֗h hnʻr ha⁠mĕʼò֣ráşá̂֔h wĕ⁠ʼé֥yn mwòşǐ֖yʻa láֽ⁠ḣ׃s"],[22,28,"כִּֽי־יִמְצָ֣א אִ֗ישׁ נער בְתוּלָה֙ אֲשֶׁ֣ר לֹא־אֹרָ֔שָׂה וּ⁠תְפָשָׂ֖⁠הּ וְ⁠שָׁכַ֣ב עִמָּ֑⁠הּ וְ⁠נִמְצָֽאוּ׃","kiֽ̇y-yimĕẕá֣ʼ ʼi֗yş̌ nʻr bĕţẇláh֙ ʼàşě֣r lòʼ-ʼòrá֔şá̂h ẇ⁠ţĕpáşá֖̂⁠ḣ wĕ⁠şá̌ka֣b ʻimá֑̇⁠ḣ wĕ⁠nimĕẕáֽʼẇ׃"],[22,29,"וְ֠⁠נָתַן הָ⁠אִ֨ישׁ הַ⁠שֹּׁכֵ֥ב עִמָּ֛⁠הּ לַ⁠אֲבִ֥י ה⁠נער חֲמִשִּׁ֣ים כָּ֑סֶף וְ⁠לֽ⁠וֹ־תִהְיֶ֣ה לְ⁠אִשָּׁ֗ה תַּ֚חַת אֲשֶׁ֣ר עִנָּ֔⁠הּ לֹא־יוּכַ֥ל שַׁלְּחָ֖⁠ה כָּל־יָמָֽי⁠ו׃ס","wĕ֠⁠náţan há⁠ʼi֨yş̌ ha⁠şò̇̌ké֥b ʻimá֛̇⁠ḣ la⁠ʼàbi֥y h⁠nʻr ẖàmişi֣̇̌ym ká֑̇sep wĕ⁠lֽ⁠wò-ţihĕye֣h lĕ⁠ʼişá̇̌֗h ţȧ֚ẖaţ ʼàşě֣r ʻiná̇֔⁠ḣ lòʼ-yẇka֥l şǎlĕ̇ẖá֖⁠h ká̇l-yámáֽy⁠w׃s"],[22,30,"לֹא־יִקַּ֥ח אִ֖ישׁ אֶת־אֵ֣שֶׁת אָבִ֑י⁠ו וְ⁠לֹ֥א יְגַלֶּ֖ה כְּנַ֥ף אָבִֽי⁠ו׃ס","lòʼ-yiqȧ֥ẖ ʼi֖yş̌ ʼeţ-ʼé֣şěţ ʼábi֑y⁠w wĕ⁠lò֥ʼ yĕgalė֖h kĕ̇na֥p ʼábiֽy⁠w׃s"],[23,1,"לֹֽא־יָבֹ֧א פְצֽוּעַ־דַּכָּ֛א וּ⁠כְר֥וּת שָׁפְכָ֖ה בִּ⁠קְהַ֥ל יְהוָֽה׃ס","lòֽʼ-yábò֧ʼ pĕẕֽẇʻa-dȧká֛̇ʼ ẇ⁠kĕr֥ẇţ şá̌pĕká֖h bi̇⁠qĕha֥l yĕhwáֽh׃s"],[23,2,"לֹא־יָבֹ֥א מַמְזֵ֖ר בִּ⁠קְהַ֣ל יְהוָ֑ה גַּ֚ם דּ֣וֹר עֲשִׂירִ֔י לֹא־יָ֥בֹא ל֖⁠וֹ בִּ⁠קְהַ֥ל יְהוָֽה׃ס","lòʼ-yábò֥ʼ mamĕzé֖r bi̇⁠qĕha֣l yĕhwá֑h gȧ֚m ḋ֣wòr ʻàşîyri֔y lòʼ-yá֥bòʼ l֖⁠wò bi̇⁠qĕha֥l yĕhwáֽh׃s"],[23,3,"לֹֽא־יָבֹ֧א עַמּוֹנִ֛י וּ⁠מוֹאָבִ֖י בִּ⁠קְהַ֣ל יְהוָ֑ה גַּ֚ם דּ֣וֹר עֲשִׂירִ֔י לֹא־יָבֹ֥א לָ⁠הֶ֛ם בִּ⁠קְהַ֥ל יְהוָ֖ה עַד־עוֹלָֽם׃","lòֽʼ-yábò֧ʼ ʻaṁwòni֛y ẇ⁠mwòʼábi֖y bi̇⁠qĕha֣l yĕhwá֑h gȧ֚m ḋ֣wòr ʻàşîyri֔y lòʼ-yábò֥ʼ lá⁠he֛m bi̇⁠qĕha֥l yĕhwá֖h ʻad-ʻwòláֽm׃"],[23,4,"עַל־דְּבַ֞ר אֲשֶׁ֨ר לֹא־קִדְּמ֤וּ אֶתְ⁠כֶם֙ בַּ⁠לֶּ֣חֶם וּ⁠בַ⁠מַּ֔יִם בַּ⁠דֶּ֖רֶךְ בְּ⁠צֵאתְ⁠כֶ֣ם מִ⁠מִּצְרָ֑יִם וַ⁠אֲשֶׁר֩ שָׂכַ֨ר עָלֶ֜י⁠ךָ אֶת־בִּלְעָ֣ם בֶּן־בְּע֗וֹר מִ⁠פְּת֛וֹר אֲרַ֥ם נַהֲרַ֖יִם לְ⁠קַֽלְלֶֽ⁠ךָּ׃","ʻal-dĕ̇ba֞r ʼàşě֨r lòʼ-qidĕ̇m֤ẇ ʼeţĕ⁠kem֙ bȧ⁠lė֣ẖem ẇ⁠ba⁠mȧ֔yim bȧ⁠dė֖rekĕ bĕ̇⁠ẕéʼţĕ⁠ke֣m mi⁠mi̇ẕĕrá֑yim wa⁠ʼàşěr֩ şá̂ka֨r ʻále֜y⁠ká ʼeţ-bi̇lĕʻá֣m bėn-bĕ̇ʻ֗wòr mi⁠pĕ̇ţ֛wòr ʼàra֥m nahàra֖yim lĕ⁠qaֽlĕleֽ⁠ká̇׃"],[23,5,"וְ⁠לֹֽא־אָבָ֞ה יְהוָ֤ה אֱלֹהֶ֨י⁠ךָ֙ לִ⁠שְׁמֹ֣עַ אֶל־בִּלְעָ֔ם וַ⁠יַּהֲפֹךְ֩ יְהוָ֨ה אֱלֹהֶ֧י⁠ךָ לְּ⁠ךָ֛ אֶת־הַ⁠קְּלָלָ֖ה לִ⁠בְרָכָ֑ה כִּ֥י אֲהֵֽבְ⁠ךָ֖ יְהוָ֥ה אֱלֹהֶֽי⁠ךָ׃","wĕ⁠lòֽʼ-ʼábá֞h yĕhwá֤h ʼèlòhe֨y⁠ká֙ li⁠şĕ̌mò֣ʻa ʼel-bi̇lĕʻá֔m wa⁠yȧhàpòkĕ֩ yĕhwá֨h ʼèlòhe֧y⁠ká lĕ̇⁠ká֛ ʼeţ-ha⁠qĕ̇lálá֖h li⁠bĕráká֑h ki֥̇y ʼàhéֽbĕ⁠ká֖ yĕhwá֥h ʼèlòheֽy⁠ká׃"],[23,6,"לֹא־תִדְרֹ֥שׁ שְׁלֹמָ֖⁠ם וְ⁠טֹבָתָ֑⁠ם כָּל־יָמֶ֖י⁠ךָ לְ⁠עוֹלָֽם׃ס","lòʼ-ţidĕrò֥ş̌ şĕ̌lòmá֖⁠m wĕ⁠tòbáţá֑⁠m ká̇l-yáme֖y⁠ká lĕ⁠ʻwòláֽm׃s"],[23,7,"לֹֽא־תְתַעֵ֣ב אֲדֹמִ֔י כִּ֥י אָחִ֖י⁠ךָ ה֑וּא ס לֹא־תְתַעֵ֣ב מִצְרִ֔י כִּי־גֵ֖ר הָיִ֥יתָ בְ⁠אַרְצֽ⁠וֹ׃","lòֽʼ-ţĕţaʻé֣b ʼàdòmi֔y ki֥̇y ʼáẖi֖y⁠ká h֑ẇʼ s lòʼ-ţĕţaʻé֣b miẕĕri֔y ki̇y-gé֖r háyi֥yţá bĕ⁠ʼarĕẕֽ⁠wò׃"],[23,8,"בָּנִ֛ים אֲשֶׁר־יִוָּלְד֥וּ לָ⁠הֶ֖ם דּ֣וֹר שְׁלִישִׁ֑י יָבֹ֥א לָ⁠הֶ֖ם בִּ⁠קְהַ֥ל יְהוָֽה׃ס","bá̇ni֛ym ʼàşěr-yiwá̇lĕd֥ẇ lá⁠he֖m ḋ֣wòr şĕ̌liyşǐ֑y yábò֥ʼ lá⁠he֖m bi̇⁠qĕha֥l yĕhwáֽh׃s"],[23,9,"כִּֽי־תֵצֵ֥א מַחֲנֶ֖ה עַל־אֹיְבֶ֑י⁠ךָ וְ⁠נִ֨שְׁמַרְתָּ֔ מִ⁠כֹּ֖ל דָּבָ֥ר רָֽע׃","kiֽ̇y-ţéẕé֥ʼ maẖàne֖h ʻal-ʼòyĕbe֑y⁠ká wĕ⁠ni֨şĕ̌marĕţá̇֔ mi⁠kò֖̇l dá̇bá֥r ráֽʻ׃"],[23,10,"כִּֽי־יִהְיֶ֤ה בְ⁠ךָ֙ אִ֔ישׁ אֲשֶׁ֛ר לֹא־יִהְיֶ֥ה טָה֖וֹר מִ⁠קְּרֵה־לָ֑יְלָה וְ⁠יָצָא֙ אֶל־מִ⁠ח֣וּץ לַֽ⁠מַּחֲנֶ֔ה לֹ֥א יָבֹ֖א אֶל־תּ֥וֹךְ הַֽ⁠מַּחֲנֶֽה׃","kiֽ̇y-yihĕye֤h bĕ⁠ká֙ ʼi֔yş̌ ʼàşě֛r lòʼ-yihĕye֥h táh֖wòr mi⁠qĕ̇réh-lá֑yĕláh wĕ⁠yáẕáʼ֙ ʼel-mi⁠ẖ֣ẇẕ laֽ⁠mȧẖàne֔h lò֥ʼ yábò֖ʼ ʼel-ţ֥̇wòkĕ haֽ⁠mȧẖàneֽh׃"],[23,11,"וְ⁠הָיָ֥ה לִ⁠פְנֽוֹת־עֶ֖רֶב יִרְחַ֣ץ בַּ⁠מָּ֑יִם וּ⁠כְ⁠בֹ֣א הַ⁠שֶּׁ֔מֶשׁ יָבֹ֖א אֶל־תּ֥וֹךְ הַֽ⁠מַּחֲנֶה׃","wĕ⁠háyá֥h li⁠pĕnֽwòţ-ʻe֖reb yirĕẖa֣ẕ bȧ⁠má֑̇yim ẇ⁠kĕ⁠bò֣ʼ ha⁠şė̌֔meş̌ yábò֖ʼ ʼel-ţ֥̇wòkĕ haֽ⁠mȧẖàneh׃"],[23,12,"וְ⁠יָד֙ תִּהְיֶ֣ה לְ⁠ךָ֔ מִ⁠ח֖וּץ לַֽ⁠מַּחֲנֶ֑ה וְ⁠יָצָ֥אתָ שָׁ֖מָּ⁠ה חֽוּץ׃","wĕ⁠yád֙ ţi̇hĕye֣h lĕ⁠ká֔ mi⁠ẖ֖ẇẕ laֽ⁠mȧẖàne֑h wĕ⁠yáẕá֥ʼţá şá֖̌má̇⁠h ẖֽẇẕ׃"],[23,13,"וְ⁠יָתֵ֛ד תִּהְיֶ֥ה לְ⁠ךָ֖ עַל־אֲזֵנֶ֑⁠ךָ וְ⁠הָיָה֙ בְּ⁠שִׁבְתְּ⁠ךָ֣ ח֔וּץ וְ⁠חָפַרְתָּ֣ה בָ֔⁠הּ וְ⁠שַׁבְתָּ֖ וְ⁠כִסִּ֥יתָ אֶת־צֵאָתֶֽ⁠ךָ׃","wĕ⁠yáţé֛d ţi̇hĕye֥h lĕ⁠ká֖ ʻal-ʼàzéne֑⁠ká wĕ⁠háyáh֙ bĕ̇⁠şǐbĕţĕ̇⁠ká֣ ẖ֔ẇẕ wĕ⁠ẖáparĕţá֣̇h bá֔⁠ḣ wĕ⁠şǎbĕţá֖̇ wĕ⁠kisi֥̇yţá ʼeţ-ẕéʼáţeֽ⁠ká׃"],[23,14,"כִּי֩ יְהוָ֨ה אֱלֹהֶ֜י⁠ךָ מִתְהַלֵּ֣ךְ ׀ בְּ⁠קֶ֣רֶב מַחֲנֶ֗⁠ךָ לְ⁠הַצִּֽילְ⁠ךָ֙ וְ⁠לָ⁠תֵ֤ת אֹיְבֶ֨י⁠ךָ֙ לְ⁠פָנֶ֔י⁠ךָ וְ⁠הָיָ֥ה מַחֲנֶ֖י⁠ךָ קָד֑וֹשׁ וְ⁠לֹֽא־יִרְאֶ֤ה בְ⁠ךָ֙ עֶרְוַ֣ת דָּבָ֔ר וְ⁠שָׁ֖ב מֵ⁠אַחֲרֶֽי⁠ךָ׃ס","ki̇y֩ yĕhwá֨h ʼèlòhe֜y⁠ká miţĕhalé֣̇kĕ ׀ bĕ̇⁠qe֣reb maẖàne֗⁠ká lĕ⁠haẕiֽ̇ylĕ⁠ká֙ wĕ⁠lá⁠ţé֤ţ ʼòyĕbe֨y⁠ká֙ lĕ⁠páne֔y⁠ká wĕ⁠háyá֥h maẖàne֖y⁠ká qád֑wòş̌ wĕ⁠lòֽʼ-yirĕʼe֤h bĕ⁠ká֙ ʻerĕwa֣ţ dá̇bá֔r wĕ⁠şá֖̌b mé⁠ʼaẖàreֽy⁠ká׃s"],[23,15,"לֹא־תַסְגִּ֥יר עֶ֖בֶד אֶל־אֲדֹנָ֑י⁠ו אֲשֶׁר־יִנָּצֵ֥ל אֵלֶ֖י⁠ךָ מֵ⁠עִ֥ם אֲדֹנָֽי⁠ו׃","lòʼ-ţasĕgi֥̇yr ʻe֖bed ʼel-ʼàdòná֑y⁠w ʼàşěr-yiná̇ẕé֥l ʼéle֖y⁠ká mé⁠ʻi֥m ʼàdònáֽy⁠w׃"],[23,16,"עִמְּ⁠ךָ֞ יֵשֵׁ֣ב בְּ⁠קִרְבְּ⁠ךָ֗ בַּ⁠מָּק֧וֹם אֲשֶׁר־יִבְחַ֛ר בְּ⁠אַחַ֥ד שְׁעָרֶ֖י⁠ךָ בַּ⁠טּ֣וֹב ל֑⁠וֹ לֹ֖א תּוֹנֶֽ⁠נּוּ׃ס","ʻimĕ̇⁠ká֞ yéşé֣̌b bĕ̇⁠qirĕbĕ̇⁠ká֗ bȧ⁠má̇q֧wòm ʼàşěr-yibĕẖa֛r bĕ̇⁠ʼaẖa֥d şĕ̌ʻáre֖y⁠ká bȧ⁠ṫ֣wòb l֑⁠wò lò֖ʼ ţ̇wòneֽ⁠ṅẇ׃s"],[23,17,"לֹא־תִהְיֶ֥ה קְדֵשָׁ֖ה מִ⁠בְּנ֣וֹת יִשְׂרָאֵ֑ל וְ⁠לֹֽא־יִהְיֶ֥ה קָדֵ֖שׁ מִ⁠בְּנֵ֥י יִשְׂרָאֵל׃","lòʼ-ţihĕye֥h qĕdéşá֖̌h mi⁠bĕ̇n֣wòţ yişĕ̂ráʼé֑l wĕ⁠lòֽʼ-yihĕye֥h qádé֖ş̌ mi⁠bĕ̇né֥y yişĕ̂ráʼél׃"],[23,18,"לֹא־תָבִיא֩ אֶתְנַ֨ן זוֹנָ֜ה וּ⁠מְחִ֣יר כֶּ֗לֶב בֵּ֛ית יְהוָ֥ה אֱלֹהֶ֖י⁠ךָ לְ⁠כָל־נֶ֑דֶר כִּ֧י תוֹעֲבַ֛ת יְהוָ֥ה אֱלֹהֶ֖י⁠ךָ גַּם־שְׁנֵי⁠הֶֽם׃","lòʼ-ţábiyʼ֩ ʼeţĕna֨n zwòná֜h ẇ⁠mĕẖi֣yr kė֗leb bé֛̇yţ yĕhwá֥h ʼèlòhe֖y⁠ká lĕ⁠kál-ne֑der ki֧̇y ţwòʻàba֛ţ yĕhwá֥h ʼèlòhe֖y⁠ká gȧm-şĕ̌néy⁠heֽm׃"],[23,19,"לֹא־תַשִּׁ֣יךְ לְ⁠אָחִ֔י⁠ךָ נֶ֥שֶׁךְ כֶּ֖סֶף נֶ֣שֶׁךְ אֹ֑כֶל נֶ֕שֶׁךְ כָּל־דָּבָ֖ר אֲשֶׁ֥ר יִשָּֽׁךְ׃","lòʼ-ţaşi֣̇̌ykĕ lĕ⁠ʼáẖi֔y⁠ká ne֥şěkĕ kė֖sep ne֣şěkĕ ʼò֑kel ne֕şěkĕ ká̇l-dá̇bá֖r ʼàşě֥r yişáֽ̇̌kĕ׃"],[23,20,"לַ⁠נָּכְרִ֣י תַשִּׁ֔יךְ וּ⁠לְ⁠אָחִ֖י⁠ךָ לֹ֣א תַשִּׁ֑יךְ לְמַ֨עַן יְבָרֶכְ⁠ךָ֜ יְהוָ֣ה אֱלֹהֶ֗י⁠ךָ בְּ⁠כֹל֙ מִשְׁלַ֣ח יָדֶ֔⁠ךָ עַל־הָ⁠אָ֕רֶץ אֲשֶׁר־אַתָּ֥ה בָא־שָׁ֖מָּ⁠ה לְ⁠רִשְׁתָּֽ⁠הּ׃ס","la⁠ná̇kĕri֣y ţaşi̇̌֔ykĕ ẇ⁠lĕ⁠ʼáẖi֖y⁠ká lò֣ʼ ţaşi֑̇̌ykĕ lĕma֨ʻan yĕbárekĕ⁠ká֜ yĕhwá֣h ʼèlòhe֗y⁠ká bĕ̇⁠kòl֙ mişĕ̌la֣ẖ yáde֔⁠ká ʻal-há⁠ʼá֕reẕ ʼàşěr-ʼaţá֥̇h báʼ-şá֖̌má̇⁠h lĕ⁠rişĕ̌ţáֽ̇⁠ḣ׃s"],[23,21,"כִּֽי־תִדֹּ֥ר נֶ֨דֶר֙ לַ⁠יהוָ֣ה אֱלֹהֶ֔י⁠ךָ לֹ֥א תְאַחֵ֖ר לְ⁠שַׁלְּמ֑⁠וֹ כִּֽי־דָּרֹ֨שׁ יִדְרְשֶׁ֜⁠נּוּ יְהוָ֤ה אֱלֹהֶ֨י⁠ךָ֙ מֵֽ⁠עִמָּ֔⁠ךְ וְ⁠הָיָ֥ה בְ⁠ךָ֖ חֵֽטְא׃","kiֽ̇y-ţidò֥̇r ne֨der֙ la⁠yhwá֣h ʼèlòhe֔y⁠ká lò֥ʼ ţĕʼaẖé֖r lĕ⁠şǎlĕ̇m֑⁠wò kiֽ̇y-dá̇rò֨ş̌ yidĕrĕşě֜⁠ṅẇ yĕhwá֤h ʼèlòhe֨y⁠ká֙ méֽ⁠ʻimá̇֔⁠kĕ wĕ⁠háyá֥h bĕ⁠ká֖ ẖéֽtĕʼ׃"],[23,22,"וְ⁠כִ֥י תֶחְדַּ֖ל לִ⁠נְדֹּ֑ר לֹֽא־יִהְיֶ֥ה בְ⁠ךָ֖ חֵֽטְא׃","wĕ⁠ki֥y ţeẖĕdȧ֖l li⁠nĕdò֑̇r lòֽʼ-yihĕye֥h bĕ⁠ká֖ ẖéֽtĕʼ׃"],[23,23,"מוֹצָ֥א שְׂפָתֶ֖י⁠ךָ תִּשְׁמֹ֣ר וְ⁠עָשִׂ֑יתָ כַּ⁠אֲשֶׁ֨ר נָדַ֜רְתָּ לַ⁠יהוָ֤ה אֱלֹהֶ֨י⁠ךָ֙ נְדָבָ֔ה אֲשֶׁ֥ר דִּבַּ֖רְתָּ בְּ⁠פִֽי⁠ךָ׃ס","mwòẕá֥ʼ şĕ̂páţe֖y⁠ká ţi̇şĕ̌mò֣r wĕ⁠ʻáşî֑yţá kȧ⁠ʼàşě֨r náda֜rĕţá̇ la⁠yhwá֤h ʼèlòhe֨y⁠ká֙ nĕdábá֔h ʼàşě֥r di̇bȧ֖rĕţá̇ bĕ̇⁠piֽy⁠ká׃s"],[23,24,"כִּ֤י תָבֹא֙ בְּ⁠כֶ֣רֶם רֵעֶ֔⁠ךָ וְ⁠אָכַלְתָּ֧ עֲנָבִ֛ים כְּ⁠נַפְשְׁ⁠ךָ֖ שָׂבְעֶ֑⁠ךָ וְ⁠אֶֽל־כֶּלְיְ⁠ךָ֖ לֹ֥א תִתֵּֽן׃ס","ki֤̇y ţábòʼ֙ bĕ̇⁠ke֣rem réʻe֔⁠ká wĕ⁠ʼákalĕţá֧̇ ʻànábi֛ym kĕ̇⁠napĕşĕ̌⁠ká֖ şá̂bĕʻe֑⁠ká wĕ⁠ʼeֽl-kėlĕyĕ⁠ká֖ lò֥ʼ ţiţéֽ̇n׃s"],[23,25,"כִּ֤י תָבֹא֙ בְּ⁠קָמַ֣ת רֵעֶ֔⁠ךָ וְ⁠קָטַפְתָּ֥ מְלִילֹ֖ת בְּ⁠יָדֶ֑⁠ךָ וְ⁠חֶרְמֵשׁ֙ לֹ֣א תָנִ֔יף עַ֖ל קָמַ֥ת רֵעֶֽ⁠ךָ׃ס","ki֤̇y ţábòʼ֙ bĕ̇⁠qáma֣ţ réʻe֔⁠ká wĕ⁠qátapĕţá֥̇ mĕliylò֖ţ bĕ̇⁠yáde֑⁠ká wĕ⁠ẖerĕméş̌֙ lò֣ʼ ţáni֔yp ʻa֖l qáma֥ţ réʻeֽ⁠ká׃s"],[24,1,"כִּֽי־יִקַּ֥ח אִ֛ישׁ אִשָּׁ֖ה וּ⁠בְעָלָ֑⁠הּ וְ⁠הָיָ֞ה אִם־לֹ֧א תִמְצָא־חֵ֣ן בְּ⁠עֵינָ֗י⁠ו כִּי־מָ֤צָא בָ⁠הּ֙ עֶרְוַ֣ת דָּבָ֔ר וְ⁠כָ֨תַב לָ֜⁠הּ סֵ֤פֶר כְּרִיתֻת֙ וְ⁠נָתַ֣ן בְּ⁠יָדָ֔⁠הּ וְ⁠שִׁלְּחָ֖⁠הּ מִ⁠בֵּיתֽ⁠וֹ׃","kiֽ̇y-yiqȧ֥ẖ ʼi֛yş̌ ʼişá֖̇̌h ẇ⁠bĕʻálá֑⁠ḣ wĕ⁠háyá֞h ʼim-lò֧ʼ ţimĕẕáʼ-ẖé֣n bĕ̇⁠ʻéyná֗y⁠w ki̇y-má֤ẕáʼ bá⁠ḣ֙ ʻerĕwa֣ţ dá̇bá֔r wĕ⁠ká֨ţab lá֜⁠ḣ sé֤per kĕ̇riyţuţ֙ wĕ⁠náţa֣n bĕ̇⁠yádá֔⁠ḣ wĕ⁠şǐlĕ̇ẖá֖⁠ḣ mi⁠bé̇yţֽ⁠wò׃"],[24,2,"וְ⁠יָצְאָ֖ה מִ⁠בֵּית֑⁠וֹ וְ⁠הָלְכָ֖ה וְ⁠הָיְתָ֥ה לְ⁠אִישׁ־אַחֵֽר׃","wĕ⁠yáẕĕʼá֖h mi⁠bé̇yţ֑⁠wò wĕ⁠hálĕká֖h wĕ⁠háyĕţá֥h lĕ⁠ʼiyş̌-ʼaẖéֽr׃"],[24,3,"וּ⁠שְׂנֵאָ⁠הּ֮ הָ⁠אִ֣ישׁ הָ⁠אַחֲרוֹן֒ וְ⁠כָ֨תַב לָ֜⁠הּ סֵ֤פֶר כְּרִיתֻת֙ וְ⁠נָתַ֣ן בְּ⁠יָדָ֔⁠הּ וְ⁠שִׁלְּחָ֖⁠הּ מִ⁠בֵּית֑⁠וֹ א֣וֹ כִ֤י יָמוּת֙ הָ⁠אִ֣ישׁ הָ⁠אַחֲר֔וֹן אֲשֶׁר־לְקָחָ֥⁠הּ ל֖⁠וֹ לְ⁠אִשָּֽׁה׃","ẇ⁠şĕ̂néʼá⁠ḣ֮ há⁠ʼi֣yş̌ há⁠ʼaẖàrwòn֒ wĕ⁠ká֨ţab lá֜⁠ḣ sé֤per kĕ̇riyţuţ֙ wĕ⁠náţa֣n bĕ̇⁠yádá֔⁠ḣ wĕ⁠şǐlĕ̇ẖá֖⁠ḣ mi⁠bé̇yţ֑⁠wò ʼ֣wò ki֤y yámẇţ֙ há⁠ʼi֣yş̌ há⁠ʼaẖàr֔wòn ʼàşěr-lĕqáẖá֥⁠ḣ l֖⁠wò lĕ⁠ʼişáֽ̇̌h׃"],[24,4,"לֹא־יוּכַ֣ל בַּעְלָ֣⁠הּ הָ⁠רִאשׁ֣וֹן אֲשֶֽׁר־שִׁ֠לְּחָ⁠הּ לָ⁠שׁ֨וּב לְ⁠קַחְתָּ֜⁠הּ לִ⁠הְי֧וֹת ל֣⁠וֹ לְ⁠אִשָּׁ֗ה אַחֲרֵי֙ אֲשֶׁ֣ר הֻטַּמָּ֔אָה כִּֽי־תוֹעֵבָ֥ה הִ֖וא לִ⁠פְנֵ֣י יְהוָ֑ה וְ⁠לֹ֤א תַחֲטִיא֙ אֶת־הָ⁠אָ֔רֶץ אֲשֶׁר֙ יְהוָ֣ה אֱלֹהֶ֔י⁠ךָ נֹתֵ֥ן לְ⁠ךָ֖ נַחֲלָֽה׃ס","lòʼ-yẇka֣l bȧʻĕlá֣⁠ḣ há⁠riʼş֣̌wòn ʼàşěֽr-şǐ֠lĕ̇ẖá⁠ḣ lá⁠ş̌֨ẇb lĕ⁠qaẖĕţá̇֜⁠ḣ li⁠hĕy֧wòţ l֣⁠wò lĕ⁠ʼişá̇̌֗h ʼaẖàréy֙ ʼàşě֣r hutȧmá̇֔ʼáh kiֽ̇y-ţwòʻébá֥h hi֖wʼ li⁠pĕné֣y yĕhwá֑h wĕ⁠lò֤ʼ ţaẖàtiyʼ֙ ʼeţ-há⁠ʼá֔reẕ ʼàşěr֙ yĕhwá֣h ʼèlòhe֔y⁠ká nòţé֥n lĕ⁠ká֖ naẖàláֽh׃s"],[24,5,"כִּֽי־יִקַּ֥ח אִישׁ֙ אִשָּׁ֣ה חֲדָשָׁ֔ה לֹ֤א יֵצֵא֙ בַּ⁠צָּבָ֔א וְ⁠לֹא־יַעֲבֹ֥ר עָלָ֖י⁠ו לְ⁠כָל־דָּבָ֑ר נָקִ֞י יִהְיֶ֤ה לְ⁠בֵית⁠וֹ֙ שָׁנָ֣ה אֶחָ֔ת וְ⁠שִׂמַּ֖ח אֶת־אִשְׁתּ֥⁠וֹ אֲשֶׁר־לָקָֽח׃ס","kiֽ̇y-yiqȧ֥ẖ ʼiyş̌֙ ʼişá֣̇̌h ẖàdáşá̌֔h lò֤ʼ yéẕéʼ֙ bȧ⁠ẕá̇bá֔ʼ wĕ⁠lòʼ-yaʻàbò֥r ʻálá֖y⁠w lĕ⁠kál-dá̇bá֑r náqi֞y yihĕye֤h lĕ⁠béyţ⁠wò֙ şá̌ná֣h ʼeẖá֔ţ wĕ⁠şîmȧ֖ẖ ʼeţ-ʼişĕ̌ţ֥̇⁠wò ʼàşěr-láqáֽẖ׃s"],[24,6,"לֹא־יַחֲבֹ֥ל רֵחַ֖יִם וָ⁠רָ֑כֶב כִּי־נֶ֖פֶשׁ ה֥וּא חֹבֵֽל׃ס","lòʼ-yaẖàbò֥l réẖa֖yim wá⁠rá֑keb ki̇y-ne֖peş̌ h֥ẇʼ ẖòbéֽl׃s"],[24,7,"כִּי־יִמָּצֵ֣א אִ֗ישׁ גֹּנֵ֨ב נֶ֤פֶשׁ מֵ⁠אֶחָי⁠ו֙ מִ⁠בְּנֵ֣י יִשְׂרָאֵ֔ל וְ⁠הִתְעַמֶּר־בּ֖⁠וֹ וּ⁠מְכָר֑⁠וֹ וּ⁠מֵת֙ הַ⁠גַּנָּ֣ב הַ⁠ה֔וּא וּ⁠בִֽעַרְתָּ֥ הָ⁠רָ֖ע מִ⁠קִּרְבֶּֽ⁠ךָ׃","ki̇y-yimá̇ẕé֣ʼ ʼi֗yş̌ gò̇né֨b ne֤peş̌ mé⁠ʼeẖáy⁠w֙ mi⁠bĕ̇né֣y yişĕ̂ráʼé֔l wĕ⁠hiţĕʻamėr-ḃ֖⁠wò ẇ⁠mĕkár֑⁠wò ẇ⁠méţ֙ ha⁠gȧná֣̇b ha⁠h֔ẇʼ ẇ⁠biֽʻarĕţá֥̇ há⁠rá֖ʻ mi⁠qi̇rĕbėֽ⁠ká׃"],[24,8,"הִשָּׁ֧מֶר בְּ⁠נֶֽגַע־הַ⁠צָּרַ֛עַת לִ⁠שְׁמֹ֥ר מְאֹ֖ד וְ⁠לַ⁠עֲשׂ֑וֹת כְּ⁠כֹל֩ אֲשֶׁר־יוֹר֨וּ אֶתְ⁠כֶ֜ם הַ⁠כֹּהֲנִ֧ים הַ⁠לְוִיִּ֛ם כַּ⁠אֲשֶׁ֥ר צִוִּיתִ֖⁠ם תִּשְׁמְר֥וּ לַ⁠עֲשֽׂוֹת׃ס","hişá֧̇̌mer bĕ̇⁠neֽgaʻ-ha⁠ẕá̇ra֛ʻaţ li⁠şĕ̌mò֥r mĕʼò֖d wĕ⁠la⁠ʻàş֑̂wòţ kĕ̇⁠kòl֩ ʼàşěr-ywòr֨ẇ ʼeţĕ⁠ke֜m ha⁠kò̇hàni֧ym ha⁠lĕwiyi֛̇m kȧ⁠ʼàşě֥r ẕiwi̇yţi֖⁠m ţi̇şĕ̌mĕr֥ẇ la⁠ʻàşֽ̂wòţ׃s"],[24,9,"זָכ֕וֹר אֵ֧ת אֲשֶׁר־עָשָׂ֛ה יְהוָ֥ה אֱלֹהֶ֖י⁠ךָ לְ⁠מִרְיָ֑ם בַּ⁠דֶּ֖רֶךְ בְּ⁠צֵאתְ⁠כֶ֥ם מִ⁠מִּצְרָֽיִם׃ס","zák֕wòr ʼé֧ţ ʼàşěr-ʻáşá֛̂h yĕhwá֥h ʼèlòhe֖y⁠ká lĕ⁠mirĕyá֑m bȧ⁠dė֖rekĕ bĕ̇⁠ẕéʼţĕ⁠ke֥m mi⁠mi̇ẕĕráֽyim׃s"],[24,10,"כִּֽי־תַשֶּׁ֥ה בְ⁠רֵֽעֲ⁠ךָ מַשַּׁ֣את מְא֑וּמָה לֹא־תָבֹ֥א אֶל־בֵּית֖⁠וֹ לַ⁠עֲבֹ֥ט עֲבֹטֽ⁠וֹ׃","kiֽ̇y-ţaşė֥̌h bĕ⁠réֽʻà⁠ká maşȧ֣̌ʼţ mĕʼ֑ẇmáh lòʼ-ţábò֥ʼ ʼel-bé̇yţ֖⁠wò la⁠ʻàbò֥t ʻàbòtֽ⁠wò׃"],[24,11,"בַּ⁠ח֖וּץ תַּעֲמֹ֑ד וְ⁠הָ⁠אִ֗ישׁ אֲשֶׁ֤ר אַתָּה֙ נֹשֶׁ֣ה ב֔⁠וֹ יוֹצִ֥יא אֵלֶ֛י⁠ךָ אֶֽת־הַ⁠עֲב֖וֹט הַ⁠חֽוּצָ⁠ה׃","bȧ⁠ẖ֖ẇẕ ţȧʻàmò֑d wĕ⁠há⁠ʼi֗yş̌ ʼàşě֤r ʼaţá̇h֙ nòşě֣h b֔⁠wò ywòẕi֥yʼ ʼéle֛y⁠ká ʼeֽţ-ha⁠ʻàb֖wòt ha⁠ẖֽẇẕá⁠h׃"],[24,12,"וְ⁠אִם־אִ֥ישׁ עָנִ֖י ה֑וּא לֹ֥א תִשְׁכַּ֖ב בַּ⁠עֲבֹטֽ⁠וֹ׃","wĕ⁠ʼim-ʼi֥yş̌ ʻáni֖y h֑ẇʼ lò֥ʼ ţişĕ̌kȧ֖b bȧ⁠ʻàbòtֽ⁠wò׃"],[24,13,"הָשֵׁב֩ תָּשִׁ֨יב ל֤⁠וֹ אֶֽת־הַ⁠עֲבוֹט֙ כְּ⁠בֹ֣א הַ⁠שֶּׁ֔מֶשׁ וְ⁠שָׁכַ֥ב בְּ⁠שַׂלְמָת֖⁠וֹ וּ⁠בֵֽרֲכֶ֑⁠ךָּ וּ⁠לְ⁠ךָ֙ תִּהְיֶ֣ה צְדָקָ֔ה לִ⁠פְנֵ֖י יְהוָ֥ה אֱלֹהֶֽי⁠ךָ׃ס","háşé̌b֩ ţá̇şǐ֨yb l֤⁠wò ʼeֽţ-ha⁠ʻàbwòt֙ kĕ̇⁠bò֣ʼ ha⁠şė̌֔meş̌ wĕ⁠şá̌ka֥b bĕ̇⁠şâlĕmáţ֖⁠wò ẇ⁠béֽràke֑⁠ká̇ ẇ⁠lĕ⁠ká֙ ţi̇hĕye֣h ẕĕdáqá֔h li⁠pĕné֖y yĕhwá֥h ʼèlòheֽy⁠ká׃s"],[24,14,"לֹא־תַעֲשֹׁ֥ק שָׂכִ֖יר עָנִ֣י וְ⁠אֶבְי֑וֹן מֵ⁠אַחֶ֕י⁠ךָ א֧וֹ מִ⁠גֵּרְ⁠ךָ֛ אֲשֶׁ֥ר בְּ⁠אַרְצְ⁠ךָ֖ בִּ⁠שְׁעָרֶֽי⁠ךָ׃","lòʼ-ţaʻàşò֥̌q şá̂ki֖yr ʻáni֣y wĕ⁠ʼebĕy֑wòn mé⁠ʼaẖe֕y⁠ká ʼ֧wò mi⁠gé̇rĕ⁠ká֛ ʼàşě֥r bĕ̇⁠ʼarĕẕĕ⁠ká֖ bi̇⁠şĕ̌ʻáreֽy⁠ká׃"],[24,15,"בְּ⁠יוֹמ⁠וֹ֩ תִתֵּ֨ן שְׂכָר֜⁠וֹ וְֽ⁠לֹא־תָב֧וֹא עָלָ֣י⁠ו הַ⁠שֶּׁ֗מֶשׁ כִּ֤י עָנִי֙ ה֔וּא וְ⁠אֵלָ֕י⁠ו ה֥וּא נֹשֵׂ֖א אֶת־נַפְשׁ֑⁠וֹ וְ⁠לֹֽא־יִקְרָ֤א עָלֶ֨י⁠ךָ֙ אֶל־יְהוָ֔ה וְ⁠הָיָ֥ה בְ⁠ךָ֖ חֵֽטְא׃ס","bĕ̇⁠ywòm⁠wò֩ ţiţé̇֨n şĕ̂kár֜⁠wò wĕֽ⁠lòʼ-ţáb֧wòʼ ʻálá֣y⁠w ha⁠şė̌֗meş̌ ki֤̇y ʻániy֙ h֔ẇʼ wĕ⁠ʼélá֕y⁠w h֥ẇʼ nòşé֖̂ʼ ʼeţ-napĕş֑̌⁠wò wĕ⁠lòֽʼ-yiqĕrá֤ʼ ʻále֨y⁠ká֙ ʼel-yĕhwá֔h wĕ⁠háyá֥h bĕ⁠ká֖ ẖéֽtĕʼ׃s"],[24,16,"לֹֽא־יוּמְת֤וּ אָבוֹת֙ עַל־בָּנִ֔ים וּ⁠בָנִ֖ים לֹא־יוּמְת֣וּ עַל־אָב֑וֹת אִ֥יש בְּ⁠חֶטְא֖⁠וֹ יוּמָֽתוּ׃ס","lòֽʼ-yẇmĕţ֤ẇ ʼábwòţ֙ ʻal-bá̇ni֔ym ẇ⁠báni֖ym lòʼ-yẇmĕţ֣ẇ ʻal-ʼáb֑wòţ ʼi֥yş bĕ̇⁠ẖetĕʼ֖⁠wò yẇmáֽţẇ׃s"],[24,17,"לֹ֣א תַטֶּ֔ה מִשְׁפַּ֖ט גֵּ֣ר יָת֑וֹם וְ⁠לֹ֣א תַחֲבֹ֔ל בֶּ֖גֶד אַלְמָנָֽה׃","lò֣ʼ ţatė֔h mişĕ̌pȧ֖t gé֣̇r yáţ֑wòm wĕ⁠lò֣ʼ ţaẖàbò֔l bė֖ged ʼalĕmánáֽh׃"],[24,18,"וְ⁠זָכַרְתָּ֗ כִּ֣י עֶ֤בֶד הָיִ֨יתָ֙ בְּ⁠מִצְרַ֔יִם וַֽ⁠יִּפְדְּ⁠ךָ֛ יְהוָ֥ה אֱלֹהֶ֖י⁠ךָ מִ⁠שָּׁ֑ם עַל־כֵּ֞ן אָנֹכִ֤י מְצַוְּ⁠ךָ֙ לַ⁠עֲשׂ֔וֹת אֶת־הַ⁠דָּבָ֖ר הַ⁠זֶּֽה׃ס","wĕ⁠zákarĕţá̇֗ ki֣̇y ʻe֤bed háyi֨yţá֙ bĕ̇⁠miẕĕra֔yim waֽ⁠yi̇pĕdĕ̇⁠ká֛ yĕhwá֥h ʼèlòhe֖y⁠ká mi⁠şá֑̇̌m ʻal-ké̇֞n ʼánòki֤y mĕẕawĕ̇⁠ká֙ la⁠ʻàş̂֔wòţ ʼeţ-ha⁠dá̇bá֖r ha⁠zėֽh׃s"],[24,19,"כִּ֣י תִקְצֹר֩ קְצִֽירְ⁠ךָ֨ בְ⁠שָׂדֶ֜⁠ךָ וְ⁠שָֽׁכַחְתָּ֧ עֹ֣מֶר בַּ⁠שָּׂדֶ֗ה לֹ֤א תָשׁוּב֙ לְ⁠קַחְתּ֔⁠וֹ לַ⁠גֵּ֛ר לַ⁠יָּת֥וֹם וְ⁠לָ⁠אַלְמָנָ֖ה יִהְיֶ֑ה לְמַ֤עַן יְבָרֶכְ⁠ךָ֙ יְהוָ֣ה אֱלֹהֶ֔י⁠ךָ בְּ⁠כֹ֖ל מַעֲשֵׂ֥ה יָדֶֽי⁠ךָ׃","ki֣̇y ţiqĕẕòr֩ qĕẕiֽyrĕ⁠ká֨ bĕ⁠şá̂de֜⁠ká wĕ⁠şáֽ̌kaẖĕţá֧̇ ʻò֣mer bȧ⁠şá̇̂de֗h lò֤ʼ ţáş̌ẇb֙ lĕ⁠qaẖĕţ̇֔⁠wò la⁠gé֛̇r la⁠yá̇ţ֥wòm wĕ⁠lá⁠ʼalĕmáná֖h yihĕye֑h lĕma֤ʻan yĕbárekĕ⁠ká֙ yĕhwá֣h ʼèlòhe֔y⁠ká bĕ̇⁠kò֖l maʻàşé֥̂h yádeֽy⁠ká׃"],[24,20,"כִּ֤י תַחְבֹּט֙ זֵֽיתְ⁠ךָ֔ לֹ֥א תְפָאֵ֖ר אַחֲרֶ֑י⁠ךָ לַ⁠גֵּ֛ר לַ⁠יָּת֥וֹם וְ⁠לָ⁠אַלְמָנָ֖ה יִהְיֶֽה׃ס","ki֤̇y ţaẖĕbò̇t֙ zéֽyţĕ⁠ká֔ lò֥ʼ ţĕpáʼé֖r ʼaẖàre֑y⁠ká la⁠gé֛̇r la⁠yá̇ţ֥wòm wĕ⁠lá⁠ʼalĕmáná֖h yihĕyeֽh׃s"],[24,21,"כִּ֤י תִבְצֹר֙ כַּרְמְ⁠ךָ֔ לֹ֥א תְעוֹלֵ֖ל אַחֲרֶ֑י⁠ךָ לַ⁠גֵּ֛ר לַ⁠יָּת֥וֹם וְ⁠לָ⁠אַלְמָנָ֖ה יִהְיֶֽה׃","ki֤̇y ţibĕẕòr֙ kȧrĕmĕ⁠ká֔ lò֥ʼ ţĕʻwòlé֖l ʼaẖàre֑y⁠ká la⁠gé֛̇r la⁠yá̇ţ֥wòm wĕ⁠lá⁠ʼalĕmáná֖h yihĕyeֽh׃"],[24,22,"וְ⁠זָ֣כַרְתָּ֔ כִּי־עֶ֥בֶד הָיִ֖יתָ בְּ⁠אֶ֣רֶץ מִצְרָ֑יִם עַל־כֵּ֞ן אָנֹכִ֤י מְצַוְּ⁠ךָ֙ לַ⁠עֲשׂ֔וֹת אֶת־הַ⁠דָּבָ֖ר הַ⁠זֶּֽה׃ס","wĕ⁠zá֣karĕţá̇֔ ki̇y-ʻe֥bed háyi֖yţá bĕ̇⁠ʼe֣reẕ miẕĕrá֑yim ʻal-ké̇֞n ʼánòki֤y mĕẕawĕ̇⁠ká֙ la⁠ʻàş̂֔wòţ ʼeţ-ha⁠dá̇bá֖r ha⁠zėֽh׃s"],[25,1,"כִּֽי־יִהְיֶ֥ה רִיב֙ בֵּ֣ין אֲנָשִׁ֔ים וְ⁠נִגְּשׁ֥וּ אֶל־הַ⁠מִּשְׁפָּ֖ט וּ⁠שְׁפָט֑וּ⁠ם וְ⁠הִצְדִּ֨יקוּ֙ אֶת־הַ⁠צַּדִּ֔יק וְ⁠הִרְשִׁ֖יעוּ אֶת־הָ⁠רָשָֽׁע׃","kiֽ̇y-yihĕye֥h riyb֙ bé֣̇yn ʼànáşǐ֔ym wĕ⁠nigĕ̇ş֥̌ẇ ʼel-ha⁠mi̇şĕ̌pá֖̇t ẇ⁠şĕ̌pát֑ẇ⁠m wĕ⁠hiẕĕdi̇֨yqẇ֙ ʼeţ-ha⁠ẕȧdi̇֔yq wĕ⁠hirĕşǐ֖yʻẇ ʼeţ-há⁠ráşáֽ̌ʻ׃"],[25,2,"וְ⁠הָיָ֛ה אִם־בִּ֥ן הַכּ֖וֹת הָ⁠רָשָׁ֑ע וְ⁠הִפִּיל֤⁠וֹ הַ⁠שֹּׁפֵט֙ וְ⁠הִכָּ֣ה⁠וּ לְ⁠פָנָ֔י⁠ו כְּ⁠דֵ֥י רִשְׁעָת֖⁠וֹ בְּ⁠מִסְפָּֽר׃","wĕ⁠háyá֛h ʼim-bi֥̇n hak֖̇wòţ há⁠ráşá֑̌ʻ wĕ⁠hipi̇yl֤⁠wò ha⁠şò̇̌pét֙ wĕ⁠hiká֣̇h⁠ẇ lĕ⁠páná֔y⁠w kĕ̇⁠dé֥y rişĕ̌ʻáţ֖⁠wò bĕ̇⁠misĕpáֽ̇r׃"],[25,3,"אַרְבָּעִ֥ים יַכֶּ֖⁠נּוּ לֹ֣א יֹסִ֑יף פֶּן־יֹסִ֨יף לְ⁠הַכֹּת֤⁠וֹ עַל־אֵ֨לֶּה֙ מַכָּ֣ה רַבָּ֔ה וְ⁠נִקְלָ֥ה אָחִ֖י⁠ךָ לְ⁠עֵינֶֽי⁠ךָ׃ס","ʼarĕbá̇ʻi֥ym yakė֖⁠ṅẇ lò֣ʼ yòsi֑yp pėn-yòsi֨yp lĕ⁠hakò̇ţ֤⁠wò ʻal-ʼé֨lėh֙ maká֣̇h rabá̇֔h wĕ⁠niqĕlá֥h ʼáẖi֖y⁠ká lĕ⁠ʻéyneֽy⁠ká׃s"],[25,4,"לֹא־תַחְסֹ֥ם שׁ֖וֹר בְּ⁠דִישֽׁ⁠וֹ׃ס","lòʼ-ţaẖĕsò֥m ş֖̌wòr bĕ̇⁠diyşֽ̌⁠wò׃s"],[25,5,"כִּֽי־יֵשְׁב֨וּ אַחִ֜ים יַחְדָּ֗ו וּ⁠מֵ֨ת אַחַ֤ד מֵ⁠הֶם֙ וּ⁠בֵ֣ן אֵֽין־ל֔⁠וֹ לֹֽא־תִהְיֶ֧ה אֵֽשֶׁת־הַ⁠מֵּ֛ת הַ⁠ח֖וּצָ⁠ה לְ⁠אִ֣ישׁ זָ֑ר יְבָמָ⁠הּ֙ יָבֹ֣א עָלֶ֔י⁠הָ וּ⁠לְקָחָ֥⁠הּ ל֛⁠וֹ לְ⁠אִשָּׁ֖ה וְ⁠יִבְּמָֽ⁠הּ׃","kiֽ̇y-yéşĕ̌b֨ẇ ʼaẖi֜ym yaẖĕdá̇֗w ẇ⁠mé֨ţ ʼaẖa֤d mé⁠hem֙ ẇ⁠bé֣n ʼéֽyn-l֔⁠wò lòֽʼ-ţihĕye֧h ʼéֽşěţ-ha⁠mé֛̇ţ ha⁠ẖ֖ẇẕá⁠h lĕ⁠ʼi֣yş̌ zá֑r yĕbámá⁠ḣ֙ yábò֣ʼ ʻále֔y⁠há ẇ⁠lĕqáẖá֥⁠ḣ l֛⁠wò lĕ⁠ʼişá֖̇̌h wĕ⁠yibĕ̇máֽ⁠ḣ׃"],[25,6,"וְ⁠הָיָ֗ה הַ⁠בְּכוֹר֙ אֲשֶׁ֣ר תֵּלֵ֔ד יָק֕וּם עַל־שֵׁ֥ם אָחִ֖י⁠ו הַ⁠מֵּ֑ת וְ⁠לֹֽא־יִמָּחֶ֥ה שְׁמ֖⁠וֹ מִ⁠יִּשְׂרָאֵֽל׃","wĕ⁠háyá֗h ha⁠bĕ̇kwòr֙ ʼàşě֣r ţé̇lé֔d yáq֕ẇm ʻal-şé֥̌m ʼáẖi֖y⁠w ha⁠mé֑̇ţ wĕ⁠lòֽʼ-yimá̇ẖe֥h şĕ̌m֖⁠wò mi⁠yi̇şĕ̂ráʼéֽl׃"],[25,7,"וְ⁠אִם־לֹ֤א יַחְפֹּץ֙ הָ⁠אִ֔ישׁ לָ⁠קַ֖חַת אֶת־יְבִמְתּ֑⁠וֹ וְ⁠עָלְתָה֩ יְבִמְתּ֨⁠וֹ הַ⁠שַּׁ֜עְרָ⁠ה אֶל־הַ⁠זְּקֵנִ֗ים וְ⁠אָֽמְרָה֙ מֵאֵ֨ין יְבָמִ֜⁠י לְ⁠הָקִ֨ים לְ⁠אָחִ֥י⁠ו שֵׁם֙ בְּ⁠יִשְׂרָאֵ֔ל לֹ֥א אָבָ֖ה יַבְּמִֽ⁠י׃","wĕ⁠ʼim-lò֤ʼ yaẖĕpò̇ẕ֙ há⁠ʼi֔yş̌ lá⁠qa֖ẖaţ ʼeţ-yĕbimĕţ֑̇⁠wò wĕ⁠ʻálĕţáh֩ yĕbimĕţ̇֨⁠wò ha⁠şȧ̌֜ʻĕrá⁠h ʼel-ha⁠zĕ̇qéni֗ym wĕ⁠ʼáֽmĕráh֙ méʼé֨yn yĕbámi֜⁠y lĕ⁠háqi֨ym lĕ⁠ʼáẖi֥y⁠w şé̌m֙ bĕ̇⁠yişĕ̂ráʼé֔l lò֥ʼ ʼábá֖h yabĕ̇miֽ⁠y׃"],[25,8,"וְ⁠קָֽרְאוּ־ל֥⁠וֹ זִקְנֵי־עִיר֖⁠וֹ וְ⁠דִבְּר֣וּ אֵלָ֑י⁠ו וְ⁠עָמַ֣ד וְ⁠אָמַ֔ר לֹ֥א חָפַ֖צְתִּי לְ⁠קַחְתָּֽ⁠הּ׃","wĕ⁠qáֽrĕʼẇ-l֥⁠wò ziqĕnéy-ʻiyr֖⁠wò wĕ⁠dibĕ̇r֣ẇ ʼélá֑y⁠w wĕ⁠ʻáma֣d wĕ⁠ʼáma֔r lò֥ʼ ẖápa֖ẕĕţi̇y lĕ⁠qaẖĕţáֽ̇⁠ḣ׃"],[25,9,"וְ⁠נִגְּשָׁ֨ה יְבִמְתּ֣⁠וֹ אֵלָי⁠ו֮ לְ⁠עֵינֵ֣י הַ⁠זְּקֵנִים֒ וְ⁠חָלְצָ֤ה נַעֲל⁠וֹ֙ מֵ⁠עַ֣ל רַגְל֔⁠וֹ וְ⁠יָרְקָ֖ה בְּ⁠פָנָ֑י⁠ו וְ⁠עָֽנְתָה֙ וְ⁠אָ֣מְרָ֔ה כָּ֚כָה יֵעָשֶׂ֣ה לָ⁠אִ֔ישׁ אֲשֶׁ֥ר לֹא־יִבְנֶ֖ה אֶת־בֵּ֥ית אָחִֽי⁠ו","wĕ⁠nigĕ̇şá̌֨h yĕbimĕţ֣̇⁠wò ʼéláy⁠w֮ lĕ⁠ʻéyné֣y ha⁠zĕ̇qéniym֒ wĕ⁠ẖálĕẕá֤h naʻàl⁠wò֙ mé⁠ʻa֣l ragĕl֔⁠wò wĕ⁠yárĕqá֖h bĕ̇⁠páná֑y⁠w wĕ⁠ʻáֽnĕţáh֙ wĕ⁠ʼá֣mĕrá֔h ká֚̇káh yéʻáşê֣h lá⁠ʼi֔yş̌ ʼàşě֥r lòʼ-yibĕne֖h ʼeţ-bé֥̇yţ ʼáẖiֽy⁠w"],[25,10,"וְ⁠נִקְרָ֥א שְׁמ֖⁠וֹ בְּ⁠יִשְׂרָאֵ֑ל בֵּ֖ית חֲל֥וּץ הַ⁠נָּֽעַל׃ס","wĕ⁠niqĕrá֥ʼ şĕ̌m֖⁠wò bĕ̇⁠yişĕ̂ráʼé֑l bé֖̇yţ ẖàl֥ẇẕ ha⁠náֽ̇ʻal׃s"],[25,11,"כִּֽי־יִנָּצ֨וּ אֲנָשִׁ֤ים יַחְדָּו֙ אִ֣ישׁ וְ⁠אָחִ֔י⁠ו וְ⁠קָֽרְבָה֙ אֵ֣שֶׁת הָֽ⁠אֶחָ֔ד לְ⁠הַצִּ֥יל אֶת־אִישָׁ֖⁠הּ מִ⁠יַּ֣ד מַכֵּ֑ה⁠וּ וְ⁠שָׁלְחָ֣ה יָדָ֔⁠הּ וְ⁠הֶחֱזִ֖יקָה בִּ⁠מְבֻשָֽׁי⁠ו׃","kiֽ̇y-yiná̇ẕ֨ẇ ʼànáşǐ֤ym yaẖĕdá̇w֙ ʼi֣yş̌ wĕ⁠ʼáẖi֔y⁠w wĕ⁠qáֽrĕbáh֙ ʼé֣şěţ háֽ⁠ʼeẖá֔d lĕ⁠haẕi֥̇yl ʼeţ-ʼiyşá֖̌⁠ḣ mi⁠yȧ֣d maké֑̇h⁠ẇ wĕ⁠şá̌lĕẖá֣h yádá֔⁠ḣ wĕ⁠heẖèzi֖yqáh bi̇⁠mĕbuşáֽ̌y⁠w׃"],[25,12,"וְ⁠קַצֹּתָ֖ה אֶת־כַּפָּ֑⁠הּ לֹ֥א תָח֖וֹס עֵינֶֽ⁠ךָ׃ס","wĕ⁠qaẕò̇ţá֖h ʼeţ-kȧpá֑̇⁠ḣ lò֥ʼ ţáẖ֖wòs ʻéyneֽ⁠ká׃s"],[25,13,"לֹֽא־יִהְיֶ֥ה לְ⁠ךָ֛ בְּ⁠כִֽיסְ⁠ךָ֖ אֶ֣בֶן וָ⁠אָ֑בֶן גְּדוֹלָ֖ה וּ⁠קְטַנָּֽה׃ס","lòֽʼ-yihĕye֥h lĕ⁠ká֛ bĕ̇⁠kiֽysĕ⁠ká֖ ʼe֣ben wá⁠ʼá֑ben gĕ̇dwòlá֖h ẇ⁠qĕtanáֽ̇h׃s"],[25,14,"לֹא־יִהְיֶ֥ה לְ⁠ךָ֛ בְּ⁠בֵיתְ⁠ךָ֖ אֵיפָ֣ה וְ⁠אֵיפָ֑ה גְּדוֹלָ֖ה וּ⁠קְטַנָּֽה׃","lòʼ-yihĕye֥h lĕ⁠ká֛ bĕ̇⁠béyţĕ⁠ká֖ ʼéypá֣h wĕ⁠ʼéypá֑h gĕ̇dwòlá֖h ẇ⁠qĕtanáֽ̇h׃"],[25,15,"אֶ֣בֶן שְׁלֵמָ֤ה וָ⁠צֶ֨דֶק֙ יִֽהְיֶה־לָּ֔⁠ךְ אֵיפָ֧ה שְׁלֵמָ֛ה וָ⁠צֶ֖דֶק יִֽהְיֶה־לָּ֑⁠ךְ לְמַ֨עַן֙ יַאֲרִ֣יכוּ יָמֶ֔י⁠ךָ עַ֚ל הָֽ⁠אֲדָמָ֔ה אֲשֶׁר־יְהוָ֥ה אֱלֹהֶ֖י⁠ךָ נֹתֵ֥ן לָֽ⁠ךְ׃","ʼe֣ben şĕ̌lémá֤h wá⁠ẕe֨deq֙ yiֽhĕyeh-lá̇֔⁠kĕ ʼéypá֧h şĕ̌lémá֛h wá⁠ẕe֖deq yiֽhĕyeh-lá֑̇⁠kĕ lĕma֨ʻan֙ yaʼàri֣ykẇ yáme֔y⁠ká ʻa֚l háֽ⁠ʼàdámá֔h ʼàşěr-yĕhwá֥h ʼèlòhe֖y⁠ká nòţé֥n láֽ⁠kĕ׃"],[25,16,"כִּ֧י תוֹעֲבַ֛ת יְהוָ֥ה אֱלֹהֶ֖י⁠ךָ כָּל־עֹ֣שֵׂה אֵ֑לֶּה כֹּ֖ל עֹ֥שֵׂה עָֽוֶל׃פ","ki֧̇y ţwòʻàba֛ţ yĕhwá֥h ʼèlòhe֖y⁠ká ká̇l-ʻò֣şé̂h ʼé֑lėh kò֖̇l ʻò֥şé̂h ʻáֽwel׃p"],[25,17,"זָכ֕וֹר אֵ֛ת אֲשֶׁר־עָשָׂ֥ה לְ⁠ךָ֖ עֲמָלֵ֑ק בַּ⁠דֶּ֖רֶךְ בְּ⁠צֵאתְ⁠כֶ֥ם מִ⁠מִּצְרָֽיִם׃","zák֕wòr ʼé֛ţ ʼàşěr-ʻáşá֥̂h lĕ⁠ká֖ ʻàmálé֑q bȧ⁠dė֖rekĕ bĕ̇⁠ẕéʼţĕ⁠ke֥m mi⁠mi̇ẕĕráֽyim׃"],[25,18,"אֲשֶׁ֨ר קָֽרְ⁠ךָ֜ בַּ⁠דֶּ֗רֶךְ וַ⁠יְזַנֵּ֤ב בְּ⁠ךָ֙ כָּל־הַ⁠נֶּחֱשָׁלִ֣ים אַֽחַרֶ֔י⁠ךָ וְ⁠אַתָּ֖ה עָיֵ֣ף וְ⁠יָגֵ֑עַ וְ⁠לֹ֥א יָרֵ֖א אֱלֹהִֽים׃","ʼàşě֨r qáֽrĕ⁠ká֜ bȧ⁠dė֗rekĕ wa⁠yĕzané֤̇b bĕ̇⁠ká֙ ká̇l-ha⁠nėẖèşá̌li֣ym ʼaֽẖare֔y⁠ká wĕ⁠ʼaţá֖̇h ʻáyé֣p wĕ⁠yágé֑ʻa wĕ⁠lò֥ʼ yáré֖ʼ ʼèlòhiֽym׃"],[25,19,"וְ⁠הָיָ֡ה בְּ⁠הָנִ֣יחַ יְהוָ֣ה אֱלֹהֶ֣י⁠ךָ ׀ לְ֠⁠ךָ מִ⁠כָּל־אֹ֨יְבֶ֜י⁠ךָ מִ⁠סָּבִ֗יב בָּ⁠אָ֨רֶץ֙ אֲשֶׁ֣ר יְהוָֽה־אֱ֠לֹהֶי⁠ךָ נֹתֵ֨ן לְ⁠ךָ֤ נַחֲלָה֙ לְ⁠רִשְׁתָּ֔⁠הּ תִּמְחֶה֙ אֶת־זֵ֣כֶר עֲמָלֵ֔ק מִ⁠תַּ֖חַת הַ⁠שָּׁמָ֑יִם לֹ֖א תִּשְׁכָּֽח׃פ","wĕ⁠háyá֡h bĕ̇⁠háni֣yẖa yĕhwá֣h ʼèlòhe֣y⁠ká ׀ lĕ֠⁠ká mi⁠ká̇l-ʼò֨yĕbe֜y⁠ká mi⁠sá̇bi֗yb bá̇⁠ʼá֨reẕ֙ ʼàşě֣r yĕhwáֽh-ʼè֠lòhey⁠ká nòţé֨n lĕ⁠ká֤ naẖàláh֙ lĕ⁠rişĕ̌ţá̇֔⁠ḣ ţi̇mĕẖeh֙ ʼeţ-zé֣ker ʻàmálé֔q mi⁠ţȧ֖ẖaţ ha⁠şá̇̌má֑yim lò֖ʼ ţi̇şĕ̌káֽ̇ẖ׃p"],[26,1,"וְ⁠הָיָה֙ כִּֽי־תָב֣וֹא אֶל־הָ⁠אָ֔רֶץ אֲשֶׁר֙ יְהוָ֣ה אֱלֹהֶ֔י⁠ךָ נֹתֵ֥ן לְ⁠ךָ֖ נַחֲלָ֑ה וִֽ⁠ירִשְׁתָּ֖⁠הּ וְ⁠יָשַׁ֥בְתָּ בָּֽ⁠הּ׃","wĕ⁠háyáh֙ kiֽ̇y-ţáb֣wòʼ ʼel-há⁠ʼá֔reẕ ʼàşěr֙ yĕhwá֣h ʼèlòhe֔y⁠ká nòţé֥n lĕ⁠ká֖ naẖàlá֑h wiֽ⁠yrişĕ̌ţá֖̇⁠ḣ wĕ⁠yáşǎ֥bĕţá̇ báֽ̇⁠ḣ׃"],[26,2,"וְ⁠לָקַחְתָּ֞ מֵ⁠רֵאשִׁ֣ית ׀ כָּל־פְּרִ֣י הָ⁠אֲדָמָ֗ה אֲשֶׁ֨ר תָּבִ֧יא מֵֽ⁠אַרְצְ⁠ךָ֛ אֲשֶׁ֨ר יְהוָ֧ה אֱלֹהֶ֛י⁠ךָ נֹתֵ֥ן לָ֖⁠ךְ וְ⁠שַׂמְתָּ֣ בַ⁠טֶּ֑נֶא וְ⁠הָֽלַכְתָּ֙ אֶל־הַ⁠מָּק֔וֹם אֲשֶׁ֤ר יִבְחַר֙ יְהוָ֣ה אֱלֹהֶ֔י⁠ךָ לְ⁠שַׁכֵּ֥ן שְׁמ֖⁠וֹ שָֽׁם׃","wĕ⁠láqaẖĕţá̇֞ mé⁠réʼşǐ֣yţ ׀ ká̇l-pĕ̇ri֣y há⁠ʼàdámá֗h ʼàşě֨r ţá̇bi֧yʼ méֽ⁠ʼarĕẕĕ⁠ká֛ ʼàşě֨r yĕhwá֧h ʼèlòhe֛y⁠ká nòţé֥n lá֖⁠kĕ wĕ⁠şâmĕţá֣̇ ba⁠tė֑neʼ wĕ⁠háֽlakĕţá̇֙ ʼel-ha⁠má̇q֔wòm ʼàşě֤r yibĕẖar֙ yĕhwá֣h ʼèlòhe֔y⁠ká lĕ⁠şǎké֥̇n şĕ̌m֖⁠wò şáֽ̌m׃"],[26,3,"וּ⁠בָאתָ֙ אֶל־הַ⁠כֹּהֵ֔ן אֲשֶׁ֥ר יִהְיֶ֖ה בַּ⁠יָּמִ֣ים הָ⁠הֵ֑ם וְ⁠אָמַרְתָּ֣ אֵלָ֗י⁠ו הִגַּ֤דְתִּי הַ⁠יּוֹם֙ לַ⁠יהוָ֣ה אֱלֹהֶ֔י⁠ךָ כִּי־בָ֨אתִי֙ אֶל־הָ⁠אָ֔רֶץ אֲשֶׁ֨ר נִשְׁבַּ֧ע יְהוָ֛ה לַ⁠אֲבֹתֵ֖י⁠נוּ לָ֥⁠תֶת לָֽ⁠נוּ׃","ẇ⁠báʼţá֙ ʼel-ha⁠kò̇hé֔n ʼàşě֥r yihĕye֖h bȧ⁠yá̇mi֣ym há⁠hé֑m wĕ⁠ʼámarĕţá֣̇ ʼélá֗y⁠w higȧ֤dĕţi̇y ha⁠ẏwòm֙ la⁠yhwá֣h ʼèlòhe֔y⁠ká ki̇y-bá֨ʼţiy֙ ʼel-há⁠ʼá֔reẕ ʼàşě֨r nişĕ̌bȧ֧ʻ yĕhwá֛h la⁠ʼàbòţé֖y⁠nẇ lá֥⁠ţeţ láֽ⁠nẇ׃"],[26,4,"וְ⁠לָקַ֧ח הַ⁠כֹּהֵ֛ן הַ⁠טֶּ֖נֶא מִ⁠יָּדֶ֑⁠ךָ וְ⁠הִ֨נִּיח֔⁠וֹ לִ⁠פְנֵ֕י מִזְבַּ֖ח יְהוָ֥ה אֱלֹהֶֽי⁠ךָ׃","wĕ⁠láqa֧ẖ ha⁠kò̇hé֛n ha⁠tė֖neʼ mi⁠yá̇de֑⁠ká wĕ⁠hi֨ni̇yẖ֔⁠wò li⁠pĕné֕y mizĕbȧ֖ẖ yĕhwá֥h ʼèlòheֽy⁠ká׃"],[26,5,"וְ⁠עָנִ֨יתָ וְ⁠אָמַרְתָּ֜ לִ⁠פְנֵ֣י ׀ יְהוָ֣ה אֱלֹהֶ֗י⁠ךָ אֲרַמִּי֙ אֹבֵ֣ד אָבִ֔⁠י וַ⁠יֵּ֣רֶד מִצְרַ֔יְמָ⁠ה וַ⁠יָּ֥גָר שָׁ֖ם בִּ⁠מְתֵ֣י מְעָ֑ט וַֽ⁠יְהִי־שָׁ֕ם לְ⁠ג֥וֹי גָּד֖וֹל עָצ֥וּם וָ⁠רָֽב׃","wĕ⁠ʻáni֨yţá wĕ⁠ʼámarĕţá̇֜ li⁠pĕné֣y ׀ yĕhwá֣h ʼèlòhe֗y⁠ká ʼàrami̇y֙ ʼòbé֣d ʼábi֔⁠y wa⁠yé֣̇red miẕĕra֔yĕmá⁠h wa⁠yá֥̇gár şá֖̌m bi̇⁠mĕţé֣y mĕʻá֑t waֽ⁠yĕhiy-şá̌֕m lĕ⁠g֥wòy gá̇d֖wòl ʻáẕ֥ẇm wá⁠ráֽb׃"],[26,6,"וַ⁠יָּרֵ֧עוּ אֹתָ֛⁠נוּ הַ⁠מִּצְרִ֖ים וַ⁠יְעַנּ֑וּ⁠נוּ וַ⁠יִּתְּנ֥וּ עָלֵ֖י⁠נוּ עֲבֹדָ֥ה קָשָֽׁה׃","wa⁠yá̇ré֧ʻẇ ʼòţá֛⁠nẇ ha⁠mi̇ẕĕri֖ym wa⁠yĕʻaṅ֑ẇ⁠nẇ wa⁠yi̇ţĕ̇n֥ẇ ʻálé֖y⁠nẇ ʻàbòdá֥h qáşáֽ̌h׃"],[26,7,"וַ⁠נִּצְעַ֕ק אֶל־יְהוָ֖ה אֱלֹהֵ֣י אֲבֹתֵ֑י⁠נוּ וַ⁠יִּשְׁמַ֤ע יְהוָה֙ אֶת־קֹלֵ֔⁠נוּ וַ⁠יַּ֧רְא אֶת־עָנְיֵ֛⁠נוּ וְ⁠אֶת־עֲמָלֵ֖⁠נוּ וְ⁠אֶת־לַחֲצֵֽ⁠נוּ׃","wa⁠ni̇ẕĕʻa֕q ʼel-yĕhwá֖h ʼèlòhé֣y ʼàbòţé֑y⁠nẇ wa⁠yi̇şĕ̌ma֤ʻ yĕhwáh֙ ʼeţ-qòlé֔⁠nẇ wa⁠yȧ֧rĕʼ ʼeţ-ʻánĕyé֛⁠nẇ wĕ⁠ʼeţ-ʻàmálé֖⁠nẇ wĕ⁠ʼeţ-laẖàẕéֽ⁠nẇ׃"],[26,8,"וַ⁠יּוֹצִאֵ֤⁠נוּ יְהוָה֙ מִ⁠מִּצְרַ֔יִם בְּ⁠יָ֤ד חֲזָקָה֙ וּ⁠בִ⁠זְרֹ֣עַ נְטוּיָ֔ה וּ⁠בְ⁠מֹרָ֖א גָּדֹ֑ל וּ⁠בְ⁠אֹת֖וֹת וּ⁠בְ⁠מֹפְתִֽים׃","wa⁠ẏwòẕiʼé֤⁠nẇ yĕhwáh֙ mi⁠mi̇ẕĕra֔yim bĕ̇⁠yá֤d ẖàzáqáh֙ ẇ⁠bi⁠zĕrò֣ʻa nĕtẇyá֔h ẇ⁠bĕ⁠mòrá֖ʼ gá̇dò֑l ẇ⁠bĕ⁠ʼòţ֖wòţ ẇ⁠bĕ⁠mòpĕţiֽym׃"],[26,9,"וַ⁠יְבִאֵ֖⁠נוּ אֶל־הַ⁠מָּק֣וֹם הַ⁠זֶּ֑ה וַ⁠יִּתֶּן־לָ֨⁠נוּ֙ אֶת־הָ⁠אָ֣רֶץ הַ⁠זֹּ֔את אֶ֛רֶץ זָבַ֥ת חָלָ֖ב וּ⁠דְבָֽשׁ׃","wa⁠yĕbiʼé֖⁠nẇ ʼel-ha⁠má̇q֣wòm ha⁠zė֑h wa⁠yi̇ţėn-lá֨⁠nẇ֙ ʼeţ-há⁠ʼá֣reẕ ha⁠zò̇֔ʼţ ʼe֛reẕ zába֥ţ ẖálá֖b ẇ⁠dĕbáֽş̌׃"],[26,10,"וְ⁠עַתָּ֗ה הִנֵּ֤ה הֵבֵ֨אתִי֙ אֶת־רֵאשִׁית֙ פְּרִ֣י הָ⁠אֲדָמָ֔ה אֲשֶׁר־נָתַ֥תָּה לִּ֖⁠י יְהוָ֑ה וְ⁠הִנַּחְתּ֗⁠וֹ לִ⁠פְנֵי֙ יְהוָ֣ה אֱלֹהֶ֔י⁠ךָ וְ⁠הִֽשְׁתַּחֲוִ֔יתָ לִ⁠פְנֵ֖י יְהוָ֥ה אֱלֹהֶֽי⁠ךָ׃","wĕ⁠ʻaţá̇֗h hiné֤̇h hébé֨ʼţiy֙ ʼeţ-réʼşǐyţ֙ pĕ̇ri֣y há⁠ʼàdámá֔h ʼàşěr-náţa֥ţá̇h li֖̇⁠y yĕhwá֑h wĕ⁠hinȧẖĕţ̇֗⁠wò li⁠pĕnéy֙ yĕhwá֣h ʼèlòhe֔y⁠ká wĕ⁠hiֽşĕ̌ţȧẖàwi֔yţá li⁠pĕné֖y yĕhwá֥h ʼèlòheֽy⁠ká׃"],[26,11,"וְ⁠שָׂמַחְתָּ֣ בְ⁠כָל־הַ⁠טּ֗וֹב אֲשֶׁ֧ר נָֽתַן־לְ⁠ךָ֛ יְהוָ֥ה אֱלֹהֶ֖י⁠ךָ וּ⁠לְ⁠בֵיתֶ֑⁠ךָ אַתָּה֙ וְ⁠הַ⁠לֵּוִ֔י וְ⁠הַ⁠גֵּ֖ר אֲשֶׁ֥ר בְּ⁠קִרְבֶּֽ⁠ךָ׃ס","wĕ⁠şá̂maẖĕţá֣̇ bĕ⁠kál-ha⁠ṫ֗wòb ʼàşě֧r náֽţan-lĕ⁠ká֛ yĕhwá֥h ʼèlòhe֖y⁠ká ẇ⁠lĕ⁠béyţe֑⁠ká ʼaţá̇h֙ wĕ⁠ha⁠lé̇wi֔y wĕ⁠ha⁠gé֖̇r ʼàşě֥r bĕ̇⁠qirĕbėֽ⁠ká׃s"],[26,12,"כִּ֣י תְכַלֶּ֞ה לַ֠⁠עְשֵׂר אֶת־כָּל־מַעְשַׂ֧ר תְּבוּאָתְ⁠ךָ֛ בַּ⁠שָּׁנָ֥ה הַ⁠שְּׁלִישִׁ֖ת שְׁנַ֣ת הַֽ⁠מַּעֲשֵׂ֑ר וְ⁠נָתַתָּ֣ה לַ⁠לֵּוִ֗י לַ⁠גֵּר֙ לַ⁠יָּת֣וֹם וְ⁠לָֽ⁠אַלְמָנָ֔ה וְ⁠אָכְל֥וּ בִ⁠שְׁעָרֶ֖י⁠ךָ וְ⁠שָׂבֵֽעוּ׃","ki֣̇y ţĕkalė֞h la֠⁠ʻĕşé̂r ʼeţ-ká̇l-maʻĕşâ֧r ţĕ̇bẇʼáţĕ⁠ká֛ bȧ⁠şá̇̌ná֥h ha⁠şĕ̇̌liyşǐ֖ţ şĕ̌na֣ţ haֽ⁠mȧʻàşé֑̂r wĕ⁠náţaţá֣̇h la⁠lé̇wi֗y la⁠gé̇r֙ la⁠yá̇ţ֣wòm wĕ⁠láֽ⁠ʼalĕmáná֔h wĕ⁠ʼákĕl֥ẇ bi⁠şĕ̌ʻáre֖y⁠ká wĕ⁠şá̂béֽʻẇ׃"],[26,13,"וְ⁠אָמַרְתָּ֡ לִ⁠פְנֵי֩ יְהוָ֨ה אֱלֹהֶ֜י⁠ךָ בִּעַ֧רְתִּי הַ⁠קֹּ֣דֶשׁ מִן־הַ⁠בַּ֗יִת וְ⁠גַ֨ם נְתַתִּ֤י⁠ו לַ⁠לֵּוִי֙ וְ⁠לַ⁠גֵּר֙ לַ⁠יָּת֣וֹם וְ⁠לָ⁠אַלְמָנָ֔ה כְּ⁠כָל־מִצְוָתְ⁠ךָ֖ אֲשֶׁ֣ר צִוִּיתָ֑⁠נִי לֹֽא־עָבַ֥רְתִּי מִ⁠מִּצְוֺתֶ֖י⁠ךָ וְ⁠לֹ֥א שָׁכָֽחְתִּי׃","wĕ⁠ʼámarĕţá̇֡ li⁠pĕnéy֩ yĕhwá֨h ʼèlòhe֜y⁠ká bi̇ʻa֧rĕţi̇y ha⁠qò֣̇deş̌ min-ha⁠bȧ֗yiţ wĕ⁠ga֨m nĕţaţi֤̇y⁠w la⁠lé̇wiy֙ wĕ⁠la⁠gé̇r֙ la⁠yá̇ţ֣wòm wĕ⁠lá⁠ʼalĕmáná֔h kĕ̇⁠kál-miẕĕwáţĕ⁠ká֖ ʼàşě֣r ẕiwi̇yţá֑⁠niy lòֽʼ-ʻába֥rĕţi̇y mi⁠mi̇ẕĕwֺţe֖y⁠ká wĕ⁠lò֥ʼ şá̌káֽẖĕţi̇y׃"],[26,14,"לֹא־אָכַ֨לְתִּי בְ⁠אֹנִ֜י מִמֶּ֗⁠נּוּ וְ⁠לֹא־בִעַ֤רְתִּי מִמֶּ֨⁠נּוּ֙ בְּ⁠טָמֵ֔א וְ⁠לֹא־נָתַ֥תִּי מִמֶּ֖⁠נּוּ לְ⁠מֵ֑ת שָׁמַ֗עְתִּי בְּ⁠קוֹל֙ יְהוָ֣ה אֱלֹהָ֔⁠י עָשִׂ֕יתִי כְּ⁠כֹ֖ל אֲשֶׁ֥ר צִוִּיתָֽ⁠נִי׃","lòʼ-ʼáka֨lĕţi̇y bĕ⁠ʼòni֜y mimė֗⁠ṅẇ wĕ⁠lòʼ-biʻa֤rĕţi̇y mimė֨⁠ṅẇ֙ bĕ̇⁠támé֔ʼ wĕ⁠lòʼ-náţa֥ţi̇y mimė֖⁠ṅẇ lĕ⁠mé֑ţ şá̌ma֗ʻĕţi̇y bĕ̇⁠qwòl֙ yĕhwá֣h ʼèlòhá֔⁠y ʻáşî֕yţiy kĕ̇⁠kò֖l ʼàşě֥r ẕiwi̇yţáֽ⁠niy׃"],[26,15,"הַשְׁקִיפָ⁠ה֩ מִ⁠מְּע֨וֹן קָדְשְׁ⁠ךָ֜ מִן־הַ⁠שָּׁמַ֗יִם וּ⁠בָרֵ֤ךְ אֶֽת־עַמְּ⁠ךָ֙ אֶת־יִשְׂרָאֵ֔ל וְ⁠אֵת֙ הָ⁠אֲדָמָ֔ה אֲשֶׁ֥ר נָתַ֖תָּה לָ֑⁠נוּ כַּ⁠אֲשֶׁ֤ר נִשְׁבַּ֨עְתָּ֙ לַ⁠אֲבֹתֵ֔י⁠נוּ אֶ֛רֶץ זָבַ֥ת חָלָ֖ב וּ⁠דְבָֽשׁ׃ס","haşĕ̌qiypá⁠h֩ mi⁠mĕ̇ʻ֨wòn qádĕşĕ̌⁠ká֜ min-ha⁠şá̇̌ma֗yim ẇ⁠báré֤kĕ ʼeֽţ-ʻamĕ̇⁠ká֙ ʼeţ-yişĕ̂ráʼé֔l wĕ⁠ʼéţ֙ há⁠ʼàdámá֔h ʼàşě֥r náţa֖ţá̇h lá֑⁠nẇ kȧ⁠ʼàşě֤r nişĕ̌bȧ֨ʻĕţá̇֙ la⁠ʼàbòţé֔y⁠nẇ ʼe֛reẕ zába֥ţ ẖálá֖b ẇ⁠dĕbáֽş̌׃s"],[26,16,"הַ⁠יּ֣וֹם הַ⁠זֶּ֗ה יְהוָ֨ה אֱלֹהֶ֜י⁠ךָ מְצַוְּ⁠ךָ֧ לַ⁠עֲשׂ֛וֹת אֶת־הַ⁠חֻקִּ֥ים הָ⁠אֵ֖לֶּה וְ⁠אֶת־הַ⁠מִּשְׁפָּטִ֑ים וְ⁠שָׁמַרְתָּ֤ וְ⁠עָשִׂ֨יתָ֙ אוֹתָ֔⁠ם בְּ⁠כָל־לְבָבְ⁠ךָ֖ וּ⁠בְ⁠כָל־נַפְשֶֽׁ⁠ךָ׃","ha⁠ẏ֣wòm ha⁠zė֗h yĕhwá֨h ʼèlòhe֜y⁠ká mĕẕawĕ̇⁠ká֧ la⁠ʻàş֛̂wòţ ʼeţ-ha⁠ẖuqi֥̇ym há⁠ʼé֖lėh wĕ⁠ʼeţ-ha⁠mi̇şĕ̌pá̇ti֑ym wĕ⁠şá̌marĕţá֤̇ wĕ⁠ʻáşî֨yţá֙ ʼwòţá֔⁠m bĕ̇⁠kál-lĕbábĕ⁠ká֖ ẇ⁠bĕ⁠kál-napĕşěֽ⁠ká׃"],[26,17,"אֶת־יְהוָ֥ה הֶאֱמַ֖רְתָּ הַ⁠יּ֑וֹם לִ⁠הְיוֹת֩ לְ⁠ךָ֨ לֵֽ⁠אלֹהִ֜ים וְ⁠לָ⁠לֶ֣כֶת בִּ⁠דְרָכָ֗י⁠ו וְ⁠לִ⁠שְׁמֹ֨ר חֻקָּ֧י⁠ו וּ⁠מִצְוֺתָ֛י⁠ו וּ⁠מִשְׁפָּטָ֖י⁠ו וְ⁠לִ⁠שְׁמֹ֥עַ בְּ⁠קֹלֽ⁠וֹ׃","ʼeţ-yĕhwá֥h heʼèma֖rĕţá̇ ha⁠ẏ֑wòm li⁠hĕywòţ֩ lĕ⁠ká֨ léֽ⁠ʼlòhi֜ym wĕ⁠lá⁠le֣keţ bi̇⁠dĕráká֗y⁠w wĕ⁠li⁠şĕ̌mò֨r ẖuqá֧̇y⁠w ẇ⁠miẕĕwֺţá֛y⁠w ẇ⁠mişĕ̌pá̇tá֖y⁠w wĕ⁠li⁠şĕ̌mò֥ʻa bĕ̇⁠qòlֽ⁠wò׃"],[26,18,"וַֽ⁠יהוָ֞ה הֶאֱמִֽירְ⁠ךָ֣ הַ⁠יּ֗וֹם לִ⁠הְי֥וֹת ל⁠וֹ֙ לְ⁠עַ֣ם סְגֻלָּ֔ה כַּ⁠אֲשֶׁ֖ר דִּבֶּר־לָ֑⁠ךְ וְ⁠לִ⁠שְׁמֹ֖ר כָּל־מִצְוֺתָֽי⁠ו׃","waֽ⁠yhwá֞h heʼèmiֽyrĕ⁠ká֣ ha⁠ẏ֗wòm li⁠hĕy֥wòţ l⁠wò֙ lĕ⁠ʻa֣m sĕgulá̇֔h kȧ⁠ʼàşě֖r di̇bėr-lá֑⁠kĕ wĕ⁠li⁠şĕ̌mò֖r ká̇l-miẕĕwֺţáֽy⁠w׃"],[26,19,"וּֽ⁠לְ⁠תִתְּ⁠ךָ֣ עֶלְי֗וֹן עַ֤ל כָּל־הַ⁠גּוֹיִם֙ אֲשֶׁ֣ר עָשָׂ֔ה לִ⁠תְהִלָּ֖ה וּ⁠לְ⁠שֵׁ֣ם וּ⁠לְ⁠תִפְאָ֑רֶת וְ⁠לִֽ⁠הְיֹתְ⁠ךָ֧ עַם־קָדֹ֛שׁ לַ⁠יהוָ֥ה אֱלֹהֶ֖י⁠ךָ כַּ⁠אֲשֶׁ֥ר דִּבֵּֽר׃ס","ẇֽ⁠lĕ⁠ţiţĕ̇⁠ká֣ ʻelĕy֗wòn ʻa֤l ká̇l-ha⁠ġwòyim֙ ʼàşě֣r ʻáşá̂֔h li⁠ţĕhilá֖̇h ẇ⁠lĕ⁠şé֣̌m ẇ⁠lĕ⁠ţipĕʼá֑reţ wĕ⁠liֽ⁠hĕyòţĕ⁠ká֧ ʻam-qádò֛ş̌ la⁠yhwá֥h ʼèlòhe֖y⁠ká kȧ⁠ʼàşě֥r di̇béֽ̇r׃s"],[27,1,"וַ⁠יְצַ֤ו מֹשֶׁה֙ וְ⁠זִקְנֵ֣י יִשְׂרָאֵ֔ל אֶת־הָ⁠עָ֖ם לֵ⁠אמֹ֑ר שָׁמֹר֙ אֶת־כָּל־הַ⁠מִּצְוָ֔ה אֲשֶׁ֧ר אָנֹכִ֛י מְצַוֶּ֥ה אֶתְ⁠כֶ֖ם הַ⁠יּֽוֹם׃","wa⁠yĕẕa֤w mòşěh֙ wĕ⁠ziqĕné֣y yişĕ̂ráʼé֔l ʼeţ-há⁠ʻá֖m lé⁠ʼmò֑r şá̌mòr֙ ʼeţ-ká̇l-ha⁠mi̇ẕĕwá֔h ʼàşě֧r ʼánòki֛y mĕẕawė֥h ʼeţĕ⁠ke֖m ha⁠ẏֽwòm׃"],[27,2,"וְ⁠הָיָ֗ה בַּ⁠יּוֹם֮ אֲשֶׁ֣ר תַּעַבְר֣וּ אֶת־הַ⁠יַּרְדֵּן֒ אֶל־הָ⁠אָ֕רֶץ אֲשֶׁר־יְהוָ֥ה אֱלֹהֶ֖י⁠ךָ נֹתֵ֣ן לָ֑⁠ךְ וַ⁠הֲקֵמֹתָ֤ לְ⁠ךָ֙ אֲבָנִ֣ים גְּדֹל֔וֹת וְ⁠שַׂדְתָּ֥ אֹתָ֖⁠ם בַּ⁠שִּֽׂיד׃","wĕ⁠háyá֗h bȧ⁠ẏwòm֮ ʼàşě֣r ţȧʻabĕr֣ẇ ʼeţ-ha⁠yȧrĕdé̇n֒ ʼel-há⁠ʼá֕reẕ ʼàşěr-yĕhwá֥h ʼèlòhe֖y⁠ká nòţé֣n lá֑⁠kĕ wa⁠hàqémòţá֤ lĕ⁠ká֙ ʼàbáni֣ym gĕ̇dòl֔wòţ wĕ⁠şâdĕţá֥̇ ʼòţá֖⁠m bȧ⁠şiֽ̇̂yd׃"],[27,3,"וְ⁠כָתַבְתָּ֣ עֲלֵי⁠הֶ֗ן אֶֽת־כָּל־דִּבְרֵ֛י הַ⁠תּוֹרָ֥ה הַ⁠זֹּ֖את בְּ⁠עָבְרֶ֑⁠ךָ לְמַ֡עַן אֲשֶׁר֩ תָּבֹ֨א אֶל־הָ⁠אָ֜רֶץ אֲֽשֶׁר־יְהוָ֥ה אֱלֹהֶ֣י⁠ךָ ׀ נֹתֵ֣ן לְ⁠ךָ֗ אֶ֣רֶץ זָבַ֤ת חָלָב֙ וּ⁠דְבַ֔שׁ כַּ⁠אֲשֶׁ֥ר דִּבֶּ֛ר יְהוָ֥ה אֱלֹהֵֽי־אֲבֹתֶ֖י⁠ךָ לָֽ⁠ךְ׃","wĕ⁠káţabĕţá֣̇ ʻàléy⁠he֗n ʼeֽţ-ká̇l-di̇bĕré֛y ha⁠ţ̇wòrá֥h ha⁠zò֖̇ʼţ bĕ̇⁠ʻábĕre֑⁠ká lĕma֡ʻan ʼàşěr֩ ţá̇bò֨ʼ ʼel-há⁠ʼá֜reẕ ʼàֽşěr-yĕhwá֥h ʼèlòhe֣y⁠ká ׀ nòţé֣n lĕ⁠ká֗ ʼe֣reẕ zába֤ţ ẖáláb֙ ẇ⁠dĕba֔ş̌ kȧ⁠ʼàşě֥r di̇bė֛r yĕhwá֥h ʼèlòhéֽy-ʼàbòţe֖y⁠ká láֽ⁠kĕ׃"],[27,4,"וְ⁠הָיָה֮ בְּ⁠עָבְרְ⁠כֶ֣ם אֶת־הַ⁠יַּרְדֵּן֒ תָּקִ֜ימוּ אֶת־הָ⁠אֲבָנִ֣ים הָ⁠אֵ֗לֶּה אֲשֶׁ֨ר אָנֹכִ֜י מְצַוֶּ֥ה אֶתְ⁠כֶ֛ם הַ⁠יּ֖וֹם בְּ⁠הַ֣ר עֵיבָ֑ל וְ⁠שַׂדְתָּ֥ אוֹתָ֖⁠ם בַּ⁠שִּֽׂיד׃","wĕ⁠háyáh֮ bĕ̇⁠ʻábĕrĕ⁠ke֣m ʼeţ-ha⁠yȧrĕdé̇n֒ ţá̇qi֜ymẇ ʼeţ-há⁠ʼàbáni֣ym há⁠ʼé֗lėh ʼàşě֨r ʼánòki֜y mĕẕawė֥h ʼeţĕ⁠ke֛m ha⁠ẏ֖wòm bĕ̇⁠ha֣r ʻéybá֑l wĕ⁠şâdĕţá֥̇ ʼwòţá֖⁠m bȧ⁠şiֽ̇̂yd׃"],[27,5,"וּ⁠בָנִ֤יתָ שָּׁם֙ מִזְבֵּ֔חַ לַ⁠יהוָ֖ה אֱלֹהֶ֑י⁠ךָ מִזְבַּ֣ח אֲבָנִ֔ים לֹא־תָנִ֥יף עֲלֵי⁠הֶ֖ם בַּרְזֶֽל׃","ẇ⁠báni֤yţá şá̇̌m֙ mizĕbé̇֔ẖa la⁠yhwá֖h ʼèlòhe֑y⁠ká mizĕbȧ֣ẖ ʼàbáni֔ym lòʼ-ţáni֥yp ʻàléy⁠he֖m bȧrĕzeֽl׃"],[27,6,"אֲבָנִ֤ים שְׁלֵמוֹת֙ תִּבְנֶ֔ה אֶת־מִזְבַּ֖ח יְהוָ֣ה אֱלֹהֶ֑י⁠ךָ וְ⁠הַעֲלִ֤יתָ עָלָי⁠ו֙ עוֹלֹ֔ת לַ⁠יהוָ֖ה אֱלֹהֶֽי⁠ךָ׃","ʼàbáni֤ym şĕ̌lémwòţ֙ ţi̇bĕne֔h ʼeţ-mizĕbȧ֖ẖ yĕhwá֣h ʼèlòhe֑y⁠ká wĕ⁠haʻàli֤yţá ʻáláy⁠w֙ ʻwòlò֔ţ la⁠yhwá֖h ʼèlòheֽy⁠ká׃"],[27,7,"וְ⁠זָבַחְתָּ֥ שְׁלָמִ֖ים וְ⁠אָכַ֣לְתָּ שָּׁ֑ם וְ⁠שָׂ֣מַחְתָּ֔ לִ⁠פְנֵ֖י יְהוָ֥ה אֱלֹהֶֽי⁠ךָ׃","wĕ⁠zábaẖĕţá֥̇ şĕ̌lámi֖ym wĕ⁠ʼáka֣lĕţá̇ şá֑̇̌m wĕ⁠şá֣̂maẖĕţá̇֔ li⁠pĕné֖y yĕhwá֥h ʼèlòheֽy⁠ká׃"],[27,8,"וְ⁠כָתַבְתָּ֣ עַל־הָ⁠אֲבָנִ֗ים אֶֽת־כָּל־דִּבְרֵ֛י הַ⁠תּוֹרָ֥ה הַ⁠זֹּ֖את בַּאֵ֥ר הֵיטֵֽב׃ס","wĕ⁠káţabĕţá֣̇ ʻal-há⁠ʼàbáni֗ym ʼeֽţ-ká̇l-di̇bĕré֛y ha⁠ţ̇wòrá֥h ha⁠zò֖̇ʼţ bȧʼé֥r héytéֽb׃s"],[27,9,"וַ⁠יְדַבֵּ֤ר מֹשֶׁה֙ וְ⁠הַ⁠כֹּהֲנִ֣ים הַ⁠לְוִיִּ֔ם אֶ֥ל כָּל־יִשְׂרָאֵ֖ל לֵ⁠אמֹ֑ר הַסְכֵּ֤ת ׀ וּ⁠שְׁמַע֙ יִשְׂרָאֵ֔ל הַ⁠יּ֤וֹם הַ⁠זֶּה֙ נִהְיֵ֣יתָֽ לְ⁠עָ֔ם לַ⁠יהוָ֖ה אֱלֹהֶֽי⁠ךָ׃","wa⁠yĕdabé֤̇r mòşěh֙ wĕ⁠ha⁠kò̇hàni֣ym ha⁠lĕwiyi̇֔m ʼe֥l ká̇l-yişĕ̂ráʼé֖l lé⁠ʼmò֑r hasĕké֤̇ţ ׀ ẇ⁠şĕ̌maʻ֙ yişĕ̂ráʼé֔l ha⁠ẏ֤wòm ha⁠zėh֙ nihĕyé֣yţáֽ lĕ⁠ʻá֔m la⁠yhwá֖h ʼèlòheֽy⁠ká׃"],[27,10,"וְ⁠שָׁ֣מַעְתָּ֔ בְּ⁠ק֖וֹל יְהוָ֣ה אֱלֹהֶ֑י⁠ךָ וְ⁠עָשִׂ֤יתָ אֶת־מִצְוֺתָ⁠ו֙ וְ⁠אֶת־חֻקָּ֔י⁠ו אֲשֶׁ֛ר אָנֹכִ֥י מְצַוְּ⁠ךָ֖ הַ⁠יּֽוֹם׃ס","wĕ⁠şá֣̌maʻĕţá̇֔ bĕ̇⁠q֖wòl yĕhwá֣h ʼèlòhe֑y⁠ká wĕ⁠ʻáşî֤yţá ʼeţ-miẕĕwֺţá⁠w֙ wĕ⁠ʼeţ-ẖuqá̇֔y⁠w ʼàşě֛r ʼánòki֥y mĕẕawĕ̇⁠ká֖ ha⁠ẏֽwòm׃s"],[27,11,"וַ⁠יְצַ֤ו מֹשֶׁה֙ אֶת־הָ⁠עָ֔ם בַּ⁠יּ֥וֹם הַ⁠ה֖וּא לֵ⁠אמֹֽר׃","wa⁠yĕẕa֤w mòşěh֙ ʼeţ-há⁠ʻá֔m bȧ⁠ẏ֥wòm ha⁠h֖ẇʼ lé⁠ʼmòֽr׃"],[27,12,"אֵ֠לֶּה יַֽעַמְד֞וּ לְ⁠בָרֵ֤ךְ אֶת־הָ⁠עָם֙ עַל־הַ֣ר גְּרִזִ֔ים בְּ⁠עָבְרְ⁠כֶ֖ם אֶת־הַ⁠יַּרְדֵּ֑ן שִׁמְעוֹן֙ וְ⁠לֵוִ֣י וִֽ⁠יהוּדָ֔ה וְ⁠יִשָּׂשכָ֖ר וְ⁠יוֹסֵ֥ף וּ⁠בִנְיָמִֽן׃","ʼé֠lėh yaֽʻamĕd֞ẇ lĕ⁠báré֤kĕ ʼeţ-há⁠ʻám֙ ʻal-ha֣r gĕ̇rizi֔ym bĕ̇⁠ʻábĕrĕ⁠ke֖m ʼeţ-ha⁠yȧrĕdé֑̇n şǐmĕʻwòn֙ wĕ⁠léwi֣y wiֽ⁠yhẇdá֔h wĕ⁠yişá̇̂şká֖r wĕ⁠ywòsé֥p ẇ⁠binĕyámiֽn׃"],[27,13,"וְ⁠אֵ֛לֶּה יַֽעַמְד֥וּ עַל־הַ⁠קְּלָלָ֖ה בְּ⁠הַ֣ר עֵיבָ֑ל רְאוּבֵן֙ גָּ֣ד וְ⁠אָשֵׁ֔ר וּ⁠זְבוּלֻ֖ן דָּ֥ן וְ⁠נַפְתָּלִֽי׃","wĕ⁠ʼé֛lėh yaֽʻamĕd֥ẇ ʻal-ha⁠qĕ̇lálá֖h bĕ̇⁠ha֣r ʻéybá֑l rĕʼẇbén֙ gá֣̇d wĕ⁠ʼáşé̌֔r ẇ⁠zĕbẇlu֖n dá֥̇n wĕ⁠napĕţá̇liֽy׃"],[27,14,"וְ⁠עָנ֣וּ הַ⁠לְוִיִּ֗ם וְ⁠אָֽמְר֛וּ אֶל־כָּל־אִ֥ישׁ יִשְׂרָאֵ֖ל ק֥וֹל רָֽם׃ס","wĕ⁠ʻán֣ẇ ha⁠lĕwiyi̇֗m wĕ⁠ʼáֽmĕr֛ẇ ʼel-ká̇l-ʼi֥yş̌ yişĕ̂ráʼé֖l q֥wòl ráֽm׃s"],[27,15,"אָר֣וּר הָ⁠אִ֡ישׁ אֲשֶׁ֣ר יַעֲשֶׂה֩ פֶ֨סֶל וּ⁠מַסֵּכָ֜ה תּוֹעֲבַ֣ת יְהוָ֗ה מַעֲשֵׂ֛ה יְדֵ֥י חָרָ֖שׁ וְ⁠שָׂ֣ם בַּ⁠סָּ֑תֶר וְ⁠עָנ֧וּ כָל־הָ⁠עָ֛ם וְ⁠אָמְר֖וּ אָמֵֽן׃ס","ʼár֣ẇr há⁠ʼi֡yş̌ ʼàşě֣r yaʻàşêh֩ pe֨sel ẇ⁠masé̇ká֜h ţ̇wòʻàba֣ţ yĕhwá֗h maʻàşé֛̂h yĕdé֥y ẖárá֖ş̌ wĕ⁠şá֣̂m bȧ⁠sá֑̇ţer wĕ⁠ʻán֧ẇ kál-há⁠ʻá֛m wĕ⁠ʼámĕr֖ẇ ʼáméֽn׃s"],[27,16,"אָר֕וּר מַקְלֶ֥ה אָבִ֖י⁠ו וְ⁠אִמּ֑⁠וֹ וְ⁠אָמַ֥ר כָּל־הָ⁠עָ֖ם אָמֵֽן׃ס","ʼár֕ẇr maqĕle֥h ʼábi֖y⁠w wĕ⁠ʼiṁ֑⁠wò wĕ⁠ʼáma֥r ká̇l-há⁠ʻá֖m ʼáméֽn׃s"],[27,17,"אָר֕וּר מַסִּ֖יג גְּב֣וּל רֵעֵ֑⁠הוּ וְ⁠אָמַ֥ר כָּל־הָ⁠עָ֖ם אָמֵֽן׃ס","ʼár֕ẇr masi֖̇yg gĕ̇b֣ẇl réʻé֑⁠hẇ wĕ⁠ʼáma֥r ká̇l-há⁠ʻá֖m ʼáméֽn׃s"],[27,18,"אָר֕וּר מַשְׁגֶּ֥ה עִוֵּ֖ר בַּ⁠דָּ֑רֶךְ וְ⁠אָמַ֥ר כָּל־הָ⁠עָ֖ם אָמֵֽן׃ס","ʼár֕ẇr maşĕ̌gė֥h ʻiwé֖̇r bȧ⁠dá֑̇rekĕ wĕ⁠ʼáma֥r ká̇l-há⁠ʻá֖m ʼáméֽn׃s"],[27,19,"אָר֗וּר מַטֶּ֛ה מִשְׁפַּ֥ט גֵּר־יָת֖וֹם וְ⁠אַלְמָנָ֑ה וְ⁠אָמַ֥ר כָּל־הָ⁠עָ֖ם אָמֵֽן׃ס","ʼár֗ẇr matė֛h mişĕ̌pȧ֥t gé̇r-yáţ֖wòm wĕ⁠ʼalĕmáná֑h wĕ⁠ʼáma֥r ká̇l-há⁠ʻá֖m ʼáméֽn׃s"],[27,20,"אָר֗וּר שֹׁכֵב֙ עִם־אֵ֣שֶׁת אָבִ֔י⁠ו כִּ֥י גִלָּ֖ה כְּנַ֣ף אָבִ֑י⁠ו וְ⁠אָמַ֥ר כָּל־הָ⁠עָ֖ם אָמֵֽן׃ס","ʼár֗ẇr şò̌kéb֙ ʻim-ʼé֣şěţ ʼábi֔y⁠w ki֥̇y gilá֖̇h kĕ̇na֣p ʼábi֑y⁠w wĕ⁠ʼáma֥r ká̇l-há⁠ʻá֖m ʼáméֽn׃s"],[27,21,"אָר֕וּר שֹׁכֵ֖ב עִם־כָּל־בְּהֵמָ֑ה וְ⁠אָמַ֥ר כָּל־הָ⁠עָ֖ם אָמֵֽן׃ס","ʼár֕ẇr şò̌ké֖b ʻim-ká̇l-bĕ̇hémá֑h wĕ⁠ʼáma֥r ká̇l-há⁠ʻá֖m ʼáméֽn׃s"],[27,22,"אָר֗וּר שֹׁכֵב֙ עִם־אֲחֹת֔⁠וֹ בַּת־אָבִ֖י⁠ו א֣וֹ בַת־אִמּ֑⁠וֹ וְ⁠אָמַ֥ר כָּל־הָ⁠עָ֖ם אָמֵֽן׃ס","ʼár֗ẇr şò̌kéb֙ ʻim-ʼàẖòţ֔⁠wò bȧţ-ʼábi֖y⁠w ʼ֣wò baţ-ʼiṁ֑⁠wò wĕ⁠ʼáma֥r ká̇l-há⁠ʻá֖m ʼáméֽn׃s"],[27,23,"אָר֕וּר שֹׁכֵ֖ב עִם־חֹֽתַנְתּ֑⁠וֹ וְ⁠אָמַ֥ר כָּל־הָ⁠עָ֖ם אָמֵֽן׃ס","ʼár֕ẇr şò̌ké֖b ʻim-ẖòֽţanĕţ֑̇⁠wò wĕ⁠ʼáma֥r ká̇l-há⁠ʻá֖m ʼáméֽn׃s"],[27,24,"אָר֕וּר מַכֵּ֥ה רֵעֵ֖⁠הוּ בַּ⁠סָּ֑תֶר וְ⁠אָמַ֥ר כָּל־הָ⁠עָ֖ם אָמֵֽן׃ס","ʼár֕ẇr maké֥̇h réʻé֖⁠hẇ bȧ⁠sá֑̇ţer wĕ⁠ʼáma֥r ká̇l-há⁠ʻá֖m ʼáméֽn׃s"],[27,25,"אָרוּר֙ לֹקֵ֣חַ שֹׁ֔חַד לְ⁠הַכּ֥וֹת נֶ֖פֶשׁ דָּ֣ם נָקִ֑י וְ⁠אָמַ֥ר כָּל־הָ⁠עָ֖ם אָמֵֽן׃ס","ʼárẇr֙ lòqé֣ẖa şò̌֔ẖad lĕ⁠hak֥̇wòţ ne֖peş̌ dá֣̇m náqi֑y wĕ⁠ʼáma֥r ká̇l-há⁠ʻá֖m ʼáméֽn׃s"],[27,26,"אָר֗וּר אֲשֶׁ֧ר לֹא־יָקִ֛ים אֶת־דִּבְרֵ֥י הַ⁠תּוֹרָֽה־הַ⁠זֹּ֖את לַ⁠עֲשׂ֣וֹת אוֹתָ֑⁠ם וְ⁠אָמַ֥ר כָּל־הָ⁠עָ֖ם אָמֵֽן׃פ","ʼár֗ẇr ʼàşě֧r lòʼ-yáqi֛ym ʼeţ-di̇bĕré֥y ha⁠ţ̇wòráֽh-ha⁠zò֖̇ʼţ la⁠ʻàş֣̂wòţ ʼwòţá֑⁠m wĕ⁠ʼáma֥r ká̇l-há⁠ʻá֖m ʼáméֽn׃p"],[28,1,"וְ⁠הָיָ֗ה אִם־שָׁמ֤וֹעַ תִּשְׁמַע֙ בְּ⁠קוֹל֙ יְהוָ֣ה אֱלֹהֶ֔י⁠ךָ לִ⁠שְׁמֹ֤ר לַ⁠עֲשׂוֹת֙ אֶת־כָּל־מִצְוֺתָ֔י⁠ו אֲשֶׁ֛ר אָנֹכִ֥י מְצַוְּ⁠ךָ֖ הַ⁠יּ֑וֹם וּ⁠נְתָ֨נְ⁠ךָ֜ יְהוָ֤ה אֱלֹהֶ֨י⁠ךָ֙ עֶלְי֔וֹן עַ֖ל כָּל־גּוֹיֵ֥י הָ⁠אָֽרֶץ׃","wĕ⁠háyá֗h ʼim-şá̌m֤wòʻa ţi̇şĕ̌maʻ֙ bĕ̇⁠qwòl֙ yĕhwá֣h ʼèlòhe֔y⁠ká li⁠şĕ̌mò֤r la⁠ʻàş̂wòţ֙ ʼeţ-ká̇l-miẕĕwֺţá֔y⁠w ʼàşě֛r ʼánòki֥y mĕẕawĕ̇⁠ká֖ ha⁠ẏ֑wòm ẇ⁠nĕţá֨nĕ⁠ká֜ yĕhwá֤h ʼèlòhe֨y⁠ká֙ ʻelĕy֔wòn ʻa֖l ká̇l-ġwòyé֥y há⁠ʼáֽreẕ׃"],[28,2,"וּ⁠בָ֧אוּ עָלֶ֛י⁠ךָ כָּל־הַ⁠בְּרָכ֥וֹת הָ⁠אֵ֖לֶּה וְ⁠הִשִּׂיגֻ֑⁠ךָ כִּ֣י תִשְׁמַ֔ע בְּ⁠ק֖וֹל יְהוָ֥ה אֱלֹהֶֽי⁠ךָ׃","ẇ⁠bá֧ʼẇ ʻále֛y⁠ká ká̇l-ha⁠bĕ̇rák֥wòţ há⁠ʼé֖lėh wĕ⁠hişi̇̂ygu֑⁠ká ki֣̇y ţişĕ̌ma֔ʻ bĕ̇⁠q֖wòl yĕhwá֥h ʼèlòheֽy⁠ká׃"],[28,3,"בָּר֥וּךְ אַתָּ֖ה בָּ⁠עִ֑יר וּ⁠בָר֥וּךְ אַתָּ֖ה בַּ⁠שָּׂדֶֽה׃","bá̇r֥ẇkĕ ʼaţá֖̇h bá̇⁠ʻi֑yr ẇ⁠bár֥ẇkĕ ʼaţá֖̇h bȧ⁠şá̇̂deֽh׃"],[28,4,"בָּר֧וּךְ פְּרִֽי־בִטְנְ⁠ךָ֛ וּ⁠פְרִ֥י אַדְמָתְ⁠ךָ֖ וּ⁠פְרִ֣י בְהֶמְתֶּ֑⁠ךָ שְׁגַ֥ר אֲלָפֶ֖י⁠ךָ וְ⁠עַשְׁתְּר֥וֹת צֹאנֶֽ⁠ךָ׃","bá̇r֧ẇkĕ pĕ̇riֽy-bitĕnĕ⁠ká֛ ẇ⁠pĕri֥y ʼadĕmáţĕ⁠ká֖ ẇ⁠pĕri֣y bĕhemĕţė֑⁠ká şĕ̌ga֥r ʼàlápe֖y⁠ká wĕ⁠ʻaşĕ̌ţĕ̇r֥wòţ ẕòʼneֽ⁠ká׃"],[28,5,"בָּר֥וּךְ טַנְאֲ⁠ךָ֖ וּ⁠מִשְׁאַרְתֶּֽ⁠ךָ׃","bá̇r֥ẇkĕ tanĕʼà⁠ká֖ ẇ⁠mişĕ̌ʼarĕţėֽ⁠ká׃"],[28,6,"בָּר֥וּךְ אַתָּ֖ה בְּ⁠בֹאֶ֑⁠ךָ וּ⁠בָר֥וּךְ אַתָּ֖ה בְּ⁠צֵאתֶֽ⁠ךָ׃","bá̇r֥ẇkĕ ʼaţá֖̇h bĕ̇⁠bòʼe֑⁠ká ẇ⁠bár֥ẇkĕ ʼaţá֖̇h bĕ̇⁠ẕéʼţeֽ⁠ká׃"],[28,7,"יִתֵּ֨ן יְהוָ֤ה אֶת־אֹיְבֶ֨י⁠ךָ֙ הַ⁠קָּמִ֣ים עָלֶ֔י⁠ךָ נִגָּפִ֖ים לְ⁠פָנֶ֑י⁠ךָ בְּ⁠דֶ֤רֶךְ אֶחָד֙ יֵצְא֣וּ אֵלֶ֔י⁠ךָ וּ⁠בְ⁠שִׁבְעָ֥ה דְרָכִ֖ים יָנ֥וּסוּ לְ⁠פָנֶֽי⁠ךָ׃","yiţé̇֨n yĕhwá֤h ʼeţ-ʼòyĕbe֨y⁠ká֙ ha⁠qá̇mi֣ym ʻále֔y⁠ká nigá̇pi֖ym lĕ⁠páne֑y⁠ká bĕ̇⁠de֤rekĕ ʼeẖád֙ yéẕĕʼ֣ẇ ʼéle֔y⁠ká ẇ⁠bĕ⁠şǐbĕʻá֥h dĕráki֖ym yán֥ẇsẇ lĕ⁠páneֽy⁠ká׃"],[28,8,"יְצַ֨ו יְהוָ֤ה אִתְּ⁠ךָ֙ אֶת־הַ⁠בְּרָכָ֔ה בַּ⁠אֲסָמֶ֕י⁠ךָ וּ⁠בְ⁠כֹ֖ל מִשְׁלַ֣ח יָדֶ֑⁠ךָ וּ⁠בֵ֣רַכְ⁠ךָ֔ בָּ⁠אָ֕רֶץ אֲשֶׁר־יְהוָ֥ה אֱלֹהֶ֖י⁠ךָ נֹתֵ֥ן לָֽ⁠ךְ׃","yĕẕa֨w yĕhwá֤h ʼiţĕ̇⁠ká֙ ʼeţ-ha⁠bĕ̇ráká֔h bȧ⁠ʼàsáme֕y⁠ká ẇ⁠bĕ⁠kò֖l mişĕ̌la֣ẖ yáde֑⁠ká ẇ⁠bé֣rakĕ⁠ká֔ bá̇⁠ʼá֕reẕ ʼàşěr-yĕhwá֥h ʼèlòhe֖y⁠ká nòţé֥n láֽ⁠kĕ׃"],[28,9,"יְקִֽימְ⁠ךָ֨ יְהוָ֥ה ל⁠וֹ֙ לְ⁠עַ֣ם קָד֔וֹשׁ כַּ⁠אֲשֶׁ֖ר נִֽשְׁבַּֽע־לָ֑⁠ךְ כִּ֣י תִשְׁמֹ֗ר אֶת־מִצְוֺת֙ יְהוָ֣ה אֱלֹהֶ֔י⁠ךָ וְ⁠הָלַכְתָּ֖ בִּ⁠דְרָכָֽי⁠ו׃","yĕqiֽymĕ⁠ká֨ yĕhwá֥h l⁠wò֙ lĕ⁠ʻa֣m qád֔wòş̌ kȧ⁠ʼàşě֖r niֽşĕ̌bȧֽʻ-lá֑⁠kĕ ki֣̇y ţişĕ̌mò֗r ʼeţ-miẕĕwֺţ֙ yĕhwá֣h ʼèlòhe֔y⁠ká wĕ⁠hálakĕţá֖̇ bi̇⁠dĕrákáֽy⁠w׃"],[28,10,"וְ⁠רָאוּ֙ כָּל־עַמֵּ֣י הָ⁠אָ֔רֶץ כִּ֛י שֵׁ֥ם יְהוָ֖ה נִקְרָ֣א עָלֶ֑י⁠ךָ וְ⁠יָֽרְא֖וּ מִמֶּֽ⁠ךָּ׃","wĕ⁠ráʼẇ֙ ká̇l-ʻamé֣̇y há⁠ʼá֔reẕ ki֛̇y şé֥̌m yĕhwá֖h niqĕrá֣ʼ ʻále֑y⁠ká wĕ⁠yáֽrĕʼ֖ẇ mimėֽ⁠ká̇׃"],[28,11,"וְ⁠הוֹתִֽרְ⁠ךָ֤ יְהוָה֙ לְ⁠טוֹבָ֔ה בִּ⁠פְרִ֧י בִטְנְ⁠ךָ֛ וּ⁠בִ⁠פְרִ֥י בְהַמְתְּ⁠ךָ֖ וּ⁠בִ⁠פְרִ֣י אַדְמָתֶ֑⁠ךָ עַ֚ל הָ⁠אֲדָמָ֔ה אֲשֶׁ֨ר נִשְׁבַּ֧ע יְהוָ֛ה לַ⁠אֲבֹתֶ֖י⁠ךָ לָ֥⁠תֶת לָֽ⁠ךְ׃","wĕ⁠hwòţiֽrĕ⁠ká֤ yĕhwáh֙ lĕ⁠twòbá֔h bi̇⁠pĕri֧y bitĕnĕ⁠ká֛ ẇ⁠bi⁠pĕri֥y bĕhamĕţĕ̇⁠ká֖ ẇ⁠bi⁠pĕri֣y ʼadĕmáţe֑⁠ká ʻa֚l há⁠ʼàdámá֔h ʼàşě֨r nişĕ̌bȧ֧ʻ yĕhwá֛h la⁠ʼàbòţe֖y⁠ká lá֥⁠ţeţ láֽ⁠kĕ׃"],[28,12,"יִפְתַּ֣ח יְהוָ֣ה ׀ לְ֠⁠ךָ אֶת־אוֹצָר֨⁠וֹ הַ⁠טּ֜וֹב אֶת־הַ⁠שָּׁמַ֗יִם לָ⁠תֵ֤ת מְטַֽר־אַרְצְ⁠ךָ֙ בְּ⁠עִתּ֔⁠וֹ וּ⁠לְ⁠בָרֵ֕ךְ אֵ֖ת כָּל־מַעֲשֵׂ֣ה יָדֶ֑⁠ךָ וְ⁠הִלְוִ֨יתָ֙ גּוֹיִ֣ם רַבִּ֔ים וְ⁠אַתָּ֖ה לֹ֥א תִלְוֶֽה׃","yipĕţȧ֣ẖ yĕhwá֣h ׀ lĕ֠⁠ká ʼeţ-ʼwòẕár֨⁠wò ha⁠ṫ֜wòb ʼeţ-ha⁠şá̇̌ma֗yim lá⁠ţé֤ţ mĕtaֽr-ʼarĕẕĕ⁠ká֙ bĕ̇⁠ʻiţ̇֔⁠wò ẇ⁠lĕ⁠báré֕kĕ ʼé֖ţ ká̇l-maʻàşé֣̂h yáde֑⁠ká wĕ⁠hilĕwi֨yţá֙ ġwòyi֣m rabi̇֔ym wĕ⁠ʼaţá֖̇h lò֥ʼ ţilĕweֽh׃"],[28,13,"וּ⁠נְתָֽנְ⁠ךָ֨ יְהוָ֤ה לְ⁠רֹאשׁ֙ וְ⁠לֹ֣א לְ⁠זָנָ֔ב וְ⁠הָיִ֨יתָ֙ רַ֣ק לְ⁠מַ֔עְלָ⁠ה וְ⁠לֹ֥א תִהְיֶ֖ה לְ⁠מָ֑טָּה כִּֽי־תִשְׁמַ֞ע אֶל־מִצְוֺ֣ת ׀ יְהוָ֣ה אֱלֹהֶ֗י⁠ךָ אֲשֶׁ֨ר אָנֹכִ֧י מְצַוְּ⁠ךָ֛ הַ⁠יּ֖וֹם לִ⁠שְׁמֹ֥ר וְ⁠לַ⁠עֲשֽׂוֹת׃","ẇ⁠nĕţáֽnĕ⁠ká֨ yĕhwá֤h lĕ⁠ròʼş̌֙ wĕ⁠lò֣ʼ lĕ⁠záná֔b wĕ⁠háyi֨yţá֙ ra֣q lĕ⁠ma֔ʻĕlá⁠h wĕ⁠lò֥ʼ ţihĕye֖h lĕ⁠má֑tá̇h kiֽ̇y-ţişĕ̌ma֞ʻ ʼel-miẕĕwֺ֣ţ ׀ yĕhwá֣h ʼèlòhe֗y⁠ká ʼàşě֨r ʼánòki֧y mĕẕawĕ̇⁠ká֛ ha⁠ẏ֖wòm li⁠şĕ̌mò֥r wĕ⁠la⁠ʻàşֽ̂wòţ׃"],[28,14,"וְ⁠לֹ֣א תָס֗וּר מִ⁠כָּל־הַ⁠דְּבָרִים֙ אֲשֶׁ֨ר אָנֹכִ֜י מְצַוֶּ֥ה אֶתְ⁠כֶ֛ם הַ⁠יּ֖וֹם יָמִ֣ין וּ⁠שְׂמֹ֑אול לָ⁠לֶ֗כֶת אַחֲרֵ֛י אֱלֹהִ֥ים אֲחֵרִ֖ים לְ⁠עָבְדָֽ⁠ם׃ס","wĕ⁠lò֣ʼ ţás֗ẇr mi⁠ká̇l-ha⁠dĕ̇báriym֙ ʼàşě֨r ʼánòki֜y mĕẕawė֥h ʼeţĕ⁠ke֛m ha⁠ẏ֖wòm yámi֣yn ẇ⁠şĕ̂mò֑ʼwl lá⁠le֗keţ ʼaẖàré֛y ʼèlòhi֥ym ʼàẖéri֖ym lĕ⁠ʻábĕdáֽ⁠m׃s"],[28,15,"וְ⁠הָיָ֗ה אִם־לֹ֤א תִשְׁמַע֙ בְּ⁠קוֹל֙ יְהוָ֣ה אֱלֹהֶ֔י⁠ךָ לִ⁠שְׁמֹ֤ר לַ⁠עֲשׂוֹת֙ אֶת־כָּל־מִצְוֺתָ֣י⁠ו וְ⁠חֻקֹּתָ֔י⁠ו אֲשֶׁ֛ר אָנֹכִ֥י מְצַוְּ⁠ךָ֖ הַ⁠יּ֑וֹם וּ⁠בָ֧אוּ עָלֶ֛י⁠ךָ כָּל־הַ⁠קְּלָל֥וֹת הָ⁠אֵ֖לֶּה וְ⁠הִשִּׂיגֽוּ⁠ךָ׃","wĕ⁠háyá֗h ʼim-lò֤ʼ ţişĕ̌maʻ֙ bĕ̇⁠qwòl֙ yĕhwá֣h ʼèlòhe֔y⁠ká li⁠şĕ̌mò֤r la⁠ʻàş̂wòţ֙ ʼeţ-ká̇l-miẕĕwֺţá֣y⁠w wĕ⁠ẖuqò̇ţá֔y⁠w ʼàşě֛r ʼánòki֥y mĕẕawĕ̇⁠ká֖ ha⁠ẏ֑wòm ẇ⁠bá֧ʼẇ ʻále֛y⁠ká ká̇l-ha⁠qĕ̇lál֥wòţ há⁠ʼé֖lėh wĕ⁠hişi̇̂ygֽẇ⁠ká׃"],[28,16,"אָר֥וּר אַתָּ֖ה בָּ⁠עִ֑יר וְ⁠אָר֥וּר אַתָּ֖ה בַּ⁠שָּׂדֶֽה׃","ʼár֥ẇr ʼaţá֖̇h bá̇⁠ʻi֑yr wĕ⁠ʼár֥ẇr ʼaţá֖̇h bȧ⁠şá̇̂deֽh׃"],[28,17,"אָר֥וּר טַנְאֲ⁠ךָ֖ וּ⁠מִשְׁאַרְתֶּֽ⁠ךָ׃","ʼár֥ẇr tanĕʼà⁠ká֖ ẇ⁠mişĕ̌ʼarĕţėֽ⁠ká׃"],[28,18,"אָר֥וּר פְּרִֽי־בִטְנְ⁠ךָ֖ וּ⁠פְרִ֣י אַדְמָתֶ֑⁠ךָ שְׁגַ֥ר אֲלָפֶ֖י⁠ךָ וְ⁠עַשְׁתְּר֥וֹת צֹאנֶֽ⁠ךָ׃","ʼár֥ẇr pĕ̇riֽy-bitĕnĕ⁠ká֖ ẇ⁠pĕri֣y ʼadĕmáţe֑⁠ká şĕ̌ga֥r ʼàlápe֖y⁠ká wĕ⁠ʻaşĕ̌ţĕ̇r֥wòţ ẕòʼneֽ⁠ká׃"],[28,19,"אָר֥וּר אַתָּ֖ה בְּ⁠בֹאֶ֑⁠ךָ וְ⁠אָר֥וּר אַתָּ֖ה בְּ⁠צֵאתֶֽ⁠ךָ׃","ʼár֥ẇr ʼaţá֖̇h bĕ̇⁠bòʼe֑⁠ká wĕ⁠ʼár֥ẇr ʼaţá֖̇h bĕ̇⁠ẕéʼţeֽ⁠ká׃"],[28,20,"יְשַׁלַּ֣ח יְהוָ֣ה ׀ בְּ֠⁠ךָ אֶת־הַ⁠מְּאֵרָ֤ה אֶת־הַ⁠מְּהוּמָה֙ וְ⁠אֶת־הַ⁠מִּגְעֶ֔רֶת בְּ⁠כָל־מִשְׁלַ֥ח יָדְ⁠ךָ֖ אֲשֶׁ֣ר תַּעֲשֶׂ֑ה עַ֣ד הִשָּֽׁמֶדְ⁠ךָ֤ וְ⁠עַד־אֲבָדְ⁠ךָ֙ מַהֵ֔ר מִ⁠פְּנֵ֛י רֹ֥עַ מַֽעֲלָלֶ֖י⁠ךָ אֲשֶׁ֥ר עֲזַבְתָּֽ⁠נִי׃","yĕşǎlȧ֣ẖ yĕhwá֣h ׀ bĕ̇֠⁠ká ʼeţ-ha⁠mĕ̇ʼérá֤h ʼeţ-ha⁠mĕ̇hẇmáh֙ wĕ⁠ʼeţ-ha⁠mi̇gĕʻe֔reţ bĕ̇⁠kál-mişĕ̌la֥ẖ yádĕ⁠ká֖ ʼàşě֣r ţȧʻàşê֑h ʻa֣d hişáֽ̇̌medĕ⁠ká֤ wĕ⁠ʻad-ʼàbádĕ⁠ká֙ mahé֔r mi⁠pĕ̇né֛y rò֥ʻa maֽʻàlále֖y⁠ká ʼàşě֥r ʻàzabĕţáֽ̇⁠niy׃"],[28,21,"יַדְבֵּ֧ק יְהוָ֛ה בְּ⁠ךָ֖ אֶת־הַ⁠דָּ֑בֶר עַ֚ד כַּלֹּת֣⁠וֹ אֹֽתְ⁠ךָ֔ מֵ⁠עַל֙ הָֽ⁠אֲדָמָ֔ה אֲשֶׁר־אַתָּ֥ה בָא־שָׁ֖מָּ⁠ה לְ⁠רִשְׁתָּֽ⁠הּ׃","yadĕbé֧̇q yĕhwá֛h bĕ̇⁠ká֖ ʼeţ-ha⁠dá֑̇ber ʻa֚d kȧlò̇ţ֣⁠wò ʼòֽţĕ⁠ká֔ mé⁠ʻal֙ háֽ⁠ʼàdámá֔h ʼàşěr-ʼaţá֥̇h báʼ-şá֖̌má̇⁠h lĕ⁠rişĕ̌ţáֽ̇⁠ḣ׃"],[28,22,"יַכְּ⁠כָ֣ה יְ֠הוָה בַּ⁠שַּׁחֶ֨פֶת וּ⁠בַ⁠קַּדַּ֜חַת וּ⁠בַ⁠דַּלֶּ֗קֶת וּ⁠בַֽ⁠חַרְחֻר֙ וּ⁠בַ⁠חֶ֔רֶב וּ⁠בַ⁠שִּׁדָּפ֖וֹן וּ⁠בַ⁠יֵּרָק֑וֹן וּ⁠רְדָפ֖וּ⁠ךָ עַ֥ד אָבְדֶֽ⁠ךָ׃","yakĕ̇⁠ká֣h yĕ֠hwáh bȧ⁠şȧ̌ẖe֨peţ ẇ⁠ba⁠qȧdȧ֜ẖaţ ẇ⁠ba⁠dȧlė֗qeţ ẇ⁠baֽ⁠ẖarĕẖur֙ ẇ⁠ba⁠ẖe֔reb ẇ⁠ba⁠şi̇̌dá̇p֖wòn ẇ⁠ba⁠yé̇ráq֑wòn ẇ⁠rĕdáp֖ẇ⁠ká ʻa֥d ʼábĕdeֽ⁠ká׃"],[28,23,"וְ⁠הָי֥וּ שָׁמֶ֛י⁠ךָ אֲשֶׁ֥ר עַל־רֹאשְׁ⁠ךָ֖ נְחֹ֑שֶׁת וְ⁠הָ⁠אָ֥רֶץ אֲשֶׁר־תַּחְתֶּ֖י⁠ךָ בַּרְזֶֽל׃","wĕ⁠háy֥ẇ şá̌me֛y⁠ká ʼàşě֥r ʻal-ròʼşĕ̌⁠ká֖ nĕẖò֑şěţ wĕ⁠há⁠ʼá֥reẕ ʼàşěr-ţȧẖĕţė֖y⁠ká bȧrĕzeֽl׃"],[28,24,"יִתֵּ֧ן יְהוָ֛ה אֶת־מְטַ֥ר אַרְצְ⁠ךָ֖ אָבָ֣ק וְ⁠עָפָ֑ר מִן־הַ⁠שָּׁמַ֨יִם֙ יֵרֵ֣ד עָלֶ֔י⁠ךָ עַ֖ד הִשָּׁמְדָֽ⁠ךְ׃","yiţé֧̇n yĕhwá֛h ʼeţ-mĕta֥r ʼarĕẕĕ⁠ká֖ ʼábá֣q wĕ⁠ʻápá֑r min-ha⁠şá̇̌ma֨yim֙ yéré֣d ʻále֔y⁠ká ʻa֖d hişá̇̌mĕdáֽ⁠kĕ׃"],[28,25,"יִתֶּנְ⁠ךָ֨ יְהוָ֥ה ׀ נִגָּף֮ לִ⁠פְנֵ֣י אֹיְבֶי⁠ךָ֒ בְּ⁠דֶ֤רֶךְ אֶחָד֙ תֵּצֵ֣א אֵלָ֔י⁠ו וּ⁠בְ⁠שִׁבְעָ֥ה דְרָכִ֖ים תָּנ֣וּס לְ⁠פָנָ֑י⁠ו וְ⁠הָיִ֣יתָ לְ⁠זַעֲוָ֔ה לְ⁠כֹ֖ל מַמְלְכ֥וֹת הָ⁠אָֽרֶץ׃","yiţėnĕ⁠ká֨ yĕhwá֥h ׀ nigá̇p֮ li⁠pĕné֣y ʼòyĕbey⁠ká֒ bĕ̇⁠de֤rekĕ ʼeẖád֙ ţé̇ẕé֣ʼ ʼélá֔y⁠w ẇ⁠bĕ⁠şǐbĕʻá֥h dĕráki֖ym ţá̇n֣ẇs lĕ⁠páná֑y⁠w wĕ⁠háyi֣yţá lĕ⁠zaʻàwá֔h lĕ⁠kò֖l mamĕlĕk֥wòţ há⁠ʼáֽreẕ׃"],[28,26,"וְ⁠הָיְתָ֤ה נִבְלָֽתְ⁠ךָ֙ לְ⁠מַאֲכָ֔ל לְ⁠כָל־ע֥וֹף הַ⁠שָּׁמַ֖יִם וּ⁠לְ⁠בֶהֱמַ֣ת הָ⁠אָ֑רֶץ וְ⁠אֵ֖ין מַחֲרִֽיד׃","wĕ⁠háyĕţá֤h nibĕláֽţĕ⁠ká֙ lĕ⁠maʼàká֔l lĕ⁠kál-ʻ֥wòp ha⁠şá̇̌ma֖yim ẇ⁠lĕ⁠behèma֣ţ há⁠ʼá֑reẕ wĕ⁠ʼé֖yn maẖàriֽyd׃"],[28,27,"יַכְּ⁠כָ֨ה יְהוָ֜ה בִּ⁠שְׁחִ֤ין מִצְרַ֨יִם֙ ו⁠ב⁠עפלים וּ⁠בַ⁠גָּרָ֖ב וּ⁠בֶ⁠חָ֑רֶס אֲשֶׁ֥ר לֹא־תוּכַ֖ל לְ⁠הֵרָפֵֽא׃","yakĕ̇⁠ká֨h yĕhwá֜h bi̇⁠şĕ̌ẖi֤yn miẕĕra֨yim֙ w⁠b⁠ʻplym ẇ⁠ba⁠gá̇rá֖b ẇ⁠be⁠ẖá֑res ʼàşě֥r lòʼ-ţẇka֖l lĕ⁠hérápéֽʼ׃"],[28,28,"יַכְּ⁠כָ֣ה יְהוָ֔ה בְּ⁠שִׁגָּע֖וֹן וּ⁠בְ⁠עִוָּר֑וֹן וּ⁠בְ⁠תִמְה֖וֹן לֵבָֽב׃","yakĕ̇⁠ká֣h yĕhwá֔h bĕ̇⁠şǐgá̇ʻ֖wòn ẇ⁠bĕ⁠ʻiwá̇r֑wòn ẇ⁠bĕ⁠ţimĕh֖wòn lébáֽb׃"],[28,29,"וְ⁠הָיִ֜יתָ מְמַשֵּׁ֣שׁ בַּֽ⁠צָּהֳרַ֗יִם כַּ⁠אֲשֶׁ֨ר יְמַשֵּׁ֤שׁ הָ⁠עִוֵּר֙ בָּ⁠אֲפֵלָ֔ה וְ⁠לֹ֥א תַצְלִ֖יחַ אֶת־דְּרָכֶ֑י⁠ךָ וְ⁠הָיִ֜יתָ אַ֣ךְ עָשׁ֧וּק וְ⁠גָז֛וּל כָּל־הַ⁠יָּמִ֖ים וְ⁠אֵ֥ין מוֹשִֽׁיעַ׃","wĕ⁠háyi֜yţá mĕmaşé֣̇̌ş̌ bȧֽ⁠ẕá̇hora֗yim kȧ⁠ʼàşě֨r yĕmaşé֤̇̌ş̌ há⁠ʻiwé̇r֙ bá̇⁠ʼàpélá֔h wĕ⁠lò֥ʼ ţaẕĕli֖yẖa ʼeţ-dĕ̇ráke֑y⁠ká wĕ⁠háyi֜yţá ʼa֣kĕ ʻáş֧̌ẇq wĕ⁠gáz֛ẇl ká̇l-ha⁠yá̇mi֖ym wĕ⁠ʼé֥yn mwòşǐֽyʻa׃"],[28,30,"אִשָּׁ֣ה תְאָרֵ֗שׂ וְ⁠אִ֤ישׁ אַחֵר֙ ישגל⁠נה בַּ֥יִת תִּבְנֶ֖ה וְ⁠לֹא־תֵשֵׁ֣ב בּ֑⁠וֹ כֶּ֥רֶם תִּטַּ֖ע וְ⁠לֹ֥א תְחַלְּלֶּֽ⁠נּוּ׃","ʼişá֣̇̌h ţĕʼáré֗ş̂ wĕ⁠ʼi֤yş̌ ʼaẖér֙ yşgl⁠nh bȧ֥yiţ ţi̇bĕne֖h wĕ⁠lòʼ-ţéşé֣̌b ḃ֑⁠wò kė֥rem ţi̇tȧ֖ʻ wĕ⁠lò֥ʼ ţĕẖalĕ̇lėֽ⁠ṅẇ׃"],[28,31,"שׁוֹרְ⁠ךָ֞ טָב֣וּחַ לְ⁠עֵינֶ֗י⁠ךָ וְ⁠לֹ֣א תֹאכַל֮ מִמֶּ⁠נּוּ֒ חֲמֹֽרְ⁠ךָ֙ גָּז֣וּל מִ⁠לְּ⁠פָנֶ֔י⁠ךָ וְ⁠לֹ֥א יָשׁ֖וּב לָ֑⁠ךְ צֹֽאנְ⁠ךָ֙ נְתֻנ֣וֹת לְ⁠אֹיְבֶ֔י⁠ךָ וְ⁠אֵ֥ין לְ⁠ךָ֖ מוֹשִֽׁיעַ׃","ş̌wòrĕ⁠ká֞ táb֣ẇẖa lĕ⁠ʻéyne֗y⁠ká wĕ⁠lò֣ʼ ţòʼkal֮ mimė⁠ṅẇ֒ ẖàmòֽrĕ⁠ká֙ gá̇z֣ẇl mi⁠lĕ̇⁠páne֔y⁠ká wĕ⁠lò֥ʼ yáş֖̌ẇb lá֑⁠kĕ ẕòֽʼnĕ⁠ká֙ nĕţun֣wòţ lĕ⁠ʼòyĕbe֔y⁠ká wĕ⁠ʼé֥yn lĕ⁠ká֖ mwòşǐֽyʻa׃"],[28,32,"בָּנֶ֨י⁠ךָ וּ⁠בְנֹתֶ֜י⁠ךָ נְתֻנִ֨ים לְ⁠עַ֤ם אַחֵר֙ וְ⁠עֵינֶ֣י⁠ךָ רֹא֔וֹת וְ⁠כָל֥וֹת אֲלֵי⁠הֶ֖ם כָּל־הַ⁠יּ֑וֹם וְ⁠אֵ֥ין לְ⁠אֵ֖ל יָדֶֽ⁠ךָ׃","bá̇ne֨y⁠ká ẇ⁠bĕnòţe֜y⁠ká nĕţuni֨ym lĕ⁠ʻa֤m ʼaẖér֙ wĕ⁠ʻéyne֣y⁠ká ròʼ֔wòţ wĕ⁠kál֥wòţ ʼàléy⁠he֖m ká̇l-ha⁠ẏ֑wòm wĕ⁠ʼé֥yn lĕ⁠ʼé֖l yádeֽ⁠ká׃"],[28,33,"פְּרִ֤י אַדְמָֽתְ⁠ךָ֙ וְ⁠כָל־יְגִ֣יעֲ⁠ךָ֔ יֹאכַ֥ל עַ֖ם אֲשֶׁ֣ר לֹא־יָדָ֑עְתָּ וְ⁠הָיִ֗יתָ רַ֛ק עָשׁ֥וּק וְ⁠רָצ֖וּץ כָּל־הַ⁠יָּמִֽים׃","pĕ̇ri֤y ʼadĕmáֽţĕ⁠ká֙ wĕ⁠kál-yĕgi֣yʻà⁠ká֔ yòʼka֥l ʻa֖m ʼàşě֣r lòʼ-yádá֑ʻĕţá̇ wĕ⁠háyi֗yţá ra֛q ʻáş֥̌ẇq wĕ⁠ráẕ֖ẇẕ ká̇l-ha⁠yá̇miֽym׃"],[28,34,"וְ⁠הָיִ֖יתָ מְשֻׁגָּ֑ע מִ⁠מַּרְאֵ֥ה עֵינֶ֖י⁠ךָ אֲשֶׁ֥ר תִּרְאֶֽה׃","wĕ⁠háyi֖yţá mĕşǔgá֑̇ʻ mi⁠mȧrĕʼé֥h ʻéyne֖y⁠ká ʼàşě֥r ţi̇rĕʼeֽh׃"],[28,35,"יַכְּ⁠כָ֨ה יְהוָ֜ה בִּ⁠שְׁחִ֣ין רָ֗ע עַל־הַ⁠בִּרְכַּ֨יִם֙ וְ⁠עַל־הַ⁠שֹּׁקַ֔יִם אֲשֶׁ֥ר לֹא־תוּכַ֖ל לְ⁠הֵרָפֵ֑א מִ⁠כַּ֥ף רַגְלְ⁠ךָ֖ וְ⁠עַ֥ד קָדְקֳדֶֽ⁠ךָ׃","yakĕ̇⁠ká֨h yĕhwá֜h bi̇⁠şĕ̌ẖi֣yn rá֗ʻ ʻal-ha⁠bi̇rĕkȧ֨yim֙ wĕ⁠ʻal-ha⁠şò̇̌qa֔yim ʼàşě֥r lòʼ-ţẇka֖l lĕ⁠hérápé֑ʼ mi⁠kȧ֥p ragĕlĕ⁠ká֖ wĕ⁠ʻa֥d qádĕqodeֽ⁠ká׃"],[28,36,"יוֹלֵ֨ךְ יְהוָ֜ה אֹֽתְ⁠ךָ֗ וְ⁠אֶֽת־מַלְכְּ⁠ךָ֙ אֲשֶׁ֣ר תָּקִ֣ים עָלֶ֔י⁠ךָ אֶל־גּ֕וֹי אֲשֶׁ֥ר לֹא־יָדַ֖עְתָּ אַתָּ֣ה וַ⁠אֲבֹתֶ֑י⁠ךָ וְ⁠עָבַ֥דְתָּ שָּׁ֛ם אֱלֹהִ֥ים אֲחֵרִ֖ים עֵ֥ץ וָ⁠אָֽבֶן׃","ywòlé֨kĕ yĕhwá֜h ʼòֽţĕ⁠ká֗ wĕ⁠ʼeֽţ-malĕkĕ̇⁠ká֙ ʼàşě֣r ţá̇qi֣ym ʻále֔y⁠ká ʼel-ġ֕wòy ʼàşě֥r lòʼ-yáda֖ʻĕţá̇ ʼaţá֣̇h wa⁠ʼàbòţe֑y⁠ká wĕ⁠ʻába֥dĕţá̇ şá֛̇̌m ʼèlòhi֥ym ʼàẖéri֖ym ʻé֥ẕ wá⁠ʼáֽben׃"],[28,37,"וְ⁠הָיִ֣יתָ לְ⁠שַׁמָּ֔ה לְ⁠מָשָׁ֖ל וְ⁠לִ⁠שְׁנִינָ֑ה בְּ⁠כֹל֙ הָֽ⁠עַמִּ֔ים אֲשֶׁר־יְנַהֶגְ⁠ךָ֥ יְהוָ֖ה שָֽׁמָּ⁠ה׃","wĕ⁠háyi֣yţá lĕ⁠şǎmá̇֔h lĕ⁠máşá֖̌l wĕ⁠li⁠şĕ̌niyná֑h bĕ̇⁠kòl֙ háֽ⁠ʻami̇֔ym ʼàşěr-yĕnahegĕ⁠ká֥ yĕhwá֖h şáֽ̌má̇⁠h׃"],[28,38,"זֶ֥רַע רַ֖ב תּוֹצִ֣יא הַ⁠שָּׂדֶ֑ה וּ⁠מְעַ֣ט תֶּאֱסֹ֔ף כִּ֥י יַחְסְלֶ֖⁠נּוּ הָ⁠אַרְבֶּֽה׃","ze֥raʻ ra֖b ţ̇wòẕi֣yʼ ha⁠şá̇̂de֑h ẇ⁠mĕʻa֣t ţėʼèsò֔p ki֥̇y yaẖĕsĕle֖⁠ṅẇ há⁠ʼarĕbėֽh׃"],[28,39,"כְּרָמִ֥ים תִּטַּ֖ע וְ⁠עָבָ֑דְתָּ וְ⁠יַ֤יִן לֹֽא־תִשְׁתֶּה֙ וְ⁠לֹ֣א תֶאֱגֹ֔ר כִּ֥י תֹאכְלֶ֖⁠נּוּ הַ⁠תֹּלָֽעַת׃","kĕ̇rámi֥ym ţi̇tȧ֖ʻ wĕ⁠ʻábá֑dĕţá̇ wĕ⁠ya֤yin lòֽʼ-ţişĕ̌ţėh֙ wĕ⁠lò֣ʼ ţeʼègò֔r ki֥̇y ţòʼkĕle֖⁠ṅẇ ha⁠ţò̇láֽʻaţ׃"],[28,40,"זֵיתִ֛ים יִהְי֥וּ לְ⁠ךָ֖ בְּ⁠כָל־גְּבוּלֶ֑⁠ךָ וְ⁠שֶׁ֨מֶן֙ לֹ֣א תָס֔וּךְ כִּ֥י יִשַּׁ֖ל זֵיתֶֽ⁠ךָ׃","zéyţi֛ym yihĕy֥ẇ lĕ⁠ká֖ bĕ̇⁠kál-gĕ̇bẇle֑⁠ká wĕ⁠şě֨men֙ lò֣ʼ ţás֔ẇkĕ ki֥̇y yişȧ֖̌l zéyţeֽ⁠ká׃"],[28,41,"בָּנִ֥ים וּ⁠בָנ֖וֹת תּוֹלִ֑יד וְ⁠לֹא־יִהְי֣וּ לָ֔⁠ךְ כִּ֥י יֵלְכ֖וּ בַּ⁠שֶּֽׁבִי׃","bá̇ni֥ym ẇ⁠bán֖wòţ ţ̇wòli֑yd wĕ⁠lòʼ-yihĕy֣ẇ lá֔⁠kĕ ki֥̇y yélĕk֖ẇ bȧ⁠şėֽ̌biy׃"],[28,42,"כָּל־עֵצְ⁠ךָ֖ וּ⁠פְרִ֣י אַדְמָתֶ֑⁠ךָ יְיָרֵ֖שׁ הַ⁠צְּלָצַֽל׃","ká̇l-ʻéẕĕ⁠ká֖ ẇ⁠pĕri֣y ʼadĕmáţe֑⁠ká yĕyáré֖ş̌ ha⁠ẕĕ̇láẕaֽl׃"],[28,43,"הַ⁠גֵּר֙ אֲשֶׁ֣ר בְּ⁠קִרְבְּ⁠ךָ֔ יַעֲלֶ֥ה עָלֶ֖י⁠ךָ מַ֣עְלָ⁠ה מָּ֑עְלָ⁠ה וְ⁠אַתָּ֥ה תֵרֵ֖ד מַ֥טָּה מָּֽטָּה׃","ha⁠gé̇r֙ ʼàşě֣r bĕ̇⁠qirĕbĕ̇⁠ká֔ yaʻàle֥h ʻále֖y⁠ká ma֣ʻĕlá⁠h má֑̇ʻĕlá⁠h wĕ⁠ʼaţá֥̇h ţéré֖d ma֥tá̇h máֽ̇tá̇h׃"],[28,44,"ה֣וּא יַלְוְ⁠ךָ֔ וְ⁠אַתָּ֖ה לֹ֣א תַלְוֶ֑⁠נּוּ ה֚וּא יִהְיֶ֣ה לְ⁠רֹ֔אשׁ וְ⁠אַתָּ֖ה תִּֽהְיֶ֥ה לְ⁠זָנָֽב׃","h֣ẇʼ yalĕwĕ⁠ká֔ wĕ⁠ʼaţá֖̇h lò֣ʼ ţalĕwe֑⁠ṅẇ h֚ẇʼ yihĕye֣h lĕ⁠rò֔ʼş̌ wĕ⁠ʼaţá֖̇h ţiֽ̇hĕye֥h lĕ⁠zánáֽb׃"],[28,45,"וּ⁠בָ֨אוּ עָלֶ֜י⁠ךָ כָּל־הַ⁠קְּלָל֣וֹת הָ⁠אֵ֗לֶּה וּ⁠רְדָפ֨וּ⁠ךָ֙ וְ⁠הִשִּׂיג֔וּ⁠ךָ עַ֖ד הִשָּֽׁמְדָ֑⁠ךְ כִּי־לֹ֣א שָׁמַ֗עְתָּ בְּ⁠קוֹל֙ יְהוָ֣ה אֱלֹהֶ֔י⁠ךָ לִ⁠שְׁמֹ֛ר מִצְוֺתָ֥י⁠ו וְ⁠חֻקֹּתָ֖י⁠ו אֲשֶׁ֥ר צִוָּֽ⁠ךְ׃","ẇ⁠bá֨ʼẇ ʻále֜y⁠ká ká̇l-ha⁠qĕ̇lál֣wòţ há⁠ʼé֗lėh ẇ⁠rĕdáp֨ẇ⁠ká֙ wĕ⁠hişi̇̂yg֔ẇ⁠ká ʻa֖d hişáֽ̇̌mĕdá֑⁠kĕ ki̇y-lò֣ʼ şá̌ma֗ʻĕţá̇ bĕ̇⁠qwòl֙ yĕhwá֣h ʼèlòhe֔y⁠ká li⁠şĕ̌mò֛r miẕĕwֺţá֥y⁠w wĕ⁠ẖuqò̇ţá֖y⁠w ʼàşě֥r ẕiwáֽ̇⁠kĕ׃"],[28,46,"וְ⁠הָי֣וּ בְ⁠ךָ֔ לְ⁠א֖וֹת וּ⁠לְ⁠מוֹפֵ֑ת וּֽ⁠בְ⁠זַרְעֲ⁠ךָ֖ עַד־עוֹלָֽם׃","wĕ⁠háy֣ẇ bĕ⁠ká֔ lĕ⁠ʼ֖wòţ ẇ⁠lĕ⁠mwòpé֑ţ ẇֽ⁠bĕ⁠zarĕʻà⁠ká֖ ʻad-ʻwòláֽm׃"],[28,47,"תַּ֗חַת אֲשֶׁ֤ר לֹא־עָבַ֨דְתָּ֙ אֶת־יְהוָ֣ה אֱלֹהֶ֔י⁠ךָ בְּ⁠שִׂמְחָ֖ה וּ⁠בְ⁠ט֣וּב לֵבָ֑ב מֵ⁠רֹ֖ב כֹּֽל׃","ţȧ֗ẖaţ ʼàşě֤r lòʼ-ʻába֨dĕţá̇֙ ʼeţ-yĕhwá֣h ʼèlòhe֔y⁠ká bĕ̇⁠şîmĕẖá֖h ẇ⁠bĕ⁠t֣ẇb lébá֑b mé⁠rò֖b kòֽ̇l׃"],[28,48,"וְ⁠עָבַדְתָּ֣ אֶת־אֹיְבֶ֗י⁠ךָ אֲשֶׁ֨ר יְשַׁלְּחֶ֤⁠נּוּ יְהוָה֙ בָּ֔⁠ךְ בְּ⁠רָעָ֧ב וּ⁠בְ⁠צָמָ֛א וּ⁠בְ⁠עֵירֹ֖ם וּ⁠בְ⁠חֹ֣סֶר כֹּ֑ל וְ⁠נָתַ֞ן עֹ֤ל בַּרְזֶל֙ עַל־צַוָּארֶ֔⁠ךָ עַ֥ד הִשְׁמִיד֖⁠וֹ אֹתָֽ⁠ךְ׃","wĕ⁠ʻábadĕţá֣̇ ʼeţ-ʼòyĕbe֗y⁠ká ʼàşě֨r yĕşǎlĕ̇ẖe֤⁠ṅẇ yĕhwáh֙ bá̇֔⁠kĕ bĕ̇⁠ráʻá֧b ẇ⁠bĕ⁠ẕámá֛ʼ ẇ⁠bĕ⁠ʻéyrò֖m ẇ⁠bĕ⁠ẖò֣ser kò֑̇l wĕ⁠náţa֞n ʻò֤l bȧrĕzel֙ ʻal-ẕawá̇ʼre֔⁠ká ʻa֥d hişĕ̌miyd֖⁠wò ʼòţáֽ⁠kĕ׃"],[28,49,"יִשָּׂ֣א יְהוָה֩ עָלֶ֨י⁠ךָ גּ֤וֹי מֵ⁠רָחוֹק֙ מִ⁠קְצֵ֣ה הָ⁠אָ֔רֶץ כַּ⁠אֲשֶׁ֥ר יִדְאֶ֖ה הַ⁠נָּ֑שֶׁר גּ֕וֹי אֲשֶׁ֥ר לֹא־תִשְׁמַ֖ע לְשֹׁנֽ⁠וֹ׃","yişá֣̇̂ʼ yĕhwáh֩ ʻále֨y⁠ká ġ֤wòy mé⁠ráẖwòq֙ mi⁠qĕẕé֣h há⁠ʼá֔reẕ kȧ⁠ʼàşě֥r yidĕʼe֖h ha⁠ná֑̇şěr ġ֕wòy ʼàşě֥r lòʼ-ţişĕ̌ma֖ʻ lĕşò̌nֽ⁠wò׃"],[28,50,"גּ֖וֹי עַ֣ז פָּנִ֑ים אֲשֶׁ֨ר לֹא־יִשָּׂ֤א פָנִים֙ לְ⁠זָקֵ֔ן וְ⁠נַ֖עַר לֹ֥א יָחֹֽן׃","ġ֖wòy ʻa֣z pá̇ni֑ym ʼàşě֨r lòʼ-yişá֤̇̂ʼ pániym֙ lĕ⁠záqé֔n wĕ⁠na֖ʻar lò֥ʼ yáẖòֽn׃"],[28,51,"וְ֠⁠אָכַל פְּרִ֨י בְהֶמְתְּ⁠ךָ֥ וּ⁠פְרִֽי־אַדְמָתְ⁠ךָ֮ עַ֣ד הִשָּֽׁמְדָ⁠ךְ֒ אֲשֶׁ֨ר לֹֽא־יַשְׁאִ֜יר לְ⁠ךָ֗ דָּגָן֙ תִּיר֣וֹשׁ וְ⁠יִצְהָ֔ר שְׁגַ֥ר אֲלָפֶ֖י⁠ךָ וְ⁠עַשְׁתְּרֹ֣ת צֹאנֶ֑⁠ךָ עַ֥ד הַאֲבִיד֖⁠וֹ אֹתָֽ⁠ךְ׃","wĕ֠⁠ʼákal pĕ̇ri֨y bĕhemĕţĕ̇⁠ká֥ ẇ⁠pĕriֽy-ʼadĕmáţĕ⁠ká֮ ʻa֣d hişáֽ̇̌mĕdá⁠kĕ֒ ʼàşě֨r lòֽʼ-yaşĕ̌ʼi֜yr lĕ⁠ká֗ dá̇gán֙ ţi̇yr֣wòş̌ wĕ⁠yiẕĕhá֔r şĕ̌ga֥r ʼàlápe֖y⁠ká wĕ⁠ʻaşĕ̌ţĕ̇rò֣ţ ẕòʼne֑⁠ká ʻa֥d haʼàbiyd֖⁠wò ʼòţáֽ⁠kĕ׃"],[28,52,"וְ⁠הֵצַ֨ר לְ⁠ךָ֜ בְּ⁠כָל־שְׁעָרֶ֗י⁠ךָ עַ֣ד רֶ֤דֶת חֹמֹתֶ֨י⁠ךָ֙ הַ⁠גְּבֹה֣וֹת וְ⁠הַ⁠בְּצֻר֔וֹת אֲשֶׁ֥ר אַתָּ֛ה בֹּטֵ֥חַ בָּ⁠הֵ֖ן בְּ⁠כָל־אַרְצֶ֑⁠ךָ וְ⁠הֵצַ֤ר לְ⁠ךָ֙ בְּ⁠כָל־שְׁעָרֶ֔י⁠ךָ בְּ⁠כָ֨ל־אַרְצְ⁠ךָ֔ אֲשֶׁ֥ר נָתַ֛ן יְהוָ֥ה אֱלֹהֶ֖י⁠ךָ לָֽ⁠ךְ׃","wĕ⁠héẕa֨r lĕ⁠ká֜ bĕ̇⁠kál-şĕ̌ʻáre֗y⁠ká ʻa֣d re֤deţ ẖòmòţe֨y⁠ká֙ ha⁠gĕ̇bòh֣wòţ wĕ⁠ha⁠bĕ̇ẕur֔wòţ ʼàşě֥r ʼaţá֛̇h bò̇té֥ẖa bá̇⁠hé֖n bĕ̇⁠kál-ʼarĕẕe֑⁠ká wĕ⁠héẕa֤r lĕ⁠ká֙ bĕ̇⁠kál-şĕ̌ʻáre֔y⁠ká bĕ̇⁠ká֨l-ʼarĕẕĕ⁠ká֔ ʼàşě֥r náţa֛n yĕhwá֥h ʼèlòhe֖y⁠ká láֽ⁠kĕ׃"],[28,53,"וְ⁠אָכַלְתָּ֣ פְרִֽי־בִטְנְ⁠ךָ֗ בְּשַׂ֤ר בָּנֶ֨י⁠ךָ֙ וּ⁠בְנֹתֶ֔י⁠ךָ אֲשֶׁ֥ר נָֽתַן־לְ⁠ךָ֖ יְהוָ֣ה אֱלֹהֶ֑י⁠ךָ בְּ⁠מָצוֹר֙ וּ⁠בְ⁠מָצ֔וֹק אֲשֶׁר־יָצִ֥יק לְ⁠ךָ֖ אֹיְבֶֽ⁠ךָ׃","wĕ⁠ʼákalĕţá֣̇ pĕriֽy-bitĕnĕ⁠ká֗ bĕ̇şâ֤r bá̇ne֨y⁠ká֙ ẇ⁠bĕnòţe֔y⁠ká ʼàşě֥r náֽţan-lĕ⁠ká֖ yĕhwá֣h ʼèlòhe֑y⁠ká bĕ̇⁠máẕwòr֙ ẇ⁠bĕ⁠máẕ֔wòq ʼàşěr-yáẕi֥yq lĕ⁠ká֖ ʼòyĕbeֽ⁠ká׃"],[28,54,"הָ⁠אִישׁ֙ הָ⁠רַ֣ךְ בְּ⁠ךָ֔ וְ⁠הֶ⁠עָנֹ֖ג מְאֹ֑ד תֵּרַ֨ע עֵינ֤⁠וֹ בְ⁠אָחִי⁠ו֙ וּ⁠בְ⁠אֵ֣שֶׁת חֵיק֔⁠וֹ וּ⁠בְ⁠יֶ֥תֶר בָּנָ֖י⁠ו אֲשֶׁ֥ר יוֹתִֽיר׃","há⁠ʼiyş̌֙ há⁠ra֣kĕ bĕ̇⁠ká֔ wĕ⁠he⁠ʻánò֖g mĕʼò֑d ţé̇ra֨ʻ ʻéyn֤⁠wò bĕ⁠ʼáẖiy⁠w֙ ẇ⁠bĕ⁠ʼé֣şěţ ẖéyq֔⁠wò ẇ⁠bĕ⁠ye֥ţer bá̇ná֖y⁠w ʼàşě֥r ywòţiֽyr׃"],[28,55,"מִ⁠תֵּ֣ת ׀ לְ⁠אַחַ֣ד מֵ⁠הֶ֗ם מִ⁠בְּשַׂ֤ר בָּנָי⁠ו֙ אֲשֶׁ֣ר יֹאכֵ֔ל מִ⁠בְּלִ֥י הִשְׁאִֽיר־ל֖⁠וֹ כֹּ֑ל בְּ⁠מָצוֹר֙ וּ⁠בְ⁠מָצ֔וֹק אֲשֶׁ֨ר יָצִ֥יק לְ⁠ךָ֛ אֹיִבְ⁠ךָ֖ בְּ⁠כָל־שְׁעָרֶֽי⁠ךָ׃","mi⁠ţé֣̇ţ ׀ lĕ⁠ʼaẖa֣d mé⁠he֗m mi⁠bĕ̇şâ֤r bá̇náy⁠w֙ ʼàşě֣r yòʼké֔l mi⁠bĕ̇li֥y hişĕ̌ʼiֽyr-l֖⁠wò kò֑̇l bĕ̇⁠máẕwòr֙ ẇ⁠bĕ⁠máẕ֔wòq ʼàşě֨r yáẕi֥yq lĕ⁠ká֛ ʼòyibĕ⁠ká֖ bĕ̇⁠kál-şĕ̌ʻáreֽy⁠ká׃"],[28,56,"הָ⁠רַכָּ֨ה בְ⁠ךָ֜ וְ⁠הָ⁠עֲנֻגָּ֗ה אֲשֶׁ֨ר לֹא־נִסְּתָ֤ה כַף־רַגְלָ⁠הּ֙ הַצֵּ֣ג עַל־הָ⁠אָ֔רֶץ מֵ⁠הִתְעַנֵּ֖ג וּ⁠מֵ⁠רֹ֑ךְ תֵּרַ֤ע עֵינָ⁠הּ֙ בְּ⁠אִ֣ישׁ חֵיקָ֔⁠הּ וּ⁠בִ⁠בְנָ֖⁠הּ וּ⁠בְ⁠בִתָּֽ⁠הּ׃","há⁠raká̇֨h bĕ⁠ká֜ wĕ⁠há⁠ʻànugá̇֗h ʼàşě֨r lòʼ-nisĕ̇ţá֤h kap-ragĕlá⁠ḣ֙ haẕé֣̇g ʻal-há⁠ʼá֔reẕ mé⁠hiţĕʻané֖̇g ẇ⁠mé⁠rò֑kĕ ţé̇ra֤ʻ ʻéyná⁠ḣ֙ bĕ̇⁠ʼi֣yş̌ ẖéyqá֔⁠ḣ ẇ⁠bi⁠bĕná֖⁠ḣ ẇ⁠bĕ⁠biţáֽ̇⁠ḣ׃"],[28,57,"וּֽ⁠בְ⁠שִׁלְיָתָ֞⁠הּ הַ⁠יּוֹצֵ֣ת ׀ מִ⁠בֵּ֣ין רַגְלֶ֗י⁠הָ וּ⁠בְ⁠בָנֶ֨י⁠הָ֙ אֲשֶׁ֣ר תֵּלֵ֔ד כִּֽי־תֹאכְלֵ֥⁠ם בְּ⁠חֹֽסֶר־כֹּ֖ל בַּ⁠סָּ֑תֶר בְּ⁠מָצוֹר֙ וּ⁠בְ⁠מָצ֔וֹק אֲשֶׁ֨ר יָצִ֥יק לְ⁠ךָ֛ אֹיִבְ⁠ךָ֖ בִּ⁠שְׁעָרֶֽי⁠ךָ׃","ẇֽ⁠bĕ⁠şǐlĕyáţá֞⁠ḣ ha⁠ẏwòẕé֣ţ ׀ mi⁠bé֣̇yn ragĕle֗y⁠há ẇ⁠bĕ⁠báne֨y⁠há֙ ʼàşě֣r ţé̇lé֔d kiֽ̇y-ţòʼkĕlé֥⁠m bĕ̇⁠ẖòֽser-kò֖̇l bȧ⁠sá֑̇ţer bĕ̇⁠máẕwòr֙ ẇ⁠bĕ⁠máẕ֔wòq ʼàşě֨r yáẕi֥yq lĕ⁠ká֛ ʼòyibĕ⁠ká֖ bi̇⁠şĕ̌ʻáreֽy⁠ká׃"],[28,58,"אִם־לֹ֨א תִשְׁמֹ֜ר לַ⁠עֲשׂ֗וֹת אֶת־כָּל־דִּבְרֵי֙ הַ⁠תּוֹרָ֣ה הַ⁠זֹּ֔את הַ⁠כְּתוּבִ֖ים בַּ⁠סֵּ֣פֶר הַ⁠זֶּ֑ה לְ֠⁠יִרְאָה אֶת־הַ⁠שֵּׁ֞ם הַ⁠נִּכְבָּ֤ד וְ⁠הַ⁠נּוֹרָא֙ הַ⁠זֶּ֔ה אֵ֖ת יְהוָ֥ה אֱלֹהֶֽי⁠ךָ׃","ʼim-lò֨ʼ ţişĕ̌mò֜r la⁠ʻàş̂֗wòţ ʼeţ-ká̇l-di̇bĕréy֙ ha⁠ţ̇wòrá֣h ha⁠zò̇֔ʼţ ha⁠kĕ̇ţẇbi֖ym bȧ⁠sé֣̇per ha⁠zė֑h lĕ֠⁠yirĕʼáh ʼeţ-ha⁠şé̇̌֞m ha⁠ni̇kĕbá֤̇d wĕ⁠ha⁠ṅwòráʼ֙ ha⁠zė֔h ʼé֖ţ yĕhwá֥h ʼèlòheֽy⁠ká׃"],[28,59,"וְ⁠הִפְלָ֤א יְהוָה֙ אֶת־מַכֹּ֣תְ⁠ךָ֔ וְ⁠אֵ֖ת מַכּ֣וֹת זַרְעֶ֑⁠ךָ מַכּ֤וֹת גְּדֹלוֹת֙ וְ⁠נֶ֣אֱמָנ֔וֹת וָ⁠חֳלָיִ֥ם רָעִ֖ים וְ⁠נֶאֱמָנִֽים׃","wĕ⁠hipĕlá֤ʼ yĕhwáh֙ ʼeţ-makò֣̇ţĕ⁠ká֔ wĕ⁠ʼé֖ţ mak֣̇wòţ zarĕʻe֑⁠ká mak֤̇wòţ gĕ̇dòlwòţ֙ wĕ⁠ne֣ʼèmán֔wòţ wá⁠ẖoláyi֥m ráʻi֖ym wĕ⁠neʼèmániֽym׃"],[28,60,"וְ⁠הֵשִׁ֣יב בְּ⁠ךָ֗ אֵ֚ת כָּל־מַדְוֵ֣ה מִצְרַ֔יִם אֲשֶׁ֥ר יָגֹ֖רְתָּ מִ⁠פְּנֵי⁠הֶ֑ם וְ⁠דָבְק֖וּ בָּֽ⁠ךְ׃","wĕ⁠héşǐ֣yb bĕ̇⁠ká֗ ʼé֚ţ ká̇l-madĕwé֣h miẕĕra֔yim ʼàşě֥r yágò֖rĕţá̇ mi⁠pĕ̇néy⁠he֑m wĕ⁠dábĕq֖ẇ báֽ̇⁠kĕ׃"],[28,61,"גַּ֤ם כָּל־חֳלִי֙ וְ⁠כָל־מַכָּ֔ה אֲשֶׁר֙ לֹ֣א כָת֔וּב בְּ⁠סֵ֖פֶר הַ⁠תּוֹרָ֣ה הַ⁠זֹּ֑את יַעְלֵ֤⁠ם יְהוָה֙ עָלֶ֔י⁠ךָ עַ֖ד הִשָּׁמְדָֽ⁠ךְ׃","gȧ֤m ká̇l-ẖoliy֙ wĕ⁠kál-maká̇֔h ʼàşěr֙ lò֣ʼ káţ֔ẇb bĕ̇⁠sé֖per ha⁠ţ̇wòrá֣h ha⁠zò֑̇ʼţ yaʻĕlé֤⁠m yĕhwáh֙ ʻále֔y⁠ká ʻa֖d hişá̇̌mĕdáֽ⁠kĕ׃"],[28,62,"וְ⁠נִשְׁאַרְתֶּם֙ בִּ⁠מְתֵ֣י מְעָ֔ט תַּ֚חַת אֲשֶׁ֣ר הֱיִיתֶ֔ם כְּ⁠כוֹכְבֵ֥י הַ⁠שָּׁמַ֖יִם לָ⁠רֹ֑ב כִּי־לֹ֣א שָׁמַ֔עְתָּ בְּ⁠ק֖וֹל יְהוָ֥ה אֱלֹהֶֽי⁠ךָ׃","wĕ⁠nişĕ̌ʼarĕţėm֙ bi̇⁠mĕţé֣y mĕʻá֔t ţȧ֚ẖaţ ʼàşě֣r hèyiyţe֔m kĕ̇⁠kwòkĕbé֥y ha⁠şá̇̌ma֖yim lá⁠rò֑b ki̇y-lò֣ʼ şá̌ma֔ʻĕţá̇ bĕ̇⁠q֖wòl yĕhwá֥h ʼèlòheֽy⁠ká׃"],[28,63,"וְ֠⁠הָיָה כַּ⁠אֲשֶׁר־שָׂ֨שׂ יְהוָ֜ה עֲלֵי⁠כֶ֗ם לְ⁠הֵיטִ֣יב אֶתְ⁠כֶם֮ וּ⁠לְ⁠הַרְבּ֣וֹת אֶתְ⁠כֶם֒ כֵּ֣ן יָשִׂ֤ישׂ יְהוָה֙ עֲלֵי⁠כֶ֔ם לְ⁠הַאֲבִ֥יד אֶתְ⁠כֶ֖ם וּ⁠לְ⁠הַשְׁמִ֣יד אֶתְ⁠כֶ֑ם וְ⁠נִסַּחְתֶּם֙ מֵ⁠עַ֣ל הָֽ⁠אֲדָמָ֔ה אֲשֶׁר־אַתָּ֥ה בָא־שָׁ֖מָּ⁠ה לְ⁠רִשְׁתָּֽ⁠הּ׃","wĕ֠⁠háyáh kȧ⁠ʼàşěr-şá̂֨ş̂ yĕhwá֜h ʻàléy⁠ke֗m lĕ⁠héyti֣yb ʼeţĕ⁠kem֮ ẇ⁠lĕ⁠harĕḃ֣wòţ ʼeţĕ⁠kem֒ ké֣̇n yáşî֤yş̂ yĕhwáh֙ ʻàléy⁠ke֔m lĕ⁠haʼàbi֥yd ʼeţĕ⁠ke֖m ẇ⁠lĕ⁠haşĕ̌mi֣yd ʼeţĕ⁠ke֑m wĕ⁠nisȧẖĕţėm֙ mé⁠ʻa֣l háֽ⁠ʼàdámá֔h ʼàşěr-ʼaţá֥̇h báʼ-şá֖̌má̇⁠h lĕ⁠rişĕ̌ţáֽ̇⁠ḣ׃"],[28,64,"וֶ⁠הֱפִֽיצְ⁠ךָ֤ יְהוָה֙ בְּ⁠כָל־הָ֣⁠עַמִּ֔ים מִ⁠קְצֵ֥ה הָ⁠אָ֖רֶץ וְ⁠עַד־קְצֵ֣ה הָ⁠אָ֑רֶץ וְ⁠עָבַ֨דְתָּ שָּׁ֜ם אֱלֹהִ֣ים אֲחֵרִ֗ים אֲשֶׁ֧ר לֹא־יָדַ֛עְתָּ אַתָּ֥ה וַ⁠אֲבֹתֶ֖י⁠ךָ עֵ֥ץ וָ⁠אָֽבֶן׃","we⁠hèpiֽyẕĕ⁠ká֤ yĕhwáh֙ bĕ̇⁠kál-há֣⁠ʻami̇֔ym mi⁠qĕẕé֥h há⁠ʼá֖reẕ wĕ⁠ʻad-qĕẕé֣h há⁠ʼá֑reẕ wĕ⁠ʻába֨dĕţá̇ şá̇̌֜m ʼèlòhi֣ym ʼàẖéri֗ym ʼàşě֧r lòʼ-yáda֛ʻĕţá̇ ʼaţá֥̇h wa⁠ʼàbòţe֖y⁠ká ʻé֥ẕ wá⁠ʼáֽben׃"],[28,65,"וּ⁠בַ⁠גּוֹיִ֤ם הָ⁠הֵם֙ לֹ֣א תַרְגִּ֔יעַ וְ⁠לֹא־יִהְיֶ֥ה מָנ֖וֹחַ לְ⁠כַף־רַגְלֶ֑⁠ךָ וְ⁠נָתַן֩ יְהוָ֨ה לְ⁠ךָ֥ שָׁם֙ לֵ֣ב רַגָּ֔ז וְ⁠כִלְי֥וֹן עֵינַ֖יִם וְ⁠דַֽאֲב֥וֹן נָֽפֶשׁ׃","ẇ⁠ba⁠ġwòyi֤m há⁠hém֙ lò֣ʼ ţarĕgi̇֔yʻa wĕ⁠lòʼ-yihĕye֥h mán֖wòẖa lĕ⁠kap-ragĕle֑⁠ká wĕ⁠náţan֩ yĕhwá֨h lĕ⁠ká֥ şá̌m֙ lé֣b ragá̇֔z wĕ⁠kilĕy֥wòn ʻéyna֖yim wĕ⁠daֽʼàb֥wòn náֽpeş̌׃"],[28,66,"וְ⁠הָי֣וּ חַיֶּ֔י⁠ךָ תְּלֻאִ֥ים לְ⁠ךָ֖ מִ⁠נֶּ֑גֶד וּ⁠פָֽחַדְתָּ֙ לַ֣יְלָה וְ⁠יוֹמָ֔ם וְ⁠לֹ֥א תַאֲמִ֖ין בְּ⁠חַיֶּֽי⁠ךָ׃","wĕ⁠háy֣ẇ ẖayė֔y⁠ká ţĕ̇luʼi֥ym lĕ⁠ká֖ mi⁠nė֑ged ẇ⁠páֽẖadĕţá̇֙ la֣yĕláh wĕ⁠ywòmá֔m wĕ⁠lò֥ʼ ţaʼàmi֖yn bĕ̇⁠ẖayėֽy⁠ká׃"],[28,67,"בַּ⁠בֹּ֤קֶר תֹּאמַר֙ מִֽי־יִתֵּ֣ן עֶ֔רֶב וּ⁠בָ⁠עֶ֥רֶב תֹּאמַ֖ר מִֽי־יִתֵּ֣ן בֹּ֑קֶר מִ⁠פַּ֤חַד לְבָֽבְ⁠ךָ֙ אֲשֶׁ֣ר תִּפְחָ֔ד וּ⁠מִ⁠מַּרְאֵ֥ה עֵינֶ֖י⁠ךָ אֲשֶׁ֥ר תִּרְאֶֽה׃","bȧ⁠bò֤̇qer ţò̇ʼmar֙ miֽy-yiţé֣̇n ʻe֔reb ẇ⁠bá⁠ʻe֥reb ţò̇ʼma֖r miֽy-yiţé֣̇n bò֑̇qer mi⁠pȧ֤ẖad lĕbáֽbĕ⁠ká֙ ʼàşě֣r ţi̇pĕẖá֔d ẇ⁠mi⁠mȧrĕʼé֥h ʻéyne֖y⁠ká ʼàşě֥r ţi̇rĕʼeֽh׃"],[28,68,"וֶֽ⁠הֱשִֽׁיבְ⁠ךָ֨ יְהוָ֥ה ׀ מִצְרַיִם֮ בָּ⁠אֳנִיּוֹת֒ בַּ⁠דֶּ֨רֶךְ֙ אֲשֶׁ֣ר אָמַ֣רְתִּֽי לְ⁠ךָ֔ לֹא־תֹסִ֥יף ע֖וֹד לִ⁠רְאֹתָ֑⁠הּ וְ⁠הִתְמַכַּרְתֶּ֨ם שָׁ֧ם לְ⁠אֹיְבֶ֛י⁠ךָ לַ⁠עֲבָדִ֥ים וְ⁠לִ⁠שְׁפָח֖וֹת וְ⁠אֵ֥ין קֹנֶֽה׃ס","weֽ⁠hèşǐֽybĕ⁠ká֨ yĕhwá֥h ׀ miẕĕrayim֮ bá̇⁠ʼoniẏwòţ֒ bȧ⁠dė֨rekĕ֙ ʼàşě֣r ʼáma֣rĕţiֽ̇y lĕ⁠ká֔ lòʼ-ţòsi֥yp ʻ֖wòd li⁠rĕʼòţá֑⁠ḣ wĕ⁠hiţĕmakȧrĕţė֨m şá֧̌m lĕ⁠ʼòyĕbe֛y⁠ká la⁠ʻàbádi֥ym wĕ⁠li⁠şĕ̌páẖ֖wòţ wĕ⁠ʼé֥yn qòneֽh׃s"],[29,1,"אֵלֶּה֩ דִבְרֵ֨י הַ⁠בְּרִ֜ית אֲֽשֶׁר־צִוָּ֧ה יְהוָ֣ה אֶת־מֹשֶׁ֗ה לִ⁠כְרֹ֛ת אֶת־בְּנֵ֥י יִשְׂרָאֵ֖ל בְּ⁠אֶ֣רֶץ מוֹאָ֑ב מִ⁠לְּ⁠בַ֣ד הַ⁠בְּרִ֔ית אֲשֶׁר־כָּרַ֥ת אִתָּ֖⁠ם בְּ⁠חֹרֵֽב׃פ","ʼélėh֩ dibĕré֨y ha⁠bĕ̇ri֜yţ ʼàֽşěr-ẕiwá֧̇h yĕhwá֣h ʼeţ-mòşě֗h li⁠kĕrò֛ţ ʼeţ-bĕ̇né֥y yişĕ̂ráʼé֖l bĕ̇⁠ʼe֣reẕ mwòʼá֑b mi⁠lĕ̇⁠ba֣d ha⁠bĕ̇ri֔yţ ʼàşěr-ká̇ra֥ţ ʼiţá֖̇⁠m bĕ̇⁠ẖòréֽb׃p"],[29,2,"וַ⁠יִּקְרָ֥א מֹשֶׁ֛ה אֶל־כָּל־יִשְׂרָאֵ֖ל וַ⁠יֹּ֣אמֶר אֲלֵ⁠הֶ֑ם אַתֶּ֣ם רְאִיתֶ֗ם אֵ֣ת כָּל־אֲשֶׁר֩ עָשָׂ֨ה יְהוָ֤ה לְ⁠עֵֽינֵי⁠כֶם֙ בְּ⁠אֶ֣רֶץ מִצְרַ֔יִם לְ⁠פַרְעֹ֥ה וּ⁠לְ⁠כָל־עֲבָדָ֖י⁠ו וּ⁠לְ⁠כָל־אַרְצֽ⁠וֹ׃","wa⁠yi̇qĕrá֥ʼ mòşě֛h ʼel-ká̇l-yişĕ̂ráʼé֖l wa⁠yò֣̇ʼmer ʼàlé⁠he֑m ʼaţė֣m rĕʼiyţe֗m ʼé֣ţ ká̇l-ʼàşěr֩ ʻáşá̂֨h yĕhwá֤h lĕ⁠ʻéֽynéy⁠kem֙ bĕ̇⁠ʼe֣reẕ miẕĕra֔yim lĕ⁠parĕʻò֥h ẇ⁠lĕ⁠kál-ʻàbádá֖y⁠w ẇ⁠lĕ⁠kál-ʼarĕẕֽ⁠wò׃"],[29,3,"הַ⁠מַּסּוֹת֙ הַ⁠גְּדֹלֹ֔ת אֲשֶׁ֥ר רָא֖וּ עֵינֶ֑י⁠ךָ הָ⁠אֹתֹ֧ת וְ⁠הַ⁠מֹּפְתִ֛ים הַ⁠גְּדֹלִ֖ים הָ⁠הֵֽם׃","ha⁠mȧṡwòţ֙ ha⁠gĕ̇dòlò֔ţ ʼàşě֥r ráʼ֖ẇ ʻéyne֑y⁠ká há⁠ʼòţò֧ţ wĕ⁠ha⁠mò̇pĕţi֛ym ha⁠gĕ̇dòli֖ym há⁠héֽm׃"],[29,4,"וְ⁠לֹֽא־נָתַן֩ יְהוָ֨ה לָ⁠כֶ֥ם לֵב֙ לָ⁠דַ֔עַת וְ⁠עֵינַ֥יִם לִ⁠רְא֖וֹת וְ⁠אָזְנַ֣יִם לִ⁠שְׁמֹ֑עַ עַ֖ד הַ⁠יּ֥וֹם הַ⁠זֶּֽה׃","wĕ⁠lòֽʼ-náţan֩ yĕhwá֨h lá⁠ke֥m léb֙ lá⁠da֔ʻaţ wĕ⁠ʻéyna֥yim li⁠rĕʼ֖wòţ wĕ⁠ʼázĕna֣yim li⁠şĕ̌mò֑ʻa ʻa֖d ha⁠ẏ֥wòm ha⁠zėֽh׃"],[29,5,"וָ⁠אוֹלֵ֥ךְ אֶתְ⁠כֶ֛ם אַרְבָּעִ֥ים שָׁנָ֖ה בַּ⁠מִּדְבָּ֑ר לֹֽא־בָל֤וּ שַׂלְמֹֽתֵי⁠כֶם֙ מֵ⁠עֲלֵי⁠כֶ֔ם וְ⁠נַֽעַלְ⁠ךָ֥ לֹֽא־בָלְתָ֖ה מֵ⁠עַ֥ל רַגְלֶֽ⁠ךָ׃","wá⁠ʼwòlé֥kĕ ʼeţĕ⁠ke֛m ʼarĕbá̇ʻi֥ym şá̌ná֖h bȧ⁠mi̇dĕbá֑̇r lòֽʼ-bál֤ẇ şâlĕmòֽţéy⁠kem֙ mé⁠ʻàléy⁠ke֔m wĕ⁠naֽʻalĕ⁠ká֥ lòֽʼ-bálĕţá֖h mé⁠ʻa֥l ragĕleֽ⁠ká׃"],[29,6,"לֶ֚חֶם לֹ֣א אֲכַלְתֶּ֔ם וְ⁠יַ֥יִן וְ⁠שֵׁכָ֖ר לֹ֣א שְׁתִיתֶ֑ם לְמַ֨עַן֙ תֵּֽדְע֔וּ כִּ֛י אֲנִ֥י יְהוָ֖ה אֱלֹהֵי⁠כֶֽם׃","le֚ẖem lò֣ʼ ʼàkalĕţė֔m wĕ⁠ya֥yin wĕ⁠şé̌ká֖r lò֣ʼ şĕ̌ţiyţe֑m lĕma֨ʻan֙ ţéֽ̇dĕʻ֔ẇ ki֛̇y ʼàni֥y yĕhwá֖h ʼèlòhéy⁠keֽm׃"],[29,7,"וַ⁠תָּבֹ֖אוּ אֶל־הַ⁠מָּק֣וֹם הַ⁠זֶּ֑ה וַ⁠יֵּצֵ֣א סִיחֹ֣ן מֶֽלֶךְ־חֶ֠שְׁבּוֹן וְ⁠ע֨וֹג מֶֽלֶךְ־הַ⁠בָּשָׁ֧ן לִ⁠קְרָאתֵ֛⁠נוּ לַ⁠מִּלְחָמָ֖ה וַ⁠נַּכֵּֽ⁠ם׃","wa⁠ţá̇bò֖ʼẇ ʼel-ha⁠má̇q֣wòm ha⁠zė֑h wa⁠yé̇ẕé֣ʼ siyẖò֣n meֽlekĕ-ẖe֠şĕ̌ḃwòn wĕ⁠ʻ֨wòg meֽlekĕ-ha⁠bá̇şá֧̌n li⁠qĕráʼţé֛⁠nẇ la⁠mi̇lĕẖámá֖h wa⁠nȧkéֽ̇⁠m׃"],[29,8,"וַ⁠נִּקַּח֙ אֶת־אַרְצָ֔⁠ם וַ⁠נִּתְּנָ֣⁠הּ לְ⁠נַחֲלָ֔ה לָ⁠רֽאוּבֵנִ֖י וְ⁠לַ⁠גָּדִ֑י וְ⁠לַ⁠חֲצִ֖י שֵׁ֥בֶט הַֽ⁠מְנַשִּֽׁי׃","wa⁠ni̇qȧẖ֙ ʼeţ-ʼarĕẕá֔⁠m wa⁠ni̇ţĕ̇ná֣⁠ḣ lĕ⁠naẖàlá֔h lá⁠rֽʼẇbéni֖y wĕ⁠la⁠gá̇di֑y wĕ⁠la⁠ẖàẕi֖y şé֥̌bet haֽ⁠mĕnaşiֽ̇̌y׃"],[29,9,"וּ⁠שְׁמַרְתֶּ֗ם אֶת־דִּבְרֵי֙ הַ⁠בְּרִ֣ית הַ⁠זֹּ֔את וַ⁠עֲשִׂיתֶ֖ם אֹתָ֑⁠ם לְמַ֣עַן תַּשְׂכִּ֔ילוּ אֵ֖ת כָּל־אֲשֶׁ֥ר תַּעֲשֽׂוּ⁠ן׃פ","ẇ⁠şĕ̌marĕţė֗m ʼeţ-di̇bĕréy֙ ha⁠bĕ̇ri֣yţ ha⁠zò̇֔ʼţ wa⁠ʻàşîyţe֖m ʼòţá֑⁠m lĕma֣ʻan ţȧşĕ̂ki̇֔ylẇ ʼé֖ţ ká̇l-ʼàşě֥r ţȧʻàşֽ̂ẇ⁠n׃p"],[29,10,"אַתֶּ֨ם נִצָּבִ֤ים הַ⁠יּוֹם֙ כֻּלְּ⁠כֶ֔ם לִ⁠פְנֵ֖י יְהוָ֣ה אֱלֹהֵי⁠כֶ֑ם רָאשֵׁי⁠כֶ֣ם שִׁבְטֵי⁠כֶ֗ם זִקְנֵי⁠כֶם֙ וְ⁠שֹׁ֣טְרֵי⁠כֶ֔ם כֹּ֖ל אִ֥ישׁ יִשְׂרָאֵֽל׃","ʼaţė֨m niẕá̇bi֤ym ha⁠ẏwòm֙ ku̇lĕ̇⁠ke֔m li⁠pĕné֖y yĕhwá֣h ʼèlòhéy⁠ke֑m ráʼşé̌y⁠ke֣m şǐbĕtéy⁠ke֗m ziqĕnéy⁠kem֙ wĕ⁠şò֣̌tĕréy⁠ke֔m kò֖̇l ʼi֥yş̌ yişĕ̂ráʼéֽl׃"],[29,11,"טַפְּ⁠כֶ֣ם נְשֵׁי⁠כֶ֔ם וְ⁠גֵ֣רְ⁠ךָ֔ אֲשֶׁ֖ר בְּ⁠קֶ֣רֶב מַחֲנֶ֑י⁠ךָ מֵ⁠חֹטֵ֣ב עֵצֶ֔י⁠ךָ עַ֖ד שֹׁאֵ֥ב מֵימֶֽי⁠ךָ׃","tapĕ̇⁠ke֣m nĕşé̌y⁠ke֔m wĕ⁠gé֣rĕ⁠ká֔ ʼàşě֖r bĕ̇⁠qe֣reb maẖàne֑y⁠ká mé⁠ẖòté֣b ʻéẕe֔y⁠ká ʻa֖d şò̌ʼé֥b méymeֽy⁠ká׃"],[29,12,"לְ⁠עָבְרְ⁠ךָ֗ בִּ⁠בְרִ֛ית יְהוָ֥ה אֱלֹהֶ֖י⁠ךָ וּ⁠בְ⁠אָלָת֑⁠וֹ אֲשֶׁר֙ יְהוָ֣ה אֱלֹהֶ֔י⁠ךָ כֹּרֵ֥ת עִמְּ⁠ךָ֖ הַ⁠יּֽוֹם׃","lĕ⁠ʻábĕrĕ⁠ká֗ bi̇⁠bĕri֛yţ yĕhwá֥h ʼèlòhe֖y⁠ká ẇ⁠bĕ⁠ʼáláţ֑⁠wò ʼàşěr֙ yĕhwá֣h ʼèlòhe֔y⁠ká kò̇ré֥ţ ʻimĕ̇⁠ká֖ ha⁠ẏֽwòm׃"],[29,13,"לְמַ֣עַן הָקִֽים־אֹתְ⁠ךָ֩ הַ⁠יּ֨וֹם ׀ ל֜⁠וֹ לְ⁠עָ֗ם וְ⁠ה֤וּא יִֽהְיֶה־לְּ⁠ךָ֙ לֵֽ⁠אלֹהִ֔ים כַּ⁠אֲשֶׁ֖ר דִּבֶּר־לָ֑⁠ךְ וְ⁠כַ⁠אֲשֶׁ֤ר נִשְׁבַּע֙ לַ⁠אֲבֹתֶ֔י⁠ךָ לְ⁠אַבְרָהָ֥ם לְ⁠יִצְחָ֖ק וּֽ⁠לְ⁠יַעֲקֹֽב׃","lĕma֣ʻan háqiֽym-ʼòţĕ⁠ká֩ ha⁠ẏ֨wòm ׀ l֜⁠wò lĕ⁠ʻá֗m wĕ⁠h֤ẇʼ yiֽhĕyeh-lĕ̇⁠ká֙ léֽ⁠ʼlòhi֔ym kȧ⁠ʼàşě֖r di̇bėr-lá֑⁠kĕ wĕ⁠ka⁠ʼàşě֤r nişĕ̌bȧʻ֙ la⁠ʼàbòţe֔y⁠ká lĕ⁠ʼabĕráhá֥m lĕ⁠yiẕĕẖá֖q ẇֽ⁠lĕ⁠yaʻàqòֽb׃"],[29,14,"וְ⁠לֹ֥א אִתְּ⁠כֶ֖ם לְ⁠בַדְּ⁠כֶ֑ם אָנֹכִ֗י כֹּרֵת֙ אֶת־הַ⁠בְּרִ֣ית הַ⁠זֹּ֔את וְ⁠אֶת־הָ⁠אָלָ֖ה הַ⁠זֹּֽאת׃","wĕ⁠lò֥ʼ ʼiţĕ̇⁠ke֖m lĕ⁠badĕ̇⁠ke֑m ʼánòki֗y kò̇réţ֙ ʼeţ-ha⁠bĕ̇ri֣yţ ha⁠zò̇֔ʼţ wĕ⁠ʼeţ-há⁠ʼálá֖h ha⁠zòֽ̇ʼţ׃"],[29,15,"כִּי֩ אֶת־אֲשֶׁ֨ר יֶשְׁנ֜⁠וֹ פֹּ֗ה עִמָּ֨⁠נוּ֙ עֹמֵ֣ד הַ⁠יּ֔וֹם לִ⁠פְנֵ֖י יְהוָ֣ה אֱלֹהֵ֑י⁠נוּ וְ⁠אֵ֨ת אֲשֶׁ֥ר אֵינֶ֛⁠נּוּ פֹּ֖ה עִמָּ֥⁠נוּ הַ⁠יּֽוֹם׃","ki̇y֩ ʼeţ-ʼàşě֨r yeşĕ̌n֜⁠wò pò̇֗h ʻimá̇֨⁠nẇ֙ ʻòmé֣d ha⁠ẏ֔wòm li⁠pĕné֖y yĕhwá֣h ʼèlòhé֑y⁠nẇ wĕ⁠ʼé֨ţ ʼàşě֥r ʼéyne֛⁠ṅẇ pò֖̇h ʻimá֥̇⁠nẇ ha⁠ẏֽwòm׃"],[29,16,"כִּֽי־אַתֶּ֣ם יְדַעְתֶּ֔ם אֵ֥ת אֲשֶׁר־יָשַׁ֖בְנוּ בְּ⁠אֶ֣רֶץ מִצְרָ֑יִם וְ⁠אֵ֧ת אֲשֶׁר־עָבַ֛רְנוּ בְּ⁠קֶ֥רֶב הַ⁠גּוֹיִ֖ם אֲשֶׁ֥ר עֲבַרְתֶּֽם׃","kiֽ̇y-ʼaţė֣m yĕdaʻĕţė֔m ʼé֥ţ ʼàşěr-yáşǎ֖bĕnẇ bĕ̇⁠ʼe֣reẕ miẕĕrá֑yim wĕ⁠ʼé֧ţ ʼàşěr-ʻába֛rĕnẇ bĕ̇⁠qe֥reb ha⁠ġwòyi֖m ʼàşě֥r ʻàbarĕţėֽm׃"],[29,17,"וַ⁠תִּרְאוּ֙ אֶת־שִׁקּ֣וּצֵי⁠הֶ֔ם וְ⁠אֵ֖ת גִּלֻּלֵי⁠הֶ֑ם עֵ֣ץ וָ⁠אֶ֔בֶן כֶּ֥סֶף וְ⁠זָהָ֖ב אֲשֶׁ֥ר עִמָּ⁠הֶֽם׃","wa⁠ţi̇rĕʼẇ֙ ʼeţ-şǐq֣̇ẇẕéy⁠he֔m wĕ⁠ʼé֖ţ gi̇lu̇léy⁠he֑m ʻé֣ẕ wá⁠ʼe֔ben kė֥sep wĕ⁠záhá֖b ʼàşě֥r ʻimá̇⁠heֽm׃"],[29,18,"פֶּן־יֵ֣שׁ בָּ֠⁠כֶם אִ֣ישׁ אוֹ־אִשָּׁ֞ה א֧וֹ מִשְׁפָּחָ֣ה אוֹ־שֵׁ֗בֶט אֲשֶׁר֩ לְבָב֨⁠וֹ פֹנֶ֤ה הַ⁠יּוֹם֙ מֵ⁠עִם֙ יְהוָ֣ה אֱלֹהֵ֔י⁠נוּ לָ⁠לֶ֣כֶת לַ⁠עֲבֹ֔ד אֶת־אֱלֹהֵ֖י הַ⁠גּוֹיִ֣ם הָ⁠הֵ֑ם פֶּן־יֵ֣שׁ בָּ⁠כֶ֗ם שֹׁ֛רֶשׁ פֹּרֶ֥ה רֹ֖אשׁ וְ⁠לַעֲנָֽה׃","pėn-yé֣ş̌ bá̇֠⁠kem ʼi֣yş̌ ʼwò-ʼişá̇̌֞h ʼ֧wò mişĕ̌pá̇ẖá֣h ʼwò-şé̌֗bet ʼàşěr֩ lĕbáb֨⁠wò pòne֤h ha⁠ẏwòm֙ mé⁠ʻim֙ yĕhwá֣h ʼèlòhé֔y⁠nẇ lá⁠le֣keţ la⁠ʻàbò֔d ʼeţ-ʼèlòhé֖y ha⁠ġwòyi֣m há⁠hé֑m pėn-yé֣ş̌ bá̇⁠ke֗m şò֛̌reş̌ pò̇re֥h rò֖ʼş̌ wĕ⁠laʻànáֽh׃"],[29,19,"וְ⁠הָיָ֡ה בְּ⁠שָׁמְע⁠וֹ֩ אֶת־דִּבְרֵ֨י הָֽ⁠אָלָ֜ה הַ⁠זֹּ֗את וְ⁠הִתְבָּרֵ֨ךְ בִּ⁠לְבָב֤⁠וֹ לֵ⁠אמֹר֙ שָׁל֣וֹם יִֽהְיֶה־לִּ֔⁠י כִּ֛י בִּ⁠שְׁרִר֥וּת לִבִּ֖⁠י אֵלֵ֑ךְ לְמַ֛עַן סְפ֥וֹת הָ⁠רָוָ֖ה אֶת־הַ⁠צְּמֵאָֽה׃","wĕ⁠háyá֡h bĕ̇⁠şá̌mĕʻ⁠wò֩ ʼeţ-di̇bĕré֨y háֽ⁠ʼálá֜h ha⁠zò̇֗ʼţ wĕ⁠hiţĕbá̇ré֨kĕ bi̇⁠lĕbáb֤⁠wò lé⁠ʼmòr֙ şá̌l֣wòm yiֽhĕyeh-li̇֔⁠y ki֛̇y bi̇⁠şĕ̌rir֥ẇţ libi֖̇⁠y ʼélé֑kĕ lĕma֛ʻan sĕp֥wòţ há⁠ráwá֖h ʼeţ-ha⁠ẕĕ̇méʼáֽh׃"],[29,20,"לֹא־יֹאבֶ֣ה יְהוָה֮ סְלֹ֣חַֽ ל⁠וֹ֒ כִּ֣י אָ֠ז יֶעְשַׁ֨ן אַף־יְהוָ֤ה וְ⁠קִנְאָת⁠וֹ֙ בָּ⁠אִ֣ישׁ הַ⁠ה֔וּא וְ⁠רָ֤בְצָה בּ⁠וֹ֙ כָּל־הָ֣⁠אָלָ֔ה הַ⁠כְּתוּבָ֖ה בַּ⁠סֵּ֣פֶר הַ⁠זֶּ֑ה וּ⁠מָחָ֤ה יְהוָה֙ אֶת־שְׁמ֔⁠וֹ מִ⁠תַּ֖חַת הַ⁠שָּׁמָֽיִם׃","lòʼ-yòʼbe֣h yĕhwáh֮ sĕlò֣ẖaֽ l⁠wò֒ ki֣̇y ʼá֠z yeʻĕşǎ֨n ʼap-yĕhwá֤h wĕ⁠qinĕʼáţ⁠wò֙ bá̇⁠ʼi֣yş̌ ha⁠h֔ẇʼ wĕ⁠rá֤bĕẕáh ḃ⁠wò֙ ká̇l-há֣⁠ʼálá֔h ha⁠kĕ̇ţẇbá֖h bȧ⁠sé֣̇per ha⁠zė֑h ẇ⁠máẖá֤h yĕhwáh֙ ʼeţ-şĕ̌m֔⁠wò mi⁠ţȧ֖ẖaţ ha⁠şá̇̌máֽyim׃"],[29,21,"וְ⁠הִבְדִּיל֤⁠וֹ יְהוָה֙ לְ⁠רָעָ֔ה מִ⁠כֹּ֖ל שִׁבְטֵ֣י יִשְׂרָאֵ֑ל כְּ⁠כֹל֙ אָל֣וֹת הַ⁠בְּרִ֔ית הַ⁠כְּתוּבָ֕ה בְּ⁠סֵ֥פֶר הַ⁠תּוֹרָ֖ה הַ⁠זֶּֽה׃","wĕ⁠hibĕdi̇yl֤⁠wò yĕhwáh֙ lĕ⁠ráʻá֔h mi⁠kò֖̇l şǐbĕté֣y yişĕ̂ráʼé֑l kĕ̇⁠kòl֙ ʼál֣wòţ ha⁠bĕ̇ri֔yţ ha⁠kĕ̇ţẇbá֕h bĕ̇⁠sé֥per ha⁠ţ̇wòrá֖h ha⁠zėֽh׃"],[29,22,"וְ⁠אָמַ֞ר הַ⁠דּ֣וֹר הָֽ⁠אַחֲר֗וֹן בְּנֵי⁠כֶם֙ אֲשֶׁ֤ר יָק֨וּמוּ֙ מֵ⁠אַ֣חֲרֵי⁠כֶ֔ם וְ⁠הַ֨⁠נָּכְרִ֔י אֲשֶׁ֥ר יָבֹ֖א מֵ⁠אֶ֣רֶץ רְחוֹקָ֑ה וְ֠⁠רָאוּ אֶת־מַכּ֞וֹת הָ⁠אָ֤רֶץ הַ⁠הִוא֙ וְ⁠אֶת־תַּ֣חֲלֻאֶ֔י⁠הָ אֲשֶׁר־חִלָּ֥ה יְהוָ֖ה בָּֽ⁠הּ׃","wĕ⁠ʼáma֞r ha⁠ḋ֣wòr háֽ⁠ʼaẖàr֗wòn bĕ̇néy⁠kem֙ ʼàşě֤r yáq֨ẇmẇ֙ mé⁠ʼa֣ẖàréy⁠ke֔m wĕ⁠ha֨⁠ná̇kĕri֔y ʼàşě֥r yábò֖ʼ mé⁠ʼe֣reẕ rĕẖwòqá֑h wĕ֠⁠ráʼẇ ʼeţ-mak̇֞wòţ há⁠ʼá֤reẕ ha⁠hiwʼ֙ wĕ⁠ʼeţ-ţȧ֣ẖàluʼe֔y⁠há ʼàşěr-ẖilá֥̇h yĕhwá֖h báֽ̇⁠ḣ׃"],[29,23,"גָּפְרִ֣ית וָ⁠מֶלַח֮ שְׂרֵפָ֣ה כָל־אַרְצָ⁠הּ֒ לֹ֤א תִזָּרַע֙ וְ⁠לֹ֣א תַצְמִ֔חַ וְ⁠לֹֽא־יַעֲלֶ֥ה בָ֖⁠הּ כָּל־עֵ֑שֶׂב כְּֽ⁠מַהְפֵּכַ֞ת סְדֹ֤ם וַ⁠עֲמֹרָה֙ אַדְמָ֣ה ו⁠צביים אֲשֶׁר֙ הָפַ֣ךְ יְהוָ֔ה בְּ⁠אַפּ֖⁠וֹ וּ⁠בַ⁠חֲמָתֽ⁠וֹ׃","gá̇pĕri֣yţ wá⁠melaẖ֮ şĕ̂répá֣h kál-ʼarĕẕá⁠ḣ֒ lò֤ʼ ţizá̇raʻ֙ wĕ⁠lò֣ʼ ţaẕĕmi֔ẖa wĕ⁠lòֽʼ-yaʻàle֥h bá֖⁠ḣ ká̇l-ʻé֑şêb kĕֽ̇⁠mahĕpé̇ka֞ţ sĕdò֤m wa⁠ʻàmòráh֙ ʼadĕmá֣h w⁠ẕbyym ʼàşěr֙ hápa֣kĕ yĕhwá֔h bĕ̇⁠ʼaṗ֖⁠wò ẇ⁠ba⁠ẖàmáţֽ⁠wò׃"],[29,24,"וְ⁠אָֽמְרוּ֙ כָּל־הַ⁠גּוֹיִ֔ם עַל־מֶ֨ה עָשָׂ֧ה יְהוָ֛ה כָּ֖כָה לָ⁠אָ֣רֶץ הַ⁠זֹּ֑את מֶ֥ה חֳרִ֛י הָ⁠אַ֥ף הַ⁠גָּד֖וֹל הַ⁠זֶּֽה׃","wĕ⁠ʼáֽmĕrẇ֙ ká̇l-ha⁠ġwòyi֔m ʻal-me֨h ʻáşá֧̂h yĕhwá֛h ká֖̇káh lá⁠ʼá֣reẕ ha⁠zò֑̇ʼţ me֥h ẖori֛y há⁠ʼa֥p ha⁠gá̇d֖wòl ha⁠zėֽh׃"],[29,25,"וְ⁠אָ֣מְר֔וּ עַ֚ל אֲשֶׁ֣ר עָֽזְב֔וּ אֶת־בְּרִ֥ית יְהוָ֖ה אֱלֹהֵ֣י אֲבֹתָ֑⁠ם אֲשֶׁר֙ כָּרַ֣ת עִמָּ֔⁠ם בְּ⁠הוֹצִיא֥⁠וֹ אֹתָ֖⁠ם מֵ⁠אֶ֥רֶץ מִצְרָֽיִם׃","wĕ⁠ʼá֣mĕr֔ẇ ʻa֚l ʼàşě֣r ʻáֽzĕb֔ẇ ʼeţ-bĕ̇ri֥yţ yĕhwá֖h ʼèlòhé֣y ʼàbòţá֑⁠m ʼàşěr֙ ká̇ra֣ţ ʻimá̇֔⁠m bĕ̇⁠hwòẕiyʼ֥⁠wò ʼòţá֖⁠m mé⁠ʼe֥reẕ miẕĕráֽyim׃"],[29,26,"וַ⁠יֵּלְכ֗וּ וַ⁠יַּֽעַבְדוּ֙ אֱלֹהִ֣ים אֲחֵרִ֔ים וַ⁠יִּֽשְׁתַּחֲוּ֖וּ לָ⁠הֶ֑ם אֱלֹהִים֙ אֲשֶׁ֣ר לֹֽא־יְדָע֔וּ⁠ם וְ⁠לֹ֥א חָלַ֖ק לָ⁠הֶֽם׃","wa⁠yé̇lĕk֗ẇ wa⁠yȧֽʻabĕdẇ֙ ʼèlòhi֣ym ʼàẖéri֔ym wa⁠yiֽ̇şĕ̌ţȧẖàẇ֖ẇ lá⁠he֑m ʼèlòhiym֙ ʼàşě֣r lòֽʼ-yĕdáʻ֔ẇ⁠m wĕ⁠lò֥ʼ ẖála֖q lá⁠heֽm׃"],[29,27,"וַ⁠יִּֽחַר־אַ֥ף יְהוָ֖ה בָּ⁠אָ֣רֶץ הַ⁠הִ֑וא לְ⁠הָבִ֤יא עָלֶ֨י⁠הָ֙ אֶת־כָּל־הַ⁠קְּלָלָ֔ה הַ⁠כְּתוּבָ֖ה בַּ⁠סֵּ֥פֶר הַ⁠זֶּֽה׃","wa⁠yiֽ̇ẖar-ʼa֥p yĕhwá֖h bá̇⁠ʼá֣reẕ ha⁠hi֑wʼ lĕ⁠hábi֤yʼ ʻále֨y⁠há֙ ʼeţ-ká̇l-ha⁠qĕ̇lálá֔h ha⁠kĕ̇ţẇbá֖h bȧ⁠sé֥̇per ha⁠zėֽh׃"],[29,28,"וַ⁠יִּתְּשֵׁ֤⁠ם יְהוָה֙ מֵ⁠עַ֣ל אַדְמָתָ֔⁠ם בְּ⁠אַ֥ף וּ⁠בְ⁠חֵמָ֖ה וּ⁠בְ⁠קֶ֣צֶף גָּד֑וֹל וַ⁠יַּשְׁלִכֵ֛⁠ם אֶל־אֶ֥רֶץ אַחֶ֖רֶת כַּ⁠יּ֥וֹם הַ⁠זֶּֽה׃","wa⁠yi̇ţĕ̇şé֤̌⁠m yĕhwáh֙ mé⁠ʻa֣l ʼadĕmáţá֔⁠m bĕ̇⁠ʼa֥p ẇ⁠bĕ⁠ẖémá֖h ẇ⁠bĕ⁠qe֣ẕep gá̇d֑wòl wa⁠yȧşĕ̌liké֛⁠m ʼel-ʼe֥reẕ ʼaẖe֖reţ kȧ⁠ẏ֥wòm ha⁠zėֽh׃"],[29,29,"הַ֨⁠נִּסְתָּרֹ֔ת לַ⁠יהוָ֖ה אֱלֹהֵ֑י⁠נוּ וְ⁠הַ⁠נִּגְלֹ֞ת לָ֤ׄ⁠נׄוּׄ וּׄ⁠לְׄ⁠בָׄנֵׄ֨יׄ⁠נׄוּׄ֙ עַד־עוֹלָ֔ם לַ⁠עֲשׂ֕וֹת אֶת־כָּל־דִּבְרֵ֖י הַ⁠תּוֹרָ֥ה הַ⁠זֹּֽאת׃ס","ha֨⁠ni̇sĕţá̇rò֔ţ la⁠yhwá֖h ʼèlòhé֑y⁠nẇ wĕ⁠ha⁠ni̇gĕlò֞ţ lá֤ׄ⁠nׄẇׄ ẇׄ⁠lĕׄ⁠báׄnéׄ֨yׄ⁠nׄẇׄ֙ ʻad-ʻwòlá֔m la⁠ʻàş̂֕wòţ ʼeţ-ká̇l-di̇bĕré֖y ha⁠ţ̇wòrá֥h ha⁠zòֽ̇ʼţ׃s"],[30,1,"וְ⁠הָיָה֩ כִֽי־יָבֹ֨אוּ עָלֶ֜י⁠ךָ כָּל־הַ⁠דְּבָרִ֣ים הָ⁠אֵ֗לֶּה הַ⁠בְּרָכָה֙ וְ⁠הַ⁠קְּלָלָ֔ה אֲשֶׁ֥ר נָתַ֖תִּי לְ⁠פָנֶ֑י⁠ךָ וַ⁠הֲשֵׁבֹתָ֙ אֶל־לְבָבֶ֔⁠ךָ בְּ⁠כָל־הַ⁠גּוֹיִ֔ם אֲשֶׁ֧ר הִדִּיחֲ⁠ךָ֛ יְהוָ֥ה אֱלֹהֶ֖י⁠ךָ שָֽׁמָּ⁠ה׃","wĕ⁠háyáh֩ kiֽy-yábò֨ʼẇ ʻále֜y⁠ká ká̇l-ha⁠dĕ̇bári֣ym há⁠ʼé֗lėh ha⁠bĕ̇rákáh֙ wĕ⁠ha⁠qĕ̇lálá֔h ʼàşě֥r náţa֖ţi̇y lĕ⁠páne֑y⁠ká wa⁠hàşé̌bòţá֙ ʼel-lĕbábe֔⁠ká bĕ̇⁠kál-ha⁠ġwòyi֔m ʼàşě֧r hidi̇yẖà⁠ká֛ yĕhwá֥h ʼèlòhe֖y⁠ká şáֽ̌má̇⁠h׃"],[30,2,"וְ⁠שַׁבְתָּ֞ עַד־יְהוָ֤ה אֱלֹהֶ֨י⁠ךָ֙ וְ⁠שָׁמַעְתָּ֣ בְ⁠קֹל֔⁠וֹ כְּ⁠כֹ֛ל אֲשֶׁר־אָנֹכִ֥י מְצַוְּ⁠ךָ֖ הַ⁠יּ֑וֹם אַתָּ֣ה וּ⁠בָנֶ֔י⁠ךָ בְּ⁠כָל־לְבָבְ⁠ךָ֖ וּ⁠בְ⁠כָל־נַפְשֶֽׁ⁠ךָ׃","wĕ⁠şǎbĕţá̇֞ ʻad-yĕhwá֤h ʼèlòhe֨y⁠ká֙ wĕ⁠şá̌maʻĕţá֣̇ bĕ⁠qòl֔⁠wò kĕ̇⁠kò֛l ʼàşěr-ʼánòki֥y mĕẕawĕ̇⁠ká֖ ha⁠ẏ֑wòm ʼaţá֣̇h ẇ⁠báne֔y⁠ká bĕ̇⁠kál-lĕbábĕ⁠ká֖ ẇ⁠bĕ⁠kál-napĕşěֽ⁠ká׃"],[30,3,"וְ⁠שָׁ֨ב יְהוָ֧ה אֱלֹהֶ֛י⁠ךָ אֶת־שְׁבוּתְ⁠ךָ֖ וְ⁠רִחֲמֶ֑⁠ךָ וְ⁠שָׁ֗ב וְ⁠קִבֶּצְ⁠ךָ֙ מִ⁠כָּל־הָ֣⁠עַמִּ֔ים אֲשֶׁ֧ר הֱפִֽיצְ⁠ךָ֛ יְהוָ֥ה אֱלֹהֶ֖י⁠ךָ שָֽׁמָּ⁠ה׃","wĕ⁠şá̌֨b yĕhwá֧h ʼèlòhe֛y⁠ká ʼeţ-şĕ̌bẇţĕ⁠ká֖ wĕ⁠riẖàme֑⁠ká wĕ⁠şá̌֗b wĕ⁠qibėẕĕ⁠ká֙ mi⁠ká̇l-há֣⁠ʻami̇֔ym ʼàşě֧r hèpiֽyẕĕ⁠ká֛ yĕhwá֥h ʼèlòhe֖y⁠ká şáֽ̌má̇⁠h׃"],[30,4,"אִם־יִהְיֶ֥ה נִֽדַּחֲ⁠ךָ֖ בִּ⁠קְצֵ֣ה הַ⁠שָּׁמָ֑יִם מִ⁠שָּׁ֗ם יְקַבֶּצְ⁠ךָ֙ יְהוָ֣ה אֱלֹהֶ֔י⁠ךָ וּ⁠מִ⁠שָּׁ֖ם יִקָּחֶֽ⁠ךָ׃","ʼim-yihĕye֥h niֽdȧẖà⁠ká֖ bi̇⁠qĕẕé֣h ha⁠şá̇̌má֑yim mi⁠şá̇̌֗m yĕqabėẕĕ⁠ká֙ yĕhwá֣h ʼèlòhe֔y⁠ká ẇ⁠mi⁠şá֖̇̌m yiqá̇ẖeֽ⁠ká׃"],[30,5,"וֶ⁠הֱבִֽיאֲ⁠ךָ֞ יְהוָ֣ה אֱלֹהֶ֗י⁠ךָ אֶל־הָ⁠אָ֛רֶץ אֲשֶׁר־יָרְשׁ֥וּ אֲבֹתֶ֖י⁠ךָ וִֽ⁠ירִשְׁתָּ֑⁠הּ וְ⁠הֵיטִֽבְ⁠ךָ֥ וְ⁠הִרְבְּ⁠ךָ֖ מֵ⁠אֲבֹתֶֽי⁠ךָ׃","we⁠hèbiֽyʼà⁠ká֞ yĕhwá֣h ʼèlòhe֗y⁠ká ʼel-há⁠ʼá֛reẕ ʼàşěr-yárĕş֥̌ẇ ʼàbòţe֖y⁠ká wiֽ⁠yrişĕ̌ţá֑̇⁠ḣ wĕ⁠héytiֽbĕ⁠ká֥ wĕ⁠hirĕbĕ̇⁠ká֖ mé⁠ʼàbòţeֽy⁠ká׃"],[30,6,"וּ⁠מָ֨ל יְהוָ֧ה אֱלֹהֶ֛י⁠ךָ אֶת־לְבָבְ⁠ךָ֖ וְ⁠אֶת־לְבַ֣ב זַרְעֶ֑⁠ךָ לְ⁠אַהֲבָ֞ה אֶת־יְהוָ֧ה אֱלֹהֶ֛י⁠ךָ בְּ⁠כָל־לְבָבְ⁠ךָ֥ וּ⁠בְ⁠כָל־נַפְשְׁ⁠ךָ֖ לְמַ֥עַן חַיֶּֽי⁠ךָ׃","ẇ⁠má֨l yĕhwá֧h ʼèlòhe֛y⁠ká ʼeţ-lĕbábĕ⁠ká֖ wĕ⁠ʼeţ-lĕba֣b zarĕʻe֑⁠ká lĕ⁠ʼahàbá֞h ʼeţ-yĕhwá֧h ʼèlòhe֛y⁠ká bĕ̇⁠kál-lĕbábĕ⁠ká֥ ẇ⁠bĕ⁠kál-napĕşĕ̌⁠ká֖ lĕma֥ʻan ẖayėֽy⁠ká׃"],[30,7,"וְ⁠נָתַן֙ יְהוָ֣ה אֱלֹהֶ֔י⁠ךָ אֵ֥ת כָּל־הָ⁠אָל֖וֹת הָ⁠אֵ֑לֶּה עַל־אֹיְבֶ֥י⁠ךָ וְ⁠עַל־שֹׂנְאֶ֖י⁠ךָ אֲשֶׁ֥ר רְדָפֽוּ⁠ךָ׃","wĕ⁠náţan֙ yĕhwá֣h ʼèlòhe֔y⁠ká ʼé֥ţ ká̇l-há⁠ʼál֖wòţ há⁠ʼé֑lėh ʻal-ʼòyĕbe֥y⁠ká wĕ⁠ʻal-şò̂nĕʼe֖y⁠ká ʼàşě֥r rĕdápֽẇ⁠ká׃"],[30,8,"וְ⁠אַתָּ֣ה תָשׁ֔וּב וְ⁠שָׁמַעְתָּ֖ בְּ⁠ק֣וֹל יְהוָ֑ה וְ⁠עָשִׂ֨יתָ֙ אֶת־כָּל־מִצְוֺתָ֔י⁠ו אֲשֶׁ֛ר אָנֹכִ֥י מְצַוְּ⁠ךָ֖ הַ⁠יּֽוֹם׃","wĕ⁠ʼaţá֣̇h ţáş̌֔ẇb wĕ⁠şá̌maʻĕţá֖̇ bĕ̇⁠q֣wòl yĕhwá֑h wĕ⁠ʻáşî֨yţá֙ ʼeţ-ká̇l-miẕĕwֺţá֔y⁠w ʼàşě֛r ʼánòki֥y mĕẕawĕ̇⁠ká֖ ha⁠ẏֽwòm׃"],[30,9,"וְ⁠הוֹתִֽירְ⁠ךָ֩ יְהוָ֨ה אֱלֹהֶ֜י⁠ךָ בְּ⁠כֹ֣ל ׀ מַעֲשֵׂ֣ה יָדֶ֗⁠ךָ בִּ⁠פְרִ֨י בִטְנְ⁠ךָ֜ וּ⁠בִ⁠פְרִ֧י בְהֶמְתְּ⁠ךָ֛ וּ⁠בִ⁠פְרִ֥י אַדְמָתְ⁠ךָ֖ לְ⁠טוֹבָ֑ה כִּ֣י ׀ יָשׁ֣וּב יְהוָ֗ה לָ⁠שׂ֤וּשׂ עָלֶ֨י⁠ךָ֙ לְ⁠ט֔וֹב כַּ⁠אֲשֶׁר־שָׂ֖שׂ עַל־אֲבֹתֶֽי⁠ךָ׃","wĕ⁠hwòţiֽyrĕ⁠ká֩ yĕhwá֨h ʼèlòhe֜y⁠ká bĕ̇⁠kò֣l ׀ maʻàşé֣̂h yáde֗⁠ká bi̇⁠pĕri֨y bitĕnĕ⁠ká֜ ẇ⁠bi⁠pĕri֧y bĕhemĕţĕ̇⁠ká֛ ẇ⁠bi⁠pĕri֥y ʼadĕmáţĕ⁠ká֖ lĕ⁠twòbá֑h ki֣̇y ׀ yáş֣̌ẇb yĕhwá֗h lá⁠ş֤̂ẇş̂ ʻále֨y⁠ká֙ lĕ⁠t֔wòb kȧ⁠ʼàşěr-şá֖̂ş̂ ʻal-ʼàbòţeֽy⁠ká׃"],[30,10,"כִּ֣י תִשְׁמַ֗ע בְּ⁠קוֹל֙ יְהוָ֣ה אֱלֹהֶ֔י⁠ךָ לִ⁠שְׁמֹ֤ר מִצְוֺתָי⁠ו֙ וְ⁠חֻקֹּתָ֔י⁠ו הַ⁠כְּתוּבָ֕ה בְּ⁠סֵ֥פֶר הַ⁠תּוֹרָ֖ה הַ⁠זֶּ֑ה כִּ֤י תָשׁוּב֙ אֶל־יְהוָ֣ה אֱלֹהֶ֔י⁠ךָ בְּ⁠כָל־לְבָבְ⁠ךָ֖ וּ⁠בְ⁠כָל־נַפְשֶֽׁ⁠ךָ׃פ","ki֣̇y ţişĕ̌ma֗ʻ bĕ̇⁠qwòl֙ yĕhwá֣h ʼèlòhe֔y⁠ká li⁠şĕ̌mò֤r miẕĕwֺţáy⁠w֙ wĕ⁠ẖuqò̇ţá֔y⁠w ha⁠kĕ̇ţẇbá֕h bĕ̇⁠sé֥per ha⁠ţ̇wòrá֖h ha⁠zė֑h ki֤̇y ţáş̌ẇb֙ ʼel-yĕhwá֣h ʼèlòhe֔y⁠ká bĕ̇⁠kál-lĕbábĕ⁠ká֖ ẇ⁠bĕ⁠kál-napĕşěֽ⁠ká׃p"],[30,11,"כִּ֚י הַ⁠מִּצְוָ֣ה הַ⁠זֹּ֔את אֲשֶׁ֛ר אָנֹכִ֥י מְצַוְּ⁠ךָ֖ הַ⁠יּ֑וֹם לֹֽא־נִפְלֵ֥את הִוא֙ מִמְּ⁠ךָ֔ וְ⁠לֹ֥א רְחֹקָ֖ה הִֽוא׃","ki֚̇y ha⁠mi̇ẕĕwá֣h ha⁠zò̇֔ʼţ ʼàşě֛r ʼánòki֥y mĕẕawĕ̇⁠ká֖ ha⁠ẏ֑wòm lòֽʼ-nipĕlé֥ʼţ hiwʼ֙ mimĕ̇⁠ká֔ wĕ⁠lò֥ʼ rĕẖòqá֖h hiֽwʼ׃"],[30,12,"לֹ֥א בַ⁠שָּׁמַ֖יִם הִ֑וא לֵ⁠אמֹ֗ר מִ֣י יַעֲלֶה־לָּ֤⁠נוּ הַ⁠שָּׁמַ֨יְמָ⁠ה֙ וְ⁠יִקָּחֶ֣⁠הָ לָּ֔⁠נוּ וְ⁠יַשְׁמִעֵ֥⁠נוּ אֹתָ֖⁠הּ וְ⁠נַעֲשֶֽׂ⁠נָּה׃","lò֥ʼ ba⁠şá̇̌ma֖yim hi֑wʼ lé⁠ʼmò֗r mi֣y yaʻàleh-lá֤̇⁠nẇ ha⁠şá̇̌ma֨yĕmá⁠h֙ wĕ⁠yiqá̇ẖe֣⁠há lá̇֔⁠nẇ wĕ⁠yaşĕ̌miʻé֥⁠nẇ ʼòţá֖⁠ḣ wĕ⁠naʻàşêֽ⁠ná̇h׃"],[30,13,"וְ⁠לֹֽא־מֵ⁠עֵ֥בֶר לַ⁠יָּ֖ם הִ֑וא לֵ⁠אמֹ֗ר מִ֣י יַעֲבָר־לָ֜⁠נוּ אֶל־עֵ֤בֶר הַ⁠יָּם֙ וְ⁠יִקָּחֶ֣⁠הָ לָּ֔⁠נוּ וְ⁠יַשְׁמִעֵ֥⁠נוּ אֹתָ֖⁠הּ וְ⁠נַעֲשֶֽׂ⁠נָּה׃","wĕ⁠lòֽʼ-mé⁠ʻé֥ber la⁠yá֖̇m hi֑wʼ lé⁠ʼmò֗r mi֣y yaʻàbár-lá֜⁠nẇ ʼel-ʻé֤ber ha⁠yá̇m֙ wĕ⁠yiqá̇ẖe֣⁠há lá̇֔⁠nẇ wĕ⁠yaşĕ̌miʻé֥⁠nẇ ʼòţá֖⁠ḣ wĕ⁠naʻàşêֽ⁠ná̇h׃"],[30,14,"כִּֽי־קָר֥וֹב אֵלֶ֛י⁠ךָ הַ⁠דָּבָ֖ר מְאֹ֑ד בְּ⁠פִ֥י⁠ךָ וּ⁠בִֽ⁠לְבָבְ⁠ךָ֖ לַ⁠עֲשֹׂתֽ⁠וֹ׃ס","kiֽ̇y-qár֥wòb ʼéle֛y⁠ká ha⁠dá̇bá֖r mĕʼò֑d bĕ̇⁠pi֥y⁠ká ẇ⁠biֽ⁠lĕbábĕ⁠ká֖ la⁠ʻàşò̂ţֽ⁠wò׃s"],[30,15,"רְאֵ֨ה נָתַ֤תִּי לְ⁠פָנֶ֨י⁠ךָ֙ הַ⁠יּ֔וֹם אֶת־הַֽ⁠חַיִּ֖ים וְ⁠אֶת־הַ⁠טּ֑וֹב וְ⁠אֶת־הַ⁠מָּ֖וֶת וְ⁠אֶת־הָ⁠רָֽע׃","rĕʼé֨h náţa֤ţi̇y lĕ⁠páne֨y⁠ká֙ ha⁠ẏ֔wòm ʼeţ-haֽ⁠ẖayi֖̇ym wĕ⁠ʼeţ-ha⁠ṫ֑wòb wĕ⁠ʼeţ-ha⁠má֖̇weţ wĕ⁠ʼeţ-há⁠ráֽʻ׃"],[30,16,"אֲשֶׁ֨ר אָנֹכִ֣י מְצַוְּ⁠ךָ֮ הַ⁠יּוֹם֒ לְ⁠אַהֲבָ֞ה אֶת־יְהוָ֤ה אֱלֹהֶ֨י⁠ךָ֙ לָ⁠לֶ֣כֶת בִּ⁠דְרָכָ֔י⁠ו וְ⁠לִ⁠שְׁמֹ֛ר מִצְוֺתָ֥י⁠ו וְ⁠חֻקֹּתָ֖י⁠ו וּ⁠מִשְׁפָּטָ֑י⁠ו וְ⁠חָיִ֣יתָ וְ⁠רָבִ֔יתָ וּ⁠בֵֽרַכְ⁠ךָ֙ יְהוָ֣ה אֱלֹהֶ֔י⁠ךָ בָּ⁠אָ֕רֶץ אֲשֶׁר־אַתָּ֥ה בָא־שָׁ֖מָּ⁠ה לְ⁠רִשְׁתָּֽ⁠הּ׃","ʼàşě֨r ʼánòki֣y mĕẕawĕ̇⁠ká֮ ha⁠ẏwòm֒ lĕ⁠ʼahàbá֞h ʼeţ-yĕhwá֤h ʼèlòhe֨y⁠ká֙ lá⁠le֣keţ bi̇⁠dĕráká֔y⁠w wĕ⁠li⁠şĕ̌mò֛r miẕĕwֺţá֥y⁠w wĕ⁠ẖuqò̇ţá֖y⁠w ẇ⁠mişĕ̌pá̇tá֑y⁠w wĕ⁠ẖáyi֣yţá wĕ⁠rábi֔yţá ẇ⁠béֽrakĕ⁠ká֙ yĕhwá֣h ʼèlòhe֔y⁠ká bá̇⁠ʼá֕reẕ ʼàşěr-ʼaţá֥̇h báʼ-şá֖̌má̇⁠h lĕ⁠rişĕ̌ţáֽ̇⁠ḣ׃"],[30,17,"וְ⁠אִם־יִפְנֶ֥ה לְבָבְ⁠ךָ֖ וְ⁠לֹ֣א תִשְׁמָ֑ע וְ⁠נִדַּחְתָּ֗ וְ⁠הִֽשְׁתַּחֲוִ֛יתָ לֵ⁠אלֹהִ֥ים אֲחֵרִ֖ים וַ⁠עֲבַדְתָּֽ⁠ם׃","wĕ⁠ʼim-yipĕne֥h lĕbábĕ⁠ká֖ wĕ⁠lò֣ʼ ţişĕ̌má֑ʻ wĕ⁠nidȧẖĕţá̇֗ wĕ⁠hiֽşĕ̌ţȧẖàwi֛yţá lé⁠ʼlòhi֥ym ʼàẖéri֖ym wa⁠ʻàbadĕţáֽ̇⁠m׃"],[30,18,"הִגַּ֤דְתִּי לָ⁠כֶם֙ הַ⁠יּ֔וֹם כִּ֥י אָבֹ֖ד תֹּאבֵד֑וּ⁠ן לֹא־תַאֲרִיכֻ֤⁠ן יָמִים֙ עַל־הָ֣⁠אֲדָמָ֔ה אֲשֶׁ֨ר אַתָּ֤ה עֹבֵר֙ אֶת־הַ⁠יַּרְדֵּ֔ן לָ⁠בֹ֥א שָׁ֖מָּ⁠ה לְ⁠רִשְׁתָּֽ⁠הּ׃","higȧ֤dĕţi̇y lá⁠kem֙ ha⁠ẏ֔wòm ki֥̇y ʼábò֖d ţò̇ʼbéd֑ẇ⁠n lòʼ-ţaʼàriyku֤⁠n yámiym֙ ʻal-há֣⁠ʼàdámá֔h ʼàşě֨r ʼaţá֤̇h ʻòbér֙ ʼeţ-ha⁠yȧrĕdé̇֔n lá⁠bò֥ʼ şá֖̌má̇⁠h lĕ⁠rişĕ̌ţáֽ̇⁠ḣ׃"],[30,19,"הַעִידֹ֨תִי בָ⁠כֶ֣ם הַ⁠יּוֹם֮ אֶת־הַ⁠שָּׁמַ֣יִם וְ⁠אֶת־הָ⁠אָרֶץ֒ הַ⁠חַיִּ֤ים וְ⁠הַ⁠מָּ֨וֶת֙ נָתַ֣תִּי לְ⁠פָנֶ֔י⁠ךָ הַ⁠בְּרָכָ֖ה וְ⁠הַ⁠קְּלָלָ֑ה וּ⁠בָֽחַרְתָּ֙ בַּֽ⁠חַיִּ֔ים לְמַ֥עַן תִּחְיֶ֖ה אַתָּ֥ה וְ⁠זַרְעֶֽ⁠ךָ׃","haʻiydò֨ţiy bá⁠ke֣m ha⁠ẏwòm֮ ʼeţ-ha⁠şá̇̌ma֣yim wĕ⁠ʼeţ-há⁠ʼáreẕ֒ ha⁠ẖayi֤̇ym wĕ⁠ha⁠má̇֨weţ֙ náţa֣ţi̇y lĕ⁠páne֔y⁠ká ha⁠bĕ̇ráká֖h wĕ⁠ha⁠qĕ̇lálá֑h ẇ⁠báֽẖarĕţá̇֙ bȧֽ⁠ẖayi̇֔ym lĕma֥ʻan ţi̇ẖĕye֖h ʼaţá֥̇h wĕ⁠zarĕʻeֽ⁠ká׃"],[30,20,"לְ⁠אַֽהֲבָה֙ אֶת־יְהוָ֣ה אֱלֹהֶ֔י⁠ךָ לִ⁠שְׁמֹ֥עַ בְּ⁠קֹל֖⁠וֹ וּ⁠לְ⁠דָבְקָה־ב֑⁠וֹ כִּ֣י ה֤וּא חַיֶּ֨י⁠ךָ֙ וְ⁠אֹ֣רֶךְ יָמֶ֔י⁠ךָ לָ⁠שֶׁ֣בֶת עַל־הָ⁠אֲדָמָ֗ה אֲשֶׁר֩ נִשְׁבַּ֨ע יְהוָ֧ה לַ⁠אֲבֹתֶ֛י⁠ךָ לְ⁠אַבְרָהָ֛ם לְ⁠יִצְחָ֥ק וּֽ⁠לְ⁠יַעֲקֹ֖ב לָ⁠תֵ֥ת לָ⁠הֶֽם׃פ","lĕ⁠ʼaֽhàbáh֙ ʼeţ-yĕhwá֣h ʼèlòhe֔y⁠ká li⁠şĕ̌mò֥ʻa bĕ̇⁠qòl֖⁠wò ẇ⁠lĕ⁠dábĕqáh-b֑⁠wò ki֣̇y h֤ẇʼ ẖayė֨y⁠ká֙ wĕ⁠ʼò֣rekĕ yáme֔y⁠ká lá⁠şě֣beţ ʻal-há⁠ʼàdámá֗h ʼàşěr֩ nişĕ̌bȧ֨ʻ yĕhwá֧h la⁠ʼàbòţe֛y⁠ká lĕ⁠ʼabĕráhá֛m lĕ⁠yiẕĕẖá֥q ẇֽ⁠lĕ⁠yaʻàqò֖b lá⁠ţé֥ţ lá⁠heֽm׃p"],[31,1,"וַ⁠יֵּ֖לֶךְ מֹשֶׁ֑ה וַ⁠יְדַבֵּ֛ר אֶת־הַ⁠דְּבָרִ֥ים הָ⁠אֵ֖לֶּה אֶל־כָּל־יִשְׂרָאֵֽל׃","wa⁠yé֖̇lekĕ mòşě֑h wa⁠yĕdabé֛̇r ʼeţ-ha⁠dĕ̇bári֥ym há⁠ʼé֖lėh ʼel-ká̇l-yişĕ̂ráʼéֽl׃"],[31,2,"וַ⁠יֹּ֣אמֶר אֲלֵ⁠הֶ֗ם בֶּן־מֵאָה֩ וְ⁠עֶשְׂרִ֨ים שָׁנָ֤ה אָנֹכִי֙ הַ⁠יּ֔וֹם לֹא־אוּכַ֥ל ע֖וֹד לָ⁠צֵ֣את וְ⁠לָ⁠ב֑וֹא וַֽ⁠יהוָה֙ אָמַ֣ר אֵלַ֔⁠י לֹ֥א תַעֲבֹ֖ר אֶת־הַ⁠יַּרְדֵּ֥ן הַ⁠זֶּֽה׃","wa⁠yò֣̇ʼmer ʼàlé⁠he֗m bėn-méʼáh֩ wĕ⁠ʻeşĕ̂ri֨ym şá̌ná֤h ʼánòkiy֙ ha⁠ẏ֔wòm lòʼ-ʼẇka֥l ʻ֖wòd lá⁠ẕé֣ʼţ wĕ⁠lá⁠b֑wòʼ waֽ⁠yhwáh֙ ʼáma֣r ʼéla֔⁠y lò֥ʼ ţaʻàbò֖r ʼeţ-ha⁠yȧrĕdé֥̇n ha⁠zėֽh׃"],[31,3,"יְהוָ֨ה אֱלֹהֶ֜י⁠ךָ ה֣וּא ׀ עֹבֵ֣ר לְ⁠פָנֶ֗י⁠ךָ הֽוּא־יַשְׁמִ֞יד אֶת־הַ⁠גּוֹיִ֥ם הָ⁠אֵ֛לֶּה מִ⁠לְּ⁠פָנֶ֖י⁠ךָ וִֽ⁠ירִשְׁתָּ֑⁠ם יְהוֹשֻׁ֗עַ ה֚וּא עֹבֵ֣ר לְ⁠פָנֶ֔י⁠ךָ כַּ⁠אֲשֶׁ֖ר דִּבֶּ֥ר יְהוָֽה׃","yĕhwá֨h ʼèlòhe֜y⁠ká h֣ẇʼ ׀ ʻòbé֣r lĕ⁠páne֗y⁠ká hֽẇʼ-yaşĕ̌mi֞yd ʼeţ-ha⁠ġwòyi֥m há⁠ʼé֛lėh mi⁠lĕ̇⁠páne֖y⁠ká wiֽ⁠yrişĕ̌ţá֑̇⁠m yĕhwòşǔ֗ʻa h֚ẇʼ ʻòbé֣r lĕ⁠páne֔y⁠ká kȧ⁠ʼàşě֖r di̇bė֥r yĕhwáֽh׃"],[31,4,"וְ⁠עָשָׂ֤ה יְהוָה֙ לָ⁠הֶ֔ם כַּ⁠אֲשֶׁ֣ר עָשָׂ֗ה לְ⁠סִיח֥וֹן וּ⁠לְ⁠ע֛וֹג מַלְכֵ֥י הָ⁠אֱמֹרִ֖י וּ⁠לְ⁠אַרְצָ֑⁠ם אֲשֶׁ֥ר הִשְׁמִ֖יד אֹתָֽ⁠ם׃","wĕ⁠ʻáşá֤̂h yĕhwáh֙ lá⁠he֔m kȧ⁠ʼàşě֣r ʻáşá̂֗h lĕ⁠siyẖ֥wòn ẇ⁠lĕ⁠ʻ֛wòg malĕké֥y há⁠ʼèmòri֖y ẇ⁠lĕ⁠ʼarĕẕá֑⁠m ʼàşě֥r hişĕ̌mi֖yd ʼòţáֽ⁠m׃"],[31,5,"וּ⁠נְתָנָ֥⁠ם יְהוָ֖ה לִ⁠פְנֵי⁠כֶ֑ם וַ⁠עֲשִׂיתֶ֣ם לָ⁠הֶ֔ם כְּ⁠כָל־הַ⁠מִּצְוָ֔ה אֲשֶׁ֥ר צִוִּ֖יתִי אֶתְ⁠כֶֽם׃","ẇ⁠nĕţáná֥⁠m yĕhwá֖h li⁠pĕnéy⁠ke֑m wa⁠ʻàşîyţe֣m lá⁠he֔m kĕ̇⁠kál-ha⁠mi̇ẕĕwá֔h ʼàşě֥r ẕiwi֖̇yţiy ʼeţĕ⁠keֽm׃"],[31,6,"חִזְק֣וּ וְ⁠אִמְצ֔וּ אַל־תִּֽירְא֥וּ וְ⁠אַל־תַּעַרְצ֖וּ מִ⁠פְּנֵי⁠הֶ֑ם כִּ֣י ׀ יְהוָ֣ה אֱלֹהֶ֗י⁠ךָ ה֚וּא הַ⁠הֹלֵ֣ךְ עִמָּ֔⁠ךְ לֹ֥א יַרְפְּ⁠ךָ֖ וְ⁠לֹ֥א יַעַזְבֶֽ⁠ךָּ׃פ","ẖizĕq֣ẇ wĕ⁠ʼimĕẕ֔ẇ ʼal-ţiֽ̇yrĕʼ֥ẇ wĕ⁠ʼal-ţȧʻarĕẕ֖ẇ mi⁠pĕ̇néy⁠he֑m ki֣̇y ׀ yĕhwá֣h ʼèlòhe֗y⁠ká h֚ẇʼ ha⁠hòlé֣kĕ ʻimá̇֔⁠kĕ lò֥ʼ yarĕpĕ̇⁠ká֖ wĕ⁠lò֥ʼ yaʻazĕbeֽ⁠ká̇׃p"],[31,7,"וַ⁠יִּקְרָ֨א מֹשֶׁ֜ה לִֽ⁠יהוֹשֻׁ֗עַ וַ⁠יֹּ֨אמֶר אֵלָ֜י⁠ו לְ⁠עֵינֵ֣י כָל־יִשְׂרָאֵ֘ל חֲזַ֣ק וֶ⁠אֱמָץ֒ כִּ֣י אַתָּ֗ה תָּבוֹא֙ אֶת־הָ⁠עָ֣ם הַ⁠זֶּ֔ה אֶל־הָ⁠אָ֕רֶץ אֲשֶׁ֨ר נִשְׁבַּ֧ע יְהוָ֛ה לַ⁠אֲבֹתָ֖⁠ם לָ⁠תֵ֣ת לָ⁠הֶ֑ם וְ⁠אַתָּ֖ה תַּנְחִילֶ֥⁠נָּה אוֹתָֽ⁠ם׃","wa⁠yi̇qĕrá֨ʼ mòşě֜h liֽ⁠yhwòşǔ֗ʻa wa⁠yò̇֨ʼmer ʼélá֜y⁠w lĕ⁠ʻéyné֣y kál-yişĕ̂ráʼé֘l ẖàza֣q we⁠ʼèmáẕ֒ ki֣̇y ʼaţá̇֗h ţá̇bwòʼ֙ ʼeţ-há⁠ʻá֣m ha⁠zė֔h ʼel-há⁠ʼá֕reẕ ʼàşě֨r nişĕ̌bȧ֧ʻ yĕhwá֛h la⁠ʼàbòţá֖⁠m lá⁠ţé֣ţ lá⁠he֑m wĕ⁠ʼaţá֖̇h ţȧnĕẖiyle֥⁠ná̇h ʼwòţáֽ⁠m׃"],[31,8,"וַֽ⁠יהוָ֞ה ה֣וּא ׀ הַ⁠הֹלֵ֣ךְ לְ⁠פָנֶ֗י⁠ךָ ה֚וּא יִהְיֶ֣ה עִמָּ֔⁠ךְ לֹ֥א יַרְפְּ⁠ךָ֖ וְ⁠לֹ֣א יַֽעַזְבֶ֑⁠ךָּ לֹ֥א תִירָ֖א וְ⁠לֹ֥א תֵחָֽת׃","waֽ⁠yhwá֞h h֣ẇʼ ׀ ha⁠hòlé֣kĕ lĕ⁠páne֗y⁠ká h֚ẇʼ yihĕye֣h ʻimá̇֔⁠kĕ lò֥ʼ yarĕpĕ̇⁠ká֖ wĕ⁠lò֣ʼ yaֽʻazĕbe֑⁠ká̇ lò֥ʼ ţiyrá֖ʼ wĕ⁠lò֥ʼ ţéẖáֽţ׃"],[31,9,"וַ⁠יִּכְתֹּ֣ב מֹשֶׁה֮ אֶת־הַ⁠תּוֹרָ֣ה הַ⁠זֹּאת֒ וַֽ⁠יִּתְּנָ֗⁠הּ אֶל־הַ⁠כֹּהֲנִים֙ בְּנֵ֣י לֵוִ֔י הַ⁠נֹּ֣שְׂאִ֔ים אֶת־אֲר֖וֹן בְּרִ֣ית יְהוָ֑ה וְ⁠אֶל־כָּל־זִקְנֵ֖י יִשְׂרָאֵֽל׃","wa⁠yi̇kĕţò֣̇b mòşěh֮ ʼeţ-ha⁠ţ̇wòrá֣h ha⁠zò̇ʼţ֒ waֽ⁠yi̇ţĕ̇ná֗⁠ḣ ʼel-ha⁠kò̇hàniym֙ bĕ̇né֣y léwi֔y ha⁠nò֣̇şĕ̂ʼi֔ym ʼeţ-ʼàr֖wòn bĕ̇ri֣yţ yĕhwá֑h wĕ⁠ʼel-ká̇l-ziqĕné֖y yişĕ̂ráʼéֽl׃"],[31,10,"וַ⁠יְצַ֥ו מֹשֶׁ֖ה אוֹתָ֣⁠ם לֵ⁠אמֹ֑ר מִ⁠קֵּ֣ץ ׀ שֶׁ֣בַע שָׁנִ֗ים בְּ⁠מֹעֵ֛ד שְׁנַ֥ת הַ⁠שְּׁמִטָּ֖ה בְּ⁠חַ֥ג הַ⁠סֻּכּֽוֹת׃","wa⁠yĕẕa֥w mòşě֖h ʼwòţá֣⁠m lé⁠ʼmò֑r mi⁠qé֣̇ẕ ׀ şě֣baʻ şá̌ni֗ym bĕ̇⁠mòʻé֛d şĕ̌na֥ţ ha⁠şĕ̇̌mitá֖̇h bĕ̇⁠ẖa֥g ha⁠su̇kֽ̇wòţ׃"],[31,11,"בְּ⁠ב֣וֹא כָל־יִשְׂרָאֵ֗ל לֵ⁠רָאוֹת֙ אֶת־פְּנֵי֙ יְהוָ֣ה אֱלֹהֶ֔י⁠ךָ בַּ⁠מָּק֖וֹם אֲשֶׁ֣ר יִבְחָ֑ר תִּקְרָ֞א אֶת־הַ⁠תּוֹרָ֥ה הַ⁠זֹּ֛את נֶ֥גֶד כָּל־יִשְׂרָאֵ֖ל בְּ⁠אָזְנֵי⁠הֶֽם׃","bĕ̇⁠b֣wòʼ kál-yişĕ̂ráʼé֗l lé⁠ráʼwòţ֙ ʼeţ-pĕ̇néy֙ yĕhwá֣h ʼèlòhe֔y⁠ká bȧ⁠má̇q֖wòm ʼàşě֣r yibĕẖá֑r ţi̇qĕrá֞ʼ ʼeţ-ha⁠ţ̇wòrá֥h ha⁠zò֛̇ʼţ ne֥ged ká̇l-yişĕ̂ráʼé֖l bĕ̇⁠ʼázĕnéy⁠heֽm׃"],[31,12,"הַקְהֵ֣ל אֶת־הָ⁠עָ֗ם הָֽ⁠אֲנָשִׁ֤ים וְ⁠הַ⁠נָּשִׁים֙ וְ⁠הַ⁠טַּ֔ף וְ⁠גֵרְ⁠ךָ֖ אֲשֶׁ֣ר בִּ⁠שְׁעָרֶ֑י⁠ךָ לְמַ֨עַן יִשְׁמְע֜וּ וּ⁠לְמַ֣עַן יִלְמְד֗וּ וְ⁠יָֽרְאוּ֙ אֶת־יְהוָ֣ה אֱלֹֽהֵי⁠כֶ֔ם וְ⁠שָֽׁמְר֣וּ לַ⁠עֲשׂ֔וֹת אֶת־כָּל־דִּבְרֵ֖י הַ⁠תּוֹרָ֥ה הַ⁠זֹּֽאת׃","haqĕhé֣l ʼeţ-há⁠ʻá֗m háֽ⁠ʼànáşǐ֤ym wĕ⁠ha⁠ná̇şǐym֙ wĕ⁠ha⁠tȧ֔p wĕ⁠gérĕ⁠ká֖ ʼàşě֣r bi̇⁠şĕ̌ʻáre֑y⁠ká lĕma֨ʻan yişĕ̌mĕʻ֜ẇ ẇ⁠lĕma֣ʻan yilĕmĕd֗ẇ wĕ⁠yáֽrĕʼẇ֙ ʼeţ-yĕhwá֣h ʼèlòֽhéy⁠ke֔m wĕ⁠şáֽ̌mĕr֣ẇ la⁠ʻàş̂֔wòţ ʼeţ-ká̇l-di̇bĕré֖y ha⁠ţ̇wòrá֥h ha⁠zòֽ̇ʼţ׃"],[31,13,"וּ⁠בְנֵי⁠הֶ֞ם אֲשֶׁ֣ר לֹֽא־יָדְע֗וּ יִשְׁמְעוּ֙ וְ⁠לָ֣מְד֔וּ לְ⁠יִרְאָ֖ה אֶת־יְהוָ֣ה אֱלֹהֵי⁠כֶ֑ם כָּל־הַ⁠יָּמִ֗ים אֲשֶׁ֨ר אַתֶּ֤ם חַיִּים֙ עַל־הָ֣⁠אֲדָמָ֔ה אֲשֶׁ֨ר אַתֶּ֜ם עֹבְרִ֧ים אֶת־הַ⁠יַּרְדֵּ֛ן שָׁ֖מָּ⁠ה לְ⁠רִשְׁתָּֽ⁠הּ׃פ","ẇ⁠bĕnéy⁠he֞m ʼàşě֣r lòֽʼ-yádĕʻ֗ẇ yişĕ̌mĕʻẇ֙ wĕ⁠lá֣mĕd֔ẇ lĕ⁠yirĕʼá֖h ʼeţ-yĕhwá֣h ʼèlòhéy⁠ke֑m ká̇l-ha⁠yá̇mi֗ym ʼàşě֨r ʼaţė֤m ẖayi̇ym֙ ʻal-há֣⁠ʼàdámá֔h ʼàşě֨r ʼaţė֜m ʻòbĕri֧ym ʼeţ-ha⁠yȧrĕdé֛̇n şá֖̌má̇⁠h lĕ⁠rişĕ̌ţáֽ̇⁠ḣ׃p"],[31,14,"וַ⁠יֹּ֨אמֶר יְהוָ֜ה אֶל־מֹשֶׁ֗ה הֵ֣ן קָרְב֣וּ יָמֶי⁠ךָ֮ לָ⁠מוּת֒ קְרָ֣א אֶת־יְהוֹשֻׁ֗עַ וְ⁠הִֽתְיַצְּב֛וּ בְּ⁠אֹ֥הֶל מוֹעֵ֖ד וַ⁠אֲצַוֶּ֑⁠נּוּ וַ⁠יֵּ֤לֶךְ מֹשֶׁה֙ וִֽ⁠יהוֹשֻׁ֔עַ וַ⁠יִּֽתְיַצְּב֖וּ בְּ⁠אֹ֥הֶל מוֹעֵֽד׃","wa⁠yò̇֨ʼmer yĕhwá֜h ʼel-mòşě֗h hé֣n qárĕb֣ẇ yámey⁠ká֮ lá⁠mẇţ֒ qĕrá֣ʼ ʼeţ-yĕhwòşǔ֗ʻa wĕ⁠hiֽţĕyaẕĕ̇b֛ẇ bĕ̇⁠ʼò֥hel mwòʻé֖d wa⁠ʼàẕawė֑⁠ṅẇ wa⁠yé֤̇lekĕ mòşěh֙ wiֽ⁠yhwòşǔ֔ʻa wa⁠yiֽ̇ţĕyaẕĕ̇b֖ẇ bĕ̇⁠ʼò֥hel mwòʻéֽd׃"],[31,15,"וַ⁠יֵּרָ֧א יְהוָ֛ה בָּ⁠אֹ֖הֶל בְּ⁠עַמּ֣וּד עָנָ֑ן וַ⁠יַּעֲמֹ֛ד עַמּ֥וּד הֶ⁠עָנָ֖ן עַל־פֶּ֥תַח הָ⁠אֹֽהֶל׃ס","wa⁠yé̇rá֧ʼ yĕhwá֛h bá̇⁠ʼò֖hel bĕ̇⁠ʻaṁ֣ẇd ʻáná֑n wa⁠yȧʻàmò֛d ʻaṁ֥ẇd he⁠ʻáná֖n ʻal-pė֥ţaẖ há⁠ʼòֽhel׃s"],[31,16,"וַ⁠יֹּ֤אמֶר יְהוָה֙ אֶל־מֹשֶׁ֔ה הִנְּ⁠ךָ֥ שֹׁכֵ֖ב עִם־אֲבֹתֶ֑י⁠ךָ וְ⁠קָם֩ הָ⁠עָ֨ם הַ⁠זֶּ֜ה וְ⁠זָנָ֣ה ׀ אַחֲרֵ֣י ׀ אֱלֹהֵ֣י נֵֽכַר־הָ⁠אָ֗רֶץ אֲשֶׁ֨ר ה֤וּא בָא־שָׁ֨מָּ⁠ה֙ בְּ⁠קִרְבּ֔⁠וֹ וַ⁠עֲזָבַ֕⁠נִי וְ⁠הֵפֵר֙ אֶת־בְּרִיתִ֔⁠י אֲשֶׁ֥ר כָּרַ֖תִּי אִתּֽ⁠וֹ׃","wa⁠yò֤̇ʼmer yĕhwáh֙ ʼel-mòşě֔h hinĕ̇⁠ká֥ şò̌ké֖b ʻim-ʼàbòţe֑y⁠ká wĕ⁠qám֩ há⁠ʻá֨m ha⁠zė֜h wĕ⁠záná֣h ׀ ʼaẖàré֣y ׀ ʼèlòhé֣y néֽkar-há⁠ʼá֗reẕ ʼàşě֨r h֤ẇʼ báʼ-şá̌֨má̇⁠h֙ bĕ̇⁠qirĕḃ֔⁠wò wa⁠ʻàzába֕⁠niy wĕ⁠hépér֙ ʼeţ-bĕ̇riyţi֔⁠y ʼàşě֥r ká̇ra֖ţi̇y ʼiţֽ̇⁠wò׃"],[31,17,"וְ⁠חָרָ֣ה אַפִּ֣⁠י ב֣⁠וֹ בַ⁠יּוֹם־הַ֠⁠הוּא וַ⁠עֲזַבְתִּ֞י⁠ם וְ⁠הִסְתַּרְתִּ֨י פָנַ֤⁠י מֵ⁠הֶם֙ וְ⁠הָיָ֣ה לֶֽ⁠אֱכֹ֔ל וּ⁠מְצָאֻ֛⁠הוּ רָע֥וֹת רַבּ֖וֹת וְ⁠צָר֑וֹת וְ⁠אָמַר֙ בַּ⁠יּ֣וֹם הַ⁠ה֔וּא הֲ⁠לֹ֗א עַ֣ל כִּֽי־אֵ֤ין אֱלֹהַ⁠י֙ בְּ⁠קִרְבִּ֔⁠י מְצָא֖וּ⁠נִי הָ⁠רָע֥וֹת הָ⁠אֵֽלֶּה׃","wĕ⁠ẖárá֣h ʼapi֣̇⁠y b֣⁠wò ba⁠ẏwòm-ha֠⁠hẇʼ wa⁠ʻàzabĕţi̇֞y⁠m wĕ⁠hisĕţȧrĕţi̇֨y pána֤⁠y mé⁠hem֙ wĕ⁠háyá֣h leֽ⁠ʼèkò֔l ẇ⁠mĕẕáʼu֛⁠hẇ ráʻ֥wòţ raḃ֖wòţ wĕ⁠ẕár֑wòţ wĕ⁠ʼámar֙ bȧ⁠ẏ֣wòm ha⁠h֔ẇʼ hà⁠lò֗ʼ ʻa֣l kiֽ̇y-ʼé֤yn ʼèlòha⁠y֙ bĕ̇⁠qirĕbi̇֔⁠y mĕẕáʼ֖ẇ⁠niy há⁠ráʻ֥wòţ há⁠ʼéֽlėh׃"],[31,18,"וְ⁠אָנֹכִ֗י הַסְתֵּ֨ר אַסְתִּ֤יר פָּנַ⁠י֙ בַּ⁠יּ֣וֹם הַ⁠ה֔וּא עַ֥ל כָּל־הָ⁠רָעָ֖ה אֲשֶׁ֣ר עָשָׂ֑ה כִּ֣י פָנָ֔ה אֶל־אֱלֹהִ֖ים אֲחֵרִֽים׃","wĕ⁠ʼánòki֗y hasĕţé̇֨r ʼasĕţi֤̇yr pá̇na⁠y֙ bȧ⁠ẏ֣wòm ha⁠h֔ẇʼ ʻa֥l ká̇l-há⁠ráʻá֖h ʼàşě֣r ʻáşá֑̂h ki֣̇y páná֔h ʼel-ʼèlòhi֖ym ʼàẖériֽym׃"],[31,19,"וְ⁠עַתָּ֗ה כִּתְב֤וּ לָ⁠כֶם֙ אֶת־הַ⁠שִּׁירָ֣ה הַ⁠זֹּ֔את וְ⁠לַמְּדָ֥⁠הּ אֶת־בְּנֵי־יִשְׂרָאֵ֖ל שִׂימָ֣⁠הּ בְּ⁠פִי⁠הֶ֑ם לְמַ֨עַן תִּהְיֶה־לִּ֜⁠י הַ⁠שִּׁירָ֥ה הַ⁠זֹּ֛את לְ⁠עֵ֖ד בִּ⁠בְנֵ֥י יִשְׂרָאֵֽל׃","wĕ⁠ʻaţá̇֗h ki̇ţĕb֤ẇ lá⁠kem֙ ʼeţ-ha⁠şi̇̌yrá֣h ha⁠zò̇֔ʼţ wĕ⁠lamĕ̇dá֥⁠ḣ ʼeţ-bĕ̇néy-yişĕ̂ráʼé֖l şîymá֣⁠ḣ bĕ̇⁠piy⁠he֑m lĕma֨ʻan ţi̇hĕyeh-li̇֜⁠y ha⁠şi̇̌yrá֥h ha⁠zò֛̇ʼţ lĕ⁠ʻé֖d bi̇⁠bĕné֥y yişĕ̂ráʼéֽl׃"],[31,20,"כִּֽי־אֲבִיאֶ֜⁠נּוּ אֶֽל־הָ⁠אֲדָמָ֣ה ׀ אֲשֶׁר־נִשְׁבַּ֣עְתִּי לַ⁠אֲבֹתָ֗י⁠ו זָבַ֤ת חָלָב֙ וּ⁠דְבַ֔שׁ וְ⁠אָכַ֥ל וְ⁠שָׂבַ֖ע וְ⁠דָשֵׁ֑ן וּ⁠פָנָ֞ה אֶל־אֱלֹהִ֤ים אֲחֵרִים֙ וַ⁠עֲבָד֔וּ⁠ם וְ⁠נִ֣אֲצ֔וּ⁠נִי וְ⁠הֵפֵ֖ר אֶת־בְּרִיתִֽ⁠י׃","kiֽ̇y-ʼàbiyʼe֜⁠ṅẇ ʼeֽl-há⁠ʼàdámá֣h ׀ ʼàşěr-nişĕ̌bȧ֣ʻĕţi̇y la⁠ʼàbòţá֗y⁠w zába֤ţ ẖáláb֙ ẇ⁠dĕba֔ş̌ wĕ⁠ʼáka֥l wĕ⁠şá̂ba֖ʻ wĕ⁠dáşé֑̌n ẇ⁠páná֞h ʼel-ʼèlòhi֤ym ʼàẖériym֙ wa⁠ʻàbád֔ẇ⁠m wĕ⁠ni֣ʼàẕ֔ẇ⁠niy wĕ⁠hépé֖r ʼeţ-bĕ̇riyţiֽ⁠y׃"],[31,21,"וְ֠⁠הָיָה כִּֽי־תִמְצֶ֨אןָ אֹת֜⁠וֹ רָע֣וֹת רַבּוֹת֮ וְ⁠צָרוֹת֒ וְ֠⁠עָנְתָה הַ⁠שִּׁירָ֨ה הַ⁠זֹּ֤את לְ⁠פָנָי⁠ו֙ לְ⁠עֵ֔ד כִּ֛י לֹ֥א תִשָּׁכַ֖ח מִ⁠פִּ֣י זַרְע֑⁠וֹ כִּ֧י יָדַ֣עְתִּי אֶת־יִצְר֗⁠וֹ אֲשֶׁ֨ר ה֤וּא עֹשֶׂה֙ הַ⁠יּ֔וֹם בְּ⁠טֶ֣רֶם אֲבִיאֶ֔⁠נּוּ אֶל־הָ⁠אָ֖רֶץ אֲשֶׁ֥ר נִשְׁבָּֽעְתִּי׃","wĕ֠⁠háyáh kiֽ̇y-ţimĕẕe֨ʼná ʼòţ֜⁠wò ráʻ֣wòţ raḃwòţ֮ wĕ⁠ẕárwòţ֒ wĕ֠⁠ʻánĕţáh ha⁠şi̇̌yrá֨h ha⁠zò֤̇ʼţ lĕ⁠pánáy⁠w֙ lĕ⁠ʻé֔d ki֛̇y lò֥ʼ ţişá̇̌ka֖ẖ mi⁠pi֣̇y zarĕʻ֑⁠wò ki֧̇y yáda֣ʻĕţi̇y ʼeţ-yiẕĕr֗⁠wò ʼàşě֨r h֤ẇʼ ʻòşêh֙ ha⁠ẏ֔wòm bĕ̇⁠te֣rem ʼàbiyʼe֔⁠ṅẇ ʼel-há⁠ʼá֖reẕ ʼàşě֥r nişĕ̌báֽ̇ʻĕţi̇y׃"],[31,22,"וַ⁠יִּכְתֹּ֥ב מֹשֶׁ֛ה אֶת־הַ⁠שִּׁירָ֥ה הַ⁠זֹּ֖את בַּ⁠יּ֣וֹם הַ⁠ה֑וּא וַֽ⁠יְלַמְּדָ֖⁠הּ אֶת־בְּנֵ֥י יִשְׂרָאֵֽל׃","wa⁠yi̇kĕţò֥̇b mòşě֛h ʼeţ-ha⁠şi̇̌yrá֥h ha⁠zò֖̇ʼţ bȧ⁠ẏ֣wòm ha⁠h֑ẇʼ waֽ⁠yĕlamĕ̇dá֖⁠ḣ ʼeţ-bĕ̇né֥y yişĕ̂ráʼéֽl׃"],[31,23,"וַ⁠יְצַ֞ו אֶת־יְהוֹשֻׁ֣עַ בִּן־נ֗וּן וַ⁠יֹּאמֶר֮ חֲזַ֣ק וֶֽ⁠אֱמָץ֒ כִּ֣י אַתָּ֗ה תָּבִיא֙ אֶת־בְּנֵ֣י יִשְׂרָאֵ֔ל אֶל־הָ⁠אָ֖רֶץ אֲשֶׁר־נִשְׁבַּ֣עְתִּי לָ⁠הֶ֑ם וְ⁠אָנֹכִ֖י אֶֽהְיֶ֥ה עִמָּֽ⁠ךְ׃","wa⁠yĕẕa֞w ʼeţ-yĕhwòşǔ֣ʻa bi̇n-n֗ẇn wa⁠yò̇ʼmer֮ ẖàza֣q weֽ⁠ʼèmáẕ֒ ki֣̇y ʼaţá̇֗h ţá̇biyʼ֙ ʼeţ-bĕ̇né֣y yişĕ̂ráʼé֔l ʼel-há⁠ʼá֖reẕ ʼàşěr-nişĕ̌bȧ֣ʻĕţi̇y lá⁠he֑m wĕ⁠ʼánòki֖y ʼeֽhĕye֥h ʻimáֽ̇⁠kĕ׃"],[31,24,"וַ⁠יְהִ֣י ׀ כְּ⁠כַלּ֣וֹת מֹשֶׁ֗ה לִ⁠כְתֹּ֛ב אֶת־דִּבְרֵ֥י הַ⁠תּוֹרָֽה־הַ⁠זֹּ֖את עַל־סֵ֑פֶר עַ֖ד תֻּמָּֽ⁠ם׃","wa⁠yĕhi֣y ׀ kĕ̇⁠kal֣̇wòţ mòşě֗h li⁠kĕţò֛̇b ʼeţ-di̇bĕré֥y ha⁠ţ̇wòráֽh-ha⁠zò֖̇ʼţ ʻal-sé֑per ʻa֖d ţu̇máֽ̇⁠m׃"],[31,25,"וַ⁠יְצַ֤ו מֹשֶׁה֙ אֶת־הַ⁠לְוִיִּ֔ם נֹ֥שְׂאֵ֛י אֲר֥וֹן בְּרִית־יְהוָ֖ה לֵ⁠אמֹֽר׃","wa⁠yĕẕa֤w mòşěh֙ ʼeţ-ha⁠lĕwiyi̇֔m nò֥şĕ̂ʼé֛y ʼàr֥wòn bĕ̇riyţ-yĕhwá֖h lé⁠ʼmòֽr׃"],[31,26,"לָקֹ֗חַ אֵ֣ת סֵ֤פֶר הַ⁠תּוֹרָה֙ הַ⁠זֶּ֔ה וְ⁠שַׂמְתֶּ֣ם אֹת֔⁠וֹ מִ⁠צַּ֛ד אֲר֥וֹן בְּרִית־יְהוָ֖ה אֱלֹהֵי⁠כֶ֑ם וְ⁠הָֽיָה־שָׁ֥ם בְּ⁠ךָ֖ לְ⁠עֵֽד׃","láqò֗ẖa ʼé֣ţ sé֤per ha⁠ţ̇wòráh֙ ha⁠zė֔h wĕ⁠şâmĕţė֣m ʼòţ֔⁠wò mi⁠ẕȧ֛d ʼàr֥wòn bĕ̇riyţ-yĕhwá֖h ʼèlòhéy⁠ke֑m wĕ⁠háֽyáh-şá֥̌m bĕ̇⁠ká֖ lĕ⁠ʻéֽd׃"],[31,27,"כִּ֣י אָנֹכִ֤י יָדַ֨עְתִּי֙ אֶֽת־מֶרְיְ⁠ךָ֔ וְ⁠אֶֽת־עָרְפְּ⁠ךָ֖ הַ⁠קָּשֶׁ֑ה הֵ֣ן בְּ⁠עוֹדֶ⁠נִּי֩ חַ֨י עִמָּ⁠כֶ֜ם הַ⁠יּ֗וֹם מַמְרִ֤ים הֱיִתֶם֙ עִם־יְהֹוָ֔ה וְ⁠אַ֖ף כִּי־אַחֲרֵ֥י מוֹתִֽ⁠י׃","ki֣̇y ʼánòki֤y yáda֨ʻĕţi̇y֙ ʼeֽţ-merĕyĕ⁠ká֔ wĕ⁠ʼeֽţ-ʻárĕpĕ̇⁠ká֖ ha⁠qá̇şě֑h hé֣n bĕ̇⁠ʻwòde⁠ni̇y֩ ẖa֨y ʻimá̇⁠ke֜m ha⁠ẏ֗wòm mamĕri֤ym hèyiţem֙ ʻim-yĕhòwá֔h wĕ⁠ʼa֖p ki̇y-ʼaẖàré֥y mwòţiֽ⁠y׃"],[31,28,"הַקְהִ֧ילוּ אֵלַ֛⁠י אֶת־כָּל־זִקְנֵ֥י שִׁבְטֵי⁠כֶ֖ם וְ⁠שֹׁטְרֵי⁠כֶ֑ם וַ⁠אֲדַבְּרָ֣ה בְ⁠אָזְנֵי⁠הֶ֗ם אֵ֚ת הַ⁠דְּבָרִ֣ים הָ⁠אֵ֔לֶּה וְ⁠אָעִ֣ידָה בָּ֔⁠ם אֶת־הַ⁠שָּׁמַ֖יִם וְ⁠אֶת־הָ⁠אָֽרֶץ׃","haqĕhi֧ylẇ ʼéla֛⁠y ʼeţ-ká̇l-ziqĕné֥y şǐbĕtéy⁠ke֖m wĕ⁠şò̌tĕréy⁠ke֑m wa⁠ʼàdabĕ̇rá֣h bĕ⁠ʼázĕnéy⁠he֗m ʼé֚ţ ha⁠dĕ̇bári֣ym há⁠ʼé֔lėh wĕ⁠ʼáʻi֣ydáh bá̇֔⁠m ʼeţ-ha⁠şá̇̌ma֖yim wĕ⁠ʼeţ-há⁠ʼáֽreẕ׃"],[31,29,"כִּ֣י יָדַ֗עְתִּי אַחֲרֵ֤י מוֹתִ⁠י֙ כִּֽי־הַשְׁחֵ֣ת תַּשְׁחִת֔וּ⁠ן וְ⁠סַרְתֶּ֣ם מִן־הַ⁠דֶּ֔רֶךְ אֲשֶׁ֥ר צִוִּ֖יתִי אֶתְ⁠כֶ֑ם וְ⁠קָרָ֨את אֶתְ⁠כֶ֤ם הָֽ⁠רָעָה֙ בְּ⁠אַחֲרִ֣ית הַ⁠יָּמִ֔ים כִּֽי־תַעֲשׂ֤וּ אֶת־הָ⁠רַע֙ בְּ⁠עֵינֵ֣י יְהוָ֔ה לְ⁠הַכְעִיס֖⁠וֹ בְּ⁠מַעֲשֵׂ֥ה יְדֵי⁠כֶֽם׃","ki֣̇y yáda֗ʻĕţi̇y ʼaẖàré֤y mwòţi⁠y֙ kiֽ̇y-haşĕ̌ẖé֣ţ ţȧşĕ̌ẖiţ֔ẇ⁠n wĕ⁠sarĕţė֣m min-ha⁠dė֔rekĕ ʼàşě֥r ẕiwi֖̇yţiy ʼeţĕ⁠ke֑m wĕ⁠qárá֨ʼţ ʼeţĕ⁠ke֤m háֽ⁠ráʻáh֙ bĕ̇⁠ʼaẖàri֣yţ ha⁠yá̇mi֔ym kiֽ̇y-ţaʻàş֤̂ẇ ʼeţ-há⁠raʻ֙ bĕ̇⁠ʻéyné֣y yĕhwá֔h lĕ⁠hakĕʻiys֖⁠wò bĕ̇⁠maʻàşé֥̂h yĕdéy⁠keֽm׃"],[31,30,"וַ⁠יְדַבֵּ֣ר מֹשֶׁ֗ה בְּ⁠אָזְנֵי֙ כָּל־קְהַ֣ל יִשְׂרָאֵ֔ל אֶת־דִּבְרֵ֥י הַ⁠שִּׁירָ֖ה הַ⁠זֹּ֑את עַ֖ד תֻּמָּֽ⁠ם׃פ","wa⁠yĕdabé֣̇r mòşě֗h bĕ̇⁠ʼázĕnéy֙ ká̇l-qĕha֣l yişĕ̂ráʼé֔l ʼeţ-di̇bĕré֥y ha⁠şi̇̌yrá֖h ha⁠zò֑̇ʼţ ʻa֖d ţu̇máֽ̇⁠m׃p"],[32,1,"הַאֲזִ֥ינוּ הַ⁠שָּׁמַ֖יִם וַ⁠אֲדַבֵּ֑רָה וְ⁠תִשְׁמַ֥ע הָ⁠אָ֖רֶץ אִמְרֵי־פִֽ⁠י׃","haʼàzi֥ynẇ ha⁠şá̇̌ma֖yim wa⁠ʼàdabé֑̇ráh wĕ⁠ţişĕ̌ma֥ʻ há⁠ʼá֖reẕ ʼimĕréy-piֽ⁠y׃"],[32,2,"יַעֲרֹ֤ף כַּ⁠מָּטָר֙ לִקְחִ֔⁠י תִּזַּ֥ל כַּ⁠טַּ֖ל אִמְרָתִ֑⁠י כִּ⁠שְׂעִירִ֣ם עֲלֵי־דֶ֔שֶׁא וְ⁠כִ⁠רְבִיבִ֖ים עֲלֵי־עֵֽשֶׂב׃","yaʻàrò֤p kȧ⁠má̇tár֙ liqĕẖi֔⁠y ţi̇zȧ֥l kȧ⁠tȧ֖l ʼimĕráţi֑⁠y ki̇⁠şĕ̂ʻiyri֣m ʻàléy-de֔şěʼ wĕ⁠ki⁠rĕbiybi֖ym ʻàléy-ʻéֽşêb׃"],[32,3,"כִּ֛י שֵׁ֥ם יְהוָ֖ה אֶקְרָ֑א הָב֥וּ גֹ֖דֶל לֵ⁠אלֹהֵֽי⁠נוּ׃","ki֛̇y şé֥̌m yĕhwá֖h ʼeqĕrá֑ʼ háb֥ẇ gò֖del lé⁠ʼlòhéֽy⁠nẇ׃"],[32,4,"הַ⁠צּוּר֙ תָּמִ֣ים פָּעֳל֔⁠וֹ כִּ֥י כָל־דְּרָכָ֖י⁠ו מִשְׁפָּ֑ט אֵ֤ל אֱמוּנָה֙ וְ⁠אֵ֣ין עָ֔וֶל צַדִּ֥יק וְ⁠יָשָׁ֖ר הֽוּא׃","ha⁠ẕ̇ẇr֙ ţá̇mi֣ym pá̇ʻol֔⁠wò ki֥̇y kál-dĕ̇ráká֖y⁠w mişĕ̌pá֑̇t ʼé֤l ʼèmẇnáh֙ wĕ⁠ʼé֣yn ʻá֔wel ẕadi֥̇yq wĕ⁠yáşá֖̌r hֽẇʼ׃"],[32,5,"שִׁחֵ֥ת ל֛⁠וֹ לֹ֖א בָּנָ֣י⁠ו מוּמָ֑⁠ם דּ֥וֹר עִקֵּ֖שׁ וּ⁠פְתַלְתֹּֽל׃","şǐẖé֥ţ l֛⁠wò lò֖ʼ bá̇ná֣y⁠w mẇmá֑⁠m ḋ֥wòr ʻiqé֖̇ş̌ ẇ⁠pĕţalĕţòֽ̇l׃"],[32,6,"הֲ־לַ⁠יְהוָה֙ תִּגְמְלוּ־זֹ֔את עַ֥ם נָבָ֖ל וְ⁠לֹ֣א חָכָ֑ם הֲ⁠לוֹא־הוּא֙ אָבִ֣י⁠ךָ קָּנֶ֔⁠ךָ ה֥וּא עָֽשְׂ⁠ךָ֖ וַֽ⁠יְכֹנְנֶֽ⁠ךָ׃","hà-la⁠yĕhwáh֙ ţi̇gĕmĕlẇ-zò֔ʼţ ʻa֥m nábá֖l wĕ⁠lò֣ʼ ẖáká֑m hà⁠lwòʼ-hẇʼ֙ ʼábi֣y⁠ká qá̇ne֔⁠ká h֥ẇʼ ʻáֽşĕ̂⁠ká֖ waֽ⁠yĕkònĕneֽ⁠ká׃"],[32,7,"זְכֹר֙ יְמ֣וֹת עוֹלָ֔ם בִּ֖ינוּ שְׁנ֣וֹת דּוֹר־וָ⁠ד֑וֹר שְׁאַ֤ל אָבִ֨י⁠ךָ֙ וְ⁠יַגֵּ֔דְ⁠ךָ זְקֵנֶ֖י⁠ךָ וְ⁠יֹ֥אמְרוּ לָֽ⁠ךְ׃","zĕkòr֙ yĕm֣wòţ ʻwòlá֔m bi֖̇ynẇ şĕ̌n֣wòţ ḋwòr-wá⁠d֑wòr şĕ̌ʼa֤l ʼábi֨y⁠ká֙ wĕ⁠yagé̇֔dĕ⁠ká zĕqéne֖y⁠ká wĕ⁠yò֥ʼmĕrẇ láֽ⁠kĕ׃"],[32,8,"בְּ⁠הַנְחֵ֤ל עֶלְיוֹן֙ גּוֹיִ֔ם בְּ⁠הַפְרִיד֖⁠וֹ בְּנֵ֣י אָדָ֑ם יַצֵּב֙ גְּבֻלֹ֣ת עַמִּ֔ים לְ⁠מִסְפַּ֖ר בְּנֵ֥י יִשְׂרָאֵֽל׃","bĕ̇⁠hanĕẖé֤l ʻelĕywòn֙ ġwòyi֔m bĕ̇⁠hapĕriyd֖⁠wò bĕ̇né֣y ʼádá֑m yaẕé̇b֙ gĕ̇bulò֣ţ ʻami̇֔ym lĕ⁠misĕpȧ֖r bĕ̇né֥y yişĕ̂ráʼéֽl׃"],[32,9,"כִּ֛י חֵ֥לֶק יְהֹוָ֖ה עַמּ֑⁠וֹ יַעֲקֹ֖ב חֶ֥בֶל נַחֲלָתֽ⁠וֹ׃","ki֛̇y ẖé֥leq yĕhòwá֖h ʻaṁ֑⁠wò yaʻàqò֖b ẖe֥bel naẖàláţֽ⁠wò׃"],[32,10,"יִמְצָאֵ֨⁠הוּ֙ בְּ⁠אֶ֣רֶץ מִדְבָּ֔ר וּ⁠בְ⁠תֹ֖הוּ יְלֵ֣ל יְשִׁמֹ֑ן יְסֹֽבְבֶ֨⁠נְהוּ֙ יְב֣וֹנְנֵ֔⁠הוּ יִצְּרֶ֖⁠נְהוּ כְּ⁠אִישׁ֥וֹן עֵינֽ⁠וֹ׃","yimĕẕáʼé֨⁠hẇ֙ bĕ̇⁠ʼe֣reẕ midĕbá̇֔r ẇ⁠bĕ⁠ţò֖hẇ yĕlé֣l yĕşǐmò֑n yĕsòֽbĕbe֨⁠nĕhẇ֙ yĕb֣wònĕné֔⁠hẇ yiẕĕ̇re֖⁠nĕhẇ kĕ̇⁠ʼiyş֥̌wòn ʻéynֽ⁠wò׃"],[32,11,"כְּ⁠נֶ֨שֶׁר֙ יָעִ֣יר קִנּ֔⁠וֹ עַל־גּוֹזָלָ֖י⁠ו יְרַחֵ֑ף יִפְרֹ֤שׂ כְּנָפָי⁠ו֙ יִקָּחֵ֔⁠הוּ יִשָּׂאֵ֖⁠הוּ עַל־אֶבְרָתֽ⁠וֹ׃","kĕ̇⁠ne֨şěr֙ yáʻi֣yr qiṅ֔⁠wò ʻal-ġwòzálá֖y⁠w yĕraẖé֑p yipĕrò֤ş̂ kĕ̇nápáy⁠w֙ yiqá̇ẖé֔⁠hẇ yişá̇̂ʼé֖⁠hẇ ʻal-ʼebĕráţֽ⁠wò׃"],[32,12,"יְהוָ֖ה בָּדָ֣ד יַנְחֶ֑⁠נּוּ וְ⁠אֵ֥ין עִמּ֖⁠וֹ אֵ֥ל נֵכָֽר׃","yĕhwá֖h bá̇dá֣d yanĕẖe֑⁠ṅẇ wĕ⁠ʼé֥yn ʻiṁ֖⁠wò ʼé֥l nékáֽr׃"],[32,13,"יַרְכִּבֵ֨⁠הוּ֙ עַל־במותי אָ֔רֶץ וַ⁠יֹּאכַ֖ל תְּנוּבֹ֣ת שָׂדָ֑י וַ⁠יֵּנִקֵ֤⁠הֽוּ דְבַשׁ֙ מִ⁠סֶּ֔לַע וְ⁠שֶׁ֖מֶן מֵ⁠חַלְמִ֥ישׁ צֽוּר׃","yarĕki̇bé֨⁠hẇ֙ ʻal-bmwţy ʼá֔reẕ wa⁠yò̇ʼka֖l ţĕ̇nẇbò֣ţ şá̂dá֑y wa⁠yé̇niqé֤⁠hֽẇ dĕbaş̌֙ mi⁠sė֔laʻ wĕ⁠şě֖men mé⁠ẖalĕmi֥yş̌ ẕֽẇr׃"],[32,14,"חֶמְאַ֨ת בָּקָ֜ר וַ⁠חֲלֵ֣ב צֹ֗אן עִם־חֵ֨לֶב כָּרִ֜ים וְ⁠אֵילִ֤ים בְּנֵֽי־בָשָׁן֙ וְ⁠עַתּוּדִ֔ים עִם־חֵ֖לֶב כִּלְי֣וֹת חִטָּ֑ה וְ⁠דַם־עֵנָ֖ב תִּשְׁתֶּה־חָֽמֶר׃","ẖemĕʼa֨ţ bá̇qá֜r wa⁠ẖàlé֣b ẕò֗ʼn ʻim-ẖé֨leb ká̇ri֜ym wĕ⁠ʼéyli֤ym bĕ̇néֽy-báşá̌n֙ wĕ⁠ʻaţ̇ẇdi֔ym ʻim-ẖé֖leb ki̇lĕy֣wòţ ẖitá֑̇h wĕ⁠dam-ʻéná֖b ţi̇şĕ̌ţėh-ẖáֽmer׃"],[32,15,"וַ⁠יִּשְׁמַ֤ן יְשֻׁרוּן֙ וַ⁠יִּבְעָ֔ט שָׁמַ֖נְתָּ עָבִ֣יתָ כָּשִׂ֑יתָ וַ⁠יִּטֹּשׁ֙ אֱל֣וֹהַ עָשָׂ֔⁠הוּ וַ⁠יְנַבֵּ֖ל צ֥וּר יְשֻׁעָתֽ⁠וֹ׃","wa⁠yi̇şĕ̌ma֤n yĕşǔrẇn֙ wa⁠yi̇bĕʻá֔t şá̌ma֖nĕţá̇ ʻábi֣yţá ká̇şî֑yţá wa⁠yi̇tò̇ş̌֙ ʼèl֣wòha ʻáşá̂֔⁠hẇ wa⁠yĕnabé֖̇l ẕ֥ẇr yĕşǔʻáţֽ⁠wò׃"],[32,16,"יַקְנִאֻ֖⁠הוּ בְּ⁠זָרִ֑ים בְּ⁠תוֹעֵבֹ֖ת יַכְעִיסֻֽ⁠הוּ׃","yaqĕniʼu֖⁠hẇ bĕ̇⁠zári֑ym bĕ̇⁠ţwòʻébò֖ţ yakĕʻiysuֽ⁠hẇ׃"],[32,17,"יִזְבְּח֗וּ לַ⁠שֵּׁדִים֙ לֹ֣א אֱלֹ֔הַ אֱלֹהִ֖ים לֹ֣א יְדָע֑וּ⁠ם חֲדָשִׁים֙ מִ⁠קָּרֹ֣ב בָּ֔אוּ לֹ֥א שְׂעָר֖וּ⁠ם אֲבֹתֵי⁠כֶֽם׃","yizĕbĕ̇ẖ֗ẇ la⁠şé̇̌diym֙ lò֣ʼ ʼèlò֔ha ʼèlòhi֖ym lò֣ʼ yĕdáʻ֑ẇ⁠m ẖàdáşǐym֙ mi⁠qá̇rò֣b bá̇֔ʼẇ lò֥ʼ şĕ̂ʻár֖ẇ⁠m ʼàbòţéy⁠keֽm׃"],[32,18,"צ֥וּר יְלָדְ⁠ךָ֖ תֶּ֑שִׁי וַ⁠תִּשְׁכַּ֖ח אֵ֥ל מְחֹלְלֶֽ⁠ךָ׃","ẕ֥ẇr yĕládĕ⁠ká֖ ţė֑şǐy wa⁠ţi̇şĕ̌kȧ֖ẖ ʼé֥l mĕẖòlĕleֽ⁠ká׃"],[32,19,"וַ⁠יַּ֥רְא יְהוָ֖ה וַ⁠יִּנְאָ֑ץ מִ⁠כַּ֥עַס בָּנָ֖י⁠ו וּ⁠בְנֹתָֽי⁠ו׃","wa⁠yȧ֥rĕʼ yĕhwá֖h wa⁠yi̇nĕʼá֑ẕ mi⁠kȧ֥ʻas bá̇ná֖y⁠w ẇ⁠bĕnòţáֽy⁠w׃"],[32,20,"וַ⁠יֹּ֗אמֶר אַסְתִּ֤ירָה פָנַ⁠י֙ מֵ⁠הֶ֔ם אֶרְאֶ֖ה מָ֣ה אַחֲרִיתָ֑⁠ם כִּ֣י ד֤וֹר תַּהְפֻּכֹת֙ הֵ֔מָּה בָּנִ֖ים לֹא־אֵמֻ֥ן בָּֽ⁠ם׃","wa⁠yò̇֗ʼmer ʼasĕţi֤̇yráh pána⁠y֙ mé⁠he֔m ʼerĕʼe֖h má֣h ʼaẖàriyţá֑⁠m ki֣̇y d֤wòr ţȧhĕpu̇kòţ֙ hé֔má̇h bá̇ni֖ym lòʼ-ʼému֥n báֽ̇⁠m׃"],[32,21,"הֵ֚ם קִנְא֣וּ⁠נִי בְ⁠לֹא־אֵ֔ל כִּעֲס֖וּ⁠נִי בְּ⁠הַבְלֵי⁠הֶ֑ם וַ⁠אֲנִי֙ אַקְנִיאֵ֣⁠ם בְּ⁠לֹא־עָ֔ם בְּ⁠ג֥וֹי נָבָ֖ל אַכְעִיסֵֽ⁠ם׃","hé֚m qinĕʼ֣ẇ⁠niy bĕ⁠lòʼ-ʼé֔l ki̇ʻàs֖ẇ⁠niy bĕ̇⁠habĕléy⁠he֑m wa⁠ʼàniy֙ ʼaqĕniyʼé֣⁠m bĕ̇⁠lòʼ-ʻá֔m bĕ̇⁠g֥wòy nábá֖l ʼakĕʻiyséֽ⁠m׃"],[32,22,"כִּי־אֵשׁ֙ קָדְחָ֣ה בְ⁠אַפִּ֔⁠י וַ⁠תִּיקַ֖ד עַד־שְׁא֣וֹל תַּחְתִּ֑ית וַ⁠תֹּ֤אכַל אֶ֨רֶץ֙ וִֽ⁠יבֻלָ֔⁠הּ וַ⁠תְּלַהֵ֖ט מוֹסְדֵ֥י הָרִֽים׃","ki̇y-ʼéş̌֙ qádĕẖá֣h bĕ⁠ʼapi̇֔⁠y wa⁠ţi̇yqa֖d ʻad-şĕ̌ʼ֣wòl ţȧẖĕţi֑̇yţ wa⁠ţò֤̇ʼkal ʼe֨reẕ֙ wiֽ⁠ybulá֔⁠ḣ wa⁠ţĕ̇lahé֖t mwòsĕdé֥y háriֽym׃"],[32,23,"אַסְפֶּ֥ה עָלֵ֖י⁠מוֹ רָע֑וֹת חִצַּ֖⁠י אֲכַלֶּה־בָּֽ⁠ם׃","ʼasĕpė֥h ʻálé֖y⁠mwò ráʻ֑wòţ ẖiẕȧ֖⁠y ʼàkalėh-báֽ̇⁠m׃"],[32,24,"מְזֵ֥י רָעָ֛ב וּ⁠לְחֻ֥מֵי רֶ֖שֶׁף וְ⁠קֶ֣טֶב מְרִירִ֑י וְ⁠שֶׁן־בְּהֵמוֹת֙ אֲשַׁלַּח־בָּ֔⁠ם עִם־חֲמַ֖ת זֹחֲלֵ֥י עָפָֽר׃","mĕzé֥y ráʻá֛b ẇ⁠lĕẖu֥méy re֖şěp wĕ⁠qe֣teb mĕriyri֑y wĕ⁠şěn-bĕ̇hémwòţ֙ ʼàşǎlȧẖ-bá̇֔⁠m ʻim-ẖàma֖ţ zòẖàlé֥y ʻápáֽr׃"],[32,25,"מִ⁠חוּץ֙ תְּשַׁכֶּל־חֶ֔רֶב וּ⁠מֵ⁠חֲדָרִ֖ים אֵימָ֑ה גַּם־בָּחוּר֙ גַּם־בְּתוּלָ֔ה יוֹנֵ֖ק עִם־אִ֥ישׁ שֵׂיבָֽה׃","mi⁠ẖẇẕ֙ ţĕ̇şǎkėl-ẖe֔reb ẇ⁠mé⁠ẖàdári֖ym ʼéymá֑h gȧm-bá̇ẖẇr֙ gȧm-bĕ̇ţẇlá֔h ywòné֖q ʻim-ʼi֥yş̌ şé̂ybáֽh׃"],[32,26,"אָמַ֖רְתִּי אַפְאֵי⁠הֶ֑ם אַשְׁבִּ֥יתָה מֵ⁠אֱנ֖וֹשׁ זִכְרָֽ⁠ם׃","ʼáma֖rĕţi̇y ʼapĕʼéy⁠he֑m ʼaşĕ̌bi֥̇yţáh mé⁠ʼèn֖wòş̌ zikĕráֽ⁠m׃"],[32,27,"לוּלֵ֗י כַּ֤עַס אוֹיֵב֙ אָג֔וּר פֶּֽן־יְנַכְּר֖וּ צָרֵ֑י⁠מוֹ פֶּן־יֹֽאמְרוּ֙ יָדֵ֣י⁠נוּ רָ֔מָה וְ⁠לֹ֥א יְהוָ֖ה פָּעַ֥ל כָּל־זֹֽאת׃","lẇlé֗y kȧ֤ʻas ʼwòyéb֙ ʼág֔ẇr pėֽn-yĕnakĕ̇r֖ẇ ẕáré֑y⁠mwò pėn-yòֽʼmĕrẇ֙ yádé֣y⁠nẇ rá֔máh wĕ⁠lò֥ʼ yĕhwá֖h pá̇ʻa֥l ká̇l-zòֽʼţ׃"],[32,28,"כִּי־ג֛וֹי אֹבַ֥ד עֵצ֖וֹת הֵ֑מָּה וְ⁠אֵ֥ין בָּ⁠הֶ֖ם תְּבוּנָֽה׃","ki̇y-g֛wòy ʼòba֥d ʻéẕ֖wòţ hé֑má̇h wĕ⁠ʼé֥yn bá̇⁠he֖m ţĕ̇bẇnáֽh׃"],[32,29,"ל֥וּ חָכְמ֖וּ יַשְׂכִּ֣ילוּ זֹ֑את יָבִ֖ינוּ לְ⁠אַחֲרִיתָֽ⁠ם׃","l֥ẇ ẖákĕm֖ẇ yaşĕ̂ki֣̇ylẇ zò֑ʼţ yábi֖ynẇ lĕ⁠ʼaẖàriyţáֽ⁠m׃"],[32,30,"אֵיכָ֞ה יִרְדֹּ֤ף אֶחָד֙ אֶ֔לֶף וּ⁠שְׁנַ֖יִם יָנִ֣יסוּ רְבָבָ֑ה אִם־לֹא֙ כִּי־צוּרָ֣⁠ם מְכָרָ֔⁠ם וַֽ⁠יהוָ֖ה הִסְגִּירָֽ⁠ם׃","ʼéyká֞h yirĕdò֤̇p ʼeẖád֙ ʼe֔lep ẇ⁠şĕ̌na֖yim yáni֣ysẇ rĕbábá֑h ʼim-lòʼ֙ ki̇y-ẕẇrá֣⁠m mĕkárá֔⁠m waֽ⁠yhwá֖h hisĕgi̇yráֽ⁠m׃"],[32,31,"כִּ֛י לֹ֥א כְ⁠צוּרֵ֖⁠נוּ צוּרָ֑⁠ם וְ⁠אֹיְבֵ֖י⁠נוּ פְּלִילִֽים׃","ki֛̇y lò֥ʼ kĕ⁠ẕẇré֖⁠nẇ ẕẇrá֑⁠m wĕ⁠ʼòyĕbé֖y⁠nẇ pĕ̇liyliֽym׃"],[32,32,"כִּֽי־מִ⁠גֶּ֤פֶן סְדֹם֙ גַּפְנָ֔⁠ם וּ⁠מִ⁠שַּׁדְמֹ֖ת עֲמֹרָ֑ה עֲנָבֵ֨⁠מוֹ֙ עִנְּבֵי־ר֔וֹשׁ אַשְׁכְּלֹ֥ת מְרֹרֹ֖ת לָֽ⁠מוֹ׃","kiֽ̇y-mi⁠gė֤pen sĕdòm֙ gȧpĕná֔⁠m ẇ⁠mi⁠şȧ̌dĕmò֖ţ ʻàmòrá֑h ʻànábé֨⁠mwò֙ ʻinĕ̇béy-r֔wòş̌ ʼaşĕ̌kĕ̇lò֥ţ mĕròrò֖ţ láֽ⁠mwò׃"],[32,33,"חֲמַ֥ת תַּנִּינִ֖ם יֵינָ֑⁠ם וְ⁠רֹ֥אשׁ פְּתָנִ֖ים אַכְזָֽר׃","ẖàma֥ţ ţȧni̇yni֖m yéyná֑⁠m wĕ⁠rò֥ʼş̌ pĕ̇ţáni֖ym ʼakĕzáֽr׃"],[32,34,"הֲ⁠לֹא־ה֖וּא כָּמֻ֣ס עִמָּ⁠דִ֑י חָתֻ֖ם בְּ⁠אוֹצְרֹתָֽ⁠י׃","hà⁠lòʼ-h֖ẇʼ ká̇mu֣s ʻimá̇⁠di֑y ẖáţu֖m bĕ̇⁠ʼwòẕĕròţáֽ⁠y׃"],[32,35,"לִ֤⁠י נָקָם֙ וְ⁠שִׁלֵּ֔ם לְ⁠עֵ֖ת תָּמ֣וּט רַגְלָ֑⁠ם כִּ֤י קָרוֹב֙ י֣וֹם אֵידָ֔⁠ם וְ⁠חָ֖שׁ עֲתִדֹ֥ת לָֽ⁠מוֹ׃","li֤⁠y náqám֙ wĕ⁠şǐlé̇֔m lĕ⁠ʻé֖ţ ţá̇m֣ẇt ragĕlá֑⁠m ki֤̇y qárwòb֙ y֣wòm ʼéydá֔⁠m wĕ⁠ẖá֖ş̌ ʻàţidò֥ţ láֽ⁠mwò׃"],[32,36,"כִּֽי־יָדִ֤ין יְהוָה֙ עַמּ֔⁠וֹ וְ⁠עַל־עֲבָדָ֖י⁠ו יִתְנֶחָ֑ם כִּ֤י יִרְאֶה֙ כִּי־אָ֣זְלַת יָ֔ד וְ⁠אֶ֖פֶס עָצ֥וּר וְ⁠עָזֽוּב׃","kiֽ̇y-yádi֤yn yĕhwáh֙ ʻaṁ֔⁠wò wĕ⁠ʻal-ʻàbádá֖y⁠w yiţĕneẖá֑m ki֤̇y yirĕʼeh֙ ki̇y-ʼá֣zĕlaţ yá֔d wĕ⁠ʼe֖pes ʻáẕ֥ẇr wĕ⁠ʻázֽẇb׃"],[32,37,"וְ⁠אָמַ֖ר אֵ֣י אֱלֹהֵ֑י⁠מוֹ צ֖וּר חָסָ֥יוּ בֽ⁠וֹ׃","wĕ⁠ʼáma֖r ʼé֣y ʼèlòhé֑y⁠mwò ẕ֖ẇr ẖásá֥yẇ bֽ⁠wò׃"],[32,38,"אֲשֶׁ֨ר חֵ֤לֶב זְבָחֵ֨י⁠מוֹ֙ יֹאכֵ֔לוּ יִשְׁתּ֖וּ יֵ֣ין נְסִיכָ֑⁠ם יָק֨וּמוּ֙ וְ⁠יַעְזְרֻ⁠כֶ֔ם יְהִ֥י עֲלֵי⁠כֶ֖ם סִתְרָֽה׃","ʼàşě֨r ẖé֤leb zĕbáẖé֨y⁠mwò֙ yòʼké֔lẇ yişĕ̌ţ֖̇ẇ yé֣yn nĕsiyká֑⁠m yáq֨ẇmẇ֙ wĕ⁠yaʻĕzĕru⁠ke֔m yĕhi֥y ʻàléy⁠ke֖m siţĕráֽh׃"],[32,39,"רְא֣וּ ׀ עַתָּ֗ה כִּ֣י אֲנִ֤י אֲנִי֙ ה֔וּא וְ⁠אֵ֥ין אֱלֹהִ֖ים עִמָּ⁠דִ֑י אֲנִ֧י אָמִ֣ית וַ⁠אֲחַיֶּ֗ה מָחַ֨צְתִּי֙ וַ⁠אֲנִ֣י אֶרְפָּ֔א וְ⁠אֵ֥ין מִ⁠יָּדִ֖⁠י מַצִּֽיל׃","rĕʼ֣ẇ ׀ ʻaţá̇֗h ki֣̇y ʼàni֤y ʼàniy֙ h֔ẇʼ wĕ⁠ʼé֥yn ʼèlòhi֖ym ʻimá̇⁠di֑y ʼàni֧y ʼámi֣yţ wa⁠ʼàẖayė֗h máẖa֨ẕĕţi̇y֙ wa⁠ʼàni֣y ʼerĕpá̇֔ʼ wĕ⁠ʼé֥yn mi⁠yá̇di֖⁠y maẕiֽ̇yl׃"],[32,40,"כִּֽי־אֶשָּׂ֥א אֶל־שָׁמַ֖יִם יָדִ֑⁠י וְ⁠אָמַ֕רְתִּי חַ֥י אָנֹכִ֖י לְ⁠עֹלָֽם׃","kiֽ̇y-ʼeşá֥̇̂ʼ ʼel-şá̌ma֖yim yádi֑⁠y wĕ⁠ʼáma֕rĕţi̇y ẖa֥y ʼánòki֖y lĕ⁠ʻòláֽm׃"],[32,41,"אִם־שַׁנּוֹתִי֙ בְּרַ֣ק חַרְבִּ֔⁠י וְ⁠תֹאחֵ֥ז בְּ⁠מִשְׁפָּ֖ט יָדִ֑⁠י אָשִׁ֤יב נָקָם֙ לְ⁠צָרָ֔⁠י וְ⁠לִ⁠מְשַׂנְאַ֖⁠י אֲשַׁלֵּֽם׃","ʼim-şǎṅwòţiy֙ bĕ̇ra֣q ẖarĕbi̇֔⁠y wĕ⁠ţòʼẖé֥z bĕ̇⁠mişĕ̌pá֖̇t yádi֑⁠y ʼáşǐ֤yb náqám֙ lĕ⁠ẕárá֔⁠y wĕ⁠li⁠mĕşânĕʼa֖⁠y ʼàşǎléֽ̇m׃"],[32,42,"אַשְׁכִּ֤יר חִצַּ⁠י֙ מִ⁠דָּ֔ם וְ⁠חַרְבִּ֖⁠י תֹּאכַ֣ל בָּשָׂ֑ר מִ⁠דַּ֤ם חָלָל֙ וְ⁠שִׁבְיָ֔ה מֵ⁠רֹ֖אשׁ פַּרְע֥וֹת אוֹיֵֽב׃","ʼaşĕ̌ki֤̇yr ẖiẕȧ⁠y֙ mi⁠dá̇֔m wĕ⁠ẖarĕbi֖̇⁠y ţò̇ʼka֣l bá̇şá֑̂r mi⁠dȧ֤m ẖálál֙ wĕ⁠şǐbĕyá֔h mé⁠rò֖ʼş̌ pȧrĕʻ֥wòţ ʼwòyéֽb׃"],[32,43,"הַרְנִ֤ינוּ גוֹיִם֙ עַמּ֔⁠וֹ כִּ֥י דַם־עֲבָדָ֖י⁠ו יִקּ֑וֹם וְ⁠נָקָם֙ יָשִׁ֣יב לְ⁠צָרָ֔י⁠ו וְ⁠כִפֶּ֥ר אַדְמָת֖⁠וֹ עַמּֽ⁠וֹ׃פ","harĕni֤ynẇ gwòyim֙ ʻaṁ֔⁠wò ki֥̇y dam-ʻàbádá֖y⁠w yiq֑̇wòm wĕ⁠náqám֙ yáşǐ֣yb lĕ⁠ẕárá֔y⁠w wĕ⁠kipė֥r ʼadĕmáţ֖⁠wò ʻaṁֽ⁠wò׃p"],[32,44,"וַ⁠יָּבֹ֣א מֹשֶׁ֗ה וַ⁠יְדַבֵּ֛ר אֶת־כָּל־דִּבְרֵ֥י הַ⁠שִּׁירָֽה־הַ⁠זֹּ֖את בְּ⁠אָזְנֵ֣י הָ⁠עָ֑ם ה֖וּא וְ⁠הוֹשֵׁ֥עַ בִּן־נֽוּן׃","wa⁠yá̇bò֣ʼ mòşě֗h wa⁠yĕdabé֛̇r ʼeţ-ká̇l-di̇bĕré֥y ha⁠şi̇̌yráֽh-ha⁠zò֖̇ʼţ bĕ̇⁠ʼázĕné֣y há⁠ʻá֑m h֖ẇʼ wĕ⁠hwòşé֥̌ʻa bi̇n-nֽẇn׃"],[32,45,"וַ⁠יְכַ֣ל מֹשֶׁ֗ה לְ⁠דַבֵּ֛ר אֶת־כָּל־הַ⁠דְּבָרִ֥ים הָ⁠אֵ֖לֶּה אֶל־כָּל־יִשְׂרָאֵֽל׃","wa⁠yĕka֣l mòşě֗h lĕ⁠dabé֛̇r ʼeţ-ká̇l-ha⁠dĕ̇bári֥ym há⁠ʼé֖lėh ʼel-ká̇l-yişĕ̂ráʼéֽl׃"],[32,46,"וַ⁠יֹּ֤אמֶר אֲלֵ⁠הֶם֙ שִׂ֣ימוּ לְבַבְ⁠כֶ֔ם לְ⁠כָל־הַ⁠דְּבָרִ֔ים אֲשֶׁ֧ר אָנֹכִ֛י מֵעִ֥יד בָּ⁠כֶ֖ם הַ⁠יּ֑וֹם אֲשֶׁ֤ר תְּצַוֻּ⁠ם֙ אֶת־בְּנֵי⁠כֶ֔ם לִ⁠שְׁמֹ֣ר לַ⁠עֲשׂ֔וֹת אֶת־כָּל־דִּבְרֵ֖י הַ⁠תּוֹרָ֥ה הַ⁠זֹּֽאת׃","wa⁠yò֤̇ʼmer ʼàlé⁠hem֙ şî֣ymẇ lĕbabĕ⁠ke֔m lĕ⁠kál-ha⁠dĕ̇bári֔ym ʼàşě֧r ʼánòki֛y méʻi֥yd bá̇⁠ke֖m ha⁠ẏ֑wòm ʼàşě֤r ţĕ̇ẕawu̇⁠m֙ ʼeţ-bĕ̇néy⁠ke֔m li⁠şĕ̌mò֣r la⁠ʻàş̂֔wòţ ʼeţ-ká̇l-di̇bĕré֖y ha⁠ţ̇wòrá֥h ha⁠zòֽ̇ʼţ׃"],[32,47,"כִּ֠י לֹֽא־דָבָ֨ר רֵ֥ק הוּא֙ מִ⁠כֶּ֔ם כִּי־ה֖וּא חַיֵּי⁠כֶ֑ם וּ⁠בַ⁠דָּבָ֣ר הַ⁠זֶּ֗ה תַּאֲרִ֤יכוּ יָמִים֙ עַל־הָ֣⁠אֲדָמָ֔ה אֲשֶׁ֨ר אַתֶּ֜ם עֹבְרִ֧ים אֶת־הַ⁠יַּרְדֵּ֛ן שָׁ֖מָּ⁠ה לְ⁠רִשְׁתָּֽ⁠הּ׃פ","ki̇֠y lòֽʼ-dábá֨r ré֥q hẇʼ֙ mi⁠kė֔m ki̇y-h֖ẇʼ ẖayé̇y⁠ke֑m ẇ⁠ba⁠dá̇bá֣r ha⁠zė֗h ţȧʼàri֤ykẇ yámiym֙ ʻal-há֣⁠ʼàdámá֔h ʼàşě֨r ʼaţė֜m ʻòbĕri֧ym ʼeţ-ha⁠yȧrĕdé֛̇n şá֖̌má̇⁠h lĕ⁠rişĕ̌ţáֽ̇⁠ḣ׃p"],[32,48,"וַ⁠יְדַבֵּ֤ר יְהוָה֙ אֶל־מֹשֶׁ֔ה בְּ⁠עֶ֛צֶם הַ⁠יּ֥וֹם הַ⁠זֶּ֖ה לֵ⁠אמֹֽר׃","wa⁠yĕdabé֤̇r yĕhwáh֙ ʼel-mòşě֔h bĕ̇⁠ʻe֛ẕem ha⁠ẏ֥wòm ha⁠zė֖h lé⁠ʼmòֽr׃"],[32,49,"עֲלֵ֡ה אֶל־הַר֩ הָ⁠עֲבָרִ֨ים הַ⁠זֶּ֜ה הַר־נְב֗וֹ אֲשֶׁר֙ בְּ⁠אֶ֣רֶץ מוֹאָ֔ב אֲשֶׁ֖ר עַל־פְּנֵ֣י יְרֵח֑וֹ וּ⁠רְאֵה֙ אֶת־אֶ֣רֶץ כְּנַ֔עַן אֲשֶׁ֨ר אֲנִ֥י נֹתֵ֛ן לִ⁠בְנֵ֥י יִשְׂרָאֵ֖ל לַ⁠אֲחֻזָּֽה׃","ʻàlé֡h ʼel-har֩ há⁠ʻàbári֨ym ha⁠zė֜h har-nĕb֗wò ʼàşěr֙ bĕ̇⁠ʼe֣reẕ mwòʼá֔b ʼàşě֖r ʻal-pĕ̇né֣y yĕréẖ֑wò ẇ⁠rĕʼéh֙ ʼeţ-ʼe֣reẕ kĕ̇na֔ʻan ʼàşě֨r ʼàni֥y nòţé֛n li⁠bĕné֥y yişĕ̂ráʼé֖l la⁠ʼàẖuzáֽ̇h׃"],[32,50,"וּ⁠מֻ֗ת בָּ⁠הָר֙ אֲשֶׁ֤ר אַתָּה֙ עֹלֶ֣ה שָׁ֔מָּ⁠ה וְ⁠הֵאָסֵ֖ף אֶל־עַמֶּ֑י⁠ךָ כַּֽ⁠אֲשֶׁר־מֵ֞ת אַהֲרֹ֤ן אָחִ֨י⁠ךָ֙ בְּ⁠הֹ֣ר הָ⁠הָ֔ר וַ⁠יֵּאָ֖סֶף אֶל־עַמָּֽי⁠ו׃","ẇ⁠mu֗ţ bá̇⁠hár֙ ʼàşě֤r ʼaţá̇h֙ ʻòle֣h şá̌֔má̇⁠h wĕ⁠héʼásé֖p ʼel-ʻamė֑y⁠ká kȧֽ⁠ʼàşěr-mé֞ţ ʼahàrò֤n ʼáẖi֨y⁠ká֙ bĕ̇⁠hò֣r há⁠há֔r wa⁠yé̇ʼá֖sep ʼel-ʻamáֽ̇y⁠w׃"],[32,51,"עַל֩ אֲשֶׁ֨ר מְעַלְתֶּ֜ם בִּ֗⁠י בְּ⁠תוֹךְ֙ בְּנֵ֣י יִשְׂרָאֵ֔ל בְּ⁠מֵֽי־מְרִיבַ֥ת קָדֵ֖שׁ מִדְבַּר־צִ֑ן עַ֣ל אֲשֶׁ֤ר לֹֽא־קִדַּשְׁתֶּם֙ אוֹתִ֔⁠י בְּ⁠ת֖וֹךְ בְּנֵ֥י יִשְׂרָאֵֽל׃","ʻal֩ ʼàşě֨r mĕʻalĕţė֜m bi̇֗⁠y bĕ̇⁠ţwòkĕ֙ bĕ̇né֣y yişĕ̂ráʼé֔l bĕ̇⁠méֽy-mĕriyba֥ţ qádé֖ş̌ midĕbȧr-ẕi֑n ʻa֣l ʼàşě֤r lòֽʼ-qidȧşĕ̌ţėm֙ ʼwòţi֔⁠y bĕ̇⁠ţ֖wòkĕ bĕ̇né֥y yişĕ̂ráʼéֽl׃"],[32,52,"כִּ֥י מִ⁠נֶּ֖גֶד תִּרְאֶ֣ה אֶת־הָ⁠אָ֑רֶץ וְ⁠שָׁ֨מָּ⁠ה֙ לֹ֣א תָב֔וֹא אֶל־הָ⁠אָ֕רֶץ אֲשֶׁר־אֲנִ֥י נֹתֵ֖ן לִ⁠בְנֵ֥י יִשְׂרָאֵֽל׃פ","ki֥̇y mi⁠nė֖ged ţi̇rĕʼe֣h ʼeţ-há⁠ʼá֑reẕ wĕ⁠şá̌֨má̇⁠h֙ lò֣ʼ ţáb֔wòʼ ʼel-há⁠ʼá֕reẕ ʼàşěr-ʼàni֥y nòţé֖n li⁠bĕné֥y yişĕ̂ráʼéֽl׃p"],[33,1,"וְ⁠זֹ֣את הַ⁠בְּרָכָ֗ה אֲשֶׁ֨ר בֵּרַ֥ךְ מֹשֶׁ֛ה אִ֥ישׁ הָ⁠אֱלֹהִ֖ים אֶת־בְּנֵ֣י יִשְׂרָאֵ֑ל לִ⁠פְנֵ֖י מוֹתֽ⁠וֹ׃","wĕ⁠zò֣ʼţ ha⁠bĕ̇ráká֗h ʼàşě֨r bé̇ra֥kĕ mòşě֛h ʼi֥yş̌ há⁠ʼèlòhi֖ym ʼeţ-bĕ̇né֣y yişĕ̂ráʼé֑l li⁠pĕné֖y mwòţֽ⁠wò׃"],[33,2,"וַ⁠יֹּאמַ֗ר יְהוָ֞ה מִ⁠סִּינַ֥י בָּא֙ וְ⁠זָרַ֤ח מִ⁠שֵּׂעִיר֙ לָ֔⁠מוֹ הוֹפִ֨יעַ֙ מֵ⁠הַ֣ר פָּארָ֔ן וְ⁠אָתָ֖ה מֵ⁠רִבְבֹ֣ת קֹ֑דֶשׁ מִֽ⁠ימִינ֕⁠וֹ אשדת לָֽ⁠מוֹ׃","wa⁠yò̇ʼma֗r yĕhwá֞h mi⁠si̇yna֥y bá̇ʼ֙ wĕ⁠zára֤ẖ mi⁠şé̇̂ʻiyr֙ lá֔⁠mwò hwòpi֨yʻa֙ mé⁠ha֣r pá̇ʼrá֔n wĕ⁠ʼáţá֖h mé⁠ribĕbò֣ţ qò֑deş̌ miֽ⁠ymiyn֕⁠wò ʼşdţ láֽ⁠mwò׃"],[33,3,"אַ֚ף חֹבֵ֣ב עַמִּ֔ים כָּל־קְדֹשָׁ֖י⁠ו בְּ⁠יָדֶ֑⁠ךָ וְ⁠הֵם֙ תֻּכּ֣וּ לְ⁠רַגְלֶ֔⁠ךָ יִשָּׂ֖א מִ⁠דַּבְּרֹתֶֽי⁠ךָ׃","ʼa֚p ẖòbé֣b ʻami̇֔ym ká̇l-qĕdòşá֖̌y⁠w bĕ̇⁠yáde֑⁠ká wĕ⁠hém֙ ţu̇k֣̇ẇ lĕ⁠ragĕle֔⁠ká yişá֖̇̂ʼ mi⁠dȧbĕ̇ròţeֽy⁠ká׃"],[33,4,"תּוֹרָ֥ה צִוָּה־לָ֖⁠נוּ מֹשֶׁ֑ה מוֹרָשָׁ֖ה קְהִלַּ֥ת יַעֲקֹֽב׃","ţ̇wòrá֥h ẕiwá̇h-lá֖⁠nẇ mòşě֑h mwòráşá֖̌h qĕhilȧ֥ţ yaʻàqòֽb׃"],[33,5,"וַ⁠יְהִ֥י בִ⁠ישֻׁר֖וּן מֶ֑לֶךְ בְּ⁠הִתְאַסֵּף֙ רָ֣אשֵׁי עָ֔ם יַ֖חַד שִׁבְטֵ֥י יִשְׂרָאֵֽל׃","wa⁠yĕhi֥y bi⁠yşǔr֖ẇn me֑lekĕ bĕ̇⁠hiţĕʼasé̇p֙ rá֣ʼşé̌y ʻá֔m ya֖ẖad şǐbĕté֥y yişĕ̂ráʼéֽl׃"],[33,6,"יְחִ֥י רְאוּבֵ֖ן וְ⁠אַל־יָמֹ֑ת וִ⁠יהִ֥י מְתָ֖י⁠ו מִסְפָּֽר׃ס","yĕẖi֥y rĕʼẇbé֖n wĕ⁠ʼal-yámò֑ţ wi⁠yhi֥y mĕţá֖y⁠w misĕpáֽ̇r׃s"],[33,7,"וְ⁠זֹ֣את לִֽ⁠יהוּדָה֮ וַ⁠יֹּאמַר֒ שְׁמַ֤ע יְהוָה֙ ק֣וֹל יְהוּדָ֔ה וְ⁠אֶל־עַמּ֖⁠וֹ תְּבִיאֶ֑⁠נּוּ יָדָי⁠ו֙ רָ֣ב ל֔⁠וֹ וְ⁠עֵ֥זֶר מִ⁠צָּרָ֖י⁠ו תִּהְיֶֽה׃ס","wĕ⁠zò֣ʼţ liֽ⁠yhẇdáh֮ wa⁠yò̇ʼmar֒ şĕ̌ma֤ʻ yĕhwáh֙ q֣wòl yĕhẇdá֔h wĕ⁠ʼel-ʻaṁ֖⁠wò ţĕ̇biyʼe֑⁠ṅẇ yádáy⁠w֙ rá֣b l֔⁠wò wĕ⁠ʻé֥zer mi⁠ẕá̇rá֖y⁠w ţi̇hĕyeֽh׃s"],[33,8,"וּ⁠לְ⁠לֵוִ֣י אָמַ֔ר תֻּמֶּ֥י⁠ךָ וְ⁠אוּרֶ֖י⁠ךָ לְ⁠אִ֣ישׁ חֲסִידֶ֑⁠ךָ אֲשֶׁ֤ר נִסִּית⁠וֹ֙ בְּ⁠מַסָּ֔ה תְּרִיבֵ֖⁠הוּ עַל־מֵ֥י מְרִיבָֽה׃","ẇ⁠lĕ⁠léwi֣y ʼáma֔r ţu̇mė֥y⁠ká wĕ⁠ʼẇre֖y⁠ká lĕ⁠ʼi֣yş̌ ẖàsiyde֑⁠ká ʼàşě֤r nisi̇yţ⁠wò֙ bĕ̇⁠masá̇֔h ţĕ̇riybé֖⁠hẇ ʻal-mé֥y mĕriybáֽh׃"],[33,9,"הָ⁠אֹמֵ֞ר לְ⁠אָבִ֤י⁠ו וּ⁠לְ⁠אִמּ⁠וֹ֙ לֹ֣א רְאִיתִ֔י⁠ו וְ⁠אֶת־אֶחָי⁠ו֙ לֹ֣א הִכִּ֔יר וְ⁠אֶת־בנ⁠ו לֹ֣א יָדָ֑ע כִּ֤י שָֽׁמְרוּ֙ אִמְרָתֶ֔⁠ךָ וּ⁠בְרִֽיתְ⁠ךָ֖ יִנְצֹֽרוּ׃","há⁠ʼòmé֞r lĕ⁠ʼábi֤y⁠w ẇ⁠lĕ⁠ʼiṁ⁠wò֙ lò֣ʼ rĕʼiyţi֔y⁠w wĕ⁠ʼeţ-ʼeẖáy⁠w֙ lò֣ʼ hiki̇֔yr wĕ⁠ʼeţ-bn⁠w lò֣ʼ yádá֑ʻ ki֤̇y şáֽ̌mĕrẇ֙ ʼimĕráţe֔⁠ká ẇ⁠bĕriֽyţĕ⁠ká֖ yinĕẕòֽrẇ׃"],[33,10,"יוֹר֤וּ מִשְׁפָּטֶ֨י⁠ךָ֙ לְ⁠יַעֲקֹ֔ב וְ⁠תוֹרָתְ⁠ךָ֖ לְ⁠יִשְׂרָאֵ֑ל יָשִׂ֤ימוּ קְטוֹרָה֙ בְּ⁠אַפֶּ֔⁠ךָ וְ⁠כָלִ֖יל עַֽל־מִזְבְּחֶֽ⁠ךָ׃","ywòr֤ẇ mişĕ̌pá̇te֨y⁠ká֙ lĕ⁠yaʻàqò֔b wĕ⁠ţwòráţĕ⁠ká֖ lĕ⁠yişĕ̂ráʼé֑l yáşî֤ymẇ qĕtwòráh֙ bĕ̇⁠ʼapė֔⁠ká wĕ⁠káli֖yl ʻaֽl-mizĕbĕ̇ẖeֽ⁠ká׃"],[33,11,"בָּרֵ֤ךְ יְהוָה֙ חֵיל֔⁠וֹ וּ⁠פֹ֥עַל יָדָ֖י⁠ו תִּרְצֶ֑ה מְחַ֨ץ מָתְנַ֧יִם קָמָ֛י⁠ו וּ⁠מְשַׂנְאָ֖י⁠ו מִן־יְקוּמֽוּ⁠ן׃ס","bá̇ré֤kĕ yĕhwáh֙ ẖéyl֔⁠wò ẇ⁠pò֥ʻal yádá֖y⁠w ţi̇rĕẕe֑h mĕẖa֨ẕ máţĕna֧yim qámá֛y⁠w ẇ⁠mĕşânĕʼá֖y⁠w min-yĕqẇmֽẇ⁠n׃s"],[33,12,"לְ⁠בִנְיָמִ֣ן אָמַ֔ר יְדִ֣יד יְהֹוָ֔ה יִשְׁכֹּ֥ן לָ⁠בֶ֖טַח עָלָ֑י⁠ו חֹפֵ֤ף עָלָי⁠ו֙ כָּל־הַ⁠יּ֔וֹם וּ⁠בֵ֥ין כְּתֵיפָ֖י⁠ו שָׁכֵֽן׃ס","lĕ⁠binĕyámi֣n ʼáma֔r yĕdi֣yd yĕhòwá֔h yişĕ̌kò֥̇n lá⁠be֖taẖ ʻálá֑y⁠w ẖòpé֤p ʻáláy⁠w֙ ká̇l-ha⁠ẏ֔wòm ẇ⁠bé֥yn kĕ̇ţéypá֖y⁠w şá̌kéֽn׃s"],[33,13,"וּ⁠לְ⁠יוֹסֵ֣ף אָמַ֔ר מְבֹרֶ֥כֶת יְהֹוָ֖ה אַרְצ֑⁠וֹ מִ⁠מֶּ֤גֶד שָׁמַ֨יִם֙ מִ⁠טָּ֔ל וּ⁠מִ⁠תְּה֖וֹם רֹבֶ֥צֶת תָּֽחַת׃","ẇ⁠lĕ⁠ywòsé֣p ʼáma֔r mĕbòre֥keţ yĕhòwá֖h ʼarĕẕ֑⁠wò mi⁠mė֤ged şá̌ma֨yim֙ mi⁠tá̇֔l ẇ⁠mi⁠ţĕ̇h֖wòm ròbe֥ẕeţ ţáֽ̇ẖaţ׃"],[33,14,"וּ⁠מִ⁠מֶּ֖גֶד תְּבוּאֹ֣ת שָׁ֑מֶשׁ וּ⁠מִ⁠מֶּ֖גֶד גֶּ֥רֶשׁ יְרָחִֽים׃","ẇ⁠mi⁠mė֖ged ţĕ̇bẇʼò֣ţ şá֑̌meş̌ ẇ⁠mi⁠mė֖ged gė֥reş̌ yĕráẖiֽym׃"],[33,15,"וּ⁠מֵ⁠רֹ֖אשׁ הַרְרֵי־קֶ֑דֶם וּ⁠מִ⁠מֶּ֖גֶד גִּבְע֥וֹת עוֹלָֽם׃","ẇ⁠mé⁠rò֖ʼş̌ harĕréy-qe֑dem ẇ⁠mi⁠mė֖ged gi̇bĕʻ֥wòţ ʻwòláֽm׃"],[33,16,"וּ⁠מִ⁠מֶּ֗גֶד אֶ֚רֶץ וּ⁠מְלֹאָ֔⁠הּ וּ⁠רְצ֥וֹן שֹׁכְנִ֖י סְנֶ֑ה תָּב֨וֹאתָ⁠ה֙ לְ⁠רֹ֣אשׁ יוֹסֵ֔ף וּ⁠לְ⁠קָדְקֹ֖ד נְזִ֥יר אֶחָֽי⁠ו׃","ẇ⁠mi⁠mė֗ged ʼe֚reẕ ẇ⁠mĕlòʼá֔⁠ḣ ẇ⁠rĕẕ֥wòn şò̌kĕni֖y sĕne֑h ţá̇b֨wòʼţá⁠h֙ lĕ⁠rò֣ʼş̌ ywòsé֔p ẇ⁠lĕ⁠qádĕqò֖d nĕzi֥yr ʼeẖáֽy⁠w׃"],[33,17,"בְּכ֨וֹר שׁוֹר֜⁠וֹ הָדָ֣ר ל֗⁠וֹ וְ⁠קַרְנֵ֤י רְאֵם֙ קַרְנָ֔י⁠ו בָּ⁠הֶ֗ם עַמִּ֛ים יְנַגַּ֥ח יַחְדָּ֖ו אַפְסֵי־אָ֑רֶץ וְ⁠הֵם֙ רִבְב֣וֹת אֶפְרַ֔יִם וְ⁠הֵ֖ם אַלְפֵ֥י מְנַשֶּֽׁה׃ס","bĕ̇k֨wòr ş̌wòr֜⁠wò hádá֣r l֗⁠wò wĕ⁠qarĕné֤y rĕʼém֙ qarĕná֔y⁠w bá̇⁠he֗m ʻami֛̇ym yĕnagȧ֥ẖ yaẖĕdá֖̇w ʼapĕséy-ʼá֑reẕ wĕ⁠hém֙ ribĕb֣wòţ ʼepĕra֔yim wĕ⁠hé֖m ʼalĕpé֥y mĕnaşėֽ̌h׃s"],[33,18,"וְ⁠לִ⁠זְבוּלֻ֣ן אָמַ֔ר שְׂמַ֥ח זְבוּלֻ֖ן בְּ⁠צֵאתֶ֑⁠ךָ וְ⁠יִשָּׂשכָ֖ר בְּ⁠אֹהָלֶֽי⁠ךָ׃","wĕ⁠li⁠zĕbẇlu֣n ʼáma֔r şĕ̂ma֥ẖ zĕbẇlu֖n bĕ̇⁠ẕéʼţe֑⁠ká wĕ⁠yişá̇̂şká֖r bĕ̇⁠ʼòháleֽy⁠ká׃"],[33,19,"עַמִּים֙ הַר־יִקְרָ֔אוּ שָׁ֖ם יִזְבְּח֣וּ זִבְחֵי־צֶ֑דֶק כִּ֣י שֶׁ֤פַע יַמִּים֙ יִינָ֔קוּ וּ⁠שְׂפוּנֵ֖י טְמ֥וּנֵי חֽוֹל׃ס","ʻami̇ym֙ har-yiqĕrá֔ʼẇ şá֖̌m yizĕbĕ̇ẖ֣ẇ zibĕẖéy-ẕe֑deq ki֣̇y şě֤paʻ yami̇ym֙ yiyná֔qẇ ẇ⁠şĕ̂pẇné֖y tĕm֥ẇnéy ẖֽwòl׃s"],[33,20,"וּ⁠לְ⁠גָ֣ד אָמַ֔ר בָּר֖וּךְ מַרְחִ֣יב גָּ֑ד כְּ⁠לָבִ֣יא שָׁכֵ֔ן וְ⁠טָרַ֥ף זְר֖וֹעַ אַף־קָדְקֹֽד׃","ẇ⁠lĕ⁠gá֣d ʼáma֔r bá̇r֖ẇkĕ marĕẖi֣yb gá֑̇d kĕ̇⁠lábi֣yʼ şá̌ké֔n wĕ⁠tára֥p zĕr֖wòʻa ʼap-qádĕqòֽd׃"],[33,21,"וַ⁠יַּ֤רְא רֵאשִׁית֙ ל֔⁠וֹ כִּי־שָׁ֛ם חֶלְקַ֥ת מְחֹקֵ֖ק סָפ֑וּן וַ⁠יֵּתֵא֙ רָ֣אשֵׁי עָ֔ם צִדְקַ֤ת יְהוָה֙ עָשָׂ֔ה וּ⁠מִשְׁפָּטָ֖י⁠ו עִם־יִשְׂרָאֵֽל׃ס","wa⁠yȧ֤rĕʼ réʼşǐyţ֙ l֔⁠wò ki̇y-şá֛̌m ẖelĕqa֥ţ mĕẖòqé֖q sáp֑ẇn wa⁠yé̇ţéʼ֙ rá֣ʼşé̌y ʻá֔m ẕidĕqa֤ţ yĕhwáh֙ ʻáşá̂֔h ẇ⁠mişĕ̌pá̇tá֖y⁠w ʻim-yişĕ̂ráʼéֽl׃s"],[33,22,"וּ⁠לְ⁠דָ֣ן אָמַ֔ר דָּ֖ן גּ֣וּר אַרְיֵ֑ה יְזַנֵּ֖ק מִן־הַ⁠בָּשָֽׁן׃","ẇ⁠lĕ⁠dá֣n ʼáma֔r dá֖̇n ġ֣ẇr ʼarĕyé֑h yĕzané֖̇q min-ha⁠bá̇şáֽ̌n׃"],[33,23,"וּ⁠לְ⁠נַפְתָּלִ֣י אָמַ֔ר נַפְתָּלִי֙ שְׂבַ֣ע רָצ֔וֹן וּ⁠מָלֵ֖א בִּרְכַּ֣ת יְהוָ֑ה יָ֥ם וְ⁠דָר֖וֹם יְרָֽשָׁ⁠ה׃ס","ẇ⁠lĕ⁠napĕţá̇li֣y ʼáma֔r napĕţá̇liy֙ şĕ̂ba֣ʻ ráẕ֔wòn ẇ⁠málé֖ʼ bi̇rĕkȧ֣ţ yĕhwá֑h yá֥m wĕ⁠dár֖wòm yĕráֽşá̌⁠h׃s"],[33,24,"וּ⁠לְ⁠אָשֵׁ֣ר אָמַ֔ר בָּר֥וּךְ מִ⁠בָּנִ֖ים אָשֵׁ֑ר יְהִ֤י רְצוּי֙ אֶחָ֔י⁠ו וְ⁠טֹבֵ֥ל בַּ⁠שֶּׁ֖מֶן רַגְלֽ⁠וֹ׃","ẇ⁠lĕ⁠ʼáşé֣̌r ʼáma֔r bá̇r֥ẇkĕ mi⁠bá̇ni֖ym ʼáşé֑̌r yĕhi֤y rĕẕẇy֙ ʼeẖá֔y⁠w wĕ⁠tòbé֥l bȧ⁠şė֖̌men ragĕlֽ⁠wò׃"],[33,25,"בַּרְזֶ֥ל וּ⁠נְחֹ֖שֶׁת מִנְעָלֶ֑י⁠ךָ וּ⁠כְ⁠יָמֶ֖י⁠ךָ דָּבְאֶֽ⁠ךָ׃","bȧrĕze֥l ẇ⁠nĕẖò֖şěţ minĕʻále֑y⁠ká ẇ⁠kĕ⁠yáme֖y⁠ká dá̇bĕʼeֽ⁠ká׃"],[33,26,"אֵ֥ין כָּ⁠אֵ֖ל יְשֻׁר֑וּן רֹכֵ֤ב שָׁמַ֨יִם֙ בְ⁠עֶזְרֶ֔⁠ךָ וּ⁠בְ⁠גַאֲוָת֖⁠וֹ שְׁחָקִֽים׃","ʼé֥yn ká̇⁠ʼé֖l yĕşǔr֑ẇn ròké֤b şá̌ma֨yim֙ bĕ⁠ʻezĕre֔⁠ká ẇ⁠bĕ⁠gaʼàwáţ֖⁠wò şĕ̌ẖáqiֽym׃"],[33,27,"מְעֹנָה֙ אֱלֹ֣הֵי קֶ֔דֶם וּ⁠מִ⁠תַּ֖חַת זְרֹעֹ֣ת עוֹלָ֑ם וַ⁠יְגָ֧רֶשׁ מִ⁠פָּנֶ֛י⁠ךָ אוֹיֵ֖ב וַ⁠יֹּ֥אמֶר הַשְׁמֵֽד׃","mĕʻònáh֙ ʼèlò֣héy qe֔dem ẇ⁠mi⁠ţȧ֖ẖaţ zĕròʻò֣ţ ʻwòlá֑m wa⁠yĕgá֧reş̌ mi⁠pá̇ne֛y⁠ká ʼwòyé֖b wa⁠yò֥̇ʼmer haşĕ̌méֽd׃"],[33,28,"וַ⁠יִּשְׁכֹּן֩ יִשְׂרָאֵ֨ל בֶּ֤טַח בָּדָד֙ עֵ֣ין יַעֲקֹ֔ב אֶל־אֶ֖רֶץ דָּגָ֣ן וְ⁠תִיר֑וֹשׁ אַף־שָׁמָ֖י⁠ו יַֽעַרְפוּ טָֽל׃","wa⁠yi̇şĕ̌kò̇n֩ yişĕ̂ráʼé֨l bė֤taẖ bá̇dád֙ ʻé֣yn yaʻàqò֔b ʼel-ʼe֖reẕ dá̇gá֣n wĕ⁠ţiyr֑wòş̌ ʼap-şá̌má֖y⁠w yaֽʻarĕpẇ táֽl׃"],[33,29,"אַשְׁרֶ֨י⁠ךָ יִשְׂרָאֵ֜ל מִ֣י כָמ֗וֹ⁠ךָ עַ֚ם נוֹשַׁ֣ע בַּֽ⁠יהוָ֔ה מָגֵ֣ן עֶזְרֶ֔⁠ךָ וַ⁠אֲשֶׁר־חֶ֖רֶב גַּאֲוָתֶ֑⁠ךָ וְ⁠יִכָּֽחֲשׁ֤וּ אֹיְבֶ֨י⁠ךָ֙ לָ֔⁠ךְ וְ⁠אַתָּ֖ה עַל־בָּמוֹתֵ֥י⁠מוֹ תִדְרֹֽךְ׃ס","ʼaşĕ̌re֨y⁠ká yişĕ̂ráʼé֜l mi֣y kám֗wò⁠ká ʻa֚m nwòşǎ֣ʻ bȧֽ⁠yhwá֔h mágé֣n ʻezĕre֔⁠ká wa⁠ʼàşěr-ẖe֖reb gȧʼàwáţe֑⁠ká wĕ⁠yikáֽ̇ẖàş֤̌ẇ ʼòyĕbe֨y⁠ká֙ lá֔⁠kĕ wĕ⁠ʼaţá֖̇h ʻal-bá̇mwòţé֥y⁠mwò ţidĕròֽkĕ׃s"],[34,1,"וַ⁠יַּ֨עַל מֹשֶׁ֜ה מֵֽ⁠עַרְבֹ֤ת מוֹאָב֙ אֶל־הַ֣ר נְב֔וֹ רֹ֚אשׁ הַ⁠פִּסְגָּ֔ה אֲשֶׁ֖ר עַל־פְּנֵ֣י יְרֵח֑וֹ וַ⁠יַּרְאֵ֨⁠הוּ יְהוָ֧ה אֶת־כָּל־הָ⁠אָ֛רֶץ אֶת־הַ⁠גִּלְעָ֖ד עַד־דָּֽן׃","wa⁠yȧ֨ʻal mòşě֜h méֽ⁠ʻarĕbò֤ţ mwòʼáb֙ ʼel-ha֣r nĕb֔wò rò֚ʼş̌ ha⁠pi̇sĕgá̇֔h ʼàşě֖r ʻal-pĕ̇né֣y yĕréẖ֑wò wa⁠yȧrĕʼé֨⁠hẇ yĕhwá֧h ʼeţ-ká̇l-há⁠ʼá֛reẕ ʼeţ-ha⁠gi̇lĕʻá֖d ʻad-dáֽ̇n׃"],[34,2,"וְ⁠אֵת֙ כָּל־נַפְתָּלִ֔י וְ⁠אֶת־אֶ֥רֶץ אֶפְרַ֖יִם וּ⁠מְנַשֶּׁ֑ה וְ⁠אֵת֙ כָּל־אֶ֣רֶץ יְהוּדָ֔ה עַ֖ד הַ⁠יָּ֥ם הָ⁠אַחֲרֽוֹן׃","wĕ⁠ʼéţ֙ ká̇l-napĕţá̇li֔y wĕ⁠ʼeţ-ʼe֥reẕ ʼepĕra֖yim ẇ⁠mĕnaşė֑̌h wĕ⁠ʼéţ֙ ká̇l-ʼe֣reẕ yĕhẇdá֔h ʻa֖d ha⁠yá֥̇m há⁠ʼaẖàrֽwòn׃"],[34,3,"וְ⁠אֶת־הַ⁠נֶּ֗גֶב וְֽ⁠אֶת־הַ⁠כִּכָּ֞ר בִּקְעַ֧ת יְרֵח֛וֹ עִ֥יר הַ⁠תְּמָרִ֖ים עַד־צֹֽעַר׃","wĕ⁠ʼeţ-ha⁠nė֗geb wĕֽ⁠ʼeţ-ha⁠ki̇ká̇֞r bi̇qĕʻa֧ţ yĕréẖ֛wò ʻi֥yr ha⁠ţĕ̇mári֖ym ʻad-ẕòֽʻar׃"],[34,4,"וַ⁠יֹּ֨אמֶר יְהוָ֜ה אֵלָ֗י⁠ו זֹ֤את הָ⁠אָ֨רֶץ֙ אֲשֶׁ֣ר נִ֠שְׁבַּעְתִּי לְ⁠אַבְרָהָ֨ם לְ⁠יִצְחָ֤ק וּֽ⁠לְ⁠יַעֲקֹב֙ לֵ⁠אמֹ֔ר לְ⁠זַרְעֲ⁠ךָ֖ אֶתְּנֶ֑נָּ⁠ה הֶרְאִיתִ֣י⁠ךָ בְ⁠עֵינֶ֔י⁠ךָ וְ⁠שָׁ֖מָּ⁠ה לֹ֥א תַעֲבֹֽר׃","wa⁠yò̇֨ʼmer yĕhwá֜h ʼélá֗y⁠w zò֤ʼţ há⁠ʼá֨reẕ֙ ʼàşě֣r ni֠şĕ̌bȧʻĕţi̇y lĕ⁠ʼabĕráhá֨m lĕ⁠yiẕĕẖá֤q ẇֽ⁠lĕ⁠yaʻàqòb֙ lé⁠ʼmò֔r lĕ⁠zarĕʻà⁠ká֖ ʼeţĕ̇ne֑ná̇⁠h herĕʼiyţi֣y⁠ká bĕ⁠ʻéyne֔y⁠ká wĕ⁠şá֖̌má̇⁠h lò֥ʼ ţaʻàbòֽr׃"],[34,5,"וַ⁠יָּ֨מָת שָׁ֜ם מֹשֶׁ֧ה עֶֽבֶד־יְהוָ֛ה בְּ⁠אֶ֥רֶץ מוֹאָ֖ב עַל־פִּ֥י יְהוָֽה׃","wa⁠yá̇֨máţ şá̌֜m mòşě֧h ʻeֽbed-yĕhwá֛h bĕ̇⁠ʼe֥reẕ mwòʼá֖b ʻal-pi֥̇y yĕhwáֽh׃"],[34,6,"וַ⁠יִּקְבֹּ֨ר אֹת֤⁠וֹ בַ⁠גַּיְ֙ בְּ⁠אֶ֣רֶץ מוֹאָ֔ב מ֖וּל בֵּ֣ית פְּע֑וֹר וְ⁠לֹֽא־יָדַ֥ע אִישׁ֙ אֶת־קְבֻ֣רָת֔⁠וֹ עַ֖ד הַ⁠יּ֥וֹם הַ⁠זֶּֽה׃","wa⁠yi̇qĕbò̇֨r ʼòţ֤⁠wò ba⁠gȧyĕ֙ bĕ̇⁠ʼe֣reẕ mwòʼá֔b m֖ẇl bé֣̇yţ pĕ̇ʻ֑wòr wĕ⁠lòֽʼ-yáda֥ʻ ʼiyş̌֙ ʼeţ-qĕbu֣ráţ֔⁠wò ʻa֖d ha⁠ẏ֥wòm ha⁠zėֽh׃"],[34,7,"וּ⁠מֹשֶׁ֗ה בֶּן־מֵאָ֧ה וְ⁠עֶשְׂרִ֛ים שָׁנָ֖ה בְּ⁠מֹת֑⁠וֹ לֹֽא־כָהֲתָ֥ה עֵינ֖⁠וֹ וְ⁠לֹא־נָ֥ס לֵחֹֽ⁠ה׃","ẇ⁠mòşě֗h bėn-méʼá֧h wĕ⁠ʻeşĕ̂ri֛ym şá̌ná֖h bĕ̇⁠mòţ֑⁠wò lòֽʼ-káhàţá֥h ʻéyn֖⁠wò wĕ⁠lòʼ-ná֥s léẖòֽ⁠h׃"],[34,8,"וַ⁠יִּבְכּוּ֩ בְנֵ֨י יִשְׂרָאֵ֧ל אֶת־מֹשֶׁ֛ה בְּ⁠עַֽרְבֹ֥ת מוֹאָ֖ב שְׁלֹשִׁ֣ים י֑וֹם וַֽ⁠יִּתְּמ֔וּ יְמֵ֥י בְכִ֖י אֵ֥בֶל מֹשֶֽׁה׃","wa⁠yi̇bĕk̇ẇ֩ bĕné֨y yişĕ̂ráʼé֧l ʼeţ-mòşě֛h bĕ̇⁠ʻaֽrĕbò֥ţ mwòʼá֖b şĕ̌lòşǐ֣ym y֑wòm waֽ⁠yi̇ţĕ̇m֔ẇ yĕmé֥y bĕki֖y ʼé֥bel mòşěֽh׃"],[34,9,"וִֽ⁠יהוֹשֻׁ֣עַ בִּן־נ֗וּן מָלֵא֙ ר֣וּחַ חָכְמָ֔ה כִּֽי־סָמַ֥ךְ מֹשֶׁ֛ה אֶת־יָדָ֖י⁠ו עָלָ֑י⁠ו וַ⁠יִּשְׁמְע֨וּ אֵלָ֤י⁠ו בְּנֵֽי־יִשְׂרָאֵל֙ וַֽ⁠יַּעֲשׂ֔וּ כַּ⁠אֲשֶׁ֛ר צִוָּ֥ה יְהוָ֖ה אֶת־מֹשֶֽׁה׃","wiֽ⁠yhwòşǔ֣ʻa bi̇n-n֗ẇn máléʼ֙ r֣ẇẖa ẖákĕmá֔h kiֽ̇y-sáma֥kĕ mòşě֛h ʼeţ-yádá֖y⁠w ʻálá֑y⁠w wa⁠yi̇şĕ̌mĕʻ֨ẇ ʼélá֤y⁠w bĕ̇néֽy-yişĕ̂ráʼél֙ waֽ⁠yȧʻàş̂֔ẇ kȧ⁠ʼàşě֛r ẕiwá֥̇h yĕhwá֖h ʼeţ-mòşěֽh׃"],[34,10,"וְ⁠לֹֽא־קָ֨ם נָבִ֥יא ע֛וֹד בְּ⁠יִשְׂרָאֵ֖ל כְּ⁠מֹשֶׁ֑ה אֲשֶׁר֙ יְדָע֣⁠וֹ יְהוָ֔ה פָּנִ֖ים אֶל־פָּנִֽים׃","wĕ⁠lòֽʼ-qá֨m nábi֥yʼ ʻ֛wòd bĕ̇⁠yişĕ̂ráʼé֖l kĕ̇⁠mòşě֑h ʼàşěr֙ yĕdáʻ֣⁠wò yĕhwá֔h pá̇ni֖ym ʼel-pá̇niֽym׃"],[34,11,"לְ⁠כָל־הָ֨⁠אֹת֜וֹת וְ⁠הַ⁠מּוֹפְתִ֗ים אֲשֶׁ֤ר שְׁלָח⁠וֹ֙ יְהוָ֔ה לַ⁠עֲשׂ֖וֹת בְּ⁠אֶ֣רֶץ מִצְרָ֑יִם לְ⁠פַרְעֹ֥ה וּ⁠לְ⁠כָל־עֲבָדָ֖י⁠ו וּ⁠לְ⁠כָל־אַרְצֽ⁠וֹ׃","lĕ⁠kál-há֨⁠ʼòţ֜wòţ wĕ⁠ha⁠ṁwòpĕţi֗ym ʼàşě֤r şĕ̌láẖ⁠wò֙ yĕhwá֔h la⁠ʻàş֖̂wòţ bĕ̇⁠ʼe֣reẕ miẕĕrá֑yim lĕ⁠parĕʻò֥h ẇ⁠lĕ⁠kál-ʻàbádá֖y⁠w ẇ⁠lĕ⁠kál-ʼarĕẕֽ⁠wò׃"],[34,12,"וּ⁠לְ⁠כֹל֙ הַ⁠יָּ֣ד הַ⁠חֲזָקָ֔ה וּ⁠לְ⁠כֹ֖ל הַ⁠מּוֹרָ֣א הַ⁠גָּד֑וֹל אֲשֶׁר֙ עָשָׂ֣ה מֹשֶׁ֔ה לְ⁠עֵינֵ֖י כָּל־יִשְׂרָאֵֽל׃","ẇ⁠lĕ⁠kòl֙ ha⁠yá֣̇d ha⁠ẖàzáqá֔h ẇ⁠lĕ⁠kò֖l ha⁠ṁwòrá֣ʼ ha⁠gá̇d֑wòl ʼàşěr֙ ʻáşá֣̂h mòşě֔h lĕ⁠ʻéyné֖y ká̇l-yişĕ̂ráʼéֽl׃"]]}};